window.SEMIPRIME_SOURCES={"RiemannGaussian.SemiprimeAcquiredPrefixSearch":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeAcquiredSourceCounter\nimport RiemannGaussian.SemiprimeCounterSearch\nimport RiemannGaussian.SemiprimeMacroEntryBitPrimitives\n\n/-! # Prefix search driven by the actual acquired scalar counter -/\nset_option autoImplicit false\nset_option maxHeartbeats 1400000\nnamespace RiemannGaussian.SemiprimeAcquiredPrefixSearch\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen SemiprimeLocalArrayFrontend SemiprimeCounterSearch SemiprimeCountRecovery\nopen SemiprimeMacroEntryBitPrimitives\nvariable {n F r Q : ℕ} [NeZero r]\n\n/-- Explicit finite every-occurrence restriction on the unchanged local scope. -/\ndef prefixGate (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) : Bool :=\n  fixed.all (fun pair => (List.finRange (arity e)).all\n    (fun i => decide (coordinate e i=pair.1 → input i=pair.2)))\n\n/-- The executed gate imposes every fixed bit on every occurrence. -/\ntheorem prefixGate_correct (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    prefixGate arity coordinate fixed e input =\n      decide (∀ pair ∈ fixed, ∀ i, coordinate e i=pair.1 → input i=pair.2) := by\n  apply Bool.eq_iff_iff.mpr\n  simp only [prefixGate, List.all_eq_true, decide_eq_true_eq, List.mem_finRange, true_implies]\n\n/-- Paid original local bit checker plus the actual finite restriction scan. -/\ndef entry (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) : EntryReport :=\n  let original := base e input\n  let accept := original.accepted && prefixGate arity coordinate fixed e input\n  let budget := original.clock+fixed.length*(3*arity e+2)+1\n  ⟨if accept then 1 else 0,budget,budget⟩\n\n/-- The integer entry callback is exactly the original rational prefix table. -/\ntheorem entry_value (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    ((entry arity coordinate base fixed e input).value : ℚ)=\n      rationalTable arity (prefixTable arity (fun e a => (base e a).accepted) coordinate fixed) e input := by\n  simp only [entry, prefixGate_correct, rationalTable, prefixTable, Int.cast_ite, Int.cast_one, Int.cast_zero]\n  rfl\n\n/-- Natural prefix count obtained from the executed source-to-scalar interpreter. -/\ndef prefixCount (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B J : ℕ)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun) (fixed : List (Fin n × Bool)) : ℕ :=\n  Nat.floor (SemiprimeAcquiredSourceCounter.count (r := r) (Q := Q) arity coordinate eps R B J\n    (entry arity coordinate base fixed)).value\n\n/-- Every prefix count is the original restricted acceptance count; no count oracle is supplied. -/\ntheorem prefixCount_correct (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B J : ℕ)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (howner : ∀ v, (Finset.univ.filter\n      (fun i : (e : Fin F) × Fin (arity e) => coordinate i.1 i.2=v)).card ≤ B)\n    (coverage : ∀ a, ∃ e i, coordinate e i=a)\n    (hQ : 1≤Q) (hAQ : Subexp.TailInterval.intervalStart r Q R ≤ Q)\n    (hJ : 0<J) (hprecision : (∑ e, arity e)*R<Q*J) (fixed : List (Fin n × Bool)) :\n    prefixCount (r := r) (Q := Q) arity coordinate eps R B J base fixed =\n      acceptedCount (restricted assignmentBit\n        (originalPredicate arity (fun e a => (base e a).accepted) coordinate) fixed) := by\n  have hs := SemiprimeAcquiredSourceCounter.count_correct arity coordinate eps R B J\n    (entry arity coordinate base fixed) howner hQ hAQ hJ hprecision\n  have he : SemiprimeCounterNative.originalContraction arity\n      (fun e eta => ((entry arity coordinate base fixed e eta).value : ℚ)) coordinate =\n      (acceptedCount (restricted assignmentBit\n        (originalPredicate arity (fun e a => (base e a).accepted) coordinate) fixed) : ℕ) := by\n    simp only [SemiprimeCounterNative.originalContraction, acceptedCount, Nat.cast_sum,\n      Nat.cast_ite, Nat.cast_one, Nat.cast_zero]\n    apply Finset.sum_congr rfl\n    intro x _\n    simp only [entry_value]\n    change (∏ e, rationalTable arity (prefixTable arity (fun e a => (base e a).accepted)\n      coordinate fixed) e (fun i => assignmentBit x (coordinate e i))) = _\n    rw [rational_product_indicator]\n    have hp : originalPredicate arity\n        (prefixTable arity (fun e a => (base e a).accepted) coordinate fixed) coordinate x =\n        restricted assignmentBit (originalPredicate arity (fun e a => (base e a).accepted) coordinate) fixed x := by\n      apply Bool.eq_iff_iff.mpr\n      simpa only [originalPredicate, decide_eq_true_eq] using\n        prefix_accept_iff arity (fun e a => (base e a).accepted) coordinate coverage fixed x\n    rw [hp]\n  unfold prefixCount\n  rw [hs,he,Nat.floor_natCast]\n\n/-- Search all literal indexed wire bits using only actual acquired prefix counts. -/\ndef search (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B J : ℕ)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun) : SearchResult (Fin n) :=\n  SemiprimeCountRecovery.search\n    (prefixCount (r := r) (Q := Q) arity coordinate eps R B J base) (List.finRange n)\n\n/-- There are at most one initial and one conditional query per actual wire. -/\ntheorem search_queries (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (eps : ℚ) (R B J : ℕ)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun) :\n    (search (r := r) (Q := Q) arity coordinate eps R B J base).queries ≤ n+1 := by\n  simpa only [search, List.length_finRange] using SemiprimeCountRecovery.search_queries_le\n    (prefixCount (r := r) (Q := Q) arity coordinate eps R B J base) (List.finRange n)\n\n/-- Reconstruct a selected wire directly from the returned literal bit list. -/\ndef selectedBits (values : List (Fin n × Bool)) (i : Fin n) : Bool :=\n  values.any (fun p => decide (p.1=i) && p.2)\n\n/-- A complete sound selected list reconstructs its one common original witness. -/\ntheorem selectedBits_eq (values : List (Fin n × Bool)) (bits : Fin n → Bool)\n    (hcover : ∀ i, ∃ p ∈ values, p.1=i)\n    (hsound : ∀ p ∈ values, bits p.1=p.2) (i : Fin n) : selectedBits values i=bits i := by\n  apply Bool.eq_iff_iff.mpr\n  constructor\n  · intro h\n    obtain ⟨p,hp,hv⟩ := List.any_eq_true.mp h\n    have hv' : decide (p.1=i)=true ∧ p.2=true := by simpa only [Bool.and_eq_true] using hv\n    obtain ⟨hi,hb⟩ := hv'\n    have he : p.1=i := of_decide_eq_true hi\n    exact (he ▸ hsound p hp).trans hb\n  · intro h\n    obtain ⟨p,hp,hi⟩ := hcover i\n    apply List.any_eq_true.mpr\n    refine ⟨p,hp,?_⟩\n    have hb : p.2=true := (hsound p hp).symm.trans (by simpa only [hi] using h)\n    simpa only [Bool.and_eq_true, decide_eq_true_eq] using And.intro hi hb\n\n/-- Every executed prefix callback remains a literal zero/one integer tensor entry. -/\ntheorem entry_abs (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).value.natAbs ≤ 1 := by\n  change (if (base e input).accepted && prefixGate arity coordinate fixed e input then (1 : ℤ) else 0).natAbs ≤ 1\n  split_ifs <;> decide\n\n/-- Callback accounting retains the paid bit checker and the finite local restriction scan. -/\ntheorem entry_work (arity : Fin F → ℕ)\n    (coordinate : (e : Fin F) → Fin (arity e) → Fin n)\n    (base : (e : Fin F) → (Fin (arity e) → Bool) → CheckRun)\n    (fixed : List (Fin n × Bool)) (e : Fin F) (input : Fin (arity e) → Bool) :\n    (entry arity coordinate base fixed e input).arithmetic=\n      (base e input).clock+fixed.length*(3*arity e+2)+1 ∧\n    (entry arity coordinate base fixed e input).reads=\n      (base e input).clock+fixed.length*(3*arity e+2)+1 := ⟨rfl,rfl⟩\n\nend RiemannGaussian.SemiprimeAcquiredPrefixSearch\n","RiemannGaussian.SemiprimeAffinePointAreas":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSameResidueAreas\n\n/-!\n# All row areas in a public affine point carrier\n\nRemove one common public midpoint plane over the integers, retaining the\nsigned error and the mixed-center direction separately upstream. Two\nunit-guarded coordinates per packet preserve every three-row area GCD,\nnot just triples through a selected anchor. One anchored root axis is the\nsecant equation through one point of this carrier. No efficient complete\nincidence extractor or universal sixth-root coverage is asserted.\n-/\n\nnamespace RiemannGaussian.SemiprimeAffinePointAreas\n\nopen SemiprimeQuotientRows SemiprimeQuotientCentering SemiprimeEuclidRowFamily\nopen SemiprimeWeightedRows SemiprimeCompanionRows SemiprimeCompanionCenterSpectrum\nopen SemiprimeAffineRowRoots SemiprimeCenteredOffsetExtractor SemiprimeAnchoredRowAreas\nopen SemiprimeRowAreaSpectrum SemiprimeSameResidueAreas\n\n/-- Integer residual after one common public center plane is removed. -/\ndef pointResidual (N m : ℕ) (w : FamilyPacket) : ℤ :=\n  -2*packetOffset m w-w.original.a*centerA N false-w.original.t*centerB N false\n\n/-- Both signed source channels commute with the common-plane removal. -/\ntheorem pointResidual_center_channels {N m : ℕ} (w : FamilyPacket) (side : Bool)\n    (hc : CenterChoice N m w side) :\n    pointResidual N m w=packetCenterError N m w side+\n      centerFlag side*(w.original.a-w.original.t)*centerDifference N := by\n  have h := packet_center_equation w side hc\n  rw [centerA_split N side,centerB_split N side] at h\n  unfold pointResidual\n  linear_combination h\n\n/-- The residual is independent of overlapping admissible center choices. -/\ntheorem pointResidual_center_choice {N m : ℕ} (w : FamilyPacket) (us ws : Bool)\n    (hu : CenterChoice N m w us) (hw : CenterChoice N m w ws) :\n    packetCenterError N m w us+centerFlag us*(w.original.a-w.original.t)*centerDifference N=\n      packetCenterError N m w ws+centerFlag ws*(w.original.a-w.original.t)*centerDifference N :=\n  (pointResidual_center_channels w us hu).symm.trans (pointResidual_center_channels w ws hw)\n\n/-- A literal integer determinant, with the common plane removed before reduction. -/\ntheorem pointResidual_area (N m : ℕ) (u w v : FamilyPacket) :\n    Matrix.det !![u.original.a,u.original.t,pointResidual N m u;\n      w.original.a,w.original.t,pointResidual N m w;\n      v.original.a,v.original.t,pointResidual N m v]=2*rowArea m u w v := by\n  simp [pointResidual,rowArea,Matrix.det_fin_three]\n  ring\n\n/-- The original denominator ratio remains a separate coordinate. -/\ndef pointX (N : ℕ) (w : FamilyPacket) : ZMod N :=\n  (w.original.t : ZMod N)*(w.original.a : ZMod N)⁻¹\n\n/-- The signed residual ratio retains the second affine coordinate. -/\ndef pointY (N m : ℕ) (w : FamilyPacket) : ZMod N :=\n  (pointResidual N m w : ZMod N)*(w.original.a : ZMod N)⁻¹\n\n/-- One pair per full original packet; use only after its leading unit check. -/\ndef packetPoint (N m : ℕ) (w : FamilyPacket) : ZMod N×ZMod N :=\n  (pointX N w,pointY N m w)\n\ntheorem pointX_coefficient {N : ℕ} (w : FamilyPacket)\n    (hu : IsUnit (w.original.a : ZMod N)) :\n    (w.original.a : ZMod N)*pointX N w=(w.original.t : ZMod N) := by\n  unfold pointX\n  rw [mul_left_comm,ZMod.mul_inv_of_unit _ hu,mul_one]\n\ntheorem pointY_coefficient {N m : ℕ} (w : FamilyPacket)\n    (hu : IsUnit (w.original.a : ZMod N)) :\n    (w.original.a : ZMod N)*pointY N m w=(pointResidual N m w : ZMod N) := by\n  unfold pointY\n  rw [mul_left_comm,ZMod.mul_inv_of_unit _ hu,mul_one]\n\n/-- Constant-size incidence evaluation; no list of all triples is built. -/\ndef affineArea {N : ℕ} (u w v : ZMod N×ZMod N) : ZMod N :=\n  Matrix.det !![1,u.1,u.2;1,w.1,w.2;1,v.1,v.2]\n\n/-- Every triple, with arbitrary residues and centers, survives normalization. -/\ntheorem packetPoint_area {N m : ℕ} (u w v : FamilyPacket)\n    (hu : IsUnit (u.original.a : ZMod N)) (hw : IsUnit (w.original.a : ZMod N))\n    (hv : IsUnit (v.original.a : ZMod N)) :\n    (u.original.a : ZMod N)*(w.original.a : ZMod N)*(v.original.a : ZMod N)*\n        affineArea (packetPoint N m u) (packetPoint N m w) (packetPoint N m v)=\n      2*(rowArea m u w v : ZMod N) := by\n  have h := congrArg (fun z : ℤ => (z : ZMod N)) (pointResidual_area N m u w v)\n  simp [Matrix.det_fin_three] at h\n  rw [←pointX_coefficient u hu,←pointY_coefficient u hu,\n    ←pointX_coefficient w hw,←pointY_coefficient w hw,\n    ←pointX_coefficient v hv,←pointY_coefficient v hv] at h\n  simp [affineArea,packetPoint,Matrix.det_fin_three]\n  linear_combination h\n\n/-- Exact GCD transport includes prime powers, zeros and whole-N saturation. -/\ntheorem packetPoint_area_gcd {N m : ℕ} (u w v : FamilyPacket)\n    (h2 : IsUnit (2 : ZMod N)) (hu : IsUnit (u.original.a : ZMod N))\n    (hw : IsUnit (w.original.a : ZMod N)) (hv : IsUnit (v.original.a : ZMod N)) :\n    N.gcd (affineArea (packetPoint N m u) (packetPoint N m w) (packetPoint N m v)).val=\n      N.gcd (rowArea m u w v : ZMod N).val := by\n  have hp := SemiprimeRHCancellation.unit_mul_gcd_eq ((hu.mul hw).mul hv).unit\n    (affineArea (packetPoint N m u) (packetPoint N m w) (packetPoint N m v))\n  have htwo := SemiprimeRHCancellation.unit_mul_gcd_eq h2.unit (rowArea m u w v : ZMod N)\n  rw [((hu.mul hw).mul hv).unit_spec,packetPoint_area u w v hu hw hv] at hp\n  rw [h2.unit_spec] at htwo\n  exact hp.symm.trans htwo\n\n/-- Original affine roots and both residual coordinates commute with the plane removal. -/\ntheorem packetPoint_original_root {N m : ℕ} (w : FamilyPacket)\n    (hu : IsUnit (w.original.a : ZMod N)) :\n    2*packetRoot N m w false=(centerA N false : ZMod N)+\n      (centerB N false : ZMod N)*pointX N w+pointY N m w := by\n  have hx := pointX_coefficient w hu\n  have hy := pointY_coefficient (m:=m) w hu\n  have hr := packetRoot_coefficient (m:=m) w false hu\n  simp only [packetScale,Bool.false_eq_true,ite_false] at hr\n  unfold pointResidual at hy\n  push_cast at hy\n  have hprod : (w.original.a : ZMod N)*\n      (2*packetRoot N m w false-(centerA N false : ZMod N)-\n        (centerB N false : ZMod N)*pointX N w-pointY N m w)=0 := by\n    linear_combination 2*hr-hy-(centerB N false : ZMod N)*hx\n  have h := congrArg (fun z => (w.original.a : ZMod N)⁻¹*z) hprod\n  rw [←mul_assoc,ZMod.inv_mul_of_unit _ hu,one_mul,mul_zero] at h\n  linear_combination h\n\n/-- The two-point denominator minor is one coordinate difference with unit phases. -/\ntheorem pointX_minor {N : ℕ} (u w : FamilyPacket)\n    (hu : IsUnit (u.original.a : ZMod N)) (hw : IsUnit (w.original.a : ZMod N)) :\n    (u.original.a : ZMod N)*(w.original.a : ZMod N)*(pointX N w-pointX N u)=\n      (denominatorMinor u w : ZMod N) := by\n  have hx := pointX_coefficient u hu\n  have hy := pointX_coefficient w hw\n  simp only [denominatorMinor,Int.cast_sub,Int.cast_mul]\n  linear_combination (u.original.a : ZMod N)*hy-(w.original.a : ZMod N)*hx\n\ntheorem pointY_minor {N m : ℕ} (u w : FamilyPacket)\n    (hu : IsUnit (u.original.a : ZMod N)) (hw : IsUnit (w.original.a : ZMod N)) :\n    (u.original.a : ZMod N)*(w.original.a : ZMod N)*(pointY N m w-pointY N m u)=\n      -2*(offsetMinor m u w : ZMod N)-\n        (centerB N false : ZMod N)*(denominatorMinor u w : ZMod N) := by\n  have hx := pointY_coefficient (m:=m) u hu\n  have hy := pointY_coefficient (m:=m) w hw\n  simp only [pointResidual,Int.cast_sub,Int.cast_mul,Int.cast_neg,Int.cast_ofNat] at hx hy\n  simp only [offsetMinor,denominatorMinor,Int.cast_sub,Int.cast_mul]\n  linear_combination (u.original.a : ZMod N)*hy-(w.original.a : ZMod N)*hx\n\n/-- The residual scalar channel retains a new signed two-row functional. -/\ntheorem pointY_difference_gcd {N m : ℕ} (u w : FamilyPacket)\n    (hu : IsUnit (u.original.a : ZMod N)) (hw : IsUnit (w.original.a : ZMod N)) :\n    N.gcd (pointY N m w-pointY N m u).val=\n      N.gcd (-2*(offsetMinor m u w : ZMod N)-\n        (centerB N false : ZMod N)*(denominatorMinor u w : ZMod N)).val := by\n  have h := SemiprimeRHCancellation.unit_mul_gcd_eq (hu.mul hw).unit\n    (pointY N m w-pointY N m u)\n  rw [(hu.mul hw).unit_spec,pointY_minor u w hu hw] at h\n  exact h.symm\n\n/-- One old root axis is the secant equation through one retained point. -/\ntheorem anchorSlope_secant {N m : ℕ} (u w : FamilyPacket)\n    (hu : IsUnit (u.original.a : ZMod N)) (hw : IsUnit (w.original.a : ZMod N))\n    (hd : IsUnit (denominatorMinor u w : ZMod N)) :\n    (pointX N w-pointX N u)*(2*anchorSlope N m u w+(centerB N false : ZMod N))+\n      (pointY N m w-pointY N m u)=0 := by\n  have hx := pointX_minor u w hu hw\n  have hy := pointY_minor (m:=m) u w hu hw\n  have hs := anchorSlope_coefficient (m:=m) u w hd\n  have hprod : ((u.original.a : ZMod N)*(w.original.a : ZMod N))*\n      ((pointX N w-pointX N u)*(2*anchorSlope N m u w+(centerB N false : ZMod N))+\n        (pointY N m w-pointY N m u))=0 := by\n    linear_combination (2*anchorSlope N m u w+(centerB N false : ZMod N))*hx+hy+2*hs\n  have h := congrArg (fun z => ((u.original.a : ZMod N)*(w.original.a : ZMod N))⁻¹*z) hprod\n  rw [←mul_assoc,ZMod.inv_mul_of_unit _ (hu.mul hw),one_mul,mul_zero] at h\n  exact h\n\n/-- The source list remains available before its complete two-coordinate fork. -/\ndef publicPoints (N m : ℕ) : List (ZMod N×ZMod N) :=\n  (publicPackets N m).map (packetPoint N m)\n\ntheorem publicPoints_length (N m : ℕ) : (publicPoints N m).length=(publicPackets N m).length :=\n  List.length_map _\n\n/-- This is a stored-coordinate count, not a full incidence bit-complexity theorem. -/\ntheorem publicPoints_length_prime_le (N : ℕ) {m : ℕ} (hm : m.Prime) :\n    (publicPoints N m).length≤8*m*(Nat.log2 m+1)^2 := by\n  rw [publicPoints_length]\n  exact SemiprimeEuclidRowBudget.publicPackets_length_le N hm\n\ntheorem publicPacket_numerator_ne_zero {N m : ℕ} (hm : 0<m) {w : FamilyPacket}\n    (hw : w∈publicPackets N m) : w.original.a≠0 := by\n  obtain ⟨j,_,hw⟩ := List.mem_flatMap.mp hw\n  split_ifs at hw\n  · obtain ⟨z,hz,hw⟩ := List.mem_flatMap.mp hw\n    have ha := (publicPairs_correct hm hz).1\n    simp only [List.mem_cons,List.not_mem_nil,or_false] at hw\n    rcases hw with rfl|rfl <;> exact ha\n  · simp only [List.not_mem_nil] at hw\n\n/-- Large-factor membership discharges the leading-coordinate unit guard. -/\ntheorem publicPacket_leading_unit {p q m : ℕ} (hm : 0<m) (hp : p.Prime) (hq : q.Prime)\n    (hmp : m<p) (hmq : m<q) {w : FamilyPacket} (hw : w∈publicPackets (p*q) m) :\n    IsUnit (w.original.a : ZMod (p*q)) := by\n  have hb := (publicPacket_coefficient_bounds hm hw).1\n  exact bounded_int_isUnit hp hq (publicPacket_numerator_ne_zero hm hw)\n    (hb.trans_lt (by exact_mod_cast hmp)) (hb.trans_lt (by exact_mod_cast hmq))\n\ntheorem two_isUnit_of_large_primes {p q m : ℕ} (hm : 2≤m) (hp : p.Prime) (hq : q.Prime)\n    (hmp : m<p) (hmq : m<q) : IsUnit (2 : ZMod (p*q)) := by\n  have h := bounded_int_isUnit hp hq (by norm_num : (2 : ℤ)≠0)\n    (by norm_num; exact_mod_cast hm.trans_lt hmp)\n    (by norm_num; exact_mod_cast hm.trans_lt hmq)\n  simpa using h\n\n/-- All actual public triples survive the full point fork in the hard branch.\nNo balanced-ratio restriction or distinct-prime assumption is needed. -/\ntheorem publicPacket_point_area_gcd {p q m : ℕ} (hm : 2≤m)\n    (hp : p.Prime) (hq : q.Prime) (hmp : m<p) (hmq : m<q) {u w v : FamilyPacket}\n    (hu : u∈publicPackets (p*q) m) (hw : w∈publicPackets (p*q) m)\n    (hv : v∈publicPackets (p*q) m) :\n    (p*q).gcd (affineArea (packetPoint (p*q) m u) (packetPoint (p*q) m w)\n      (packetPoint (p*q) m v)).val=(p*q).gcd (rowArea m u w v : ZMod (p*q)).val := by\n  have hmpos : 0<m := by omega\n  exact packetPoint_area_gcd u w v (two_isUnit_of_large_primes hm hp hq hmp hmq)\n    (publicPacket_leading_unit hmpos hp hq hmp hmq hu)\n    (publicPacket_leading_unit hmpos hp hq hmp hmq hw)\n    (publicPacket_leading_unit hmpos hp hq hmp hmq hv)\n\nend RiemannGaussian.SemiprimeAffinePointAreas\n","RiemannGaussian.SemiprimeBitGcd":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMergedIndexAcquisition\nimport RiemannGaussian.SemiprimeBitDivision\n\n/-!\n# Boolean Euclidean GCD and checked divisor extraction\n\nThe data path uses Boolean words, the frozen restoring division circuit,\nand a physically constructed list of fuel cells. Natural GCD, modulo and\nword evaluation occur only in specifications and proofs. Two successive\nremainders halve the positive divisor, so the public fuel always suffices.\nThe clocks charge the existing Boolean/cell/test primitives, including\nfuel construction, padded words and zero inputs. This scalar backend does\nnot pay the full collision acquisition or the whole factorizer's bit cost.\n-/\n\nnamespace RiemannGaussian.SemiprimeBitGcd\n\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeGroupSelection\n\n/-- Literal loop-budget cells and the work to construct them. -/\nstructure GcdFuel where\n  /-- The recursive algorithm consumes these cells rather than a native counter. -/\n  cells : List Unit\n  /-- Input reads, list tests and newly written fuel cells. -/\n  clock : ℕ\n\n/-- Construct two fuel cells for every physical input bit and one terminal\ncell. A paired frame pays two reads, two tests and four writes. -/\ndef buildGcdFuel : List Bool → List Bool → GcdFuel\n  | [],[] => ⟨[()],3⟩\n  | _::xs,[] =>\n    let child := buildGcdFuel xs []\n    ⟨()::()::child.cells,child.clock+5⟩\n  | [],_::ys =>\n    let child := buildGcdFuel [] ys\n    ⟨()::()::child.cells,child.clock+5⟩\n  | _::xs,_::ys =>\n    let child := buildGcdFuel xs ys\n    ⟨()::()::()::()::child.cells,child.clock+8⟩\ntermination_by xs ys => xs.length+ys.length\ndecreasing_by all_goals simp_wf <;> omega\n\n/-- Exact fuel size and its charged linear construction cost. -/\ntheorem buildGcdFuel_counts (xs ys : List Bool) :\n    (buildGcdFuel xs ys).cells.length=2*(xs.length+ys.length)+1 ∧\n      (buildGcdFuel xs ys).clock≤5*(xs.length+ys.length)+3 := by\n  induction xs generalizing ys with\n  | nil =>\n    induction ys with\n    | nil => simp [buildGcdFuel]\n    | cons bit ys ih =>\n      simp only [buildGcdFuel,List.length_cons,List.length_nil] at *\n      omega\n  | cons bit xs ih =>\n    cases ys with\n    | nil =>\n      have hc := ih []\n      simp only [buildGcdFuel,List.length_cons,List.length_nil] at *\n      omega\n    | cons other ys =>\n      have hc := ih ys\n      simp only [buildGcdFuel,List.length_cons] at *\n      omega\n\n/-- Actual output word, total primitive clock and the actual division count. -/\nstructure GcdReport where\n  /-- The last positive divisor, or the first input when the second is zero. -/\n  bits : List Bool\n  /-- Every performed circuit, scan and fuel-frame primitive. -/\n  clock : ℕ\n  /-- Calls of the restoring quotient/remainder backend. -/\n  divisions : ℕ\n  /-- An explicit failure flag for arbitrary insufficient supplied fuel. -/\n  exhausted : Bool\n\n/-- Fuelled Euclid on actual bit words. Each visited frame pays the fuel\ntest/read and the Boolean branch; the divisor scan and division are charged\nseparately, even though division scans the divisor again. -/\ndef gcdLoop (xs ys : List Bool) : List Unit → GcdReport\n  | [] => ⟨xs,1,0,true⟩\n  | _::fuel =>\n    let check := nonzeroBits ys\n    if check.nonzero=true then\n      let division := divideBits xs ys\n      let child := gcdLoop ys division.remainder fuel\n      ⟨child.bits,check.clock+division.clock+child.clock+3,\n        child.divisions+1,child.exhausted⟩\n    else\n      ⟨xs,check.clock+3,0,false⟩\n\n/-- A stopped loop computes GCD; the exhaustion flag cannot be ignored. -/\ntheorem gcdLoop_correct_of_stopped (xs ys : List Bool) (fuel : List Unit)\n    (hstop : (gcdLoop xs ys fuel).exhausted=false) :\n    bitValue (gcdLoop xs ys fuel).bits=(bitValue xs).gcd (bitValue ys) := by\n  induction fuel generalizing xs ys with\n  | nil => simp [gcdLoop] at hstop\n  | cons cell fuel ih =>\n    by_cases hb : (nonzeroBits ys).nonzero=true\n    · have hc : (gcdLoop ys (divideBits xs ys).remainder fuel).exhausted=false := by\n        simpa only [gcdLoop,ite_eq_left hb] using hstop\n      have he := ih ys (divideBits xs ys).remainder hc\n      simp only [gcdLoop,ite_eq_left hb]\n      rw [he,(divideBits_correct xs ys).2]\n      calc\n        (bitValue ys).gcd (bitValue xs%bitValue ys)=\n            (bitValue xs%bitValue ys).gcd (bitValue ys) := Nat.gcd_comm _ _\n        _=(bitValue ys).gcd (bitValue xs) := (Nat.gcd_rec _ _).symm\n        _=(bitValue xs).gcd (bitValue ys) := Nat.gcd_comm _ _\n    · have hz : bitValue ys=0 := by\n        have hn : ¬0<bitValue ys := by\n          intro hp\n          exact hb ((nonzeroBits_correct ys).mpr hp)\n        omega\n      simp only [gcdLoop,ite_eq_right hb,hz,Nat.gcd_zero_right]\n\n/-- Every two positive Euclidean steps halve the divisor. The theorem\nbounds the actual division calls and proves that literal fuel suffices. -/\ntheorem gcdLoop_stops_pow (k : ℕ) (xs ys : List Bool) (fuel : List Unit)\n    (hy : bitValue ys<2^k) (hf : 2*k+1≤fuel.length) :\n    (gcdLoop xs ys fuel).exhausted=false ∧\n      (gcdLoop xs ys fuel).divisions≤2*k := by\n  induction k generalizing xs ys fuel with\n  | zero =>\n    have hz : bitValue ys=0 := by simpa using hy\n    have hb : ¬(nonzeroBits ys).nonzero=true := by\n      intro hp\n      have hpos := (nonzeroBits_correct ys).mp hp\n      omega\n    cases fuel with\n    | nil => simp only [List.length_nil] at hf; omega\n    | cons cell fuel => simp [gcdLoop,hb]\n  | succ k ih =>\n    cases fuel with\n    | nil => simp only [List.length_nil] at hf; omega\n    | cons cell fuel =>\n      by_cases hb : (nonzeroBits ys).nonzero=true\n      · have hpos := (nonzeroBits_correct ys).mp hb\n        cases fuel with\n        | nil => simp only [List.length_cons,List.length_nil] at hf; omega\n        | cons other fuel =>\n          let remainder := (divideBits xs ys).remainder\n          by_cases hr : (nonzeroBits remainder).nonzero=true\n          · have hrpos := (nonzeroBits_correct remainder).mp hr\n            have he : bitValue remainder=bitValue xs%bitValue ys :=\n              (divideBits_correct xs ys).2\n            have hs := SemiprimeQuotientRows.two_remainders_half\n              (a:=bitValue xs) (b:=bitValue ys) hpos (by\n              simpa only [←he] using hrpos)\n            have hn : bitValue (divideBits ys remainder).remainder<2^k := by\n              rw [(divideBits_correct ys remainder).2]\n              rw [←he] at hs\n              rw [pow_succ] at hy\n              omega\n            have hremaining : 2*k+1≤fuel.length := by\n              simp only [List.length_cons] at hf\n              omega\n            have hc := ih remainder (divideBits ys remainder).remainder fuel hn hremaining\n            simp only [gcdLoop,ite_eq_left hb]\n            change (gcdLoop ys remainder (other::fuel)).exhausted=false ∧\n              (gcdLoop ys remainder (other::fuel)).divisions+1≤2*(k+1)\n            simp only [gcdLoop,ite_eq_left hr]\n            constructor\n            · exact hc.1\n            · omega\n          · simp only [gcdLoop,ite_eq_left hb]\n            change (gcdLoop ys remainder (other::fuel)).exhausted=false ∧\n              (gcdLoop ys remainder (other::fuel)).divisions+1≤2*(k+1)\n            simp only [gcdLoop,ite_eq_right hr]\n            constructor\n            · trivial\n            · omega\n      · simp [gcdLoop,hb]\n\n/-- Neither Euclid nor an exhausted supplied loop grows a physical input\nword. Fixed-width division retains padding, which is charged later. -/\ntheorem gcdLoop_width {L : ℕ} {xs ys : List Bool} (fuel : List Unit)\n    (hx : xs.length≤L) (hy : ys.length≤L) :\n    (gcdLoop xs ys fuel).bits.length≤L := by\n  induction fuel generalizing xs ys with\n  | nil => simpa only [gcdLoop] using hx\n  | cons cell fuel ih =>\n    by_cases hb : (nonzeroBits ys).nonzero=true\n    · have hpos := (nonzeroBits_correct ys).mp hb\n      have hw := (divideBits_widths (xs:=xs) hpos).1\n      have hc := ih hy (by omega : (divideBits xs ys).remainder.length≤L)\n      simpa only [gcdLoop,ite_eq_left hb] using hc\n    · simpa only [gcdLoop,ite_eq_right hb] using hx\n\n/-- Complete loop clock, including repeated divisor scans and every\nphysical frame. This bound also applies to insufficient supplied fuel. -/\ntheorem gcdLoop_cost {L : ℕ} {xs ys : List Bool} (fuel : List Unit)\n    (hx : xs.length≤L) (hy : ys.length≤L) :\n    (gcdLoop xs ys fuel).clock≤\n      fuel.length*(72*(L+1)^2+3*L+4)+1 := by\n  induction fuel generalizing xs ys with\n  | nil => simp [gcdLoop]\n  | cons cell fuel ih =>\n    have hz := nonzeroBits_cost ys\n    by_cases hb : (nonzeroBits ys).nonzero=true\n    · have hpos := (nonzeroBits_correct ys).mp hb\n      have hw := (divideBits_widths (xs:=xs) hpos).1\n      have hc := ih hy (by omega : (divideBits xs ys).remainder.length≤L)\n      have hd := bounded_divideBits (by omega : xs.length≤3*L) hy\n      simp only [gcdLoop,ite_eq_left hb,List.length_cons]\n      nlinarith\n    · simp only [gcdLoop,ite_eq_right hb,List.length_cons]\n      nlinarith\n\n/-- Public GCD constructs its own sufficient physical fuel. -/\ndef gcdBits (xs ys : List Bool) : GcdReport :=\n  let fuel := buildGcdFuel xs ys\n  let child := gcdLoop xs ys fuel.cells\n  {child with clock := child.clock+fuel.clock+1}\n\n/-- GCD is correct and never exhausts its self-constructed fuel, for all\nwords, including both zero values and arbitrarily high zero padding. -/\ntheorem gcdBits_correct (xs ys : List Bool) :\n    bitValue (gcdBits xs ys).bits=(bitValue xs).gcd (bitValue ys) ∧\n      (gcdBits xs ys).exhausted=false := by\n  have hf := (buildGcdFuel_counts xs ys).1\n  have hs := (gcdLoop_stops_pow ys.length xs ys (buildGcdFuel xs ys).cells\n    (bitValue_lt_width ys) (by omega)).1\n  exact ⟨gcdLoop_correct_of_stopped xs ys _ hs,hs⟩\n\n/-- The actual number of division calls is at most twice the second\nword's physical bit length, rather than a unit-cost native GCD call. -/\ntheorem gcdBits_divisions (xs ys : List Bool) :\n    (gcdBits xs ys).divisions≤2*ys.length := by\n  have hf := (buildGcdFuel_counts xs ys).1\n  exact (gcdLoop_stops_pow ys.length xs ys (buildGcdFuel xs ys).cells\n    (bitValue_lt_width ys) (by omega)).2\n\n/-- A bounded physical input width is preserved by the GCD output. -/\ntheorem gcdBits_width {L : ℕ} {xs ys : List Bool}\n    (hx : xs.length≤L) (hy : ys.length≤L) :\n    (gcdBits xs ys).bits.length≤L :=\n  gcdLoop_width _ hx hy\n\n/-- Uniform cubic bit-primitive bound pays fuel allocation and every\nrestoring division. Natural clock arithmetic is proof instrumentation. -/\ntheorem gcdBits_cost {L : ℕ} {xs ys : List Bool}\n    (hx : xs.length≤L) (hy : ys.length≤L) :\n    (gcdBits xs ys).clock≤400*(L+1)^3 := by\n  obtain ⟨hf,hbuild⟩ := buildGcdFuel_counts xs ys\n  have hloop := gcdLoop_cost (buildGcdFuel xs ys).cells hx hy\n  have hframe : 72*(L+1)^2+3*L+4≤79*(L+1)^2 := by nlinarith\n  have hsize : (buildGcdFuel xs ys).cells.length≤4*L+1 := by omega\n  have hm := Nat.mul_le_mul hsize hframe\n  have hclock : (gcdBits xs ys).clock≤(4*L+1)*(79*(L+1)^2)+10*L+5 := by\n    dsimp only [gcdBits]\n    omega\n  have hcube : (4*L+1)*(79*(L+1)^2)+10*L+5≤400*(L+1)^3 := by\n    nlinarith [sq_nonneg (L:ℤ)]\n  exact le_trans hclock hcube\n\n/-- Retained GCD, optional checked factor word and their composed clock. -/\nstructure CheckedBitsReport where\n  /-- The complete Boolean GCD report used by this actual check. -/\n  gcd : GcdReport\n  /-- A word is returned only after two Boolean borrow comparisons. -/\n  factor : Option (List Bool)\n  /-- GCD, both comparisons, the literal one cell, gate and output tests. -/\n  clock : ℕ\n\n/-- Implement the existing checked-signal interface with Boolean circuits.\nThe lower comparison is one minus the GCD; the upper comparison is the GCD\nminus the modulus. Their final borrows recognize exactly a proper factor. -/\ndef checkedSignalBits (modulus signal : List Bool) : CheckedBitsReport :=\n  let divisor := gcdBits modulus signal\n  let lower := subBits [true] divisor.bits false\n  let upper := subBits divisor.bits modulus false\n  let proper := Bool.and lower.borrow upper.borrow\n  let factor := if proper=true then some divisor.bits else none\n  ⟨divisor,factor,divisor.clock+bitCost lower.result+bitCost upper.result+5⟩\n\n/-- Both actual borrow bits together are exactly the proper-GCD condition,\nincluding zero moduli, saturated signals, prime powers and padded inputs. -/\ntheorem checkedSignalBits_condition (modulus signal : List Bool) :\n    Bool.and (subBits [true] (gcdBits modulus signal).bits false).borrow\n        (subBits (gcdBits modulus signal).bits modulus false).borrow=true ↔\n      1<(bitValue modulus).gcd (bitValue signal) ∧\n        (bitValue modulus).gcd (bitValue signal)<bitValue modulus := by\n  have hlo := subBits_borrow_iff [true] (gcdBits modulus signal).bits false\n  have hhi := subBits_borrow_iff (gcdBits modulus signal).bits modulus false\n  simp only [bitValue,bitNat,ite_true,Nat.mul_zero,Nat.add_zero,\n    Bool.false_eq_true,ite_false] at hlo\n  simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero] at hhi\n  rw [Bool.and_eq_true,hlo,hhi,(gcdBits_correct modulus signal).1]\n\n/-- The executable word routine returns exactly the established checked\nsignal value. No natural GCD or ordering oracle computes its output. -/\ntheorem checkedSignalBits_exact (modulus signal : List Bool) :\n    (checkedSignalBits modulus signal).factor.map bitValue=\n      checkedSignal (bitValue modulus) (bitValue signal) := by\n  have hc := checkedSignalBits_condition modulus signal\n  have hg := (gcdBits_correct modulus signal).1\n  by_cases hb : Bool.and (subBits [true] (gcdBits modulus signal).bits false).borrow\n      (subBits (gcdBits modulus signal).bits modulus false).borrow=true\n  · have hd := hc.mp hb\n    simp only [checkedSignalBits,ite_eq_left hb,Option.map_some,hg,checkedSignal,ite_eq_left hd]\n  · have hd : ¬(1<(bitValue modulus).gcd (bitValue signal) ∧\n        (bitValue modulus).gcd (bitValue signal)<bitValue modulus) := by\n      intro hp\n      exact hb (hc.mpr hp)\n    simp only [checkedSignalBits,ite_eq_right hb,Option.map_none,checkedSignal,ite_eq_right hd]\n\n/-- Every returned Boolean word evaluates to a checked proper divisor. -/\ntheorem checkedSignalBits_sound {modulus signal divisor : List Bool}\n    (h : (checkedSignalBits modulus signal).factor=some divisor) :\n    ProperDivisor (bitValue modulus) (bitValue divisor) := by\n  apply checkedSignal_sound\n  rw [←checkedSignalBits_exact modulus signal,h,Option.map_some]\n\n/-- A returned factor retains the bounded physical GCD width. -/\ntheorem checkedSignalBits_width {L : ℕ} {modulus signal divisor : List Bool}\n    (hm : modulus.length≤L) (hs : signal.length≤L)\n    (h : (checkedSignalBits modulus signal).factor=some divisor) :\n    divisor.length≤L := by\n  unfold checkedSignalBits at h\n  dsimp only at h\n  split_ifs at h\n  cases h\n  exact gcdBits_width hm hs\n\n/-- One checked divisor extraction has a fully composed cubic scalar\nbit-primitive bound, paying fuel construction and both borrow comparisons. -/\ntheorem checkedSignalBits_cost {L : ℕ} {modulus signal : List Bool}\n    (hm : modulus.length≤L) (hs : signal.length≤L) :\n    (checkedSignalBits modulus signal).clock≤500*(L+1)^3 := by\n  have hg := gcdBits_cost hm hs\n  have hw := gcdBits_width hm hs\n  have hlo := subBits_cost [true] (gcdBits modulus signal).bits false\n  have hhi := subBits_cost (gcdBits modulus signal).bits modulus false\n  have hlowidth : max ([true]:List Bool).length (gcdBits modulus signal).bits.length≤L+1 :=\n    max_le (by simp) (by omega)\n  have hhiwidth : max (gcdBits modulus signal).bits.length modulus.length≤L :=\n    max_le hw hm\n  have hbound : (checkedSignalBits modulus signal).clock≤\n      400*(L+1)^3+24*L+21 := by\n    dsimp only [checkedSignalBits]\n    omega\n  have hpower : L+1≤(L+1)^3 := Nat.le_self_pow (by decide : 3≠0) (L+1)\n  have hlast : 400*(L+1)^3+24*L+21≤500*(L+1)^3 := by omega\n  exact le_trans hbound hlast\n\nend RiemannGaussian.SemiprimeBitGcd\n","RiemannGaussian.SemiprimeCachedSourcePublicExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeCachedSourceCounter\nimport RiemannGaussian.SemiprimePublicAcquiredExecution\n\n/-!\n# Materialized count and prefix recovery on the actual public factoring graph\n\nAll source coefficients and designs are acquired internally. The runtime entry\ncallback is the actual paid subdivided arithmetic/equality checker with the\nexisting every-occurrence prefix gate. Only computed numerical source parameters\nare exposed here; the N-only schedule is connected in the companion module.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeCachedSourcePublicExecution\nopen scoped BigOperators\nopen SemiprimePublicAcquiredExecution\nopen SemiprimeCountRecovery SemiprimeCounterSearch\n\n/-- Actual public prefix count with the new paid original-source counter. -/\ndef prefixCount (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (fixed : List (Fin (wireCount N) × Bool)) : ℕ :=\n  Nat.floor (SemiprimeCachedSourceCounter.count (r := r) (Q := Q)\n    (indexedArity N) (indexedCoordinate N hN) eps R 2 J\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed)).value\n\n/-- Every new requested count agrees with the old public interpreter, for the\nsame original network and same every-occurrence restrictions. -/\ntheorem prefixCount_eq_old (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    prefixCount N hN r Q eps R J fixed =\n      SemiprimePublicAcquiredExecution.prefixCount N hN r Q eps R J fixed := by\n  exact congrArg Nat.floor (SemiprimeCachedSourceCounter.count_value_eq_old\n    (indexedArity N) (indexedCoordinate N hN) eps R 2 J\n    (SemiprimeAcquiredPrefixSearch.entry (indexedArity N) (indexedCoordinate N hN)\n      (indexedEntry N hN) fixed) (indexed_occurrences N hN) hQ hAQ hJ hprecision)\n\n/-- Counts are exactly the original restricted accepting counts, not modular approximations. -/\ntheorem prefixCount_correct (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    prefixCount N hN r Q eps R J fixed =\n      acceptedCount (restricted assignmentBit (indexedPredicate N hN) fixed) :=\n  (prefixCount_eq_old N hN r Q eps R J hQ hAQ hJ hprecision fixed).trans\n    (SemiprimePublicAcquiredExecution.prefixCount_correct N hN r Q eps R J hQ hAQ hJ hprecision fixed)\n\n/-- Actual zero-first bit selection invokes the NEW acquired materialized count. -/\ndef search (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) :\n    SearchResult (Fin (wireCount N)) :=\n  SemiprimeCountRecovery.search (prefixCount N hN r Q eps R J) (List.finRange (wireCount N))\n\n/-- Equality includes all selected bits and the actual prefix-query count. -/\ntheorem search_eq_old (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    search N hN r Q eps R J = SemiprimePublicAcquiredExecution.search N hN r Q eps R J := by\n  have hp : prefixCount N hN r Q eps R J =\n      SemiprimePublicAcquiredExecution.prefixCount N hN r Q eps R J := by\n    funext fixed\n    exact prefixCount_eq_old N hN r Q eps R J hQ hAQ hJ hprecision fixed\n  exact congrArg (fun f => SemiprimeCountRecovery.search f (List.finRange (wireCount N))) hp\n\n/-- Decode the actual selected physical input bits into an integer factor. -/\ndef factor (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) : Option ℕ :=\n  (search N hN r Q eps R J).values.map (fun values => decodeOperand N values 0)\n\n/-- The materialized factoring execution preserves the exact public selected output. -/\ntheorem factor_eq_old (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    factor N hN r Q eps R J = SemiprimePublicAcquiredExecution.factor N hN r Q eps R J := by\n  unfold factor SemiprimePublicAcquiredExecution.factor\n  rw [search_eq_old N hN r Q eps R J hQ hAQ hJ hprecision]\n\n/-- Every returned integer is a genuine proper divisor of N. -/\ntheorem factor_sound (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J)\n    (p : ℕ) (h : factor N hN r Q eps R J=some p) : 2≤p ∧ p<N ∧ p∣N :=\n  SemiprimePublicAcquiredExecution.factor_sound N hN r Q eps R J hQ hAQ hJ hprecision p\n    ((factor_eq_old N hN r Q eps R J hQ hAQ hJ hprecision).symm.trans h)\n\n/-- Exact failure characterization, including primes and perfect squares. -/\ntheorem factor_none_iff (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ)\n    (hQ : 1≤Q) (hAQ : OAI.Algorithms.SubexponentialSAT.Subexp.TailInterval.intervalStart r Q R≤Q)\n    (hJ : 0<J) (hprecision : (∑ e, indexedArity N e)*R<Q*J) :\n    factor N hN r Q eps R J=none ↔ ¬Nonempty (SemiprimePublicFactorCount.OrdinaryFactors N) := by\n  rw [factor_eq_old N hN r Q eps R J hQ hAQ hJ hprecision]\n  exact SemiprimePublicAcquiredExecution.factor_none_iff N hN r Q eps R J hQ hAQ hJ hprecision\n\n/-- At most one initial and one conditional query per actual public wire. -/\ntheorem search_queries (N : ℕ) (hN : 0<N) (r Q : ℕ) [NeZero r] (eps : ℚ) (R J : ℕ) :\n    (search N hN r Q eps R J).queries ≤ wireCount N+1 := by\n  simpa only [search,List.length_finRange] using SemiprimeCountRecovery.search_queries_le\n    (prefixCount N hN r Q eps R J) (List.finRange (wireCount N))\n\nend RiemannGaussian.SemiprimeCachedSourcePublicExecution\n","RiemannGaussian.SemiprimeCounterRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport Mathlib.Analysis.SpecialFunctions.Pow.Asymptotics\nimport Mathlib.Analysis.SpecialFunctions.Log.Deriv\nimport Mathlib.Data.Nat.Log\nimport Mathlib.Data.Nat.Sqrt\nimport Mathlib.Tactic\n\n/-!\n# Rate obligations for the growing-arity shared-summary counter\n\nThese results establish analytic decay and the incidence-balance implication.\nThey do not identify an implementation with a machine or assert acceptance of\nunformalized integer schedule/tail checks.\n-/\n\nnoncomputable section\nopen Filter\nopen scoped Topology\n\nnamespace RiemannGaussian.SemiprimeCounterRate\n\n/-- The displayed ordinary-bit counter rate, in the bit-length parameter. -/\ndef rho (x : ℝ) : ℝ := (Real.log (Real.log x)) ^ 2 / Real.sqrt (Real.log x)\n\ntheorem tendsto_rho_zero : Tendsto rho atTop (𝓝 0) := by\n  have h := (isLittleO_log_rpow_rpow_atTop (2 : ℝ)\n    (show (0 : ℝ) < 1 / 2 by norm_num)).tendsto_div_nhds_zero\n  have hc := h.comp Real.tendsto_log_atTop\n  change Tendsto (fun x : ℝ => (Real.log (Real.log x)) ^ 2 / Real.sqrt (Real.log x)) atTop (𝓝 0)\n  simpa [Function.comp_def, Real.sqrt_eq_rpow, Real.rpow_two] using hc\n\n/-- Every fixed polynomial prefactor and constant in the displayed exponent\nare absorbed into any positive exponential rate in bit length. -/\ntheorem eventually_polynomial_exp_rho_le (d A ε : ℝ) (hε : 0 < ε) :\n    ∀ᶠ x : ℝ in atTop,\n      x ^ d * Real.exp (A * x * rho x) ≤ Real.exp (ε * x) := by\n  have hlog : Tendsto (fun x : ℝ => Real.log x / x) atTop (𝓝 0) :=\n    Real.isLittleO_log_id_atTop.tendsto_div_nhds_zero\n  have hlim : Tendsto (fun x : ℝ => d * (Real.log x / x) + A * rho x)\n      atTop (𝓝 0) := by\n    simpa using (hlog.const_mul d).add (tendsto_rho_zero.const_mul A)\n  filter_upwards [hlim.eventually (gt_mem_nhds hε), eventually_gt_atTop (0 : ℝ)]\n    with x hx hxpos\n  rw [Real.rpow_def_of_pos hxpos, ← Real.exp_add]\n  apply Real.exp_le_exp.mpr\n  have he := mul_le_mul_of_nonneg_right (le_of_lt hx) (le_of_lt hxpos)\n  field_simp at he\n  nlinarith\n\n/-- A fixed multiplicative constant (including a finite exceptional-input\nconstant) is also absorbed without changing the arbitrary target exponent. -/\ntheorem eventually_constant_polynomial_exp_rho_le (C d A ε : ℝ) (hε : 0 < ε) :\n    ∀ᶠ x : ℝ in atTop,\n      C * x ^ d * Real.exp (A * x * rho x) ≤ Real.exp (ε * x) := by\n  filter_upwards [eventually_polynomial_exp_rho_le (d + 1) A ε hε,\n    eventually_ge_atTop C, eventually_gt_atTop (0 : ℝ)] with x hx hCx hxpos\n  calc\n    C * x ^ d * Real.exp (A * x * rho x) ≤\n        x * x ^ d * Real.exp (A * x * rho x) := by gcongr\n    _ = x ^ (d + 1) * Real.exp (A * x * rho x) := by\n      rw [Real.rpow_add hxpos, Real.rpow_one]\n      ring\n    _ ≤ _ := hx\n\n/-- The actual growing-arity overhead exp(B*x^(3/4)) is absorbed as well. -/\ntheorem eventually_polynomial_counter_with_arity_le (d A B ε : ℝ) (hε : 0 < ε) :\n    ∀ᶠ x : ℝ in atTop,\n      x ^ d * Real.exp (A * x * rho x + B * x ^ (3 / 4 : ℝ)) ≤\n        Real.exp (ε * x) := by\n  have hlog : Tendsto (fun x : ℝ => Real.log x / x) atTop (𝓝 0) :=\n    Real.isLittleO_log_id_atTop.tendsto_div_nhds_zero\n  have harity := (tendsto_rpow_neg_atTop (show (0 : ℝ) < 1 / 4 by norm_num)).const_mul B\n  have hlim : Tendsto (fun x : ℝ => d * (Real.log x / x) + A * rho x +\n      B * x ^ (-(1 / 4) : ℝ)) atTop (𝓝 0) := by\n    simpa using ((hlog.const_mul d).add (tendsto_rho_zero.const_mul A)).add harity\n  filter_upwards [hlim.eventually (gt_mem_nhds hε), eventually_gt_atTop (0 : ℝ)]\n    with x hx hxpos\n  rw [Real.rpow_def_of_pos hxpos, ← Real.exp_add]\n  apply Real.exp_le_exp.mpr\n  have he := mul_le_mul_of_nonneg_right (le_of_lt hx) (le_of_lt hxpos)\n  have hp : x ^ (-(1 / 4) : ℝ) * x = x ^ (3 / 4 : ℝ) := by\n    calc\n      x ^ (-(1 / 4) : ℝ) * x = x ^ (-(1 / 4) : ℝ) * x ^ (1 : ℝ) := by rw [Real.rpow_one]\n      _ = x ^ (-(1 / 4) + 1 : ℝ) := (Real.rpow_add hxpos _ _).symm\n      _ = _ := by norm_num\n  have hdiv : (Real.log x / x) * x = Real.log x := div_mul_cancel₀ _ (ne_of_gt hxpos)\n  simp only [add_mul, mul_assoc, hdiv, hp] at he\n  nlinarith\n\n/-- Fixed leading constants and the growing-arity cost can be charged together. -/\ntheorem eventually_constant_polynomial_counter_with_arity_le (C d A B ε : ℝ)\n    (hε : 0 < ε) :\n    ∀ᶠ x : ℝ in atTop,\n      C * x ^ d * Real.exp (A * x * rho x + B * x ^ (3 / 4 : ℝ)) ≤\n        Real.exp (ε * x) := by\n  filter_upwards [eventually_polynomial_counter_with_arity_le (d + 1) A B ε hε,\n    eventually_ge_atTop C, eventually_gt_atTop (0 : ℝ)] with x hx hCx hxpos\n  calc\n    C * x ^ d * Real.exp (A * x * rho x + B * x ^ (3 / 4 : ℝ)) ≤\n        x * x ^ d * Real.exp (A * x * rho x + B * x ^ (3 / 4 : ℝ)) := by gcongr\n    _ = x ^ (d + 1) * Real.exp (A * x * rho x + B * x ^ (3 / 4 : ℝ)) := by\n      rw [Real.rpow_add hxpos, Real.rpow_one]\n      ring\n    _ ≤ _ := hx\n\n/-- The same bound in the integer-size parameter: every positive power wins. -/\ntheorem eventually_log_polynomial_counter_subpower (d A ε : ℝ) (hε : 0 < ε) :\n    ∀ᶠ N : ℝ in atTop,\n      (Real.log N) ^ d * Real.exp (A * Real.log N * rho (Real.log N)) ≤ N ^ ε := by\n  filter_upwards [Real.tendsto_log_atTop.eventually\n    (eventually_polynomial_exp_rho_le d A ε hε), eventually_gt_atTop (0 : ℝ)] with N hN hNpos\n  simpa only [Real.rpow_def_of_pos hNpos, mul_comm ε (Real.log N)] using hN\n\n/-- In particular, the proposed algorithm-level bound is eventually sixth-rate.\nThis is an analytic bound, not a supplied running-time theorem. -/\ntheorem eventually_log_polynomial_counter_sixth (d A : ℝ) :\n    ∀ᶠ N : ℝ in atTop,\n      (Real.log N) ^ d * Real.exp (A * Real.log N * rho (Real.log N)) ≤\n        N ^ (1 / 6 : ℝ) :=\n  eventually_log_polynomial_counter_subpower d A (1 / 6) (by norm_num)\n\n/-- Full analytic envelope, including a fixed leading constant and growing\narity overhead, is eventually bounded by every positive power of N. -/\ntheorem eventually_full_counter_bound_subpower (C d A B ε : ℝ) (hε : 0 < ε) :\n    ∀ᶠ N : ℝ in atTop,\n      C * (Real.log N) ^ d * Real.exp (A * Real.log N * rho (Real.log N) +\n        B * (Real.log N) ^ (3 / 4 : ℝ)) ≤ N ^ ε := by\n  filter_upwards [Real.tendsto_log_atTop.eventually\n    (eventually_constant_polynomial_counter_with_arity_le C d A B ε hε),\n    eventually_gt_atTop (0 : ℝ)] with N hN hNpos\n  simpa only [Real.rpow_def_of_pos hNpos, mul_comm ε (Real.log N)] using hN\n\n/-- Exact integer budget, before any real asymptotic estimates. -/\ntheorem integer_dimension_budget {r ν Q lam : ℕ}\n    (hr : r ^ 2 ≤ 2 ^ ν) (hQ : 128 * ν * Q ≤ lam) :\n    (r ^ (2 * Q)) ^ 128 ≤ 2 ^ lam := by\n  calc\n    (r ^ (2 * Q)) ^ 128 = (r ^ 2) ^ (128 * Q) := by\n      rw [← pow_mul, ← pow_mul]\n      congr 1\n      omega\n    _ ≤ (2 ^ ν) ^ (128 * Q) := Nat.pow_le_pow_left hr _\n    _ = 2 ^ (128 * ν * Q) := by\n      rw [← pow_mul]\n      congr 1\n      ring\n    _ ≤ 2 ^ lam := Nat.pow_le_pow_right (by decide) hQ\n\n/-- The actual integer-floor formulas in `shared_parameters.py`. -/\ndef scheduledGroupCount (lam : ℕ) : ℕ := Nat.sqrt lam / (Nat.clog 2 lam) ^ 2\n\n/-- The scheduled number Q of nonzero interpolation nodes. -/\ndef scheduledPointCount (lam : ℕ) : ℕ := lam / (128 * Nat.clog 2 lam)\n\ntheorem scheduled_dimension_budget (lam : ℕ) :\n    (scheduledGroupCount lam ^ (2 * scheduledPointCount lam)) ^ 128 ≤ 2 ^ lam := by\n  apply integer_dimension_budget\n  · exact (Nat.pow_le_pow_left (Nat.div_le_self _ _) 2).trans\n      ((Nat.sqrt_le' lam).trans (Nat.le_pow_clog (by decide) lam))\n  · simpa [scheduledPointCount, Nat.mul_comm, Nat.mul_left_comm, Nat.mul_assoc] using\n      Nat.div_mul_le_self lam (128 * Nat.clog 2 lam)\n\n/-- For the bit-count parameter n, the scheduled auxiliary dimension satisfies\nan exact polynomial-size budget, even before any eventual guard hypotheses. -/\ntheorem scheduled_dimension_budget_input {n : ℕ} (hn : 1 < n) :\n    (scheduledGroupCount (Nat.clog 2 n) ^ (2 * scheduledPointCount (Nat.clog 2 n))) ^ 128 < 2 * n := by\n  apply lt_of_le_of_lt (scheduled_dimension_budget (Nat.clog 2 n))\n  have hp := Nat.pow_pred_clog_lt_self (by decide : 1 < 2) hn\n  simp only [Nat.pred_eq_sub_one] at hp\n  have hc : 1 ≤ Nat.clog 2 n := Nat.clog_pos (by decide) hn\n  calc\n    2 ^ Nat.clog 2 n = 2 ^ (Nat.clog 2 n - 1) * 2 := by\n      rw [← pow_succ, Nat.sub_add_cancel hc]\n    _ < 2 * n := by omega\n\n/-- The real normalized load corresponding to occurrence two and arity\nO(n^(3/4)) tends to zero under the scheduled dimension exponent. -/\ntheorem tendsto_incidence_load_zero (C A : ℝ) :\n    Tendsto (fun x : ℝ => (2 + C * x ^ (3 / 4 : ℝ)) *\n      (A * x ^ (1 / 64 : ℝ)) / x) atTop (𝓝 0) := by\n  have h1 := (tendsto_rpow_neg_atTop (show (0 : ℝ) < 63 / 64 by norm_num)).const_mul (2 * A)\n  have h2 := (tendsto_rpow_neg_atTop (show (0 : ℝ) < 15 / 64 by norm_num)).const_mul (C * A)\n  have hlim := h1.add h2\n  simp only [mul_zero, add_zero] at hlim\n  apply hlim.congr'\n  filter_upwards [eventually_gt_atTop (0 : ℝ)] with x hx\n  have he1 : x ^ (1 / 64 : ℝ) / x = x ^ (-(63 / 64) : ℝ) := by\n    rw [show (-(63 / 64) : ℝ) = 1 / 64 - 1 by norm_num,\n      Real.rpow_sub hx, Real.rpow_one]\n  have he2 : x ^ (3 / 4 : ℝ) * x ^ (1 / 64 : ℝ) / x =\n      x ^ (-(15 / 64) : ℝ) := by\n    rw [← Real.rpow_add hx]\n    rw [show (-(15 / 64) : ℝ) = (3 / 4 + 1 / 64) - 1 by norm_num,\n      Real.rpow_sub hx, Real.rpow_one]\n  calc\n    2 * A * x ^ (-(63 / 64) : ℝ) + C * A * x ^ (-(15 / 64) : ℝ) =\n        2 * A * (x ^ (1 / 64 : ℝ) / x) +\n          C * A * (x ^ (3 / 4 : ℝ) * x ^ (1 / 64 : ℝ) / x) := by rw [he1, he2]\n    _ = _ := by ring\n\n/-- Genuine eventual load balance; no assumption that the guard succeeds.\nOnly its separately proved numerical dimension budget is an input here. -/\ntheorem eventually_incidence_balance (C A : ℝ) (hC : 0 ≤ C) :\n    ∀ᶠ x : ℝ in atTop, ∀ w d : ℝ,\n      0 ≤ w → 0 ≤ d → w ≤ C * x ^ (3 / 4 : ℝ) →\n      d ≤ A * x ^ (1 / 64 : ℝ) → 2 * (2 + w) * d ≤ 2 * x := by\n  filter_upwards [(tendsto_incidence_load_zero C A).eventually\n    (gt_mem_nhds (show (0 : ℝ) < 1 by norm_num)), eventually_gt_atTop (0 : ℝ)]\n      with x hx hxpos w d hw hd hwbound hdbound\n  have hbound : (2 + C * x ^ (3 / 4 : ℝ)) * (A * x ^ (1 / 64 : ℝ)) ≤ x :=\n    by simpa using (div_le_iff₀ hxpos).mp (le_of_lt hx)\n  have hmul : (2 + w) * d ≤ (2 + C * x ^ (3 / 4 : ℝ)) *\n      (A * x ^ (1 / 64 : ℝ)) :=\n    mul_le_mul (by linarith) hdbound hd (by positivity)\n  linarith\n\n/-- The auxiliary array cardinality for the exact floor/square-root schedule. -/\ndef scheduledDimension (n : ℕ) : ℕ :=\n  scheduledGroupCount (Nat.clog 2 n) ^ (2 * scheduledPointCount (Nat.clog 2 n))\n\n/-- The real budget required by the growing-arity balance theorem follows from\ninteger schedule arithmetic; it is not an extra asymptotic hypothesis. -/\ntheorem scheduled_dimension_square_le {n : ℕ} (hn : 1 < n) :\n    (scheduledDimension n : ℝ) ^ 2 ≤ 2 * (n : ℝ) ^ (1 / 64 : ℝ) := by\n  have hp : ((scheduledDimension n : ℝ) ^ 2) ^ (64 : ℝ) ≤ 2 * (n : ℝ) := by\n    rw [Real.rpow_ofNat, ← pow_mul]\n    norm_num\n    exact_mod_cast (le_of_lt (scheduled_dimension_budget_input hn))\n  have hr := (Real.le_rpow_inv_iff_of_pos\n    (sq_nonneg (scheduledDimension n : ℝ))\n    (show 0 ≤ 2 * (n : ℝ) by positivity) (show (0 : ℝ) < 64 by norm_num)).mpr hp\n  have htwo : (2 : ℝ) ^ (1 / 64 : ℝ) ≤ 2 :=\n    Real.rpow_le_self_of_one_le (by norm_num) (by norm_num)\n  calc\n    (scheduledDimension n : ℝ) ^ 2 ≤ (2 * (n : ℝ)) ^ (1 / 64 : ℝ) := by\n      simpa only [one_div] using hr\n    _ = (2 : ℝ) ^ (1 / 64 : ℝ) * (n : ℝ) ^ (1 / 64 : ℝ) :=\n      Real.mul_rpow (by norm_num) (by positivity)\n    _ ≤ 2 * (n : ℝ) ^ (1 / 64 : ℝ) :=\n      mul_le_mul_of_nonneg_right htwo (by positivity)\n\n/-- Eventual acceptance of the actual incidence-load inequality for every\narity bounded by C*n^(3/4), proved for the scheduled integer D itself.\nThe other schedule tests (group balance and spectral tail) are separate. -/\ntheorem eventually_scheduled_incidence_balance (C : ℝ) (hC : 0 ≤ C) :\n    ∀ᶠ n : ℕ in atTop, ∀ w : ℕ,\n      (w : ℝ) ≤ C * (n : ℝ) ^ (3 / 4 : ℝ) →\n      2 * (2 + w) * scheduledDimension n ^ 2 ≤ 2 * n := by\n  have ht : Tendsto (fun n : ℕ => (n : ℝ)) atTop atTop :=\n    tendsto_natCast_atTop_atTop\n  filter_upwards [ht.eventually (eventually_incidence_balance C 2 hC),\n    eventually_gt_atTop (1 : ℕ)] with n hn hnp w hw\n  have hb := hn (w : ℝ) ((scheduledDimension n : ℝ) ^ 2)\n    (by positivity) (by positivity) hw (scheduled_dimension_square_le hnp)\n  exact_mod_cast hb\n\nprivate theorem twice_sq_le_pow_pred {k : ℕ} (hk : 16 ≤ k) :\n    2 * k ^ 2 ≤ 2 ^ (k - 1) := by\n  induction k, hk using Nat.le_induction with\n  | base => norm_num\n  | succ k hk ih =>\n    calc\n      2 * (k + 1) ^ 2 ≤ 2 * (2 * k ^ 2) := by nlinarith\n      _ ≤ 2 * 2 ^ (k - 1) := Nat.mul_le_mul_left 2 ih\n      _ = 2 ^ k := by\n        rw [mul_comm, ← pow_succ, Nat.sub_add_cancel (by omega)]\n      _ = 2 ^ (k + 1 - 1) := by simp\n\n/-- An explicit eventual bound for the second numerical balance test. No\nbinomial estimate or eventual-guard assumption enters this theorem. -/\ntheorem scheduled_group_balance {n : ℕ} (hn : 2 ^ 16 < n) :\n    2 * scheduledPointCount (Nat.clog 2 n) * scheduledGroupCount (Nat.clog 2 n) ^ 2 ≤ n := by\n  let lam := Nat.clog 2 n\n  have hlarge : 16 ≤ lam := by\n    have := (Nat.lt_clog_iff_pow_lt (by decide : 1 < 2)).mpr hn\n    omega\n  have hq : scheduledPointCount lam ≤ lam := Nat.div_le_self _ _\n  have hr : scheduledGroupCount lam ^ 2 ≤ lam :=\n    (Nat.pow_le_pow_left (Nat.div_le_self _ _) 2).trans (Nat.sqrt_le' lam)\n  have hmul := Nat.mul_le_mul hq hr\n  have hpoly := twice_sq_le_pow_pred hlarge\n  have hpow := Nat.pow_pred_clog_lt_self (by decide : 1 < 2)\n    (show 1 < n by omega)\n  simp only [Nat.pred_eq_sub_one] at hpow\n  change 2 * scheduledPointCount lam * scheduledGroupCount lam ^ 2 ≤ n\n  change 2 ^ (lam - 1) < n at hpow\n  nlinarith\n\nprivate theorem quartic_le_pow_pred {k : ℕ} (hk : 64 ≤ k) :\n    65536 * k ^ 4 ≤ 2 ^ (k - 1) := by\n  induction k, hk using Nat.le_induction with\n  | base => norm_num\n  | succ k hk ih =>\n    have h8 : 8 ≤ k := by omega\n    have h1 := Nat.mul_le_mul_right (k ^ 3) h8\n    have h2 := Nat.mul_le_mul_right (k ^ 2) h8\n    have h3 := Nat.mul_le_mul_right k h8\n    have hstep : (k + 1) ^ 4 ≤ 2 * k ^ 4 := by nlinarith\n    calc\n      65536 * (k + 1) ^ 4 ≤ 65536 * (2 * k ^ 4) := Nat.mul_le_mul_left _ hstep\n      _ = 2 * (65536 * k ^ 4) := by ring\n      _ ≤ 2 * 2 ^ (k - 1) := Nat.mul_le_mul_left _ ih\n      _ = 2 ^ k := by rw [mul_comm, ← pow_succ, Nat.sub_add_cancel (by omega)]\n      _ = 2 ^ (k + 1 - 1) := by simp\n\n/-- Exact ceiling square root used in the Python schedule. -/\ndef scheduledCeilSqrt (lam : ℕ) : ℕ :=\n  Nat.sqrt lam + if Nat.sqrt lam ^ 2 = lam then 0 else 1\n\n/-- The scheduled degree R=4*ceil(sqrt(lambda)); this is not the group count r. -/\ndef scheduledDegree (lam : ℕ) : ℕ := 4 * scheduledCeilSqrt lam\n\n/-- Explicit large-log range tests, without assuming any guard or tail bound. -/\ntheorem scheduled_parameter_ranges {lam : ℕ} (hν : 64 ≤ Nat.clog 2 lam) :\n    2 ≤ scheduledGroupCount lam ∧ 32 ≤ scheduledDegree lam ∧\n      6 * scheduledDegree lam ≤ scheduledPointCount lam := by\n  let ν := Nat.clog 2 lam\n  let s := Nat.sqrt lam\n  have hν64 : 64 ≤ ν := hν\n  have hlam : 1 < lam := by\n    by_contra h\n    have : lam ≤ 1 := by omega\n    have hz := Nat.clog_of_right_le_one this 2\n    omega\n  have hpow := Nat.pow_pred_clog_lt_self (by decide : 1 < 2) hlam\n  simp only [Nat.pred_eq_sub_one] at hpow\n  have hquart := quartic_le_pow_pred hν64\n  have hs : 256 * ν ^ 2 ≤ s := by\n    apply Nat.le_sqrt'.mpr\n    change 2 ^ (ν - 1) < lam at hpow\n    nlinarith\n  have hνpos : 0 < ν ^ 2 := by positivity\n  have hr : 2 ≤ scheduledGroupCount lam := by\n    apply (Nat.le_div_iff_mul_le hνpos).mpr\n    change 2 * ν ^ 2 ≤ s\n    nlinarith\n  have hslarge : 6144 * ν ≤ s := by nlinarith\n  have hspos : 1 ≤ s := by nlinarith\n  have hnorm : 3072 * ν * (s + 1) ≤ lam := by\n    have hsq : s ^ 2 ≤ lam := Nat.sqrt_le' lam\n    have hm := Nat.mul_le_mul_right s hslarge\n    nlinarith\n  have hQ : 24 * (s + 1) ≤ scheduledPointCount lam := by\n    apply (Nat.le_div_iff_mul_le (show 0 < 128 * ν by positivity)).mpr\n    nlinarith\n  have hc : s ≤ scheduledCeilSqrt lam ∧ scheduledCeilSqrt lam ≤ s + 1 := by\n    dsimp [scheduledCeilSqrt, s]\n    split_ifs <;> omega\n  refine ⟨hr, ?_, ?_⟩\n  · dsimp [scheduledDegree]\n    nlinarith\n  · dsimp [scheduledDegree]\n    nlinarith\n\n/-- The integer ceiling binary logarithm itself tends to infinity. -/\ntheorem tendsto_clog_two_atTop : Tendsto (Nat.clog 2) atTop atTop := by\n  apply tendsto_atTop.mpr\n  intro b\n  filter_upwards [eventually_gt_atTop (2 ^ b)] with n hn\n  exact le_of_lt ((Nat.lt_clog_iff_pow_lt (by decide : 1 < 2)).mpr hn)\n\n/-- Thus the exact positivity and concentration-range tests hold eventually\nfor the actual double-ceiling-log integer schedule. -/\ntheorem eventually_scheduled_parameter_ranges :\n    ∀ᶠ n : ℕ in atTop,\n      2 ≤ scheduledGroupCount (Nat.clog 2 n) ∧\n      32 ≤ scheduledDegree (Nat.clog 2 n) ∧\n      6 * scheduledDegree (Nat.clog 2 n) ≤ scheduledPointCount (Nat.clog 2 n) := by\n  have ht := tendsto_clog_two_atTop.comp tendsto_clog_two_atTop\n  filter_upwards [ht.eventually (eventually_ge_atTop 64)] with n hn\n  exact scheduled_parameter_ranges hn\n\n/-- The nonnegative numerator of the actual centered interval formula. -/\ntheorem interval_numerator_nonnegative {r Q R : ℕ} (hr : 2 ≤ r) (hQR : 6 * R ≤ Q) :\n    r * (R - 1) ≤ Q * (r - 1) := by\n  have hs : r ≤ 2 * (r - 1) := by omega\n  have h1 := Nat.mul_le_mul_right Q hs\n  have h2 := Nat.mul_le_mul_right r hQR\n  have h3 := Nat.mul_le_mul_left r (Nat.sub_le R 1)\n  nlinarith\n\n/-- Centered interval start; the preceding lemma makes natural subtraction\nidentical to the signed numerator used by Python on accepted ranges. -/\ndef intervalStart (r Q R : ℕ) : ℕ :=\n  (Q * (r - 1) - r * (R - 1)) / (2 * r)\n\n/-- The interval is contained in 0,...,Q under the actual range tests. -/\ntheorem interval_contained {r Q R : ℕ} (hQR : 6 * R ≤ Q) :\n    intervalStart r Q R + R ≤ Q + 1 := by\n  have hsmall : Q ≤ 2 * (Q + 1 - R) := by omega\n  have hm := Nat.mul_le_mul_right r hsmall\n  have hnum : Q * (r - 1) - r * (R - 1) ≤ (2 * r) * (Q + 1 - R) := by\n    have hsub := Nat.sub_le (Q * (r - 1)) (r * (R - 1))\n    have hmul := Nat.mul_le_mul_left Q (Nat.sub_le r 1)\n    nlinarith\n  have hd := Nat.div_le_of_le_mul hnum\n  change intervalStart r Q R ≤ Q + 1 - R at hd\n  omega\n\n/-- The exact scheduled interval passes its containment check eventually. -/\ntheorem eventually_scheduled_interval_contained :\n    ∀ᶠ n : ℕ in atTop,\n      intervalStart (scheduledGroupCount (Nat.clog 2 n))\n        (scheduledPointCount (Nat.clog 2 n)) (scheduledDegree (Nat.clog 2 n)) +\n        scheduledDegree (Nat.clog 2 n) ≤ scheduledPointCount (Nat.clog 2 n) + 1 := by\n  filter_upwards [eventually_scheduled_parameter_ranges] with n hn\n  exact interval_contained hn.2.2\n\n/-- Combined eventual acceptance of all displayed numerical schedule checks\nexcept the binomial-tail test. The arity grows as n^(3/4); no fixed-width or\npolylogarithmic-arity premise is used. -/\ntheorem eventually_non_tail_schedule_checks (C : ℝ) (hC : 0 ≤ C) :\n    ∀ᶠ n : ℕ in atTop, ∀ w : ℕ,\n      (w : ℝ) ≤ C * (n : ℝ) ^ (3 / 4 : ℝ) →\n      2 ≤ scheduledGroupCount (Nat.clog 2 n) ∧\n      32 ≤ scheduledDegree (Nat.clog 2 n) ∧\n      6 * scheduledDegree (Nat.clog 2 n) ≤ scheduledPointCount (Nat.clog 2 n) ∧\n      scheduledDegree (Nat.clog 2 n) < scheduledPointCount (Nat.clog 2 n) ∧\n      2 ≤ scheduledGroupCount (Nat.clog 2 n) * Nat.clog 2 n ∧\n      2 * (2 + w) * scheduledDimension n ^ 2 ≤ 2 * n ∧\n      2 * scheduledPointCount (Nat.clog 2 n) *\n        scheduledGroupCount (Nat.clog 2 n) ^ 2 ≤ n ∧\n      intervalStart (scheduledGroupCount (Nat.clog 2 n))\n        (scheduledPointCount (Nat.clog 2 n)) (scheduledDegree (Nat.clog 2 n)) +\n        scheduledDegree (Nat.clog 2 n) ≤ scheduledPointCount (Nat.clog 2 n) + 1 := by\n  filter_upwards [eventually_scheduled_parameter_ranges,\n    eventually_scheduled_incidence_balance C hC,\n    eventually_gt_atTop (2 ^ 16 : ℕ)] with n hr hi hn w hw\n  have hn1 : 1 < n := by omega\n  have hlog : 1 ≤ Nat.clog 2 n := Nat.clog_pos (by decide) hn1\n  have hden : 2 ≤ scheduledGroupCount (Nat.clog 2 n) * Nat.clog 2 n := by\n    simpa using Nat.mul_le_mul hr.1 hlog\n  refine ⟨hr.1, hr.2.1, hr.2.2, ?_, hden, hi w hw,\n    scheduled_group_balance hn, interval_contained hr.2.2⟩\n  omega\n\nend RiemannGaussian.SemiprimeCounterRate\n","RiemannGaussian.SemiprimeD1BinaryFactorExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PhysicalPublicSearch\nimport RiemannGaussian.SemiprimeD1PublicOperandBits\nimport RiemannGaussian.SemiprimeD1FactorValidationBits\n\n/-! # Closed binary-output semiprime factor execution\nAll count queries acquire their own original root and execute the physical\nrecursive counter. Operand construction uses original selected-label scans and\nBoolean radix assembly; proper-divisor validation and cofactor recovery use\nBoolean comparison and restoring division. The result contains literal factor\nbytes. Query, physical arithmetic and native metadata reports remain distinct;\nno complete primitive-machine runtime is asserted by this module.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1BinaryFactorExecution\nopen SemiprimePublicAcquiredExecution SemiprimeBitArithmetic SemiprimeBitDivision\nopen SemiprimePublicAcquiredExecution SemiprimeBitPrimeScan\nattribute [local irreducible] SemiprimeD1PhysicalPublicSearch.search\n  SemiprimeD1PhysicalPublicCounter.search SemiprimeD1PublicCounter.search\n  SemiprimeD1PublicOperandBits.run SemiprimeD1FactorValidationBits.run\n  SemiprimePublicAcquiredExecution.decodeOperand\n\n/-- Literal factor bytes and every retained contribution of this executed path. -/\nstructure Run where\n  /-- Successful ordinary factor pair in little-endian binary words. -/\n  factors : Option (List Bool × List Bool)\n  /-- Actual original-prefix count queries executed by the search. -/\n  queries : ℕ\n  /-- All actual original root acquisition and physical recursive reports. -/\n  queryWork : ℕ\n  /-- Actual input zero test, radix shift/add and final validation/division. -/\n  arithmeticClock : ℕ\n  /-- Typed constructor/index/label/control reports, requiring host lowering. -/\n  metadataWork : ℕ\n\n/-- Original binary input is the only input. No acquired count, table, mode,\ncoefficient, word getter, decoder result or factor answer is supplied. -/\ndef run (input : List Bool) : Run :=\n  let initial := nonzeroBits input\n  if hz : initial.nonzero=true then\n    let N := bitValue input\n    let hN : 0 < N := (nonzeroBits_correct input).mp hz\n    let queried := SemiprimeD1PhysicalPublicSearch.search N hN\n    match queried.result.values with\n    | none => ⟨none,queried.result.queries,queried.queryWork,initial.clock+3,\n      queried.metadataWork+10*(wireCount N+input.length+1)⟩\n    | some values =>\n      let operand := SemiprimeD1PublicOperandBits.run N values 0\n      let checked := SemiprimeD1FactorValidationBits.run input operand.bits\n      let answer := if checked.valid then some (operand.bits,checked.cofactor) else none\n      ⟨answer,queried.result.queries,queried.queryWork,\n        initial.clock+operand.arithmeticClock+checked.clock+7,\n        queried.metadataWork+operand.metadataWork+10*(wireCount N+input.length+values.length+1)⟩\n  else ⟨none,0,0,initial.clock+3,10*(input.length+1)⟩\n\n/-- Every successful byte result is a true ordinary factor pair on every input. -/\ntheorem run_sound (input left right : List Bool) (h : (run input).factors=some (left,right)) :\n    bitValue left*bitValue right=bitValue input ∧ 2 ≤ bitValue left ∧ 2 ≤ bitValue right := by\n  dsimp only [run] at h\n  split at h\n  · split at h\n    · cases h\n    · dsimp only at h\n      split at h\n      · cases h\n        exact SemiprimeD1FactorValidationBits.run_factor_pair _ _ (by assumption)\n      · cases h\n  · cases h\n\n/-- Closed search completeness and ordinary decoded factors, derived from the\nexact actual original-prefix counter without any count supplier at execution. -/\ntheorem selected_complete (N p q : ℕ) (hN : 0 < N) (hp : p.Prime) (hq : q.Prime)\n    (hsem : N=p*q) :\n    ∃ values,(SemiprimeD1PhysicalPublicSearch.search N hN).result.values=some values ∧\n      2 ≤ decodeOperand N values 0 ∧ 2 ≤ decodeOperand N values 1 ∧\n        decodeOperand N values 0*decodeOperand N values 1=N := by\n  have hc := SemiprimeD1PublicCorrectness.prefixCount_exact N p q hN hp hq hsem\n  obtain ⟨values,hvalues⟩ := SemiprimeD1PublicCountConsequences.search_exists N p q hN hp hq hsem hc\n  have he : (SemiprimeD1PhysicalPublicSearch.search N hN).result.values=\n      (SemiprimeD1PublicCounter.search N hN).values :=\n    congrArg SemiprimeCountRecovery.SearchResult.values\n      ((SemiprimeD1PhysicalPublicSearch.search_spec N hN).trans\n        (SemiprimeD1PhysicalPublicCounter.search_eq_original N hN))\n  exact ⟨values,he.trans hvalues,\n    SemiprimeD1PublicCountConsequences.selected_factor_pair N hN hc values hvalues⟩\n\n/-- Every semiprime, including a repeated prime, produces an entire actual\nbinary factor pair. All word/count/search/carry/cofactor semantics are closed. -/\ntheorem run_complete (input : List Bool) (p q : ℕ) (hp : p.Prime) (hq : q.Prime)\n    (hsem : bitValue input=p*q) :\n    ∃ left right,(run input).factors=some (left,right) ∧\n      bitValue left*bitValue right=bitValue input ∧\n      2 ≤ bitValue left ∧ 2 ≤ bitValue right ∧ (bitValue left=p ∨ bitValue left=q) := by\n  have hN : 0 < bitValue input := by rw [hsem];exact Nat.mul_pos hp.pos hq.pos\n  have hz := (nonzeroBits_correct input).mpr hN\n  obtain ⟨values,hvalues,hl,hr,hprod⟩ := selected_complete (bitValue input) p q hN hp hq hsem\n  let operand := SemiprimeD1PublicOperandBits.run (bitValue input) values 0\n  have hd : bitValue operand.bits=decodeOperand (bitValue input) values 0 :=\n    SemiprimeD1PublicOperandBits.run_value _ _ _\n  have hlt : bitValue operand.bits < bitValue input := by rw [hd];nlinarith\n  have hdvd : bitValue operand.bits ∣ bitValue input := by\n    rw [hd]\n    exact ⟨decodeOperand (bitValue input) values 1,hprod.symm⟩\n  have hflag : (SemiprimeD1FactorValidationBits.run input operand.bits).valid=true :=\n    (SemiprimeD1FactorValidationBits.run_valid input operand.bits).mpr\n      ⟨hd.symm ▸ hl,hlt,Nat.mod_eq_zero_of_dvd hdvd⟩\n  have hout : (run input).factors=some\n      (operand.bits,(SemiprimeD1FactorValidationBits.run input operand.bits).cofactor) := by\n    dsimp only [run]\n    rw [dite_eq_left hz,hvalues]\n    exact ite_eq_left hflag\n  have hpair := SemiprimeD1FactorValidationBits.run_factor_pair input operand.bits hflag\n  refine ⟨operand.bits,(SemiprimeD1FactorValidationBits.run input operand.bits).cofactor,\n    hout,hpair.1,hpair.2.1,hpair.2.2,?_⟩\n  exact SemiprimeD1SemiprimePrefix.left_factor_eq p q _ _ hp hq hpair.2.1 hpair.2.2\n    (hpair.1.trans hsem)\n\n/-- The byte-producing execution makes only the same original linear number\nof count queries; validation and cofactor production add none. -/\ntheorem run_queries (input : List Bool) : (run input).queries ≤ wireCount (bitValue input)+1 := by\n  dsimp only [run]\n  split\n  · have hs := SemiprimeD1PhysicalPublicSearch.search_queries (bitValue input)\n      ((nonzeroBits_correct input).mp (by assumption))\n    split <;> exact hs\n  · dsimp only\n    omega\n\nend RiemannGaussian.SemiprimeD1BinaryFactorExecution\n","RiemannGaussian.SemiprimeD1BooleanFactorCatalogueIndicesOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BooleanFactorCatalogueIndicesBounds\n/-! # Original numeric factor ports and exact binary-to-unary scope bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1BooleanFactorCatalogueIndicesOriginal\nopen SemiprimeD1BooleanFactorCatalogueIndices SemiprimeD1BooleanFactorCatalogueIndicesBounds\nopen SemiprimePublicAcquiredExecution (factorCount indexedArity)\nopen SemiprimeD1StackOwnerFibreOriginal (enumeration scopeWord)\nopen SemiprimeD1RootTensorTables (Port factorNode)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Original global occurrence ordinal, in factor-major/local-slot source order. -/\ndef portOrdinal (N : Nat) (p : Port N) : Nat :=((enumeration N).equivFin.symm p).val\n/-- Original ordered factor port list expressed in the physical numeric occurrence domain. -/\ndef numericPorts (N : Nat) (f : Fin (factorCount N)) : List Nat :=\n  ((List.finRange (indexedArity N f)).map (Sigma.mk f)).map (portOrdinal N)\n/-- Exact original eager factor-node port list, with unchanged ascending local order. -/\ntheorem numericPorts_factorNode (N : Nat) (hN : 0<N) (f : Fin (factorCount N)) :\n    numericPorts N f=(factorNode N hN f).ports.map (portOrdinal N) := by\n  rw [SemiprimeD1RootTensorTables.factorNode_ports]\n  rfl\n/-- Scope count equals the actual old local table arity, without a supplied degree. -/\ntheorem scope_count_eq (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (f : Fin (factorCount (bitValue bits))) :\n    (scopeWords bits f.val).length=indexedArity (bitValue bits) f := by\n  rw [original_scopes bits hc hN f,List.length_map,SemiprimeD1RootTensorTables.factorNode_degree]\n/-- Numeric port inventory has exactly the old factor table's arity. -/\ntheorem numericPorts_length (N : Nat) (f : Fin (factorCount N)) :\n    (numericPorts N f).length=indexedArity N f := by\n  simp only [numericPorts,List.length_map,List.length_finRange]\n/-- Every numeric original factor port lies in the acquired M-occurrence domain. -/\ntheorem numericPorts_lt (N : Nat) (f : Fin (factorCount N)) :\n    ∀i∈numericPorts N f,i<occurrences N := by\n  intro i hi\n  obtain ⟨p,_,rfl⟩:=List.mem_map.mp hi\n  have h:=((enumeration N).equivFin.symm p).isLt\n  simpa only [portOrdinal,occurrences,SemiprimeD1StackOwnerFibreOriginal.enumeration_length] using h\n/-- Actual selected binary scope values are exactly the original global numeric ports. -/\ntheorem scopeWords_values (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (f : Fin (factorCount (bitValue bits))) :\n    (scopeWords bits f.val).map bitValue=numericPorts (bitValue bits) f := by\n  rw [original_scopes bits hc hN f,numericPorts_factorNode _ hN,List.map_map]\n  apply List.map_congr_left\n  intro p _\n  exact SemiprimeD1StackOwnerFibreOriginal.scopeWord_value _ p\n/-- Every actual scope byte is the original acquired common-width idAt M word. -/\ntheorem scopeWords_idAt (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (f : Fin (factorCount (bitValue bits))) :\n    scopeWords bits f.val=(numericPorts (bitValue bits) f).map\n      (SemiprimeD1OrdinalBankSpec.idAt (occurrences (bitValue bits))) := by\n  rw [original_scopes bits hc hN f,numericPorts_factorNode _ hN,List.map_map]\n  rfl\n/-- The actual paid scope converter emits exactly the frozen original unary port field. -/\ntheorem unary_portTape (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (f : Fin (factorCount (bitValue bits))) :\n    SemiprimeD1StackPortOrdinalStream.result (scopeWords bits f.val)=\n      SemiprimeD1StackVertexReadExecution.portTape (numericPorts (bitValue bits) f) := by\n  rw [scopeWords_idAt bits hc hN f]\n  exact SemiprimeD1StackPortOrdinalStreamOriginal.selected_portTape _ _ (numericPorts_lt _ f)\nend RiemannGaussian.SemiprimeD1BooleanFactorCatalogueIndicesOriginal\n","RiemannGaussian.SemiprimeD1BoundaryCatalogue":"import RiemannGaussian.SemiprimeD1BoundaryAddresses\nimport Mathlib.Algebra.BigOperators.Group.Finset.Powerset\n\n/-! Ordered concrete Boolean catalogues enumerate each incident TRUE subset once. -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryCatalogue\nopen scoped BigOperators\nopen SemiprimeD1BoundaryRecords\nvariable {E R : Type*} [DecidableEq E]\n\n/-- TRUE subset encoded by a concrete ordered address. -/\ndef selected : List E → List Bool → Finset E\n  | [],_ => ∅\n  | _::_,[] => ∅\n  | p::ps,b::bs => if b then insert p (selected ps bs) else selected ps bs\n\ntheorem selected_subset (ports : List E) (bits : List Bool) :\n    selected ports bits ⊆ ports.toFinset := by\n  induction ports generalizing bits with\n  | nil => simp [selected]\n  | cons p ps ih =>\n    cases bits with\n    | nil => simp [selected]\n    | cons b bs =>\n      cases b\n      · simpa only [selected,List.toFinset_cons,Bool.false_eq_true,ite_false] using\n          (ih bs).trans (Finset.subset_insert p ps.toFinset)\n      · simpa only [selected,List.toFinset_cons,ite_true] using\n          Finset.insert_subset_insert p (ih bs)\n\n/-- No address multiplicity is introduced by the executed false-first catalogue. -/\ntheorem assignments_selected_sum [AddCommMonoid R] (ports : List E) (hn : ports.Nodup)\n    (F : Finset E → R) :\n    ((assignments ports.length).value.map (fun bits => F (selected ports bits))).sum =\n      ∑ z ∈ ports.toFinset.powerset, F z := by\n  induction ports generalizing F with\n  | nil => simp [assignments,selected]\n  | cons p ps ih =>\n    have hp := List.nodup_cons.mp hn\n    simp only [List.length_cons,assignments,List.map_append,List.sum_append,List.map_map,\n      Function.comp_def,selected,Bool.false_eq_true,ite_false,ite_true]\n    rw [ih hp.2 F,ih hp.2 (fun z => F (insert p z))]\n    rw [List.toFinset_cons,Finset.sum_powerset_insert (by simpa using hp.1)]\n\n/-- Full finite Boolean assignment syntax is equivalent to the TRUE-subset sum. -/\ntheorem finite_selected_sum [AddCommMonoid R] (ports : List E) (hn : ports.Nodup)\n    (F : Finset E → R) :\n    (∑ bits : Fin ports.length → Bool, F (selected ports (List.ofFn bits))) =\n      ∑ z ∈ ports.toFinset.powerset, F z := by\n  exact (SemiprimeD1BoundaryAddresses.assignments_sum ports.length\n    (fun bits => F (selected ports bits))).symm.trans\n      (assignments_selected_sum ports hn F)\n\ntheorem selected_read (ports : List E) (hn : ports.Nodup) (bits : List Bool)\n    (hl : bits.length = ports.length) (p : E) (hp : p ∈ ports) :\n    decide (p ∈ selected ports bits) = (bits[ports.idxOf p]?).getD false := by\n  induction ports generalizing bits with\n  | nil => simp at hp\n  | cons q qs ih =>\n    have hq := List.nodup_cons.mp hn\n    cases bits with\n    | nil => simp at hl\n    | cons b bs =>\n      have hlen : bs.length = qs.length := Nat.succ.inj hl\n      by_cases he : p = q\n      · subst p\n        have hnsel : q ∉ selected qs bs := fun h => hq.1\n          (List.mem_toFinset.mp (selected_subset qs bs h))\n        cases b <;> simp [selected,hnsel]\n      · have hpt : p ∈ qs := (List.mem_cons.mp hp).resolve_left he\n        have ht := ih hq.2 bs hlen hpt\n        cases b <;> simpa [selected,List.idxOf_cons,he,eq_comm] using ht\n\ntheorem address_eq_iff (ports : List E) (x y : Finset E) :\n    ports.map (fun p => decide (p ∈ x)) = ports.map (fun p => decide (p ∈ y)) ↔\n      x ∩ ports.toFinset = y ∩ ports.toFinset := by\n  constructor\n  · intro h\n    ext p\n    by_cases hp : p ∈ ports\n    · obtain ⟨i,hi,hpi⟩ := List.mem_iff_getElem.mp hp\n      have he := congrArg (fun l : List Bool => l[i]?) h\n      simp only [List.getElem?_map,List.getElem?_eq_getElem hi,Option.map_some,\n        Option.some.injEq,decide_eq_decide] at he\n      simp only [Finset.mem_inter,List.mem_toFinset,hp,and_true]\n      exact hpi ▸ he\n    · simp [hp]\n  · intro h\n    apply List.map_congr_left\n    intro p hp\n    have he := Finset.ext_iff.mp h p\n    simpa only [Finset.mem_inter,List.mem_toFinset,hp,and_true,decide_eq_decide] using he\n\nend RiemannGaussian.SemiprimeD1BoundaryCatalogue\n\nnamespace RiemannGaussian.SemiprimeD1BoundaryCatalogue\nopen scoped BigOperators\n\ntheorem project_selected (source target : List Nat) (hn : source.Nodup)\n    (bits : List Bool) (hl : bits.length = source.length)\n    (ht : ∀ p ∈ target, p ∈ source) :\n    (SemiprimeD1BoundaryRecords.project bits source target).value =\n      target.map (fun p => decide (p ∈ selected source bits)) := by\n  rw [SemiprimeD1BoundaryRecordsLookup.project_value]\n  apply List.map_congr_left\n  intro p hp\n  exact (selected_read source hn bits hl p (ht p hp)).symm\n\n/-- Interpret original natural-number occurrence identifiers as finite edges. -/\ndef lift (m : Nat) (s : Finset Nat) : Finset (Fin m) :=\n  Finset.univ.filter (fun e => e.val ∈ s)\n\n@[simp] theorem mem_lift (m : Nat) (s : Finset Nat) (e : Fin m) :\n    e ∈ lift m s ↔ e.val ∈ s := by simp [lift]\n\ntheorem lift_image (m : Nat) (s : Finset (Fin m)) : lift m (s.image Fin.val) = s := by\n  ext e\n  simp only [mem_lift,Finset.mem_image,Fin.val_inj,exists_eq_right]\n\ntheorem image_lift (m : Nat) (s : Finset Nat) (h : ∀ p ∈ s, p < m) :\n    (lift m s).image Fin.val = s := by\n  ext p\n  simp only [Finset.mem_image,mem_lift]\n  constructor\n  · rintro ⟨e,he,rfl⟩\n    exact he\n  · intro hp\n    exact ⟨⟨p,h p hp⟩,hp,rfl⟩\n\ntheorem lift_inter (m : Nat) (x y : Finset Nat) :\n    lift m (x ∩ y) = lift m x ∩ lift m y := by\n  ext e\n  simp\n\ntheorem lift_eq_iff (m : Nat) (x y : Finset Nat)\n    (hx : ∀ p ∈ x, p < m) (hy : ∀ p ∈ y, p < m) :\n    lift m x = lift m y ↔ x = y := by\n  constructor\n  · intro h\n    have he := congrArg (Finset.image Fin.val) h\n    simpa only [image_lift m x hx,image_lift m y hy] using he\n  · rintro rfl\n    rfl\n\ntheorem sum_lift_powerset {R : Type*} [AddCommMonoid R] (m : Nat) (s : Finset Nat)\n    (h : ∀ p ∈ s, p < m) (F : Finset (Fin m) → R) :\n    (∑ z ∈ s.powerset, F (lift m z)) = ∑ z ∈ (lift m s).powerset, F z := by\n  classical\n  apply Finset.sum_bij (fun z _ => lift m z)\n  · intro z hz\n    apply Finset.mem_powerset.mpr\n    intro e he\n    exact (mem_lift m s e).mpr (Finset.mem_powerset.mp hz ((mem_lift m z e).mp he))\n  · intro z hz y hy he\n    have hz' := image_lift m z (fun p hp => h p (Finset.mem_powerset.mp hz hp))\n    have hy' := image_lift m y (fun p hp => h p (Finset.mem_powerset.mp hy hp))\n    rw [←hz',←hy',he]\n  · intro z hz\n    refine ⟨z.image Fin.val,?_,lift_image m z⟩\n    apply Finset.mem_powerset.mpr\n    intro p hp\n    obtain ⟨e,he,rfl⟩ := Finset.mem_image.mp hp\n    exact (mem_lift m s e).mp (Finset.mem_powerset.mp hz he)\n  · intro z _\n    rfl\n\ntheorem sum_constrained_lift {R : Type*} [AddCommMonoid R] (m : Nat)\n    (source target : Finset Nat) (hs : ∀ p ∈ source, p < m) (ht : ∀ p ∈ target, p < m)\n    (x : Finset (Fin m)) (F : Finset (Fin m) → R) :\n    (∑ z ∈ source.powerset, if z ∩ target = x.image Fin.val ∩ target then F (lift m z) else 0) =\n      ∑ z ∈ (lift m source).powerset,\n        if z ∩ lift m target = x ∩ lift m target then F z else 0 := by\n  classical\n  have hcond (z : Finset Nat) : (z ∩ target = x.image Fin.val ∩ target) ↔\n      (lift m z ∩ lift m target = x ∩ lift m target) := by\n    have hh := (lift_eq_iff m (z ∩ target) (x.image Fin.val ∩ target)\n      (fun p hp => ht p (Finset.mem_inter.mp hp).2)\n      (fun p hp => ht p (Finset.mem_inter.mp hp).2)).symm\n    rw [lift_inter,lift_inter,lift_image m x] at hh\n    exact hh\n  simp_rw [hcond]\n  exact sum_lift_powerset m source hs (fun z =>\n    if z ∩ lift m target = x ∩ lift m target then F z else 0)\n\nend RiemannGaussian.SemiprimeD1BoundaryCatalogue\n","RiemannGaussian.SemiprimeD1BoundaryCheckedPolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryLeafOriginalRate\n\n/-! # Actual checked boundary leaf report, including paid validation -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryCheckedPolynomial\nopen SemiprimeD1BoundaryLeaf\nopen SemiprimeD1BoundaryLeafPolynomial\nopen SemiprimeD1BoundaryLeafOriginalRate\nopen SemiprimeD1JetAxes (Context)\nopen SemiprimeReportPolynomialGrowth\nopen SemiprimeD1PackingReady SemiprimeD1OriginalStateResources\nopen SemiprimeD1OriginalEnvelopeRate SemiprimeD1OriginalScalarResources\n\n/-- Metadata traversed by the actual layout and payload checker. -/\ndef metadata (ctx : Context) (V M : Nat) : Nat := V+M+V*M+ctx.axes.sum+ctx.precision+2\n\n/-- Fixed complete checked-leaf factor, including all validation work. -/\ndef checkedBudget (ctx : Context) (V M : Nat) : Nat :=\n  closedBudget ctx V M+(metadata ctx V M+1)^6+\n    20*(inputFactor ctx V M+1)*(metadata ctx V M+1)^2+3\n\n/-- Exact checked source uses its accepting branch on canonical original data. -/\ntheorem checked_clock (ctx : Context) (net : Network)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net)\n    (hg : SemiprimeD1LeafCounter.Good ctx (SemiprimeD1TensorNetwork.vertices net)) :\n    (checked ctx net).clock≤ checkedBudget ctx\n      (SemiprimeD1BoundaryPlan.graph net).vertices (SemiprimeD1BoundaryPlan.graph net).edges.length*\n      (2^(SemiprimeD1BoundaryPlan.acquire (SemiprimeD1BoundaryPlan.graph net)).width+1) := by\n  let g:=SemiprimeD1BoundaryPlan.graph net\n  let vs:=SemiprimeD1TensorNetwork.vertices net\n  let N:=2^(SemiprimeD1BoundaryPlan.acquire g).width+1\n  have hr:=run_clock_polynomial ctx net hw hg\n  have hi:=inputMass_le ctx net hw hg\n  have hscope:=sum_le vs (fun v => v.ports.length) g.edges.length\n    (fun v hv => ports_length _ _ (original_vertex_ports net hw v hv))\n  have hmeta : vs.length+SemiprimeD1TensorNetwork.edgeCount net+\n      (vs.map (fun v => v.ports.length)).sum+ctx.axes.sum+ctx.precision+2≤ metadata ctx g.vertices g.edges.length := by\n    rw [←SemiprimeD1BoundaryPlan.graph_edges_length net]\n    change vs.length+g.edges.length+_+ctx.axes.sum+ctx.precision+2≤_\n    unfold metadata\n    change vs.length+g.edges.length+_+ctx.axes.sum+ctx.precision+2≤\n      vs.length+g.edges.length+vs.length*g.edges.length+ctx.axes.sum+ctx.precision+2\n    omega\n  have hN : 1≤ N := Nat.le_add_left _ _\n  have hi' : inputMass vs+1≤(inputFactor ctx g.vertices g.edges.length+1)*N := by\n    change inputMass vs≤ inputFactor ctx g.vertices g.edges.length*N at hi\n    nlinarith only [hi,hN]\n  have hv : (validate ctx net).clock≤\n      (metadata ctx g.vertices g.edges.length+1)^6+\n        20*((inputFactor ctx g.vertices g.edges.length+1)*N)*(metadata ctx g.vertices g.edges.length+1)^2 := by\n    change (vs.length+SemiprimeD1TensorNetwork.edgeCount net+\n      (vs.map (fun v => v.ports.length)).sum+ctx.axes.sum+ctx.precision+2+1)^6+\n      20*(inputMass vs+1)*(vs.length+SemiprimeD1TensorNetwork.edgeCount net+\n      (vs.map (fun v => v.ports.length)).sum+ctx.axes.sum+ctx.precision+2+1)^2≤_\n    exact Nat.add_le_add (Nat.pow_le_pow_left (Nat.add_le_add_right hmeta 1) 6)\n      (Nat.mul_le_mul (Nat.mul_le_mul_left 20 hi')\n        (Nat.pow_le_pow_left (Nat.add_le_add_right hmeta 1) 2))\n  have hbase : (metadata ctx g.vertices g.edges.length+1)^6≤\n      (metadata ctx g.vertices g.edges.length+1)^6*N := Nat.le_mul_of_pos_right _ (by omega)\n  have hpad : 3≤3*N := by omega\n  have hvalid : (validate ctx net).value=true := (validate_correct ctx net).mpr ⟨hw,hg⟩\n  simp only [checked,hvalid,ite_true]\n  unfold checkedBudget\n  change _≤(closedBudget ctx g.vertices g.edges.length+(metadata ctx g.vertices g.edges.length+1)^6+\n    20*(inputFactor ctx g.vertices g.edges.length+1)*(metadata ctx g.vertices g.edges.length+1)^2+3)*N\n  change (run ctx net).clock≤ closedBudget ctx g.vertices g.edges.length*N at hr\n  nlinarith only [hr,hv,hbase,hpad]\n\n/-- One-variable validation polynomial with a separately paid axis inventory. -/\ndef checkedEnvelope (S : Nat) : Nat  := SemiprimeD1BoundaryLeafOriginalRate.envelope S+(3*S+2*S*S+3)^6+\n  20*(inputFactor (capContext S) S S+1)*(3*S+2*S*S+3)^2+3\n\n/-- Complete checked-leaf factor fits the same actual scalar-field caps. -/\ntheorem checkedBudget_le (ctx : Context) (V M S : Nat)\n    (hV : V≤ S) (hM : M≤ S) (ha : ctx.axes.length≤ S) (hu : ctx.axes.sum≤ S*S)\n    (hr : ctx.rank≤ S) (hp : ctx.precision≤ S) : checkedBudget ctx V M≤ checkedEnvelope S := by\n  have hb:=budget_le_envelope ctx V M S hV hM ha hu hr hp\n  have hm : metadata ctx V M+1≤3*S+2*S*S+3 := by\n    unfold metadata\n    have hmul:=Nat.mul_le_mul hV hM\n    nlinarith only [hV,hM,hu,hp,hmul]\n  have hi : inputFactor ctx V M≤ inputFactor (capContext S) S S := by\n    unfold inputFactor\n    simp only [capContext,SemiprimeD1JetAxes.Context.rank,List.prod_append,List.prod_replicate,List.prod_cons,List.prod_nil,one_pow,Nat.one_mul,Nat.mul_one]\n    have hr':ctx.axes.prod≤ S+1 := hr.trans (Nat.le_succ _)\n    gcongr\n  unfold checkedBudget checkedEnvelope\n  gcongr\n\n/-- Validation adds only fixed arithmetic, hence has fixed monomial witnesses. -/\ntheorem checkedEnvelope_monomial : Bound checkedEnvelope := by\n  unfold checkedEnvelope\n  apply add_bound\n  · apply add_bound\n    · apply add_bound\n      · exact envelope_monomial\n      · boundArithmetic\n    · simp only [inputFactor,capContext,SemiprimeD1JetAxes.Context.rank,List.prod_append,List.prod_replicate,\n        List.prod_cons,List.prod_nil,one_pow,Nat.one_mul,Nat.mul_one]\n      boundArithmetic\n  · exact constant_bound 3\n\n/-- Full original family resources bound paid validation and contraction together. -/\ntheorem checked_original_budget_le (ctx : Context) (V M s : Nat) (hl : 1000≤ logarithm s)\n    (hV : V≤5*s) (hM : M≤ s+1) (ha : ctx.axes.length≤ logarithm s+1)\n    (hq : ∀q∈ctx.axes,q≤4*s) (hr : ctx.rank≤ rankCap s) (hp : ctx.precision≤ precisionCap s) :\n    checkedBudget ctx V M≤ checkedEnvelope (scalar s+1) := by\n  obtain ⟨hs,hv,hlength⟩:=base_caps s hl\n  have ha':ctx.axes.length≤ scalar s := ha.trans hlength\n  have hq':∀q∈ctx.axes,q≤ scalar s := by intro q hqmem; exact (hq q hqmem).trans (by omega)\n  have hu:ctx.axes.sum≤(scalar s+1)*(scalar s+1) :=\n    (axes_sum_le ctx.axes (scalar s) hq').trans\n      (Nat.mul_le_mul (ha'.trans (Nat.le_succ _)) (Nat.le_succ _))\n  exact checkedBudget_le ctx V M (scalar s+1) (by omega) (by omega) (by omega) hu\n    ((hr.trans (rankCap_le s hl)).trans (Nat.le_succ _))\n    ((hp.trans (precisionCap_le s hl)).trans (Nat.le_succ _))\n\n/-- Uniform fixed original-scale reserve for the actual checked recursion leaf.\nValidation is included. The old full-enumeration leaf allowance is used only as\nan upper envelope for this new source's independently proved native report. -/\ntheorem checked_original_polynomial : ∃B k : Nat, 0<B ∧\n    ∀ (s : Nat) (ctx : Context) (net : Network), 1000≤ logarithm s →\n    SemiprimeD1TensorNetwork.WellFormed net →\n    SemiprimeD1LeafCounter.Good ctx (SemiprimeD1TensorNetwork.vertices net) →\n    (SemiprimeD1BoundaryPlan.graph net).vertices≤5*s →\n    (SemiprimeD1BoundaryPlan.graph net).edges.length≤ s+1 →\n    (SemiprimeD1BoundaryPlan.graph net).edges.length≤ SemiprimeD1Schedule.leafSize s (logarithm s) →\n    ctx.axes.length≤ logarithm s+1 → (∀q∈ctx.axes,q≤4*s) →\n    ctx.rank≤ rankCap s → ctx.precision≤ precisionCap s →\n    (checked ctx net).clock≤ B*(scalar s+1)^k*2^(SemiprimeD1Schedule.leafSize s (logarithm s)) := by\n  obtain ⟨C,k,hmono⟩:=checkedEnvelope_monomial\n  refine ⟨2*C*2^k+1,k,by omega,?_⟩\n  intro s ctx net hl hw hg hV hM hleaf ha hq hr hp\n  let g:=SemiprimeD1BoundaryPlan.graph net\n  let L:=SemiprimeD1Schedule.leafSize s (logarithm s)\n  have hb:=(checked_original_budget_le ctx g.vertices g.edges.length s hl hV hM ha hq hr hp).trans\n    (hmono (scalar s+1))\n  have hwidth : (SemiprimeD1BoundaryPlan.acquire g).width≤ L := (plan_width_le g).trans hleaf\n  have hn : 2^(SemiprimeD1BoundaryPlan.acquire g).width+1≤2*2^L := by\n    have hh:=Nat.pow_le_pow_right (by omega : 0<(2:Nat)) hwidth\n    have ho : 1≤(2:Nat)^L := Nat.one_le_two_pow\n    omega\n  have hs : scalar s+2≤2*(scalar s+1) := by omega\n  calc\n    _ ≤ (C*(scalar s+2)^k)*(2*2^L) := (checked_clock ctx net hw hg).trans (Nat.mul_le_mul hb hn)\n    _ ≤ (C*(2*(scalar s+1))^k)*(2*2^L) := by gcongr\n    _ = (2*C*2^k)*(scalar s+1)^k*2^L := by rw [mul_pow]; ring\n    _ ≤ _ := by gcongr; omega\n\nend RiemannGaussian.SemiprimeD1BoundaryCheckedPolynomial\n","RiemannGaussian.SemiprimeD1BoundaryInitialVariance":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryConditionalAverage\n\n/-! # Proof-only complete catalogue formula for the initial potential\nThe executable algorithm still generates only local endpoint samples. The\ncomplete assignment catalogue occurs exclusively in the following identities.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1BoundaryInitialVariance\nopen SemiprimeD1BoundaryPlan SemiprimeD1BoundaryConditionalAverage\n\n/-- Repeated exact marginals recover the proof-only complete finite catalogue. -/\ntheorem catalogue_marginal (k n : Nat) (f : List Nat → Int) (hf : Averages k f)\n    (fixed : List Nat) :\n    ((colourWords k n).map (fun sample => f (fixed ++ sample))).sum =\n      (k : Int)^n * f fixed := by\n  induction n generalizing fixed with\n  | zero => simp [colourWords]\n  | succ n ih =>\n    have he : ((colourWords k (n + 1)).map (fun sample => f (fixed ++ sample))).sum =\n        ((List.range k).map (fun c => ((colourWords k n).map\n          (fun sample => f ((fixed ++ [c]) ++ sample))).sum)).sum := by\n      simp [colourWords, List.flatMap, List.map_flatten,\n        List.sum_flatten, List.map_map, Function.comp_def, List.append_assoc]\n    rw [he]\n    simp_rw [ih]\n    rw [List.sum_map_mul_left, hf, pow_succ]\n    ring\n\n/-- The initial executed potential is exactly a finite mean of literal squares.\nNo global assignment enumeration is executed by the runtime partitioner. -/\ntheorem initial_catalogue (g : Graph) (k : Nat)\n    (hg : SemiprimeD1BoundaryPotential.Valid g) :\n    (k : Int)^g.vertices * (potential g k []).value =\n      ((colourWords k g.vertices).map (fun colours => ((loads k).map (fun load =>\n        ((k : Int)^2 * (loadValue g colours load : Int) -\n          (meanNumerator g.edges.length k load : Int))^2)).sum)).sum := by\n  have ha : Averages k (fun fixed => (potential g k fixed).value) :=\n    potential_average g k\n  rw [← catalogue_marginal k g.vertices _ ha []]\n  simp only [List.nil_append]\n  apply congrArg List.sum\n  apply List.map_congr_left\n  intro colours hc\n  apply SemiprimeD1BoundaryPotential.potential_fixed\n  have hl := SemiprimeD1BoundaryColourWords.member_length k g.vertices colours hc\n  intro e he\n  have hh := hg e he\n  omega\n\n/-- Complete local words factor exactly at any consecutive coordinate cut. -/\ntheorem colourWords_add (k n m : Nat) :\n    colourWords k (n + m) = (colourWords k n).flatMap (fun xs =>\n      (colourWords k m).map (fun ys => xs ++ ys)) := by\n  induction n with\n  | zero => simp [colourWords]\n  | succ n ih =>\n    simp [Nat.succ_add, colourWords, ih, List.flatMap_assoc, List.flatMap_map,\n      List.map_flatMap, List.map_map, Function.comp_def]\n\n/-- Counts of independent finite catalogue factors multiply, retaining duplicates. -/\ntheorem successes_product {α β : Type} (xs : List α) (ys : List β)\n    (p : α → Bool) (q : β → Bool) :\n    ((xs.flatMap (fun x => ys.map (fun y => (x, y)))).filter\n      (fun xy => p xy.1 && q xy.2)).length =\n      (xs.filter p).length * (ys.filter q).length := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih =>\n    simp only [List.flatMap_cons, List.filter_append, List.length_append, List.filter_cons]\n    have he : ((ys.map (fun y => (x, y))).filter\n        (fun xy => p xy.1 && q xy.2)).length =\n        if p x then (ys.filter q).length else 0 := by\n      rw [List.filter_map]\n      cases hp : p x <;> simp [hp, Function.comp_def]\n    rw [he, ih]\n    cases hp : p x <;> simp [Nat.add_mul, Nat.add_comm]\n\n/-- Exact two-colour event count independent of endpoint names. -/\ndef eventCount (k : Nat) (load : Load) : Nat :=\n  ((colourWords k 2).filter (fun sample =>\n    indicator load (sample.getD 0 0) (sample.getD 1 0))).length\n\n/-- Every nonloop single-edge initial expectation has the same event count. -/\ntheorem single_initial (k a b : Nat) (load : Load) (hab : a ≠ b) :\n    (localExpectation 2 k [] load [(a, b)]).value = eventCount k load := by\n  simp [localExpectation, endpoints, List.eraseDups_cons, hab, Ne.symm hab,\n    readColour, eventCount]\n\n/-- A local edge event count lies between zero and the two-coordinate catalogue. -/\ntheorem eventCount_le (k : Nat) (load : Load) : eventCount k load ≤ k^2 := by\n  unfold eventCount\n  apply Nat.le_trans (List.length_filter_le _ _)\n  exact le_of_eq (colourWords_length k 2)\n\n/-- Exact weighted count for one distinguished value in an occurrence list. -/\ntheorem sum_special (xs : List Nat) (t k : Nat) :\n    ((xs.map (fun a => if a == t then k else 1)).sum) + xs.count t =\n      xs.count t * k + xs.length := by\n  induction xs with\n  | nil => simp\n  | cons a xs ih =>\n    by_cases ha : a = t\n    · subst a\n      simp only [List.map_cons, List.sum_cons, beq_self_eq_true, reduceIte,\n        List.count_cons_self, List.length_cons, Nat.add_mul, one_mul]\n      omega\n    · simp only [List.map_cons, List.sum_cons, beq_eq_false_iff_ne.mpr ha, Bool.false_eq_true,\n        reduceIte, List.count_cons, Nat.add_zero,\n        List.length_cons]\n      omega\n\n/-- A bucket event has exactly the literal unconditional numerator. -/\ntheorem eventCount_bucket (k t : Nat) (ht : t < k) :\n    eventCount k (.bucket t) = 2 * k - 1 := by\n  have hi (a : Nat) :\n      (((List.range k).map (fun b => [a, b])).filter (fun sample =>\n        indicator (.bucket t) (sample.getD 0 0) (sample.getD 1 0))).length =\n      if a == t then k else 1 := by\n    rw [List.filter_map]\n    by_cases ha : a = t\n    · subst a\n      simp [indicator, Function.comp_def]\n    · simp [indicator, Function.comp_def, beq_eq_false_iff_ne.mpr ha, List.filter_beq, List.count_range, ht]\n  have he : colourWords k 2 = (List.range k).flatMap (fun a =>\n      (List.range k).map (fun b => [a, b])) := by\n    simp [colourWords, ← List.map_eq_flatMap, Function.comp_def]\n  unfold eventCount\n  rw [he, List.filter_flatMap, List.length_flatMap]\n  simp_rw [hi]\n  have hh := sum_special (List.range k) t k\n  simp only [List.count_range, ht, reduceIte, List.length_range, one_mul] at hh\n  omega\n\n/-- A disjoint ordered edge pair reads exactly four independent local coordinates. -/\ntheorem pair_initial_disjoint_coordinates (k a b c d : Nat) (load : Load)\n    (hab : a ≠ b) (hac : a ≠ c) (had : a ≠ d)\n    (hbc : b ≠ c) (hbd : b ≠ d) (hcd : c ≠ d) :\n    (localExpectation 4 k [] load [(a, b), (c, d)]).value =\n      ((colourWords k 4).filter (fun sample =>\n        indicator load (sample.getD 0 0) (sample.getD 1 0) &&\n          indicator load (sample.getD 2 0) (sample.getD 3 0))).length := by\n  simp [localExpectation, endpoints, List.eraseDups_cons, readColour,\n    hab, hac, had, hbc, hbd, hcd, Ne.symm hab, Ne.symm hac, Ne.symm had,\n    Ne.symm hbc, Ne.symm hbd, Ne.symm hcd]\n\n/-- Constant successful weights sum exactly over a filtered occurrence list. -/\ntheorem sum_success_weight {α : Type} (xs : List α) (p : α → Bool) (w : Nat) :\n    ((xs.map (fun x => if p x then w else 0)).sum) = (xs.filter p).length * w := by\n  induction xs with\n  | nil => simp\n  | cons x xs ih =>\n    cases hp : p x <;> simp [hp, ih, Nat.add_mul, Nat.add_comm]\n\n/-- Independence of the two consecutive two-colour blocks in the local catalogue. -/\ntheorem fourCount_eq_square (k : Nat) (load : Load) :\n    ((colourWords k 4).filter (fun sample =>\n      indicator load (sample.getD 0 0) (sample.getD 1 0) &&\n        indicator load (sample.getD 2 0) (sample.getD 3 0))).length =\n      eventCount k load * eventCount k load := by\n  rw [show 4 = 2 + 2 from rfl, colourWords_add, List.filter_flatMap, List.length_flatMap]\n  have hi (xs : List Nat) (hx : xs ∈ colourWords k 2) :\n      (((colourWords k 2).map (fun ys => xs ++ ys)).filter (fun sample =>\n        indicator load (sample.getD 0 0) (sample.getD 1 0) &&\n          indicator load (sample.getD 2 0) (sample.getD 3 0))).length =\n      if indicator load (xs.getD 0 0) (xs.getD 1 0) then eventCount k load else 0 := by\n    have hl := SemiprimeD1BoundaryColourWords.member_length k 2 xs hx\n    rw [List.filter_map, List.length_map]\n    have he : (fun ys =>\n        indicator load ((xs ++ ys).getD 0 0) ((xs ++ ys).getD 1 0) &&\n          indicator load ((xs ++ ys).getD 2 0) ((xs ++ ys).getD 3 0)) =\n        (fun ys => indicator load (xs.getD 0 0) (xs.getD 1 0) &&\n          indicator load (ys.getD 0 0) (ys.getD 1 0)) := by\n      funext ys\n      rw [List.getD_append _ _ _ _ (by omega), List.getD_append _ _ _ _ (by omega),\n        List.getD_append_right _ _ _ _ (by omega),\n        List.getD_append_right _ _ _ _ (by omega)]\n      simp only [hl]\n    change ((colourWords k 2).filter (fun ys =>\n      indicator load ((xs ++ ys).getD 0 0) ((xs ++ ys).getD 1 0) &&\n        indicator load ((xs ++ ys).getD 2 0) ((xs ++ ys).getD 3 0))).length = _\n    rw [he]\n    cases hb : indicator load (xs.getD 0 0) (xs.getD 1 0) <;> simp [eventCount]\n  have he : (colourWords k 2).map (fun xs =>\n      (((colourWords k 2).map (fun ys => xs ++ ys)).filter (fun sample =>\n        indicator load (sample.getD 0 0) (sample.getD 1 0) &&\n          indicator load (sample.getD 2 0) (sample.getD 3 0))).length) =\n      (colourWords k 2).map (fun xs =>\n        if indicator load (xs.getD 0 0) (xs.getD 1 0) then eventCount k load else 0) := by\n    apply List.map_congr_left\n    exact hi\n  rw [he, sum_success_weight]\n  rfl\n\n/-- Disjoint-edge covariance cancels exactly in the executed initial potential. -/\ntheorem pair_initial_disjoint (k a b c d : Nat) (load : Load)\n    (hab : a ≠ b) (hac : a ≠ c) (had : a ≠ d)\n    (hbc : b ≠ c) (hbd : b ≠ d) (hcd : c ≠ d) :\n    (localExpectation 4 k [] load [(a, b), (c, d)]).value =\n      eventCount k load * eventCount k load := by\n  rw [pair_initial_disjoint_coordinates k a b c d load hab hac had hbc hbd hcd,\n    fourCount_eq_square]\n\n/-- A pair event is pointwise dominated by its first single event. -/\ntheorem pair_initial_le_single (g : Graph) (k : Nat) (load : Load) (e f : Nat × Nat)\n    (hk : 0 < k) (he : e ∈ g.edges) (hf : f ∈ g.edges)\n    (hg : SemiprimeD1BoundaryPotential.Valid g) :\n    ((localExpectation 4 k [] load [e, f]).value : Int) ≤\n      (k : Int)^2 * ((localExpectation 2 k [] load [e]).value : Int) := by\n  let term : List Nat → Int := fun fixed =>\n    (k : Int)^2 * ((localExpectation 2 k fixed load [e]).value : Int) -\n      ((localExpectation 4 k fixed load [e, f]).value : Int)\n  have ha : Averages k term := averages_sub k _ _\n    (averages_mul k _ _ (averages_single k load e)) (averages_pair k load e f)\n  have hm := catalogue_marginal k g.vertices term ha []\n  have hn : 0 ≤ ((colourWords k g.vertices).map (fun sample => term ([] ++ sample))).sum := by\n    apply List.sum_nonneg\n    intro x hx\n    obtain ⟨colours, hc, rfl⟩ := List.mem_map.mp hx\n    have hl := SemiprimeD1BoundaryColourWords.member_length k g.vertices colours hc\n    have hge := hg e he\n    have hgf := hg f hf\n    have hle : e.1 < colours.length ∧ e.2 < colours.length := by omega\n    have hlf : f.1 < colours.length ∧ f.2 < colours.length := by omega\n    dsimp only [term]\n    simp only [List.nil_append,\n      SemiprimeD1BoundaryPotential.single_fixed k colours load e hle,\n      SemiprimeD1BoundaryPotential.pair_fixed k colours load e f hle hlf,\n      SemiprimeD1BoundaryPotential.atom]\n    split_ifs <;> simp_all [pow_succ]\n    nlinarith [sq_nonneg (k : Int)]\n  rw [hm] at hn\n  have hp : (0 : Int) < (k : Int)^g.vertices := pow_pos (by exact_mod_cast hk) _\n  dsimp only [term] at hn\n  nlinarith\n\n/-- Each ordered edge covariance is bounded above by one quarter of the scale. -/\ntheorem covariance_quarter (g : Graph) (k : Nat) (load : Load) (e f : Nat × Nat)\n    (hk : 0 < k) (he : e ∈ g.edges) (hf : f ∈ g.edges)\n    (hg : SemiprimeD1BoundaryPotential.Valid g) :\n    4 * (((localExpectation 4 k [] load [e, f]).value : Int) -\n      (eventCount k load : Int)^2) ≤ (k : Int)^4 := by\n  have hb := pair_initial_le_single g k load e f hk he hf hg\n  rw [single_initial k e.1 e.2 load (hg e he).2.2] at hb\n  nlinarith [sq_nonneg ((k : Int)^2 - 2 * (eventCount k load : Int))]\n\nend RiemannGaussian.SemiprimeD1BoundaryInitialVariance\n","RiemannGaussian.SemiprimeD1BoundaryLeafOriginalReachRate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryCheckedOriginalRate\nimport RiemannGaussian.SemiprimeD1BoundaryPartitionReachRate\n\n/-! # Half exponent of actual original-reachable checked boundary leaves -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryLeafOriginalReachRate\nopen Filter SemiprimeD1PackingReady SemiprimeD1OriginalStateResources\nopen SemiprimeD1RecursiveCallTree SemiprimeD1RecursiveCallState SemiprimeD1RecursiveCallPath\nopen SemiprimeD1RootStateResources SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimePublicAcquiredExecution SemiprimeMacroParameters\n\n/-- Every actually reached stopped checked leaf has the uniform leading half\nexponent. All context, degree, graph and literal table resources come from the\noriginal binary input; no resource inequality is supplied by the caller. -/\ntheorem eventually_original_stopped_half (e : Real) (he : 0<e) :\n    ∀ᶠ ell : Nat in atTop, ∀ (N : Nat) (hN : 0<N), bitLength N=ell →\n    ∀ (fixed : List (Fin (wireCount N) × Bool)) (next : Call),\n    Reach (SemiprimeD1PublicPackingReady.scale ell) (originalCall N hN fixed) next →\n    activeTest (SemiprimeD1PublicPackingReady.scale ell)\n      (logarithm (SemiprimeD1PublicPackingReady.scale ell)) next.depth (edgeCount next.net)=false →\n    ((SemiprimeD1BoundaryLeaf.checked next.ctx next.net).clock:Real)≤\n      (2:Real)^((1/2+e)*((SemiprimeD1PublicPackingReady.scale ell:Real)/\n        Real.sqrt (logarithm (SemiprimeD1PublicPackingReady.scale ell):Real))) := by\n  filter_upwards [eventually_original,\n    scale_tendsto.eventually (SemiprimeD1BoundaryCheckedOriginalRate.eventually_checked_uniform_half e he),\n    scale_tendsto.eventually eventually_reach_invariant,\n    scale_tendsto.eventually SemiprimeD1LeafReady.eventually_rootReady] with ell hres hhalf hinv hready\n  intro N hN hEll fixed next hreach hstop\n  subst ell\n  let s:=SemiprimeD1PublicPackingReady.scale (bitLength N)\n  have hb:=hres N hN rfl fixed next hreach\n  have hroot:=original_shape N hN fixed\n  have hrootM:=root_edges_le_scale N hN fixed\n  have hrootD:=root_global_degree N hN fixed\n  have hi:=hinv (originalCall N hN fixed) next rfl hrootM hroot.2.2.2\n    hroot.1 hroot.2.1 hroot.2.2.1 hrootD hreach\n  have hshape:=reach_shape s (originalCall N hN fixed) next hreach hroot.1 hroot.2.1 hroot.2.2.1\n  have hnot : ¬SemiprimeD1Schedule.Active s (logarithm s) next.depth (edgeCount next.net) := by\n    intro ha\n    have ht:=(activeTest_correct _ _ _ _).mpr ha\n    rw [hstop] at ht\n    exact Bool.false_ne_true ht\n  have hleaf:=SemiprimeD1LeafRate.inactive_leaf s (logarithm s) next.depth (edgeCount next.net)\n    hready hi.2.1 hnot\n  apply hhalf next.ctx next.net hshape.2.1 hshape.2.2\n  · simpa only [SemiprimeD1BoundaryPlan.graph,SemiprimeD1NetworkStateResources.vertices_length] using hb.vertex_count\n  · simpa only [SemiprimeD1BoundaryPlan.graph_edges_length] using hleaf\n  · exact hb.axes_length.le.trans hb.depth\n  · exact hb.axes\n  · exact hb.rank\n  · exact hb.precision\n  · exact hb.degree\n\n/-- Exhausting the actual original logarithmic fuel has the same checked-leaf\nhalf exponent; the schedule itself implies the inactive guard. -/\ntheorem eventually_original_zero_fuel_half (e : Real) (he : 0<e) :\n    ∀ᶠ ell : Nat in atTop, ∀ (N : Nat) (hN : 0<N), bitLength N=ell →\n    ∀ (fixed : List (Fin (wireCount N) × Bool)) (next : Call),\n    Reach (SemiprimeD1PublicPackingReady.scale ell) (originalCall N hN fixed) next →\n    logarithm (SemiprimeD1PublicPackingReady.scale ell)+1≤next.depth+0 →\n    ((SemiprimeD1BoundaryLeaf.checked next.ctx next.net).clock:Real)≤\n      (2:Real)^((1/2+e)*((SemiprimeD1PublicPackingReady.scale ell:Real)/\n        Real.sqrt (logarithm (SemiprimeD1PublicPackingReady.scale ell):Real))) := by\n  filter_upwards [eventually_original_stopped_half e he] with ell hs\n  intro N hN hEll fixed next hreach hf\n  exact hs N hN hEll fixed next hreach\n    (SemiprimeD1RecursiveLeafBounds.zero_fuel_inactive _ next.depth hf (edgeCount next.net))\n\nend RiemannGaussian.SemiprimeD1BoundaryLeafOriginalReachRate\n","RiemannGaussian.SemiprimeD1BoundaryLeafPorts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryLeaf\nimport RiemannGaussian.SemiprimeD1BoundaryRefinement\nimport RiemannGaussian.SemiprimeD1BoundaryIdentity\nimport RiemannGaussian.SemiprimeD1BoundaryChoice\n\n/-! # Literal class and merge port metadata\n\nThe original ordered occurrence list supplies every address. Distinct ordinals\nremain distinct for parallel incidences, and all vertices are retained.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryLeafPorts\nopen SemiprimeD1BoundaryLeaf\nopen SemiprimeD1BoundaryRefinement\n\n/-- The ordinal scan used by both executed class-port filters. -/\ndef selectedIndices {α : Type} (xs : List α) (p : α × Nat → Bool) : List Nat :=\n  ((xs.zipIdx).filter p).map Prod.snd\n\n/-- Selection returns exactly the original address whose predicate succeeds. -/\ntheorem selectedIndices_mem {α : Type} (xs : List α) (p : α × Nat → Bool)\n    (i : Nat) (hi : i < xs.length) :\n    i ∈ selectedIndices xs p ↔ p (xs[i], i) = true := by\n  constructor\n  · intro h\n    obtain ⟨x, hx, he⟩ := List.mem_map.mp h\n    obtain ⟨hm, hp⟩ := List.mem_filter.mp hx\n    have hg := List.mem_zipIdx' hm\n    have hxe : x = (xs[i], i) := by\n      apply Prod.ext\n      · simpa only [he] using hg.2\n      · exact he\n    exact hxe ▸ hp\n  · intro hp\n    apply List.mem_map.mpr\n    refine ⟨(xs[i], i), List.mem_filter.mpr ⟨?_, hp⟩, rfl⟩\n    exact List.mk_mem_zipIdx_iff_getElem?.mpr (List.getElem?_eq_getElem hi)\n\n/-- Every selected ordinal is an actual original occurrence. -/\ntheorem selectedIndices_lt {α : Type} (xs : List α) (p : α × Nat → Bool)\n    (i : Nat) (hi : i ∈ selectedIndices xs p) : i < xs.length := by\n  obtain ⟨x, hx, rfl⟩ := List.mem_map.mp hi\n  exact (List.mem_zipIdx' (List.mem_filter.mp hx).1).1\n\n/-- Filtering never duplicates an original occurrence ordinal. -/\ntheorem selectedIndices_nodup {α : Type} (xs : List α) (p : α × Nat → Bool) :\n    (selectedIndices xs p).Nodup := by\n  exact List.Nodup.sublist (List.Sublist.map Prod.snd List.filter_sublist)\n    (List.nodup_zipIdx_map_snd xs)\n\n/-- The actual finite set of vertices assigned this colour. -/\ndef colourClass (net : Network) (colours : List Nat) (c : Nat) : Finset Nat :=\n  (Finset.range (SemiprimeD1TensorNetwork.vertices net).length).filter\n    (fun v => colours.getD v 0 = c)\n\n/-- Distinct colours give disjoint vertex sets, even when a class is empty. -/\ntheorem colourClass_disjoint (net : Network) (colours : List Nat) (c d : Nat) (h : c ≠ d) :\n    Disjoint (colourClass net colours c) (colourClass net colours d) := by\n  apply Finset.disjoint_left.mpr\n  intro v hc hd\n  exact h ((Finset.mem_filter.mp hc).2.symm.trans (Finset.mem_filter.mp hd).2)\n\n/-- Exact selected-vertex product, indexed by original positions rather than values.\nThus repeated scalar tables and isolated vertices keep their multiplicities. -/\ntheorem classVertices_product {R : Type} [CommMonoid R]\n    (net : Network) (colours : List Nat) (c : Nat) (f : Vertex → R) :\n    ((classVertices (SemiprimeD1TensorNetwork.vertices net) colours c).map f).prod =\n      ∏ i ∈ colourClass net colours c,\n        if hi : i < (SemiprimeD1TensorNetwork.vertices net).length\n          then f ((SemiprimeD1TensorNetwork.vertices net)[i]) else 1 := by\n  classical\n  let vs := SemiprimeD1TensorNetwork.vertices net\n  let pairs := vs.zipIdx.filter (fun x => colours.getD x.2 0 == c)\n  have hnd : pairs.Nodup := by\n    exact (List.Nodup.of_map Prod.snd (List.nodup_zipIdx_map_snd vs)).filter _\n  simp only [classVertices, List.map_map]\n  change (pairs.map (fun x => f x.1)).prod = _\n  rw [←List.prod_toFinset _ hnd]\n  apply Finset.prod_bij (fun x _ => x.2)\n  · intro x hx\n    have hm := List.mem_filter.mp (List.mem_toFinset.mp hx)\n    have hg := List.mem_zipIdx' hm.1\n    exact Finset.mem_filter.mpr ⟨Finset.mem_range.mpr hg.1, beq_iff_eq.mp hm.2⟩\n  · intro x hx y hy he\n    have hxm := (List.mem_filter.mp (List.mem_toFinset.mp hx)).1\n    have hym := (List.mem_filter.mp (List.mem_toFinset.mp hy)).1\n    apply Prod.ext\n    · have hxx := (List.mem_zipIdx' hxm).2\n      have hyy := (List.mem_zipIdx' hym).2\n      rw [hxx, hyy]\n      congr 1\n    · exact he\n  · intro i hi\n    have hv := Finset.mem_range.mp (Finset.mem_filter.mp hi).1\n    have hc := (Finset.mem_filter.mp hi).2\n    refine ⟨(vs[i], i), List.mem_toFinset.mpr ?_, rfl⟩\n    exact List.mem_filter.mpr ⟨List.mk_mem_zipIdx_iff_getElem?.mpr\n      (List.getElem?_eq_getElem hv), beq_iff_eq.mpr hc⟩\n  · intro x hx\n    have hg := List.mem_zipIdx' (List.mem_filter.mp (List.mem_toFinset.mp hx)).1\n    change f x.1 = if hi : x.2 < vs.length then f vs[x.2] else 1\n    simp only [dite_eq_left hg.1, hg.2]\n\n/-- Both endpoints lie in the complete original vertex range. -/\ntheorem endpoints_lt (net : Network) (e : Fin (SemiprimeD1TensorNetwork.edgeCount net)) :\n    (networkGraph net).left e < (SemiprimeD1TensorNetwork.vertices net).length ∧\n      (networkGraph net).right e < (SemiprimeD1TensorNetwork.vertices net).length := by\n  have hl := (SemiprimeD1TensorNetwork.owner net.rows (occurrence net e)).isLt\n  have hr := (occurrence net e).1.isLt\n  simp only [networkGraph, vertices_length]\n  constructor <;> omega\n\n/-- Literal class incident addresses equal the mathematical incident-edge set. -/\ntheorem classPorts_incident (net : Network) (colours : List Nat) (c : Nat)\n    (e : Fin (SemiprimeD1TensorNetwork.edgeCount net)) :\n    e.val ∈ (classPorts (SemiprimeD1BoundaryPlan.graph net) colours c).1 ↔\n      e ∈ SemiprimeD1BoundarySemantics.incident (networkGraph net) (colourClass net colours c) := by\n  change e.val ∈ selectedIndices (SemiprimeD1BoundaryPlan.graph net).edges\n    (fun x => colours.getD x.1.1 0 == c || colours.getD x.1.2 0 == c) ↔ _\n  rw [selectedIndices_mem _ _ e.val (by\n    simpa only [SemiprimeD1BoundaryPlan.graph_edges_length] using e.isLt)]\n  have hi : e.val < (SemiprimeD1BoundaryPlan.graph net).edges.length := by\n    simpa only [SemiprimeD1BoundaryPlan.graph_edges_length] using e.isLt\n  have he : (SemiprimeD1BoundaryPlan.graph net).edges[e.val]'hi =\n      ((networkGraph net).left e, (networkGraph net).right e) := networkEndpoints_get net e\n  rw [he]\n  have hb := endpoints_lt net e\n  simp [SemiprimeD1BoundarySemantics.incident, colourClass, hb.1, hb.2]\n\n/-- Literal class boundary addresses equal precisely the exclusive endpoint set. -/\ntheorem classPorts_boundary (net : Network) (colours : List Nat) (c : Nat)\n    (e : Fin (SemiprimeD1TensorNetwork.edgeCount net)) :\n    e.val ∈ (classPorts (SemiprimeD1BoundaryPlan.graph net) colours c).2 ↔\n      e ∈ SemiprimeD1BoundarySemantics.boundary (networkGraph net) (colourClass net colours c) := by\n  change e.val ∈ selectedIndices (SemiprimeD1BoundaryPlan.graph net).edges\n    (fun x => (colours.getD x.1.1 0 == c) != (colours.getD x.1.2 0 == c)) ↔ _\n  rw [selectedIndices_mem _ _ e.val (by\n    simpa only [SemiprimeD1BoundaryPlan.graph_edges_length] using e.isLt)]\n  have hi : e.val < (SemiprimeD1BoundaryPlan.graph net).edges.length := by\n    simpa only [SemiprimeD1BoundaryPlan.graph_edges_length] using e.isLt\n  have he : (SemiprimeD1BoundaryPlan.graph net).edges[e.val]'hi =\n      ((networkGraph net).left e, (networkGraph net).right e) := networkEndpoints_get net e\n  rw [he]\n  have hb := endpoints_lt net e\n  simp only [SemiprimeD1BoundarySemantics.boundary, SemiprimeD1BoundarySemantics.incident,\n    SemiprimeD1BoundarySemantics.internal, colourClass, Finset.mem_sdiff,\n    Finset.mem_filter, Finset.mem_univ, true_and, Finset.mem_range, hb.1, hb.2,\n    bne_iff_ne]\n  change (¬ (colours.getD ((networkGraph net).left e) 0 == c) =\n      (colours.getD ((networkGraph net).right e) 0 == c)) ↔ _\n  rw [not_congr Bool.eq_iff_iff]\n  simp only [beq_iff_eq]\n  tauto\n\n/-- Both executed class address lists contain each selected occurrence only once. -/\ntheorem classPorts_nodup (g : SemiprimeD1BoundaryPlan.Graph) (colours : List Nat) (c : Nat) :\n    (classPorts g colours c).1.Nodup ∧ (classPorts g colours c).2.Nodup :=\n  ⟨selectedIndices_nodup _ _, selectedIndices_nodup _ _⟩\n\n/-- Both actual class lists contain only valid global occurrence ordinals. -/\ntheorem classPorts_lt (g : SemiprimeD1BoundaryPlan.Graph) (colours : List Nat) (c p : Nat) :\n    (p ∈ (classPorts g colours c).1 → p < g.edges.length) ∧\n      (p ∈ (classPorts g colours c).2 → p < g.edges.length) :=\n  ⟨selectedIndices_lt _ _ p, selectedIndices_lt _ _ p⟩\n\n/-- A selected literal vertex retains its original ordinal and acquired colour. -/\ntheorem classVertices_index (vs : List Vertex) (colours : List Nat) (c : Nat)\n    (v : Vertex) (hv : v ∈ classVertices vs colours c) :\n    ∃ i, ∃ hi : i < vs.length, vs[i] = v ∧ colours.getD i 0 = c := by\n  obtain ⟨x, hx, he⟩ := List.mem_map.mp hv\n  obtain ⟨hm, hc⟩ := List.mem_filter.mp hx\n  have hg := List.mem_zipIdx' hm\n  exact ⟨x.2, hg.1, hg.2.symm.trans he, beq_iff_eq.mp hc⟩\n\n/-- Well-formed local port caches have no repeated original ordinal. -/\ntheorem vertex_ports_nodup (net : Network) (hw : SemiprimeD1TensorNetwork.WellFormed net)\n    (v : Vertex) (hv : v ∈ SemiprimeD1TensorNetwork.vertices net) : v.ports.Nodup := by\n  rcases List.mem_append.mp hv with hl | hr\n  · obtain ⟨i, hi, he⟩ := List.mem_iff_getElem.mp hl\n    rw [Vector.getElem_toList] at he\n    subst v\n    rw [hw.1 ⟨i, by simpa only [Vector.length_toList] using hi⟩]\n    exact SemiprimeD1TensorNetwork.leftPorts_nodup _ _\n  · obtain ⟨i, hi, he⟩ := List.mem_iff_getElem.mp hr\n    rw [Vector.getElem_toList] at he\n    subst v\n    rw [hw.2 ⟨i, by simpa only [Vector.length_toList] using hi⟩]\n    exact SemiprimeD1TensorNetwork.rightPorts_nodup _ _\n\n/-- Every selected local table address is among that class's acquired incident edges. -/\ntheorem class_vertex_ports_subset (net : Network) (hw : SemiprimeD1TensorNetwork.WellFormed net)\n    (colours : List Nat) (c : Nat) (v : Vertex)\n    (hv : v ∈ classVertices (SemiprimeD1TensorNetwork.vertices net) colours c) :\n    ∀ p ∈ v.ports, p ∈ (classPorts (SemiprimeD1BoundaryPlan.graph net) colours c).1 := by\n  obtain ⟨i, hi, he, hc⟩ := classVertices_index _ colours c v hv\n  intro p hp\n  have hmem : v ∈ SemiprimeD1TensorNetwork.vertices net := he ▸ List.getElem_mem hi\n  have hbound := SemiprimeD1TensorNetwork.wellFormed_vertices net hw v hmem p hp\n  let e : Fin (SemiprimeD1TensorNetwork.edgeCount net) := ⟨p, hbound⟩\n  have hp' : e.val ∈ ((SemiprimeD1TensorNetwork.vertices net)[i]).ports := he.symm ▸ hp\n  have hend := (edge_mem_vertex_ports net hw i hi e).mp hp'\n  apply (classPorts_incident net colours c e).mpr\n  simp only [SemiprimeD1BoundarySemantics.incident, colourClass, Finset.mem_filter,\n    Finset.mem_univ, true_and, Finset.mem_range]\n  rcases hend with hl | hr\n  · exact Or.inl ⟨hl ▸ hi, hl ▸ hc⟩\n  · exact Or.inr ⟨hr ▸ hi, hr ▸ hc⟩\n\n/-- Every stored selected local arity is bounded by the actual incident dimension. -/\ntheorem class_vertex_arity (net : Network) (hw : SemiprimeD1TensorNetwork.WellFormed net)\n    (colours : List Nat) (c : Nat) (v : Vertex)\n    (hv : v ∈ classVertices (SemiprimeD1TensorNetwork.vertices net) colours c) :\n    v.ports.length ≤ (classPorts (SemiprimeD1BoundaryPlan.graph net) colours c).1.length := by\n  obtain ⟨i, hi, he, _⟩ := classVertices_index _ colours c v hv\n  have hn := vertex_ports_nodup net hw v (he ▸ List.getElem_mem hi)\n  exact hn.length_le_of_subset (class_vertex_ports_subset net hw colours c v hv)\n\n/-- Every colour class together is exactly the original complete vertex set. -/\ntheorem colourClass_cover (net : Network) (colours : List Nat) (k : Nat)\n    (hc : ∀ v, v < (SemiprimeD1TensorNetwork.vertices net).length → colours.getD v 0 < k) :\n    (Finset.range k).biUnion (colourClass net colours) = fullVertices net := by\n  ext v\n  simp only [Finset.mem_biUnion, colourClass, fullVertices, Finset.mem_filter,\n    Finset.mem_range]\n  constructor\n  · rintro ⟨c, _, hv, _⟩\n    exact hv\n  · intro hv\n    exact ⟨colours.getD v 0, hc v hv, hv, rfl⟩\n\n/-- The partition actually acquired at runtime covers the complete original family. -/\ntheorem acquired_cover (net : Network) :\n    (Finset.range (SemiprimeD1BoundaryPlan.acquire\n      (SemiprimeD1BoundaryPlan.graph net)).k).biUnion\n      (colourClass net (SemiprimeD1BoundaryPlan.acquire\n        (SemiprimeD1BoundaryPlan.graph net)).colours) = fullVertices net := by\n  apply colourClass_cover\n  intro v hv\n  have hl := SemiprimeD1BoundaryChoice.acquire_length (SemiprimeD1BoundaryPlan.graph net)\n  have hvi : v < (SemiprimeD1BoundaryPlan.acquire\n      (SemiprimeD1BoundaryPlan.graph net)).colours.length := by\n    rw [hl]\n    exact hv\n  apply SemiprimeD1BoundaryChoice.acquire_colours\n  rw [List.getD_eq_getElem _ _ hvi]\n  exact List.getElem_mem hvi\n\n/-- Selecting all original vertices leaves no boundary variable. -/\ntheorem boundary_full (net : Network) :\n    SemiprimeD1BoundarySemantics.boundary (networkGraph net) (fullVertices net) = ∅ := by\n  ext e\n  have hb := endpoints_lt net e\n  simp [SemiprimeD1BoundarySemantics.boundary, SemiprimeD1BoundarySemantics.incident,\n    SemiprimeD1BoundarySemantics.internal, fullVertices, hb.1, hb.2]\n\nnoncomputable section\n\n/-- The selected original table product is exactly the graph's local vertex product. -/\ntheorem classVertices_value (ctx : SemiprimeD1JetAxes.Context) (net : Network)\n    (colours : List Nat) (c : Nat) (bits : Fin (SemiprimeD1TensorNetwork.edgeCount net) → Bool) :\n    ((classVertices (SemiprimeD1TensorNetwork.vertices net) colours c).map (fun v =>\n      SemiprimeD1JetInterpretation.interpret ctx (SemiprimeD1TensorTables.valueAt v.table\n        (SemiprimeD1LeafCounter.localAssignment bits v)))).prod =\n    SemiprimeD1BoundarySemantics.product (vertexValue ctx net) (colourClass net colours c)\n      (SemiprimeD1BoundarySemantics.bitsEquiv.symm bits) := by\n  rw [classVertices_product]\n  simp only [SemiprimeD1BoundarySemantics.product, vertexValue, Equiv.apply_symm_apply]\n\nend\n\n/-- The actual sorted union contains exactly the two input port sets. -/\ntheorem unionPorts_mem (xs ys : List Nat) (p : Nat) :\n    p ∈ unionPorts xs ys ↔ p ∈ xs ∨ p ∈ ys := by\n  simp [unionPorts]\n\n/-- The actual new boundary is exactly the exclusive union of the old lists. -/\ntheorem remainingPorts_mem (xs ys : List Nat) (p : Nat) :\n    p ∈ remainingPorts xs ys ↔ (p ∈ xs ∧ p ∉ ys) ∨ (p ∈ ys ∧ p ∉ xs) := by\n  by_cases hx : p ∈ xs <;> by_cases hy : p ∈ ys <;>\n    simp [remainingPorts, unionPorts_mem, hx, hy]\n\n/-- Sorted union does not duplicate a variable shared by two old boundaries. -/\ntheorem eraseDups_nodup (xs : List Nat) : xs.eraseDups.Nodup := by\n  induction hn : xs.length using Nat.strong_induction_on generalizing xs with\n  | h n ih =>\n    cases xs with\n    | nil => simp\n    | cons x xs =>\n      rw [List.eraseDups_cons]\n      apply List.nodup_cons.mpr\n      constructor\n      · intro hm\n        have hh := List.mem_filter.mp (List.mem_eraseDups.mp hm)\n        simpa using hh.2\n      · apply ih ((xs.filter (fun b => !(b == x))).length)\n          (by have := List.length_filter_le (fun b => !(b == x)) xs\n              simp only [List.length_cons] at hn\n              omega) _ rfl\n\n/-- Sorted union does not duplicate a variable shared by two old boundaries. -/\ntheorem unionPorts_nodup (xs ys : List Nat) : (unionPorts xs ys).Nodup :=\n  eraseDups_nodup _\n\n/-- The executed symmetric difference has no duplicate ordinal. -/\ntheorem remainingPorts_nodup (xs ys : List Nat) : (remainingPorts xs ys).Nodup :=\n  (unionPorts_nodup xs ys).filter _\n\nend RiemannGaussian.SemiprimeD1BoundaryLeafPorts\n","RiemannGaussian.SemiprimeD1BoundaryLeafValue":"import RiemannGaussian.SemiprimeD1BoundaryTensorRep\nimport RiemannGaussian.SemiprimeD1BoundaryLeafLoad\n\n/-! Closed actual boundary-leaf byte correctness and paid fallback correctness. -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryLeaf\nopen SemiprimeD1BoundaryTensorRep\nopen SemiprimeD1BoundaryLeafPorts\nopen SemiprimeD1BoundaryRefinement\nopen SemiprimeD1BoundaryRecordsShape\nopen SemiprimeD1BoundaryRecordsReduction\nopen SemiprimeD1BoundaryPlan (Work)\nopen SemiprimeD1JetAxes (Context)\n\ntheorem acquire_represents (ctx : Context) (hp : ctx.Positive) (net : Network)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net) :\n    Represents ctx net (fullVertices net) (acquire ctx net).tensor := by\n  let g := SemiprimeD1BoundaryPlan.graph net\n  let vs := SemiprimeD1TensorNetwork.vertices net\n  let plan := SemiprimeD1BoundaryPlan.acquire g\n  have hk : 0 < plan.k := by\n    have h := (SemiprimeD1BoundaryChoice.chooseK_bounds g).1\n    exact lt_of_lt_of_le (by omega : 0 < 2) h\n  have hs := SemiprimeD1BoundaryLeafLoad.buckets_split ctx g vs plan.colours plan.k hk\n  have hm := mergeAll_represents ctx hp net hw plan.colours (List.range' 1 (plan.k-1))\n    (List.nodup_range') (colourClass net plan.colours 0)\n    (bucket ctx g vs plan.colours 0).value (bucket_represents ctx hp net hw plan.colours 0)\n    (by\n      intro c hc\n      obtain ⟨i,_,hc'⟩ := List.mem_range'.mp hc\n      exact colourClass_disjoint net plan.colours 0 c (by omega))\n  have hrange : List.range plan.k = 0 :: List.range' 1 (plan.k-1) := by\n    cases h : plan.k with\n    | zero => omega\n    | succ n => simp only [List.range_eq_range',List.range'_succ,Nat.add_sub_cancel,Nat.zero_add]\n  have hcover : colourClass net plan.colours 0 ∪\n      (List.range' 1 (plan.k-1)).toFinset.biUnion (colourClass net plan.colours) = fullVertices net := by\n    have hc := acquired_cover net\n    change (Finset.range plan.k).biUnion (colourClass net plan.colours) = fullVertices net at hc\n    rw [←List.toFinset_range,hrange] at hc\n    simpa only [List.toFinset_cons,Finset.biUnion_insert] using hc\n  rw [hcover] at hm\n  change Represents ctx net (fullVertices net)\n    (mergeAll ctx (((List.range plan.k).map (bucket ctx g vs plan.colours)).headD ⟨⟨[],[]⟩,1⟩).value\n      ((((List.range plan.k).map (bucket ctx g vs plan.colours)).tail).map Work.value)).value\n  rw [hs]\n  simpa only [List.headD_cons,List.tail_cons,List.map_map,Function.comp_def] using hm\n\n/-- Exact old whole-jet bytes from the closed acquired bucket/merge execution. -/\ntheorem run_words (ctx : Context) (net : Network) (hp : ctx.Positive)\n    (hw : SemiprimeD1TensorNetwork.WellFormed net) :\n    (run ctx net).words = (SemiprimeD1TensorNetwork.leaf ctx net).words := by\n  apply words_eq_leaf_of_boundary ctx net hp _ (SemiprimeD1BoundaryLeafCanonical.run_good ctx net)\n  have hr := acquire_represents ctx hp net hw\n  rw [run_interpret_scalar ctx net (SemiprimeD1BoundaryLeafLoad.acquired_empty_ports ctx net)]\n  have he := hr.value (∅ : Finset (Fin (SemiprimeD1TensorNetwork.edgeCount net)))\n  simp only [address,SemiprimeD1BoundaryLeafLoad.acquired_empty_ports,List.map_nil] at he\n  rw [he]\n  change SemiprimeD1BoundarySemantics.value (networkGraph net) (vertexValue ctx net) (fullVertices net) ∅ =\n    SemiprimeD1BoundarySemantics.value (networkGraph net) (vertexValue ctx net) (fullVertices net)\n      (SemiprimeD1BoundarySemantics.bitsEquiv.symm (fun _ => false))\n  have hb : SemiprimeD1BoundarySemantics.bitsEquiv.symm\n      (fun _ : Fin (SemiprimeD1TensorNetwork.edgeCount net) => false) = ∅ := by\n    ext e\n    simp [SemiprimeD1BoundarySemantics.bitsEquiv]\n  rw [hb]\n\n/-- The executed validity guard and paid old-leaf fallback give total byte\ncorrectness under positive axes alone, including precision zero. -/\ntheorem checked_words (ctx : Context) (net : Network) (hp : ctx.Positive) :\n    (checked ctx net).words = (SemiprimeD1TensorNetwork.leaf ctx net).words := by\n  simp only [checked]\n  split_ifs with h\n  ·\n    exact run_words ctx net hp ((validate_correct ctx net).mp h).1\n  · exact SemiprimeD1TensorTapeLeaf.leaf_words ctx net\n\nend RiemannGaussian.SemiprimeD1BoundaryLeaf\n","RiemannGaussian.SemiprimeD1BoundaryRecordsContractBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BoundaryRecordsGroupBounds\nimport RiemannGaussian.SemiprimeD1BoundaryRecordsSortBounds\n\n/-! # Full-record sequential contraction report -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1BoundaryRecordsContractBounds\nopen SemiprimeD1BoundaryRecords\nopen SemiprimeD1BoundaryRecordsCanonical\nopen SemiprimeD1BoundaryRecordsReduction\nopen SemiprimeD1BoundaryRecordsGroupBounds\nopen SemiprimeD1JetAxes (Context)\n\n/-- Paid identifier comparison metadata, independent of assignment count. -/\ndef portMass (ps : List Nat) : Nat := (ps.map (fun p => Nat.size p+1)).sum\n\n/-- Search pays actual binary identifier widths and sequential traversal. -/\ntheorem findPort_clock (p : Nat) (ps : List Nat) :\n    (findPort p ps).clock ≤ 3*(Nat.size p+1)*(portMass ps+1) := by\n  induction ps with\n  | nil => simp [findPort,portMass]; omega\n  | cons q qs ih =>\n    simp only [findPort]\n    split <;> simp only [portMass,List.map_cons,List.sum_cons] at ih ⊢ <;> nlinarith\n\n/-- Sequential bit access pays at most the entire input address. -/\ntheorem readBit_clock (bits : List Bool) (i : Nat) :\n    (readBit bits i).clock ≤ 3*(bits.length+1) := by\n  induction bits generalizing i with\n  | nil => simp [readBit]\n  | cons b bs ih =>\n    cases i with\n    | zero => simp only [readBit,List.length_cons]; omega\n    | succ i =>\n      have ht:=ih i\n      simp only [readBit,List.length_cons]\n      omega\n\n/-- Port projection has polynomial metadata work and no table scan. -/\ndef projectBudget (source target : List Nat) (K : Nat) : Nat :=\n  3*(portMass target+1)*(portMass source+1)+3*(target.length+1)*(K+2)\n\ntheorem project_clock (bits : List Bool) (source target : List Nat) (K : Nat)\n    (hk : bits.length≤K) : (project bits source target).clock ≤ projectBudget source target K := by\n  induction target with\n  | nil => simp [project,projectBudget,portMass]; omega\n  | cons p ps ih =>\n    have hf:=findPort_clock p source\n    have hb:=readBit_clock bits (findPort p source).value\n    simp only [project]\n    unfold projectBudget at ih ⊢\n    simp only [portMass,List.map_cons,List.sum_cons,List.length_cons] at ih hf ⊢\n    nlinarith\n\n/-- Full rekey work retains all payload bytes and address projection. -/\ndef rekeyBudget (ctx : Context) (source target : List Nat) (K : Nat) : Nat :=\n  projectBudget source target K+3*recordBudget ctx K+6\n\ntheorem rekey_clock (ctx : Context) (source target : List Nat) (K : Nat)\n    (es : List Entry) (hg : GoodEntries ctx es) (hk : Keys K es) :\n    (rekey source target es).clock ≤ rekeyBudget ctx source target K*(es.length+1) := by\n  induction es with\n  | nil => simp only [rekey,List.length_nil,Nat.zero_add,Nat.mul_one]; unfold rekeyBudget; omega\n  | cons e es ih =>\n    have ht:=ih (fun x hx => hg x (List.mem_cons_of_mem _ hx))\n      (fun x hx => hk x (List.mem_cons_of_mem _ hx))\n    have hp:=project_clock e.key source target K (hk e List.mem_cons_self)\n    have hs:=size_le ctx K e (hg e List.mem_cons_self) (hk e List.mem_cons_self)\n    simp only [rekey,List.length_cons]\n    unfold rekeyBudget at ht ⊢\n    nlinarith\n\ntheorem rekey_keys (source target : List Nat) (es : List Entry) :\n    Keys target.length (rekey source target es).value := by\n  induction es with\n  | nil => simp [rekey,Keys]\n  | cons e es ih =>\n    intro x hx\n    rcases List.mem_cons.mp hx with rfl | hx\n    · exact (project_length e.key source target).le\n    · exact ih x hx\n\n/-- Actual sort and full-jet grouping cost one exponential catalogue, with a\npolynomial independent factor. Precision zero still retains rank delimiters. -/\ndef contractBudget (ctx : Context) (source target : List Nat) (K W : Nat) : Nat :=\n  rekeyBudget ctx source target K+\n  200*(recordBudget ctx target.length+1)*(W+3)+sumBudget ctx target.length+5\n\ntheorem contract_clock_pow (ctx : Context) (source target : List Nat) (K W : Nat)\n    (es : List Entry) (hg : GoodEntries ctx es) (hk : Keys K es) (hn : es.length≤2^W) :\n    (contract ctx source target es).clock ≤ contractBudget ctx source target K W*(2^W+1) := by\n  have hr:=rekey_clock ctx source target K es hg hk\n  have hgood:=rekey_good ctx source target es hg\n  have hkeys:=rekey_keys source target es\n  have hs:=SemiprimeD1BoundaryRecordsSortBounds.sort_clock_pow\n    (rekey source target es).value (recordBudget ctx target.length) W\n    (fun e he => size_le ctx target.length e (hgood e he) (hkeys e he))\n    (by rw [rekey_length]; exact hn)\n  have hg':=sort_good ctx _ hgood\n  have hk' : Keys target.length (sort (rekey source target es).value).value := by\n    intro e he\n    exact hkeys e ((SemiprimeD1BoundaryRecordsSort.sort_perm _).mem_iff.mp he)\n  have ht:=group_clock ctx target.length _ hg' hk'\n  rw [SemiprimeD1BoundaryRecordsSort.sort_length,rekey_length] at ht\n  have hr':=hr.trans (Nat.mul_le_mul_left _ (Nat.add_le_add_right hn 1))\n  have ht':=ht.trans (Nat.mul_le_mul_left _ (Nat.add_le_add_right hn 1))\n  simp only [contract]\n  unfold contractBudget\n  nlinarith only [hr',hs,ht',Nat.zero_le (2^W)]\n\nend RiemannGaussian.SemiprimeD1BoundaryRecordsContractBounds\n","RiemannGaussian.SemiprimeD1ChildContractionSum":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildNetworkIntegrand\nimport RiemannGaussian.SemiprimeD1OriginalDoubleAssignments\n\n/-! # Original double sums equal products of actual child contractions\nOnly computed original assignment bijections and literal child-scope equalities\nare used. The right side is the executed eager leaf contraction of each actual\ncached child; no assignment inverse, contraction or solver answer is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 120000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1ChildContractionSum\nopen scoped BigOperators\nopen SemiprimeD1TensorNetwork\nopen SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nopen SemiprimeD1ChildOldEntrySemantics SemiprimeD1ChildOldEntryAssignment\nopen SemiprimeD1ChildNetworkIntegrand\n\n/-- The ACTUAL emitted child variable count is the acquired physical endpoint scope. -/\ntheorem child_scope (net : Network) (old : Context) (extra : List ℕ) (p r a u : ℕ)\n    (q : Fin a) (g : Fin r) (z : SemiprimeD1JetRingBits.Run)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) :\n    edgeCount (child net old extra p r a u q g z t beta)=\n      SemiprimeD1ChildAssignmentEquiv.scope net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows) q g := by\n  change scope (SemiprimeD1ChildOldEntryAssignment.rows net r a q g)=\n    (data net r a q g).graph.factors.flatten.length\n  exact SemiprimeD1TensorNetworkLayout.child_scope (data net r a q g).graph\n\n/-- Exact finite-coordinate assignment transport, with its literal inverse. -/\ndef castBits {M N : ℕ} (h : M=N) : (Fin N→Bool) ≃ (Fin M→Bool) where\n  toFun bits j := bits ((finCongr h) j)\n  invFun bits j := bits ((finCongr h).symm j)\n  left_inv bits := by\n    funext j\n    exact congrArg bits ((finCongr h).apply_symm_apply j)\n  right_inv bits := by\n    funext j\n    exact congrArg bits ((finCongr h).symm_apply_apply j)\n\n/-- Literal coordinate-identity assignment cast, from the ACTUAL derived child scopes. -/\ndef assignmentCast (net : Network) (old : Context) (extra : List ℕ) (p r a u : ℕ)\n    (q : Fin a) (g : Fin r) (z : SemiprimeD1JetRingBits.Run)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ) :\n    (Fin (SemiprimeD1ChildAssignmentEquiv.scope net.leftCount net.rows.length r a\n      (arity net.rows) (owner net.rows) q g)→Bool) ≃\n    (Fin (edgeCount (child net old extra p r a u q g z t beta))→Bool) :=\n  castBits (child_scope net old extra p r a u q g z t beta)\n\n/-- The coordinate cast is EXACTLY the canonical networkAssignment already used by the executed integrand. -/\ntheorem assignmentCast_value (net : Network) (old : Context) (extra : List ℕ) (p r a u : ℕ)\n    [NeZero r] (q : Fin a) (g : Fin r) (z : SemiprimeD1JetRingBits.Run)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ)\n    (bits : Incidence net.rows×Bool→Bool) :\n    assignmentCast net old extra p r a u q g z t beta\n      (SemiprimeD1ChildAssignmentEquiv.assignments net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows) q bits g)=networkAssignment net r a q g bits := rfl\n\n/-- The actual leaf contraction is the sum of its actual executed assignment products. -/\ntheorem leaf_sum_evaluations (ctx : Context) (hpos : ctx.Positive) (net : Network) :\n    interpret ctx (leaf ctx net).words=\n      ∑bits : Fin (edgeCount net)→Bool,\n        interpret ctx (SemiprimeD1LeafCounter.evaluateAssignment ctx (vertices net) (List.ofFn bits)).words := by\n  rw [leaf_value ctx hpos net]\n  apply Finset.sum_congr rfl\n  intro bits _\n  exact (SemiprimeD1LeafCounter.evaluateAssignment_value ctx hpos (vertices net) bits).symm\n\n/-- Exact original X/Y double sum of actual cached child assignment products equals\nindependent ACTUAL child contractions. No supplied inverse, count or projection is used. -/\ntheorem sum_child_contractions (net : Network) (old : Context) (extra : List ℕ)\n    (p r a u : ℕ) [NeZero r] (q : Fin a) (z : SemiprimeD1JetRingBits.Run)\n    (t : Fin (SemiprimeD1WireKernelOriginal.size a)) (beta : List ℕ)\n    (hpos : (⟨extra++old.axes,p⟩ : Context).Positive) :\n    (∑X : SemiprimeD1OriginalDoubleAssignments.Bits net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows),\n      ∑Y : SemiprimeD1OriginalDoubleAssignments.Bits net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows),\n        ∏g : Fin r,interpret ⟨extra++old.axes,p⟩\n          (SemiprimeD1LeafCounter.evaluateAssignment ⟨extra++old.axes,p⟩\n            (vertices (child net old extra p r a u q g z t beta))\n            (List.ofFn (networkAssignment net r a q g\n              (SemiprimeD1PacketAssignmentRows.tagBits net.leftCount net.rows.length r a\n                (arity net.rows) (owner net.rows) X Y)))).words)=\n      ∏g : Fin r,interpret ⟨extra++old.axes,p⟩\n        (leaf ⟨extra++old.axes,p⟩ (child net old extra p r a u q g z t beta)).words := by\n  classical\n  have h:=SemiprimeD1OriginalDoubleAssignments.sum_child_products net.leftCount net.rows.length r a\n    (arity net.rows) (owner net.rows) q\n    (fun g bits => interpret ⟨extra++old.axes,p⟩\n      (SemiprimeD1LeafCounter.evaluateAssignment ⟨extra++old.axes,p⟩\n        (vertices (child net old extra p r a u q g z t beta))\n        (List.ofFn (assignmentCast net old extra p r a u q g z t beta bits))).words)\n  calc\n    _=∏g : Fin r,∑bits : Fin (SemiprimeD1ChildAssignmentEquiv.scope net.leftCount net.rows.length r a\n        (arity net.rows) (owner net.rows) q g)→Bool,\n      interpret ⟨extra++old.axes,p⟩\n        (SemiprimeD1LeafCounter.evaluateAssignment ⟨extra++old.axes,p⟩\n          (vertices (child net old extra p r a u q g z t beta))\n          (List.ofFn (assignmentCast net old extra p r a u q g z t beta bits))).words := by\n      convert h using 1\n      apply Finset.sum_congr (by ext; simp)\n      intro X _\n      apply Finset.sum_congr (by ext; simp)\n      intro Y _\n      apply Finset.prod_congr (by ext; simp)\n      intro g _\n      rw [assignmentCast_value]\n      rfl\n    _=_ := by\n      apply Finset.prod_congr rfl\n      intro g _\n      exact ((assignmentCast net old extra p r a u q g z t beta).sum_comp\n        (fun bits => interpret ⟨extra++old.axes,p⟩\n          (SemiprimeD1LeafCounter.evaluateAssignment ⟨extra++old.axes,p⟩\n            (vertices (child net old extra p r a u q g z t beta)) (List.ofFn bits)).words)).trans\n        (leaf_sum_evaluations ⟨extra++old.axes,p⟩ hpos (child net old extra p r a u q g z t beta)).symm\nend RiemannGaussian.SemiprimeD1ChildContractionSum\n","RiemannGaussian.SemiprimeD1ChildTableCopy":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTables\nimport RiemannGaussian.SemiprimeD1ModeRoutingBits\n\n/-! # Eager physical copy and port reindexing of CURRENT local tables\nThe source is an already materialized table. Every assignment is gathered from\nan explicit cached index list, physically read, zero-extended and reduced at the\nnew precision. There is no tensor truth callback or creator replay.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1ChildTableCopy\nopen SemiprimeD1JetAxes SemiprimeD1TensorTables\n\n/-- Actual assignment-bit gather in the supplied cached port order. -/\ndef gather (bits : List Bool) : List ℕ→SemiprimeMaterializedWords.Run (List Bool)\n  | [] => ⟨[],1⟩\n  | i::is =>\n    let bit := SemiprimeD1ModeRoutingBits.readBit bits i\n    let tail := gather bits is\n    ⟨bit.value::tail.value,bit.work+tail.work+4⟩\n\n/-- The computed assignment is the literal selected-bit vector. -/\ntheorem gather_value (bits : List Bool) (order : List ℕ) :\n    (gather bits order).value=order.map (fun i => (bits[i]?).getD false) := by\n  induction order with\n  | nil => rfl\n  | cons i is ih => simp only [gather,SemiprimeD1ModeRoutingBits.readBit_value,ih,List.map_cons]\n\n/-- Gathering never invents or removes a source port. -/\ntheorem gather_length (bits : List Bool) (order : List ℕ) :\n    (gather bits order).value.length=order.length := by rw [gather_value,List.length_map]\n\n/-- A padded read cannot visit more cells than the actual assignment list. -/\ntheorem readBit_clock_length (bits : List Bool) (i : ℕ) :\n    (SemiprimeD1ModeRoutingBits.readBit bits i).work≤4*bits.length+2 := by\n  induction bits generalizing i with\n  | nil => simp [SemiprimeD1ModeRoutingBits.readBit]\n  | cons b bs ih =>\n    cases i with\n    | zero => simp [SemiprimeD1ModeRoutingBits.readBit]\n    | succ i =>\n      have h := ih i\n      simp only [SemiprimeD1ModeRoutingBits.readBit,List.length_cons]\n      omega\n\n/-- Every actual bit scan and gathered list cell is paid. -/\ntheorem gather_clock (bits : List Bool) (order : List ℕ) :\n    (gather bits order).work≤order.length*(4*bits.length+7)+1 := by\n  induction order with\n  | nil => simp [gather]\n  | cons i is ih =>\n    have h := readBit_clock_length bits i\n    simp only [gather,List.length_cons]\n    nlinarith\n\n/-- Reduce every copied coefficient physically, including at a smaller precision. -/\ndef normalize (p : ℕ) : List (List Bool)→SemiprimeD1JetRingBits.Run\n  | [] => ⟨[],1⟩\n  | w::ws =>\n    let out := SemiprimeD1JetScalarBits.reduce p w\n    let tail := normalize p ws\n    ⟨out.bits::tail.words,out.clock+tail.clock+4⟩\n\n/-- Exact literal coefficient transformation performed by normalization. -/\ntheorem normalize_words (p : ℕ) (ws : List (List Bool)) :\n    (normalize p ws).words=ws.map (fun w => (SemiprimeD1JetScalarBits.reduce p w).bits) := by\n  induction ws with\n  | nil => rfl\n  | cons w ws ih => simp only [normalize,ih,List.map_cons]\n\n/-- Physical canonical output shape needs only the actual vector length. -/\ntheorem normalize_good (ctx : Context) (ws : List (List Bool)) (hs : ws.length=ctx.rank) :\n    GoodWords ctx (normalize ctx.precision ws).words := by\n  rw [normalize_words]\n  refine ⟨by simpa only [List.length_map] using hs,?_⟩\n  intro w hw\n  obtain ⟨v,_,rfl⟩ := List.mem_map.mp hw\n  exact ⟨SemiprimeD1JetScalarBits.reduce_compact _ _,SemiprimeD1JetScalarBits.reduce_length _ _⟩\n\n/-- Every physical coefficient reduction and vector cell is retained. -/\ntheorem normalize_clock (p : ℕ) (ws : List (List Bool)) :\n    (normalize p ws).clock≤ws.length*(9*p+9)+1 := by\n  induction ws with\n  | nil => simp [normalize]\n  | cons w ws ih =>\n    have h := SemiprimeD1JetScalarBits.reduce_clock p w\n    simp only [normalize,List.length_cons]\n    nlinarith\n\n/-- At a larger precision the CURRENT canonical literal bytes are unchanged. -/\ntheorem normalize_stable (old : Context) (p : ℕ) (ws : List (List Bool))\n    (hg : GoodWords old ws) (hp : old.precision≤p) : (normalize p ws).words=ws := by\n  rw [normalize_words]\n  conv_rhs => rw [←List.map_id ws]\n  apply List.map_congr_left\n  intro w hw\n  apply SemiprimeSourceCompactWordIds.compact_value_injective\n  · exact SemiprimeD1JetScalarBits.reduce_compact _ _\n  · exact (hg.2 w hw).1\n  · have hlt := (SemiprimeBitArithmetic.bitValue_lt_width w).trans_le\n      (Nat.pow_le_pow_right (by omega : 0<2) ((hg.2 w hw).2.trans hp))\n    exact (SemiprimeD1JetScalarBits.reduce_value p w).trans (Nat.mod_eq_of_lt hlt)\n\n/-- Copy ALL current coordinates, append zero axes, then reduce the same literal\ninteger coefficients at the new precision. -/\ndef lift (old : Context) (extra : List ℕ) (p : ℕ) (ws : List (List Bool)) :\n    SemiprimeD1JetRingBits.Run :=\n  let copied := embed ⟨old,old,ws⟩ extra p\n  let out := normalize p copied.value.coefficients\n  ⟨out.words,copied.clock+out.clock+3⟩\n\n/-- Exact physical current-integer lift, including every old coordinate. -/\ntheorem lift_words (old : Context) (extra : List ℕ) (p : ℕ) (ws : List (List Bool)) :\n    (lift old extra p ws).words=\n      (ws++List.replicate (old.rank*(extra.prod-1)) []).map\n        (fun w => (SemiprimeD1JetScalarBits.reduce p w).bits) := by\n  simp only [lift,normalize_words,embed_coefficients]\n\n/-- When the child precision is larger, every current literal byte is copied\nunchanged and only genuinely new axis coordinates are zero. -/\ntheorem lift_stable (old : Context) (extra : List ℕ) (p : ℕ) (ws : List (List Bool))\n    (hg : GoodWords old ws) (hp : old.precision≤p) :\n    (lift old extra p ws).words=ws++List.replicate (old.rank*(extra.prod-1)) [] := by\n  rw [lift_words,List.map_append]\n  have hm := normalize_stable old p ws hg hp\n  rw [normalize_words] at hm\n  rw [hm,List.map_replicate]\n  congr 2\n  simp only [SemiprimeD1JetScalarBits.reduce,SemiprimeD1JetScalarBits.takeBits_bits,\n    List.take_nil,SemiprimeSourceCompactBits.trim]\n\n/-- Actual shape and canonicality follow from the old vector and positive new axes. -/\ntheorem lift_good (old : Context) (extra : List ℕ) (p : ℕ) (ws : List (List Bool))\n    (hs : ws.length=old.rank) (he : 0<extra.prod) :\n    GoodWords ⟨extra++old.axes,p⟩ (lift old extra p ws).words := by\n  exact normalize_good ⟨extra++old.axes,p⟩ _ (embed_shape ⟨old,old,ws⟩ extra p hs he)\n\n/-- Explicit finite physical copy/reduction budget, retaining every old coordinate. -/\ndef liftBudget (old : Context) (extra : List ℕ) (p : ℕ) : ℕ :=\n  old.rank*(3*old.precision+5)+old.rank*(extra.prod-1)+extra.length+old.axes.length+8+\n    (extra.prod*old.rank)*(9*p+9)+4\n\n/-- The literal vector loop obeys its computed budget, not a clock annotation. -/\ntheorem lift_clock (old : Context) (extra : List ℕ) (p : ℕ) (ws : List (List Bool))\n    (hg : GoodWords old ws) (he : 0<extra.prod) :\n    (lift old extra p ws).clock≤liftBudget old extra p := by\n  have hc := embed_clock_le ⟨old,old,ws⟩ extra p old.precision hg.1 (fun w hw => (hg.2 w hw).2)\n  have hn := normalize_clock p (embed ⟨old,old,ws⟩ extra p).value.coefficients\n  rw [embed_shape ⟨old,old,ws⟩ extra p hg.1 he,embed_rank] at hn\n  change (embed ⟨old,old,ws⟩ extra p).clock+\n    (normalize p (embed ⟨old,old,ws⟩ extra p).value.coefficients).clock+3≤_\n  exact Nat.add_le_add_right (Nat.add_le_add hc hn) 3\n\n/-- The producer is a concrete cached-table read, not an arbitrary tensor oracle. -/\ndef entry {oldDegree : ℕ} (old : Context) (extra : List ℕ) (p : ℕ)\n    (table : Table oldDegree) (order : List ℕ) (bits : List Bool) :\n    SemiprimeD1JetRingBits.Run :=\n  let selected := gather bits order\n  let value := lookup table selected.value\n  let copied := lift old extra p value.words\n  ⟨copied.words,selected.work+value.clock+copied.clock+5⟩\n\n/-- Materialize the entire child table using actual cached parent table entries. -/\ndef acquire {oldDegree : ℕ} (old : Context) (extra : List ℕ) (p childDegree : ℕ)\n    (table : Acquired oldDegree) (order : List ℕ) : Acquired childDegree :=\n  let out := build childDegree (entry old extra p table.table order)\n  ⟨out.table,table.clock+out.clock+order.length+5⟩\n\n/-- Exact entry refinement to the actual copied parent read. -/\ntheorem acquire_value {oldDegree : ℕ} (old : Context) (extra : List ℕ) (p childDegree : ℕ)\n    (table : Acquired oldDegree) (order : List ℕ) (bits : List Bool) (hb : bits.length=childDegree) :\n    (lookup (acquire old extra p childDegree table order).table bits).words=\n      (lift old extra p (lookup table.table (gather bits order).value).words).words :=\n  build_value childDegree (entry old extra p table.table order) bits hb\n\n/-- Every newly materialized entry is canonical at the new CURRENT context. -/\ntheorem acquire_good {oldDegree : ℕ} (old : Context) (extra : List ℕ) (p childDegree : ℕ)\n    (table : Acquired oldDegree) (order : List ℕ) (ht : Good old table.table)\n    (he : 0<extra.prod) : Good ⟨extra++old.axes,p⟩ (acquire old extra p childDegree table order).table := by\n  apply build_good\n  intro bits _\n  exact lift_good old extra p _ (lookup_good old table.table ht _).1 he\n\n/-- Full table-copy work has exactly the eager local `2^degree` scale. -/\ntheorem acquire_clock {oldDegree : ℕ} (old : Context) (extra : List ℕ) (p childDegree : ℕ)\n    (table : Acquired oldDegree) (order : List ℕ) (ht : Good old table.table)\n    (he : 0<extra.prod) :\n    (acquire old extra p childDegree table order).clock≤table.clock+\n      (order.length*(4*childDegree+7)+1+old.rank*(3*old.precision+4)+1+\n        4*oldDegree+liftBudget old extra p+12)*2^childDegree+order.length := by\n  have h := build_clock childDegree\n    (order.length*(4*childDegree+7)+1+old.rank*(3*old.precision+4)+1+\n      4*oldDegree+liftBudget old extra p+5) (entry old extra p table.table order) (by\n    intro bits hb\n    have hg := gather_clock bits order\n    rw [hb] at hg\n    have hv := lookup_clock old table.table ht (gather bits order).value\n    have hl := lift_clock old extra p (lookup table.table (gather bits order).value).words\n      (lookup_good old table.table ht (gather bits order).value) he\n    change (gather bits order).work+(lookup table.table (gather bits order).value).clock+\n      (lift old extra p (lookup table.table (gather bits order).value).words).clock+5≤_\n    omega)\n  change (build childDegree (entry old extra p table.table order)).clock+5≤\n    (order.length*(4*childDegree+7)+1+old.rank*(3*old.precision+4)+1+\n      4*oldDegree+liftBudget old extra p+12)*2^childDegree at h\n  change table.clock+(build childDegree (entry old extra p table.table order)).clock+order.length+5≤_\n  omega\n\nend RiemannGaussian.SemiprimeD1ChildTableCopy\n","RiemannGaussian.SemiprimeD1ChildTensorTables":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ChildTableCopy\nimport RiemannGaussian.SemiprimeD1ChildTableOrder\n\n/-! # Actual cached old-vertex tables in a child group\nThe original/current tensor is concrete literal data. Active vertices copy and\nreindex it by the computed port cache; inactive vertices get the zero-port one\ntable. No truth callback is accepted, including for isolated old vertices.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1ChildTensorTables\nopen SemiprimeD1TensorTables SemiprimeD1JetAxes\n\n/-- Concrete zero-port scalar-one table in every current coefficient coordinate. -/\ndef unit (ctx : Context) : Acquired 0 :=\n  let one := SemiprimeD1JetScalarBits.reduce ctx.precision [true]\n  let words := if ctx.rank=0 then [] else one.bits::List.replicate (ctx.rank-1) []\n  ⟨.leaf words,one.clock+ctx.rank+8⟩\n\n/-- All scalar-one coefficients are canonical at the actual target precision. -/\ntheorem unit_good (ctx : Context) : Good ctx (unit ctx).table := by\n  change GoodWords ctx (if ctx.rank=0 then [] else\n    (SemiprimeD1JetScalarBits.reduce ctx.precision [true]).bits::List.replicate (ctx.rank-1) [])\n  split_ifs with hz\n  · exact ⟨by simpa only [List.length_nil] using hz.symm,by simp⟩\n  · refine ⟨by simp only [List.length_cons,List.length_replicate];omega,?_⟩\n    intro w hw\n    rcases List.mem_cons.mp hw with rfl|hw\n    · exact ⟨SemiprimeD1JetScalarBits.reduce_compact _ _,SemiprimeD1JetScalarBits.reduce_length _ _⟩\n    · have he : w=[] := (List.mem_replicate.mp hw).2\n      subst w\n      exact ⟨True.intro,Nat.zero_le _⟩\n\n/-- The zero-port unit is built from a literal bit and explicit zero cells. -/\ntheorem unit_clock (ctx : Context) : (unit ctx).clock≤9*ctx.precision+ctx.rank+13 := by\n  have h := SemiprimeD1JetScalarBits.reduce_clock ctx.precision [true]\n  change (SemiprimeD1JetScalarBits.reduce ctx.precision [true]).clock+ctx.rank+8≤_\n  omega\n\n/-- A concrete table whose degree is acquired from the actual physical mask/cache. -/\nstructure Result where\n  /-- Zero if masked out; otherwise the actual child-local port count. -/\n  degree : ℕ\n  /-- Entire acquired literal table. -/\n  table : Table degree\n  /-- Complete cached-order, physical table-copy and new table allocation report. -/\n  clock : ℕ\n\n/-- The current parent table is supplied literally; all routing metadata is acquired\nfrom the actual cached endpoint permutation, and every old coordinate is kept. -/\ndef fromCache {n F a : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (data : SemiprimeD1ChildPortPullback.Acquired n F a arity) (v : Fin (n+F))\n    (old : Context) (extra : List ℕ) (p : ℕ)\n    (parent : Table (SemiprimeD1ChildTableOrder.acquire owner data v).old.length) : Result :=\n  let ports := SemiprimeD1ChildTableOrder.acquire owner data v\n  if (data.activation.bits[v.val]?).getD false then\n    let out := SemiprimeD1ChildTableCopy.acquire old extra p ports.child.length ⟨parent,0⟩ ports.order\n    ⟨ports.child.length,out.table,ports.clock+out.clock+5⟩\n  else\n    let out := unit ⟨extra++old.axes,p⟩\n    ⟨0,out.table,ports.clock+out.clock+5⟩\n\n/-- Inactive old vertices literally acquire a zero-port scalar-one table. -/\ntheorem fromCache_inactive {n F a : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (data : SemiprimeD1ChildPortPullback.Acquired n F a arity) (v : Fin (n+F))\n    (old : Context) (extra : List ℕ) (p : ℕ)\n    (parent : Table (SemiprimeD1ChildTableOrder.acquire owner data v).old.length)\n    (ha : (data.activation.bits[v.val]?).getD false=false) :\n    (fromCache owner data v old extra p parent).degree=0 ∧\n    HEq (fromCache owner data v old extra p parent).table (unit ⟨extra++old.axes,p⟩).table := by\n  have he : fromCache owner data v old extra p parent=\n      ⟨0,(unit ⟨extra++old.axes,p⟩).table,\n        (SemiprimeD1ChildTableOrder.acquire owner data v).clock+(unit ⟨extra++old.axes,p⟩).clock+5⟩ := by\n    dsimp only [fromCache]\n    rw [ha]\n    rfl\n  rw [he]\n  exact ⟨rfl,HEq.rfl⟩\n\n/-- Every resulting table has intrinsic canonical shape in the CURRENT child ring. -/\ntheorem fromCache_good {n F a : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (data : SemiprimeD1ChildPortPullback.Acquired n F a arity) (v : Fin (n+F))\n    (old : Context) (extra : List ℕ) (p : ℕ)\n    (parent : Table (SemiprimeD1ChildTableOrder.acquire owner data v).old.length)\n    (hp : Good old parent) (he : 0<extra.prod) :\n    Good ⟨extra++old.axes,p⟩ (fromCache owner data v old extra p parent).table := by\n  dsimp only [fromCache]\n  by_cases ha : (data.activation.bits[v.val]?).getD false=true\n  · rw [ha]\n    exact SemiprimeD1ChildTableCopy.acquire_good old extra p _ ⟨parent,0⟩ _ hp he\n  · have hf : (data.activation.bits[v.val]?).getD false=false := Bool.eq_false_iff.mpr ha\n    rw [hf]\n    exact unit_good _\n\n/-- Active copied entries read the original literal table in the computed cache order. -/\ntheorem fromCache_active_value {n F a : ℕ} {arity : Fin F→ℕ}\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (data : SemiprimeD1ChildPortPullback.Acquired n F a arity) (v : Fin (n+F))\n    (old : Context) (extra : List ℕ) (p : ℕ)\n    (parent : Table (SemiprimeD1ChildTableOrder.acquire owner data v).old.length)\n    (ha : (data.activation.bits[v.val]?).getD false=true)\n    (bits : List Bool) (hb : bits.length=(SemiprimeD1ChildTableOrder.acquire owner data v).child.length) :\n    (lookup (fromCache owner data v old extra p parent).table bits).words=\n      (SemiprimeD1ChildTableCopy.lift old extra p\n        (lookup parent (SemiprimeD1ChildTableCopy.gather bits\n          (SemiprimeD1ChildTableOrder.acquire owner data v).order).value).words).words := by\n  dsimp only [fromCache]\n  rw [ha]\n  exact SemiprimeD1ChildTableCopy.acquire_value old extra p _ ⟨parent,0⟩ _ bits hb\n\nend RiemannGaussian.SemiprimeD1ChildTensorTables\n","RiemannGaussian.SemiprimeD1CrossingModulo":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1CrossingResidue\n\n/-! # Actual scalar finite D.12 expansion modulo 2^p\nThe proof clears only odd denominators. Auxiliary fraction sums are proof\nwitnesses, not a proposed runtime denominator-product algorithm.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1CrossingModulo\nopen scoped BigOperators\nopen SemiprimeD1WireKernelFactors SemiprimeD1WireKernelEntry\n  SemiprimeD1WireKernelOriginal SemiprimeD1CrossingCoefficient\n  SemiprimeD1CrossingExpansion SemiprimeD1CrossingOriginal SemiprimeD1CrossingResidue\n\n/-- Integer-fraction addition used to witness a finite odd-localized sum. -/\ndef fractionAdd (a b : Coefficient) : Coefficient :=\n  ⟨a.numerator*b.denominator+b.numerator*a.denominator,a.denominator*b.denominator⟩\n\n/-- Addition of acquired odd fractions agrees with rational addition. -/\ntheorem fractionAdd_value (a b : Coefficient) (ha : Odd a.denominator)\n    (hb : Odd b.denominator) : value (fractionAdd a b)=value a+value b := by\n  have han : a.denominator≠0 := by intro h;rw [h] at ha;simp at ha\n  have hbn : b.denominator≠0 := by intro h;rw [h] at hb;simp at hb\n  have haq : (a.denominator:ℚ)≠0 := by exact_mod_cast han\n  have hbq : (b.denominator:ℚ)≠0 := by exact_mod_cast hbn\n  unfold value fractionAdd\n  simp only [Int.cast_add,Int.cast_mul]\n  field_simp\n\n/-- Exact finite odd-fraction addition respects actual unit-inverse residues. -/\ntheorem fractionAdd_residue (p : ℕ) (a b : Coefficient)\n    (ha : Odd a.denominator) (hb : Odd b.denominator) :\n    residue p (fractionAdd a b)=residue p a+residue p b := by\n  apply (odd_unit _ (ha.mul hb) p).mul_left_cancel\n  change ((fractionAdd a b).denominator:ZMod (2^p))*_= _\n  rw [residue_denominator p (fractionAdd a b) (ha.mul hb)]\n  simp only [fractionAdd,Int.cast_add,Int.cast_mul]\n  calc\n    _ = (b.denominator:ZMod (2^p))*((a.denominator:ZMod (2^p))*residue p a)+\n      (a.denominator:ZMod (2^p))*((b.denominator:ZMod (2^p))*residue p b) := by\n        rw [residue_denominator p a ha,residue_denominator p b hb]\n        ring\n    _ = _ := by ring\n\n/-- Finite odd-localized rational sums have consistent actual modular evaluations. -/\ntheorem finite_sum_witness {ι : Type*} (s : Finset ι) (f : ι → Coefficient)\n    (p : ℕ) (hf : ∀ b∈s,Odd (f b).denominator) :\n    ∃ c : Coefficient,Odd c.denominator ∧ value c=(∑ b∈s,value (f b)) ∧\n      residue p c=∑ b∈s,residue p (f b) := by\n  classical\n  induction s using Finset.induction_on with\n  | empty => exact ⟨⟨0,1⟩,by decide,by simp [value],by simp [residue]⟩\n  | @insert a s ha ih =>\n    obtain ⟨c,hc,hv,hr⟩ := ih (fun b hb => hf b (Finset.mem_insert_of_mem hb))\n    refine ⟨fractionAdd (f a) c,(hf a (by simp)).mul hc,?_,?_⟩\n    · rw [fractionAdd_value (f a) c (hf a (by simp)) hc,hv,Finset.sum_insert ha]\n    · rw [fractionAdd_residue p (f a) c (hf a (by simp)) hc,hr,Finset.sum_insert ha]\n\n/-- Multiplying an acquired fraction by an integer retains the same odd denominator. -/\ndef fractionScale (a : Coefficient) (j : ℤ) : Coefficient := ⟨a.numerator*j,a.denominator⟩\n\n/-- Scaling consistency is an exact identity over the odd-localized rationals. -/\ntheorem fractionScale_value (a : Coefficient) (j : ℤ) :\n    value (fractionScale a j)=value a*(j:ℚ) := by\n  simp only [value,fractionScale,Int.cast_mul]\n  ring\n\n/-- Scaling consistency uses actual integer cast and actual unit inverse modulo 2^p. -/\ntheorem fractionScale_residue (p : ℕ) (a : Coefficient) (j : ℤ) :\n    residue p (fractionScale a j)=residue p a*(j:ZMod (2^p)) := by\n  simp only [residue,fractionScale,Int.cast_mul]\n  ring\n\n/-- ORIGINAL scalar kernel D.12, with exactly b+1<p and positive tile powers.\nEvery mode and inverse is acquired from the original grid data. -/\ntheorem original_modulo (k center i j d tile p : ℕ) (z : ℤ)\n    (hc : center<2^k) (hj : j<2^k) (hd : d<2^k) (htile : d+2^(i+1)*tile<2^k)\n    (hi : i<k) (hne : d≠j) (hv : padicValInt 2 (difference j d)≤ i) (hp : 0<p) :\n    evaluate p (SemiprimeD1WireKernelEntry.acquire k center j (d+2^(i+1)*tile)) (z:ZMod (2^p))=\n      ∑ b∈Finset.range (p-1),\n        residue p (SemiprimeD1CrossingCoefficient.acquire k center i j d b z)*\n          (tile:ZMod (2^p))^b := by\n  let f := fun b => fractionScale (SemiprimeD1CrossingCoefficient.acquire k center i j d b z) ((tile:ℤ)^b)\n  obtain ⟨c,hco,hcv,hcr⟩ := finite_sum_witness (Finset.range (p-1)) f p\n    (fun b _ => acquire_odd k center i j d b z hc hj hd hne)\n  have he := expansion k center i j d (p-1) z tile hc hj hd hne hv\n  have hfo : Odd (remainder k center i j d (p-1) z tile).denominator :=\n    (target_remainder_odd k center i j d (p-1) z tile hc hj hd hne hv).2\n  have heq : value (target k center i j d z tile)=\n      value (fractionAdd c (remainder k center i j d (p-1) z tile)) := by\n    rw [fractionAdd_value c _ hco hfo,hcv]\n    simpa only [f,fractionScale_value,Int.cast_pow,Int.cast_natCast] using he\n  have hz := residue_eq_of_value_eq p (target k center i j d z tile)\n    (fractionAdd c (remainder k center i j d (p-1) z tile))\n    (target_remainder_odd k center i j d (p-1) z tile hc hj hd hne hv).1 (hco.mul hfo) heq\n  rw [fractionAdd_residue p c _ hco hfo,\n    (strict_remainder_zero k center i j d tile p z hc hj hd hi hne hv hp).2,\n    add_zero,hcr] at hz\n  rw [← target_residue_original k center i j d tile p z hc hj hd htile hne hv,hz]\n  apply Finset.sum_congr rfl\n  intro b _\n  simp only [f,fractionScale_residue,Int.cast_pow,Int.cast_natCast]\n\nend RiemannGaussian.SemiprimeD1CrossingModulo\n","RiemannGaussian.SemiprimeD1GridLevelSum":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1GridRawSum\nimport RiemannGaussian.SemiprimeD1InvolutionRegroup\n\n/-! # Actual D.10 complete-grid regrouping and tapered precision loss -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1GridLevelSum\nopen scoped BigOperators\nopen SemiprimeD1GridValuation SemiprimeD1GridResidue SemiprimeD1GridHistogram\n  SemiprimeD1GridRawSum SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss\n  SemiprimeD1JetRecoveryGrid\n\n/-- Regrouping uses the actual finite reflection, not a supplied valuation histogram. -/\ntheorem residue_regroup (k h u : ℕ) (t : ZMod (2^k)) (ht : t≠0) :\n    residueValuation k h u t=\n      ∑ x∈residueOthers k t,if order k t<order k x then\n        ((multiplicity h u (order k x):ℤ)-(multiplicity h u (order k t):ℤ))*\n          ((order k x:ℤ)-(order k t:ℤ)) else 0 := by\n  unfold residueValuation\n  apply SemiprimeD1InvolutionRegroup.regroup (residueOthers k t) (fun x => t-x) (order k)\n    (fun v => (multiplicity h u v:ℤ)) (order k t)\n  · intro x hx\n    exact (residue_reflect k t x).mp hx\n  · intro x _\n    simp\n  · intro x hx hl\n    have hxn := ((residue_membership k t x).mp hx).1\n    have hneq : order k t≠order k x := by omega\n    rw [order_sub_of_ne k t x ht hxn hneq]\n    exact Nat.min_eq_right hl.le\n  · intro x hx hh\n    have hxn := ((residue_membership k t x).mp hx).1\n    have hneq : order k t≠order k x := by omega\n    rw [order_sub_of_ne k t x ht hxn hneq]\n    exact Nat.min_eq_left hh.le\n\n/-- Exact summation over actual high residue levels, counting each literal grid value. -/\ntheorem high_level_sum (k i : ℕ) (t : ZMod (2^k)) (ht : t≠0)\n    (hi : order k t=i) (f : ℕ→ℤ) :\n    (∑ x∈residueOthers k t,if i<order k x then f (order k x) else 0)=\n      ∑ v∈Finset.range k,if i<v then (2^(k-v-1):ℤ)*f v else 0 := by\n  let S : Finset (ZMod (2^k)) := Finset.univ.erase 0\n  let g := fun x : ZMod (2^k) => if i<order k x then f (order k x) else 0\n  have hmem : t∈S := Finset.mem_erase.mpr ⟨ht,Finset.mem_univ _⟩\n  have he := Finset.sum_erase_add S g hmem\n  have hgt : g t=0 := by simp only [g,hi,lt_self_iff_false,ite_false]\n  rw [hgt,add_zero] at he\n  change (∑ x∈S.erase t,g x)=_\n  rw [he]\n  have hm : ∀ x∈S,order k x∈Finset.range k := by\n    intro x hx\n    exact Finset.mem_range.mpr (order_lt k x (Finset.mem_erase.mp hx).1)\n  rw [← Finset.sum_fiberwise_of_maps_to hm g]\n  apply Finset.sum_congr rfl\n  intro v hv\n  have hvk := Finset.mem_range.mp hv\n  have hset : S.filter (fun x => order k x=v)=residueLevel k v := by\n    ext x\n    simp [S,residueLevel]\n  rw [hset]\n  have hg : (∑ x∈residueLevel k v,g x)=\n      ∑ _x∈residueLevel k v,if i<v then f v else 0 := by\n    apply Finset.sum_congr rfl\n    intro x hx\n    obtain ⟨_,_,hxv⟩ := Finset.mem_filter.mp hx\n    simp only [g,hxv]\n  rw [hg,Finset.sum_const,nsmul_eq_mul,residueLevel_card k v hvk]\n  by_cases hiv : i<v <;> simp only [hiv,ite_true,ite_false,mul_zero]\n  rfl\n\n/-- The actual high-level count sum is the original D.10 level expression. -/\ntheorem levels_eq_taper (a h u i : ℕ) (hi : i≤a) :\n    (∑ v∈Finset.range (a+1),if i<v then (2^(a+1-v-1):ℤ)*\n      (((multiplicity h u v:ℤ)-(multiplicity h u i:ℤ))*((v:ℤ)-(i:ℤ))) else 0)=\n      levelValuation h u i (a-i) := by\n  rw [← Finset.sum_filter]\n  have hs : (Finset.range (a+1)).filter (fun v => i<v)=Finset.Ico (i+1) (a+1) := by\n    ext v\n    simp only [Finset.mem_filter,Finset.mem_range,Finset.mem_Ico]\n    omega\n  rw [hs,Finset.sum_Ico_eq_sum_range]\n  have he : a+1-(i+1)=a-i := by omega\n  rw [he]\n  unfold levelValuation\n  apply Finset.sum_congr rfl\n  intro j hj\n  have hjn := Finset.mem_range.mp hj\n  have hex : a+1-(i+1+j)-1=(a-i)-(j+1) := by omega\n  have hidx : i+1+j=i+(j+1) := by omega\n  rw [hex,hidx]\n  push_cast\n  ring\n\n/-- Complete actual D.10 identity for the original signed grid and taper. -/\ntheorem original_D10 (a h u : ℕ) (t : Fin (size a)) (ht : point a t.val≠0) :\n    padicValRat 2 (Ezero a h u t.val)=\n      levelValuation h u (padicValInt 2 (point a t.val))\n        (a-padicValInt 2 (point a t.val)) := by\n  have htc : t.val≠center a := (not_congr (point_zero_iff a t.val)).mp ht\n  have hz : gridEquiv a t≠0 := by intro he;exact htc ((gridEquiv_zero_iff a t).mp he)\n  have ho := original_order a t htc\n  have hil : padicValInt 2 (point a t.val)≤a := by\n    have h := order_lt (a+1) (gridEquiv a t) hz\n    rw [ho] at h\n    omega\n  rw [Ezero_valuation,original_raw_sum,residue_regroup (a+1) h u _ hz]\n  rw [high_level_sum (a+1) (order (a+1) (gridEquiv a t)) (gridEquiv a t) hz rfl\n    (fun v => ((multiplicity h u v:ℤ)-(multiplicity h u (order (a+1) (gridEquiv a t)):ℤ))*\n      ((v:ℤ)-(order (a+1) (gridEquiv a t):ℤ)))]\n  rw [ho]\n  exact levels_eq_taper a h u _ hil\n\n/-- Original tapered precision-loss bound, with NO valuation/precision advice. -/\ntheorem original_D10_lower (a M u : ℕ) (t : Fin (size a)) (ht : point a t.val≠0) :\n    -(6:ℤ)*(2:ℤ)^(a-padicValInt 2 (point a t.val))*(height M u:ℤ)≤\n      padicValRat 2 (Ezero a (height M u) u t.val) := by\n  rw [original_D10 a (height M u) u t ht]\n  exact levelValuation_lower _ _ _ _\n\nend RiemannGaussian.SemiprimeD1GridLevelSum\n","RiemannGaussian.SemiprimeD1HermiteWeightBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1HermiteWeightHeight\n\n/-! # Actual original scalar-weight polynomial logarithmic heights\nBoth the stored weights and every defined coefficient-sum prefix have explicit\noriginal-derived dyadic caps. A full-grid weight-denominator product is also\nacquired and bounded, without multiplying denominators recursively at each sum.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1HermiteWeightBits\nopen scoped BigOperators\nopen SemiprimeJetArray SemiprimeJetArrayHeight SemiprimeD1WireKernelOriginal\n  SemiprimeD1TaperedLoss SemiprimeD1JetRecoveryGrid SemiprimeD1JetRecoveryWeights\n  SemiprimeD1HermiteNodes SemiprimeD1WeightPrecision\n  SemiprimeD1HermiteDenominatorHeight SemiprimeD1HermiteDenominatorBits\n  SemiprimeD1HermiteWeightHeight\n\n/-- Original-derived logarithmic cap covering all retained weight scalars at one node. -/\ndef weightExponent (a h u t : ℕ) : ℕ :=\n  SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u+nodeMultiplicity a h u t+\n    inverseExponent a h u t+(a+1)*nodeMultiplicity a h u t+1\n\n/-- Actual raw E_t0 scalar products have the earlier original dyadic bound. -/\ntheorem scalar_bounds (a h u : ℕ) (t : Fin (size a)) :\n    scalarNumerator a h u t.val≤2^SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u ∧\n    scalarDenominator a h u t.val≤2^SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u :=\n  SemiprimeD1JetRecoveryScalarHeight.original_dyadic_height a h u t\n\n/-- The actual LOCAL weight common denominator and numerator envelope have\npolynomial logarithmic heights, derived from ORIGINAL data alone. -/\ntheorem weight_bounds (a h u : ℕ) (t : Fin (size a)) :\n    weightDenominator a h u t.val≤2^weightExponent a h u t.val ∧\n    weightNumerator a h u t.val≤2^weightExponent a h u t.val := by\n  have hs := scalar_bounds a h u t\n  have hi := inverse_power_bounds a h u t\n  let q := nodeMultiplicity a h u t.val\n  have hq : q≤2^q := self_le_two_power q\n  have hN : (size a)^q=2^((a+1)*q) := by rw [SemiprimeD1WireKernelOriginal.size,← pow_mul]\n  constructor\n  · unfold weightDenominator\n    rw [mul_pow,hN]\n    calc\n      _ ≤ 2^SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u*\n          (2^inverseExponent a h u t.val*2^((a+1)*q)) := Nat.mul_le_mul hs.2 (Nat.mul_le_mul_right _ hi.1)\n      _ = 2^(SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u+inverseExponent a h u t.val+(a+1)*q) := by\n        simp only [← pow_add,Nat.add_assoc]\n      _ ≤ _ := Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (by unfold weightExponent;dsimp [q];omega)\n  · unfold weightNumerator\n    rw [mul_pow,hN]\n    calc\n      _ ≤ (2^SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u*2^q)*\n          (2^inverseExponent a h u t.val*2^((a+1)*q)) :=\n        Nat.mul_le_mul (Nat.mul_le_mul hs.1 hq) (Nat.mul_le_mul_right _ hi.2)\n      _ = 2^(SemiprimeD1JetRecoveryScalarHeight.bitExponent a h u+q+inverseExponent a h u t.val+(a+1)*q) := by\n        simp only [← pow_add,Nat.add_assoc]\n      _ ≤ _ := Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (by unfold weightExponent;dsimp [q];omega)\n\n/-- ACTUAL acquired weight normalization cannot exceed the original dyadic caps. -/\ntheorem original_weight_bits (a h u : ℕ) (t : Fin (size a))\n    (hq : 0< nodeMultiplicity a h u t.val) (j : ℕ) (hj : j< nodeMultiplicity a h u t.val) :\n    (coefficient (acquire a h u t.val).weights j).den≤2^weightExponent a h u t.val ∧\n    (coefficient (acquire a h u t.val).weights j).num.natAbs≤2^weightExponent a h u t.val := by\n  have hr := representation_reduced_bound (weightDenominator_pos a h u t.val)\n    (weight_representation a h u t hq j hj)\n  have hb := weight_bounds a h u t\n  exact ⟨hr.1.trans hb.1,hr.2.trans hb.2⟩\n\n/-- Every actual defined weight coefficient-sum prefix has the same logarithmic cap. -/\ntheorem original_weight_prefix_bits (a h u : ℕ) (t : Fin (size a))\n    (hq : 0< nodeMultiplicity a h u t.val) (j len : ℕ) (hlen : len≤ nodeMultiplicity a h u t.val) :\n    (weightPrefix a h u t.val j len).den≤2^weightExponent a h u t.val ∧\n    (weightPrefix a h u t.val j len).num.natAbs≤2^weightExponent a h u t.val := by\n  have hr := prefix_reduced_bounds a h u t hq j len hlen\n  have hb := weight_bounds a h u t\n  exact ⟨hr.1.trans hb.1,hr.2.trans hb.2⟩\n\n/-- Fixed original a,M,2L polynomial envelope for EVERY scalar weight at any node. -/\ndef weightEnvelope (a M : ℕ) : ℕ :=\n  4*(a+1)*size a*M+4*M+inverseEnvelope a M+4*(a+1)*M+1\n\n/-- Original taper substitution yields a FIXED polynomial logarithmic envelope. -/\ntheorem original_weightExponent_le (a M u t : ℕ) (hM : u≤ M) :\n    weightExponent a (height M u) u t≤ weightEnvelope a M := by\n  have hq := nodeMultiplicity_le a M u t hM\n  have hi := original_inverseExponent_le a M u t hM\n  have hhu := height_mul_le M u hM\n  have hE : SemiprimeD1JetRecoveryScalarHeight.bitExponent a (height M u) u≤4*(a+1)*size a*M := by\n    unfold SemiprimeD1JetRecoveryScalarHeight.bitExponent\n    nlinarith [Nat.mul_le_mul_left ((a+1)*size a) hhu]\n  have hmul := Nat.mul_le_mul_left (a+1) hq\n  unfold weightExponent weightEnvelope\n  nlinarith\n\n/-- ACTUAL finite common denominator of all acquired scalar weights on the original grid. -/\ndef globalDenominator (a M u : ℕ) : ℕ :=\n  ∏t∈active a (height M u) u,∏j∈Finset.range (nodeMultiplicity a (height M u) u t),\n    (coefficient (acquire a (height M u) u t).weights j).den\n\n/-- The full original weight common denominator is positive, not an advised value. -/\ntheorem globalDenominator_pos (a M u : ℕ) : 0< globalDenominator a M u := by\n  unfold globalDenominator\n  apply Finset.prod_pos\n  intro t _\n  apply Finset.prod_pos\n  intro j _\n  exact Rat.den_pos _\n\n/-- Even the product of ALL actual scalar weight denominators has polynomial\nlogarithmic height in original a,M,2L. -/\ntheorem globalDenominator_bound (a M u : ℕ) (hM : u≤ M) :\n    globalDenominator a M u≤2^(weightEnvelope a M*(4*M)*size a) := by\n  have hlocal (t : ℕ) (ht : t∈active a (height M u) u) :\n      (∏j∈Finset.range (nodeMultiplicity a (height M u) u t),\n        (coefficient (acquire a (height M u) u t).weights j).den)≤2^(weightEnvelope a M*(4*M)) := by\n    have htn : t< size a := Finset.mem_range.mp (Finset.mem_filter.mp ht).1\n    let tt : Fin (size a) := ⟨t,htn⟩\n    have hq := active_positive a (height M u) u t ht\n    have hbound : ∀j∈Finset.range (nodeMultiplicity a (height M u) u t),\n        (coefficient (acquire a (height M u) u t).weights j).den≤2^weightEnvelope a M := by\n      intro j hj\n      exact (original_weight_bits a (height M u) u tt hq j (Finset.mem_range.mp hj)).1.trans\n        (Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (original_weightExponent_le a M u t hM))\n    have hp := Finset.prod_le_prod hbound\n    simp only [Finset.prod_const,Finset.card_range] at hp\n    apply hp.trans\n    rw [← pow_mul]\n    exact Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (Nat.mul_le_mul_left _ (nodeMultiplicity_le a M u t hM))\n  have hp := Finset.prod_le_prod hlocal\n  have hc : (active a (height M u) u).card≤ size a :=\n    (Finset.card_filter_le _ _).trans (by simp)\n  simp only [Finset.prod_const] at hp\n  apply hp.trans\n  rw [← pow_mul]\n  exact Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (Nat.mul_le_mul_left _ hc)\n\n/-- Pure polynomial in independent original dimensions; N is the acquired2L grid size. -/\ndef inversePolynomial (a M N : ℕ) : ℕ :=\n  4*M*(4*M+4*(a+1)*N*M+4*(4*M+a+1)*N*M+3)\n\n/-- Pure original-dimension polynomial for the local scalar weight logarithm. -/\ndef weightPolynomial (a M N : ℕ) : ℕ :=\n  4*(a+1)*N*M+4*M+inversePolynomial a M N+4*(a+1)*M+1\n\n/-- The actual envelope is the polynomial evaluated at the ACTUAL original grid size. -/\ntheorem weightEnvelope_eq (a M : ℕ) : weightEnvelope a M=weightPolynomial a M (size a) := rfl\n\n/-- Pure finite arithmetic monotonicity, separate from semantic/runtime contexts. -/\ntheorem weightPolynomial_mono {a M N A B D : ℕ} (ha : a≤A) (hM : M≤B) (hN : N≤D) :\n    weightPolynomial a M N≤weightPolynomial A B D := by\n  unfold weightPolynomial inversePolynomial\n  gcongr\n\n/-- Literal fixed polynomial controlling the ALL-weight common-denominator bit length. -/\ndef polynomialEnvelope (S : ℕ) : ℕ := weightPolynomial S S S*(4*S)*S\n\n/-- Explicit fixed monomial, not merely an assertion that the envelope is polynomial. -/\ntheorem polynomialEnvelope_bound (S : ℕ) : polynomialEnvelope S≤1000*(S+1)^6 := by\n  unfold polynomialEnvelope weightPolynomial inversePolynomial\n  nlinarith [Nat.zero_le (S^2),Nat.zero_le (S^3),Nat.zero_le (S^4),Nat.zero_le (S^5),Nat.zero_le (S^6)]\n\n/-- Actual ORIGINAL denominator-product dyadic bound under only original dimension caps.\nThe cap on2L is essential; no exponential2^S width is substituted for an acquired dimension. -/\ntheorem original_globalDenominator_bits (a M u S : ℕ) (hM : u≤M)\n    (ha : a≤S) (hm : M≤S) (hN : size a≤S) :\n    globalDenominator a M u≤2^polynomialEnvelope S := by\n  apply (globalDenominator_bound a M u hM).trans\n  apply Nat.pow_le_pow_right (by decide : 0<(2:ℕ))\n  rw [weightEnvelope_eq]\n  unfold polynomialEnvelope\n  exact Nat.mul_le_mul (Nat.mul_le_mul (weightPolynomial_mono ha hm hN)\n    (Nat.mul_le_mul_left 4 hm)) hN\n\nend RiemannGaussian.SemiprimeD1HermiteWeightBits\n","RiemannGaussian.SemiprimeD1HybridPathDecay":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecursiveCallPath\n\n/-! # Factor-sixteen decay along every actual recursive child\nThe original stored-degree and packing hypotheses already prove the stronger\nshrink. This file preserves all actual grid/mode/group choices and inherits\nshape from the unchanged controller. It changes analysis, not the program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1HybridPathDecay\nopen SemiprimeD1JetAxes SemiprimeD1TensorNetwork SemiprimeD1RecursiveCounter\nopen SemiprimeD1RecursiveCallTree SemiprimeD1RecursiveCallState\nopen SemiprimeD1TensorNetworkRecursion (DegreeBound)\nopen SemiprimeD1Schedule SemiprimeD1WireKernelOriginal\nattribute [local irreducible] SemiprimeD1OriginalModeAcquisition.acquire\n\n/-- The literal child rows satisfy the original factor-sixteen theorem. -/\ntheorem child_shrink_sixteen (parent : Call) (a u degree : ℕ)\n    (t : Fin (size a)) (i : Fin a) (beta : List ℕ) (g : Fin 64)\n    (hw : WellFormed parent.net) (hd : DegreeBound parent.net degree)\n    (hsmall : 2*(64^(2*a))^2*degree ≤ edgeCount parent.net) :\n    edgeCount (child parent a u t i beta g).net*16 ≤ edgeCount parent.net := by\n  change scope (child parent a u t i beta g).net.rows*16 ≤ _\n  rw [child_rows]\n  rw [Nat.mul_comm]\n  exact SemiprimeD1TensorNetworkRecursion.child_shrink parent.net hw degree a hd hsmall i g\n\n/-- Eventual original-scale packing pays factor-sixteen shrink for every member\nof the actual child list, with no selected-mode or supplied-size premise. -/\ntheorem eventually_mem_children_shrink : ∀ᶠ s : ℕ in Filter.atTop,\n    ∀ parent next : Call, next ∈ children s parent → WellFormed parent.net →\n      DegreeBound parent.net (SemiprimeD1PackingReady.degreeCap s) →\n      edgeCount next.net*16 ≤ edgeCount parent.net := by\n  filter_upwards [SemiprimeD1PackingReady.eventually_all_depths] with s hs\n  intro parent next hm hw hd\n  obtain ⟨ha,t,ht⟩ := (mem_children s parent next).mp hm\n  obtain ⟨hi,beta,_,g,rfl⟩ := (mem_phaseChildren parent _ _ t next).mp ht\n  have hactive := (activeTest_correct _ _ _ _).mp ha\n  have hpacking := hs parent.depth (edgeCount parent.net) _ hactive le_rfl\n  exact child_shrink_sixteen parent _ _ _ t _ beta g hw hd hpacking.1.le\n\n/-- All genuinely reachable calls satisfy factor-sixteen scaled decay, under\nexactly the old root-state assumptions. The precision and degree invariants\nare reused without altering their statements or any source program. -/\ntheorem eventually_reach_sixteen : ∀ᶠ s : ℕ in Filter.atTop,\n    ∀ root next : Call, root.depth=0 → edgeCount root.net ≤ s → root.ctx.precision ≤ s →\n      root.ctx.Positive → WellFormed root.net → Good root.ctx root.net →\n      DegreeBound root.net (SemiprimeD1PackingReady.degreeCap s) → Reach s root next →\n      edgeCount next.net*16^next.depth ≤ s := by\n  filter_upwards [SemiprimeD1HybridPathDecay.eventually_mem_children_shrink,\n    SemiprimeD1RecursiveCallPath.eventually_reach_invariant] with s hshrink hinv\n  intro root next hroot hM hp hpos hw hg hd hr\n  induction hr with\n  | root => simpa only [hroot,pow_zero,Nat.mul_one] using hM\n  | @step parent next hr hm ih =>\n    have hshape := reach_shape s root parent hr hpos hw hg\n    have hdegree := (hinv root parent hroot hM hp hpos hw hg hd hr).1\n    have hsh := hshrink parent next hm hshape.2.1 hdegree\n    rw [mem_children_depth s parent next hm,pow_succ]\n    calc\n      _ = (edgeCount next.net*16)*16^parent.depth := by ring\n      _ ≤ edgeCount parent.net*16^parent.depth := Nat.mul_le_mul_right _ hsh\n      _ ≤ s := ih\n\nend RiemannGaussian.SemiprimeD1HybridPathDecay\n","RiemannGaussian.SemiprimeD1IncidenceAcquisitionBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1IncidenceAcquisition\nimport RiemannGaussian.SemiprimeD1SelectedLoadBounds\n\n/-! # Original-data report and persistent-state bounds for D1 acquisition\nNo prefix, key width, frequency, report or cache advice is supplied. Persistent\ntrie size is distinguished from the still-open full auxiliary machine heap.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1IncidenceAcquisitionBounds\nopen scoped BigOperators\nopen SemiprimeD1IncidenceAcquisition SemiprimeD1CollisionOriginal\nopen SemiprimeSourceHistogramPortKeys SemiprimeSourceHistogramFeatureBits\nopen SemiprimeSourceHistogramTrie SemiprimeSourceHistogramTrieBounds\n\n/-- Original setup, all selection queries, one final prefix and selected-key trie. -/\ndef budget (n F r a M : ℕ) : ℕ :=\n  SemiprimeSourceHistogramSearchBudget.budget n F r a 0 M (r^a)+\n    SemiprimeSourceHistogramQueryBounds.prefixBudget (r^a) (n+F)+\n    SemiprimeSourceHistogramFeatureBitsBounds.budget (n+F) (r^a) M+n+F+10\n\n/-- Actual selected original pair-key state retains every producer report. -/\ntheorem acquire_work (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquire n F r a arity owner).state.clock≤budget n F r a (∑e,arity e) := by\n  let fixed := (SemiprimeD1IncidenceSearch.run n F r a arity owner).value\n  let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n  have hv := SemiprimeD1IncidenceSearch.run_valid n F r a arity owner\n  have hp := SemiprimeSourceHistogramQueryBounds.prefix_clock r a fixed hv\n  rw [SemiprimeD1IncidenceSearch.run_length] at hp\n  have hf := SemiprimeSourceHistogramFeatureBitsBounds.acquirePorts_clock owner\n    (ports n F a arity) dict fixed.length 0 2 2 (r^a)\n    (SemiprimeSourceHistogramPrefix.stored_compact fixed)\n    (SemiprimeSourceHistogramDictRefinement.count_cap r a fixed hv)\n  have hM : (ports n F a arity).length=∑e,arity e :=\n    (SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.1\n  rw [hM] at hf\n  have hs := SemiprimeD1IncidenceSearchBudget.run_work n F r a arity owner\n  rw [SemiprimeD1IncidenceAcquisition.acquire_clock,SemiprimeD1IncidenceSearch.run_length]\n  rw [SemiprimeSourceHistogramSetup.records_actual]\n  dsimp only [fixed,dict] at hp hf\n  rw [SemiprimeD1IncidenceSearch.run_length] at hf\n  dsimp only [ports] at hf\n  unfold budget\n  omega\n\n/-- Every actual pair key has original logarithmic variable/palette width. -/\ntheorem key_length (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ∀ key∈(acquire n F r a arity owner).keys,\n      key.length≤3*SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) (r^a)+1 := by\n  let fixed := (select n F r a arity owner).ids\n  let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n  have hv : SemiprimeSourceWordIdControl.InMenu\n      (SemiprimeSourceCompactWordBank.acquire r a).ids fixed :=\n    SemiprimeD1IncidenceSearch.run_valid n F r a arity owner\n  have hc := SemiprimeSourceHistogramPrefix.stored_compact fixed\n  have hp := SemiprimeSourceHistogramDictRefinement.count_cap r a fixed hv\n  change ∀key∈(produce dict fixed.length 0 2 2\n    (select n F r a arity owner).cache.data.records).value,_\n  rw [select_cache,SemiprimeSourceHistogramSetup.records_actual]\n  exact SemiprimeSourceHistogramFeatureBitsBounds.produce_key_length dict fixed.length 0 2 2\n    (SemiprimeSourceHistogramPortKeys.acquirePorts owner (ports n F a arity)).value\n    (n+F) (r^a) (acquirePorts_rep owner _) hc hp\n\n/-- Exact persistent-node bound from the actual acquired pair-key stream.\nThis is not a theorem about all recursion frames or machine addresses. -/\ntheorem nodes_bound (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    nodes (acquire n F r a arity owner).state.trie≤\n      (∑e,arity e)*(3*SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) (r^a)+2) := by\n  have h := SemiprimeSourceHistogramSquaresBounds.acquire_nodes\n    (acquire n F r a arity owner).keys\n    (3*SemiprimeSourceHistogramFeatureBitsBounds.width (n+F) (r^a)+1)\n    (key_length n F r a arity owner)\n  have hl : (acquire n F r a arity owner).keys.length=∑e,arity e := by\n    rw [keys_original,List.length_map]\n    exact (SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.1\n  rw [hl] at h\n  exact h\n\n/-- The actual final stream contains exactly one key per original incidence. -/\ntheorem keys_length (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (acquire n F r a arity owner).keys.length=∑e,arity e := by\n  rw [keys_original,List.length_map]\n  exact (SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.1\n\n/-- Every actual stored frequency payload has original logarithmic width.\nThis unconditional cap suffices for the physical maximum's copy/compare clock. -/\ntheorem stored_length (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (key : List Bool) :\n    (stored (acquire n F r a arity owner).state.trie key).length≤\n      Nat.clog 2 ((∑e,arity e)+1) := by\n  have hg := acquire_good n F r a arity owner\n  have hc := SemiprimeSourceCompactBits.compact_length_clog _ (hg.2.2.1 key)\n  have hv : (acquire n F r a arity owner).keys.count key≤∑e,arity e := by\n    calc\n      _ ≤ (acquire n F r a arity owner).keys.length := List.count_le_length\n      _ = _ := keys_length n F r a arity owner\n  have he : SemiprimeBitArithmetic.bitValue (stored (acquire n F r a arity owner).state.trie key)=\n      (acquire n F r a arity owner).keys.count key := hg.1 key\n  rw [he] at hc\n  exact hc.trans (Nat.clog_mono_right 2 (Nat.add_le_add_right hv 1))\n\n/-- Actual original graph guarantees the floor cap for EVERY raw trie key.\nAll semantic label/load premises are discharged by the acquired greedy selector;\nonly original degree and D.3 numerical hypotheses remain. -/\ntheorem original_countCap (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (Δ : ℕ)\n    (ho : ∀ i∈ports n F a arity,\n      SemiprimeSourceHistogramGrouping.multiplicity (fun i => (owner i).val)\n        (ports n F a arity) (owner i).val≤Δ)\n    (hf : ∀ i∈ports n F a arity,\n      SemiprimeSourceHistogramGrouping.multiplicity (fun i => n+i.1.val)\n        (ports n F a arity) (n+i.1.val)≤Δ)\n    (hsmall : 2*(r^(2*a))^2*Δ≤(ports n F a arity).length) :\n    CountCap (acquire n F r a arity owner).state.trie\n      (2*(ports n F a arity).length/r^(2*a)) := by\n  apply countCap_of_load n F r a arity owner\n  intro label\n  apply (Nat.le_div_iff_mul_le (pow_pos (NeZero.pos r) (2*a))).mpr\n  simpa only [Nat.mul_comm] using\n    SemiprimeD1SelectedLoadBounds.selected_load_nat_le n F r a arity owner Δ ho hf hsmall label\n\nend RiemannGaussian.SemiprimeD1IncidenceAcquisitionBounds\n","RiemannGaussian.SemiprimeD1InverseIntegral":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1DyadicBounds\n\n/-! # Integrality of the ACTUAL original local denominator and cached inverse\nAll bounds come from original grid differences and the executed coefficient\nrecurrences. No desired inverse, integrality or intermediate-fit premise is used.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1InverseIntegral\nopen scoped BigOperators\nopen Polynomial SemiprimeD1DyadicBounds SemiprimeD1WireKernelFactors\n  SemiprimeD1WireKernelOriginal SemiprimeD1JetRecoveryGrid SemiprimeD1JetRecoveryWeights\n  SemiprimeJetArray SemiprimeJetRecurrence SemiprimeHermiteArrayHeight\n\n/-- Every stored/default coefficient of a concrete rational array is integral. -/\ndef IntegralArray (a : Array ℚ) : Prop := ∀i,AtLeast 0 (coefficient a i)\n\n/-- The actual constant1 coefficient array has integral default coefficients too. -/\ntheorem unitArray_integral : IntegralArray #[1] := by\n  intro i\n  by_cases hi : i=0\n  · subst i\n    simpa [coefficient] using one\n  · rw [coefficient_zero (by simp only [Array.size_singleton];omega)]\n    exact zero 0\n\n/-- Literal affine coefficient arrays inherit their actual scalar integrality. -/\ntheorem affineArray_integral (c : ℚ) (hc : AtLeast 0 c) : IntegralArray (affineArray c) := by\n  intro i\n  cases i with\n  | zero => simpa [coefficient,affineArray] using one\n  | succ i =>\n    cases i with\n    | zero => simpa [coefficient,affineArray] using hc\n    | succ i =>\n      rw [coefficient_zero (by simp [affineArray])]\n      exact zero 0\n\n/-- Every executed truncated convolution coefficient is integral, including zeros\noutside the stored output width. -/\ntheorem multiply_integral (a b : Array ℚ) (J : ℕ) (ha : IntegralArray a) (hb : IntegralArray b) :\n    IntegralArray (multiply a b J).coefficients := by\n  intro i\n  by_cases hi : i<J\n  · rw [multiply_coefficient a b J i hi]\n    apply SemiprimeD1DyadicBounds.sum\n    intro j _\n    simpa only [add_zero] using mul (ha j) (hb (i-j))\n  · rw [coefficient_zero (by rw [multiply_size];omega)]\n    exact zero 0\n\n/-- The original affine builder preserves integrality at every actual recursive suffix. -/\ntheorem buildAffine_integral (J : ℕ) (cs : List ℚ) (hc : ∀c∈cs,AtLeast 0 c) :\n    IntegralArray (buildAffine J cs).coefficients := by\n  induction cs with\n  | nil => exact unitArray_integral\n  | cons c cs ih =>\n    exact multiply_integral _ _ J (ih (fun x hx => hc x (List.mem_cons_of_mem _ hx)))\n      (affineArray_integral c (hc c (by simp)))\n\n/-- Exact recurrence integrality is derived from its ACTUAL constant1 and input coefficients. -/\ntheorem inverseCoeff_integral (a : ℕ→ℚ) (ha : ∀i,AtLeast 0 (a i)) (h0 : a 0=1) (n : ℕ) :\n    AtLeast 0 (inverseCoeff a n) := by\n  induction n using Nat.strong_induction_on with\n  | h n ih =>\n    cases n with\n    | zero => simpa only [inverseCoeff,h0,inv_one] using one\n    | succ n =>\n      rw [inverseCoeff,h0,inv_one,neg_one_mul]\n      apply neg\n      apply SemiprimeD1DyadicBounds.sum\n      intro i hi\n      simpa only [add_zero] using mul (ha (i+1)) (ih (n-i) (by omega))\n\n/-- Actual cached inverse arrays are integral from the original input recurrence,\nnot an inverse coefficient/height oracle. -/\ntheorem inverse_integral (a : Array ℚ) (J : ℕ) (ha : IntegralArray a) (h0 : coefficient a 0=1) :\n    IntegralArray (SemiprimeJetArray.inverse a J).coefficients := by\n  intro i\n  by_cases hi : i<J\n  · rw [inverse_coefficient a J i hi]\n    exact inverseCoeff_integral _ ha h0 i\n  · rw [coefficient_zero (by rw [inverse_size];omega)]\n    exact zero 0\n\n/-- Each ACTUAL original-grid slope has one dyadic factor before taking inverse jets. -/\ntheorem original_slope (a h u : ℕ) (t : Fin (size a)) (c : ℚ)\n    (hc : c∈slopes a h u t.val) : AtLeast 1 c := by\n  obtain ⟨q,hqr,hc⟩ := List.mem_flatMap.mp hc\n  have hq : q<2^(a+1) := List.mem_range.mp hqr\n  by_cases hex : q=SemiprimeD1WireKernelOriginal.center a ∨ q=t.val\n  · simp only [hex,ite_true,List.not_mem_nil] at hc\n  · simp only [hex,ite_false,List.mem_replicate] at hc\n    obtain ⟨_,rfl⟩ := hc\n    have hqt : q≠t.val := fun he => hex (Or.inr he)\n    have hd : (point a t.val:ℚ)-(point a q:ℚ)≠0 := by\n      exact_mod_cast point_sub_ne_zero a t.val q hqt\n    have hα : (((2:ℤ)^(a+1)):ℚ)≠0 := by positivity\n    have hv := difference_order_lt (a+1) t.val q t.isLt hq hqt\n    have he : point a t.val-point a q=difference t.val q := by unfold point difference;ring\n    apply Or.inr\n    rw [padicValRat.div hα hd]\n    have hn : padicValRat 2 ((((2:ℤ)^(a+1)):ℚ))=(a+1:ℤ) := by\n      have htwo : padicValRat 2 (2:ℚ)=1 := padicValRat.self (p:=2) (by decide)\n      simp only [Int.cast_ofNat,padicValRat.pow,htwo,mul_one,Nat.cast_add,Nat.cast_one]\n\n    have hden : (point a t.val:ℚ)-(point a q:ℚ)=((point a t.val-point a q:ℤ):ℚ) := by push_cast;rfl\n    rw [hn,hden,SemiprimeD1JetRecoveryGrid.int_valuation,he]\n    omega\n\n/-- Integrality of the ACTUAL acquired local denominator is derived from original grid data. -/\ntheorem acquire_denominator_integral (a h u : ℕ) (t : Fin (size a)) :\n    IntegralArray (acquire a h u t.val).denominator.coefficients := by\n  apply buildAffine_integral\n  intro c hc\n  exact mono (original_slope a h u t c hc) (by omega)\n\n/-- Integrality of every ACTUAL acquired inverse coefficient, with no output-fit advice. -/\ntheorem acquire_inverse_integral (a h u : ℕ) (t : Fin (size a))\n    (hq : 0<nodeMultiplicity a h u t.val) :\n    IntegralArray (acquire a h u t.val).inverse.coefficients :=\n  inverse_integral _ _ (acquire_denominator_integral a h u t)\n    (acquire_denominator_constant a h u t.val hq)\n\nend RiemannGaussian.SemiprimeD1InverseIntegral\n","RiemannGaussian.SemiprimeD1JetWordModeScalarBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetWordModeScalarBits\n\n/-! # Original physical scalar mode acquisition bounds\nThe new reduction/cache clocks are bounded directly. Literal compatibility\nwith the old cache does not transfer or erase either acquisition report.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1JetWordModeScalarBounds\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitIndexClipping\nopen SemiprimeD1RecoveryIntegerBits SemiprimeD1JetModeBits\nopen SemiprimeD1WireKernelOriginal\n\n/-- Finite physical inverse-cache budget from precision and original word width. -/\ndef inverseBudget (p W : ℕ) : ℕ :=\n  2*(12*p*(p+W+2)+10*p+20)+400*(p+1)^3+p+2+100*(p+1)^2+\n    p*SemiprimeD1JetModeBitsBounds.geometricStage p+16\n\n/-- Every actual source reduction, odd inversion and cached geometric step is paid. -/\ntheorem inverseCache_clock (p W : ℕ) (constant : SignedWord) (slope : List Bool)\n    (hc:constant.magnitude.length ≤ W) (hs:slope.length ≤ W) :\n    (SemiprimeD1JetWordModeScalarBits.inverseCache p constant slope).clock ≤ inverseBudget p W := by\n  let c:=SemiprimeD1RecoveryStripBits.signed p constant\n  let s:=SemiprimeD1RecoveryStripBits.signed p (positive slope)\n  let inverse:=SemiprimeD1OddInverseBits.inverse p c.bits\n  let negative:=SemiprimeD1OddInverseBits.negativeOne p\n  let opposite:=SemiprimeD1JetScalarBits.mul p negative.bits s.bits\n  let ratio:=SemiprimeD1JetScalarBits.mul p opposite.bits inverse.bits\n  let out:=geometric p ratio.bits inverse.bits p\n  have hcc:c.clock ≤ 12*p*(p+W+2)+10*p+20:=\n    (SemiprimeD1RecoveryStripBits.signed_clock p constant).trans (by gcongr)\n  have hsc:s.clock ≤ 12*p*(p+W+2)+10*p+20:=\n    (SemiprimeD1RecoveryStripBits.signed_clock p (positive slope)).trans (by gcongr;exact hs)\n  have hsb:s.bits.length ≤ p:=(SemiprimeD1RecoveryStripBits.signed_good p (positive slope)).1\n  have hic:inverse.clock ≤ 400*(p+1)^3:=SemiprimeD1OddInverseBounds.inverse_clock p c.bits\n  have hib:inverse.bits.length ≤ p:=(SemiprimeD1OddInverseBits.inverse_good p c.bits).1\n  have hnb:negative.bits.length ≤ p:=by simp only [negative,SemiprimeD1OddInverseBits.negativeOne,List.length_replicate,le_refl]\n  have hoc:opposite.clock ≤ 50*(p+1)^2:=SemiprimeD1OddInverseBounds.mul_bounded p negative.bits s.bits hnb hsb\n  have hob:opposite.bits.length ≤ p:=SemiprimeD1JetScalarBits.mul_length _ _ _\n  have hrc:ratio.clock ≤ 50*(p+1)^2:=SemiprimeD1OddInverseBounds.mul_bounded p opposite.bits inverse.bits hob hib\n  have hrb:ratio.bits.length ≤ p:=SemiprimeD1JetScalarBits.mul_length _ _ _\n  have hgc:out.clock ≤ p*SemiprimeD1JetModeBitsBounds.geometricStage p+1:=\n    SemiprimeD1JetModeBitsBounds.geometric_clock p ratio.bits inverse.bits p hrb hib\n  have hnc:negative.clock=p+2:=rfl\n  change c.clock+s.clock+inverse.clock+negative.clock+opposite.clock+ratio.clock+out.clock+15 ≤ _\n  unfold inverseBudget\n  omega\n\n/-- Actual step-width bound derived from the acquired positive content. -/\ntheorem step_width (i : ℕ) (content : List Bool) (hc:0<bitValue content) :\n    (SemiprimeD1JetWordModeScalarBits.step i content).bits.length ≤ i+2 := by\n  have hq:=(divideBits_widths (xs:=(SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits) hc).2\n  rw [SemiprimeD1NormalizedLinearBits.alpha_length] at hq\n  dsimp only [SemiprimeD1JetWordModeScalarBits.step]\n  split\n  · omega\n  · simp only [List.length_cons,List.length_nil];omega\n\n/-- Physical division and zero-clamp step budget. -/\ndef stepBudget (i W : ℕ) : ℕ :=\n  6*(i+1)+3+(i+2)*(16*W+20)+7*W+4+3*(i+2)+1+5\n\n/-- Step work is polynomial in actual content width and original level. -/\ntheorem step_clock (i W : ℕ) (content : List Bool) (hc:0<bitValue content)\n    (hw:content.length ≤ W) :\n    (SemiprimeD1JetWordModeScalarBits.step i content).clock ≤ stepBudget i W := by\n  have hq:=(divideBits_widths (xs:=(SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits) hc).2\n  rw [SemiprimeD1NormalizedLinearBits.alpha_length] at hq\n  have hd:=divideBits_cost (SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits content\n  rw [SemiprimeD1NormalizedLinearBits.alpha_length] at hd\n  have hdb:(divideBits (SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits content).clock ≤ \n      (i+2)*(16*W+20)+7*W+4:=hd.trans (by gcongr)\n  have ht:=nonzeroBits_cost (divideBits (SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits content).quotient\n  rw [hq] at ht\n  change (SemiprimeD1NormalizedLinearBits.alpha (i+1)).clock+\n    (divideBits (SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits content).clock+\n    (nonzeroBits (divideBits (SemiprimeD1NormalizedLinearBits.alpha (i+1)).bits content).quotient).clock+5 ≤ _\n  rw [SemiprimeD1NormalizedLinearBits.alpha_clock]\n  unfold stepBudget\n  omega\n\n/-- Original scalar-input constructor budget, including both actual digit stages. -/\ndef budget (p a i : ℕ) : ℕ :=\n  2*(4*(a+1)+1)+SemiprimeD1NormalizedLinearBits.budget (a+1) (a+1)+\n    inverseBudget p (a+2)+stepBudget i (2*a+4)+8\n\n/-- Actual original factors derive content positivity and all source widths. -/\ntheorem acquire_factor_bounds (p a i : ℕ) (t : Fin (size a)) (x y₀ : Fin (2^a)) :\n    let f:=(SemiprimeD1JetWordModeScalarBits.acquireOriginal p a i t x y₀).factor\n    0<bitValue f.content ∧f.content.length ≤ 2*a+4 ∧\n      f.constant.magnitude.length ≤ a+2 ∧f.slope.length ≤ a+2 := by\n  have hw:=SemiprimeD1NormalizedLinearBits.acquire_width (a+1) (a+1)\n    (SemiprimeEncodedRowSelection.digits (a+1) t.val).bits\n    (SemiprimeEncodedRowSelection.digits (a+1) (displacement a x y₀).val).bits\n    (SemiprimeEncodedRowSelection.digits_length _ _).le\n    (SemiprimeEncodedRowSelection.digits_length _ _).le\n  have hc:=SemiprimeD1NormalizedLinearBits.acquire_content (a+1)\n    (SemiprimeEncodedRowSelection.digits (a+1) t.val).bits\n    (SemiprimeEncodedRowSelection.digits (a+1) (displacement a x y₀).val).bits\n  dsimp only [SemiprimeD1JetWordModeScalarBits.acquireOriginal]\n  change 0<bitValue (SemiprimeD1NormalizedLinearBits.acquire _ _ _).content ∧_\n  refine ⟨by rw [hc];positivity,?_⟩\n  rcases hw with ⟨h1,h2,h3⟩\n  exact ⟨by omega,by omega,by omega⟩\n\n/-- Complete scalar acquisition report from original input dimensions only. -/\ntheorem acquire_clock (p a i : ℕ) (t : Fin (size a)) (x y₀ : Fin (2^a)) :\n    (SemiprimeD1JetWordModeScalarBits.acquireOriginal p a i t x y₀).clock ≤ budget p a i := by\n  let j:=SemiprimeEncodedRowSelection.digits (a+1) t.val\n  let d:=SemiprimeEncodedRowSelection.digits (a+1) (displacement a x y₀).val\n  let f:=SemiprimeD1NormalizedLinearBits.acquire (a+1) j.bits d.bits\n  have hf:=acquire_factor_bounds p a i t x y₀\n  have hfc:f.clock ≤ SemiprimeD1NormalizedLinearBits.budget (a+1) (a+1):=\n    SemiprimeD1NormalizedLinearBits.acquire_clock (a+1) (a+1) j.bits d.bits\n      (SemiprimeEncodedRowSelection.digits_length _ _).le\n      (SemiprimeEncodedRowSelection.digits_length _ _).le\n  have hic:=inverseCache_clock p (a+2) f.constant f.slope hf.2.2.1 hf.2.2.2\n  have hsc:=step_clock i (2*a+4) f.content hf.1 hf.2.1\n  have hj:j.work=4*(a+1)+1:=SemiprimeEncodedRowSelection.digits_work _ _\n  have hd:d.work=4*(a+1)+1:=SemiprimeEncodedRowSelection.digits_work _ _\n  change j.work+d.work+f.clock+\n    (SemiprimeD1JetWordModeScalarBits.inverseCache p f.constant f.slope).clock+\n    (SemiprimeD1JetWordModeScalarBits.step i f.content).clock+8 ≤ _\n  unfold budget\n  omega\n\n/-- Original acquired cache and step widths follow the actually acquired factor. -/\ntheorem acquire_width (p a i : ℕ) (t : Fin (size a)) (x y₀ : Fin (2^a)) :\n    (SemiprimeD1JetWordModeScalarBits.acquireOriginal p a i t x y₀).cache.words.length=p ∧\n    (∀w∈(SemiprimeD1JetWordModeScalarBits.acquireOriginal p a i t x y₀).cache.words,w.length ≤ p) ∧\n    (SemiprimeD1JetWordModeScalarBits.acquireOriginal p a i t x y₀).step.length ≤ i+2 := by\n  have hf:=acquire_factor_bounds p a i t x y₀\n  exact ⟨SemiprimeD1JetWordModeScalarBits.inverseCache_length _ _ _,\n    SemiprimeD1JetWordModeScalarBits.inverseCache_bounded _ _ _,step_width _ _ hf.1⟩\nend RiemannGaussian.SemiprimeD1JetWordModeScalarBounds\n","RiemannGaussian.SemiprimeD1LeafCounterBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1LeafCounter\nimport RiemannGaussian.SemiprimeD1JetRingBounds\n\n/-! # Actual eager leaf reports, canonical data and storage\nAll scalar arithmetic is the physical existing word backend. Literal index-list\nreads, table construction/copies and every producer report are retained. Native\nNat indices/route/control and full tape/address simulation remain explicit.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1LeafCounterBounds\nopen SemiprimeD1LeafCounter SemiprimeD1JetAxes\nopen SemiprimeD1TensorTables (GoodWords)\n\n/-- Literal physical word vector unit has canonical shape and width. -/\ntheorem one_good (ctx : Context) : GoodWords ctx (SemiprimeD1JetAffineCoefficient.one ctx).words := by\n  have hg:=SemiprimeD1JetAffineCoefficientBounds.one_good ctx\n  refine ⟨hg.1,?_⟩\n  intro w hw\n  refine ⟨?_,hg.2 w hw⟩\n  rcases List.mem_map.mp hw with ⟨i,_,rfl⟩\n  split_ifs\n  · exact SemiprimeD1JetScalarBits.reduce_compact _ _\n  · trivial\n\n/-- Actual physical multiplication always returns canonical current-context data. -/\ntheorem mul_good (ctx : Context) (a b : List (List Bool)) :\n    GoodWords ctx (SemiprimeD1JetRingBits.mul ctx a b).words :=\n  ⟨SemiprimeD1JetRingBits.mul_shape _ _ _,fun w hw =>\n    ⟨SemiprimeD1JetRingBits.mul_compact _ _ _ w hw,SemiprimeD1JetRingBits.mul_bounded _ _ _ w hw⟩⟩\n\n/-- Actual physical addition always returns canonical current-context data. -/\ntheorem add_good (ctx : Context) (a b : List (List Bool)) :\n    GoodWords ctx (SemiprimeD1JetRingBits.add ctx a b).words :=\n  ⟨SemiprimeD1JetRingBits.add_shape _ _ _,fun w hw =>\n    ⟨SemiprimeD1JetRingBits.add_compact _ _ _ w hw,SemiprimeD1JetRingBits.add_bounded _ _ _ w hw⟩⟩\n\n/-- Actual lookup inherits the literal table's current-context invariant. -/\ntheorem evaluateVertex_good (ctx : Context) (v : Vertex)\n    (hv : SemiprimeD1TensorTables.Good ctx v.table) (bits : List Bool) :\n    GoodWords ctx (evaluateVertex v bits).words :=\n  SemiprimeD1TensorTables.lookup_good ctx v.table hv _\n\n/-- Every actual assignment product is canonical, with no output Fits premise. -/\ntheorem evaluateAssignment_good (ctx : Context) (vertices : List Vertex) (bits : List Bool) :\n    GoodWords ctx (evaluateAssignment ctx vertices bits).words := by\n  cases vertices with\n  | nil => exact one_good ctx\n  | cons v vs => exact mul_good _ _ _\n\n/-- Every materialized global-assignment table entry is an actually executed canonical product. -/\ntheorem globalTable_good (M : ℕ) (ctx : Context) (vertices : List Vertex) :\n    SemiprimeD1TensorTables.Good ctx\n      (SemiprimeD1TensorTables.build M (evaluateAssignment ctx vertices)).table :=\n  SemiprimeD1TensorTables.build_good ctx M _ (fun bits _ => evaluateAssignment_good ctx vertices bits)\n\n/-- All physically summed literal tables preserve canonical shape. -/\ntheorem sumTable_good (ctx : Context) {n : ℕ} (table : SemiprimeD1TensorTables.Table n)\n    (ht : SemiprimeD1TensorTables.Good ctx table) : GoodWords ctx (sumTable ctx table).words := by\n  cases table with\n  | leaf words => simpa only [sumTable,copyVector_value,SemiprimeD1TensorTables.Good] using ht\n  | fork low high => exact add_good _ _ _\n\n/-- The executed whole leaf counter derives canonical output directly from its actual table. -/\ntheorem run_good (M : ℕ) (ctx : Context) (vertices : List Vertex) :\n    GoodWords ctx (run M ctx vertices).words :=\n  sumTable_good ctx _ (globalTable_good M ctx vertices)\n\n/-- Each actual assignment read visits at most the full assignment list. -/\ntheorem readBit_clock (bits : List Bool) (i : ℕ) : (readBit bits i).clock≤3*bits.length+1 := by\n  induction bits generalizing i with\n  | nil => simp [readBit]\n  | cons b bs ih =>\n    cases i with\n    | zero => simp only [readBit,List.length_cons];omega\n    | succ i => have h:=ih i;simp only [readBit,List.length_cons];omega\n\n/-- Ordered port gathering pays every actual read and copied Boolean cell. -/\ntheorem gather_clock (bits : List Bool) (ports : List ℕ) :\n    (gather bits ports).clock≤ports.length*(3*bits.length+4)+1 := by\n  induction ports with\n  | nil => simp [gather]\n  | cons p ps ih =>\n    have h:=readBit_clock bits p\n    change (readBit bits p).clock+(gather bits ps).clock+3≤_\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Current vector copy/report polynomial. -/\ndef copyBudget (ctx : Context) : ℕ := ctx.rank*(3*ctx.precision+4)+1\n\n/-- Actual global-jet product/report polynomial. -/\ndef productBudget (ctx : Context) : ℕ :=\n  SemiprimeD1JetRingBounds.mulBudget ctx.axes.length ctx.rank ctx.precision ctx.precision\n\n/-- Actual global-jet addition/report polynomial. -/\ndef additionBudget (ctx : Context) : ℕ :=\n  ctx.rank*(6*ctx.rank+11*ctx.precision+9*ctx.precision+17)+10*ctx.rank+5\n\n/-- Physical unit acquisition/report polynomial. -/\ndef oneBudget (ctx : Context) : ℕ := 9*ctx.precision+3*ctx.rank+8\n\n/-- One actual gathered local table entry has a closed original-data read/copy budget. -/\ntheorem evaluateVertex_clock (M : ℕ) (ctx : Context) (v : Vertex)\n    (hv : SemiprimeD1TensorTables.Good ctx v.table) (bits : List Bool) (hb : bits.length=M) :\n    (evaluateVertex v bits).clock≤v.ports.length*(3*M+9)+copyBudget ctx+4 := by\n  have hg:=gather_clock bits v.ports\n  have hl:=SemiprimeD1TensorTables.lookup_clock ctx v.table hv (gather bits v.ports).bits\n  change (gather bits v.ports).clock+\n    (SemiprimeD1TensorTables.lookup v.table (gather bits v.ports).bits).clock+3≤_\n  rw [hb] at hg\n  dsimp [copyBudget]\n  nlinarith\n\n/-- Total literal scope/index-list size, counting repeated local ports too. -/\ndef scopeSize (vertices : List Vertex) : ℕ := (vertices.map fun v => v.ports.length).sum\n\n/-- Fixed polynomial assignment-work envelope in actual source dimensions. -/\ndef assignmentBudget (M : ℕ) (ctx : Context) (vertices : List Vertex) : ℕ :=\n  oneBudget ctx+scopeSize vertices*(3*M+9)+vertices.length*(copyBudget ctx+productBudget ctx+8)\n\n/-- Closed actual assignment producer work, without an entry-clock or Fits oracle. -/\ntheorem evaluateAssignment_clock (M : ℕ) (ctx : Context) (vertices : List Vertex)\n    (hg : Good ctx vertices) (bits : List Bool) (hb : bits.length=M) :\n    (evaluateAssignment ctx vertices bits).clock≤assignmentBudget M ctx vertices := by\n  induction vertices with\n  | nil =>\n    have h:=SemiprimeD1JetScalarBits.reduce_clock ctx.precision [true]\n    change (SemiprimeD1JetScalarBits.reduce ctx.precision [true]).clock+3*ctx.rank+3≤_\n    simp only [assignmentBudget,scopeSize,List.map_nil,List.sum_nil,List.length_nil,Nat.zero_mul,\n      Nat.add_zero,oneBudget]\n    omega\n  | cons v vs ih =>\n    have hv:=hg v List.mem_cons_self\n    have hh:=evaluateVertex_clock M ctx v hv bits hb\n    have ht:=ih (fun w hw => hg w (List.mem_cons_of_mem v hw))\n    have hhead:=evaluateVertex_good ctx v hv bits\n    have htail:=evaluateAssignment_good ctx vs bits\n    have hm:=SemiprimeD1JetRingBounds.mul_clock ctx (evaluateVertex v bits).words\n      (evaluateAssignment ctx vs bits).words ctx.precision hhead.1.le htail.1.le\n      (fun w hw => (hhead.2 w hw).2) (fun w hw => (htail.2 w hw).2)\n    change (evaluateVertex v bits).clock+(evaluateAssignment ctx vs bits).clock+\n      (SemiprimeD1JetRingBits.mul ctx (evaluateVertex v bits).words (evaluateAssignment ctx vs bits).words).clock+3≤_\n    simp only [assignmentBudget,scopeSize,List.map_cons,List.sum_cons,List.length_cons,Nat.add_mul,Nat.one_mul] at *\n    dsimp [productBudget] at *\n    omega\n\n/-- Closed actual addition budget from the two canonical source vectors. -/\ntheorem add_clock (ctx : Context) (a b : List (List Bool)) (ha : GoodWords ctx a) (hb : GoodWords ctx b) :\n    (SemiprimeD1JetRingBits.add ctx a b).clock≤additionBudget ctx :=\n  SemiprimeD1JetRingBounds.add_clock ctx a b ctx.precision ha.1.le hb.1.le\n    (fun w hw => (ha.2 w hw).2) (fun w hw => (hb.2 w hw).2)\n\n/-- ALL actual recursive table-sum reports have the exact eager exponential scale. -/\ntheorem sumTable_clock (ctx : Context) {n : ℕ} (table : SemiprimeD1TensorTables.Table n)\n    (ht : SemiprimeD1TensorTables.Good ctx table) :\n    (sumTable ctx table).clock+(additionBudget ctx+3)≤\n      (copyBudget ctx+additionBudget ctx+3)*2^n := by\n  induction table with\n  | leaf words =>\n    have h:=copyVector_clock_le words ctx.precision (fun w hw => (ht.2 w hw).2)\n    simp only [sumTable,ht.1,pow_zero,Nat.mul_one,copyBudget] at *\n    omega\n  | @fork n low high ihlow ihhigh =>\n    have hl:=ihlow ht.1\n    have hh:=ihhigh ht.2\n    have ha:=add_clock ctx (sumTable ctx low).words (sumTable ctx high).words\n      (sumTable_good ctx low ht.1) (sumTable_good ctx high ht.2)\n    change (sumTable ctx low).clock+(sumTable ctx high).clock+\n      (SemiprimeD1JetRingBits.add ctx (sumTable ctx low).words (sumTable ctx high).words).clock+3+\n        (additionBudget ctx+3)≤_\n    rw [pow_succ,←Nat.mul_assoc]\n    omega\n\n/-- Explicit original-dimension eager leaf work, with every source producer retained. -/\ndef budget (M : ℕ) (ctx : Context) (vertices : List Vertex) : ℕ :=\n  (assignmentBudget M ctx vertices+copyBudget ctx+additionBudget ctx+13)*2^M\n\n/-- The actual complete leaf call has a fixed polynomial times2^M report bound. -/\ntheorem run_clock (M : ℕ) (ctx : Context) (vertices : List Vertex) (hg : Good ctx vertices) :\n    (run M ctx vertices).clock≤budget M ctx vertices := by\n  have hb:=SemiprimeD1TensorTables.build_clock M (assignmentBudget M ctx vertices)\n    (evaluateAssignment ctx vertices) (fun bits h => evaluateAssignment_clock M ctx vertices hg bits h)\n  have hs:=sumTable_clock ctx _ (globalTable_good M ctx vertices)\n  have hp : 1≤2^M := Nat.one_le_two_pow\n  change (SemiprimeD1TensorTables.build M (evaluateAssignment ctx vertices)).clock+\n    (sumTable ctx (SemiprimeD1TensorTables.build M (evaluateAssignment ctx vertices)).table).clock+3≤_\n  dsimp [budget]\n  nlinarith\n\n/-- Actual allocated eager output-table storage, separately from held input tables. -/\ntheorem run_table_storage (M : ℕ) (ctx : Context) (vertices : List Vertex) :\n    SemiprimeD1TensorTables.storage (run M ctx vertices).table+1≤\n      (ctx.rank*(3*ctx.precision+4)+3)*2^M :=\n  SemiprimeD1TensorTables.storage_bound ctx _ (globalTable_good M ctx vertices)\n\nend RiemannGaussian.SemiprimeD1LeafCounterBounds\n","RiemannGaussian.SemiprimeD1NetworkPacketPolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OriginalPacketKernelRows\nimport RiemannGaussian.SemiprimeD1NetworkDoubleAssignment\n\n/-! # Actual literal-network deformation equals the original packet polynomial sum\nEvery packet/group polynomial and source value is acquired from the actual\noriginal sparse replay and one common original X/Y endpoint assignment. This\nis the deformation-to-mode-polynomial identity; coefficient separation and\nindependent child contractions are separate subsequent steps.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 5000000\nnamespace RiemannGaussian.SemiprimeD1NetworkPacketPolynomial\nopen scoped BigOperators\nopen SemiprimeD1TensorNetwork SemiprimeD1JetAxes SemiprimeD1JetInterpretation\nopen SemiprimeD1JetAlgebra SemiprimeD1JetBoxIndex SemiprimeD1JetScalarMap SemiprimeD1DyadicInteger\nopen SemiprimeD1LeafCounter SemiprimeD1NetworkIntegralDeformation\nopen SemiprimeD1PacketAssignmentRows SemiprimeD1ChildAssignmentEndpoint\nopen SemiprimeD1PacketRowProducts SemiprimeD1AllPacketRowProducts SemiprimeD1OriginalPacketKernelRows\nnoncomputable section\n\n/-- The exact original occurrence assignment type of the ACTUAL network. -/\nabbrev Bits (net : Network) (r a : ℕ) :=\n  Fin (SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length r a\n    (arity net.rows) (owner net.rows)).placements.length→Bool\n\n/-- Closed original-network deformation/actual-mode-polynomial identity. The\ncoefficient map preserves constants (proved for the actual fresh-axis map),\nnot arbitrary source tables, row lists, polynomials or source values. -/\ntheorem network_packet_polynomial (axes : List ℕ) (ctx : Context)\n    (f : Algebra (dims axes) (ZMod (2^ctx.precision))→+*Carrier ctx)\n    (hconstants : f.comp (constants (dims axes))=constants (dims ctx.axes))\n    (z : SemiprimeD1JetAffineCoefficient.JetRun) (net : Network) (r a u p : ℕ) [NeZero r]\n    (i : Fin a) (t : Fin (SemiprimeD1WireKernelOriginal.size a))\n    (hprecision : ctx.precision=(SemiprimeD1GlobalModeFibres.node net.leftCount net.rows.length r a u p\n      (arity net.rows) (owner net.rows) i).precision)\n    (hpos : ctx.Positive) (hp : 0<ctx.precision) (ht : SemiprimeD1WireKernelOriginal.point a t.val≠0)\n    (hi : padicValInt 2 (SemiprimeD1WireKernelOriginal.point a t.val)=i.val) :\n    ((networkPolynomial axes net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) t\n      net.left.toList net.right.toList).map (scalarMap (dims axes) (reduction ctx.precision))).eval₂ f (interpret ctx z.words)=\n      ∑x : Bits net r a,∑y : Bits net r a,\n        f ((net.right.toList.map (fun v => interpret ⟨axes,ctx.precision⟩\n          (SemiprimeD1TensorTables.valueAt v.table (localAssignment x v)))).prod)*\n        f ((net.left.toList.map (fun v => interpret ⟨axes,ctx.precision⟩\n          (SemiprimeD1TensorTables.valueAt v.table (localAssignment y v)))).prod)*\n        MvPolynomial.eval\n          (SemiprimeD1PacketSourceVector.values ctx net.leftCount net.rows.length r a (ctx.precision-1)\n            (arity net.rows) (owner net.rows) i\n            (originalEndpointBit net.leftCount net.rows.length r a (arity net.rows) (owner net.rows)\n              (tagBits net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) x y)))\n          (∏packet : Fin (SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length r a\n            (arity net.rows) (owner net.rows)).state.packets.length,\n            ∏g : Fin r,packetPolynomial ctx z net.leftCount net.rows.length r a u p\n              (arity net.rows) (owner net.rows) i packet g\n              (originalEndpointBit net.leftCount net.rows.length r a (arity net.rows) (owner net.rows)\n                (tagBits net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) x y)) t) := by\n  classical\n  rw [SemiprimeD1NetworkDoubleAssignment.network_double_sum]\n  simp_rw [hconstants]\n  apply Finset.sum_congr rfl\n  intro x _\n  apply Finset.sum_congr rfl\n  intro y _\n  congr 1\n  rw [all_packet_eval ctx z net.leftCount net.rows.length r a u p (arity net.rows) (owner net.rows) i _ t\n    hprecision hpos hp ht hi]\n  apply Finset.prod_congr rfl\n  intro j _\n  exact (wireRow_kernel ctx z net.leftCount net.rows.length r a (arity net.rows) (owner net.rows) i\n    ⟨0,NeZero.pos r⟩ x y j t hpos hp).symm\n\nend\nend RiemannGaussian.SemiprimeD1NetworkPacketPolynomial\n","RiemannGaussian.SemiprimeD1OddInverseBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OddInverseBits\n\n/-! # Intrinsic physical cost of acquired odd inverses -/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 16000\nnamespace RiemannGaussian.SemiprimeD1OddInverseBounds\nopen SemiprimeD1OddInverseBits SemiprimeD1JetScalarBits\nopen SemiprimeBitArithmetic\n\n/-- One actual bounded modular product has a fixed quadratic physical report. -/\ntheorem mul_bounded (p : ℕ) (a b : List Bool) (ha : a.length ≤ p) (hb : b.length ≤ p) :\n    (mul p a b).clock ≤ 50*(p+1)^2 := by\n  have hc := mul_clock p a b\n  have hm := Nat.mul_le_mul ha (show a.length+b.length+2 ≤ 2*p+2 by omega)\n  nlinarith\n\n/-- One actual bounded modular sum has a fixed linear physical report. -/\ntheorem add_bounded (p : ℕ) (a b : List Bool) (ha : a.length ≤ p) (hb : b.length ≤ p) :\n    (add p a b).clock ≤ 40*(p+1) := by\n  have hc := add_clock p a b\n  have hm : max a.length b.length ≤ p := max_le ha hb\n  omega\n\n/-- Every scalar operation of one Newton stage is paid, with no output width advice. -/\ntheorem step_clock (p : ℕ) (a negative two current : List Bool)\n    (ha : a.length ≤ p) (hn : negative.length ≤ p) (ht : two.length ≤ p) (hx : current.length ≤ p) :\n    (step p a negative two current).clock ≤ 250*(p+1)^2 := by\n  have h1 := mul_bounded p a current ha hx\n  have h2 := mul_bounded p negative (mul p a current).bits hn (mul_length _ _ _)\n  have h3 := add_bounded p two (mul p negative (mul p a current).bits).bits ht (mul_length _ _ _)\n  have h4 := mul_bounded p current (add p two (mul p negative (mul p a current).bits).bits).bits hx\n    (add_length _ _ _)\n  change (mul p a current).clock+(mul p negative (mul p a current).bits).clock+\n    (add p two (mul p negative (mul p a current).bits).bits).clock+\n      (mul p current (add p two (mul p negative (mul p a current).bits).bits).bits).clock+10 ≤ _\n  nlinarith\n\n/-- Literal p-independent stage loop bound, with earlier reports retained once. -/\ntheorem loop_clock (p : ℕ) (a negative two : List Bool)\n    (ha : a.length ≤ p) (hn : negative.length ≤ p) (ht : two.length ≤ p) (n : ℕ) :\n    (loop p a negative two n).clock ≤ 9*p+5+n*(250*(p+1)^2+3) := by\n  induction n with\n  | zero => simpa only [loop,Nat.zero_mul,Nat.add_zero] using reduce_clock p [true]\n  | succ n ih =>\n    have hs := step_clock p a negative two (loop p a negative two n).bits ha hn ht\n      (loop_good p a negative two n).1\n    change (loop p a negative two n).clock+(step p a negative two (loop p a negative two n).bits).clock+3 ≤ _\n    nlinarith\n\n/-- Complete original-word inverse acquisition has a cubic physical report.\nOnly p is needed: truncation visits at most p bits of the source word. -/\ntheorem inverse_clock (p : ℕ) (input : List Bool) :\n    (inverse p input).clock ≤ 400*(p+1)^3 := by\n  have ha := reduce_clock p input\n  have ht := reduce_clock p [false,true]\n  have hl := loop_clock p (reduce p input).bits (negativeOne p).bits (reduce p [false,true]).bits\n    (reduce_length _ _) (by simp [negativeOne]) (reduce_length _ _) p\n  change (reduce p input).clock+(negativeOne p).clock+(reduce p [false,true]).clock+\n    (loop p (reduce p input).bits (negativeOne p).bits (reduce p [false,true]).bits p).clock+10 ≤ _\n  simp only [negativeOne] at hl ⊢\n  nlinarith\n\n/-- The actually computed physical inverse is the same unit inverse used by the\nexisting universal kernel semantics; no inverse answer or unit proof is supplied. -/\ntheorem inverse_eq_native (p : ℕ) (input : List Bool) (hodd : Odd (bitValue input)) :\n    value p (inverse p input).bits=(value p input)⁻¹ := by\n  have hc := inverse_correct p input hodd\n  have hu : IsUnit (value p input) := isUnit_iff_exists_inv.mpr ⟨_,hc⟩\n  calc\n    _ = value p (inverse p input).bits*1 := (mul_one _).symm\n    _ = value p (inverse p input).bits*(value p input*(value p input)⁻¹) := by\n      rw [ZMod.mul_inv_of_unit _ hu]\n    _ = (value p input*value p (inverse p input).bits)*(value p input)⁻¹ := by ring\n    _ = _ := by rw [hc,one_mul]\n\nend RiemannGaussian.SemiprimeD1OddInverseBounds\n","RiemannGaussian.SemiprimeD1PackedNetworkTopology":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedRootInputOriginal\n/-! # Exact structural cache invariance under the actual marked-table replacement\nThe complete dependent row structure retains counts, order, duplicates and\nevery owner ID. Structural cache equalities below concern literal words,\nnever old tensor coefficients and never native-to-machine clock transport.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnoncomputable section\nnamespace RiemannGaussian.SemiprimeD1PackedNetworkTopology\nopen SemiprimeD1TensorNetwork\nopen SemiprimeD1StackMarkedRootRecordsNetwork (old network rowsAt leftCount_eq rows_eq)\n/-- Complete typed incidence structure, including its actual owner-count bound. -/\ndef stamp (net : Network) : (n : ℕ)×Rows n := ⟨net.leftCount,net.rows⟩\n/-- Explicit dependent row transport preserves the whole structural object. -/\ntheorem stamp_eq (base next : Network) (h : next.leftCount=base.leftCount)\n    (hr : rowsAt base next h=base.rows) : stamp next=stamp base := by\n  cases base with\n  | mk bn br bl bx =>\n    cases next with\n    | mk nn nr nl nx =>\n      change nn=bn at h\n      cases h\n      change nr=br at hr\n      cases hr\n      rfl\n/-- The actual acquired marked network has EXACTLY the old complete ordered incidence structure. -/\ntheorem actual_stamp (N : ℕ) (hN : 0<N) : stamp (network N hN)=stamp (old N hN) :=\n  stamp_eq (old N hN) (network N hN) (leftCount_eq N hN) (rows_eq N hN)\n/-- The entire occurrence/alphabet/selector/key-source bank depends only on rows and counts. -/\ntheorem selection_congr (base next : Network) (h : next.leftCount=base.leftCount)\n    (hr : rowsAt base next h=base.rows) (a : ℕ) :\n    SemiprimeD1StackSourceSelectionAcquireEncoding.result next a=\n      SemiprimeD1StackSourceSelectionAcquireEncoding.result base a := by\n  cases base with\n  | mk bn br bl bx =>\n    cases next with\n    | mk nn nr nl nx =>\n      change nn=bn at h\n      cases h\n      change nr=br at hr\n      cases hr\n      rfl\n/-- ALL154 structural source/cache words have the same exact marked-network interpretation.\nNo table word or acquisition/runtime clock is transferred by this equality. -/\ntheorem actual_selection (N : ℕ) (hN : 0<N) (a : ℕ) :\n    SemiprimeD1StackSourceSelectionAcquireEncoding.result (network N hN) a=\n      SemiprimeD1StackSourceSelectionAcquireEncoding.result (old N hN) a :=\n  selection_congr (old N hN) (network N hN) (leftCount_eq N hN) (rows_eq N hN) a\n/-- Only chronological placements and raw packet bytes, with no native report clock. -/\ndef inventory (net : Network) (a : ℕ) :\n    List SemiprimeD1PacketInventory.Placement × List (List Bool) :=\n  let acquired := SemiprimeD1PacketReplayOriginal.acquire net.leftCount net.rows.length 64 a\n    (SemiprimeD1TensorNetwork.arity net.rows) (SemiprimeD1TensorNetwork.owner net.rows)\n  (acquired.placements,acquired.state.packets)\n/-- The complete sparse inventory's useful payload depends only on the ordered incidence structure. -/\ntheorem inventory_congr (base next : Network) (h : next.leftCount=base.leftCount)\n    (hr : rowsAt base next h=base.rows) (a : ℕ) : inventory next a=inventory base a := by\n  cases base with\n  | mk bn br bl bx =>\n    cases next with\n    | mk nn nr nl nx =>\n      change nn=bn at h\n      cases h\n      change nr=br at hr\n      cases hr\n      rfl\n/-- Exact marked-network replay order, duplicate occurrences and packet bytes reuse the old payload. -/\ntheorem actual_inventory (N : ℕ) (hN : 0<N) (a : ℕ) :\n    inventory (network N hN) a=inventory (old N hN) a :=\n  inventory_congr (old N hN) (network N hN) (leftCount_eq N hN) (rows_eq N hN) a\nend RiemannGaussian.SemiprimeD1PackedNetworkTopology\n","RiemannGaussian.SemiprimeD1PacketModeMaskBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1ModeRoutingBudget\nimport RiemannGaussian.SemiprimeD1OriginalChildGraphBudget\nimport RiemannGaussian.SemiprimeD1PacketTensorTables\n\n/-! # Original packet classifiers and complete header acquisition report\nThe actual global catalogue is constructed and charged. All byte caps and\noriginal wrappers are producer-derived; no routes, mode lists or Fits are advice.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1PacketModeMaskBudget\nopen scoped BigOperators\nopen SemiprimeD1PacketModeMask SemiprimeD1ModeCatalog\nopen SemiprimeD1OriginalChildGraphBudget\n\n/-- Actual per-mode physical routing/classification and native field ledger. -/\ndef itemBudget (a W M T : ℕ) : ℕ :=\n  SemiprimeD1ModeRoutingBudget.budget a W T+20*(W+1)+M+M*T+T+20\n\n/-- Exact actual tile value is bounded even for an unrelated-packet descriptor. -/\ntheorem one_tile {n F a : ℕ} {arity : Fin F→ℕ}\n    (src : SemiprimeD1PacketReplayOriginal.Acquired n F a arity)\n    (packet : Fin src.state.packets.length) (i : Fin a) (group : List Bool) (mode : Mode) :\n    (acquireOne src packet i group mode).tile ≤ 2^a := by\n  have ht : mode.slot%2^(i.val+1)<2^(i.val+1):=Nat.mod_lt _ (by positivity)\n  have hp:=Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) (show i.val+1 ≤ a by omega)\n  unfold acquireOne\n  dsimp only\n  split_ifs <;> dsimp only <;> omega\n\n/-- Actual byte routing/classification report, including unrelated-packet skip. -/\ntheorem one_clock {n F a : ℕ} {arity : Fin F→ℕ}\n    (src : SemiprimeD1PacketReplayOriginal.Acquired n F a arity)\n    (packet : Fin src.state.packets.length) (i : Fin a) (group : List Bool) (mode : Mode)\n    (M W : ℕ) (hp : src.state.packets.length ≤ M)\n    (hk : ∀key∈src.state.packets,key.length ≤ W) (hm : mode.slot ≤ M*2^a) :\n    (acquireOne src packet i group mode).clock ≤ itemBudget a W M (2^a) := by\n  have hkey:=hk _ (List.getElem_mem packet.isLt)\n  have htiles : 2^(i.val+1) ≤ (2:ℕ)^a:=\n    Nat.pow_le_pow_right (by decide) (by omega)\n  have hpacket : packet.val ≤ M:=by have h:=packet.isLt;omega\n  let tile : Fin (2^(i.val+1)):=⟨mode.slot%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩\n  let key:=SemiprimeSourceCompactBits.copy src.state.packets[packet.val]\n  let route:=SemiprimeD1ModeRoutingBits.acquire key.bits a i tile\n  have hkb : key.bits.length ≤ W:=by simpa only [key,SemiprimeSourceCompactBits.copy_bits] using hkey\n  have hroute:=SemiprimeD1ModeRoutingBudget.acquire_clock key.bits a i tile W hkb\n  have hlen:=SemiprimeD1ModeRoutingBudget.route_lengths key.bits a i tile\n  have ht:=SemiprimeD1ChildGraph.equalBytes_work route.target group\n  have hs:=SemiprimeD1ChildGraph.equalBytes_work route.source group\n  have hleft : route.source.length ≤ W:=hlen.1.trans hkb\n  have hright : route.target.length ≤ W:=hlen.2.trans hkb\n  change route.clock ≤ _ at hroute\n  unfold acquireOne\n  dsimp only\n  split_ifs\n  · change key.clock+route.clock+(SemiprimeD1ChildGraph.equalBytes route.target group).work+\n      (SemiprimeD1ChildGraph.equalBytes route.source group).work+packet.val+mode.slot+2^(i.val+1)+9 ≤ _\n    have hc : key.clock ≤ 3*W+1:=by rw [SemiprimeSourceCompactBits.copy_clock];omega\n    unfold itemBudget\n    omega\n  · change mode.slot+2^(i.val+1)+5 ≤ _\n    unfold itemBudget\n    omega\n\n/-- Literal same-order classifier loop pays every acquired descriptor. -/\ntheorem scan_clock {n F a : ℕ} {arity : Fin F→ℕ}\n    (src : SemiprimeD1PacketReplayOriginal.Acquired n F a arity)\n    (packet : Fin src.state.packets.length) (i : Fin a) (group : List Bool)\n    (modes : List Mode) (M W : ℕ) (hp : src.state.packets.length ≤ M)\n    (hk : ∀key∈src.state.packets,key.length ≤ W) (hm : ∀mode∈modes,mode.slot ≤ M*2^a) :\n    (scan src packet i group modes).clock ≤ modes.length*(itemBudget a W M (2^a)+4)+1 := by\n  induction modes with\n  | nil => simp [scan]\n  | cons mode modes ih =>\n    have hh:=one_clock src packet i group mode M W hp hk (hm mode List.mem_cons_self)\n    have ht:=ih (fun x hx=>hm x (List.mem_cons_of_mem mode hx))\n    simp only [scan,List.length_cons]\n    nlinarith\n\n/-- Original classifier/header overhead remains polynomial in replay bytes,\nworking precision, real port count and actual dyadic tile range. -/\ndef overhead (r a M P W : ℕ) : ℕ :=\n  SemiprimeSourceHistogramPortKeys.encodeBudget r+\n    (10*P+10+P*(10*(M*2^a)+10))+\n    (P*M*2^a)*(itemBudget a W M (2^a)+4)+9\n\n/-- Actual complete acquired mode cache, keeping source.work LINEAR and explicit. -/\ntheorem fromModes_clock {n F r a : ℕ} {arity : Fin F→ℕ}\n    (src : SemiprimeD1OriginalModeAcquisition.Acquired n F a arity)\n    (packet : Fin src.packets.state.packets.length) (i : Fin a) (g : Fin r) (M W : ℕ)\n    (hp : src.packets.state.packets.length ≤ M)\n    (hk : ∀key∈src.packets.state.packets,key.length ≤ W) :\n    (fromModes src packet i g).clock ≤ src.work+overhead r a M src.precision W := by\n  let group:=SemiprimeSourceHistogramPortKeys.encodeKey g.val\n  let slots:=src.packets.state.packets.length*2^(i.val+1)\n  let catalogue:=acquireCatalog slots (src.precision-1)\n  have htile : 2^(i.val+1) ≤ (2:ℕ)^a:=Nat.pow_le_pow_right (by decide) (by omega)\n  have hslots : slots ≤ M*2^a:=Nat.mul_le_mul hp htile\n  have hc : catalogue.value.length ≤ src.precision*M*2^a := by\n    rw [show catalogue.value=catalog slots (src.precision-1) from acquireCatalog_value _ _,catalog_length]\n    have h:=Nat.mul_le_mul (Nat.sub_le src.precision 1) hslots\n    nlinarith\n  have hwork : catalogue.work ≤ 10*src.precision+10+src.precision*(10*(M*2^a)+10) := by\n    rw [show catalogue.work=10*(src.precision-1)+10+(src.precision-1)*(10*slots+10) from acquireCatalog_work _ _]\n    gcongr <;> exact Nat.sub_le _ _\n  have hm : ∀mode∈catalogue.value,mode.slot ≤ M*2^a := by\n    intro mode hm\n    rw [show catalogue.value=catalog slots (src.precision-1) from acquireCatalog_value _ _] at hm\n    exact (Nat.le_of_lt ((mem_catalog _ _ _).mp hm).1).trans hslots\n  have hs:=scan_clock src.packets packet i group.bits catalogue.value M W hp hk hm\n  have hg:=SemiprimeSourceHistogramPortKeys.encodeKey_clock g.val r (by omega)\n  have hs' : (scan src.packets packet i group.bits catalogue.value).clock ≤\n      (src.precision*M*2^a)*(itemBudget a W M (2^a)+4)+1:=hs.trans (by gcongr)\n  change src.work+group.clock+catalogue.work+(scan src.packets packet i group.bits catalogue.value).clock+8 ≤ _\n  change group.clock ≤ _ at hg\n  change _ ≤ src.work+(SemiprimeSourceHistogramPortKeys.encodeBudget r+\n    (10*src.precision+10+src.precision*(10*(M*2^a)+10))+\n    (src.precision*M*2^a)*(itemBudget a W M (2^a)+4)+9)\n  omega\n\n/-- Every ACTUAL acquired mask item has constructor-derived order and tile caps. -/\ntheorem item_caps {n F r a : ℕ} {arity : Fin F→ℕ}\n    (src : SemiprimeD1OriginalModeAcquisition.Acquired n F a arity)\n    (packet : Fin src.packets.state.packets.length) (i : Fin a) (g : Fin r)\n    (item : Item) (hi : item∈(fromModes src packet i g).items) :\n    item.mode.order ≤ src.precision ∧ item.tile ≤ 2^a := by\n  have hmode : item.mode∈((fromModes src packet i g).items.map Item.mode):=List.mem_map.mpr ⟨item,hi,rfl⟩\n  rw [fromModes_catalogue] at hmode\n  have hc:=((mem_catalog _ _ _).mp hmode).2\n  have horder : item.mode.order ≤ src.precision:=by omega\n  have hitems : (fromModes src packet i g).items=\n      ((acquireCatalog (src.packets.state.packets.length*2^(i.val+1)) (src.precision-1)).value.map\n        (acquireOne src.packets packet i (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits)) := by\n    exact scan_items _ _ _ _ _\n  rw [hitems] at hi\n  obtain ⟨mode,_,rfl⟩:=List.mem_map.mp hi\n  exact ⟨horder,one_tile _ _ _ _ _⟩\n\n/-- Literal original mode source retained by the controller. -/\nabbrev originalSource (n F r a u phase p : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :=\n  SemiprimeD1OriginalModeAcquisition.acquire n F r a u phase p arity owner\n\n/-- CLOSED actual original-source mode classifier budget. -/\ntheorem original_clock (n F r a u phase p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (originalSource n F r a u phase p arity owner).packets.state.packets.length)\n    (i : Fin a) (g : Fin r) :\n    (fromModes (originalSource n F r a u phase p arity owner) packet i g).clock ≤\n      (originalSource n F r a u phase p arity owner).work+\n        overhead r a (∑e,arity e) (originalSource n F r a u phase p arity owner).precision\n          (replayCap n F r a (∑e,arity e)) := by\n  apply fromModes_clock _ _ _ _ _ _ (SemiprimeD1ReplayMetadataBounds.original_count n F r a arity owner)\n  intro key hk\n  exact ((SemiprimeD1ReplayMetadataBounds.original_packets n F r a arity owner).2 key hk).trans\n    (SemiprimeD1PacketReplayBudget.acquire_work n F r a arity owner)\n\n/-- A cached bucket read contains only endpoints of the actually emitted list. -/\ntheorem buckets_get_subset {V : ℕ} (es : List (SemiprimeD1ChildGraph.Endpoint V))\n    (packets : List (List Bool)) (j : ℕ) (e : SemiprimeD1ChildGraph.Endpoint V)\n    (he : e∈(((SemiprimeD1ChildGraph.buckets es packets).value[j]?).getD [])) : e∈es := by\n  induction packets generalizing j with\n  | nil => simp [SemiprimeD1ChildGraph.buckets] at he\n  | cons packet packets ih =>\n    cases j with\n    | zero =>\n      change e∈(SemiprimeD1ChildGraph.bucket packet es).value at he\n      rw [SemiprimeD1ChildGraphSemantics.bucket_value] at he\n      exact (List.mem_filter.mp he).1\n    | succ j => exact ih j he\n\n/-- A total cached bucket read never exceeds the actual emitted endpoint count. -/\ntheorem buckets_get_length {V : ℕ} (es : List (SemiprimeD1ChildGraph.Endpoint V))\n    (packets : List (List Bool)) (j : ℕ) :\n    (((SemiprimeD1ChildGraph.buckets es packets).value[j]?).getD []).length ≤ es.length := by\n  induction packets generalizing j with\n  | nil => simp [SemiprimeD1ChildGraph.buckets]\n  | cons packet packets ih =>\n    cases j with\n    | zero => exact SemiprimeD1ChildMetadataPrimitives.bucket_length packet es\n    | succ j => exact ih j\n\n/-- Full original packet header supplier overhead. -/\ndef prepareOverhead (n F r a M P : ℕ) : ℕ :=\n  overhead r a M P (replayCap n F r a M)+\n    SemiprimeD1OriginalChildGraphBudget.overhead n F r a M+3*M+10\n\n/-- Actual header endpoints inherit physical original packet/slot/edge bytes. -/\ntheorem prepare_payload (n F r a u phase p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (originalSource n F r a u phase p arity owner).packets.state.packets.length)\n    (i : Fin a) (g : Fin r) :\n    ∀e∈(SemiprimeD1PacketTensorTables.prepare owner (originalSource n F r a u phase p arity owner) packet i g).endpoints,\n      e.packet.length ≤ replayCap n F r a (∑e,arity e) ∧\n      e.edge.length ≤ replayCap n F r a (∑e,arity e) ∧ e.slot.length ≤ a := by\n  intro e he\n  let src:=originalSource n F r a u phase p arity owner\n  let graph:=SemiprimeD1ChildGraph.fromReplay owner src.packets i g\n  have hm : e∈graph.endpoints := buckets_get_subset graph.endpoints src.packets.state.packets packet.val e he\n  exact endpoint_payload n F r a arity owner i g e hm\n\n/-- Actual cached packet table degree uses the proved orientation-slot injection,\nnot the coarse polynomial metadata endpoint-count estimate. -/\ntheorem prepare_degree (n F r a u phase p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (originalSource n F r a u phase p arity owner).packets.state.packets.length)\n    (i : Fin a) (g : Fin r) :\n    (SemiprimeD1PacketTensorTables.prepare owner (originalSource n F r a u phase p arity owner) packet i g).endpoints.length ≤ 2*2^a := by\n  let G:=SemiprimeD1ChildGraph.acquire n F r a arity owner i g\n  have hp : packet.val < G.factors.length := by\n    change packet.val < (SemiprimeD1ChildGraph.fromReplay owner\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner) i g).factors.length\n    rw [SemiprimeD1ChildGraphSemantics.factors_length]\n    exact packet.isLt\n  change ((G.factors[packet.val]?).getD []).length ≤ _\n  rw [List.getElem?_eq_getElem hp,Option.getD_some]\n  exact SemiprimeD1ChildGraphBounds.packet_arity n F r a arity owner i g ⟨packet.val,hp⟩\n\n/-- All original cached header mode descriptors have computed order/tile caps. -/\ntheorem prepare_item_caps (n F r a u phase p : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (originalSource n F r a u phase p arity owner).packets.state.packets.length)\n    (i : Fin a) (g : Fin r) (item : Item)\n    (hi : item∈(SemiprimeD1PacketTensorTables.prepare owner\n      (originalSource n F r a u phase p arity owner) packet i g).masks.items) :\n    item.mode.order ≤ (originalSource n F r a u phase p arity owner).precision ∧ item.tile ≤ 2^a :=\n  item_caps _ _ _ _ item hi\n\n/-- CLOSED original complete-header report. The source acquisition/menu report\nis retained LINEARLY and all repeated classifiers/graph scans remain paid. -/\ntheorem prepare_clock (n F r a u phase p : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (originalSource n F r a u phase p arity owner).packets.state.packets.length)\n    (i : Fin a) (g : Fin r) :\n    (SemiprimeD1PacketTensorTables.prepare owner (originalSource n F r a u phase p arity owner) packet i g).clock ≤\n      (originalSource n F r a u phase p arity owner).work+\n        prepareOverhead n F r a (∑e,arity e) (originalSource n F r a u phase p arity owner).precision := by\n  let src:=originalSource n F r a u phase p arity owner\n  let graph:=SemiprimeD1ChildGraph.fromReplay owner src.packets i g\n  let masks:=fromModes src packet i g\n  let W:=replayCap n F r a (∑e,arity e)\n  have hm:=original_clock n F r a u phase p arity owner packet i g\n  change masks.clock ≤ src.work+overhead r a (∑e,arity e) src.precision W at hm\n  have hg:=SemiprimeD1OriginalChildGraphBudget.fromReplay_work n F r a arity owner i g\n  change graph.work ≤ src.packets.state.clock+_ at hg\n  have hd : graph.work-src.packets.state.clock ≤ SemiprimeD1OriginalChildGraphBudget.overhead n F r a (∑e,arity e) := by omega\n  have hp:=SemiprimeD1ReplayMetadataBounds.original_count n F r a arity owner\n  change src.packets.state.packets.length ≤ ∑e,arity e at hp\n  have hpacket : packet.val ≤ ∑e,arity e := by\n    have h:=packet.isLt\n    change packet.val < src.packets.state.packets.length at h\n    omega\n  have he:=buckets_get_length graph.endpoints src.packets.state.packets packet.val\n  have hE:=endpoints_length n F r a arity owner i g\n  change graph.endpoints.length ≤ _ at hE\n  have hlen : ((graph.factors[packet.val]?).getD []).length ≤ 2*∑e,arity e := he.trans hE\n  change masks.clock+(graph.work-src.packets.state.clock)+packet.val+\n    ((graph.factors[packet.val]?).getD []).length+10 ≤ src.work+\n    (overhead r a (∑e,arity e) src.precision W+\n      SemiprimeD1OriginalChildGraphBudget.overhead n F r a (∑e,arity e)+3*(∑e,arity e)+10)\n  omega\n\nend RiemannGaussian.SemiprimeD1PacketModeMaskBudget\n","RiemannGaussian.SemiprimeD1PacketModeOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketEndpointOriginal\nimport RiemannGaussian.SemiprimeD1PacketModeProjection\n\n/-! # Original real-row crossing discharges the executed mode bit test\nThe successful physical child-group test and actual route source inequality\nsupply the hypothesis of the original replay routing theorem. No selected-word\ngetter, endpoint origin witness, or same-bit answer is a caller premise.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 3200000\nnamespace RiemannGaussian.SemiprimeD1PacketModeOriginal\nopen SemiprimeD1ChildGraph SemiprimeD1PacketEndpointOriginal SemiprimeBitArithmetic\n\n/-- A real row in the acquired child packet has the tile bit whenever it crosses\naway from that actual acquired source colour. -/\ntheorem row_samebit (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (tile : Fin (2^(i.val+1))) (endpoint : Endpoint (n+F))\n    (he : endpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hside : endpoint.side=true)\n    (hsource : (SemiprimeD1ModeRoutingBits.acquire\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source≠\n        (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits) :\n    (bitValue endpoint.slot).testBit i.val=tile.val.testBit i.val := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner\n  obtain ⟨port,out,ho,hpacket,horigin⟩ := endpoint_origin owner source packet i g endpoint he\n  rcases horigin with ⟨heq,hrow⟩|⟨heq,hcolumn⟩\n  · have hnum := (testColour_correct (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits i.val\n      (SemiprimeD1PacketRows.read source.padding.source.selection.cache.rows.source.dictionary a out.source).left).mp hrow\n    have hs : (SemiprimeD1ModeRoutingBits.fromReplay source packet i tile).source≠\n        (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits := by\n      rw [(SemiprimeD1ModeRoutingBits.fromReplay_data source packet i tile).1]\n      exact hsource\n    have hcompact := (SemiprimeD1ModeRoutingOriginal.route_palette n F r a arity owner packet i tile).1\n    have hx : (((SemiprimeD1ModeRoutingOriginal.actualRows source out).left[i.val]?).getD [])≠\n        (SemiprimeD1ModeRoutingBits.fromReplay source packet i tile).source := by\n      intro hcolour\n      apply hs\n      apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ hcompact\n        (SemiprimeSourceHistogramPortKeys.encodeKey_compact g.val)\n      rw [←hcolour]\n      exact hnum\n    have hbit := SemiprimeD1ModeRoutingOriginal.crossing_testBit n F r a arity owner packet i tile out ho hpacket hx\n    simpa only [heq,endpoints] using hbit\n  · rw [heq] at hside\n    simp only [endpoints,Bool.false_eq_true] at hside\n\n/-- The physical coefficient bit test is true on each original crossing row. -/\ntheorem row_test_true (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (tile : Fin (2^(i.val+1))) (endpoint : Endpoint (n+F))\n    (he : endpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hside : endpoint.side=true)\n    (hsource : (SemiprimeD1ModeRoutingBits.acquire\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets[packet.val] a i tile).source≠\n        (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits) (bit : Bool) :\n    (SemiprimeD1PacketEntryBits.sameBit\n      (SemiprimeD1PacketEntryInputs.wire a endpoint bit).1.slot.val tile.val i.val).value=true := by\n  have hs := original_slot_length n F r a arity owner packet i g endpoint he\n  rw [SemiprimeD1PacketEntryBits.sameBit_value,SemiprimeD1PacketEntryInputs.wire_slot a endpoint bit hs,\n    row_samebit n F r a arity owner packet i g tile endpoint he hside hsource]\n  exact beq_self_eq_true _\n\n/-- Literal nonlocal branch flag of an actually acquired mode descriptor. -/\ndef nonlocalMask (item : SemiprimeD1PacketModeMask.Item) : Bool :=\n  item.inPacket && item.targetHere && !item.sourceHere\n\n/-- The actual acquired nonlocal mode mask discharges the coefficient's physical\nbit test on every original row. Source inequality is derived, not supplied. -/\ntheorem acquired_row_test_true (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (packet : Fin (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length)\n    (i : Fin a) (g : Fin r) (mode : SemiprimeD1ModeCatalog.Mode) (endpoint : Endpoint (n+F))\n    (he : endpoint∈((acquire n F r a arity owner i g).factors[packet.val]?).getD [])\n    (hside : endpoint.side=true)\n    (hmask : nonlocalMask (SemiprimeD1PacketModeMask.acquireOne\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner) packet i\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode)=true) (bit : Bool) :\n    let item := SemiprimeD1PacketModeMask.acquireOne\n      (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner) packet i\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode\n    (SemiprimeD1PacketEntryBits.sameBit\n      (SemiprimeD1PacketEntryInputs.wire a endpoint bit).1.slot.val (item.tile%2^a) i.val).value=true := by\n  let source := SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner\n  let item := SemiprimeD1PacketModeMask.acquireOne source packet i\n    (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode\n  change (item.inPacket && item.targetHere && !item.sourceHere)=true at hmask\n  change (SemiprimeD1PacketEntryBits.sameBit\n    (SemiprimeD1PacketEntryInputs.wire a endpoint bit).1.slot.val (item.tile%2^a) i.val).value=true\n  have hpacket : mode.slot/2^(i.val+1)=packet.val := by\n    by_contra hn\n    have hz := SemiprimeD1PacketModeMask.acquireOne_other source packet i\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode hn\n    have hm := (Bool.and_eq_true_iff.mp (Bool.and_eq_true_iff.mp hmask).1).1\n    change (SemiprimeD1PacketModeMask.acquireOne source packet i _ mode).inPacket=true at hm\n    rw [hz.1] at hm\n    cases hm\n  let tile : Fin (2^(i.val+1)) := ⟨mode.slot%2^(i.val+1),Nat.mod_lt _ (by positivity)⟩\n  have hh := SemiprimeD1PacketModeMask.acquireOne_here source packet i\n    (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits mode hpacket\n  have hs : (SemiprimeD1ModeRoutingBits.acquire source.state.packets[packet.val] a i tile).source≠\n      (SemiprimeSourceHistogramPortKeys.encodeKey g.val).bits := by\n    intro heq\n    have hflag := hh.2.2.mpr heq\n    have hn := (Bool.and_eq_true_iff.mp hmask).2\n    have hflag' : item.sourceHere=true := hflag\n    rw [hflag'] at hn\n    cases hn\n  have ht := row_test_true n F r a arity owner packet i g tile endpoint he hside hs bit\n  have htile : item.tile=tile.val := by\n    dsimp only [item,SemiprimeD1PacketModeMask.acquireOne]\n    simp only [hpacket,ite_true,tile]\n  have hlt : tile.val<2^a := tile.isLt.trans_le\n    (Nat.pow_le_pow_right (by omega : 0<2) (by omega : i.val+1≤a))\n  simpa only [htile,Nat.mod_eq_of_lt hlt] using ht\n\nend RiemannGaussian.SemiprimeD1PacketModeOriginal\n","RiemannGaussian.SemiprimeD1RecoveryIntegerBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryRowsBits\nimport RiemannGaussian.SemiprimeD1RecoveryCanonicalRun\n\n/-! # Physical canonical common-denominator integer accumulator\nThe arithmetic path uses existing actual unsigned/signed Boolean multiplication,\naddition, restoring floor division and paid fixed-width copies. Native integers\nbelow are specifications only; no native arithmetic result is encoded.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1RecoveryIntegerBits\nopen SemiprimeBitArithmetic SemiprimeBitDivision SemiprimeBitIndexClipping\nopen SemiprimeBitIndexTraversal SemiprimeRationalBits\n\n/-- Actual unsigned output and its physical arithmetic/copy report. -/\nstructure UnsignedReport where\n  /-- Actual Boolean output word. -/\n  bits : List Bool\n  /-- Actual gates, payload reads/writes and bounded control report. -/\n  clock : ℕ\n\n/-- Actual signed output and its physical arithmetic/copy report. -/\nstructure SignedReport where\n  /-- Actual signed Boolean word. -/\n  word : SignedWord\n  /-- All executed arithmetic and copied/discarded bit payloads. -/\n  clock : ℕ\n\n/-- An unsigned word is wrapped as a positive signed word without decoding it. -/\ndef positive (bits : List Bool) : SignedWord := ⟨false,bits⟩\n\n/-- Exact unsigned-to-signed payload interpretation. -/\ntheorem positive_value (bits : List Bool) : (positive bits).value=(bitValue bits:ℤ) := rfl\n\n/-- Multiply actual unsigned words and copy to the public bounded store. -/\ndef product (template xs ys : List Bool) : UnsignedReport :=\n  let raw:=mulBits xs ys\n  let out:=fitBits raw.bits template\n  ⟨out.bits,bitCost raw+bitCost out+3⟩\n\n/-- Product clipping preserves the actual integer whenever original bounds fit. -/\ntheorem product_value (template xs ys : List Bool)\n    (h : bitValue xs*bitValue ys < 2^template.length) :\n    bitValue (product template xs ys).bits=bitValue xs*bitValue ys := by\n  have hv:=mulBits_correct xs ys\n  have hc:=fitBits_value (by rw [hv]; exact h)\n  exact hc.trans hv\n\n/-- Every unsigned product occupies exactly the public physical width. -/\ntheorem product_length (template xs ys : List Bool) : (product template xs ys).bits.length=template.length :=\n  (fitBits_counts _ _).1\n\n/-- Every executed unsigned multiply/copy has quadratic primitive work. -/\ntheorem product_clock (template xs ys : List Bool)\n    (hx : xs.length ≤ template.length) (hy : ys.length ≤ template.length) :\n    (product template xs ys).clock ≤ 40*(template.length+1)^2+20 := by\n  have hm:=bounded_mulBits hx hy\n  have hc:=fitBits_cost (mulBits xs ys).bits template\n  simp only [product]\n  nlinarith only [hm.1,hc]\n\n/-- Actual signed multiplication followed by a paid bounded copy. -/\ndef signedProduct (template : List Bool) (x y : SignedWord) : SignedReport :=\n  let raw:=mulSignedBits x y\n  let out:=fitSignedBits raw.word template\n  ⟨out.word,raw.clock+out.clock+3⟩\n\n/-- No native signed multiplication executes in this data path. -/\ntheorem signedProduct_value (template : List Bool) (x y : SignedWord)\n    (h : (x.value*y.value).natAbs < 2^template.length) :\n    (signedProduct template x y).word.value=x.value*y.value := by\n  have hv:=mulSignedBits_value x y\n  have hc:=fitSignedBits_value (by rw [hv]; exact h)\n  exact hc.trans hv\n\n/-- Actual signed multiplication output width. -/\ntheorem signedProduct_length (template : List Bool) (x y : SignedWord) :\n    (signedProduct template x y).word.magnitude.length=template.length :=\n  (fitSignedBits_cost_width _ _).2\n\n/-- Full signed product, normalization-by-copy and discarded payload costs. -/\ntheorem signedProduct_clock (template : List Bool) (x y : SignedWord)\n    (hx : x.magnitude.length ≤ template.length) (hy : y.magnitude.length ≤ template.length) :\n    (signedProduct template x y).clock ≤ 40*(template.length+1)^2+20 := by\n  have hm:=mulSignedBits_cost_width hx hy\n  have hc:=(fitSignedBits_cost_width (mulSignedBits x y).word template).1\n  simp only [signedProduct]\n  nlinarith only [hm.1,hc]\n\n/-- Actual signed addition and paid clipping, with both signs represented physically. -/\ndef signedSum (template : List Bool) (x y : SignedWord) : SignedReport :=\n  let raw:=addSignedBits x y\n  let out:=fitSignedBits raw.word template\n  ⟨out.word,raw.clock+out.clock+3⟩\n\n/-- Exact signed sum from actual bit operations. -/\ntheorem signedSum_value (template : List Bool) (x y : SignedWord)\n    (h : (x.value+y.value).natAbs < 2^template.length) :\n    (signedSum template x y).word.value=x.value+y.value := by\n  have hv:=addSignedBits_value x y\n  have hc:=fitSignedBits_value (by rw [hv]; exact h)\n  exact hc.trans hv\n\n/-- Actual signed-sum output width. -/\ntheorem signedSum_length (template : List Bool) (x y : SignedWord) :\n    (signedSum template x y).word.magnitude.length=template.length :=\n  (fitSignedBits_cost_width _ _).2\n\n/-- Complete signed addition/copy primitive cost. -/\ntheorem signedSum_clock (template : List Bool) (x y : SignedWord)\n    (hx : x.magnitude.length ≤ template.length) (hy : y.magnitude.length ≤ template.length) :\n    (signedSum template x y).clock ≤ 50*(template.length+1)+10 := by\n  have hm:=addSignedBits_cost_width hx hy\n  have hc:=(fitSignedBits_cost_width (addSignedBits x y).word template).1\n  simp only [signedSum]\n  omega\n\n/-- Actual restoring signed division and bounded payload copy. -/\ndef quotient (template : List Bool) (x : SignedWord) (denominator : List Bool) : SignedReport :=\n  let raw:=floorSignedBits x denominator\n  let out:=fitSignedBits raw.word template\n  ⟨out.word,raw.clock+out.clock+3⟩\n\n/-- Floor division is the same original Euclidean integer operation. -/\ntheorem quotient_value (template : List Bool) (x : SignedWord) (denominator : List Bool)\n    (h : (x.value/(bitValue denominator:ℤ)).natAbs < 2^template.length) :\n    (quotient template x denominator).word.value=x.value/(bitValue denominator:ℤ) := by\n  have hv:=floorSignedBits_value x denominator\n  have hc:=fitSignedBits_value (by rw [hv]; exact h)\n  exact hc.trans hv\n\n/-- Every actual quotient output is physically bounded. -/\ntheorem quotient_length (template : List Bool) (x : SignedWord) (denominator : List Bool) :\n    (quotient template x denominator).word.magnitude.length=template.length :=\n  (fitSignedBits_cost_width _ _).2\n\n/-- Native integer division is replaced by actual quadratic Boolean division. -/\ntheorem quotient_clock (template : List Bool) (x : SignedWord) (denominator : List Bool)\n    (hx : x.magnitude.length ≤ template.length) (hd : denominator.length ≤ template.length) :\n    (quotient template x denominator).clock ≤ 160*(template.length+1)^2+20 := by\n  have hm:=floorSignedBits_cost_width hx hd\n  have hc:=(fitSignedBits_cost_width (floorSignedBits x denominator).word template).1\n  simp only [quotient]\n  nlinarith only [hm.1,hc]\n\n/-- Actual canonical row payloads paired with an actual child coefficient word. -/\nstructure Entry where\n  /-- Original canonical signed numerator bits. -/\n  numerator : SignedWord\n  /-- Original canonical positive denominator bits. -/\n  denominator : List Bool\n  /-- Actual unsigned child-residue bits. -/\n  child : List Bool\n\n/-- Proof-only canonical-entry projection, never called by the bit runtime. -/\ndef native (es : List Entry) : List SemiprimeD1RecoveryCanonicalRun.Entry :=\n  es.map fun e => ⟨e.numerator.value,bitValue e.denominator,e.child⟩\n\n/-- Actual physical product of every canonical denominator. -/\ndef denominator (template : List Bool) : List Entry → UnsignedReport\n  | [] => ⟨[true],3⟩\n  | e::es =>\n    let tail:=denominator template es\n    let out:=product template e.denominator tail.bits\n    ⟨out.bits,tail.clock+out.clock+3⟩\n\n/-- The actual native canonical accumulator is followed operation for operation:\nphysical quotient, two signed products and one signed suffix addition. -/\ndef accumulate (template denominator : List Bool) : List Entry → SignedReport\n  | [] => ⟨positive [],3⟩\n  | e::es =>\n    let tail:=accumulate template denominator es\n    let cofactor:=quotient template (positive denominator) e.denominator\n    let first:=signedProduct template e.numerator cofactor.word\n    let second:=signedProduct template first.word (positive e.child)\n    let out:=signedSum template second.word tail.word\n    ⟨out.word,tail.clock+cofactor.clock+first.clock+second.clock+out.clock+8⟩\n\n/-- The original common-denominator product is bounded from individual canonical\nrow heights, independently of cancellation or an advised final product. -/\ntheorem native_denominator_bound (es : List Entry) (A : ℕ)\n    (h : ∀ e ∈ es, bitValue e.denominator ≤ 2^A) :\n    (SemiprimeD1RecoveryCanonicalRun.denominator (native es)).value ≤ 2^(A*es.length) := by\n  induction es with\n  | nil => simp [native,SemiprimeD1RecoveryCanonicalRun.denominator]\n  | cons e es ih =>\n    have he:=h e (by simp)\n    have ht:=ih (fun x hx => h x (by simp [hx]))\n    change bitValue e.denominator *\n      (SemiprimeD1RecoveryCanonicalRun.denominator (native es)).value ≤ _\n    calc\n      _ ≤ 2^A * 2^(A*es.length) := Nat.mul_le_mul he ht\n      _ = 2^(A*(e::es).length) := by\n        simp only [List.length_cons, Nat.mul_add, Nat.mul_one, pow_add]\n        ac_rfl\n\n/-- Actual denominator multiplication refines the original native traversal,\nwith every suffix fit derived from the individual canonical denominator caps. -/\ntheorem denominator_correct (template : List Bool) (es : List Entry) (A : ℕ)\n    (h : ∀ e ∈ es, bitValue e.denominator ≤ 2^A)\n    (hW : A*es.length+1 ≤ template.length) :\n    bitValue (denominator template es).bits=\n      (SemiprimeD1RecoveryCanonicalRun.denominator (native es)).value := by\n  induction es with\n  | nil => simp [denominator,native,SemiprimeD1RecoveryCanonicalRun.denominator,\n      bitValue,bitNat]\n  | cons e es ih =>\n    have ht : ∀ x ∈ es, bitValue x.denominator ≤ 2^A :=\n      fun x hx => h x (by simp [hx])\n    have hWt : A*es.length+1 ≤ template.length := by\n      simp only [List.length_cons, Nat.mul_succ] at hW\n      omega\n    have hv:=ih ht hWt\n    have hb:=native_denominator_bound (e::es) A h\n    have he : bitValue e.denominator * bitValue (denominator template es).bits <\n        2^template.length := by\n      rw [hv]\n      change bitValue e.denominator *\n        (SemiprimeD1RecoveryCanonicalRun.denominator (native es)).value ≤ _ at hb\n      exact lt_of_le_of_lt hb (Nat.pow_lt_pow_right (by omega) (by omega))\n    exact product_value template e.denominator (denominator template es).bits he |>.trans\n      (by rw [hv]; rfl)\n\n/-- Every native right-recursive signed suffix has a cancellation-independent\ntriangle bound from the actual individual input words. -/\ntheorem native_accumulate_bound (D A C : ℕ) (es : List Entry)\n    (ha : ∀ e ∈ es, e.numerator.value.natAbs ≤ A)\n    (hc : ∀ e ∈ es, bitValue e.child ≤ C) :\n    (SemiprimeD1RecoveryCanonicalRun.accumulate D (native es)).value.natAbs ≤\n      es.length*A*D*C := by\n  induction es with\n  | nil => simp [native,SemiprimeD1RecoveryCanonicalRun.accumulate]\n  | cons e es ih =>\n    have hA:=ha e (by simp)\n    have hC:=hc e (by simp)\n    have ht:=ih (fun x hx => ha x (by simp [hx])) (fun x hx => hc x (by simp [hx]))\n    have hd : D / bitValue e.denominator ≤ D := Nat.div_le_self _ _\n    have he : (e.numerator.value * ((D / bitValue e.denominator : ℕ):ℤ) *\n        (bitValue e.child:ℤ)).natAbs ≤ A*D*C := by\n      simp only [Int.natAbs_mul, Int.natAbs_natCast]\n      exact Nat.mul_le_mul (Nat.mul_le_mul hA hd) hC\n    have hs:=Int.natAbs_add_le (e.numerator.value * ((D / bitValue e.denominator:ℕ):ℤ) *\n      (bitValue e.child:ℤ))\n      (SemiprimeD1RecoveryCanonicalRun.accumulate D (native es)).value\n    simp only [native,List.map_cons,SemiprimeD1RecoveryCanonicalRun.accumulate,\n      SemiprimeD1IntegerRecovery.decode_eq]\n    change (e.numerator.value * ((D / bitValue e.denominator:ℕ):ℤ) *\n      (bitValue e.child:ℤ) +\n      (SemiprimeD1RecoveryCanonicalRun.accumulate D (native es)).value).natAbs ≤ _\n    calc\n      _ ≤ A*D*C + es.length*A*D*C := hs.trans (Nat.add_le_add he ht)\n      _ = (e::es).length*A*D*C := by simp only [List.length_cons]; ring\n\n/-- Actual signed suffix arithmetic is exact from input-derived triangle caps.\nThe four guards bound cofactor/product/suffix sizes, not advised outputs. -/\ntheorem accumulate_correct (template denominatorBits : List Bool) (es : List Entry)\n    (D A C : ℕ) (hD : bitValue denominatorBits=D)\n    (ha : ∀ e ∈ es, e.numerator.value.natAbs ≤ A)\n    (hc : ∀ e ∈ es, bitValue e.child ≤ C)\n    (hd : D < 2^template.length) (hAD : A*D < 2^template.length)\n    (hADC : A*D*C < 2^template.length)\n    (hS : es.length*A*D*C < 2^template.length) :\n    (accumulate template denominatorBits es).word.value=\n      (SemiprimeD1RecoveryCanonicalRun.accumulate D (native es)).value := by\n  induction es with\n  | nil => rfl\n  | cons e es ih =>\n    have hA:=ha e (by simp)\n    have hC:=hc e (by simp)\n    have hAt : ∀ x ∈ es, x.numerator.value.natAbs ≤ A :=\n      fun x hx => ha x (by simp [hx])\n    have hCt : ∀ x ∈ es, bitValue x.child ≤ C :=\n      fun x hx => hc x (by simp [hx])\n    have hSt : es.length*A*D*C < 2^template.length := by\n      have hm : es.length*A*D*C ≤ (e::es).length*A*D*C :=\n        Nat.mul_le_mul_right C (Nat.mul_le_mul_right D\n          (Nat.mul_le_mul_right A (by simp)))\n      exact lt_of_le_of_lt hm hS\n    have ht:=ih hAt hCt hSt\n    have hdiv : D / bitValue e.denominator ≤ D := Nat.div_le_self _ _\n    have hvq : (quotient template (positive denominatorBits) e.denominator).word.value=\n        ((D / bitValue e.denominator:ℕ):ℤ) := by\n      have hfit : ((positive denominatorBits).value / (bitValue e.denominator:ℤ)).natAbs <\n          2^template.length := by\n        rw [positive_value,hD,←Int.natCast_ediv,Int.natAbs_natCast]\n        exact lt_of_le_of_lt hdiv hd\n      rw [quotient_value _ _ _ hfit,positive_value,hD,←Int.natCast_ediv]\n    have hp1 : (e.numerator.value *\n        (quotient template (positive denominatorBits) e.denominator).word.value).natAbs ≤ A*D := by\n      rw [hvq,Int.natAbs_mul,Int.natAbs_natCast]\n      exact Nat.mul_le_mul hA hdiv\n    have hv1:=signedProduct_value template e.numerator\n      (quotient template (positive denominatorBits) e.denominator).word\n      (lt_of_le_of_lt hp1 hAD)\n    have hp2 : ((signedProduct template e.numerator\n        (quotient template (positive denominatorBits) e.denominator).word).word.value *\n        (positive e.child).value).natAbs ≤ A*D*C := by\n      rw [Int.natAbs_mul,positive_value,Int.natAbs_natCast]\n      exact Nat.mul_le_mul (by rw [hv1]; exact hp1) hC\n    have hv2:=signedProduct_value template\n      (signedProduct template e.numerator\n        (quotient template (positive denominatorBits) e.denominator).word).word\n      (positive e.child) (lt_of_le_of_lt hp2 hADC)\n    have hsBound:=native_accumulate_bound D A C (e::es) ha hc\n    have hvsum : ((signedProduct template\n        (signedProduct template e.numerator\n          (quotient template (positive denominatorBits) e.denominator).word).word\n        (positive e.child)).word.value + (accumulate template denominatorBits es).word.value).natAbs <\n          2^template.length := by\n      rw [hv2,hv1,hvq,positive_value,ht]\n      simpa only [native,List.map_cons,SemiprimeD1RecoveryCanonicalRun.accumulate,\n        SemiprimeD1IntegerRecovery.decode_eq] using lt_of_le_of_lt hsBound hS\n    change (signedSum template _ _).word.value = _\n    rw [signedSum_value _ _ _ hvsum,hv2,hv1,hvq,positive_value,ht]\n    simp only [native,List.map_cons,SemiprimeD1RecoveryCanonicalRun.accumulate,\n      SemiprimeD1IntegerRecovery.decode_eq]\n\n/-- Every physical signed suffix occupies the public bounded store. -/\ntheorem accumulate_length (template denominatorBits : List Bool) (es : List Entry) :\n    (accumulate template denominatorBits es).word.magnitude.length ≤ template.length := by\n  cases es with\n  | nil => simp [accumulate,positive]\n  | cons e es => exact (signedSum_length _ _ _).le\n\n/-- The product store has one public width, including the literal empty product. -/\ntheorem denominator_length (template : List Bool) (es : List Entry) (ht : 0 < template.length) :\n    (denominator template es).bits.length ≤ template.length := by\n  cases es with\n  | nil => change 1 ≤ template.length; omega\n  | cons e es => exact (product_length _ _ _).le\n\n/-- Actual denominator scans/multiplications and fixed-store copies are paid. -/\ntheorem denominator_clock (template : List Bool) (es : List Entry) (ht : 0 < template.length)\n    (he : ∀ e ∈ es, e.denominator.length ≤ template.length) :\n    (denominator template es).clock ≤ es.length*(40*(template.length+1)^2+23)+3 := by\n  induction es with\n  | nil => simp [denominator]\n  | cons e es ih =>\n    have hc:=product_clock template e.denominator (denominator template es).bits\n      (he e (by simp)) (denominator_length template es ht)\n    have hi:=ih (fun x hx => he x (by simp [hx]))\n    change (denominator template es).clock +\n      (product template e.denominator (denominator template es).bits).clock+3 ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Every actual division, signed product/addition and copied word of the\nright-recursive accumulator is charged. -/\ntheorem accumulate_clock (template denominatorBits : List Bool) (es : List Entry)\n    (hd : denominatorBits.length ≤ template.length)\n    (he : ∀ e ∈ es, e.numerator.magnitude.length ≤ template.length ∧\n      e.denominator.length ≤ template.length ∧ e.child.length ≤ template.length) :\n    (accumulate template denominatorBits es).clock ≤\n      es.length*(300*(template.length+1)^2+100)+3 := by\n  induction es with\n  | nil => simp [accumulate]\n  | cons e es ih =>\n    have hE:=he e (by simp)\n    have hq:=quotient_clock template (positive denominatorBits) e.denominator hd hE.2.1\n    have h1:=signedProduct_clock template e.numerator\n      (quotient template (positive denominatorBits) e.denominator).word hE.1\n      (quotient_length _ _ _).le\n    have h2:=signedProduct_clock template\n      (signedProduct template e.numerator\n        (quotient template (positive denominatorBits) e.denominator).word).word\n      (positive e.child) (signedProduct_length _ _ _).le hE.2.2\n    have hs:=signedSum_clock template\n      (signedProduct template\n        (signedProduct template e.numerator\n          (quotient template (positive denominatorBits) e.denominator).word).word\n        (positive e.child)).word (accumulate template denominatorBits es).word\n      (signedProduct_length _ _ _).le (accumulate_length _ _ _)\n    have hi:=ih (fun x hx => he x (by simp [hx]))\n    change (accumulate template denominatorBits es).clock + _ + _ + _ + _ + 8 ≤ _\n    simp only [List.length_cons,Nat.add_mul,Nat.one_mul]\n    nlinarith only [hq,h1,h2,hs,hi]\n\n/-- Dyadic source-row and actual child-length bounds discharge every signed\ncofactor/product/suffix guard. No intermediate or output Fits is assumed. -/\ntheorem accumulate_dyadic (template denominatorBits : List Bool) (es : List Entry)\n    (D A K P : ℕ) (hD : bitValue denominatorBits=D)\n    (ha : ∀ e ∈ es, e.numerator.value.natAbs ≤ 2^A)\n    (hc : ∀ e ∈ es, e.child.length ≤ P)\n    (hl : es.length ≤ K) (hd : D ≤ 2^(A*K))\n    (hW : K+A+A*K+P+1 ≤ template.length) :\n    (accumulate template denominatorBits es).word.value=\n      (SemiprimeD1RecoveryCanonicalRun.accumulate D (native es)).value := by\n  have hC : ∀ e ∈ es, bitValue e.child ≤ 2^P := by\n    intro e he\n    exact (bitValue_lt_width e.child).le.trans (Nat.pow_le_pow_right (by omega) (hc e he))\n  have hAD : 2^A*D ≤ 2^(A+A*K) := by\n    simpa only [pow_add] using Nat.mul_le_mul_left (2^A) hd\n  have hADC : 2^A*D*2^P ≤ 2^(A+A*K+P) := by\n    simpa only [pow_add] using Nat.mul_le_mul_right (2^P) hAD\n  have hS : es.length*2^A*D*2^P ≤ 2^(K+A+A*K+P) := by\n    have hlp:=hl.trans (SemiprimeD1HermiteDenominatorBits.self_le_two_power K)\n    calc\n      _ = es.length*(2^A*D*2^P) := by ring\n      _ ≤ 2^K*2^(A+A*K+P) := Nat.mul_le_mul hlp hADC\n      _ = _ := by simp only [←pow_add]; congr 1; omega\n  apply accumulate_correct template denominatorBits es D (2^A) (2^P) hD ha hC\n  · exact lt_of_le_of_lt hd (Nat.pow_lt_pow_right (by omega) (by omega))\n  · exact lt_of_le_of_lt hAD (Nat.pow_lt_pow_right (by omega) (by omega))\n  · exact lt_of_le_of_lt hADC (Nat.pow_lt_pow_right (by omega) (by omega))\n  · exact lt_of_le_of_lt hS (Nat.pow_lt_pow_right (by omega) (by omega))\n\nend RiemannGaussian.SemiprimeD1RecoveryIntegerBits\n","RiemannGaussian.SemiprimeD1RecoveryNodeBitsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryNodeBitsCorrectness\n\n/-! # Closed actual physical node-weight arithmetic clocks\nThe reports price executed Boolean rational arithmetic, normalization/GCD,\ncoefficient scans and payload copies. Typed input/valuation/control construction\nremains distinctly retained native metadata, not a whole tape-machine clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1RecoveryNodeBitsBounds\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeJetArray\nopen SemiprimeD1RecoveryNodeBits SemiprimeD1RecoveryNodeBitsCorrectness\nopen SemiprimeD1RecoveryScalarRun SemiprimeD1RecoveryWeightRun\nopen SemiprimeD1WireKernelOriginal SemiprimeD1TaperedLoss\nopen SemiprimeD1JetRecoveryGrid\n\n/-- Actual power-cache length is the number of original cache indices. -/\ntheorem powers_length (template : List Bool) (argument : RationalWord) (keys : List ℕ) :\n    (SemiprimeD1RecoveryScalarWeightBits.powers template argument keys).words.length=keys.length := by\n  induction keys with\n  | nil => rfl\n  | cons k ks ih => simp only [SemiprimeD1RecoveryScalarWeightBits.powers,List.length_cons,ih]\n\n/-- Each acquired output weight is stored once. -/\ntheorem weights_length (template : List Bool) (q : ℕ) (scalar : RationalWord)\n    (inverse powers : List RationalWord) (keys js : List ℕ) :\n    (weights template q scalar inverse powers keys js).words.length=js.length := by\n  induction js with\n  | nil => rfl\n  | cons j js ih => simp only [weights,List.length_cons,ih]\n\n/-- Complete physical weight-list construction retains all local scans/GCDs. -/\ntheorem weights_clock (template : List Bool) (q : ℕ) (scalar : RationalWord)\n    (inverse powers : List RationalWord) (keys js : List ℕ) (ht : 0 < template.length) (A : ℕ)\n    (hi : inverse.length ≤ A) (hp : powers.length ≤ A)\n    (hiw : ∀x∈inverse,Width x template.length) (hpw : ∀x∈powers,Width x template.length)\n    (hs : Width scalar template.length) :\n    (weights template q scalar inverse powers keys js).clock ≤\n      js.length*(keys.length*SemiprimeD1RecoveryScalarWeightBits.sumStepBudget template.length q A+\n        20000*(template.length+1)^3+10)+1 := by\n  induction js with\n  | nil => simp [weights]\n  | cons j js ih =>\n    have cur:=SemiprimeD1RecoveryScalarWeightBits.weight_clock template q j scalar inverse powers keys ht A hi hp hiw hpw hs\n    simp only [weights,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Actual native address/index stages are retained for every physical weight. -/\ntheorem weights_metadataWork (template : List Bool) (q : ℕ) (scalar : RationalWord)\n    (inverse powers : List RationalWord) (keys js : List ℕ) :\n    (weights template q scalar inverse powers keys js).metadataWork ≤\n      js.length*(keys.length*(8*(q+1)+12)+7)+1 := by\n  induction js with\n  | nil => simp [weights]\n  | cons j js ih =>\n    have cur:=SemiprimeD1RecoveryScalarWeightBits.sum_metadataWork template q j inverse powers keys\n    simp only [weights,SemiprimeD1RecoveryScalarWeightBits.weight,List.length_cons,Nat.add_mul,Nat.one_mul]\n    omega\n\n/-- Pure monotonicity of the physical affine step budget. -/\ntheorem affine_step_mono (W J K : ℕ) (h : J ≤ K) :\n    SemiprimeAffineJetBits.stepBudget W J ≤ SemiprimeAffineJetBits.stepBudget W K := by\n  unfold SemiprimeAffineJetBits.stepBudget\n  gcongr\n\n/-- Pure monotonicity of actual scalar-scan step budgets. -/\ntheorem sum_step_mono (W q A m : ℕ) (hq : q ≤ m) (hA : A ≤ m) :\n    SemiprimeD1RecoveryScalarWeightBits.sumStepBudget W q A ≤\n      SemiprimeD1RecoveryScalarWeightBits.sumStepBudget W m m := by\n  unfold SemiprimeD1RecoveryScalarWeightBits.sumStepBudget\n  gcongr\n\n/-- Pure original taper substitution in the actual grid arithmetic budget. -/\ntheorem grid_budget_le (a M u W : ℕ) (hM : u ≤ M) :\n    SemiprimeD1RecoveryGridBitsBounds.budget a (height M u) u W ≤\n      SemiprimeD1RecoveryGridBitsBounds.budget a (m M) 1 W := by\n  have hm:=SemiprimeD1WeightPrecision.height_mul_le M u hM\n  unfold SemiprimeD1RecoveryGridBitsBounds.budget SemiprimeD1RecoveryGridBits.frameBudget m\n  simp only [Nat.mul_one]\n  gcongr\n\n/-- Literal closed physical arithmetic/read/copy node budget, entirely from\noriginal dimensions and the internally derived common word width. -/\ndef budget (a M W : ℕ) : ℕ :=\n  SemiprimeD1RecoveryGridBitsBounds.budget a (m M) 1 W+\n  (4+slopeCount a M*SemiprimeAffineJetBits.stepBudget W (m M))+\n  (1+m M*SemiprimeNormalizedInverseBitsBounds.stepBudget W (m M+1) (m M))+\n  (m M*(8*W+9)+1)+(m M*(m M*(20000*(W+1)^3+4)+6)+1)+\n  (m M*(m M*SemiprimeD1RecoveryScalarWeightBits.sumStepBudget W (m M) (m M)+20000*(W+1)^3+10)+1)+3*W+30\n\n/-- Actual original node arithmetic clock has no callback, operation-count,\nFits, source array or weight advice premise. -/\ntheorem acquireAt_clock (template : List Bool) (a M u : ℕ) (t : Fin (size a))\n    (hM : u ≤ M) (hW : width a M ≤ template.length) :\n    (acquireAt template a M u t).clock ≤ budget a M template.length := by\n  let q:=nodeMultiplicity a (height M u) u t.val\n  let grid:=SemiprimeD1RecoveryGridBits.acquire template a M u t\n  let den:=SemiprimeAffineJetBits.build template q grid.grid.slopes\n  let inv:=SemiprimeNormalizedInverseBits.build template den.words q\n  let memory:=SemiprimeSourceMemoryBits.copyMemory inv.words.toList\n  let keys:=(indices q).value\n  let powers:=SemiprimeD1RecoveryScalarWeightBits.powers template grid.argument keys\n  let rows:=weights template q grid.scalar memory.words powers.words keys keys\n  have ht : 0 < template.length := lt_of_lt_of_le (width_caps a M).2.2.2.2.2.2.2 hW\n  have hq : q ≤ m M := SemiprimeD1WeightPrecision.nodeMultiplicity_le a M u t.val hM\n  have gw:=(grid_width_le a M u hM).trans hW\n  have cg:=SemiprimeD1RecoveryGridBitsBounds.acquire_clock template a M u t gw\n  have cgMax:=(grid_budget_le a M u template.length hM)\n  have hs:=SemiprimeD1RecoveryGridBits.acquire_grid_correct template a M u t gw\n  have hl : grid.grid.slopes.length ≤ slopeCount a M := by\n    have hm:=congrArg List.length hs.2.2.1\n    rw [fullGrid_slopes] at hm\n    have hb:=slopes_length_le a M u t.val hM\n    simp only [List.length_map] at hm\n    change grid.grid.slopes.length=_ at hm\n    omega\n  have hsw : ∀x∈grid.grid.slopes,Width x template.length := hs.2.2.2.2.2.2.2.2\n  have cd:=SemiprimeAffineJetBits.build_clock template q grid.grid.slopes ht hsw\n  have dstep:=affine_step_mono template.length q (m M) hq\n  have dMax : grid.grid.slopes.length*SemiprimeAffineJetBits.stepBudget template.length q ≤\n      slopeCount a M*SemiprimeAffineJetBits.stepBudget template.length (m M) := Nat.mul_le_mul hl dstep\n  have dw:=SemiprimeAffineJetBits.build_bounded template q grid.grid.slopes ht\n  have dsize : den.words.size ≤ m M+1 := by\n    change (SemiprimeAffineJetBits.build template q grid.grid.slopes).words.size ≤ _\n    rw [SemiprimeAffineJetBits.build_size]\n    split_ifs <;> omega\n  have ci:=SemiprimeNormalizedInverseBitsBounds.build_clock template ht den.words (m M+1) (m M) dsize dw q hq\n  have iw:=SemiprimeNormalizedInverseBits.build_bounded template ht den.words q\n  have imw : ∀x∈inv.words.toList,Width x template.length := toList_bounded inv.words template.length iw\n  have cm:=SemiprimeSourceMemoryBits.copyMemory_clock inv.words.toList template.length imw\n  have mlen : memory.words.length=q := by\n    simp only [memory,SemiprimeSourceMemoryBits.copyMemory_words,Array.length_toList,inv,SemiprimeNormalizedInverseBits.build_size]\n  have mw : ∀x∈memory.words,Width x template.length := by rw [SemiprimeSourceMemoryBits.copyMemory_words]; exact imw\n  have xw:=(SemiprimeD1RecoveryGridBits.acquire_argument_correct template a M u t gw).2.2\n  have sw:=(SemiprimeD1RecoveryGridBits.acquire_scalar_correct template a M u t gw).2.2\n  have hk : ∀k∈keys,k ≤ q := by simp only [keys,indices_value,List.mem_range]; exact fun k h => h.le\n  have cp:=SemiprimeD1RecoveryScalarWeightBits.powers_clock template grid.argument q ht xw keys hk\n  have pw : ∀x∈powers.words,Width x template.length := by\n    have hx:=SemiprimeD1RecoveryGridBits.acquire_argument_correct template a M u t gw\n    have caps:=scalar_caps a M u t.val hM\n    exact (SemiprimeD1RecoveryScalarWeightBits.powers_correct template a (height M u) u t\n      grid.argument hx.1 hx.2.1 (caps.2.2.trans hW) keys hk).2.2\n  have plen : powers.words.length=q := by rw [powers_length]; simp [keys,indices_value]\n  have cw:=weights_clock template q grid.scalar memory.words powers.words keys keys ht q\n    (by rw [mlen]) (by rw [plen]) mw pw sw\n  have klen : keys.length=q := by simp [keys,indices_value]\n  rw [klen] at cp cw\n  have istep:=Nat.mul_le_mul_right (SemiprimeNormalizedInverseBitsBounds.stepBudget template.length (m M+1) (m M)) hq\n  have mcopy:=Nat.mul_le_mul_right (8*template.length+9) hq\n  have pMax : q*(q*(20000*(template.length+1)^3+4)+6) ≤\n      m M*(m M*(20000*(template.length+1)^3+4)+6) := by gcongr\n  have sstep:=sum_step_mono template.length q q (m M) hq hq\n  have wMax : q*(q*SemiprimeD1RecoveryScalarWeightBits.sumStepBudget template.length q q+\n      20000*(template.length+1)^3+10) ≤\n      m M*(m M*SemiprimeD1RecoveryScalarWeightBits.sumStepBudget template.length (m M) (m M)+\n        20000*(template.length+1)^3+10) := by gcongr\n  change _ ≤ budget a M template.length\n  simp only [acquireAt,multiplicityRun_value a (height M u) u t.val t.val t.isLt]\n  change grid.clock+den.clock+inv.clock+memory.clock+powers.clock+rows.clock+3*template.length+30 ≤ _\n  unfold budget\n  have ilen : inv.words.toList.length=q := by simp [inv,SemiprimeNormalizedInverseBits.build_size]\n  rw [ilen] at cm\n  dsimp only [q,grid,den,inv,memory,keys,powers,rows] at *\n  omega\n\n/-- ORIGINAL public node entry acquires its own template; no width advice. -/\ntheorem acquire_clock (a M u : ℕ) (t : Fin (size a)) (hM : u ≤ M) :\n    (SemiprimeD1RecoveryNodeBits.acquire a M u t).clock ≤ budget a M (width a M) := by\n  have h:=acquireAt_clock (List.replicate (width a M) false) a M u t hM (by simp)\n  simpa only [SemiprimeD1RecoveryNodeBits.acquire,widthRun_value,List.length_replicate] using h\n\nend RiemannGaussian.SemiprimeD1RecoveryNodeBitsBounds\n","RiemannGaussian.SemiprimeD1RecoveryWeightRunBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1RecoveryWeightRun\n\n/-! # Native acquisition stages of the original recovery weights\nThese are actual retained scalar/control reports. Rational normalization and\ninteger digit costs remain a separate refinement, not unit physical-bit steps.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1RecoveryWeightRunBounds\nopen SemiprimeD1RecoveryWeightRun SemiprimeD1RecoveryScalarRun\n\n/-- Every acquired multiplicity is bounded by the original taper rectangle. -/\ntheorem multiplicity_value_le (g : Geometry) (h u q : ℕ) :\n    (multiplicityRun g h u q).value ≤ h*u := by\n  dsimp [multiplicityRun]\n  exact Nat.mul_le_mul_left h (Nat.sub_le _ _)\n\n/-- Actual bounded valuation traversal, including multiplicity arithmetic. -/\ntheorem multiplicity_work (g : Geometry) (h u q : ℕ) :\n    (multiplicityRun g h u q).work ≤ 5*g.size+8 := by\n  have ho:=orderFuel_work g.size ((q:ℤ)-g.center).natAbs\n  dsimp only [multiplicityRun]\n  omega\n\n/-- Original grid traversal, powers and every copied slope cell are retained. -/\ntheorem grid_work (g : Geometry) (h u t : ℕ) (qs : List ℕ) :\n    (gridRows g h u t qs).work ≤ qs.length*(5*g.size+20*(h*u)+100)+1 := by\n  induction qs with\n  | nil => simp [gridRows]\n  | cons q qs ih =>\n    have hm:=multiplicity_value_le g h u q\n    have hw:=multiplicity_work g h u q\n    simp only [gridRows]\n    split_ifs\n    · dsimp only\n      simp only [List.length_cons]\n      nlinarith\n    · dsimp only\n      simp only [intPower_work,repeat_work,repeat_value,List.length_replicate,List.length_cons]\n      nlinarith\n\n/-- Each right-recursive scalar sum charges all visited indices. -/\ntheorem sum_work (j : ℕ) (inv powers : Array ℚ) (keys : List ℕ) :\n    (sumWeights j inv powers keys).work ≤ 7*keys.length+1 := by\n  induction keys with\n  | nil => simp [sumWeights]\n  | cons k ks ih =>\n    simp only [sumWeights]\n    split_ifs <;> dsimp only <;> simp only [List.length_cons] <;> omega\n\n/-- The outer scalar multiplication is charged in addition to the whole sum. -/\ntheorem weight_work (E : ℚ) (j : ℕ) (inv powers : Array ℚ) (keys : List ℕ) :\n    (weightRun E j inv powers keys).work ≤ 7*keys.length+4 := by\n  have h:=sum_work j inv powers keys\n  dsimp only [weightRun]\n  omega\n\n/-- Cached canonical extraction retains every supplied *executed* scalar report. -/\ntheorem canonical_work (rs : List (Run ℚ)) :\n    (canonicalRows rs).work=(rs.map (fun r => r.work)).sum+4*rs.length+1 := by\n  induction rs with\n  | nil => rfl\n  | cons r rs ih => simp only [canonicalRows,List.map_cons,List.sum_cons,List.length_cons,ih]; omega\n\n/-- The actual power cache has quadratic native scalar/control work. -/\ntheorem powers_work (x : ℚ) (q : ℕ) :\n    (powersRun x q).work ≤ 30*(q+1)^2 := by\n  have hs : ((List.range q).map (fun n => (rationalPower x n).work)).sum ≤ q*(3*q+1) := by\n    have he : ((List.range q).map (fun n => (rationalPower x n).work)).length • (3*q+1) = q*(3*q+1) := by simp\n    rw [← he]\n    apply List.sum_le_length_nsmul\n    intro n hn\n    obtain ⟨k,hk,rfl⟩:=List.mem_map.mp hn\n    rw [rationalPower_work]\n    have hk':=List.mem_range.mp hk\n    omega\n  simp only [powersRun,indices_work,indices_value,List.map_map,Function.comp_def,List.length_range]\n  nlinarith\n\n/-- Actual slope payload length, including every recursive grid frame. -/\ntheorem grid_length (g : Geometry) (h u t : ℕ) (qs : List ℕ) :\n    (gridRows g h u t qs).slopes.length ≤ qs.length*(h*u) := by\n  induction qs with\n  | nil => simp [gridRows]\n  | cons q qs ih =>\n    have hm:=multiplicity_value_le g h u q\n    simp only [gridRows]\n    split_ifs <;> dsimp only\n    · simp only [List.length_cons]; nlinarith\n    · simp only [List.length_append,repeat_value,List.length_replicate,List.length_cons]; nlinarith\n\n/-- Native canonical extraction of all original local weights is quadratic. -/\ntheorem local_rows_work (E : ℚ) (inv powers : Array ℚ) (keys : List ℕ) :\n    (canonicalRows (keys.map (fun j => weightRun E j inv powers keys))).work ≤\n      keys.length*(7*keys.length+8)+1 := by\n  rw [canonical_work]\n  have hs : ((keys.map (fun j => weightRun E j inv powers keys)).map (fun r => r.work)).sum ≤\n      keys.length*(7*keys.length+4) := by\n    have he : ((keys.map (fun j => weightRun E j inv powers keys)).map (fun r => r.work)).length •\n        (7*keys.length+4)=keys.length*(7*keys.length+4) := by simp\n    rw [← he]\n    apply List.sum_le_length_nsmul\n    intro z hz\n    obtain ⟨r,hr,rfl⟩:=List.mem_map.mp hz\n    obtain ⟨j,hj,rfl⟩:=List.mem_map.mp hr\n    exact weight_work E j inv powers keys\n  simp only [List.length_map]\n  nlinarith\n\n/-- A fully explicit fixed polynomial for the actual original node producer.\nThe parameters are the original exponent and acquired grid/taper dimensions,\nnever rational magnitudes or an advised operation count. -/\ndef nodeBudget (a N h u : ℕ) : ℕ :=\n  (3*a+8)+(N*N+4*N+1)+(N*(5*N+20*(h*u)+100)+1)+(5*N+8)+\n    2*(N*(h*u))*((h*u)*(h*u+1))+(3*(h*u)^2+2)+\n    ((h*u)^2+4*(h*u)+1)+30*(h*u+1)^2+(h*u)*(7*(h*u)+8)+1+4*(h*u)+20\n\n/-- Actual original node work has an original-parameter polynomial bound.\nThis bounds the retained native scalar/control report, not the cost of GCD or\nbig-integer primitives; those require the separately derived bit heights. -/\ntheorem acquire_work (a M u : ℕ) (t : Fin (SemiprimeD1WireKernelOriginal.size a)) :\n    (SemiprimeD1RecoveryWeightRun.acquire a M u t).work ≤\n      nodeBudget a (SemiprimeD1WireKernelOriginal.size a) (SemiprimeD1TaperedLoss.height M u) u := by\n  let g:=geometry a t.val\n  let h:=SemiprimeD1TaperedLoss.height M u\n  let q:=(multiplicityRun g h u t.val).value\n  let cs:=(gridRows g h u t.val (indices g.size).value).slopes\n  have hq : q ≤ h*u := multiplicity_value_le g h u t.val\n  have hg:=grid_work g h u t.val (indices g.size).value\n  have hl:=grid_length g h u t.val (indices g.size).value\n  have hm:=multiplicity_work g h u t.val\n  have hp:=powers_work (-(g.point:ℚ)/(g.alpha:ℚ)) q\n  have hc:=local_rows_work\n    (((gridRows g h u t.val (indices g.size).value).numerator:ℚ)/\n      ((gridRows g h u t.val (indices g.size).value).denominator:ℚ))\n    (SemiprimeJetArray.inverse (SemiprimeHermiteArrayHeight.buildAffine q cs).coefficients q).coefficients\n    (powersRun (-(g.point:ℚ)/(g.alpha:ℚ)) q).value (indices q).value\n  have ha:=SemiprimeHermiteArrayHeight.buildAffine_work q cs\n  have hi:=SemiprimeJetArray.inverse_work (SemiprimeHermiteArrayHeight.buildAffine q cs).coefficients q\n  have hgeom : g.work=3*a+8 := by simp [g,geometry,intPower_work]\n  have hsize : g.size=SemiprimeD1WireKernelOriginal.size a := geometry_size a t.val\n  simp only [indices_value,List.length_range] at hg hl hc\n  have hlin : 2*cs.length*(q*(q+1)) ≤ 2*(g.size*(h*u))*((h*u)*(h*u+1)) := by\n    gcongr\n    simpa only [cs,indices_value] using hl\n  have hpow : 30*(q+1)^2 ≤ 30*(h*u+1)^2 := by gcongr\n  have hquad : 3*q^2 ≤ 3*(h*u)^2 := by gcongr\n  have hidx : q*q+4*q+1 ≤ (h*u)^2+4*(h*u)+1 := by nlinarith\n  have hcan : q*(7*q+8) ≤ (h*u)*(7*(h*u)+8) := by gcongr\n  change g.work+(indices g.size).work+(gridRows g h u t.val (indices g.size).value).work+\n    (multiplicityRun g h u t.val).work+\n    (SemiprimeHermiteArrayHeight.buildAffine q cs).arithmetic+\n    (SemiprimeHermiteArrayHeight.buildAffine q cs).reads+\n    (SemiprimeJetArray.inverse (SemiprimeHermiteArrayHeight.buildAffine q cs).coefficients q).arithmetic+\n    (SemiprimeJetArray.inverse (SemiprimeHermiteArrayHeight.buildAffine q cs).coefficients q).reads+\n    (indices q).work+(powersRun (-(g.point:ℚ)/(g.alpha:ℚ)) q).work+_+4*(indices q).value.length+20 ≤ _\n  simp only [indices_work,indices_value,List.length_range,hgeom,ha.1,ha.2]\n  have hb : nodeBudget a (SemiprimeD1WireKernelOriginal.size a) (SemiprimeD1TaperedLoss.height M u) u = nodeBudget a g.size h u := by rw [hsize]\n  rw [hb]\n  unfold nodeBudget\n  change _ ≤ (3*a+8)+(g.size*g.size+4*g.size+1)+\n    (g.size*(5*g.size+20*(h*u)+100)+1)+(5*g.size+8)+\n    2*(g.size*(h*u))*((h*u)*(h*u+1))+(3*(h*u)^2+2)+\n    ((h*u)^2+4*(h*u)+1)+30*(h*u+1)^2+(h*u)*(7*(h*u)+8)+1+4*(h*u)+20\n  have haa:=ha.1\n  have har:=ha.2\n  have hia:=hi.1\n  have hir:=hi.2.1\n  dsimp only [g,h,q,cs] at *\n  simp only [indices_value,pow_two,Nat.mul_assoc] at *\n  omega\n\nend RiemannGaussian.SemiprimeD1RecoveryWeightRunBounds\n","RiemannGaussian.SemiprimeD1ReplayMetadataBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1PacketReplayBudget\n\n/-! # Actual replay metadata widths from its retained physical reports\nThe same step/replay recursion proves all observed packet and positive edge-ID\npayloads are bounded by the retained replay report. No encoded width or packet\ncatalogue is supplied. Original report envelopes may then replace that report.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1ReplayMetadataBounds\nopen SemiprimeD1PacketInventory SemiprimeSourceHistogramTrie\nopen SemiprimeSourceCompactBits SemiprimeBitArithmetic\n\n/-- Actual physical compact-add output allocation is paid in its report. -/\ntheorem add_output_length (a b : List Bool) : (add a b).bits.length ≤ (add a b).clock := by\n  have h:=trim_length (addBits a b false).bits\n  have hc:=trim_clock (addBits a b false).bits\n  unfold add\n  dsimp only\n  omega\n\n/-- Every stored observed-packet payload and header is covered by the actual report. -/\ndef PacketBound (state : State) : Prop := state.packets.length ≤ state.clock ∧\n  ∀p∈state.packets,p.length ≤ state.clock\n\n/-- Empty observed storage satisfies the literal bound at every original seed. -/\ntheorem initial_bound (clock : ℕ) : PacketBound (initial clock) := by simp [PacketBound,initial]\n\n/-- One physical replay step introduces at most one discovered packet. -/\ntheorem step_packet_count (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) :\n    (step dict a state key).2.packets.length ≤ state.packets.length+1 := by\n  simp only [step]\n  split_ifs\n  · simp only [List.length_cons];omega\n  · omega\n\n/-- Both actual output payload widths are paid in that SAME step's report. -/\ntheorem step_payload (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) :\n    (step dict a state key).1.packet.length ≤ (step dict a state key).2.clock ∧\n    (step dict a state key).1.edge.length ≤ (step dict a state key).2.clock := by\n  have h:=add_output_length state.next [true]\n  constructor\n  · simp only [step,copy_clock]\n    omega\n  · change (increment state.next).bits.length ≤ _\n    have hi : (increment state.next).bits.length ≤ (increment state.next).clock:=h\n    change _ ≤ state.clock+_+_+_+(increment state.next).clock+_+_+_+_+_+25\n    omega\n\n/-- A physical orientation step cannot create more than the parsed row's axes. -/\ntheorem step_slots (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) : (step dict a state key).1.slot.length ≤ a := by\n  exact (SemiprimeD1PacketReplayBudget.slots_length _ _ _).trans (SemiprimeD1PacketRows.parse_length _ _)\n\n/-- Packet data bound preserved by the actual discovery/copy branch. -/\ntheorem step_bound (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (state : State) (key : List Bool) (hb : PacketBound state) :\n    PacketBound (step dict a state key).2 := by\n  have hr:=step_retains dict a state key\n  have hp:=(step_payload dict a state key).1\n  have hbold:=hb.1\n  constructor\n  · have hc:=step_packet_count dict a state key\n    have hstrict : state.clock+1 ≤ (step dict a state key).2.clock := by unfold step;dsimp only;omega\n    omega\n  · intro p hm\n    simp only [step,copy_bits] at hm\n    split_ifs at hm\n    · rcases List.mem_cons.mp hm with rfl|hm\n      · exact hp\n      · exact (hb.2 p hm).trans hr\n    · exact (hb.2 p hm).trans hr\n\n/-- Every actual observed packet/header remains covered through the full replay. -/\ntheorem replay_bound (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) (hb : PacketBound state) :\n    PacketBound (replay dict a keys state).2 := by\n  induction keys generalizing state with\n  | nil => exact hb\n  | cons key keys ih => exact ih _ (step_bound dict a state key hb)\n\n/-- Every generated real placement's payload and slot are bounded, including\nall earlier placements still retained while later replay steps execute. -/\ntheorem replay_placements (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) :\n    ∀p∈(replay dict a keys state).1,\n      p.packet.length ≤ (replay dict a keys state).2.clock ∧\n      p.edge.length ≤ (replay dict a keys state).2.clock ∧ p.slot.length ≤ a := by\n  induction keys generalizing state with\n  | nil => simp [replay]\n  | cons key keys ih =>\n    intro p hm\n    change p∈(step dict a state key).1::(replay dict a keys (step dict a state key).2).1 at hm\n    rcases List.mem_cons.mp hm with rfl|hm\n    · have hp:=step_payload dict a state key\n      have hr:=replay_retains dict a keys (step dict a state key).2\n      exact ⟨hp.1.trans hr,hp.2.trans hr,step_slots dict a state key⟩\n    · exact ih _ p hm\n\n/-- The observed factor count is bounded by the REAL input stream, retaining duplicates. -/\ntheorem replay_count (dict : SemiprimeSourceHistogramRows.Dictionary) (a : ℕ)\n    (keys : List (List Bool)) (state : State) :\n    (replay dict a keys state).2.packets.length ≤ state.packets.length+keys.length := by\n  induction keys generalizing state with\n  | nil => simp [replay]\n  | cons key keys ih =>\n    have ht:=ih (step dict a state key).2\n    have hs:=step_packet_count dict a state key\n    change (replay dict a keys (step dict a state key).2).2.packets.length ≤ _\n    simp only [List.length_cons]\n    omega\n\n/-- Actual original acquisition satisfies the report-derived packet bound. -/\ntheorem original_packets (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    PacketBound (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state :=\n  replay_bound _ _ _ _ (initial_bound _)\n\n/-- Actual original real placement bytes have derived widths, with no advice. -/\ntheorem original_placements (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ∀p∈(SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).placements,\n      p.packet.length ≤ (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.clock ∧\n      p.edge.length ≤ (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.clock ∧\n      p.slot.length ≤ a := replay_placements _ _ _ _\n\n/-- No original observed factor count exceeds the actual number of input occurrences. -/\ntheorem original_count (n F r a : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (SemiprimeD1PacketReplayOriginal.acquire n F r a arity owner).state.packets.length ≤ ∑e,arity e := by\n  have h:=replay_count (SemiprimeD1PacketPadding.acquire n F r a arity owner).source.selection.cache.rows.source.dictionary\n    a (SemiprimeD1PacketPadding.acquire n F r a arity owner).source.keys\n    (initial (SemiprimeD1PacketPadding.acquire n F r a arity owner).clock)\n  simp only [initial,List.length_nil,Nat.zero_add] at h\n  change _ ≤ (SemiprimeD1IncidenceAcquisition.acquire n F r a arity owner).keys.length at h\n  exact h.trans (SemiprimeD1IncidenceAcquisitionBounds.keys_length n F r a arity owner).le\n\nend RiemannGaussian.SemiprimeD1ReplayMetadataBounds\n","RiemannGaussian.SemiprimeD1SelectedCollision":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1IncidenceSearch\nimport RiemannGaussian.SemiprimeD1CollisionOriginal\n\n/-! # Collision guarantee for actual incidence-only acquired labels\nAll graph ports, degree hypotheses and selected labels are original data. There\nis no supplied assignment, collision answer, desired objective or head penalty.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeD1SelectedCollision\nopen SemiprimeSourceHistogramGrouping\nopen SemiprimeD1CollisionOriginal SemiprimeD1CollisionVariance\nopen OAI.Algorithms.SubexponentialSAT.MulticolorTypes\n\n/-- Proof-side interpretation of the actual selected physical compact IDs. -/\ndef selectedLabel (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (i : (e : Fin F)×Fin (arity e)) : Word r a × Word r a :=\n  let env := SemiprimeSourceHistogramHeadOriginal.originalEnv r a\n    (SemiprimeD1IncidenceSearch.run n F r a arity owner).value\n  (SemiprimeMaterializedScoreEnvironment.denote env (owner i).val,\n    SemiprimeMaterializedScoreEnvironment.denote env (n+i.1.val))\n\n/-- Literal ordered-port-pair collisions of the actual selected labels.\nThis mathematical specification is not executed by the sparse selector. -/\ndef collisionSum (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) : ℚ :=\n  pairs (ports n F a arity) (fun i j => if selectedLabel n F r a arity owner i=\n    selectedLabel n F r a arity owner j then (1:ℚ) else 0)\n\n/-- Terminal count equals the exact collision sum of the acquired selector output. -/\ntheorem terminal_eq (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    ((SemiprimeSourceHistogramQueryCorrectness.originalCounts n F r a arity owner\n      (SemiprimeD1IncidenceSearch.run n F r a arity owner).value 0).incidence:ℚ)=\n      ((r^a:ℕ):ℚ)^4*collisionSum n F r a arity owner := by\n  simpa only [collisionSum,selectedLabel,Prod.mk.injEq] using\n    terminal_incidence n F r a arity owner (SemiprimeD1IncidenceSearch.run n F r a arity owner).value\n\n/-- Original D.3 collision budget for this actual deterministic selector.\nParallel incidences, diagonal ordered pairs and arbitrary degree distributions remain. -/\ntheorem selected_collision_le (n F r a : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (Δ : ℕ)\n    (ho : ∀ i∈ports n F a arity,\n      multiplicity (fun i => (owner i).val) (ports n F a arity) (owner i).val≤Δ)\n    (hf : ∀ i∈ports n F a arity,\n      multiplicity (fun i => n+i.1.val) (ports n F a arity) (n+i.1.val)≤Δ) :\n    collisionSum n F r a arity owner≤\n      ((ports n F a arity).length:ℚ)^2/((r^a:ℕ):ℚ)^2+\n        2*(ports n F a arity).length*Δ := by\n  have hs : ((SemiprimeSourceHistogramQueryCorrectness.originalCounts n F r a arity owner\n      (SemiprimeD1IncidenceSearch.run n F r a arity owner).value 0).incidence:ℚ)≤\n    ((SemiprimeSourceHistogramQueryCorrectness.originalCounts n F r a arity owner [] (n+F)).incidence:ℚ) := by\n    exact_mod_cast SemiprimeD1IncidenceSearch.counts_le_initial n F r a arity owner\n  have h := hs.trans (initial_incidence_le n F r a arity owner Δ ho hf)\n  rw [terminal_eq] at h\n  have hL : (0:ℚ)<(r^a:ℕ) := Nat.cast_pos.mpr (pow_pos (NeZero.pos r) a)\n  have he : ((r^a:ℕ):ℚ)^4*\n      (((ports n F a arity).length:ℚ)^2/((r^a:ℕ):ℚ)^2+\n        2*(ports n F a arity).length*Δ)=\n      ((r^a:ℕ):ℚ)^2*((ports n F a arity).length:ℚ)^2+\n        2*(ports n F a arity).length*Δ*((r^a:ℕ):ℚ)^4 := by\n    field_simp\n  rw [←he] at h\n  exact le_of_mul_le_mul_left h (pow_pos hL 4)\n\nend RiemannGaussian.SemiprimeD1SelectedCollision\n","RiemannGaussian.SemiprimeD1StackAllDescriptorRecordRootBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAllDescriptorRecordUniformBounds\nimport RiemannGaussian.SemiprimeD1BooleanFactorCatalogueIndicesOriginal\nimport RiemannGaussian.SemiprimeD1StackRootScheduleOriginal\n\n/-! # Uniform original-family actual descriptor acquisition envelope\nThe acquired original descriptor and scope bytes are estimated from the\nexisting actual N-only sources. This pointwise body bound feeds the whole\nfactor-catalogue loop; it does not replace that loop's acquisition clock.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackAllDescriptorRecordRootBounds\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace U\nexport SemiprimeD1StackAllDescriptorRecordUniformBounds (inventory envelope raw_length_le component_bound)\nend U\nnamespace O\nexport SemiprimeD1StackAllDescriptorRecordOriginal (rawFields originalCode raw_canonical raw_binaryN raw_transform_bound)\nend O\nnamespace IX\nexport SemiprimeD1BooleanFactorCatalogueIndices (scopeWords vertex)\nexport SemiprimeD1BooleanFactorCatalogueIndicesBounds\n  (occurrences scope_word_length_le scope_word_value_le scope_count_le descriptor_length_le)\nexport SemiprimeD1BooleanFactorCatalogueIndicesOriginal (scope_count_eq)\nend IX\n/-- Fixed original input-polynomial capacity before every original descriptor. -/\ndef baseCapacity (bits:List Bool) : Nat :=10^20*(bits.length+1)^6\n/-- Caller history and final-output bytes remain explicitly charged. -/\ndef capacity (bits hist out:List Bool) : Nat :=baseCapacity bits+hist.length+out.length\n/-- Original complete factor-table arity cap, with its actual three-quarter-power size. -/\ndef arityCapacity (bits:List Bool) : Nat :=SemiprimeMacroParameters.scopeBound bits.length\n/-- Every one of five framed descriptor fields is part of its actual record bytes. -/\ntheorem field_in_record (w:SemiprimeD1EdgeCatalogueEncoding.Record) (i:Fin 5) :\n    (w i).length ≤ (SemiprimeD1EdgeCatalogueEncoding.record w []).length := by\n  fin_cases i\n  · change (w 0).length ≤ _\n    simp only [SemiprimeD1EdgeCatalogueEncoding.record,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n  · change (w 1).length ≤ _\n    simp only [SemiprimeD1EdgeCatalogueEncoding.record,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n  · change (w 2).length ≤ _\n    simp only [SemiprimeD1EdgeCatalogueEncoding.record,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n  · change (w 3).length ≤ _\n    simp only [SemiprimeD1EdgeCatalogueEncoding.record,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n  · change (w 4).length ≤ _\n    simp only [SemiprimeD1EdgeCatalogueEncoding.record,SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil]\n    omega\n/-- Binary N plus the real serialized descriptor bounds every cached raw field. -/\ntheorem raw_field_bytes {r t digits:Nat} (bits:List Bool) (v:SemiprimeMacroGraph.SubdividedVertex r t digits)\n    (i:Fin 6) : (O.rawFields bits v i).length ≤\n      bits.length+(SemiprimeD1VertexCatalogueEncoding.vertex v []).length := by\n  rw [←SemiprimeD1EdgeCatalogueEncoding.record_vertex]\n  fin_cases i\n  · exact Nat.le_add_right _ _\n  · exact (field_in_record _ 0).trans (Nat.le_add_left _ _)\n  · exact (field_in_record _ 1).trans (Nat.le_add_left _ _)\n  · exact (field_in_record _ 2).trans (Nat.le_add_left _ _)\n  · exact (field_in_record _ 3).trans (Nat.le_add_left _ _)\n  · exact (field_in_record _ 4).trans (Nat.le_add_left _ _)\n/-- Physical scope framing is bounded without parsing any numerical identifier. -/\ntheorem vector_length (words:List (List Bool)) (M:Nat) (h:∀w∈words,w.length ≤ M) :\n    (vectorBits words).length ≤ 2*words.length*M+2*words.length+1 := by\n  have hs:(words.map List.length).sum ≤ words.length*M := by\n    induction words with\n    | nil=>simp\n    | cons w ws ih=>\n      have hw:=h w (by simp)\n      have ht:=ih (fun x hx=>h x (by simp [hx]))\n      simp only [List.map_cons,List.sum_cons,List.length_cons]\n      nlinarith\n  rw [SemiprimeD1TensorTapeCodec.vectorBits_length]\n  simp only [Nat.mul_assoc]\n  omega\n/-- The actual acquired occurrence-domain size has the original linear bound. -/\ntheorem occurrences_linear (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    IX.occurrences (bitValue bits) ≤ 12800*bits.length := by\n  have h:=SemiprimeD1RootTensorTables.actual_incidence_bound (bitValue bits) hN\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simp only [IX.occurrences,SemiprimeD1StackOwnerLookupOriginal.Public.occurrences]\n  simpa only [←hw] using h\n/-- Abstract arithmetic isolates polynomial scope bytes from native original enumeration. -/\ntheorem scope_arithmetic (M L:Nat) (hM:M ≤ 12800*L) :\n    2*M^2+2*M+1 ≤ 10^10*(L+1)^2 := by\n  have h:=Nat.pow_le_pow_left hM 2\n  nlinarith\n/-- The actual complete binary scope vector has a fixed quadratic input-width bound. -/\ntheorem scope_bytes (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) :\n    (vectorBits (IX.scopeWords bits f.val)).length ≤ 10^10*(bits.length+1)^2 := by\n  have h0:=vector_length (IX.scopeWords bits f.val) (IX.occurrences (bitValue bits))\n    (IX.scope_word_length_le bits hc hN f)\n  simp only [Nat.mul_assoc] at h0\n  have h1:=IX.scope_count_le bits hc hN f\n  have hm:=Nat.mul_le_mul_right (IX.occurrences (bitValue bits)) h1\n  have h2:(vectorBits (IX.scopeWords bits f.val)).length ≤\n      2*(IX.occurrences (bitValue bits))^2+2*IX.occurrences (bitValue bits)+1 := by\n    rw [pow_two]\n    omega\n  exact h2.trans (scope_arithmetic _ _ (occurrences_linear bits hc hN))\n/-- The actual selected scope count is the original factor arity, within its genuine cap. -/\ntheorem scope_arity (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) :\n    (IX.scopeWords bits f.val).length ≤ arityCapacity bits := by\n  rw [IX.scope_count_eq bits hc hN f]\n  have h:=SemiprimePublicAcquiredExecution.indexedArity_le (bitValue bits) f\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simpa only [arityCapacity,←hw] using h\n/-- The physically acquired product arity is also below the common original scope cap. -/\ntheorem product_arity (bits:List Bool) :\n    SemiprimeD1StackProductTableSpec.arity bits ≤ arityCapacity bits := by\n  unfold SemiprimeD1StackProductTableSpec.arity\n  rw [SemiprimeD1StackPublicProductBounds.cached_length]\n  unfold arityCapacity SemiprimeMacroParameters.scopeBound\n  exact Nat.mul_le_mul_right _ (by omega)\n/-- The real boundary writer's acquired depth fits the very same original cap. -/\ntheorem boundary_arity (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    (SemiprimeD1StackZeroBoundaryTable.cached bits).length ≤ arityCapacity bits := by\n  rw [SemiprimeD1StackZeroBoundaryTableBounds.original_depth bits hc,SemiprimeMacroParameters.axes_product]\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  rw [←hw]\n  unfold arityCapacity SemiprimeMacroParameters.scopeBound\n  exact Nat.le_mul_of_pos_left _ (by omega)\n/-- Every original acquired descriptor field has a fixed input-polynomial byte cap. -/\ntheorem raw_capacity (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) (i:Fin 6) :\n    (O.rawFields bits (IX.vertex (bitValue bits) f) i).length ≤ 10^15*(bits.length+1)^6 := by\n  have h0:=raw_field_bytes bits (IX.vertex (bitValue bits) f) i\n  have h1:=IX.descriptor_length_le bits hc hN f\n  have h5:(bits.length+1)^5 ≤ (bits.length+1)^6:=Nat.pow_le_pow_right (by omega) (by decide)\n  have hL:bits.length+1 ≤ (bits.length+1)^6:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega:1 ≤ bits.length+1) (by decide:1 ≤ 6)\n  omega\n/-- The same actual complete dispatcher clock has one bound for ALL original eighteen-tag rows. -/\ntheorem runBound_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) (hist out:List Bool) :\n    SemiprimeD1StackAllDescriptorRecordClock.runBound\n      (O.originalCode (IX.vertex (bitValue bits) f)) (O.rawFields bits (IX.vertex (bitValue bits) f))\n      (IX.scopeWords bits f.val) (IX.occurrences (bitValue bits)) hist out ≤\n        10^130*((capacity bits hist out+1)^18*2^(arityCapacity bits)) := by\n  have hL:bits.length+1 ≤ (bits.length+1)^6:=by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega:1 ≤ bits.length+1) (by decide:1 ≤ 6)\n  have h2:(bits.length+1)^2 ≤ (bits.length+1)^6:=Nat.pow_le_pow_right (by omega) (by decide)\n  have hraw:∀i,(O.rawFields bits (IX.vertex (bitValue bits) f) i).length ≤ capacity bits hist out:=by\n    intro i\n    have h:=raw_capacity bits hc hN f i\n    unfold capacity baseCapacity\n    omega\n  have hb:(vectorBits (IX.scopeWords bits f.val)).length ≤ capacity bits hist out:=by\n    have h:=scope_bytes bits hc hN f\n    unfold capacity baseCapacity\n    omega\n  have hh:hist.length ≤ capacity bits hist out:=by unfold capacity;omega\n  have ho:out.length ≤ capacity bits hist out:=by unfold capacity;omega\n  have hm:IX.occurrences (bitValue bits) ≤ capacity bits hist out:=by\n    have h:=occurrences_linear bits hc hN\n    unfold capacity baseCapacity\n    omega\n  exact SemiprimeD1StackAllDescriptorRecordUniformBounds.run_bound _ _ _ _ hist out _ _\n    hraw hb hh ho hm (scope_arity bits hc hN f) (product_arity bits) (boundary_arity bits hc)\n/-- The original body's own actual trace clock has the same uniform family bound. -/\ntheorem timeBound_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) (hist out:List Bool) :\n    SemiprimeD1StackAllDescriptorRecordSpec.timeBound\n      (O.originalCode (IX.vertex (bitValue bits) f)) (O.rawFields bits (IX.vertex (bitValue bits) f))\n      (IX.scopeWords bits f.val) hist out ≤\n        10^130*((capacity bits hist out+1)^18*2^(arityCapacity bits)) :=\n  (SemiprimeD1StackAllDescriptorRecordClock.timeBound_le _ _ _ _ hist out\n    (IX.scope_word_length_le bits hc hN f) (IX.scope_word_value_le bits hc hN f)).trans\n      (runBound_original bits hc hN f hist out)\n/-- Same actual fixed source execution for every original descriptor, with all\nretained caller bytes and every real decoder/loader/checker/cleanup step charged. -/\ntheorem source_run_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) (hist out:List Bool) :\n    ∃t ≤ 10^130*((capacity bits hist out+1)^18*2^(arityCapacity bits)),\n      SemiprimeD1StackCalls.run SemiprimeD1StackAllDescriptorRecord.program t\n        (SemiprimeD1StackAllDescriptorRecord.initial (O.rawFields bits (IX.vertex (bitValue bits) f))\n          (vectorBits (IX.scopeWords bits f.val)) hist out)=some\n            (SemiprimeD1StackAllDescriptorRecordSpec.done (O.originalCode (IX.vertex (bitValue bits) f))\n              (O.rawFields bits (IX.vertex (bitValue bits) f)) (IX.scopeWords bits f.val) hist out) := by\n  obtain ⟨htag,h2,h3,h4⟩:=O.raw_canonical bits (IX.vertex (bitValue bits) f)\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackAllDescriptorRecordClock.source_run_bounded _ _ htag h2 h3 h4\n    (O.raw_transform_bound bits (IX.vertex (bitValue bits) f)) hc hN (IX.scopeWords bits f.val) hist out\n    (IX.occurrences (bitValue bits)) (IX.scope_word_length_le bits hc hN f) (IX.scope_word_value_le bits hc hN f)\n  exact ⟨t,ht.trans (runBound_original bits hc hN f hist out),hr⟩\n/-- The genuine original scope exponent has the established three-quarter-power estimate. -/\ntheorem arityCapacity_fourth (bits:List Bool) (h:0<bits.length) :\n    (arityCapacity bits)^4 ≤ 512^4*bits.length^3 :=\n  SemiprimeMacroParameters.scopeBound_fourth_le h\n/-- With clear caller accumulators, the SAME actual row clock has a fixed\noriginal-width polynomial times the original arity exponential. -/\ntheorem timeBound_zero_history (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (SemiprimePublicAcquiredExecution.factorCount (bitValue bits))) :\n    SemiprimeD1StackAllDescriptorRecordSpec.timeBound\n      (O.originalCode (IX.vertex (bitValue bits) f)) (O.rawFields bits (IX.vertex (bitValue bits) f))\n      (IX.scopeWords bits f.val) [] [] ≤\n        (10^130*(10^21)^18)*(bits.length+1)^108*2^(arityCapacity bits) := by\n  have h:=timeBound_original bits hc hN f [] []\n  have hpos:1 ≤ (bits.length+1)^6:=Nat.pow_pos (by omega)\n  have hi:capacity bits [] []+1 ≤ 10^21*(bits.length+1)^6:=by\n    unfold capacity baseCapacity\n    simp only [List.length_nil,Nat.add_zero]\n    omega\n  have hp:=Nat.pow_le_pow_left hi 18\n  have hL:((bits.length+1)^6)^18=(bits.length+1)^108:=\n    (pow_mul (bits.length+1) 6 18).symm\n  rw [mul_pow,hL] at hp\n  have hm:=Nat.mul_le_mul_left (10^130) (Nat.mul_le_mul_right (2^(arityCapacity bits)) hp)\n  exact h.trans (by simpa only [Nat.mul_assoc] using hm)\nend RiemannGaussian.SemiprimeD1StackAllDescriptorRecordRootBounds\n","RiemannGaussian.SemiprimeD1StackAllDescriptorRecordWiring":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAllDescriptorRecord\n/-! # Injective actual component wiring and complete physical private inventory -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 3000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 1000000\nnamespace RiemannGaussian.SemiprimeD1StackAllDescriptorRecordWiring\nopen SemiprimeD1StackAllDescriptorRecord\nprivate theorem routed_injective {K : Type} (targets : K→Option Common) (key : Common→Option K)\n    (embed : K→Private) (he : Function.Injective embed)\n    (hk : ∀k c,targets k=some c→key c=some k) :\n    Function.Injective (fun k=>(targets k).elim (privateStack (embed k)) Sum.inl) :=by\n  intro a b h\n  cases ha:targets a with\n  | none=>\n    cases hb:targets b with\n    | none=>\n      simp only [ha,hb,Option.elim_none] at h\n      exact he (Sum.inr.inj h)\n    | some c=>simp only [ha,hb,Option.elim_none,Option.elim_some,privateStack] at h;cases h\n  | some c=>\n    cases hb:targets b with\n    | none=>simp only [ha,hb,Option.elim_none,Option.elim_some,privateStack] at h;cases h\n    | some d=>\n      simp only [ha,hb,Option.elim_some] at h\n      have hc:c=d:=Sum.inl.inj h\n      subst d\n      exact Option.some.inj ((hk a c ha).symm.trans (hk b c hb))\n/-- Proof-side partial inverse for the distinct actual metadata common operands. -/\ndef metadataKey {K : Type} : Common→Option (SemiprimeD1StackDescriptorRecord.Stack K)\n  | .source i=>some (.inr (.inl i))\n  | .bank=>some (.inl (.inl (.inr (.inr (.inl .bank)))))\n  | .history=>some (.inl (.inr (.inr .history)))\n  | .output=>some (.inl (.inr (.inr .output)))\n  | _=>none\n/-- Every shared metadata operand is exactly its unique literal component role. -/\ntheorem metadata_key {K : Type} (k : SemiprimeD1StackDescriptorRecord.Stack K) (c : Common)\n    (h : metadataAlias k=some c) : metadataKey c=some k :=by\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · simp only [metadataAlias] at h;cases h\n      · rcases k with k|k\n        · simp only [metadataAlias] at h;cases h\n        · rcases k with k|k\n          · cases k <;> simp_all [metadataAlias,metadataKey]\n            all_goals (subst c; rfl)\n          · simp only [metadataAlias] at h;cases h\n    · rcases k with k|k\n      · simp only [metadataAlias] at h;cases h\n      · cases k <;> simp_all [metadataAlias,metadataKey]\n        all_goals (subst c; rfl)\n  · rcases k with k|k\n    · simp_all [metadataAlias,metadataKey]\n      all_goals (subst c; rfl)\n    · simp only [metadataAlias] at h;cases h\n/-- Proof-side partial inverse for the distinct actual selected common operands. -/\ndef selectedKey {K : Type} : Common→Option (SemiprimeD1StackSelectedDescriptorRecord.Stack K)\n  | .source i=>if i=1 then some (.inr .tag) else if i=2 then some (.inr .transform) else some (.inl (.inr (.inl i)))\n  | c=>(metadataKey c).map Sum.inl\n/-- Every shared selected operand is exactly its unique literal component role. -/\ntheorem selected_key {K : Type} (k : SemiprimeD1StackSelectedDescriptorRecord.Stack K) (c : Common)\n    (h : selectedAlias k=some c) : selectedKey c=some k :=by\n  rcases k with d|k\n  · cases hd:metadataAlias d with\n    | none=>simp only [selectedAlias,hd] at h;cases h\n    | some a=>\n      have hv:=metadata_key d a hd\n      cases a with\n      | source i=>\n        by_cases hi:i=1 ∨ i=2\n        · simp only [selectedAlias,hd,hi,ite_true] at h;cases h\n        · have he:c=Common.source i:=by\n            simpa only [selectedAlias,hd,hi,ite_false,Option.some.injEq] using h.symm\n          subst c\n          have de:d=Sum.inr (Sum.inl i):=(Option.some.inj hv).symm\n          subst d\n          have h1:i≠1:=fun hh=>hi (Or.inl hh)\n          have h2:i≠2:=fun hh=>hi (Or.inr hh)\n          simp only [selectedKey,h1,h2,ite_false]\n      | bank=>\n        have hc:c=Common.bank:=by simpa only [selectedAlias,hd,Option.some.injEq] using h.symm\n        subst c\n        change (metadataKey Common.bank).map Sum.inl=some (.inl d)\n        rw [hv];rfl\n      | history=>\n        have hc:c=Common.history:=by simpa only [selectedAlias,hd,Option.some.injEq] using h.symm\n        subst c\n        change (metadataKey Common.history).map Sum.inl=some (.inl d)\n        rw [hv];rfl\n      | output=>\n        have hc:c=Common.output:=by simpa only [selectedAlias,hd,Option.some.injEq] using h.symm\n        subst c\n        change (metadataKey Common.output).map Sum.inl=some (.inl d)\n        rw [hv];rfl\n      | tagReader=>cases hv\n      | copyScratch=>cases hv\n  · cases k <;> simp_all [selectedAlias,selectedKey]\n    all_goals (subst c; rfl)\n/-- Proof-side partial inverse for the distinct actual product common operands. -/\ndef productKey : Common→Option P.Stack\n  | .source i=>if i=0 then some SemiprimeD1StackProductRecord.original else none\n  | .bank=>some (.inr (.inl .bank))\n  | .history=>some (.inr (.inr .history))\n  | .output=>some (.inr (.inr .output))\n  | _=>none\n/-- Every shared product operand is exactly its unique literal component role. -/\ntheorem product_key (k : P.Stack) (c : Common) (h : productAlias k=some c) : productKey c=some k :=by\n  rcases k with k|k\n  · rcases k with k|k\n    · simp only [productAlias] at h;cases h\n    · cases k <;> simp_all [productAlias,productKey,SemiprimeD1StackProductRecord.original,\n        SemiprimeD1StackProductRecord.tableStack,SemiprimeD1StackProductRecord.Z.original]\n      all_goals (subst c; rfl)\n  · rcases k with k|k\n    · cases k <;> simp_all [productAlias,productKey]\n      all_goals (subst c; rfl)\n    · cases k <;> simp_all [productAlias,productKey]\n      all_goals (subst c; rfl)\n/-- Proof-side partial inverse for the distinct actual boundary common operands. -/\ndef boundaryKey : Common→Option Z.Stack\n  | .source i=>if i=0 then some SemiprimeD1StackBoundaryRecord.original else none\n  | .bank=>some (.inr (.inl .bank))\n  | .history=>some (.inr (.inr .history))\n  | .output=>some (.inr (.inr .output))\n  | _=>none\n/-- Every shared boundary operand is exactly its unique literal component role. -/\ntheorem boundary_key (k : Z.Stack) (c : Common) (h : boundaryAlias k=some c) : boundaryKey c=some k :=by\n  by_cases hn:k=SemiprimeD1StackBoundaryRecord.original\n  · subst k\n    simp only [boundaryAlias,ite_true] at h\n    have he:=Option.some.inj h\n    subst c\n    rfl\n  · simp only [boundaryAlias,hn,ite_false] at h\n    rcases k with k|k\n    · cases h\n    · rcases k with k|k\n      · cases k <;> simp_all [boundaryKey]\n        all_goals (subst c; rfl)\n      · cases k <;> simp_all [boundaryKey]\n        all_goals (subst c; rfl)\n/-- Proof-side partial inverse for the distinct actual boolean common operands. -/\ndef booleanKey : Common→Option B.Stack\n  | .bank=>some (.inr (.inl .bank))\n  | .history=>some (.inr (.inr .history))\n  | .output=>some (.inr (.inr .output))\n  | _=>none\n/-- Every shared boolean operand is exactly its unique literal component role. -/\ntheorem boolean_key (k : B.Stack) (c : Common) (h : booleanAlias k=some c) : booleanKey c=some k :=by\n  rcases k with k|k\n  · simp only [booleanAlias] at h;cases h\n  · rcases k with k|k\n    · cases k <;> simp_all [booleanAlias,booleanKey]\n      all_goals (subst c; rfl)\n    · cases k <;> simp_all [booleanAlias,booleanKey]\n      all_goals (subst c; rfl)\n/-- Every actual input-client role has a distinct physical target. -/\ntheorem inputStack_injective : Function.Injective inputStack :=by\n  apply routed_injective metadataAlias metadataKey Sum.inl Sum.inl_injective metadata_key\n/-- Every actual carry-client role has a distinct physical target. -/\ntheorem carryStack_injective : Function.Injective carryStack :=by\n  apply routed_injective metadataAlias metadataKey (fun k=>.inr (.inl k))\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj h)) metadata_key\n/-- No computed-selector or original-source role collides in scale wiring. -/\ntheorem scaleStack_injective : Function.Injective scaleStack :=by\n  apply routed_injective selectedAlias selectedKey (fun k=>.inr (.inr (.inl k)))\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj (Sum.inr.inj h))) selected_key\n/-- Both actual transform selectors and every template/private shadow remain distinct. -/\ntheorem transformStack_injective : Function.Injective transformStack :=by\n  apply routed_injective selectedAlias selectedKey (fun k=>.inr (.inr (.inr (.inl k))))\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj h)))) selected_key\n/-- Actual original N, scope, caller and all product-private roles remain distinct. -/\ntheorem productStack_injective : Function.Injective productStack :=by\n  apply routed_injective productAlias productKey (fun k=>.inr (.inr (.inr (.inr (.inl k)))))\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj h))))) product_key\n/-- Actual boundary-source aliases have no private or caller collision. -/\ntheorem boundaryStack_injective : Function.Injective boundaryStack :=by\n  apply routed_injective boundaryAlias boundaryKey (fun k=>.inr (.inr (.inr (.inr (.inr (.inl k))))))\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj h)))))) boundary_key\n/-- Actual three-mode Boolean source aliases are injective. -/\ntheorem booleanStack_injective : Function.Injective booleanStack :=by\n  apply routed_injective booleanAlias booleanKey (fun k=>.inr (.inr (.inr (.inr (.inr (.inr k))))))\n    (by intro a b h;exact Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj h)))))) boolean_key\n/-- Original tag, reader and preserving-copy scratch are distinct real words. -/\ntheorem copyStack_injective : Function.Injective copyStack :=by decide\nend RiemannGaussian.SemiprimeD1StackAllDescriptorRecordWiring\n","RiemannGaussian.SemiprimeD1StackAxesArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAxesLoop\n\n/-! # Exact residue decomposition and original-input loop bounds\nAll native divisions and powers here are mathematical specifications, not\noperations in the fixed physical program.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackAxesArithmetic\nopen SemiprimeD1StackAxesLoop SemiprimeMacroParameters\n\n/-- Proof-side parity of the retained original exponent. -/\ndef odd (E:ℕ) : Bool := decide (E%2=1)\n/-- Exact parity marker count; no parity answer is supplied to the machine. -/\ntheorem tail_odd (E:ℕ) : tailBit (odd E)=E%2 := by\n  have hr:E%2<2:=Nat.mod_lt _ (by decide)\n  by_cases h:E%2=1\n  · simp [tailBit,odd,h]\n  · have hz:E%2=0:=by omega\n    simp [tailBit,odd,hz]\n/-- The actual exponent word is partitioned into physical pairs plus its final marker. -/\ntheorem exponent_parts (E:ℕ) : 2*(E/2)+tailBit (odd E)=E := by\n  rw [tail_odd]\n  omega\n/-- The odd-marker output is the original ceil-half exponent. -/\ntheorem second_exponent (E:ℕ) : E/2+tailBit (odd E)=E-E/2 := by\n  have h:=exponent_parts E\n  omega\n/-- The paired loop has a fixed polynomial times the largest visited counter. -/\ntheorem loop_bound (h:ℕ) (odd:Bool) (k:ℕ) :\n    loopTime k h odd≤(14*2^(k+h+1)+12)*(h+1) := by\n  induction h generalizing k with\n  | zero =>\n    cases odd <;> simp only [loopTime,Nat.add_zero,Nat.zero_add,Nat.mul_one,pow_succ'] <;> omega\n  | succ h ih =>\n    have hi:=ih (k+1)\n    have he:(k+1)+h+1=k+(h+1)+1:=by omega\n    rw [he] at hi\n    have hp:(2:ℕ)^k≤2^(k+(h+1)+1):=Nat.pow_le_pow_right (by decide) (by omega)\n    simp only [loopTime]\n    nlinarith\n/-- Closed original exponent-loop bound uses the actual retained R/E resources. -/\ntheorem original_loop_bound (E:ℕ) :\n    loopTime 0 (E/2) (odd E)≤(28*2^E+12)*(E+1) := by\n  have h:=loop_bound (E/2) (odd E) 0\n  have hp:(2:ℕ)^(0+E/2+1)≤2^(E+1):=Nat.pow_le_pow_right (by decide) (by omega)\n  have hd:E/2≤E:=Nat.div_le_self _ _\n  have hp2:(2:ℕ)^(E+1)=2*2^E:=pow_succ' _ _\n  rw [hp2] at hp\n  have hc:14*2^(0+E/2+1)+12≤28*2^E+12:=by omega\n  exact h.trans (Nat.mul_le_mul hc (by omega))\n/-- Exact complete original-input instruction count. -/\ndef totalTime (n:ℕ) : ℕ := SemiprimeD1StackTransformArithmetic.totalTime n+\n  10*transformExponent n+13+loopTime 0 (transformExponent n/2) (odd (transformExponent n))\n/-- Full original-input acquisition has one fixed quadratic transition cap. -/\ntheorem totalTime_le (n:ℕ) : totalTime n≤400000*(n+1)^2 := by\n  have hm:=SemiprimeD1StackTransformArithmetic.totalTime_le n\n  have he:=SemiprimeD1StackTransformArithmetic.exponent_bound n\n  have hr:=(SemiprimeD1StackTransformArithmetic.prefix_powers n (transformExponent n) (le_refl _)).1\n  have hl:=original_loop_bound (transformExponent n)\n  unfold totalTime\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackAxesArithmetic\n","RiemannGaussian.SemiprimeD1StackAxesLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackAxesLocal\n\n/-! # Executed paired exponent loop -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackAxesLoop\nopen SemiprimeD1StackAxes SemiprimeD1StackAxesComponents SemiprimeD1StackAxesLocal\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\n\n/-- Actual residue marker count, used only to state the executed loop. -/\ndef tailBit (odd:Bool) : ℕ := if odd then 1 else 0\n/-- Exact instruction count of paired doubling, including its real terminal EOF. -/\ndef loopTime (k:ℕ) : ℕ→Bool→ℕ\n  | 0,false => 1\n  | 0,true => 7*2^k+7\n  | h+1,odd => 14*2^k+12+loopTime (k+1) h odd\n\n/-- Two actual markers trigger both actual axis-doubling calls. -/\ntheorem pair (n:ℕ) (base:Meta.Stack→List Bool) (ew D:List Bool) :\n    Runs program (14*n+12) (.inl .first)\n      (data base (true::true::ew) [] [] (List.replicate n true) (List.replicate n true) D)\n      (.inl .first) (data base ew [] [] (List.replicate (2*n) true) (List.replicate (2*n) true) D) := by\n  have h0:Runs program 1 (.inl .first) (data base (true::true::ew) [] [] (List.replicate n true) (List.replicate n true) D) (.inl .second) (data base (true::ew) [] [] (List.replicate n true) (List.replicate n true) D):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .copyDepth) (.inl .second) (.inl .second)) _ _ rfl\n    · rfl\n    · funext j;cases j with\n      | inl j => cases j <;> simp [B.execute,data,Function.update]\n      | inr j => fin_cases j <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .second) (data base (true::ew) [] [] (List.replicate n true) (List.replicate n true) D) (.inl (.copyAxis 0)) (data base ew [] [] (List.replicate n true) (List.replicate n true) D):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl (.copyAxis 2)) (.inl (.copyAxis 0)) (.inl (.copyAxis 0))) _ _ rfl\n    · rfl\n    · funext j;cases j with\n      | inl j => cases j <;> simp [B.execute,data,Function.update]\n      | inr j => fin_cases j <;> simp [B.execute,data,Function.update]\n  have h2:=double_axis n 0 base ew (List.replicate n true) D\n  have h3:=double_axis n 1 base ew (List.replicate (2*n) true) D\n  simp only [axisData,afterAxis,ite_true,show ¬((1:Fin 3)=0) by decide,ite_false] at h2 h3\n  have h:=h0.trans (h1.trans (h2.trans h3))\n  simpa only [show 1+(1+((7*n+5)+(7*n+5)))=14*n+12 by omega] using h\n\n/-- The final unmatched marker doubles Q alone, with every EOF/return charged. -/\ntheorem odd_end (n:ℕ) (base:Meta.Stack→List Bool) (D:List Bool) :\n    Runs program (7*n+7) (.inl .first)\n      (data base [true] [] [] (List.replicate n true) (List.replicate n true) D)\n      (.inl .copyDepth) (data base [] [] [] (List.replicate n true) (List.replicate (2*n) true) D) := by\n  have h0:Runs program 1 (.inl .first) (data base [true] [] [] (List.replicate n true) (List.replicate n true) D) (.inl .second) (data base [] [] [] (List.replicate n true) (List.replicate n true) D):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl .copyDepth) (.inl .second) (.inl .second)) _ _ rfl\n    · rfl\n    · funext j;cases j with\n      | inl j => cases j <;> simp [B.execute,data,Function.update]\n      | inr j => fin_cases j <;> simp [B.execute,data,Function.update]\n  have h1:Runs program 1 (.inl .second) (data base [] [] [] (List.replicate n true) (List.replicate n true) D) (.inl (.copyAxis 2)) (data base [] [] [] (List.replicate n true) (List.replicate n true) D):=by\n    apply one_base program _ _ (.pop (.inl .squareWork) (.inl (.copyAxis 2)) (.inl (.copyAxis 0)) (.inl (.copyAxis 0))) _ _ rfl\n    · rfl\n    · funext j;cases j with\n      | inl j => cases j <;> simp [B.execute,data,Function.update]\n      | inr j => fin_cases j <;> simp [B.execute,data,Function.update]\n  have h2:=double_axis n 2 base [] (List.replicate n true) D\n  simp only [axisData,afterAxis,show ¬((2:Fin 3)=0) by decide,\n    show ¬((2:Fin 3)=1) by decide,ite_false] at h2\n  have h:=h0.trans (h1.trans h2)\n  simpa only [show 1+(1+(7*n+5))=7*n+7 by omega] using h\n\n/-- All pairs and the possible odd marker are physically executed in order. -/\ntheorem loop_run (h:ℕ) (odd:Bool) (k:ℕ) (base:Meta.Stack→List Bool) (D:List Bool) :\n    Runs program (loopTime k h odd) (.inl .first)\n      (data base (List.replicate (2*h+tailBit odd) true) [] []\n        (List.replicate (2^k) true) (List.replicate (2^k) true) D)\n      (.inl .copyDepth) (data base [] [] [] (List.replicate (2^(k+h)) true)\n        (List.replicate (2^(k+h+tailBit odd)) true) D) := by\n  induction h generalizing k with\n  | zero =>\n    cases odd with\n    | false =>\n      change Runs program 1 (.inl .first) (data base [] [] [] _ _ D) (.inl .copyDepth) (data base [] [] [] (List.replicate (2^k) true) (List.replicate (2^k) true) D)\n      apply one_base program _ _ (.pop (.inl .squareWork) (.inl .copyDepth) (.inl .second) (.inl .second)) _ _ rfl\n      · rfl\n      · funext j;cases j with\n        | inl j => cases j <;> simp [B.execute,data,Function.update]\n        | inr j => fin_cases j <;> simp [B.execute,data,Function.update]\n    | true =>\n      simpa only [loopTime,tailBit,ite_true,Nat.zero_mul,Nat.mul_zero,Nat.zero_add,Nat.add_zero,pow_succ',List.replicate_succ,List.replicate_zero] using odd_end (2^k) base D\n  | succ h ih =>\n    have h0:=pair (2^k) base (List.replicate (2*h+tailBit odd) true) D\n    have h1:=ih (k+1)\n    rw [←pow_succ'] at h0\n    have ht:2*(h+1)+tailBit odd=(2*h+tailBit odd)+2:=by omega\n    have hk:(k+1)+h=k+(h+1):=by omega\n    simpa only [loopTime,ht,List.replicate_succ,hk] using h0.trans h1\nend RiemannGaussian.SemiprimeD1StackAxesLoop\n","RiemannGaussian.SemiprimeD1StackBooleanEntryExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanEntry\n/-! # Exact real Copy/read/branch/clear traces for all Boolean assignments -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackBooleanEntryExecution\nopen SemiprimeD1StackBooleanEntry\nopen SemiprimeD1StackProcedureFragments (Runs one_base included_call)\n\n/-- Every assignment is physically copied once; no read-only input oracle. -/\ntheorem copy_call (mode : Mode) (bits : List Bool) :\n    Runs program (5*bits.length+4) (.inl (.start mode)) (data bits [] [] [])\n      (.inl (.first mode)) (data bits bits [] []) := by\n  apply included_call program copyStack copyLabel copyStack_injective\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (.inl (.start mode)) (.inl (.first mode)) rfl\n    (5*bits.length+3) (SemiprimeD1StackCopy.state 0 none bits [] [])\n    (SemiprimeD1StackCopy.done bits bits)\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words bits [] none\n  · constructor\n    · intro k; fin_cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; fin_cases k <;> rfl\n    · intro k hk\n      cases k with\n      | assignment => rfl\n      | reader => exact False.elim (hk 1 rfl)\n      | scratch => rfl\n      | output => rfl\n\n/-- One actual data pop; the next label holds ONLY its physically read Boolean. -/\ntheorem read_one (pc empty : Label) (next : Bool→Label) (assignment : List Bool)\n    (bit : Bool) (tail : List Bool)\n    (hcode : program pc=.base (.pop .reader empty (next false) (next true))) :\n    Runs program 1 pc (data assignment (bit::tail) [] []) (next bit) (data assignment tail [] []) := by\n  apply one_base program _ _ (.pop .reader empty (next false) (next true)) _ _ hcode\n  · cases bit <;> rfl\n  · funext k; cases k <;> rfl\n\n/-- The real empty-reader test is followed by a literal result push. -/\ntheorem finish_run (assignment : List Bool) (accepted : Bool) :\n    Runs program 2 (.inl (.clear accepted)) (data assignment [] [] [])\n      (.inl .done) (data assignment [] [] [accepted]) := by\n  have h0 : Runs program 1 (.inl (.clear accepted)) (data assignment [] [] [])\n      (.inl (.emit accepted)) (data assignment [] [] []) := by\n    apply one_base program _ _ (.pop .reader (.inl (.emit accepted))\n      (.inl (.clear accepted)) (.inl (.clear accepted))) _ _ rfl\n    · rfl\n    · funext k; cases k <;> rfl\n  have h1 : Runs program 1 (.inl (.emit accepted)) (data assignment [] [] [])\n      (.inl .done) (data assignment [] [] [accepted]) := by\n    apply one_base program _ _ (.push .output accepted (.inl .done)) _ _ rfl\n    · rfl\n    · funext k; cases k <;> rfl\n  exact h0.trans h1\n\n/-- All three original ordered bits are read and actually checked. -/\ntheorem or_body (assignment : List Bool) (a b c : Bool) :\n    Runs program 5 (.inl (.first .orGate)) (data assignment [a,b,c] [] [])\n      (.inl .done) (data assignment [] [] [decide (c=(a || b))]) := by\n  have h0:=read_one (.inl (.first .orGate)) (.inl (.clear false)) (afterFirst .orGate)\n    assignment a [b,c] rfl\n  have h1:=read_one (.inl (.orSecond a)) (.inl (.clear false))\n    (fun b=>.inl (.orThird a b)) assignment b [c] rfl\n  have h2:=read_one (.inl (.orThird a b)) (.inl (.clear false))\n    (fun c=>.inl (.clear (decide (c=(a || b))))) assignment c [] rfl\n  exact h0.trans (h1.trans (h2.trans (finish_run assignment _)))\n\n/-- The sole original input-check bit is physically read. -/\ntheorem input_body (assignment : List Bool) (a : Bool) :\n    Runs program 3 (.inl (.first .inputCheck)) (data assignment [a] [] [])\n      (.inl .done) (data assignment [] [] [a]) := by\n  have h:=read_one (.inl (.first .inputCheck)) (.inl (.clear false)) (afterFirst .inputCheck)\n    assignment a [] rfl\n  exact h.trans (finish_run assignment a)\n\n/-- Both ordered subdivided equality bits are physically read. -/\ntheorem equality_body (assignment : List Bool) (a b : Bool) :\n    Runs program 4 (.inl (.first .equality)) (data assignment [a,b] [] [])\n      (.inl .done) (data assignment [] [] [decide (a=b)]) := by\n  have h0:=read_one (.inl (.first .equality)) (.inl (.clear false)) (afterFirst .equality)\n    assignment a [b] rfl\n  have h1:=read_one (.inl (.equalSecond a)) (.inl (.clear false))\n    (fun b=>.inl (.clear (decide (a=b)))) assignment b [] rfl\n  exact h0.trans (h1.trans (finish_run assignment _))\n\n/-- Actual halt resets transient flags and clears the whole return stack. -/\ntheorem halt_after (mode : Mode) (bits : List Bool) (accepted : Bool) (m : ℕ)\n    (h : Runs program m (.inl (.start mode)) (data bits [] [] [])\n      (.inl .done) (data bits [] [] [accepted])) :\n    C.run program (m+1) (initial mode bits)=some (done bits accepted) := by\n  obtain ⟨finish,hfinish,hAt⟩:=h [] (initial mode bits) ⟨rfl,rfl,rfl⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hfinish,Option.bind_some]\n  rcases hAt with ⟨hpc,hd,hframes⟩\n  change C.step program finish=some (done bits accepted)\n  simp [C.step,SemiprimeD1StackCalls.step,hpc,program,C.execute,SemiprimeD1StackCalls.execute,\n    hd,hframes,done]\n\n/-- Closed 25-transition OR gate, with no truth/entry supplier. -/\ntheorem or_run (a b c : Bool) :\n    C.run program 25 (initial .orGate [a,b,c])=some (done [a,b,c] (decide (c=(a || b)))) :=\n  halt_after .orGate [a,b,c] _ _ ((copy_call .orGate [a,b,c]).trans (or_body [a,b,c] a b c))\n\n/-- Closed 13-transition input check, including its actual input-preserving copy. -/\ntheorem input_run (a : Bool) :\n    C.run program 13 (initial .inputCheck [a])=some (done [a] a) :=\n  halt_after .inputCheck [a] _ _ ((copy_call .inputCheck [a]).trans (input_body [a] a))\n\n/-- Closed 19-transition equality tensor, including real calls and cleanup. -/\ntheorem equality_run (a b : Bool) :\n    C.run program 19 (initial .equality [a,b])=some (done [a,b] (decide (a=b))) :=\n  halt_after .equality [a,b] _ _ ((copy_call .equality [a,b]).trans (equality_body [a,b] a b))\n\nend RiemannGaussian.SemiprimeD1StackBooleanEntryExecution\n","RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueView\nimport RiemannGaussian.SemiprimeD1StackFactorScopeFibreBounds\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual original-N setup of the retained-source Boolean factor sweep -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueSource\nopen SemiprimeD1StackBooleanFactorCatalogue SemiprimeD1StackBooleanFactorCatalogueView\nopen SemiprimeD1StackProcedureFragments (Runs included_call one_base)\nnamespace FS\nexport SemiprimeD1StackFactorScopeFibre (result)\nend FS\nnamespace VS\nexport SemiprimeD1StackVertexCatalogue (input initial)\nexport SemiprimeD1StackVertexCatalogueExecution (result done)\nend VS\n/-- With no pending descriptor or accumulator, all non-source physical roles are empty. -/\ntheorem empty_outer (fibre : F.Stack→List Bool) :\n    data fibre (fun _=>[]) (fun _=>[]) [] []=Sum.elim fibre (fun _=>[]) := by\n  funext k\n  rcases k with k|k|k|k\n  · rfl\n  · rfl\n  · rcases k with k|k|k\n    · rcases k with k|k|k\n      · cases k;rfl\n      · cases k <;> rfl\n      · cases k <;> rfl\n    · rfl\n    · cases k <;> rfl\n  · cases k;rfl\n/-- Actual source retains original binary N, without normalization or re-encoding. -/\ntheorem retained_N (bits : List Bool) : FS.result bits [] F.originalInput=bits := by rfl\n/-- The actual catalogue initializer loads binary N in exactly its single input role. -/\ntheorem catalogue_input (bits : List Bool) (k : V.Stack) :\n    VS.input bits k=(if k=V.originalInput then bits else []) := by\n  have hi:=SemiprimeD1StackCalls.initial_correct V.originalInput catalogueOutput (.inl .main) V.program bits\n  have he:=hi.trans (SemiprimeD1StackVertexCatalogueExecution.initial_eq bits)\n  have hd:=congrArg (fun cfg:SemiprimeD1StackVertexCatalogue.machine.Cfg=>cfg.stk (some k)) he\n  exact hd.symm\n/-- Genuine physical data after the complete source and its first actual factor query. -/\ndef afterSource (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (fun _=>[]) (fun _=>[]) [] []\n/-- Genuine physical data after the real preserving binary-N copy. -/\ndef afterCopy (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (VS.input bits) (fun _=>[]) [] []\n/-- Genuine physical data after all original descriptors are actually acquired. -/\ndef afterCatalogue (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (VS.result bits) (fun _=>[]) [] []\n/-- The loop-ready data include the one physically pushed final false terminator. -/\ndef ready (bits : List Bool) : Stack→List Bool :=\n  data (FS.result bits []) (VS.result bits) (fun _=>[]) [] [false]\n/-- One real included call executes the source once and computes the first actual scope. -/\ntheorem source_call (bits : List Bool) (hb:bits≠[]) :\n    ∃t ≤ SemiprimeD1StackFactorScopeFibreBounds.runBound bits [],\n      Runs program (t+1) (.local .main) (input bits) (.local .copyN) (afterSource bits) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackFactorScopeFibreExecution.source_run bits [] hb\n  refine ⟨t,ht.trans (SemiprimeD1StackFactorScopeFibreBounds.timeBound_le bits [] hb),?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program sourceStack Label.source Sum.inl_injective\n    F.program .main (fun _=>rfl) (.local .main) (.local .copyN) rfl t\n    (F.initial bits []) (SemiprimeD1StackFactorScopeFibre.done bits [])\n    (input bits) (afterSource bits) rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k=>exact (hk k rfl).elim\n      | inr k=>unfold afterSource;rw [empty_outer];rfl\n/-- Original binary N is copied physically; no second N value is preloaded. -/\ntheorem copy_N (bits : List Bool) :\n    Runs program (5*bits.length+4) (.local .copyN) (afterSource bits) (.local .catalogue) (afterCopy bits) := by\n  apply included_call program copyStack Label.copy copy_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) (.local .copyN) (.local .catalogue) rfl (5*bits.length+3)\n    (SemiprimeD1StackCopy.state 0 none bits [] []) (SemiprimeD1StackCopy.done bits bits)\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words bits [] none\n  · constructor\n    · intro k\n      fin_cases k\n      · exact retained_N bits\n      · rfl\n      · rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      fin_cases k\n      · exact retained_N bits\n      · change VS.input bits V.originalInput=bits\n        rw [catalogue_input,ite_eq_left rfl]\n      · rfl\n    · intro k hk\n      rcases k with k|k|k|k\n      · rfl\n      · have hn:k≠V.originalInput:=by intro h;subst k;exact hk 1 rfl\n        change VS.input bits k=[]\n        rw [catalogue_input,ite_eq_right hn]\n      · rfl\n      · rfl\n/-- The actual complete53-role original catalogue source runs after the paid N copy. -/\ntheorem catalogue_call (bits : List Bool) (hb:bits≠[]) :\n    ∃t ≤ 10000000000000*(bits.length+1)^5,\n      Runs program (t+1) (.local .catalogue) (afterCopy bits) (.local .seed) (afterCatalogue bits) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackVertexCatalogueBounds.source_run_polynomial bits hb\n  refine ⟨t,ht,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program catalogueStack Label.catalogue\n    (by intro a b h;exact Sum.inl_injective (Sum.inr_injective h)) V.program (.inl .main)\n    (fun _=>rfl) (.local .catalogue) (.local .seed) rfl t (VS.initial bits) (VS.done bits)\n    (afterCopy bits) (afterCatalogue bits) rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k|k|k\n      · rfl\n      · exact (hk k rfl).elim\n      · rfl\n      · rfl\n/-- The record terminator is one actual allocated false bit on the physical output. -/\ntheorem seed_run (bits : List Bool) :\n    Runs program 1 (.local .seed) (afterCatalogue bits) (.local .loop) (ready bits) := by\n  apply one_base program (.local .seed) (.local .loop) (.push output false (.local .loop)) _ _ rfl\n  · rfl\n  · exact update_output _ _ _ _ _ _\n/-- Own setup clock includes the source/filter, N copy, catalogue and false push. -/\ndef setupBound (bits : List Bool) : Nat :=\n  SemiprimeD1StackFactorScopeFibreBounds.runBound bits []+10000000000000*(bits.length+1)^5+5*bits.length+7\n/-- Complete original-N setup trace, before the separately required descriptor loop. -/\ntheorem setup_run (bits : List Bool) (hb:bits≠[]) :\n    ∃t ≤ setupBound bits,Runs program t (.local .main) (input bits) (.local .loop) (ready bits) := by\n  obtain ⟨s,hs,h0⟩:=source_call bits hb\n  have h1:=copy_N bits\n  obtain ⟨c,hc,h2⟩:=catalogue_call bits hb\n  have h3:=seed_run bits\n  refine ⟨(s+1)+((5*bits.length+4)+((c+1)+1)),?_,h0.trans (h1.trans (h2.trans h3))⟩\n  unfold setupBound\n  omega\nend RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueSource\n","RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogue\nimport RiemannGaussian.SemiprimeD1StackBooleanDescriptorRecordAll\n/-! # Exact physical views of the retained-source Boolean factor sweep -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueView\nopen SemiprimeD1StackBooleanFactorCatalogue\nnamespace DD\nexport SemiprimeD1StackBooleanDescriptorRecord (clean data recordInput)\nend DD\nnamespace DV\nexport SemiprimeD1StackBooleanDescriptorRecordView (update_cache)\nend DV\n/-- The literal original catalogue role shared with the descriptor's physical reader. -/\ndef catalogueOutput : V.Stack := V.kernelStack (SemiprimeD1StackCartesian4.aux 2)\n/-- The complete physical state, with empty alias shadows and copy scratch.\nActual reader and bank bytes reside only in their included source inventories. -/\ndef data (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out : List Bool) : Stack→List Bool :=\n  Sum.elim fibre (Sum.elim catalogue\n    (Sum.elim (DD.clean (DD.recordInput [] hist out) words []) (fun _=>[])))\n/-- Every physically retained source role is read unchanged. -/\ntheorem data_source (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out : List Bool) (k : F.Stack) :\n    data fibre catalogue words hist out (sourceStack k)=fibre k := rfl\n/-- Every physical catalogue role is read unchanged. -/\ntheorem data_catalogue (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out : List Bool) (k : V.Stack) :\n    data fibre catalogue words hist out (catalogueStack k)=catalogue k := rfl\n/-- The actual descriptor inclusion reads the real source bank and reader;\nboth unused aliases remain real empty roles in the outer inventory. -/\ntheorem data_descriptor (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out : List Bool) (k : D.Stack) :\n    data fibre catalogue words hist out (descriptorStack k)=\n      DD.clean (DD.recordInput (fibre F.output) hist out) words (catalogue catalogueOutput) k := by\n  rcases k with k|k|k\n  · rcases k with k|k|k\n    · cases k;rfl\n    · cases k <;> rfl\n    · cases k <;> rfl\n  · rfl\n  · cases k <;> rfl\n/-- The four real logger roles see empty consumed fields and actual accumulators. -/\ntheorem data_logger (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out : List Bool) (k : Log.Stack) :\n    data fibre catalogue words hist out (loggerStack k)=SemiprimeD1StackVertexRecordStream.data [] [] hist out k := by\n  cases k <;> rfl\n/-- The original-N preserving copy scratch is an actual empty role. -/\ntheorem data_scratch (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out : List Bool) :\n    data fibre catalogue words hist out scratch=[] := rfl\n/-- A real source write updates exactly that included physical source role. -/\ntheorem update_source (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out value : List Bool) (k : F.Stack) :\n    Function.update (data fibre catalogue words hist out) (sourceStack k) value=\n      data (Function.update fibre k value) catalogue words hist out := by\n  unfold data sourceStack\n  rw [Sum.update_elim_inl]\n/-- A real catalogue write updates exactly that included physical catalogue role. -/\ntheorem update_catalogue (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out value : List Bool) (k : V.Stack) :\n    Function.update (data fibre catalogue words hist out) (catalogueStack k) value=\n      data fibre (Function.update catalogue k value) words hist out := by\n  unfold data catalogueStack\n  rw [Sum.update_elim_inr,Sum.update_elim_inl]\n/-- Each real cached-descriptor drain changes exactly that physical finite field. -/\ntheorem update_cache (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out value : List Bool) (part : Fin 5) :\n    Function.update (data fibre catalogue words hist out) (descriptorStack (D.cache part)) value=\n      data fibre catalogue (Function.update words part value) hist out := by\n  have hk:descriptorStack (D.cache part)=.inr (.inr (.inl (D.cache part))):=rfl\n  rw [hk]\n  unfold data\n  rw [Sum.update_elim_inr,Sum.update_elim_inr,Sum.update_elim_inl]\n  simp only [DD.clean,DV.update_cache]\n/-- Actual history updates preserve every source byte, descriptor field and output accumulator. -/\ntheorem update_history (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out value : List Bool) :\n    Function.update (data fibre catalogue words hist out) history value=\n      data fibre catalogue words value out := by\n  funext k\n  rcases k with k|k|k|k\n  · rfl\n  · rfl\n  · rcases k with k|k|k\n    · rcases k with k|k|k\n      · cases k;rfl\n      · cases k <;> rfl\n      · cases k <;> rfl\n    · rfl\n    · cases k <;> rfl\n  · cases k;rfl\n/-- The one physical false terminator and final reversal write only actual output. -/\ntheorem update_output (fibre : F.Stack→List Bool) (catalogue : V.Stack→List Bool)\n    (words : Fin 5→List Bool) (hist out value : List Bool) :\n    Function.update (data fibre catalogue words hist out) output value=\n      data fibre catalogue words hist value := by\n  funext k\n  rcases k with k|k|k|k\n  · rfl\n  · rfl\n  · rcases k with k|k|k\n    · rcases k with k|k|k\n      · cases k;rfl\n      · cases k <;> rfl\n      · cases k <;> rfl\n    · rfl\n    · cases k <;> rfl\n  · cases k;rfl\n/-- Outer original-N input has no preloaded descriptor, bank, table or terminator. -/\ntheorem input_data (bits : List Bool) :\n    input bits=data (F.initial bits []).data (fun _=>[]) (fun _=>[]) [] [] := by\n  funext k\n  rcases k with k|k|k|k\n  · rfl\n  · rfl\n  · rcases k with k|k|k\n    · rcases k with k|k|k\n      · cases k;rfl\n      · cases k <;> rfl\n      · cases k <;> rfl\n    · rfl\n    · cases k <;> rfl\n  · cases k;rfl\nend RiemannGaussian.SemiprimeD1StackBooleanFactorCatalogueView\n","RiemannGaussian.SemiprimeD1StackBooleanRecordComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBooleanRecord\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\n/-! # Actual nested source calls with shared acquired logger operands -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackBooleanRecordComponents\nopen SemiprimeD1StackBooleanRecord SemiprimeD1StackProcedureTrace\n/-- Actual whole Boolean table acquisition leaves the scope bank and accumulators alone. -/\ntheorem table_call (mode : SemiprimeD1StackBooleanEntry.Mode) (bank hist out : List Bool) :\n    Runs program ((table mode).length+2) (.inl (.start mode))\n      (data (fun _=>[]) (S.initial bank).data hist out) (.inl .scope)\n      (data (fun _=>table mode) (S.initial bank).data hist out) := by\n  apply SemiprimeD1StackProcedureTrace.included_call program tableStack tableLabel\n    Sum.inl_injective T.code (mode,0) (fun _=>rfl) (.inl (.start mode)) (.inl .scope) rfl\n    ((table mode).length+1) (T.initial mode) (T.done mode)\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackBooleanTableSource.source_run mode\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k => exact (hk k rfl).elim\n      | inr k => rfl\n/-- The actual binary bank is preserved and its serialized output is the logger input. -/\ntheorem scope_call (mode : SemiprimeD1StackBooleanEntry.Mode) (words : List (List Bool)) (hist out : List Bool) :\n    ∃t≤SemiprimeD1StackPortOrdinalStreamExecution.timeBound words,\n      Runs program (t+1) (.inl .scope)\n        (data (fun _=>table mode) (S.initial (SemiprimeD1TensorTapeCodec.vectorBits words)).data hist out)\n        (.inl .record)\n        (data (fun _=>table mode) (SemiprimeD1StackPortOrdinalStreamExecution.done words).data hist out) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackPortOrdinalStreamExecution.source_run words\n  refine ⟨t,ht,?_⟩\n  apply SemiprimeD1StackProcedureInclusion.included_call program scopeStack scopeLabel\n    (by intro a b h;exact Sum.inl_injective (Sum.inr_injective h))\n    S.program (.control .start) (fun _=>rfl) (.inl .scope) (.inl .record) rfl t\n    (S.initial (SemiprimeD1TensorTapeCodec.vectorBits words))\n    (SemiprimeD1StackPortOrdinalStreamExecution.done words)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · cases k with\n        | inl k => exact (hk k rfl).elim\n        | inr k => rfl\n/-- Actual logger consumes the two aliased source outputs, with no encoded-answer copy. -/\ntheorem record_call (mode : SemiprimeD1StackBooleanEntry.Mode) (words : List (List Bool)) (hist out : List Bool) :\n    Runs program (R.recordTime (S.result words) (table mode)+1) (.inl .record)\n      (data (fun _=>table mode) (SemiprimeD1StackPortOrdinalStreamExecution.done words).data hist out)\n      (.inl .done) (done mode words hist out).data := by\n  apply SemiprimeD1StackProcedureTrace.included_call program recordStack recordLabel recordStack_injective\n    R.code .record (fun _=>rfl) (.inl .record) (.inl .done) rfl _\n    (⟨some .record,none,R.data (S.result words) (table mode) hist out⟩:\n      SemiprimeD1StackBytecode.State R.Stack R.Label)\n    (⟨none,none,R.data [] [] ((R.row (S.result words) (table mode)).reverse++hist) out⟩:\n      SemiprimeD1StackBytecode.State R.Stack R.Label)\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackVertexRecordStream.record_run _ _ _ _ _\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k\n      cases k <;> simp only [done,data,recordStack,scopeStack,tableStack,R.data,\n        Sum.elim_inl,Sum.elim_inr,Function.update_same]\n    · intro k hk\n      rcases k with k|k\n      · cases k\n        exact (hk SemiprimeD1StackVertexRecordStream.Stack.table rfl).elim\n      · cases k with\n        | inl k =>\n          have hne:k≠SemiprimeD1StackPortOrdinalStream.Stack.output:=by intro h;subst k;exact hk SemiprimeD1StackVertexRecordStream.Stack.ports rfl\n          simp only [done,data,Sum.elim_inl,Sum.elim_inr,Function.update_of_ne hne]\n        | inr k =>\n          cases k with\n          | ports => rfl\n          | table => rfl\n          | history => exact (hk SemiprimeD1StackVertexRecordStream.Stack.history rfl).elim\n          | output => exact (hk SemiprimeD1StackVertexRecordStream.Stack.output rfl).elim\nend RiemannGaussian.SemiprimeD1StackBooleanRecordComponents\n","RiemannGaussian.SemiprimeD1StackCachePhaseBankResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseBankBounds\n/-! # All246 physical tapes and genuine return cells\nThe fixed polynomial counts every retained source word, every stopped callee\ncache and every physical parser/logger/cleanup/return prefix of this program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseBankResources\nopen SemiprimeD1StackCachePhaseBank SemiprimeD1StackCachePhaseBankEncoding\nopen SemiprimeD1StackCachePhaseBankInputBounds SemiprimeD1StackCachePhaseBankBounds\nattribute [local irreducible] SemiprimeD1StackRootPhaseFreshRecordsEncoding.result\n  SemiprimeD1StackRootPhaseParametersEncoding.phases\n/-- Abstract four-word input length bound, before original graph substitution. -/\ntheorem initial_length (hp cn refs children:List Bool) (k:Stack):\n    ((initial hp cn refs children).data k).length ≤hp.length+cn.length+refs.length+children.length:=by\n  rcases k with k|k\n  · change ((P.input hp cn [] []) k).length ≤_\n    rw [SemiprimeD1StackCachePhaseBankBinding.input_base]\n    dsimp only\n    split_ifs <;> first | omega | exact Nat.zero_le _\n  · cases k <;> first | exact Nat.zero_le _ | change refs.length ≤_;omega | change children.length ≤_;omega\n/-- Every actual initialized word is paid by the four actual input tapes. -/\ntheorem source_length (bits:List Bool) (requests:List (Request bits)) (k:Stack):\n    ((source bits requests).data k).length ≤resource bits requests:=\n  initial_length _ _ _ _ k\n/-- Successful halt bounds every actual prefix, including all real outer and recursive return cells. -/\ntheorem prefix_cells (bits:List Bool) (requests:List (Request bits)) (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (source bits requests)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤10^103*(capacity bits requests)^18:=by\n  obtain ⟨t,ht,hstop⟩:=source_run_bounded bits requests\n  have htime:fuel ≤t:=by\n    by_contra hn\n    have he:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hstop,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hh:SemiprimeD1StackCalls.run program 1 (done bits requests)=none:=rfl\n    rw [hh,Option.bind_none] at hr\n    cases hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (resource bits requests)\n    _ _ (source_length bits requests) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length) ≤246*(resource bits requests+fuel):=by\n    calc\n      _ ≤∑_k:Stack,(resource bits requests+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have hlin:resource bits requests ≤(capacity bits requests)^18:=by\n    have hp:capacity bits requests ≤(capacity bits requests)^18:=by\n      simpa only [pow_one] using Nat.pow_le_pow_right (by unfold capacity;omega:1 ≤capacity bits requests) (by decide:1 ≤18)\n    exact (by unfold capacity;omega:resource bits requests ≤capacity bits requests).trans hp\n  change t ≤10^100*(capacity bits requests)^18 at ht\n  norm_num only at ht ⊢\n  omega\n/-- Genuine compiled-machine prefix bound for all246 data tapes and the actual return tape. -/\ntheorem machine_prefix_cells (bits:List Bool) (requests:List (Request bits)) (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun c=>c.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (source bits requests)))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤10^103*(capacity bits requests)^18:=by\n  have he:=SemiprimeD1StackCalls.run_correct heap output (.local .start) program fuel (source bits requests)\n  have hh:=he.trans hr\n  cases hout:SemiprimeD1StackCalls.run program fuel (source bits requests) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hc:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits requests fuel out hout\n/-- Honest prepared four-word compiled endpoint with the SAME actual whole-source clock. -/\nnoncomputable def bankInTime (bits:List Bool) (requests:List (Request bits)):\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (source bits requests))\n      (some (SemiprimeD1StackCalls.configuration (done bits requests))) (runBound bits requests):=by\n  apply SemiprimeD1StackCalls.evalsCorrect heap output (.local .start) program\n  let h:=source_run_bounded bits requests\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackCachePhaseBankResources\n","RiemannGaussian.SemiprimeD1StackCachePhaseCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhasePrimitives\n/-! # Three real whole-source calls, preserving all other allocated component words -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseCalls\nopen SemiprimeD1StackCachePhase SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- The actual heap/counter/issued reference drive one real complete restore, with child and block banks untouched. -/\ntheorem restore_call (banks:List (Fresh.Stack→List Bool)) (i:Fin banks.length)\n    (fold:Fold.Stack→List Bool) (blocks:Blocks.Stack→List Bool) (scratch:List Bool) :\n    ∃t≤SemiprimeD1StackFreshBankRestoreExecution.runBound banks i+1,\n      Runs program t (ctl .start)\n        (data (SemiprimeD1StackFreshBankRestoreExecution.source banks i).data fold blocks scratch)\n        (ctl .check) (data (SemiprimeD1StackFreshBankRestoreExecution.target banks i).data fold blocks scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackFreshBankRestoreExecution.source_run banks i\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program restoreStack Label.restore\n    (fun _ _ h=>Sum.inl.inj h) Restore.program (.inl .start) (fun _=>rfl)\n    (ctl .start) (ctl .check) rfl t\n    (SemiprimeD1StackFreshBankRestoreExecution.source banks i)\n    (SemiprimeD1StackFreshBankRestoreExecution.target banks i) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- The actual111-role ready fold, with all95 restored/cache words and all31 block words retained. -/\ntheorem fold_call (axes:List Nat) (hp:∀q∈axes,0<q) (precision:List Bool)\n    (modes:SemiprimeD1StackJetFoldWords.Modes) (restored:Restore.Stack→List Bool)\n    (blocks:Blocks.Stack→List Bool) (scratch:List Bool) :\n    ∃t≤SemiprimeD1StackJetFoldBounds.runBound axes precision modes+1,\n      Runs program t (ctl .fold)\n        (data restored (SemiprimeD1StackJetFoldContext.ready axes precision\n          (SemiprimeD1StackJetFoldWords.modeTape modes)).data blocks scratch)\n        (ctl (.copy .oldAxes)) (data restored (SemiprimeD1StackJetFoldExecution.done axes precision modes).data blocks scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackJetFoldBounds.ready_run_bounded axes hp precision modes\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program foldStack Label.fold\n    (fun _ _ h=>Sum.inl.inj (Sum.inr.inj h)) Fold.program (.local .prepared) (fun _=>rfl)\n    (ctl .fold) (ctl (.copy .oldAxes)) rfl t\n    (SemiprimeD1StackJetFoldContext.ready axes precision (SemiprimeD1StackJetFoldWords.modeTape modes))\n    (SemiprimeD1StackJetFoldExecution.done axes precision modes) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · exact (hk k rfl).elim\n        · rfl\n/-- The actual31-role ready block scan, preserving both complete preceding physical source banks. -/\ntheorem blocks_call (context:X.Stack→List Bool) (rank q:Nat)\n    (hrank:context X.rankCache=List.replicate rank true) (words:List (List Bool))\n    (restored:Restore.Stack→List Bool) (fold:Fold.Stack→List Bool) (scratch:List Bool) :\n    ∃t≤SemiprimeD1StackJetBlocksReady.readyBound rank q words+1,\n      Runs program t (ctl .blocks)\n        (data restored fold (SemiprimeD1StackJetBlocksReady.ready context q words).data scratch)\n        (ctl .done) (data restored fold (SemiprimeD1StackJetBlocksReady.done context rank q words).data scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackJetBlocksReady.ready_run context rank q hrank words\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program blockStack Label.blocks\n    (fun _ _ h=>Sum.inl.inj (Sum.inr.inj (Sum.inr.inj h))) Blocks.program (.local .ready) (fun _=>rfl)\n    (ctl .blocks) (ctl .done) rfl t\n    (SemiprimeD1StackJetBlocksReady.ready context q words)\n    (SemiprimeD1StackJetBlocksReady.done context rank q words) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · exact (hk k rfl).elim\n          · rfl\nend RiemannGaussian.SemiprimeD1StackCachePhaseCalls\n","RiemannGaussian.SemiprimeD1StackCachePhaseRejected":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackCachePhaseExecution\n/-! # Rejected phases restore their real record and emit an empty block vector\nNo prepared child field or context is consumed by the rejected branch. The\ncomplete restored record and original child tape remain physically retained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackCachePhaseRejected\nopen SemiprimeD1StackCachePhase SemiprimeD1StackCachePhaseView SemiprimeD1StackCachePhaseExecution\nopen SemiprimeD1StackCachePhasePrimitives SemiprimeD1StackCachePhaseCalls SemiprimeD1StackCachePhaseGuard\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- The same actual four-word input; children may be any literal tape on rejection. -/\ndef source (banks:List (Fresh.Stack→List Bool)) (i:Fin banks.length) (children:List Bool) :C.State Stack Label :=\n  initial (heap banks) (counter banks) (reference banks i) children\n/-- All238 words after actual rejection: full restored bank, original children and empty output vector. -/\ndef result (banks:List (Fresh.Stack→List Bool)) (i:Fin banks.length) (children:List Bool) :Stack→List Bool :=\n  data (restored banks i) (Fold.initial [] [] children).data\n    (Function.update (fun _=>[]) (Blocks.aux .output) [false]) []\n/-- Genuine rejected halt with all source/work/return flags clear. -/\ndef done (banks:List (Fresh.Stack→List Bool)) (i:Fin banks.length) (children:List Bool) :C.State Stack Label :=\n  ⟨none,none,none,result banks i children,[]⟩\n/-- Full rejected source really performs restore, guard peek, terminal push and halt. -/\ntheorem source_run (banks:List (Fresh.Stack→List Bool)) (i:Fin banks.length) (children:List Bool)\n    (hg:banks[i.val] (Fresh.contextStack (Header.aux .valid))=[false]) :\n    ∃t≤SemiprimeD1StackFreshBankRestoreExecution.runBound banks i+4,\n      SemiprimeD1StackCalls.run program t (source banks i children)=some (done banks i children) :=by\n  obtain ⟨a,ha,h0⟩:=restore_call banks i (Fold.initial [] [] children).data (fun _=>[]) []\n  have h1:=guard_run (data (restored banks i) (Fold.initial [] [] children).data (fun _=>[]) []) false hg\n  change Runs program 1 (ctl .check) _ (ctl .reject) _ at h1\n  have h2:=reject_run (data (restored banks i) (Fold.initial [] [] children).data (fun _=>[]) [])\n  change Runs program 1 _ _ _ (Function.update\n    (data (restored banks i) (Fold.initial [] [] children).data (fun _=>[]) [])\n    (blockStack (Blocks.aux .output)) [false]) at h2\n  rw [data_blocks] at h2\n  have h:=join (join h0 h1) h2\n  obtain ⟨out,ho,hAt⟩:=h [] (source banks i children) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run program (ctl .done) rfl (result banks i children) [] out hAt\n  exact ⟨(a+1+1)+1,by omega,by rw [SemiprimeD1StackReturnLink.run_add,ho,Option.bind_some];exact hh⟩\nend RiemannGaussian.SemiprimeD1StackCachePhaseRejected\n","RiemannGaussian.SemiprimeD1StackCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBytecode\n\n/-! # Finite procedure calls with an actual return stack\nData stacks contain Boolean payloads. The separate return stack contains fixed\nfinite program labels; it does not contain native counters or environments.\nEvery stack alphabet and all internal flags are finite. Captured data and heap\nframes remain explicit payload work, not unbounded internal control.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 500000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackCalls\n\n/-- Procedure instructions extend literal bytecode, with no function-valued operands. -/\ninductive Instruction (K L : Type) where\n  /-- One literal Boolean-stack instruction. -/\n  | base (instruction : SemiprimeD1StackBytecode.Instruction K L)\n  /-- Push the actual finite return label, then jump to the literal callee. -/\n  | call (callee continuation : L)\n  /-- Pop and jump to the actual saved return label; empty return stack halts. -/\n  | ret\n  deriving Repr\n\n/-- Source procedure state; all unbounded frames are actual stack payload. -/\nstructure State (K L : Type) where\n  /-- Finite current label. -/\n  pc : Option L\n  /-- Finite last Boolean read. -/\n  flag : Option Bool\n  /-- Finite last continuation read. -/\n  returned : Option L\n  /-- Actual Boolean argument/data stacks. -/\n  data : K→List Bool\n  /-- Actual unbounded return stack over the FIXED finite program-label alphabet. -/\n  frames : List L\n\n/-- Literal procedure execution, including actual return-frame push/pop. -/\ndef execute {K L : Type} [DecidableEq K] : Instruction K L→State K L→State K L\n  | .base (.push k b next),state =>\n    ⟨some next,state.flag,state.returned,Function.update state.data k (b::state.data k),state.frames⟩\n  | .base (.pop k empty low high),state =>\n    let bit:=(state.data k).head?\n    ⟨some (SemiprimeD1StackBytecode.choose empty low high bit),bit,state.returned,\n      Function.update state.data k (state.data k).tail,state.frames⟩\n  | .base (.peek k empty low high),state =>\n    let bit:=(state.data k).head?\n    ⟨some (SemiprimeD1StackBytecode.choose empty low high bit),bit,state.returned,state.data,state.frames⟩\n  | .base (.jump next),state => ⟨some next,state.flag,state.returned,state.data,state.frames⟩\n  | .base .halt,state => ⟨none,none,none,state.data,state.frames⟩\n  | .call callee continuation,state =>\n    ⟨some callee,none,none,state.data,continuation::state.frames⟩\n  | .ret,state =>\n    match state.frames with\n    | [] => ⟨none,none,none,state.data,[]⟩\n    | label::frames => ⟨some label,state.flag,some label,state.data,frames⟩\n\n/-- Executable first-order procedure step, independent of any solved-value supplier. -/\ndef step {K L : Type} [DecidableEq K] (code : L→Instruction K L) (state : State K L) : Option (State K L) :=\n  state.pc.map (fun label=>execute (code label) state)\n\n/-- Literal finite source transition traversal. -/\ndef run {K L : Type} [DecidableEq K] (code : L→Instruction K L) (fuel : ℕ)\n    (state : State K L) : Option (State K L) :=\n  (fun state=>state.bind (step code))^[fuel] (some state)\n\n/-- Actual typed finite alphabet family, indexed by return/data stack tags. -/\ndef symbols {K : Type} (L : Type) : Option K→Type\n  | none => L\n  | some _ => Bool\n\n/-- Encode the actual source stacks without interpreting or synthesizing any answer. -/\ndef payload {K L : Type} (state : State K L) : (k : Option K)→List (symbols L k)\n  | none => state.frames\n  | some k => state.data k\n\n/-- Actual target configuration with only finite flags in the internal state. -/\ndef configuration {K L : Type} (state : State K L) :\n    Turing.TM2.Cfg (symbols (K:=K) L) L (Option Bool×Option L) :=\n  ⟨state.pc,(state.flag,state.returned),payload state⟩\n\n/-- Fixed literal Boolean dispatch in the enlarged finite flag state. -/\ndef dispatch {K L : Type} (empty low high : L) :\n    Turing.TM2.Stmt (symbols (K:=K) L) L (Option Bool×Option L) :=\n  .branch (fun flag=>flag.1.isNone) (.goto (fun _=>empty))\n    (.branch (fun flag=>flag.1.getD false) (.goto (fun _=>high)) (.goto (fun _=>low)))\n\n/-- Compile actual procedure calls and returns to genuine stack operations. -/\ndef compileInstruction {K L : Type} (main : L) :\n    Instruction K L→Turing.TM2.Stmt (symbols (K:=K) L) L (Option Bool×Option L)\n  | .base (.push k b next) => .push (some k) (fun _=>b) (.goto (fun _=>next))\n  | .base (.pop k empty low high) =>\n    .pop (some k) (fun flag bit=>(bit,flag.2)) (dispatch empty low high)\n  | .base (.peek k empty low high) =>\n    .peek (some k) (fun flag bit=>(bit,flag.2)) (dispatch empty low high)\n  | .base (.jump next) => .goto (fun _=>next)\n  | .base .halt => .load (fun _=>(none,none)) .halt\n  | .call callee continuation => .push none (fun _=>continuation)\n      (.load (fun _=>(none,none)) (.goto (fun _=>callee)))\n  | .ret =>\n    .pop none (fun flag returned=>(flag.1,returned))\n      (.branch (fun flag=>flag.2.isNone) (.load (fun _=>(none,none)) .halt)\n        (.goto (fun flag=>flag.2.getD main)))\n\n/-- Fixed finite procedure machine; every alphabet, including returns, is finite. -/\ndef machine {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output : K) (main : L) (code : L→Instruction K L) : Turing.FinTM2 where\n  K:=Option K\n  k₀:=some input\n  k₁:=some output\n  Γ:=symbols L\n  Γk₀Fin:=inferInstanceAs (Fintype Bool)\n  Λ:=L\n  main:=main\n  σ:=Option Bool×Option L\n  initialState:=(none,none)\n  m label:=compileInstruction main (code label)\n\n/-- Every stack alphabet is finite, not only the input alphabet. -/\ntheorem all_alphabets_finite {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output : K) (main : L) (code : L→Instruction K L) :\n    ∀k,Finite ((machine input output main code).Γ k) := by\n  intro k\n  cases k with\n  | none => exact inferInstanceAs (Finite L)\n  | some k => exact inferInstanceAs (Finite Bool)\n\n/-- Internal control carries only finite Boolean and finite return-label flags. -/\ntheorem control_finite {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output : K) (main : L) (code : L→Instruction K L) :\n    Finite (machine input output main code).σ :=\n  inferInstanceAs (Finite (Option Bool×Option L))\n\n/-- At most one actual return frame is allocated by one source instruction. -/\ntheorem execute_frame_bound {K L : Type} [DecidableEq K]\n    (instruction : Instruction K L) (state : State K L) :\n    (execute instruction state).frames.length  ≤  state.frames.length+1 := by\n  cases instruction with\n  | base instruction => cases instruction <;> exact Nat.le_succ _\n  | call callee continuation => exact le_refl _\n  | ret => cases hf:state.frames <;> simp only [execute,hf,List.length_nil,List.length_cons] <;> omega\n/-- Updating an actual data stack commutes with the return/data stack encoding. -/\ntheorem payload_data {K L : Type} [DecidableEq K] (state : State K L)\n    (k : K) (bits : List Bool) :\n    payload {state with data:=Function.update state.data k bits}=\n      Function.update (payload state) (some k) bits := by\n  funext stack\n  cases stack with\n  | none => simp [payload,Function.update] ; rfl\n  | some j =>\n    by_cases h:j=k\n    · subst j\n      simp [payload,Function.update] ; rfl\n    · simp [payload,Function.update,h] ; rfl\n\n/-- Updating the actual finite-symbol return stack commutes with its encoding. -/\ntheorem payload_frames {K L : Type} [DecidableEq K] (state : State K L) (frames : List L) :\n    payload {state with frames:=frames}=Function.update (payload state) none frames := by\n  funext stack\n  cases stack with\n  | none => simp [payload,Function.update] ; rfl\n  | some j => simp [payload,Function.update] ; rfl\n\n/-- Finite Boolean dispatch preserves the actual remembered return flag. -/\ntheorem dispatch_correct {K L : Type} [DecidableEq K] (empty low high : L)\n    (flag : Option Bool) (returned : Option L) (store : (k:Option K)→List (symbols L k)) :\n    Turing.TM2.stepAux (dispatch empty low high) (flag,returned) store=\n      ⟨some (SemiprimeD1StackBytecode.choose empty low high flag),(flag,returned),store⟩ := by\n  cases flag with\n  | none => rfl\n  | some b => cases b <;> rfl\n\n/-- One source call/return/base instruction equals one actual finite-machine transition. -/\ntheorem instruction_correct {K L : Type} [DecidableEq K] (main : L)\n    (instruction : Instruction K L) (state : State K L) :\n    Turing.TM2.stepAux (compileInstruction main instruction) (state.flag,state.returned) (payload state)=\n      configuration (execute instruction state) := by\n  cases instruction with\n  | base instruction =>\n    cases instruction with\n    | push k b next =>\n      change Turing.TM2.Cfg.mk (some next) (state.flag,state.returned)\n        (Function.update (payload state) (some k) (b::state.data k))=\n        Turing.TM2.Cfg.mk (some next) (state.flag,state.returned)\n          (payload {state with data:=Function.update state.data k (b::state.data k)})\n      exact congrArg (fun store=>Turing.TM2.Cfg.mk (some next) (state.flag,state.returned) store)\n        (payload_data state k (b::state.data k)).symm\n    | pop k empty low high =>\n      change Turing.TM2.stepAux (dispatch empty low high) ((state.data k).head?,state.returned)\n        (Function.update (payload state) (some k) (state.data k).tail)=_\n      rw [dispatch_correct]\n      change Turing.TM2.Cfg.mk _ _ _=Turing.TM2.Cfg.mk\n        (some (SemiprimeD1StackBytecode.choose empty low high (state.data k).head?))\n        ((state.data k).head?,state.returned)\n        (payload {state with data:=Function.update state.data k (state.data k).tail})\n      rw [payload_data]\n    | peek k empty low high => exact dispatch_correct empty low high _ _ _\n    | jump next => rfl\n    | halt => rfl\n  | call callee continuation =>\n    change Turing.TM2.Cfg.mk (some callee) (none,none)\n      (Function.update (payload state) none (continuation::state.frames))=\n      Turing.TM2.Cfg.mk (some callee) (none,none)\n        (payload {state with frames:=continuation::state.frames})\n    exact congrArg (fun store=>(Turing.TM2.Cfg.mk (some callee) (none,none) store:\n      Turing.TM2.Cfg (symbols (K:=K) L) L (Option Bool×Option L)))\n      (payload_frames state (continuation::state.frames)).symm\n  | ret =>\n    cases hf:state.frames with\n    | nil =>\n      change Turing.TM2.stepAux\n        (.branch (fun flag:Option Bool×Option L=>flag.2.isNone)\n          (.load (fun _=>(none,none)) .halt) (.goto (fun flag=>flag.2.getD main)))\n        (state.flag,state.frames.head?) (Function.update (payload state) none state.frames.tail)=_\n      simp only [hf,List.head?_nil,List.tail_nil,Turing.TM2.stepAux,Option.isNone_none,Bool.cond_true,\n        execute,configuration]\n      change Turing.TM2.Cfg.mk none (none,none) (Function.update (payload state) none [])=\n        Turing.TM2.Cfg.mk none (none,none) (payload {state with frames:=[]})\n      exact congrArg (fun store=>(Turing.TM2.Cfg.mk none (none,none) store:\n        Turing.TM2.Cfg (symbols (K:=K) L) L (Option Bool×Option L)))\n        (payload_frames state []).symm\n    | cons label frames =>\n      change Turing.TM2.stepAux\n        (.branch (fun flag:Option Bool×Option L=>flag.2.isNone)\n          (.load (fun _=>(none,none)) .halt) (.goto (fun flag=>flag.2.getD main)))\n        (state.flag,state.frames.head?) (Function.update (payload state) none state.frames.tail)=_\n      simp only [hf,List.head?_cons,List.tail_cons,Turing.TM2.stepAux,Option.isNone_some,Bool.cond_false,Option.getD_some,\n        execute,configuration]\n      change Turing.TM2.Cfg.mk (some label) (state.flag,some label) (Function.update (payload state) none frames)=\n        Turing.TM2.Cfg.mk (some label) (state.flag,some label) (payload {state with frames:=frames})\n      exact congrArg (fun store=>Turing.TM2.Cfg.mk (some label) (state.flag,some label) store)\n        (payload_frames state frames).symm\n/-- Whole actual procedure-step refinement to the finite target machine. -/\ntheorem step_correct {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output : K) (main : L) (code : L→Instruction K L) (state : State K L) :\n    (machine input output main code).step (configuration state)=\n      (step code state).map configuration := by\n  cases state with\n  | mk pc flag returned data frames =>\n    cases pc with\n    | none => rfl\n    | some label =>\n      exact congrArg some\n        (instruction_correct main (code label) (⟨some label,flag,returned,data,frames⟩:State K L))\n\n/-- Actual finite source execution equals the target execution at the same step count. -/\ntheorem run_correct {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output : K) (main : L) (code : L→Instruction K L) (fuel : ℕ) (state : State K L) :\n    (run code fuel state).map configuration=\n      (fun cfg=>cfg.bind (machine input output main code).step)^[fuel] (some (configuration state)) := by\n  have h (n:ℕ) (state:Option (State K L)) :\n      ((fun state=>state.bind (step code))^[n] state).map configuration=\n        (fun cfg=>cfg.bind (machine input output main code).step)^[n] (state.map configuration) := by\n    induction n generalizing state with\n    | zero => rfl\n    | succ n ih =>\n      rw [Function.iterate_succ_apply',Function.iterate_succ_apply',←ih]\n      cases hs:((fun state=>state.bind (step code))^[n] state) with\n      | none => rfl\n      | some state => exact (step_correct input output main code state).symm\n  exact h fuel (some state)\n\n/-- Concrete source execution certificates become actual finite-machine time certificates. -/\ndef evalsCorrect {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output : K) (main : L) (code : L→Instruction K L) (start finish:State K L)\n    (time:ℕ) (h:StateTransition.EvalsToInTime (step code) start (some finish) time) :\n    StateTransition.EvalsToInTime (machine input output main code).step\n      (configuration start) (some (configuration finish)) time := by\n  refine ⟨⟨h.steps,?_⟩,h.steps_le_m⟩\n  have hr:=run_correct input output main code h.steps start\n  have he:=h.evals_in_steps\n  change run code h.steps start=some finish at he\n  rw [he] at hr\n  exact hr.symm\n\n/-- One actual successful source step allocates at most one return frame. -/\ntheorem step_frame_bound {K L : Type} [DecidableEq K] (code:L→Instruction K L)\n    (state out:State K L) (h:step code state=some out) :\n    out.frames.length ≤ state.frames.length+1 := by\n  cases hp:state.pc with\n  | none => simp only [step,hp,Option.map_none] at h;cases h\n  | some label =>\n    change (state.pc.map (fun label=>execute (code label) state))=some out at h\n    rw [hp,Option.map_some] at h\n    cases h\n    exact execute_frame_bound _ _\n\n/-- Source successor execution is a genuine final step, not a result lookup. -/\ntheorem run_succ {K L : Type} [DecidableEq K] (code:L→Instruction K L)\n    (fuel:ℕ) (state:State K L) :\n    run code (fuel+1) state=(run code fuel state).bind (step code) := by\n  unfold run\n  rw [Function.iterate_succ_apply']\n\n/-- Every reached return stack has a proved bound from actual executed source steps. -/\ntheorem run_frame_bound {K L : Type} [DecidableEq K] (code:L→Instruction K L)\n    (fuel:ℕ) (state out:State K L) (h:run code fuel state=some out) :\n    out.frames.length ≤ state.frames.length+fuel := by\n  induction fuel generalizing out with\n  | zero => change some state=some out at h;cases h;exact le_refl _\n  | succ fuel ih =>\n    rw [run_succ] at h\n    cases hm:run code fuel state with\n    | none => simp only [hm,Option.bind_none] at h;cases h\n    | some mid =>\n      have hs:step code mid=some out:=by simpa only [hm,Option.bind_some] using h\n      have hb:=step_frame_bound code mid out hs\n      have ht:=ih mid hm\n      omega\n\n/-- Actual initial source data with an EMPTY real return stack. -/\ndef initial {K L : Type} [DecidableEq K] (input:K) (main:L) (bits:List Bool) : State K L :=\n  ⟨some main,none,none,fun k=>if k=input then bits else [],[]⟩\n\n/-- Actual final source data with every auxiliary/return stack empty. -/\ndef final {K L : Type} [DecidableEq K] (output:K) (bits:List Bool) : State K L :=\n  ⟨none,none,none,fun k=>if k=output then bits else [],[]⟩\n\n/-- Finite source input encoding equals the actual machine input. -/\ntheorem initial_correct {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output:K) (main:L) (code:L→Instruction K L) (bits:List Bool) :\n    configuration (initial input main bits)=Turing.initList (machine input output main code) bits := by\n  dsimp only [configuration,initial,Turing.initList,machine]\n  congr 1\n  funext stack\n  cases stack with\n  | none => rfl\n  | some k =>\n    by_cases h:k=input\n    · subst k; simp [payload,symbols]; rfl\n    · simp [payload,symbols,h]\n\n/-- Finite source output encoding equals the actual clean halting configuration. -/\ntheorem final_correct {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output:K) (main:L) (code:L→Instruction K L) (bits:List Bool) :\n    configuration (final output bits:State K L)=Turing.haltList (machine input output main code) bits := by\n  dsimp only [configuration,final,Turing.haltList,machine]\n  congr 1\n  funext stack\n  cases stack with\n  | none => rfl\n  | some k =>\n    by_cases h:k=output\n    · subst k; simp [payload,symbols]; rfl\n    · simp [payload,symbols,h]\n\n/-- Actual source trace to the corresponding genuine finite-machine input/output bound. -/\ndef outputsOfSource {K L : Type} [DecidableEq K] [Fintype K] [Fintype L]\n    (input output:K) (main:L) (code:L→Instruction K L) (bits result:List Bool) (time:ℕ)\n    (h:StateTransition.EvalsToInTime (step code) (initial input main bits) (some (final output result)) time) :\n    Turing.TM2OutputsInTime (machine input output main code) bits (some result) time := by\n  have ht:=evalsCorrect input output main code _ _ time h\n  rw [initial_correct input output main code bits,final_correct input output main code result] at ht\n  exact ht\n\n/-- Each compiled call/return/base transition has at most four fundamental commands. -/\ntheorem compile_depth {K L : Type} (main:L) (instruction:Instruction K L) :\n    SemiprimeD1StackBytecode.statementDepth (compileInstruction main instruction) ≤ 4 := by\n  cases instruction with\n  | base instruction =>\n    cases instruction <;> simp only [compileInstruction,dispatch,SemiprimeD1StackBytecode.statementDepth] <;> decide\n  | call callee continuation => exact (by decide:3 ≤ 4)\n  | ret => exact (by decide:4 ≤ 4)\n/-- One fixed five-label procedure program, independent of every input word. -/\ndef prependCode (label:Fin 5) : Instruction Unit (Fin 5) :=\n  if label=0 then .call 2 1 else if label=1 then .base .halt\n  else if label=2 then .base (.push () true 3) else .ret\n\n/-- Concrete procedure machine; finite types and code are fixed before input. -/\ndef prependMachine : Turing.FinTM2 := machine () () 0 prependCode\n\n/-- Actual callee push, return, and caller halt preserve the arbitrary input tail. -/\ntheorem prepend_run (bits:List Bool) :\n    run prependCode 4 (initial () 0 bits)=some (final () (true::bits):State Unit (Fin 5)) := by\n  change some (⟨none,none,none,Function.update (fun k:Unit=>if k=() then bits else []) ()\n    (true::bits),[]⟩:State Unit (Fin 5))=_\n  congr 1\n\n/-- Actual finite procedure-machine input/output bound, not a supplied result trace. -/\ndef prependOutputs (bits:List Bool) :\n    Turing.TM2OutputsInTime prependMachine bits (some (true::bits)) 4 := by\n  apply outputsOfSource () () 0 prependCode bits (true::bits) 4\n  exact ⟨⟨4,prepend_run bits⟩,le_refl _⟩\nend RiemannGaussian.SemiprimeD1StackCalls\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationRow\n/-! # Own physical-byte polynomial for the actual activation iteration\nEvery bound below closes clocks from the literal component executions. All\ncapacities are proof estimates; no capacity/clock enters source control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationBounds\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryActivationView\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace RowSource\nexport SemiprimeD1StackChildGroupFactoryActivationRow (timeBound)\nend RowSource\n/-- Selected field and unread suffix can never exceed their actual source row. -/\ntheorem colour_result_lengths (coordinate:Nat) (colours:List (List Bool)):\n    (SemiprimeD1StackChildGroupFactoryColour.result coordinate colours).1.length≤(vectorBits colours).length ∧\n    (SemiprimeD1StackChildGroupFactoryColour.result coordinate colours).2.length≤(vectorBits colours).length:=by\n  induction coordinate generalizing colours with\n  | zero=>\n    cases colours with\n    | nil=>simp [SemiprimeD1StackChildGroupFactoryColour.result,vectorBits]\n    | cons w ws=>\n      simp only [SemiprimeD1StackChildGroupFactoryColour.result,vectorBits,List.length_cons,\n        SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\n  | succ n ih=>\n    cases colours with\n    | nil=>simp [SemiprimeD1StackChildGroupFactoryColour.result,vectorBits]\n    | cons w ws=>\n      have h:=ih ws\n      simp only [SemiprimeD1StackChildGroupFactoryColour.result,vectorBits,List.length_cons,\n        SemiprimeSourceHistogramKeyBits.frame_length] at h ⊢\n      omega\n/-- One actual row's SAME-program trace has a fixed quadratic byte bound. -/\ntheorem timeBound_le (i:Inputs) (key selected unread:List Bool) (coordinate:Nat)\n    (environment catalogue:List (List Bool×List Bool)) (colours:List (List Bool)) (S:Nat)\n    (he:i.environment=SemiprimeD1StackOwnerLookup.records environment [])\n    (hc:i.catalogue=SemiprimeD1StackOwnerLookup.records catalogue [])\n    (hi:i.colourIndex=List.replicate coordinate true)\n    (hr:SemiprimeD1StackPacketRowsAcquire.payload selected catalogue=SemiprimeD1PacketRows.serialize colours)\n    (hs:1≤S) (hk:key.length+1≤S) (hid:selected.length+1≤S) (hu:unread.length+1≤S)\n    (henv:i.environment.length+1≤S) (hcat:i.catalogue.length+1≤S)\n    (hcoord:coordinate+1≤S) (hcol:(vectorBits colours).length+1≤S) (hg:i.group.length+1≤S):\n    RowSource.timeBound i key selected unread coordinate environment catalogue colours≤100000000*S^2:=by\n  have hen:(SemiprimeD1StackOwnerLookup.records environment []).length+1≤S:=by simpa only [he] using henv\n  have hca:(SemiprimeD1StackOwnerLookup.records catalogue []).length+1≤S:=by simpa only [hc] using hcat\n  have hm:=(Nat.mul_le_mul hk hen)\n  have hl:=SemiprimeD1StackOwnerLookupBounds.time_le key environment\n  unfold SemiprimeD1StackOwnerLookupBounds.runBound at hl\n  have hlookup:SemiprimeD1StackOwnerLookupExecution.loopTime key environment+1≤100*S^2:=by\n    nlinarith\n  have hrow:=SemiprimeD1StackPacketRowsClock.timeBound_le selected selected catalogue colours colours hr hr rfl\n  have hsize:(SemiprimeSourceHistogramKeyBits.frame selected selected).length+\n      (SemiprimeD1StackOwnerLookup.records catalogue []).length+1≤4*S:=by\n    rw [SemiprimeSourceHistogramKeyBits.frame_length]\n    omega\n  have hp:=Nat.pow_le_pow_left hsize 2\n  unfold SemiprimeD1StackPacketRowsClock.polynomial SemiprimeD1StackPacketRowsClock.inputSize at hrow\n  have hpaired:SemiprimeD1StackPacketRowsExecution.timeBound selected selected catalogue colours colours≤1600000*S^2:=by\n    nlinarith\n  have hlengths:=colour_result_lengths coordinate colours\n  have hcolour:=SemiprimeD1StackChildGroupFactoryColour.time_le coordinate colours\n  have hequal:=SemiprimeD1StackWordEqualExecution.executionTime_le\n    ((SemiprimeD1StackChildGroupFactoryColour.result coordinate colours).1++[]) i.group\n  simp only [List.append_nil] at hequal\n  have hadd:=(SemiprimeBitArithmetic.addBits_counts key [true] false).2.2.2.2\n  simp only [List.length_cons,List.length_nil] at hadd\n  have hmax:max key.length 1≤S:=max_le (by omega) hs\n  have hs2:S≤S^2:=Nat.le_pow (by decide:0<(2:Nat))\n  dsimp only [RowSource.timeBound,\n    SemiprimeD1StackChildGroupFactoryActivationLookup.budget,\n    SemiprimeD1StackChildGroupFactoryActivationRows.budget,\n    SemiprimeD1StackChildGroupFactoryActivationLog.budget,\n    SemiprimeD1StackChildGroupFactoryActivationCleanup.budget,\n    SemiprimeD1StackChildGroupFactoryActivationIncrement.budget]\n  simp only [List.length_cons,List.length_nil,List.append_nil,hi,List.length_replicate,\n    SemiprimeSourceHistogramKeyBits.frame_length]\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLog":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationView\n/-! # Actual whole activation source block, with its complete115-word boundary -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLog\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryCalls SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackChildGroupFactoryActivation SemiprimeD1StackChildGroupFactoryActivationView\nopen SemiprimeSourceHistogramKeyBits (frame)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Sum of the same literal component/cleanup clocks; no clock is a runtime operand. -/\ndef budget (i:Inputs) (key:List Bool) (coordinate:Nat) (colours:List (List Bool)):Nat:=((Col.time coordinate colours))+((5*((Col.result coordinate colours).1).length+4))+((5*(i.group).length+4))+((SemiprimeD1StackWordEqualExecution.executionTime ((Col.result coordinate colours).1++[]) i.group+1))+(3)+((6*([(SemiprimeD1StackChildGroupFactoryActivationView.active i coordinate colours)]).length+5))+((6*(key).length+5))+(1)\n/-- Complete actual block; its trace and real returns come from the literal source. -/\ntheorem source_trace (i:Inputs) (todo key hist map:List Bool) (coordinate:Nat) (selected:List Bool) (colours:List (List Bool)):\n    ∃t≤budget i key coordinate colours,Runs program t (.local 0 28) (rowData i todo key hist map selected coordinate colours) (.local 1 17) (loggedData i todo key hist map selected coordinate colours):=by\n  let active:=decide (SemiprimeBitArithmetic.bitValue (Col.result coordinate colours).1=\n    SemiprimeBitArithmetic.bitValue i.group)\n  let b0:Stack→List Bool:=rowData i todo key hist map selected coordinate colours\n  let b1:Stack→List Bool:=Col.view b0 [] (Col.result coordinate colours).2 (Col.result coordinate colours).1\n  have h0view:Col.view b0 (List.replicate coordinate true) (vectorBits colours) []=b0:=by\n    have hc:b0 (aux .colourCursor)=List.replicate coordinate true:=(by simp [b0,aux,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n    have hr:b0 (aux .colourReader)=vectorBits colours:=(by simp [b0,aux,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n    have hw:b0 (aux .colourWord)=[]:=(by simp [b0,data,input,aux,withRows,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n    unfold Col.view\n    rw [←hc,Function.update_eq_self,←hr,Function.update_eq_self,←hw,Function.update_eq_self]\n  have h0:Runs program (Col.time coordinate colours) (.local 0 28) b0 (.local 1 6) b1:=by\n    have h:=Col.source_trace b0 coordinate colours (by simp [b0,data,input,aux,field,withRows,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,data,input,aux,field,withRows,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n    rw [h0view] at h\n    exact h\n  let b2:Stack→List Bool:=Function.update b1 (arithmetic .left) ((Col.result coordinate colours).1++[])\n  have h1:Runs program (5*((Col.result coordinate colours).1).length+4) (.local 1 6) b1 (.local 1 7) b2:=\n    copy_call 10 (.local 1 6) (.local 1 7) rfl b1 (Col.result coordinate colours).1 [] (by simp [b0,b1,aux,arithmetic,copyStack,copyPorts,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,data,input,aux,arithmetic,copyStack,copyPorts,withRows,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,data,input,aux,copyStack,withRows,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  let b3:Stack→List Bool:=Function.update b2 (arithmetic .right) (i.group++[])\n  have h2:Runs program (5*(i.group).length+4) (.local 1 7) b2 (.local 1 8) b3:=\n    copy_call 11 (.local 1 7) (.local 1 8) rfl b2 i.group [] (by simp [b0,b1,b2,data,input,aux,arithmetic,copyStack,copyPorts,withRows,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,b2,data,input,aux,arithmetic,copyStack,copyPorts,withRows,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,b2,data,input,aux,arithmetic,copyStack,withRows,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  let b4:Stack→List Bool:=withArithmetic b3 (SemiprimeD1StackAdder.store [] [] [] [decide (SemiprimeBitArithmetic.bitValue ((Col.result coordinate colours).1++[])=SemiprimeBitArithmetic.bitValue i.group)])\n  have h3:Runs program (SemiprimeD1StackWordEqualExecution.executionTime ((Col.result coordinate colours).1++[]) i.group+1) (.local 1 8) b3 (.local 1 9) b4:=\n    equal_call (.local 1 8) (.local 1 9) rfl b3 ((Col.result coordinate colours).1++[]) i.group (by intro k;cases k <;> simp [b0,b1,b2,b3,data,input,aux,arithmetic,withRows,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,SemiprimeD1StackAdder.store,selectedData,rowData])\n  let b5:Stack→List Bool:=Function.update (Function.update (Function.update b4 (arithmetic .output) []) (aux .flagScratch) [active]) (aux .activationHistory) (active::hist)\n  have h4f:b4 (arithmetic .output)=[active]:=by simp [b0,b1,b2,b3,b4,aux,arithmetic,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,SemiprimeD1StackAdder.store,selectedData,rowData,active]\n  have h4s:b4 (aux .flagScratch)=[]:=(by simp [b0,b1,b2,b3,b4,data,input,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  have h4h:b4 (aux .activationHistory)=hist:=(by simp [b0,b1,b2,b3,b4,data,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  have h4:Runs program 3 (.local 1 9) b4 (.local 1 14) b5:=by\n    simpa only [h4s,h4h] using flag_trace b4 active h4f\n  let b6:Stack→List Bool:=Function.update b5 (aux .activationMap) (frame [active] map)\n  have h5:Runs program (6*([active]).length+5) (.local 1 14) b5 (.local 1 15) b6:=\n    frame_call 1 (.local 1 14) (.local 1 15) rfl b5 [active] map (by simp [b0,b1,b2,b3,b4,b5,aux,arithmetic,frameStack,framePorts,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,b2,b3,b4,b5,data,aux,arithmetic,frameStack,framePorts,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,b2,b3,b4,b5,data,input,aux,arithmetic,frameStack,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  let b7:Stack→List Bool:=Function.update b6 (aux .activationMap) (frame key (frame [active] map))\n  have h6:Runs program (6*(key).length+5) (.local 1 15) b6 (.local 1 16) b7:=\n    frame_call 2 (.local 1 15) (.local 1 16) rfl b6 key (frame [active] map) (by simp [b0,b1,b2,b3,b4,b5,b6,data,aux,arithmetic,frameStack,framePorts,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,arithmetic,frameStack,framePorts,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData]) (by simp [b0,b1,b2,b3,b4,b5,b6,data,input,aux,arithmetic,frameStack,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  let b8:Stack→List Bool:=Function.update b7 (aux .activationMap) (true::(frame key (frame [active] map)))\n  have h7p:b7 (aux .activationMap)=(frame key (frame [active] map)):=(by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,arithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData])\n  have h7a:=push_run (.local 1 16) (.local 1 17) (aux .activationMap) true b7 rfl\n  have h7:Runs program 1 (.local 1 16) b7 (.local 1 17) b8:=by\n    simpa only [h7p] using h7a\n  have hfinal:b8=(loggedData i todo key hist map selected coordinate colours):=by\n    funext k\n    rcases k with k|k|k|k|k|k\n    · rcases k with k|k <;> cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,data,input,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n    · rcases k with k|k\n      · rcases k with k|k <;> cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackOwnerLookup.data,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,SemiprimeD1StackAdder.store,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n      · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n    · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,data,input,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,SemiprimeD1StackAdder.store,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n    · rcases k with k|k <;> cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,data,input,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n    · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,data,input,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n    · cases k <;> simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,data,input,aux,arithmetic,withRows,withArithmetic,Col.view,SemiprimeD1StackPacketRowsExecution.result,SemiprimeD1StackPacketRowsView.view,selectedData,rowData,loggedData,SemiprimeD1StackChildGroupFactoryActivationView.active,active]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (h7)))))))\n  rw [hfinal] at hwhole\n  refine ⟨_,?_,hwhole⟩\n  dsimp only [budget]\n  simp only [List.length_cons,List.length_nil]\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryActivationLog\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReuse":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryPrimitives\n/-! # Complete paid reuse boundary after every observed packet bucket\nAll three packet-local words and ALL twelve ordinal-converter tapes are\nphysically drained, including its retained binary bank and unary result.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReuse\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\n/-- Exact fifteen actual reusable role labels, fixed before every input. -/\ndef role:Fin 15→Stack\n  | 0=>aux .packetKey\n  | 1=>aux .jointKey\n  | 2=>aux .portBank\n  | 3=>ordinal .bank\n  | 4=>ordinal .reader\n  | 5=>ordinal .word\n  | 6=>ordinal .fieldScratch\n  | 7=>ordinal .valid\n  | 8=>ordinal .copyScratch\n  | 9=>ordinal .digits\n  | 10=>ordinal .unaryScratch\n  | 11=>ordinal .unary\n  | 12=>ordinal .logScratch\n  | 13=>ordinal .history\n  | 14=>ordinal .output\n/-- Every field and callee word is physically cleared. -/\ndef result (before:Stack→List Bool):Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (Function.update (before) (aux .packetKey) []) (aux .jointKey) []) (aux .portBank) []) (ordinal .bank) []) (ordinal .reader) []) (ordinal .word) []) (ordinal .fieldScratch) []) (ordinal .valid) []) (ordinal .copyScratch) []) (ordinal .digits) []) (ordinal .unaryScratch) []) (ordinal .unary) []) (ordinal .logScratch) []) (ordinal .history) []) (ordinal .output) []\n/-- Actual bytes erased and all fifteen actual EOF pops. -/\ndef timeBound (before:Stack→List Bool):Nat:=\n  (before (aux .packetKey)).length+(before (aux .jointKey)).length+(before (aux .portBank)).length+(before (ordinal .bank)).length+(before (ordinal .reader)).length+(before (ordinal .word)).length+(before (ordinal .fieldScratch)).length+(before (ordinal .valid)).length+(before (ordinal .copyScratch)).length+(before (ordinal .digits)).length+(before (ordinal .unaryScratch)).length+(before (ordinal .unary)).length+(before (ordinal .logScratch)).length+(before (ordinal .history)).length+(before (ordinal .output)).length+15\n/-- Complete real cleanup before the next actual observed packet is read. -/\ntheorem source_trace (before:Stack→List Bool):\n    Runs program (timeBound before) (.local 8 17) before (.local 6 18) (result before):=by\n  let b0:=before\n  let b1:Stack→List Bool:=Function.update b0 (aux .packetKey) []\n  have h0:Runs program ((before (aux .packetKey)).length+1) (.local 8 17) b0 (.local 8 18) b1:=\n    drain_loop (.local 8 17) (.local 8 18) (aux .packetKey) rfl b0 (before (aux .packetKey)) (by simp [b0,aux])\n  let b2:Stack→List Bool:=Function.update b1 (aux .jointKey) []\n  have h1:Runs program ((before (aux .jointKey)).length+1) (.local 8 18) b1 (.local 8 19) b2:=\n    drain_loop (.local 8 18) (.local 8 19) (aux .jointKey) rfl b1 (before (aux .jointKey)) (by simp [b0,b1,aux])\n  let b3:Stack→List Bool:=Function.update b2 (aux .portBank) []\n  have h2:Runs program ((before (aux .portBank)).length+1) (.local 8 19) b2 (.local 8 20) b3:=\n    drain_loop (.local 8 19) (.local 8 20) (aux .portBank) rfl b2 (before (aux .portBank)) (by simp [b0,b1,b2,aux])\n  let b4:Stack→List Bool:=Function.update b3 (ordinal .bank) []\n  have h3:Runs program ((before (ordinal .bank)).length+1) (.local 8 20) b3 (.local 8 21) b4:=\n    drain_loop (.local 8 20) (.local 8 21) (ordinal .bank) rfl b3 (before (ordinal .bank)) (by simp [b0,b1,b2,b3,aux,ordinal])\n  let b5:Stack→List Bool:=Function.update b4 (ordinal .reader) []\n  have h4:Runs program ((before (ordinal .reader)).length+1) (.local 8 21) b4 (.local 8 22) b5:=\n    drain_loop (.local 8 21) (.local 8 22) (ordinal .reader) rfl b4 (before (ordinal .reader)) (by simp [b0,b1,b2,b3,b4,aux,ordinal])\n  let b6:Stack→List Bool:=Function.update b5 (ordinal .word) []\n  have h5:Runs program ((before (ordinal .word)).length+1) (.local 8 22) b5 (.local 8 23) b6:=\n    drain_loop (.local 8 22) (.local 8 23) (ordinal .word) rfl b5 (before (ordinal .word)) (by simp [b0,b1,b2,b3,b4,b5,aux,ordinal])\n  let b7:Stack→List Bool:=Function.update b6 (ordinal .fieldScratch) []\n  have h6:Runs program ((before (ordinal .fieldScratch)).length+1) (.local 8 23) b6 (.local 8 24) b7:=\n    drain_loop (.local 8 23) (.local 8 24) (ordinal .fieldScratch) rfl b6 (before (ordinal .fieldScratch)) (by simp [b0,b1,b2,b3,b4,b5,b6,aux,ordinal])\n  let b8:Stack→List Bool:=Function.update b7 (ordinal .valid) []\n  have h7:Runs program ((before (ordinal .valid)).length+1) (.local 8 24) b7 (.local 8 25) b8:=\n    drain_loop (.local 8 24) (.local 8 25) (ordinal .valid) rfl b7 (before (ordinal .valid)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,aux,ordinal])\n  let b9:Stack→List Bool:=Function.update b8 (ordinal .copyScratch) []\n  have h8:Runs program ((before (ordinal .copyScratch)).length+1) (.local 8 25) b8 (.local 8 26) b9:=\n    drain_loop (.local 8 25) (.local 8 26) (ordinal .copyScratch) rfl b8 (before (ordinal .copyScratch)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,aux,ordinal])\n  let b10:Stack→List Bool:=Function.update b9 (ordinal .digits) []\n  have h9:Runs program ((before (ordinal .digits)).length+1) (.local 8 26) b9 (.local 8 27) b10:=\n    drain_loop (.local 8 26) (.local 8 27) (ordinal .digits) rfl b9 (before (ordinal .digits)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,aux,ordinal])\n  let b11:Stack→List Bool:=Function.update b10 (ordinal .unaryScratch) []\n  have h10:Runs program ((before (ordinal .unaryScratch)).length+1) (.local 8 27) b10 (.local 8 28) b11:=\n    drain_loop (.local 8 27) (.local 8 28) (ordinal .unaryScratch) rfl b10 (before (ordinal .unaryScratch)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,aux,ordinal])\n  let b12:Stack→List Bool:=Function.update b11 (ordinal .unary) []\n  have h11:Runs program ((before (ordinal .unary)).length+1) (.local 8 28) b11 (.local 8 29) b12:=\n    drain_loop (.local 8 28) (.local 8 29) (ordinal .unary) rfl b11 (before (ordinal .unary)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,aux,ordinal])\n  let b13:Stack→List Bool:=Function.update b12 (ordinal .logScratch) []\n  have h12:Runs program ((before (ordinal .logScratch)).length+1) (.local 8 29) b12 (.local 8 30) b13:=\n    drain_loop (.local 8 29) (.local 8 30) (ordinal .logScratch) rfl b12 (before (ordinal .logScratch)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,aux,ordinal])\n  let b14:Stack→List Bool:=Function.update b13 (ordinal .history) []\n  have h13:Runs program ((before (ordinal .history)).length+1) (.local 8 30) b13 (.local 8 31) b14:=\n    drain_loop (.local 8 30) (.local 8 31) (ordinal .history) rfl b13 (before (ordinal .history)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,aux,ordinal])\n  let b15:Stack→List Bool:=Function.update b14 (ordinal .output) []\n  have h14:Runs program ((before (ordinal .output)).length+1) (.local 8 31) b14 (.local 6 18) b15:=\n    drain_loop (.local 8 31) (.local 6 18) (ordinal .output) rfl b14 (before (ordinal .output)) (by simp [b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,aux,ordinal])\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 (join h5 (join h6 (join h7 (join h8 (join h9 (join h10 (join h11 (join h12 (join h13 (h14))))))))))))))\n  have ht:((before (aux .packetKey)).length+1)+((before (aux .jointKey)).length+1)+((before (aux .portBank)).length+1)+((before (ordinal .bank)).length+1)+((before (ordinal .reader)).length+1)+((before (ordinal .word)).length+1)+((before (ordinal .fieldScratch)).length+1)+((before (ordinal .valid)).length+1)+((before (ordinal .copyScratch)).length+1)+((before (ordinal .digits)).length+1)+((before (ordinal .unaryScratch)).length+1)+((before (ordinal .unary)).length+1)+((before (ordinal .logScratch)).length+1)+((before (ordinal .history)).length+1)+((before (ordinal .output)).length+1)=timeBound before:=by dsimp only [timeBound];omega\n  simpa only [←ht,Nat.add_assoc,result,b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15] using hwhole\n/-- Every reusable word is now really empty. -/\ntheorem result_role (before:Stack→List Bool) (i:Fin 15):result before (role i)=[]:=by fin_cases i <;> rfl\n/-- All caller words outside the fifteen actual drained tapes are retained. -/\ntheorem result_other (before:Stack→List Bool) (k:Stack) (h:∀i,role i≠k):result before k=before k:=by\n  have h0:=Ne.symm (h 0)\n  have h1:=Ne.symm (h 1)\n  have h2:=Ne.symm (h 2)\n  have h3:=Ne.symm (h 3)\n  have h4:=Ne.symm (h 4)\n  have h5:=Ne.symm (h 5)\n  have h6:=Ne.symm (h 6)\n  have h7:=Ne.symm (h 7)\n  have h8:=Ne.symm (h 8)\n  have h9:=Ne.symm (h 9)\n  have h10:=Ne.symm (h 10)\n  have h11:=Ne.symm (h 11)\n  have h12:=Ne.symm (h 12)\n  have h13:=Ne.symm (h 13)\n  have h14:=Ne.symm (h 14)\n  simp only [role] at h0 h1 h2 h3 h4 h5 h6 h7 h8 h9 h10 h11 h12 h13 h14\n  simp only [result,Function.update_of_ne h14,Function.update_of_ne h13,Function.update_of_ne h12,Function.update_of_ne h11,Function.update_of_ne h10,Function.update_of_ne h9,Function.update_of_ne h8,Function.update_of_ne h7,Function.update_of_ne h6,Function.update_of_ne h5,Function.update_of_ne h4,Function.update_of_ne h3,Function.update_of_ne h2,Function.update_of_ne h1,Function.update_of_ne h0]\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketReuse\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketScanView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketScan\n/-! # Actual ordered bucket vectors and preserved scan-boundary caches -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketScanView\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryBucketScan\nnamespace LV\nexport SemiprimeD1StackChildGroupFactoryBucketLoopView (result_other result_clean result_position finalPosition)\nend LV\n/-- The actual ordered endpoint-vector word, with its real FALSE terminator. -/\ntheorem result_children (before:Stack→List Bool) (es:List Parse.Endpoint) (packet position:List Bool):\n    result before es packet position (aux .jointKey)=View.records es packet position++[false]:=rfl\n/-- The actual binary fresh-ID word vector consumed by the real ordinal converter. -/\ntheorem result_ports (before:Stack→List Bool) (es:List Parse.Endpoint) (packet position:List Bool):\n    result before es packet position (aux .portBank)=SemiprimeD1TensorTapeCodec.vectorBits (View.portWords es packet position):=\n  port_records_vector _\n/-- Both actual reverse histories are physically empty. -/\ntheorem result_histories (before:Stack→List Bool) (es:List Parse.Endpoint) (packet position:List Bool):\n    result before es packet position (aux .bucketHistory)=[] ∧ result before es packet position (aux .portHistory)=[]:=⟨rfl,rfl⟩\n/-- Exact current fresh child-global binary counter, obtained from actual increments. -/\ntheorem result_position (before:Stack→List Bool) (es:List Parse.Endpoint) (packet position:List Bool)\n    (hp:before (aux .globalPosition)=position):\n    result before es packet position (aux .globalPosition)=LV.finalPosition es packet position:=by\n  change Loop.result es (copied before es) packet position (aux .globalPosition)=_\n  exact LV.result_position _ _ _ _ (by simpa [copied,aux] using hp)\n/-- Every other physical source word is retained across the actual scan and ordered reversals. -/\ntheorem result_other (before:Stack→List Bool) (es:List Parse.Endpoint) (packet position:List Bool) (k:Stack)\n    (hf:∀j,Cleanup.role j≠k) (hr:k≠aux .endpointReader) (hb:k≠aux .bucketHistory)\n    (hp:k≠aux .portHistory) (hg:k≠aux .globalPosition) (hj:k≠aux .jointKey) (hpb:k≠aux .portBank):\n    result before es packet position k=before k:=by\n  simp only [result,reversed,Function.update_of_ne hpb,Function.update_of_ne hp,\n    Function.update_of_ne hj,Function.update_of_ne hb]\n  rw [LV.result_other _ _ _ _ k hf hr hb hp hg]\n  exact Function.update_of_ne hr _ _\n/-- The actual parser and row-buffer roles are all fresh at the converter boundary. -/\ntheorem result_clean (before:Stack→List Bool) (es:List Parse.Endpoint) (packet position:List Bool)\n    (hz:∀k∈Parse.cleanRoles,before k=[]):\n    ∀k∈Parse.cleanRoles,result before es packet position k=[]:=by\n  have hc:∀k∈Parse.cleanRoles,copied before es k=[]:=by simpa [copied,Parse.cleanRoles,aux,field] using hz\n  have h:=LV.result_clean es (copied before es) packet position hc\n  intro k hk\n  simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n  all_goals\n    simpa [result,reversed,aux,field] using h _ (by simp [Parse.cleanRoles,aux,field])\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryBucketScanView\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCleanup\n/-! # Actual final exhaustive cleanup, success status and true halt\nThis source executes every real cleanup label before pushing success and\nhalting. Caller returns and all 115 physical words are accounted for.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryFinish\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace Clean\nexport SemiprimeD1StackChildGroupFactoryCleanup (result mass source_trace)\nend Clean\n/-- The success bit is physically pushed only after its old word was drained. -/\ndef result (before:Stack→List Bool):Stack→List Bool:=\n  Function.update (Clean.result false before) (aux .success) [true]\n/-- All actual jumps, all word drains, the literal push and final halt are paid. -/\ndef timeBound (before:Stack→List Bool):Nat:=115*(Clean.mass before+1)+3\n/-- Actual final source, for arbitrary real saved return frames and stale flags. -/\ntheorem source_run (before:Stack→List Bool):\n    ∃t≤timeBound before,∀frames (start:C.State Stack Label),\n      At (.local 15 13) before frames start→\n      C.run program t start=some (⟨none,none,none,result before,frames⟩:C.State Stack Label):=by\n  have h0:=jump_run (.local 15 13) (.clear false 0) before rfl\n  obtain ⟨x,hx,h1⟩:=Clean.source_trace false before\n  have h2:=push_run accept (.local 15 17) (aux .success) true (Clean.result false before) rfl\n  have he:(Clean.result false before) (aux .success)=[]:=rfl\n  rw [he] at h2\n  change Runs program 1 accept _ (.local 15 17) (result before) at h2\n  have hwhole:=join h0 (join h1 h2)\n  refine ⟨1+(x+1)+1,?_,?_⟩\n  · dsimp only [timeBound];omega\n  · intro frames start hs\n    obtain ⟨mid,hm,hat⟩:=hwhole frames start hs\n    have hh:=halt_run program (.local 15 17) rfl (result before) frames mid hat\n    rw [SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,hh]\n/-- Actual retained inputs and outputs survive the complete finishing source. -/\ntheorem result_retained (before:Stack→List Bool) (k:Stack)\n    (hk:retained false k=true) (hs:k≠aux .success):result before k=before k:=by\n  simp only [result,Function.update_of_ne hs,Clean.result,hk,ite_true]\n/-- Every unretained private word, including unused shadows, is empty at halt. -/\ntheorem result_private (before:Stack→List Bool) (k:Stack)\n    (hk:retained false k=false) (hs:k≠aux .success):result before k=[]:=by\n  simp only [result,Function.update_of_ne hs,Clean.result,hk,Bool.false_eq_true,ite_false]\n/-- Literal success flag at the actual stopped boundary. -/\ntheorem result_success (before:Stack→List Bool):result before (aux .success)=[true]:=Function.update_self _ _ _\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryFinish\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoopBounds\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryLeftPortsBounds\n/-! # Complete actual original-port order source cost\nThe whole original tape is copied and scanned, every needed first-index query\nruns, and real binary answers are reversed, converted to unary, logged and\nphysically cleared. The computed ordinal VALUE and all old records are paid.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsBounds\nopen SemiprimeD1StackChildGroupFactoryRoles\nnamespace S\nexport SemiprimeD1StackChildGroupFactoryOldPortsSource (copied prepared timeBound)\nend S\nnamespace Loop\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoop (Fresh freshRole orderWords)\nend Loop\nnamespace B\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket records)\nend B\nnamespace P\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point records)\nend P\nnamespace Bound\nexport SemiprimeD1StackChildGroupFactoryOldPortsLoopBounds (queryBudget timeBound_le)\nexport SemiprimeD1StackChildGroupFactoryOldPortOneBounds (pointBytes)\nend Bound\n/-- Complete SAME-source order acquisition bound from physical bank and actual occurrence counts. -/\ntheorem source_time (before:Stack→List Bool) (points:List P.Point) (buckets:List B.Bucket)\n    (target:List Bool) (cap H D:Nat) (hc:∀k,(before k).length≤cap)\n    (hf:Loop.Fresh before) (hp:(P.records points).length≤cap)\n    (hs:before (aux .buckets)=B.records buckets) (ht:before (aux .vertexKey)=target)\n    (ha:∀k,before (arithmetic k)=[]) (hbs:(B.records buckets).length≤H)\n    (hpoints:∀p∈points,Bound.pointBytes p≤H) (htarget:target.length≤H)\n    (hd:(buckets.flatMap (fun b=>b.children)).length≤D):\n    S.timeBound before points buckets target≤1000000000*\n      (cap+points.length*(4*D+2)+3*H+Bound.queryBudget H D buckets.length+D+1)*(points.length+1):=by\n  have hcopy:∀k,(S.copied before points k).length≤cap:=by\n    intro k\n    by_cases h:k=aux .oldReader\n    · subst k;exact hp\n    · simpa only [S.copied,Function.update_of_ne h] using hc k\n  have hf':Loop.Fresh (S.copied before points):=by\n    intro j\n    have h:Loop.freshRole j≠aux .oldReader:=by fin_cases j <;> decide\n    exact (Function.update_of_ne h _ _).trans (hf j)\n  have hloop:=Bound.timeBound_le points (S.copied before points) buckets target cap H D hcopy hf' hp\n    (by simpa [S.copied,aux] using hs) (by simpa [S.copied,aux] using ht)\n    (by intro k;simpa [S.copied,aux,arithmetic] using ha k) hbs hpoints htarget hd\n  have hcount:=SemiprimeD1StackChildGroupFactoryOrderBounds.order_count buckets points target\n  have hl:∀w∈Loop.orderWords buckets points target,w.length≤2*D:=by\n    intro w hw\n    have h:=(SemiprimeD1StackChildGroupFactoryOrderBounds.order_word_bounds buckets points target w hw).1\n    omega\n  have hv:∀w∈Loop.orderWords buckets points target,SemiprimeBitArithmetic.bitValue w≤2*D:=by\n    intro w hw\n    have h:=(SemiprimeD1StackChildGroupFactoryOrderBounds.order_word_bounds buckets points target w hw).2\n    omega\n  have hconv:=SemiprimeD1StackChildGroupFactoryPortConvertBounds.timeBound_le true\n    (S.prepared before points buckets target) (Loop.orderWords buckets points target) (2*D) rfl hl hv\n  have hbank:=SemiprimeD1StackPortOrdinalStreamBounds.bank_length (Loop.orderWords buckets points target) (2*D) hl\n  have hlog:=SemiprimeD1StackChildGroupFactoryLeftPortsBounds.port_log_length (Loop.orderWords buckets points target)\n  have hconv':SemiprimeD1StackChildGroupFactoryPortConvert.timeBound true\n      (S.prepared before points buckets target) (Loop.orderWords buckets points target)≤\n      10000*(points.length+1)*(2*D+1):=by\n    apply hconv.trans\n    exact Nat.mul_le_mul_right _ (Nat.mul_le_mul_left _ (by omega))\n  have hbank':(SemiprimeD1TensorTapeCodec.vectorBits (Loop.orderWords buckets points target)).length≤\n      points.length*(4*D+2)+1:=by nlinarith\n  let base:=cap+points.length*(4*D+2)+3*H+Bound.queryBudget H D buckets.length+D+1\n  let Q:=base*(points.length+1)\n  have hbase:1≤base:=by dsimp only [base];omega\n  have hQ:base≤Q:=Nat.le_mul_of_pos_right _ (by omega)\n  have hpQ:cap≤Q:= (by dsimp only [base];omega:cap≤base).trans hQ\n  have hbankQ:points.length*(4*D+2)+1≤Q:=(by dsimp only [base];omega:points.length*(4*D+2)+1≤base).trans hQ\n  have hconvQ:SemiprimeD1StackChildGroupFactoryPortConvert.timeBound true\n      (S.prepared before points buckets target) (Loop.orderWords buckets points target)≤20000*Q:=by\n    apply hconv'.trans\n    have hD:2*D+1≤2*base:=by dsimp only [base];omega\n    have h:=Nat.mul_le_mul_left (10000*(points.length+1)) hD\n    have he:10000*(points.length+1)*(2*base)=20000*Q:=by dsimp only [Q];ring\n    rw [he] at h\n    exact h\n  have hloopQ:SemiprimeD1StackChildGroupFactoryOldPortsLoop.timeBound points (S.copied before points) buckets target≤10000000*Q:=by\n    have he:10000000*base*(points.length+1)=10000000*Q:=by dsimp only [Q];ring\n    simpa only [←he] using hloop\n  dsimp only [S.timeBound]\n  have he:1000000000*(cap+points.length*(4*D+2)+3*H+Bound.queryBudget H D buckets.length+D+1)*\n      (points.length+1)=1000000000*Q:=by dsimp only [Q,base];ring\n  rw [he]\n  omega\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsBounds\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortOneView\n/-! # Entire actual original-port ordering loop for one old vertex\nTwenty fixed physical fresh roles are proved restored after EVERY whole query.\nEvery real old record is parsed; matching vertices execute the full nested\nfirst-index source and retain original old-port order and multiplicities.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoop\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackProcedureTrace\nnamespace One\nexport SemiprimeD1StackChildGroupFactoryOldPortOne (result timeBound source_trace)\nend One\nnamespace OV\nexport SemiprimeD1StackChildGroupFactoryOldPortOneView\n  (result_other result_oldReader result_work result_answer result_local result_tag answerWord result_orderHistory)\nend OV\nnamespace Parse\nexport SemiprimeD1StackChildGroupFactoryOldPortParse (Point records cleanRoles)\nend Parse\nnamespace Header\nexport SemiprimeD1StackChildGroupFactoryBucketHeader (cleanRoles)\nend Header\nnamespace Child\nexport SemiprimeD1StackChildGroupFactoryChildParse (cleanRoles)\nend Child\nnamespace Buckets\nexport SemiprimeD1StackChildGroupFactoryLeftPortsLoop (Bucket records)\nend Buckets\nnamespace Early\nexport SemiprimeD1StackChildGroupFactoryTagEarlyClear (role)\nend Early\nnamespace Log\nexport SemiprimeD1StackChildGroupFactoryWordLog (row)\nend Log\nopen SemiprimeBitArithmetic (bitValue)\n/-- The twenty actual original-query work/parser/buffer roles; fixed before all input bytes. -/\ndef freshRole:Fin 20→Stack\n  | 0=>aux .outerReader\n  | 1=>aux .childReader\n  | 2=>aux .endpointReader\n  | 3=>aux .rowBuffer\n  | 4=>aux .ownerKey\n  | 5=>aux .sourceKey\n  | 6=>aux .slotWord\n  | 7=>aux .edgeWord\n  | 8=>aux .sideWord\n  | 9=>aux .globalPosition\n  | 10=>aux .candidateTag\n  | 11=>aux .answerPosition\n  | 12=>aux .localPosition\n  | 13=>aux .tagWord\n  | 14=>aux .packetKey\n  | 15=>aux .paddingKey\n  | 16=>field (.inl .scratch)\n  | 17=>field (.inr ())\n  | 18=>aux .frameBuffer\n  | 19=>aux .copyScratch\n  | _=>aux .copyScratch\n/-- Real data-only freshness, not a runtime flag or an answer promise. -/\ndef Fresh (before:Stack→List Bool):Prop:=∀j,before (freshRole j)=[]\n/-- Actual oldFresh destinations are among the same twenty physical fresh roles. -/\ntheorem oldFresh (before:Stack→List Bool) (hf:Fresh before):∀k∈Parse.cleanRoles,before k=[]:=by\n  intro k hk\n  simp only [Parse.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl\n  · exact hf 4\n  · exact hf 7\n  · exact hf 8\n  · exact hf 3\n  · exact hf 16\n  · exact hf 17\n/-- Actual headerFresh destinations are among the same twenty physical fresh roles. -/\ntheorem headerFresh (before:Stack→List Bool) (hf:Fresh before):∀k∈Header.cleanRoles,before k=[]:=by\n  intro k hk\n  simp only [Header.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl\n  · exact hf 1\n  · exact hf 14\n  · exact hf 2\n  · exact hf 15\n  · exact hf 16\n  · exact hf 17\n/-- Actual childFresh destinations are among the same twenty physical fresh roles. -/\ntheorem childFresh (before:Stack→List Bool) (hf:Fresh before):∀k∈Child.cleanRoles,before k=[]:=by\n  intro k hk\n  simp only [Child.cleanRoles,List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl|rfl\n  · exact hf 4\n  · exact hf 5\n  · exact hf 6\n  · exact hf 7\n  · exact hf 8\n  · exact hf 9\n  · exact hf 3\n  · exact hf 16\n  · exact hf 17\n/-- Every complete actual original-port iteration restores the entire real fresh bank. -/\ntheorem fresh_step (before:Stack→List Bool) (buckets:List Buckets.Bucket) (p:Parse.Point) (tail target:List Bool)\n    (hf:Fresh before):Fresh (One.result before buckets p tail target):=by\n  have hw:=OV.result_work before buckets p tail target (headerFresh before hf) (childFresh before hf) (hf 0) (hf 10)\n  intro j\n  fin_cases j\n  · exact hw 0\n  · exact hw 1\n  · exact hw 2\n  · exact hw 3\n  · exact hw 4\n  · exact hw 5\n  · exact hw 6\n  · exact hw 7\n  · exact hw 8\n  · exact hw 9\n  · exact hw 10\n  · exact OV.result_answer _ _ _ _ _ (hf 11)\n  · exact OV.result_local _ _ _ _ _ (hf 12)\n  · exact OV.result_tag _ _ _ _ _ (hf 13)\n  · exact (OV.result_other _ _ _ _ _ (freshRole 14) (by intro k;fin_cases k <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)).trans (hf 14)\n  · exact (OV.result_other _ _ _ _ _ (freshRole 15) (by intro k;fin_cases k <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)).trans (hf 15)\n  · exact (OV.result_other _ _ _ _ _ (freshRole 16) (by intro k;fin_cases k <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)).trans (hf 16)\n  · exact (OV.result_other _ _ _ _ _ (freshRole 17) (by intro k;fin_cases k <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)).trans (hf 17)\n  · exact (OV.result_other _ _ _ _ _ (freshRole 18) (by intro k;fin_cases k <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)).trans (hf 18)\n  · exact (OV.result_other _ _ _ _ _ (freshRole 19) (by intro k;fin_cases k <;> decide)\n      (by decide) (by decide) (by decide) (by decide) (by decide)).trans (hf 19)\n/-- Exact actual binary answer words in original old-port order. -/\ndef orderWords (buckets:List Buckets.Bucket):List Parse.Point→List Bool→List (List Bool)\n  | [],_=>[]\n  | p::ps,target=>if bitValue p.vertex=bitValue target then OV.answerWord buckets p target::orderWords buckets ps target\n    else orderWords buckets ps target\n/-- Actual EOF leaves the original-port reader physically empty. -/\ndef atEOF (before:Stack→List Bool):Stack→List Bool:=Function.update before (aux .oldReader) []\n/-- Full actual original-port loop bank. -/\ndef result:List Parse.Point→(Stack→List Bool)→List Buckets.Bucket→List Bool→Stack→List Bool\n  | [],before,_,_=>atEOF before\n  | p::ps,before,buckets,target=>result ps (One.result before buckets p (Parse.records ps) target) buckets target\n/-- Own complete actual query clocks and final real EOF pair. -/\ndef timeBound:List Parse.Point→(Stack→List Bool)→List Buckets.Bucket→List Bool→Nat\n  | [],_,_,_=>2\n  | p::ps,before,buckets,target=>One.timeBound before buckets p (Parse.records ps) target+\n      timeBound ps (One.result before buckets p (Parse.records ps) target) buckets target\n/-- Exact original-port EOF instructions, including a real empty-suffix test. -/\ntheorem eof_trace (before:Stack→List Bool) (hr:before (aux .oldReader)=[false]):\n    Runs program 2 (.local 11 7) before (.local 14 9) (atEOF before):=by\n  have h0:=pop_run (.local 11 7) abort (.local 11 8) (.local 11 9) (aux .oldReader) before [false] rfl hr\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h0\n  have h1:=peek_run (.local 11 8) (.local 14 9) abort abort (aux .oldReader) (atEOF before) [] rfl (Function.update_self _ _ _)\n  simp only [List.head?_nil,SemiprimeD1StackBytecode.choose] at h1\n  exact join h0 h1\n/-- Entire actual old-port loop, executing each needed real query rather than an idxOf/getter opcode. -/\ntheorem source_trace (points:List Parse.Point) (before:Stack→List Bool) (buckets:List Buckets.Bucket) (target:List Bool)\n    (hi:before (aux .oldReader)=Parse.records points) (hs:before (aux .buckets)=Buckets.records buckets)\n    (ht:before (aux .vertexKey)=target) (hf:Fresh before) (ha:∀k,before (arithmetic k)=[]):\n    Runs program (timeBound points before buckets target) (.local 11 7) before (.local 14 9)\n      (result points before buckets target):=by\n  induction points generalizing before with\n  | nil=>exact eof_trace before hi\n  | cons p ps ih=>\n    have h0:=One.source_trace before buckets p (Parse.records ps) target hi (oldFresh before hf) hs (hf 0)\n      (headerFresh before hf) (childFresh before hf) ht (hf 13) (hf 12) (hf 10) (hf 11) (hf 18) (hf 19)\n      ha\n    let after:=One.result before buckets p (Parse.records ps) target\n    have hi':after (aux .oldReader)=Parse.records ps:=OV.result_oldReader _ _ _ _ _\n    have hs':after (aux .buckets)=Buckets.records buckets:=\n      (OV.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide)\n        (by decide) (by decide) (by decide)).trans hs\n    have ht':after (aux .vertexKey)=target:=\n      (OV.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> decide) (by decide) (by decide)\n        (by decide) (by decide) (by decide)).trans ht\n    have ha':∀k,after (arithmetic k)=[]:=by\n      intro k\n      exact (OV.result_other _ _ _ _ _ _ (by intro j;fin_cases j <;> simp [Early.role,arithmetic,aux])\n        (by simp [arithmetic,aux]) (by simp [arithmetic,aux]) (by simp [arithmetic,aux])\n        (by simp [arithmetic,aux]) (by simp [arithmetic,aux])).trans (ha k)\n    exact join h0 (ih after hi' hs' ht' (fresh_step _ _ _ _ _ hf) ha')\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOldPortsLoop\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryNativeStreams\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryPackedRootInputs\n/-! # Whole actual retained child-factory source with exact original ordered streams\nThe literal258-role ready program consumes only already acquired physical cache\nwords and six headers. Every original activation bit and exact native unary\nscope/order row is produced in ALL original owner-first vertex order. The SAME\nsource clock covers every call, generated ordinal, frame, drain and real return.\nThis boundary supplies metadata; child table production, context installation,\nrecursive child production and the literal enclosing N-only caller stay open.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryOriginal\nopen SemiprimeBitArithmetic (bitValue)\nnamespace R\nexport SemiprimeD1StackChildGroupFactoryReady (Stack Header factory initial sourceInputs program)\nend R\nnamespace Res\nexport SemiprimeD1StackChildGroupFactoryReadyResources (source_run runBound size)\nend Res\nnamespace Meaning\nexport SemiprimeD1StackChildGroupFactoryNativeInputs (CacheMeaning valid_original count_original)\nend Meaning\nnamespace Root\nexport SemiprimeD1StackChildGroupFactoryPackedRootInputs (selectorWords occurrenceWords inventoryWords cache_original)\nend Root\nnamespace N\nexport SemiprimeD1TensorNetwork (Network arity owner)\nend N\nnamespace A\nexport SemiprimeD1StackChildGroupFactoryNativeActivation (originalIDs result_original)\nend A\nnamespace Fld\nexport SemiprimeD1StackChildGroupFactoryNativeFields (source fields)\nend Fld\nnamespace Streams\nexport SemiprimeD1StackChildGroupFactoryNativeStreams (scopeAt orderAt result_scopes result_orders)\nend Streams\nnamespace C\nexport SemiprimeD1StackCalls (State run)\nend C\nnamespace W\nexport SemiprimeD1StackChildGroupFactoryWiring (Label)\nend W\nnamespace G\nexport SemiprimeD1StackChildGroupFactoryRoles (aux)\nend G\n/-- Exact native mask and both COMPLETE ordered scope/order streams at the real same-program halt. -/\ntheorem source_run_original (net:N.Network) (a:Nat)\n    (s:SemiprimeD1StackChildGroupFactoryReady.S.Stack→List Bool)\n    (p:SemiprimeD1StackChildGroupFactoryReady.P.Stack→List Bool)\n    (iv:SemiprimeD1StackChildGroupFactoryReady.I.Stack→List Bool) (header:R.Header)\n    (hc:Meaning.CacheMeaning net a s p iv) (q:Fin a) (g:Fin 64)\n    (hq:header.colourIndex=List.replicate q.val true) (hg:bitValue header.group=g.val):\n    ∃t≤Res.runBound s p iv header,∃finish:C.State R.Stack W.Label,\n      C.run R.program t (R.initial s p iv header)=some finish ∧\n      finish.pc=none ∧ finish.flag=none ∧ finish.returned=none ∧ finish.frames=[] ∧\n      finish.data (R.factory (G.aux .activation))=\n        (SemiprimeD1ChildActivation.acquire net.leftCount net.rows.length 64 a (N.arity net.rows) (N.owner net.rows) q g).bits ∧\n      finish.data (R.factory (G.aux .leftPorts))=SemiprimeD1TensorTapeCodec.vectorBits\n        ((List.finRange (net.leftCount+net.rows.length)).map\n          (Streams.scopeAt net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows) q g)) ∧\n      finish.data (R.factory (G.aux .orders))=SemiprimeD1TensorTapeCodec.vectorBits\n        ((List.finRange (net.leftCount+net.rows.length)).map\n          (Streams.orderAt net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows) q g)) ∧\n      (∀k,SemiprimeD1StackChildGroupFactoryReadyRetention.producer k=true→\n        finish.data k=(R.initial s p iv header).data k) ∧\n      (∀j:Fin 7,finish.data (SemiprimeD1StackChildGroupFactoryReady.allocation\n        (G.aux (SemiprimeD1StackChildGroupFactoryReadyRetention.shadow j)))=[]):=by\n  let input:=R.sourceInputs s p iv header\n  have hv:=Meaning.valid_original net a s p iv header q hc hq\n  have hcount:=Meaning.count_original net a s p iv header hc\n  have hgroup:bitValue input.group=g.val:=hg\n  obtain ⟨t,ht,finish,hr,hrel⟩:=Res.source_run s p iv header a q.val\n    (A.originalIDs net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows))\n    (Fld.source net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows)).state.packets\n    (Fld.fields net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows)) hv\n  have hstop:=SemiprimeD1StackChildGroupFactoryReadyExecution.stopped hrel\n  refine ⟨t,ht,finish,hr,hstop.1,hstop.2.1,hstop.2.2.1,hstop.2.2.2,?_,?_,?_,?_,?_⟩\n  · rw [hrel.1.1]\n    exact A.result_original input net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows) q g _ _ hgroup\n  · rw [hrel.1.1]\n    exact Streams.result_scopes input net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows) q g hgroup hcount\n  · rw [hrel.1.1]\n    exact Streams.result_orders input net.leftCount net.rows.length a (N.arity net.rows) (N.owner net.rows) q g hgroup hcount\n  · intro k hk\n    exact SemiprimeD1StackChildGroupFactoryReadyRetention.producer_retained s p iv header a q.val _ _ _ finish hrel k hk\n  · intro j\n    exact SemiprimeD1StackChildGroupFactoryReadyRetention.shadow_empty s p iv header a q.val _ _ _ finish hrel j\n/-- The actual original-N reached root cache discharges ALL structural handoff obligations internally.\nThe displayed run begins at the honest ready cache, not an unimplemented enclosing N-only call. -/\ntheorem packed_root_source (bits:List Bool) (hN:0<bitValue bits) (header:R.Header)\n    (q:Fin (SemiprimeD1StackRootSelectionAcquireEncoding.dimension bits)) (g:Fin 64)\n    (hq:header.colourIndex=List.replicate q.val true) (hg:bitValue header.group=g.val):\n    ∃t≤Res.runBound (Root.selectorWords bits hN) (Root.occurrenceWords bits hN) (Root.inventoryWords bits hN) header,\n      ∃finish:C.State R.Stack W.Label,\n      C.run R.program t (R.initial (Root.selectorWords bits hN) (Root.occurrenceWords bits hN) (Root.inventoryWords bits hN) header)=\n        some finish ∧ finish.pc=none ∧ finish.frames=[]:=by\n  obtain ⟨t,ht,finish,hr,hpc,_,_,hframes,_⟩:=source_run_original\n    (SemiprimeD1StackMarkedRootRecordsNetwork.network (bitValue bits) hN)\n    (SemiprimeD1StackRootSelectionAcquireEncoding.dimension bits)\n    (Root.selectorWords bits hN) (Root.occurrenceWords bits hN) (Root.inventoryWords bits hN) header\n    (Root.cache_original bits hN) q g hq hg\n  exact ⟨t,ht,finish,hr,hpc,hframes⟩\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryOriginal\n","RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexIncrement":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildGroupFactoryCalls\n/-! # Real complete old-vertex binary successor\nThe actual old-vertex key starts at zero after its earlier real erasure and\nadvances once for every physically consumed owner/factor marker, including\nisolated vertices. Neither original N nor a coefficient becomes unary.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexIncrement\nopen SemiprimeD1StackChildGroupFactoryRoles SemiprimeD1StackChildGroupFactoryWiring\nopen SemiprimeD1StackChildGroupFactory SemiprimeD1StackChildGroupFactoryPrimitives\nopen SemiprimeD1StackChildGroupFactoryCalls SemiprimeD1StackProcedureTrace\n/-- Actual full binary add-one result. -/\ndef successor (position:List Bool):List Bool:=(SemiprimeBitArithmetic.addBits position [true] false).bits\n/-- All copies, actual adder, old-counter erase, result copy and result erase. -/\ndef timeBound (position:List Bool):Nat:=\n  (5*position.length+4)+1+(3*(max position.length 1+1)+2*(successor position).length+3)+\n    (position.length+1)+(5*(successor position).length+4)+((successor position).length+1)\n/-- Complete actual increment with all four arithmetic tapes restored to empty. -/\ntheorem source_trace (before:Stack→List Bool) (position:List Bool)\n    (hp:before (aux .vertexKey)=position) (hc:before (aux .copyScratch)=[])\n    (ha:∀k,before (arithmetic k)=[]):\n    Runs program (timeBound position) (.local 14 29) before (.local 9 4)\n      (Function.update before (aux .vertexKey) (successor position)):=by\n  simp only [aux] at hp hc\n  have hal:=ha .left\n  have har:=ha .right\n  have has:=ha .scratch\n  have hao:=ha .output\n  simp only [arithmetic] at hal har has hao\n  let b1:=Function.update before (arithmetic .left) position\n  have h0:=copy_call 12 (.local 14 29) (.local 14 30) rfl before position []\n    (by simpa [copyStack,copyPorts,aux] using hp)\n    (by simpa [copyStack,copyPorts,arithmetic] using hal) (by simpa [copyStack,aux] using hc)\n  simp only [List.append_nil] at h0\n  change Runs program _ _ before _ b1 at h0\n  let b2:=Function.update b1 (arithmetic .right) [true]\n  have h1a:=push_run (.local 14 30) (.local 14 31) (arithmetic .right) true b1 rfl\n  have hr:b1 (arithmetic .right)=[]:=by simp [b1,arithmetic,har]\n  have h1:Runs program 1 (.local 14 30) b1 (.local 14 31) b2:=by simpa only [hr] using h1a\n  let b3:=withArithmetic b2 (SemiprimeD1StackAdder.store [] [] [] (successor position))\n  have h2:=add_call (.local 14 31) (.local 15 0) rfl b2 position [true]\n    (by intro k;cases k <;> simp [b2,b1,arithmetic,SemiprimeD1StackAdder.store,has,hao])\n  change Runs program _ _ b2 _ b3 at h2\n  let b4:=Function.update b3 (aux .vertexKey) []\n  have h3:=drain_loop (.local 15 0) (.local 15 1) (aux .vertexKey) rfl b3 position\n    (by simpa [b3,b2,b1,withArithmetic,aux,arithmetic] using hp)\n  change Runs program _ _ b3 _ b4 at h3\n  let b5:=Function.update b4 (aux .vertexKey) (successor position)\n  have h4:=copy_call 13 (.local 15 1) (.local 15 2) rfl b4 (successor position) []\n    (by simp [b4,b3,withArithmetic,copyStack,copyPorts,aux,arithmetic,SemiprimeD1StackAdder.store])\n    (by simp [b4,copyStack,copyPorts])\n    (by simpa [b4,b3,b2,b1,withArithmetic,copyStack,aux,arithmetic] using hc)\n  simp only [List.append_nil] at h4\n  change Runs program _ _ b4 _ b5 at h4\n  let b6:=Function.update b5 (arithmetic .output) []\n  have h5:=drain_loop (.local 15 2) (.local 9 4) (arithmetic .output) rfl b5 (successor position)\n    (by simp [b5,b4,b3,withArithmetic,aux,arithmetic,SemiprimeD1StackAdder.store])\n  change Runs program _ _ b5 _ b6 at h5\n  have hout:b6=Function.update before (aux .vertexKey) (successor position):=by\n    funext k\n    rcases k with k|k|k|k|k|k\n    · rfl\n    · rfl\n    · cases k <;> simp [b6,b5,b4,b3,withArithmetic,aux,arithmetic,SemiprimeD1StackAdder.store,hal,har,has,hao]\n    · rfl\n    · rfl\n    · cases k <;> simp [b6,b5,b4,b3,b2,b1,withArithmetic,aux,arithmetic]\n  have hwhole:=join h0 (join h1 (join h2 (join h3 (join h4 h5))))\n  rw [hout] at hwhole\n  simpa only [timeBound,successor,List.length_cons,List.length_nil,Nat.add_assoc] using hwhole\nend RiemannGaussian.SemiprimeD1StackChildGroupFactoryVertexIncrement\n","RiemannGaussian.SemiprimeD1StackChildTableEntryOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackChildTableEntryStorage\n/-! # Exact original individual parent-entry integer lift\nThis is one prepared entry source. Acquiring the actual unary port order,\nalignment, activation/unit, entire table DFS and canonical recopy remains in\nthe caller/next factory stages; none is pretended to execute here.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackChildTableEntryOriginal\nopen SemiprimeD1StackChildTableEntry SemiprimeD1StackChildTableEntryEncoding\nopen SemiprimeD1StackChildTableEntryPrepare SemiprimeD1StackChildTableEntryExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Every original entry's output is a physical vector of individually lifted coefficients. -/\ntheorem output_bytes (oldAxes newAxes:List Nat) (oldp newp table order assignment:List Bool) (ws:List (List Bool)):\n    (done oldAxes newAxes oldp newp table order assignment ws).data (aux .output)=\n      vectorBits (lifted newp ws (newAxes.prod-oldAxes.prod)):=rfl\n/-- All15 words of EACH actually acquired context bank remain unchanged after the complete ready/whole source. -/\ntheorem contexts_preserved (oldAxes newAxes:List Nat) (oldp newp table order assignment:List Bool)\n    (ws:List (List Bool)) (b:Bool) (k:J.Stack):\n    (done oldAxes newAxes oldp newp table order assignment ws).data (context b k)=\n      (if b then Context.finalData newAxes newp else Context.finalData oldAxes oldp) k:=by cases b <;> rfl\n/-- Actual paid parent-entry vector is retained, rather than supplied to the front door. -/\ntheorem parentEntry_bytes (oldAxes newAxes:List Nat) (oldp newp table order assignment:List Bool) (ws:List (List Bool)):\n    (done oldAxes newAxes oldp newp table order assignment ws).data (aux .parentEntry)=vectorBits ws:=rfl\n/-- Allocated tree-path shadow is physically empty; actual lookup path was directly aliased to gather output. -/\ntheorem path_shadow (oldAxes newAxes:List Nat) (oldp newp table order assignment:List Bool) (ws:List (List Bool)):\n    (done oldAxes newAxes oldp newp table order assignment ws).data (treeAllocation .path)=[]:=rfl\n/-- Positive extra-axis product gives each actual appended dimension positive size. -/\ntheorem extra_positive (extra:List Nat) (he:0<extra.prod):∀q∈extra,0<q:=by\n  induction extra with\n  | nil=>intro q hq;cases hq\n  | cons a rest ih=>\n    have hprod:0<a*rest.prod:=he\n    have ha:0<a:=by\n      by_contra h\n      have hz:a=0:=by omega\n      rw [hz,Nat.zero_mul] at hprod\n      omega\n    have ht:0<rest.prod:=by\n      by_contra h\n      have hz:rest.prod=0:=by omega\n      rw [hz,Nat.mul_zero] at hprod\n      omega\n    intro q hq\n    rcases List.mem_cons.mp hq with hq|hq\n    · subst q;exact ha\n    · exact ih ht q hq\n/-- Exact individual integer lift after the REAL cached-order gather and REAL sequential parent table read, with old/new precision kept distinct. -/\ntheorem entry_words {d:Nat} (old:SemiprimeD1JetAxes.Context) (extra:List Nat) (he:0<extra.prod)\n    (newp:List Bool) (table:SemiprimeD1TensorTables.Table d) (order:List Nat) (assignment:List Bool):\n    lifted newp (selected table assignment order) ((extra++old.axes).prod-old.axes.prod)=\n      (SemiprimeD1ChildTableCopyTape.entry old extra (bitValue newp) table order assignment).words:=by\n  rw [SemiprimeD1ChildTableCopyTape.entry_words]\n  change _=(SemiprimeD1ChildTableCopy.lift old extra (bitValue newp)\n    (SemiprimeD1TensorTables.lookup table (SemiprimeD1ChildTableCopy.gather assignment order).value).words).words\n  rw [←gathered_original]\n  exact lifted_original old extra newp (selected table assignment order) he\n/-- Intrinsic canonical parent-table shape discharges the physical old-rank count internally. No rank or coefficient-count answer is an input. -/\ntheorem selected_shape {d:Nat} (old:SemiprimeD1JetAxes.Context) (table:SemiprimeD1TensorTables.Table d)\n    (hg:SemiprimeD1TensorTables.Good old table) (order:List Nat) (assignment:List Bool):\n    (selected table assignment order).length=old.axes.prod:=\n  (SemiprimeD1TensorTables.lookup_good old table hg (gathered assignment order)).1\n/-- Literal appended positive-axis header proves the relation between the two ACTUALLY acquired ranks. -/\ntheorem rank_mono (old extra:List Nat) (he:0<extra.prod):old.prod  ≤  (extra++old).prod:=by\n  rw [List.prod_append]\n  have h:=Nat.mul_le_mul_right old.prod (show 1  ≤  extra.prod by omega)\n  simpa only [Nat.one_mul] using h\n/-- Whole actual seven-input original-family entry: no given rank/q/product, no aggregate lift, no old/new-precision equality assumption. -/\ntheorem source_run_original {d:Nat} (old:SemiprimeD1JetAxes.Context) (ho:∀q∈old.axes,0<q)\n    (extra:List Nat) (he:0<extra.prod) (oldp newp:List Bool) (hp:bitValue oldp=old.precision)\n    (table:SemiprimeD1TensorTables.Table d) (hg:SemiprimeD1TensorTables.Good old table)\n    (order:List Nat) (assignment:List Bool):\n    ∃t   ≤   wholeBound old.axes (extra++old.axes) oldp newp table order assignment,\n      SemiprimeD1StackCalls.run program t (initial (tape table) (orderTape order) assignment\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp)=\n        some (done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment (selected table assignment order)) ∧\n      (done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment (selected table assignment order)).data (aux .output)=\n        vectorBits (SemiprimeD1ChildTableCopyTape.entry old extra (bitValue newp) table order assignment).words ∧\n      ((done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment\n        (selected table assignment order)).data (context false J.widthCache)).length=old.precision:=by\n  have hn:∀q∈extra++old.axes,0<q:=by\n    intro q hq\n    rcases List.mem_append.mp hq with hq|hq\n    · exact extra_positive extra he q hq\n    · exact ho q hq\n  obtain ⟨t,ht,hr⟩:=source_run old.axes (extra++old.axes) ho hn oldp newp table order assignment\n    (selected_shape old table hg order assignment) (rank_mono old.axes extra he)\n  refine ⟨t,ht,hr,?_,?_⟩\n  · rw [output_bytes,entry_words old extra he]\n  · rw [contexts_preserved]\n    exact (SemiprimeD1StackJetContextCorrectness.width_value old.axes oldp).trans hp\n/-- Both literal positive-header sources are derived from original old/extra axis lineage. -/\ntheorem appended_positive (old extra:List Nat) (ho:∀q∈old,0<q) (he:0<extra.prod):∀q∈extra++old,0<q:=by\n  intro q hq\n  rcases List.mem_append.mp hq with hq|hq\n  · exact extra_positive extra he q hq\n  · exact ho q hq\n/-- Complete original whole entry with its OWN fixed quadratic clock in actual input bytes and acquired rank/precision VALUES. -/\ntheorem source_run_original_bounded {d:Nat} (old:SemiprimeD1JetAxes.Context) (ho:∀q∈old.axes,0<q)\n    (extra:List Nat) (he:0<extra.prod) (oldp newp:List Bool) (hp:bitValue oldp=old.precision)\n    (table:SemiprimeD1TensorTables.Table d) (hg:SemiprimeD1TensorTables.Good old table)\n    (order:List Nat) (assignment:List Bool):\n    ∃t  ≤  SemiprimeD1StackChildTableEntryClock.wholePolynomial old.axes (extra++old.axes) oldp newp table order assignment,\n      SemiprimeD1StackCalls.run program t (initial (tape table) (orderTape order) assignment\n        (vectorBits (old.axes.map unary)) oldp (vectorBits ((extra++old.axes).map unary)) newp)=\n        some (done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment (selected table assignment order)) ∧\n      (done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment (selected table assignment order)).data (aux .output)=\n        vectorBits (SemiprimeD1ChildTableCopyTape.entry old extra (bitValue newp) table order assignment).words ∧\n      ((done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment\n        (selected table assignment order)).data (context false J.widthCache)).length=old.precision:=by\n  obtain ⟨t,ht,hr,hout,hwidth⟩:=source_run_original old ho extra he oldp newp hp table hg order assignment\n  have hb:=SemiprimeD1StackChildTableEntryBounds.wholeBound_le old.axes (extra++old.axes) ho\n    (appended_positive old.axes extra ho he) oldp newp table order assignment\n    (selected_shape old table hg order assignment) (rank_mono old.axes extra he)\n  exact ⟨t,ht.trans hb,hr,hout,hwidth⟩\n/-- The SAME ready entry reuses actual old/new context caches and returns the exact original INDIVIDUAL integer lift with its own fixed quadratic. -/\ntheorem ready_run_original_bounded {d:Nat} (old:SemiprimeD1JetAxes.Context) (ho:∀q∈old.axes,0<q)\n    (extra:List Nat) (he:0<extra.prod) (oldp newp:List Bool)\n    (table:SemiprimeD1TensorTables.Table d) (hg:SemiprimeD1TensorTables.Good old table)\n    (order:List Nat) (assignment:List Bool):\n    ∃t  ≤  SemiprimeD1StackChildTableEntryClock.readyPolynomial old.axes (extra++old.axes) oldp newp table order assignment,\n      SemiprimeD1StackCalls.run program t (ready old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment)=\n        some (done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment (selected table assignment order)) ∧\n      (done old.axes (extra++old.axes) oldp newp (tape table) (orderTape order) assignment (selected table assignment order)).data (aux .output)=\n        vectorBits (SemiprimeD1ChildTableCopyTape.entry old extra (bitValue newp) table order assignment).words:=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackChildTableEntryClock.ready_run_bounded old.axes (extra++old.axes)\n    (SemiprimeD1StackChildTableEntryAcquisition.prod_positive old.axes ho)\n    (SemiprimeD1StackChildTableEntryAcquisition.prod_positive (extra++old.axes) (appended_positive old.axes extra ho he))\n    oldp newp table order assignment (selected_shape old table hg order assignment) (rank_mono old.axes extra he)\n  refine ⟨t,ht,hr,?_⟩\n  rw [output_bytes,entry_words old extra he]\nend RiemannGaussian.SemiprimeD1StackChildTableEntryOriginal\n","RiemannGaussian.SemiprimeD1StackCopy":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackBytecode\n\n/-! # Fixed finite Boolean-stack copying\nThe input is moved through a real scratch stack, restored, and copied to the\noutput by literal pop/push instructions. All labels and stacks are fixed before\ninput. Native lengths occur in the proof of time, never in machine control.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 500000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackCopy\nopen SemiprimeD1StackBytecode\n\n/-- Fixed nine-label program, with input zero, output one, and scratch two. -/\ndef code (label:Fin 9) : Instruction (Fin 3) (Fin 9) :=\n  if label=0 then .pop 0 3 1 2\n  else if label=1 then .push 2 false 0\n  else if label=2 then .push 2 true 0\n  else if label=3 then .pop 2 6 4 5\n  else if label=4 then .push 0 false 7\n  else if label=5 then .push 0 true 8\n  else if label=7 then .push 1 false 3\n  else if label=8 then .push 1 true 3\n  else .halt\n\n/-- Three actual Boolean payloads; no native list is stored in finite control. -/\ndef payload (input output scratch:List Bool) : Fin 3→List Bool :=\n  fun k=>if k=0 then input else if k=1 then output else scratch\n\n/-- Concrete state at a fixed program label. -/\ndef state (label:Fin 9) (flag:Option Bool) (input output scratch:List Bool) :\n    State (Fin 3) (Fin 9) := ⟨some label,flag,payload input output scratch⟩\n\n/-- Concrete halted state with an empty scratch stack. -/\ndef done (input output:List Bool) : State (Fin 3) (Fin 9) :=\n  ⟨none,none,payload input output []⟩\n\n/-- Actual sequential composition of source transitions. -/\ntheorem run_add {K L:Type} [DecidableEq K] (program:L→Instruction K L)\n    (m n:ℕ) (s:State K L) :\n    run program (m+n) s=(run program m s).bind (run program n) := by\n  unfold run\n  rw [Nat.add_comm m n,Function.iterate_add_apply]\n  generalize (fun state=>state.bind (step program))^[m] (some s)=o\n  cases o with\n  | some s => rfl\n  | none => exact Function.iterate_fixed rfl n\n\n/-- Two executed instructions move one input bit onto scratch. -/\ntheorem move_bit (b:Bool) (xs ys zs:List Bool) (flag:Option Bool) :\n    run code 2 (state 0 flag (b::xs) ys zs)=\n      some (state 0 (some b) xs ys (b::zs)) := by\n  cases b <;> simp [run,Function.iterate_succ_apply,step,execute,code,state,payload,\n    choose,Function.update] <;> funext k <;> fin_cases k <;> rfl\n\n/-- Three executed instructions restore one scratch bit and copy it to output. -/\ntheorem copy_bit (b:Bool) (xs ys zs:List Bool) (flag:Option Bool) :\n    run code 3 (state 3 flag xs ys (b::zs))=\n      some (state 3 (some b) (b::xs) (b::ys) zs) := by\n  cases b <;> simp [run,Function.iterate_succ_apply,step,execute,code,state,payload,\n    choose,Function.update] <;> funext k <;> fin_cases k <;> rfl\n\n/-- Actual first loop, including its empty-input branch, reverses into scratch. -/\ntheorem move_run (xs ys zs:List Bool) (flag:Option Bool) :\n    run code (2*xs.length+1) (state 0 flag xs ys zs)=\n      some (state 3 none [] ys (xs.reverse++zs)) := by\n  induction xs generalizing zs flag with\n  | nil => simp [run,step,execute,code,state,payload,choose]\n  | cons b xs ih =>\n    rw [show 2*(b::xs).length+1=2+(2*xs.length+1) by simp; omega,run_add,move_bit]\n    simp only [Option.bind_some]\n    rw [ih]\n    simp only [List.reverse_cons,List.append_assoc,List.singleton_append]\n\n/-- Actual second loop restores/copies the whole scratch word and halts cleanly. -/\ntheorem copy_run (zs xs ys:List Bool) (flag:Option Bool) :\n    run code (3*zs.length+2) (state 3 flag xs ys zs)=\n      some (done (zs.reverse++xs) (zs.reverse++ys)) := by\n  induction zs generalizing xs ys flag with\n  | nil => simp [run,Function.iterate_succ_apply,step,execute,code,state,done,payload,\n      choose]\n  | cons b zs ih =>\n    rw [show 3*(b::zs).length+2=3+(3*zs.length+2) by simp; omega,run_add,copy_bit]\n    simp only [Option.bind_some]\n    rw [ih]\n    simp only [List.reverse_cons,List.append_assoc,List.singleton_append]\n\n/-- Complete acquired copy: input restored, output prepended, scratch empty. -/\ntheorem copy_words (xs ys:List Bool) (flag:Option Bool) :\n    run code (5*xs.length+3) (state 0 flag xs ys [])=some (done xs (xs++ys)) := by\n  rw [show 5*xs.length+3=(2*xs.length+1)+(3*xs.reverse.length+2) by simp; omega,run_add,move_run]\n  simp only [List.append_nil,Option.bind_some]\n  rw [copy_run,List.reverse_reverse,List.append_nil]\n\n/-- One fixed genuine finite machine, independent of all input payloads. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackBytecode.machine 0 1 0 code\n\n/-- Actual finite-machine copying certificate, including both real loops. -/\ndef copyInTime (xs ys:List Bool) (flag:Option Bool) :\n    StateTransition.EvalsToInTime machine.step (configuration (state 0 flag xs ys []))\n      (some (configuration (done xs (xs++ys)))) (5*xs.length+3) := by\n  apply evalsCorrect 0 1 0 code\n  exact ⟨⟨5*xs.length+3,copy_words xs ys flag⟩,le_refl _⟩\n/-- Every literal instruction increases any stack length by at most one. -/\ntheorem execute_bound {K L:Type} [DecidableEq K] (instruction:Instruction K L)\n    (s:State K L) (C:ℕ) (h:∀k,(s.store k).length ≤ C) :\n    ∀k,((execute instruction s).store k).length ≤ C+1 := by\n  cases instruction with\n  | push target bit next =>\n    intro k\n    by_cases hk:k=target\n    · subst k; simpa [execute] using Nat.succ_le_succ (h target)\n    · simpa [execute,Function.update,hk] using (h k).trans (Nat.le_succ C)\n  | pop target empty low high =>\n    intro k\n    by_cases hk:k=target\n    · subst k\n      simpa [execute] using (by simp only [List.length_tail]; exact Nat.sub_le _ _: (s.store target).tail.length ≤ (s.store target).length).trans ((h target).trans (Nat.le_succ C))\n    · simpa [execute,Function.update,hk] using (h k).trans (Nat.le_succ C)\n  | peek target empty low high => exact fun k=>(h k).trans (Nat.le_succ C)\n  | jump next => exact fun k=>(h k).trans (Nat.le_succ C)\n  | halt => exact fun k=>(h k).trans (Nat.le_succ C)\n\n/-- Every actual reached prefix has bounded payload on every stack. -/\ntheorem run_bound {K L:Type} [DecidableEq K] (program:L→Instruction K L)\n    (fuel C:ℕ) (s out:State K L) (h:∀k,(s.store k).length ≤ C)\n    (hr:run program fuel s=some out) : ∀k,(out.store k).length ≤ C+fuel := by\n  induction fuel generalizing s out C with\n  | zero => change some s=some out at hr;cases hr;exact h\n  | succ fuel ih =>\n    rw [show fuel+1=1+fuel by omega,run_add] at hr\n    change (step program s).bind (run program fuel)=some out at hr\n    cases hp:s.pc with\n    | none => simp [step,hp] at hr\n    | some label =>\n      have he:step program s=some (execute (program label) s):=by simp [step,hp]\n      rw [he,Option.bind_some] at hr\n      have hb:=ih (C+1) (execute (program label) s) out (execute_bound _ _ _ h) hr\n      simpa only [Nat.add_assoc,Nat.add_comm 1 fuel] using hb\n\n/-- Actual copy prefixes have a linear bound on all three physical stack payloads. -/\ntheorem copy_prefix_bound (xs ys:List Bool) (flag:Option Bool) (fuel:ℕ)\n    (out:State (Fin 3) (Fin 9)) (hr:run code fuel (state 0 flag xs ys [])=some out) :\n    ∀k,(out.store k).length ≤ xs.length+ys.length+fuel := by\n  apply run_bound code fuel (xs.length+ys.length) _ out ?_ hr\n  intro k\n  fin_cases k <;> simp [state,payload]\n/-- Total actual copy-stack cells at every reached source prefix. -/\ntheorem copy_prefix_cells (xs ys:List Bool) (flag:Option Bool) (fuel:ℕ)\n    (out:State (Fin 3) (Fin 9)) (hr:run code fuel (state 0 flag xs ys [])=some out) :\n    (out.store 0).length+(out.store 1).length+(out.store 2).length ≤\n      3*(xs.length+ys.length+fuel) := by\n  have h:=copy_prefix_bound xs ys flag fuel out hr\n  have h0:=h 0\n  have h1:=h 1\n  have h2:=h 2\n  omega\n\n/-- The reached-cell bound applies to actual finite-machine prefixes, not only source runs. -/\ntheorem machine_prefix_cells (xs ys:List Bool) (flag:Option Bool) (fuel:ℕ)\n    (cfg:Turing.TM2.Cfg (fun _:Fin 3=>Bool) (Fin 9) (Option Bool))\n    (hr:(fun cfg=>cfg.bind machine.step)^[fuel] (some (configuration (state 0 flag xs ys [])))=some cfg) :\n    (cfg.stk 0).length+(cfg.stk 1).length+(cfg.stk 2).length ≤\n      3*(xs.length+ys.length+fuel) := by\n  have he:=run_correct 0 1 0 code fuel (state 0 flag xs ys [])\n  change (run code fuel (state 0 flag xs ys [])).map configuration=\n    (fun cfg=>cfg.bind machine.step)^[fuel] (some (configuration (state 0 flag xs ys []))) at he\n  cases hc:run code fuel (state 0 flag xs ys []) with\n  | none => rw [hc,hr] at he;cases he\n  | some out =>\n    rw [hc,hr] at he\n    have hcfg:configuration out=cfg:=Option.some.inj he\n    rw [←hcfg]\n    exact copy_prefix_cells xs ys flag fuel out hc\nend RiemannGaussian.SemiprimeD1StackCopy\n","RiemannGaussian.SemiprimeD1StackDescriptorRecordLoadView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDescriptorRecord\n/-! # Exact proof views of the physically loaded checker template -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackDescriptorRecordLoadView\nopen SemiprimeD1StackDescriptorRecord\nvariable {K L : Type} [DecidableEq K] (s : T.Static K L) (sourceMap : K→Option (Fin 6))\n/-- Change only the actual checker template, retaining every other physical role. -/\ndef replaceTemplate (d : Stack K→List Bool) (template : K→List Bool) : Stack K→List Bool\n  | .inl (.inl (.inr (.inl k)))=>template k\n  | k=>d k\n/-- Prefix of literal template positions already physically drained and loaded. -/\ndef loadPrefix (d : Stack K→List Bool) (n : Nat) : Stack K→List Bool :=\n  replaceTemplate d (fun k=>if k∈s.roles.take n then selected sourceMap (fun i=>d (source i)) k else d (templateStack k))\n/-- Every actual template field loaded from its selected physical source or empty. -/\ndef loaded (d : Stack K→List Bool) : Stack K→List Bool :=\n  replaceTemplate d (selected sourceMap (fun i=>d (source i)))\n/-- No template field is preloaded before the real loader executes. -/\ntheorem loadPrefix_zero (d : Stack K→List Bool) : loadPrefix s sourceMap d 0=d := by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · simp only [loadPrefix,replaceTemplate,List.take_zero,List.not_mem_nil,ite_false,templateStack,\n            recordStack,R.tableStack,T.template]\n        · rfl\n    · rfl\n  · rfl\n/-- The compile-time inventory covers every physical template field. -/\ntheorem loadPrefix_full (d : Stack K→List Bool) : loadPrefix s sourceMap d s.roles.length=loaded sourceMap d := by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · simp only [loadPrefix,replaceTemplate,List.take_length,s.complete k,ite_true,loaded]\n        · rfl\n    · rfl\n  · rfl\n/-- One actual target write advances exactly one literal template position. -/\ntheorem loadPrefix_step (d : Stack K→List Bool) (p : Fin s.roles.length) :\n    Function.update (loadPrefix s sourceMap d p.val) (templateStack (T.role s p))\n      (selected sourceMap (fun i=>d (source i)) (T.role s p))=loadPrefix s sourceMap d (p.val+1) := by\n  funext q\n  rcases q with q|q\n  · rcases q with q|q\n    · rcases q with q|q\n      · rw [Function.update_of_ne (by intro he;cases he)];rfl\n      · rcases q with k|q\n        · by_cases he:k=s.roles[p.val]\n          · subst k\n            change Function.update _ (templateStack s.roles[p.val]) _ (templateStack s.roles[p.val])=_\n            rw [Function.update_self]\n            simp only [loadPrefix,replaceTemplate,List.take_succ_eq_append_getElem p.isLt,List.mem_append,\n              List.mem_cons,List.not_mem_nil,or_false,or_true,ite_true,T.role,templateStack,recordStack,R.tableStack,T.template]\n          · have hn:templateStack k≠templateStack (T.role s p):=by\n              intro h\n              exact he (Sum.inl.inj (Sum.inr.inj (Sum.inl.inj (Sum.inl.inj h))))\n            change Function.update _ (templateStack (T.role s p)) _ (templateStack k)=_\n            rw [Function.update_of_ne hn]\n            simp only [loadPrefix,replaceTemplate,List.take_succ_eq_append_getElem p.isLt,List.mem_append,\n              List.mem_cons,List.not_mem_nil,or_false,he,or_false,templateStack,recordStack,R.tableStack,T.template]\n        · rw [Function.update_of_ne (by intro he;cases he)];rfl\n    · rw [Function.update_of_ne (by intro he;cases he)];rfl\n  · rw [Function.update_of_ne (by intro he;cases he)];rfl\n/-- Actual old words and physical descriptor fields are all charged. -/\ndef inventory [Fintype K] (d : Stack K→List Bool) : Nat :=∑k:Stack K,(d k).length\nomit [DecidableEq K] in\n/-- One physical word never exceeds the full actual input inventory. -/\ntheorem cell_le [Fintype K] (d : Stack K→List Bool) (k : Stack K) : (d k).length≤ inventory d := by\n  unfold inventory\n  exact Finset.single_le_sum (f:=fun k:Stack K=>(d k).length) (fun _ _=>Nat.zero_le _) (Finset.mem_univ k)\nomit [DecidableEq K] in\n/-- A source-selected field is bounded by the actual supplied six-word inventory. -/\ntheorem selected_le [Fintype K] (d : Stack K→List Bool) (k : K) :\n    (selected sourceMap (fun i=>d (source i)) k).length≤ inventory d := by\n  unfold selected\n  cases sourceMap k with\n  | none=>exact Nat.zero_le _\n  | some i=>exact cell_le d (source i)\n/-- Loaded and not-yet-loaded target words have the same actual inventory bound. -/\ntheorem prefix_cell_le [Fintype K] (d : Stack K→List Bool) (n : Nat) (k : K) :\n    (loadPrefix s sourceMap d n (templateStack k)).length≤ inventory d := by\n  change (if k∈s.roles.take n then selected sourceMap (fun i=>d (source i)) k else d (templateStack k)).length≤_\n  split\n  · exact selected_le sourceMap d k\n  · exact cell_le d (templateStack k)\nend RiemannGaussian.SemiprimeD1StackDescriptorRecordLoadView\n","RiemannGaussian.SemiprimeD1StackEdgeCatalogueExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEdgeCatalogueTransduction\n\n/-! # Whole original binary-input half-edge catalogue acquisition -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackEdgeCatalogueExecution\nopen SemiprimeD1StackEdgeCatalogue SemiprimeD1StackEdgeCatalogueComponents\nopen SemiprimeD1StackEdgeCatalogueView SemiprimeD1StackEdgeCatalogueTransduction\nopen SemiprimeD1StackProcedureFragments (Runs)\nopen SemiprimeD1EdgeCatalogueEncoding (Record tape output vertex)\nopen SemiprimeD1StackVertexCatalogueCaches (digitCountValue)\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\n\n/-- Mathematical descriptor sequence of the actual acquired old catalogue. -/\ndef records (bits:List Bool) : List Record :=\n  (SemiprimeMacroFiniteEnumerations.subdividedVertices (firstAxis bits.length) (secondAxis bits.length)\n    (digitCountValue bits)).values.map vertex\n/-- Exact global source store after the real included catalogue procedure. -/\ndef afterCat (bits:List Bool) : Stack→List Bool :=\n  Sum.elim (SemiprimeD1StackVertexCatalogueExecution.result bits) (fun _=>[])\n/-- Final actual data retain source metadata and contain the physically emitted edge tape. -/\ndef result (bits:List Bool) : Stack→List Bool :=\n  finalData (SemiprimeD1StackVertexCatalogueExecution.result bits) (output (records bits) [])\n/-- Actual halted complete producer state. -/\ndef done (bits:List Bool) : C.State Stack Label := ⟨none,none,none,result bits,[]⟩\n/-- Whole actual clock before substituting the acquired source-tape byte bound. -/\ndef budget (bits:List Bool) : ℕ :=\n  10000000000000*(bits.length+1)^5+56*(tape (records bits) []).length+6\n\n/-- The original source initial-data fact follows from its actual machine encoding. -/\ntheorem cat_input (bits:List Bool) (k:Cat.Stack) :\n    SemiprimeD1StackVertexCatalogue.input bits k=(if k=Cat.originalInput then bits else []) := by\n  have hi:=SemiprimeD1StackCalls.initial_correct Cat.originalInput\n    (Cat.kernelStack (SemiprimeD1StackCartesian4.aux 2)) (Sum.inl SemiprimeD1StackVertexCatalogue.Control.main:Cat.Label)\n    Cat.program bits\n  have he:=hi.trans (SemiprimeD1StackVertexCatalogueExecution.initial_eq bits)\n  have hd:=congrArg (fun cfg:SemiprimeD1StackVertexCatalogue.machine.Cfg=>cfg.stk (some k)) he\n  change (if k=Cat.originalInput then bits else [])=SemiprimeD1StackVertexCatalogue.input bits k at hd\n  exact hd.symm\n/-- This whole fixed machine starts from binary N alone. -/\ntheorem initial_eq (bits:List Bool) : Turing.initList machine bits=SemiprimeD1StackCalls.configuration (initial bits) := by\n  have hs:initial bits=SemiprimeD1StackCalls.initial (catStack Cat.originalInput) (.inl .main) bits:=by\n    unfold initial input SemiprimeD1StackCalls.initial\n    congr 1\n    funext k\n    rcases k with k|k\n    · simp [cat_input,catStack]\n    · simp [catStack]\n  rw [hs]\n  exact (SemiprimeD1StackCalls.initial_correct (catStack Cat.originalInput) (aux .output) (.inl .main) program bits).symm\n/-- The actual source procedure executes once, retaining all its original metadata. -/\ntheorem cat_call (bits:List Bool) (hb:bits≠[]) :\n    ∃m≤10000000000000*(bits.length+1)^5+1,Runs program m (.inl .main) (input bits) (.inl .parse) (afterCat bits) := by\n  obtain ⟨m,hm,hr⟩:=SemiprimeD1StackVertexCatalogueBounds.source_run_polynomial bits hb\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program catStack catLabel catStack_injective\n    Cat.program (.inl .main) (fun _=>rfl) (.inl .main) (.inl .parse) rfl m\n    (SemiprimeD1StackVertexCatalogue.initial bits) (SemiprimeD1StackVertexCatalogueExecution.done bits)\n    (input bits) (afterCat bits)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k => exact False.elim (hk k rfl)\n      | inr k => rfl\n/-- The transducer input is the ACTUAL acquired catalogue, not a supplied descriptor list. -/\ntheorem afterCat_clean (bits:List Bool) :\n    afterCat bits=clean (SemiprimeD1StackVertexCatalogueExecution.result bits) (tape (records bits) []) (fun _=>[]) [] [] := by\n  funext k\n  rcases k with k|k|k\n  · by_cases hk:k=sourceReader\n    · subst k\n      change SemiprimeD1VertexCatalogueEncoding.catalogue (firstAxis bits.length) (secondAxis bits.length)\n        (digitCountValue bits) []=tape (records bits) []\n      exact (SemiprimeD1EdgeCatalogueEncoding.original_input _ _ _ []).symm\n    · simp only [afterCat,Sum.elim_inl,clean,store,ite_eq_right hk]\n  · rfl\n  · cases k <;> rfl\n/-- Reusable real stage after shared catalogue acquisition; original N is its sole source parameter. -/\ntheorem ready_original (bits:List Bool) :\n    ∃m≤56*(tape (records bits) []).length+4,Runs program m (.inl .parse) (afterCat bits) (.inl .halt) (result bits) := by\n  rw [afterCat_clean]\n  exact ready _ _\n/-- WHOLE closed original-input runtime, including source, all parsing/dispatch, final reversal and halt. -/\ntheorem source_run (bits:List Bool) (hb:bits≠[]) :\n    ∃m≤budget bits,C.run program m (initial bits)=some (done bits) := by\n  obtain ⟨a,ha,h0⟩:=cat_call bits hb\n  obtain ⟨b,hb,h1⟩:=ready_original bits\n  have h:=h0.trans h1\n  obtain ⟨finish,hr,hout⟩:=h [] (initial bits) ⟨rfl,rfl,rfl⟩\n  refine ⟨a+b+1,?_,?_⟩\n  · unfold budget\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n    rcases hout with ⟨hpc,hdata,hframes⟩\n    change C.step program finish=some (done bits)\n    simp [C.step,SemiprimeD1StackCalls.step,hpc,program,C.execute,SemiprimeD1StackCalls.execute,hdata,hframes,done]\n/-- The final edge bytes equal the complete ORIGINAL enumeration, in its exact order. -/\ntheorem original_edges (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    result bits (aux .output)=(SemiprimePublicAcquiredExecution.edgeEnumeration (bitValue bits)).values.foldr\n      SemiprimeD1EdgeCatalogueEncoding.edge [] := by\n  have hw:bits.length=bitLength (bitValue bits):=SemiprimeD1BinaryBootstrap.canonical_width bits hc\n  have hb:bits≠[]:=by intro h;subst bits;simp [bitValue] at hN\n  change output (records bits) []=_\n  unfold records\n  rw [SemiprimeD1EdgeCatalogueEncoding.original_output,\n    SemiprimeD1StackVertexCatalogueTags.digitCount_raw bits hb,hw]\n  rfl\nend RiemannGaussian.SemiprimeD1StackEdgeCatalogueExecution\n","RiemannGaussian.SemiprimeD1StackEdgeCatalogueView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEdgeCatalogueComponents\nimport RiemannGaussian.SemiprimeD1EdgeCatalogueEncoding\n\n/-! # Actual edge-transducer store invariants and literal local instructions -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackEdgeCatalogueView\nopen SemiprimeD1StackEdgeCatalogue SemiprimeD1StackEdgeCatalogueComponents\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeD1EdgeCatalogueEncoding (Record)\n\n/-- Literal old catalogue role physically consumed by the parser. -/\ndef sourceReader : Cat.Stack := Cat.kernelStack (SemiprimeD1StackCartesian4.aux 2)\n/-- Exact physical store; only the actually parsed old tape role is overwritten. -/\ndef store (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (work:Aux→List Bool) : Stack→List Bool\n  | .inl k => if k=sourceReader then tape else base k\n  | .inr (.inl part) => words part\n  | .inr (.inr role) => work role\n/-- All transient component buffers are empty between literal operations. -/\ndef cleanWork (raw side:List Bool) : Aux→List Bool\n  | .reversed => raw\n  | .side => side\n  | _ => []\n/-- Actual clean loop state, retaining parsed fields and reversed emitted tape. -/\ndef clean (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (raw side:List Bool) : Stack→List Bool :=\n  store base tape words (cleanWork raw side)\n/-- The actual parser reads precisely the supplied physical tape role. -/\ntheorem store_reader (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (work:Aux→List Bool) :\n    store base tape words work reader=tape := by simp [store,reader,sourceReader,catStack]\n/-- A physical tape update preserves every other original metadata role. -/\ntheorem update_reader (base:Cat.Stack→List Bool) (tape next:List Bool) (words:Record) (work:Aux→List Bool) :\n    Function.update (store base tape words work) reader next=store base next words work := by\n  funext k\n  rcases k with k|k|k\n  · by_cases h:k=sourceReader\n    · subst k;simp [store,reader,sourceReader,catStack,Function.update]\n    · have h':k≠Cat.kernelStack (SemiprimeD1StackCartesian4.aux 2):=h\n      simp [store,reader,sourceReader,catStack,Function.update,h']\n  · simp [store,reader,catStack,Function.update]\n  · simp [store,reader,catStack,Function.update]\n/-- A real parsed-field write changes only its finite cache slot. -/\ntheorem update_cache (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (work:Aux→List Bool)\n    (part:Fin 5) (word:List Bool) :\n    Function.update (store base tape words work) (cache part) word=\n      store base tape (Function.update words part word) work := by\n  funext k\n  rcases k with k|k|k\n  · simp [store,cache,Function.update]\n  · by_cases h:k=part\n    · subst k;simp [store,cache,Function.update]\n    · simp [store,cache,Function.update,h]\n  · simp [store,cache,Function.update]\n/-- A real work-stack write changes only that physical role. -/\ntheorem update_aux (base:Cat.Stack→List Bool) (tape:List Bool) (words:Record) (work:Aux→List Bool)\n    (role:Aux) (word:List Bool) :\n    Function.update (store base tape words work) (aux role) word=\n      store base tape words (Function.update work role word) := by\n  funext k\n  rcases k with k|k|k\n  · simp [store,aux,Function.update]\n  · simp [store,aux,Function.update]\n  · by_cases h:k=role\n    · subst k;simp [store,aux,Function.update]\n    · simp [store,aux,Function.update,h]\n\n/-- A literal global push, including its actual data-cell allocation. -/\ntheorem push_run (pc next:Label) (stack:Stack) (bit:Bool) (data:Stack→List Bool)\n    (hc:program pc=.base (.push stack bit next)) :\n    Runs program 1 pc data next (Function.update data stack (bit::data stack)) := by\n  exact one_base program pc next (.push stack bit next) data _ hc rfl rfl\n\n/-- A literal global pop with one continuation, including actual EOF. -/\ntheorem pop_run (pc next:Label) (stack:Stack) (data:Stack→List Bool)\n    (hc:program pc=.base (.pop stack next next next)) :\n    Runs program 1 pc data next (Function.update data stack (data stack).tail) := by\n  apply one_base program pc next (.pop stack next next next) data _ hc\n  · cases h:(data stack).head? with\n    | none => simp [B.execute,SemiprimeD1StackBytecode.choose,h]\n    | some bit => cases bit <;> simp [B.execute,SemiprimeD1StackBytecode.choose,h]\n  · rfl\n\n/-- Every old limit byte is physically cleared; no stale field is discarded for free. -/\ntheorem clear_run (word:List Bool) (pc next:Label) (stack:Stack) (data:Stack→List Bool)\n    (hw:data stack=word) (hc:program pc=.base (.pop stack next pc pc)) :\n    Runs program (word.length+1) pc data next (Function.update data stack []) := by\n  induction word generalizing data with\n  | nil =>\n    apply one_base program pc next (.pop stack next pc pc) data _ hc\n    · simp [B.execute,SemiprimeD1StackBytecode.choose,hw]\n    · change Function.update data stack (data stack).tail=_\n      rw [hw,List.tail_nil]\n  | cons bit word ih =>\n    have h0:Runs program 1 pc data pc (Function.update data stack word):=by\n      apply one_base program pc pc (.pop stack next pc pc) data _ hc\n      · cases bit <;> simp [B.execute,SemiprimeD1StackBytecode.choose,hw]\n      · change Function.update data stack (data stack).tail=_\n        rw [hw,List.tail_cons]\n    have h1:=ih (Function.update data stack word) (Function.update_self _ _ _)\n    have h:=h0.trans h1\n    rw [Function.update_idem] at h\n    simpa only [List.length_cons,show 1+(word.length+1)=word.length+1+1 by omega] using h\nend RiemannGaussian.SemiprimeD1StackEdgeCatalogueView\n","RiemannGaussian.SemiprimeD1StackEdgeCount":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackDigitCountLoop\nimport RiemannGaussian.SemiprimeD1EdgeCatalogueEncoding\n/-! # Physical six-field edge-record counting\nThe first false is a legitimate empty side field, NOT vector EOF. The actual\nloop peeks only for an empty tape, parses exactly six complete fields, consumes\nevery validity bit and payload, and pushes two occurrence markers and one wire marker per complete edge record.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1500000\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackEdgeCount\nnamespace B\nexport SemiprimeD1StackBytecode (Instruction State execute step run)\nend B\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\n/-- Same seven literal physical roles as the frozen preserving cache scanner. -/\nabbrev Stack := SemiprimeD1StackDigitCount.Stack\n/-- Seven-word physical payload, no native record count in control. -/\nabbrev data := SemiprimeD1StackDigitCount.data\n/-- Literal source-preserving whole-tape copy operands. -/\nabbrev copyStack := SemiprimeD1StackDigitCount.copyStack\n/-- Literal actual field-reader operands. -/\nabbrev fieldStack := SemiprimeD1StackDigitCount.fieldStack\n/-- Fixed six-field control, including acquired validity and physical payload drain. -/\ninductive Control where\n  | start | peekRecord | pushCount | pushSecond | pushWire | done | abort\n  | read (part : Fin 6) | valid (part : Fin 6) | clear (part : Fin 6)\n  deriving DecidableEq,Fintype\n/-- Static real Copy and field-parser calls, independent of all edge metadata. -/\nabbrev Label := Control ⊕ (Fin 9 ⊕ Field.Label)\n/-- Fixed included Copy labels. -/\ndef copyLabel (pc : Fin 9) : Label := .inr (.inl pc)\n/-- Fixed included real field-parser labels. -/\ndef fieldLabel (pc : Field.Label) : Label := .inr (.inr pc)\n/-- Only after the sixth complete field does an edge contribute its actual markers. -/\ndef afterClear (part : Fin 6) : Label :=\n  if h : part.val<5 then .inl (.read ⟨part.val+1,by omega⟩) else .inl .pushCount\n/-- One fixed physical tape-counting program; false head bits are parsed. -/\ndef program : Label→C.Instruction Stack Label\n  | .inr (.inl pc) => SemiprimeD1StackMultiplierLink.instruction copyStack copyLabel (SemiprimeD1StackCopy.code pc)\n  | .inr (.inr pc) => SemiprimeD1StackMultiplierLink.instruction fieldStack fieldLabel (Field.code pc)\n  | .inl .start => .call (copyLabel 0) (.inl .peekRecord)\n  | .inl .peekRecord => .base (.peek .reader (.inl .done) (.inl (.read 0)) (.inl (.read 0)))\n  | .inl (.read part) => .call (fieldLabel (Field.active .tagPop (none,false))) (.inl (.valid part))\n  | .inl (.valid part) => .base (.pop .valid (.inl .abort) (.inl .abort) (.inl (.clear part)))\n  | .inl (.clear part) => .base (.pop .word (afterClear part) (.inl (.clear part)) (.inl (.clear part)))\n  | .inl .pushCount => .base (.push .count true (.inl .pushSecond))\n  | .inl .pushSecond => .base (.push .count true (.inl .pushWire))\n  | .inl .pushWire => .base (.push .copyScratch true (.inl .peekRecord))\n  | .inl .done | .inl .abort => .base .halt\n/-- Exact six ordinary fields of one edge record; used only as input specification. -/\nabbrev Record := Fin 6→List Bool\n/-- Actual edge-record input grammar, with NO extra vector marker. -/\ndef record (words : Record) (tail : List Bool) : List Bool :=\n  SemiprimeSourceHistogramKeyBits.frame (words 0)\n    (SemiprimeSourceHistogramKeyBits.frame (words 1)\n      (SemiprimeSourceHistogramKeyBits.frame (words 2)\n        (SemiprimeSourceHistogramKeyBits.frame (words 3)\n          (SemiprimeSourceHistogramKeyBits.frame (words 4)\n            (SemiprimeSourceHistogramKeyBits.frame (words 5) tail)))))\n/-- Full sequence of complete six-field records. -/\ndef tape (records : List Record) (tail : List Bool) : List Bool := records.foldr record tail\n/-- Actual seven-stack fixed machine. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine SemiprimeD1StackDigitCount.Stack.bank SemiprimeD1StackDigitCount.Stack.count (.inl .start) program\n/-- Bank-only entry has no reader, count or parsed-field answer. -/\ndef initial (bank : List Bool) : C.State Stack Label := ⟨some (.inl .start),none,none,data bank [] [] [] [] [] [],[]⟩\n/-- Complete physical result preserves original bank and returns acquired markers. -/\ndef done (bank : List Bool) (n : ℕ) : C.State Stack Label :=\n  ⟨none,none,none,data bank [] (List.replicate (2*n) true) [] [] [] (List.replicate n true),[]⟩\n/-- After the initial preserving Copy, its emptied scratch is never used by\nfield reads and retains one physically acquired wire marker per record. -/\ndef wireCount : Stack := .copyScratch\n/-- Exact bytes of one six-field record, including empty fields. -/\ntheorem record_length (words : Record) (tail : List Bool) :\n    (record words tail).length=2*((List.finRange 6).map (fun i=>(words i).length)).sum+6+tail.length := by\n  simp [record,SemiprimeSourceHistogramKeyBits.frame_length,List.finRange_succ,List.map_cons,List.sum_cons]\n  omega\n/-- Six physical fields pay at least one byte per complete record. -/\ntheorem count_le_bytes (records : List Record) : records.length≤(tape records []).length := by\n  induction records with\n  | nil => simp [tape]\n  | cons r rs ih =>\n    simp only [tape,List.foldr_cons,record_length,List.length_cons] at *\n    omega\n/-- An original half-edge is exactly side + tag + four coordinates. -/\ndef edgeFields {r t digits : ℕ} (edge : SemiprimeMacroGraph.Edge r t digits) : Record :=\n  ![SemiprimeD1EdgeCatalogueEncoding.sideWord edge.2,\n    SemiprimeD1EdgeCatalogueEncoding.bit edge.1 0,SemiprimeD1EdgeCatalogueEncoding.bit edge.1 1,\n    SemiprimeD1EdgeCatalogueEncoding.bit edge.1 2,SemiprimeD1EdgeCatalogueEncoding.bit edge.1 3,\n    SemiprimeD1EdgeCatalogueEncoding.bit edge.1 4]\n/-- Exact original input grammar, not a graph/record getter executed by the counter. -/\ntheorem record_edge {r t digits : ℕ} (edge : SemiprimeMacroGraph.Edge r t digits) (tail : List Bool) :\n    record (edgeFields edge) tail=SemiprimeD1EdgeCatalogueEncoding.edge edge tail := rfl\n/-- Full actual original edge tape has exactly this six-field-per-record encoding. -/\ntheorem original_tape {r t digits : ℕ} (edges : List (SemiprimeMacroGraph.Edge r t digits)) :\n    tape (edges.map edgeFields) []=edges.foldr SemiprimeD1EdgeCatalogueEncoding.edge [] := by\n  simp only [tape,List.foldr_map,record_edge]\n\nend RiemannGaussian.SemiprimeD1StackEdgeCount\n","RiemannGaussian.SemiprimeD1StackEuclidGCDBody":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackEuclidGCDCalls\n/-! # Actual positive Euclid iteration and actual terminal zero-divisor cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackEuclidGCDBody\nopen SemiprimeD1StackEuclidGCD SemiprimeD1StackEuclidGCDEncoding SemiprimeD1StackEuclidGCDCalls\nopen SemiprimeD1StackProcedureTrace\n/-- Actual time for one complete positive-divisor step, including every return and erased quotient/backup byte. -/\ndef stepTime (xs ys:List Bool) :Nat:=\n  2+(5*ys.length+4)+(SemiprimeD1StackDividerExecution.executionTime xs ys+1)+\n    ((SemiprimeBitDivision.divideLoop xs ys).quotient.length+1)+(5*ys.length+4)+(ys.length+1)+\n    (2*(SemiprimeBitDivision.divideLoop xs ys).remainder.length+3)+\n    (SemiprimeD1StackReduceExecution.trimTime (SemiprimeBitDivision.divideLoop xs ys).remainder.reverse+1)\n/-- The actual fuel head and actual nonempty divisor drive a complete restoring division, swap and trim. -/\ntheorem step_run (left right fuel xs ys:List Bool) (hne:ys≠[]) :\n    Runs program (stepTime xs ys) .loop (bank (loopWords left right (true::fuel) xs ys)) .loop\n      (bank (loopWords left right fuel ys\n        (SemiprimeD1StackSourceEnvironmentEncoding.normalize (SemiprimeBitDivision.divideLoop xs ys).remainder))) :=by\n  have h0:=P.pop_run .loop .abort .abort .check (aux .fuel)\n    (bank (loopWords left right (true::fuel) xs ys)) (true::fuel) rfl rfl\n  rw [update_fuel] at h0\n  have h1:=P.peek_run .check .reverseFinish .backup .backup y\n    (bank (loopWords left right fuel xs ys)) ys rfl rfl\n  have he:SemiprimeD1StackBytecode.choose Label.reverseFinish .backup .backup ys.head?=.backup:=by\n    cases ys with\n    | nil=>exact False.elim (hne rfl)\n    | cons b ys=>cases b <;> rfl\n  rw [he] at h1\n  have h2:=P.copy_call .backupY .backup .divide rfl (bank (loopWords left right fuel xs ys)) ys [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (aux .next) (ys++[])) at h2\n  rw [List.append_nil,update_next] at h2\n  have h3:=divide_call left right fuel xs ys ys\n  let rem:=(SemiprimeBitDivision.divideLoop xs ys).remainder\n  let quo:=(SemiprimeBitDivision.divideLoop xs ys).quotient\n  have h4:=P.drain_loop .clearQuotient .restoreX quotient rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,next:=ys,remainder:=rem,quotient:=quo}) quo rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (dividerStack (.inr .quotient)) []) at h4\n  rw [update_quotient] at h4\n  have h5:=P.copy_call .restoreX .restoreX .clearNext rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,next:=ys,remainder:=rem}) ys [] rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (bank _) (dividerStack (.inr .input)) (ys++[])) at h5\n  rw [List.append_nil,update_x] at h5\n  have h6:=P.drain_loop .clearNext .reverseRemainder (aux .next) rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,next:=ys,remainder:=rem,x:=ys}) ys rfl\n  rw [update_next] at h6\n  have h7:=P.reverse_call .remainder .reverseRemainder .trimRemainder rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,remainder:=rem,x:=ys}) rem [] rfl rfl\n  change Runs _ _ _ _ _ (Function.update (Function.update (bank _) (dividerStack (.inr .remainder)) [])\n    (aux .trimScratch) (rem.reverse++[])) at h7\n  rw [List.append_nil,update_remainder,update_trimScratch] at h7\n  have h8:=P.trim_call .divisor .trimRemainder .loop rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,x:=ys,trimScratch:=rem.reverse}) rem.reverse [] rfl rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (Function.update (bank _) (aux .trimScratch) [])\n    (dividerStack (.inr .divisor)) (SemiprimeD1StackReduceExecution.trimReverse rem.reverse++[])) at h8\n  rw [List.append_nil,update_trimScratch,update_y] at h8\n  exact P.join (P.join (P.join (P.join (P.join (P.join (P.join (P.join h0 h1) h2) h3) h4) h5) h6) h7) h8\n/-- Actual zero-divisor terminal fragment includes remaining fuel erasure and its EOF. -/\ndef finishTime (fuel xs:List Bool) :Nat:=\n  2+(2*xs.length+3)+(SemiprimeD1StackReduceExecution.trimTime xs.reverse+1)+(fuel.length+1)\n/-- Both actual original words survive final normalization and every remaining fuel marker is physically popped. -/\ntheorem finish_run (left right fuel xs:List Bool) :\n    Runs program (finishTime fuel xs) .loop (bank (loopWords left right (true::fuel) xs [])) .done\n      (bank {originalLeft:=left,originalRight:=right, output:=SemiprimeD1StackSourceEnvironmentEncoding.normalize xs}) :=by\n  have h0:=P.pop_run .loop .abort .abort .check (aux .fuel)\n    (bank (loopWords left right (true::fuel) xs [])) (true::fuel) rfl rfl\n  rw [update_fuel] at h0\n  have h1:=P.peek_run .check .reverseFinish .backup .backup y\n    (bank (loopWords left right fuel xs [])) [] rfl rfl\n  have h2:=P.reverse_call .finish .reverseFinish .trimFinish rfl\n    (bank (loopWords left right fuel xs [])) xs [] rfl rfl\n  change Runs _ _ _ _ _ (Function.update (Function.update (bank _) (dividerStack (.inr .input)) [])\n    (aux .trimScratch) (xs.reverse++[])) at h2\n  rw [List.append_nil,update_x,update_trimScratch] at h2\n  have h3:=P.trim_call .output .trimFinish .clearFuel rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel,trimScratch:=xs.reverse}) xs.reverse [] rfl rfl rfl rfl\n  change Runs _ _ _ _ _ (Function.update (Function.update (bank _) (aux .trimScratch) [])\n    (aux .output) (SemiprimeD1StackReduceExecution.trimReverse xs.reverse++[])) at h3\n  rw [List.append_nil,update_trimScratch,update_output] at h3\n  have h4:=P.drain_loop .clearFuel .done (aux .fuel) rfl\n    (bank {originalLeft:=left,originalRight:=right,fuel:=fuel, output:=SemiprimeD1StackSourceEnvironmentEncoding.normalize xs}) fuel rfl\n  rw [update_fuel] at h4\n  exact P.join (P.join (P.join (P.join h0 h1) h2) h3) h4\nend RiemannGaussian.SemiprimeD1StackEuclidGCDBody\n","RiemannGaussian.SemiprimeD1StackExprPowerExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackExprPowerSpec\n\n/-! # Counted literal power-syntax construction trace\nEvery base occurrence is physically copied. Both exponent passes consume their\nown real acquired counter copies; no result syntax or stop count is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackExprPowerExecution\nopen SemiprimeD1StackExprPower SemiprimeD1StackExprPowerSpec SemiprimeD1StackProcedureTrace\n\n/-- Exact reached payload after one real count/base copy. -/\ndef copied (isBase : Bool) (baseCode cached count out : List Bool) : Stack→List Bool :=\n  store baseCode cached (if isBase then count else cached++count) [] (if isBase then baseCode++out else out)\n\n/-- Real included Copy, preserving its actual cached source and all other cells. -/\ntheorem copy_call (isBase : Bool) (baseCode cached count out : List Bool) (pc next : Label)\n    (hcall : program pc=.call (.copy isBase 0) next) :\n    Runs program (5*(if isBase then baseCode else cached).length+4) pc\n      (store baseCode cached count [] out) next (copied isBase baseCode cached count out) := by\n  apply included_call program (copyStack isBase) (Label.copy isBase) (copyStack_injective isBase)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hcall\n    (5*(if isBase then baseCode else cached).length+3)\n    (SemiprimeD1StackCopy.state 0 none (if isBase then baseCode else cached) (if isBase then out else count) [])\n    (SemiprimeD1StackCopy.done (if isBase then baseCode else cached)\n      ((if isBase then baseCode else cached)++(if isBase then out else count)))\n    (store baseCode cached count [] out) (copied isBase baseCode cached count out)\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words _ _ none\n  · constructor\n    · intro k;cases isBase <;> fin_cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases isBase <;> fin_cases k <;> rfl\n    · intro k hk\n      cases isBase <;> fin_cases k <;> first | rfl | exact False.elim (hk 1 rfl)\n\n/-- Empty disposable count is populated by an actual preserving cache Copy. -/\ntheorem count_copy (baseCode cached out : List Bool) (pc next : Label)\n    (hcall : program pc=.call (.copy false 0) next) :\n    Runs program (5*cached.length+4) pc (store baseCode cached [] [] out)\n      next (store baseCode cached cached [] out) := by\n  simpa only [copied,Bool.false_eq_true,ite_false,List.append_nil] using\n    copy_call false baseCode cached [] out pc next hcall\n\n/-- One actual base Copy prepends the WHOLE acquired base byte stream. -/\ntheorem base_copy (baseCode cached count out : List Bool) :\n    Runs program (5*baseCode.length+4) .baseCopy (store baseCode cached count [] out)\n      .baseLoop (store baseCode cached count [] (baseCode++out)) := by\n  exact copy_call true baseCode cached count out .baseCopy .baseLoop rfl\n\n/-- Actual fixed push helper, used only with declared literal program instructions. -/\ntheorem push_run (pc next : Label) (b : Bool) (baseCode cached count out : List Bool)\n    (hcode : program pc=.base (.push output b next)) :\n    Runs program 1 pc (store baseCode cached count [] out)\n      next (store baseCode cached count [] (b::out)) := by\n  apply one_base program pc next (.push output b next) _ _ hcode\n  · rfl\n  · funext k;fin_cases k <;> rfl\n\n/-- Every actual exponent marker triggers one complete base-code Copy. -/\ntheorem base_loop (count baseCode cached out : List Bool) :\n    Runs program ((5*baseCode.length+5)*count.length+1) .baseLoop (store baseCode cached count [] out)\n      .one0 (store baseCode cached [] [] (repeated count.length baseCode out)) := by\n  induction count generalizing out with\n  | nil =>\n    apply one_base program .baseLoop .one0 (.pop counter .one0 .baseCopy .baseCopy) _ _ rfl\n    · rfl\n    · funext k;fin_cases k <;> rfl\n  | cons bit count ih =>\n    have h0 : Runs program 1 .baseLoop (store baseCode cached (bit::count) [] out)\n        .baseCopy (store baseCode cached count [] out) := by\n      apply one_base program .baseLoop .baseCopy (.pop counter .one0 .baseCopy .baseCopy) _ _ rfl\n      · cases bit <;> rfl\n      · funext k;fin_cases k <;> rfl\n    have h1:=base_copy baseCode cached count out\n    have h2:=ih (baseCode++out)\n    rw [repeated_push] at h2\n    have hh:=runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n    convert hh using 1\n    · simp only [List.length_cons,Nat.mul_succ]\n      omega\n    · simp only [List.length_cons,repeated]\n\n/-- The five fixed pushes produce exactly the original literal-one code prefix. -/\ntheorem one_run (baseCode cached out : List Bool) :\n    Runs program 5 .one0 (store baseCode cached [] [] out)\n      .copyAgain (store baseCode cached [] [] (oneCode++out)) := by\n  have h0:=push_run .one0 .one1 false baseCode cached [] out rfl\n  have h1:=push_run .one1 .one2 true baseCode cached [] (false::out) rfl\n  have h2:=push_run .one2 .one3 true baseCode cached [] (true::false::out) rfl\n  have h3:=push_run .one3 .one4 false baseCode cached [] (true::true::false::out) rfl\n  have h4:=push_run .one4 .copyAgain false baseCode cached [] (false::true::true::false::out) rfl\n  exact runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4\n\n/-- All exponent markers are consumed by actual tag-constructor pushes. -/\ntheorem tags_loop (count baseCode cached out : List Bool) :\n    Runs program (3*count.length+1) .mulLoop (store baseCode cached count [] out)\n      .done (store baseCode cached [] [] (tags count.length out)) := by\n  induction count generalizing out with\n  | nil =>\n    apply one_base program .mulLoop .done (.pop counter .done .mul0 .mul0) _ _ rfl\n    · rfl\n    · funext k;fin_cases k <;> rfl\n  | cons bit count ih =>\n    have h0 : Runs program 1 .mulLoop (store baseCode cached (bit::count) [] out)\n        .mul0 (store baseCode cached count [] out) := by\n      apply one_base program .mulLoop .mul0 (.pop counter .done .mul0 .mul0) _ _ rfl\n      · cases bit <;> rfl\n      · funext k;fin_cases k <;> rfl\n    have h1:=push_run .mul0 .mul1 true baseCode cached count out rfl\n    have h2:=push_run .mul1 .mulLoop true baseCode cached count (true::out) rfl\n    have h3:=ih (true::true::out)\n    rw [prefix_push] at h3\n    have hh:=runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3\n    simpa only [List.length_cons,tags,\n      show (1+1)+1+(3*count.length+1)=3*(count.length+1)+1 by omega] using hh\n\n/-- Whole actual elapsed count, including all copied base bytes and the real halt. -/\ndef totalTime (baseCode cached : List Bool) : ℕ :=\n  (5*cached.length+4)+((5*baseCode.length+5)*cached.length+1)+5+\n    (5*cached.length+4)+(3*cached.length+1)+1\n/-- Exact actual final cells; both caches retained, all work and return cells empty. -/\ndef done (baseCode cached tail : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,store baseCode cached [] [] (result cached.length baseCode tail),[]⟩\n\n/-- Complete physical power-expression acquisition from the acquired base and\nactual exponent tape; no Expr tree, output code or desired numerical power input. -/\ntheorem source_run (baseCode cached tail : List Bool) :\n    C.run program (totalTime baseCode cached) (initial baseCode cached tail)=some (done baseCode cached tail) := by\n  have h0:=count_copy baseCode cached tail .start .baseLoop rfl\n  have h1:=base_loop cached baseCode cached tail\n  have h2:=one_run baseCode cached (repeated cached.length baseCode tail)\n  have h3:=count_copy baseCode cached (oneCode++repeated cached.length baseCode tail) .copyAgain .mulLoop rfl\n  have h4:=tags_loop cached baseCode cached (oneCode++repeated cached.length baseCode tail)\n  have hh:=runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4\n  obtain ⟨finish,hf,ho⟩:=hh [] (initial baseCode cached tail) ⟨rfl,rfl,rfl⟩\n  have he:=halt_run program .done rfl (store baseCode cached [] [] (result cached.length baseCode tail)) [] finish ho\n  rw [totalTime,SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some,he]\n  rfl\n\nend RiemannGaussian.SemiprimeD1StackExprPowerExecution\n","RiemannGaussian.SemiprimeD1StackFactorScopeFibreBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFactorScopeFibreExecution\n/-! # Actual complete/prepared factor-fibre clocks and all137 physical roles -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFactorScopeFibreBounds\nopen SemiprimeD1StackFactorScopeFibre SemiprimeD1StackFactorScopeFibreExecution\n/-- Exact acquired pair bytes are bounded by the paid original scoped-port stream. -/\ntheorem pair_bytes (bits : List Bool) (hb : bits≠[]) :\n    (pairTape bits).length≤10^114*(bits.length+1)^30+1 := by\n  have hr:=SemiprimeD1StackFactorScopePairBounds.raw_length (P.rows bits)\n  have hs:=SemiprimeD1StackFactorScopePairBounds.stream_length bits hb\n  have he:=congrArg List.length (SemiprimeD1FactorScopePairEncoding.raw_records (P.rows bits) [])\n  change _=(pairTape bits).length at he\n  simp only [List.length_append,List.length_cons,List.length_nil] at he\n  omega\n/-- Prepared allowance charges the actual pair copy and every generic-filter instruction. -/\ndef preparedBound (bits key : List Bool) : Nat :=5*(pairTape bits).length+\n  SemiprimeD1StackOwnerFibreBounds.runBound key ((P.rows bits).map SemiprimeD1FactorScopePairEncoding.pair)+6\n/-- Same fixed program's prepared trace including its literal final halt. -/\ntheorem prepared_time_le (bits key : List Bool) : preparedTime bits key+1≤preparedBound bits key := by\n  have h:=SemiprimeD1StackOwnerFibreBounds.time_le key ((P.rows bits).map SemiprimeD1FactorScopePairEncoding.pair)\n  unfold preparedTime preparedBound\n  omega\n/-- Whole input-width/query-width polynomial, with neither scope count nor elapsed clock supplied. -/\ndef runBound (bits key : List Bool) : Nat :=10^122*(key.length+1)*(bits.length+1)^30\n/-- All actual source/copy/scan/emission clocks are retained in one explicit bound. -/\ntheorem timeBound_le (bits key : List Bool) (hb : bits≠[]) : timeBound bits key≤runBound bits key := by\n  let K:=key.length+1\n  let W:=(bits.length+1)^30\n  have hK:1≤K:=by dsimp [K];omega\n  have hW:1≤W:=Nat.succ_le_of_lt (Nat.pow_pos (Nat.succ_pos _))\n  have hL:(pairTape bits).length≤10^114*W+1:=pair_bytes bits hb\n  have hF:=SemiprimeD1StackOwnerFibreBounds.time_le key ((P.rows bits).map SemiprimeD1FactorScopePairEncoding.pair)\n  change SemiprimeD1StackOwnerFibreExecution.totalTime key _≤100*K*((pairTape bits).length+1) at hF\n  have hm:=Nat.mul_le_mul_left (100*K) (Nat.add_le_add_right hL 1)\n  have hKW:K≤K*W:=by simpa only [Nat.mul_one] using Nat.mul_le_mul_left K hW\n  have hWK:W≤K*W:=by simpa only [Nat.one_mul] using Nat.mul_le_mul_right W hK\n  unfold timeBound preparedTime SemiprimeD1StackFactorScopePairBounds.runBound runBound\n  change 10^118*W+(5*(pairTape bits).length+SemiprimeD1StackOwnerFibreExecution.totalTime key _+5)+2≤10^122*K*W\n  nlinarith\n/-- Complete binary N plus actually acquired physical key, on the same137-role machine. -/\nnoncomputable def machineFibre (bits key : List Bool) (hb : bits≠[]) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial bits key))\n      (some (SemiprimeD1StackCalls.configuration (done bits key))) (runBound bits key) := by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output Label.main program\n  let h:=source_run bits key hb\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1.trans (timeBound_le bits key hb)⟩\n/-- Prepared actual-machine certificate: source already acquired, never silently initialized. -/\ndef preparedMachineFibre (bits key : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration\n        (⟨some .copy,none,none,afterSource bits key,[]⟩ : C.State Stack Label))\n      (some (SemiprimeD1StackCalls.configuration (done bits key))) (preparedBound bits key) := by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output Label.main program\n  exact ⟨⟨preparedTime bits key+1,prepared_run bits key⟩,prepared_time_le bits key⟩\n/-- Physical initial role widths include both genuine binary input words. -/\ntheorem initial_length (bits key : List Bool) (k : Stack) :\n    ((initial bits key).data k).length≤bits.length+key.length := by\n  have hf (j : F.Stack) : ((F.initial key []).data j).length≤key.length:=by\n    rcases j with j|j <;> cases j <;>\n      simp [SemiprimeD1StackOwnerFibre.initial,SemiprimeD1StackOwnerFibre.data,SemiprimeD1StackAdder.store]\n  cases k with\n  | inl k=>\n    change (P.input bits k).length≤_\n    rw [SemiprimeD1StackFactorScopePairExecution.input_eq]\n    dsimp only\n    split <;> simp\n  | inr k=>cases k with\n    | inl k=>have h:=hf k;change ((F.initial key []).data k).length≤_;omega\n    | inr k=>exact Nat.zero_le _\n/-- Actual successful prefixes cannot continue beyond the proved whole-source halt. -/\ntheorem prefix_fuel_le (bits key : List Bool) (hb : bits≠[]) (fuel : Nat) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits key)=some out) : fuel≤runBound bits key := by\n  obtain ⟨t,ht,he⟩:=source_run bits key hb\n  have hf:fuel≤t:=by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:C.run program 1 (done bits key)=none:=rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans (ht.trans (timeBound_le bits key hb))\n/-- Every source/cache/copy/filter/shadow role and every actual nested return cell. -/\ntheorem prefix_cells (bits key : List Bool) (hb : bits≠[]) (fuel : Nat) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial bits key)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤138*(bits.length+key.length+runBound bits key) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (bits.length+key.length) _ out\n    (initial_length bits key) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤137*(bits.length+key.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(bits.length+key.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits key hb fuel out hr\n  omega\n/-- Identical complete physical inventory for the actual compiled finite machine. -/\ntheorem machine_prefix_cells (bits key : List Bool) (hb : bits≠[]) (fuel : Nat) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits key)))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤138*(bits.length+key.length+runBound bits key) := by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output Label.main program fuel (initial bits key)\n  have hh:=he.trans hr\n  cases hs:C.run program fuel (initial bits key) with\n  | none=>rw [hs] at hh;cases hh\n  | some out=>\n    rw [hs] at hh\n    have hc:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits key hb fuel out hs\n/-- Actual bounded-ordinal factor query widths follow from the original catalogue,\nnot from a caller-supplied count or a binary/unary identification. -/\ntheorem factor_count_le (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<SemiprimeBitArithmetic.bitValue bits) :\n    SemiprimePublicAcquiredExecution.factorCount (SemiprimeBitArithmetic.bitValue bits)≤\n      2000000000000000*(bits.length+1)^5 := by\n  have hb:bits≠[]:=by intro h;rw [h] at hN;exact Nat.lt_irrefl _ hN\n  have hv:=SemiprimeD1StackPortCataloguePolynomial.vertices_le_tape (SemiprimeD1StackPortCatalogueExecution.vertices bits)\n  have hs:=SemiprimeD1StackPortCatalogueBounds.size_le bits hb\n  have he:(SemiprimeD1StackPortCatalogueExecution.vertices bits).length=\n      SemiprimePublicAcquiredExecution.factorCount (SemiprimeBitArithmetic.bitValue bits) := by\n    unfold SemiprimeD1StackPortCatalogueExecution.vertices SemiprimePublicAcquiredExecution.factorCount\n      SemiprimePublicAcquiredExecution.vertexEnumeration\n    rw [SemiprimeD1StackVertexCatalogueTags.digitCount_raw bits hb,\n      SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc]\n  unfold SemiprimeD1StackPortCataloguePolynomial.size at hs\n  rw [he] at hv\n  omega\n/-- Whole actual N+original-factor-key source is polynomial in original binary width. -/\ntheorem original_timeBound (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<SemiprimeBitArithmetic.bitValue bits)\n    (f : Fin (SemiprimePublicAcquiredExecution.factorCount (SemiprimeBitArithmetic.bitValue bits))) :\n    runBound bits (SemiprimeD1FactorScopePairOriginal.key f.val)≤10^140*(bits.length+1)^35 := by\n  have hf:=factor_count_le bits hc hN\n  have hp:1≤(bits.length+1)^5:=Nat.succ_le_of_lt (Nat.pow_pos (Nat.succ_pos _))\n  have hk:(SemiprimeD1FactorScopePairOriginal.key f.val).length+1≤\n      2000000000000001*(bits.length+1)^5:=by\n    simp only [SemiprimeD1FactorScopePairOriginal.key,SemiprimeD1StackUnaryDivmod.unary,List.length_replicate]\n    have hi:=f.isLt\n    omega\n  unfold runBound\n  calc\n    _ ≤ 10^122*(2000000000000001*(bits.length+1)^5)*(bits.length+1)^30 :=\n      Nat.mul_le_mul_right _ (Nat.mul_le_mul_left _ hk)\n    _ = (10^122*2000000000000001)*((bits.length+1)^5*(bits.length+1)^30) :=by ring\n    _ ≤ 10^140*((bits.length+1)^5*(bits.length+1)^30) :=Nat.mul_le_mul_right _ (by norm_num)\n    _ = _ :=by rw [←pow_add]\nend RiemannGaussian.SemiprimeD1StackFactorScopeFibreBounds\n","RiemannGaussian.SemiprimeD1StackFullFactorCatalogueBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFullFactorCatalogueCapacities\n/-! # Whole actual all-factor source clock with an original scope exponent\nEvery row is charged at its real current history size. The history invariant\nis additive in original factor count, giving a fixed polynomial times 2^(19 B).\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFullFactorCatalogueBounds\nopen SemiprimeD1StackFullFactorCatalogue SemiprimeD1StackFullFactorCatalogueRows\nopen SemiprimeD1StackFullFactorCatalogueLoop SemiprimeD1StackFullFactorCatalogueExecution\nopen SemiprimeD1StackFullFactorCatalogueCapacities SemiprimeD1StackFullFactorCatalogueHistoryBounds\nopen SemiprimeD1BooleanFactorCatalogueIndices (vertex scopeWords key indices)\nopen SemiprimeD1BooleanFactorCatalogueIndicesBounds (cons_values)\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (factorCount)\n/-- Actual whole-history allowance, summing zero-history row byte bounds once per factor. -/\ndef historyAllowance (bits:List Bool) :Nat:=factorAllowance bits.length*rowAllowance bits\n/-- A fixed width polynomial for an entire row, including the next retained-source query. -/\ndef rowPolynomial (n:Nat) :Nat:=\n  10^130*(polynomial n+factorAllowance n*polynomial n+2)^18+2*polynomial n\n/-- Fixed width polynomial for setup, all rows, full reversal and halt. -/\ndef runPolynomial (n:Nat) :Nat:=\n  polynomial n+factorAllowance n*rowPolynomial n+2*factorAllowance n*polynomial n+4\n/-- Whole original N-only clock; all18 table families use the genuine common scope bound. -/\ndef runBound (bits:List Bool) :Nat:=runPolynomial bits.length*2^(19*R.arityCapacity bits)\n/-- The accumulated-history exponent joins the eighteenth-power input cap once. -/\ntheorem exponent_join (B:Nat) :((2:Nat)^B)^18*2^B=2^(19*B):=by\n  rw [←pow_mul,←pow_add]\n  congr 1\n  omega\n/-- The original table exponent is below the final caller-history exponent. -/\ntheorem exponent_le (B:Nat) :(2:Nat)^B ≤ 2^(19*B):=\n  Nat.pow_le_pow_right (by decide) (by omega)\n/-- Every real dispatcher input, including actual accumulated history and output sentinel, is charged. -/\ntheorem capacity_le (bits:List Bool) (hist:List Bool) (hh:hist.length ≤ historyAllowance bits) :\n    R.capacity bits hist [false]+1 ≤\n      (polynomial bits.length+factorAllowance bits.length*polynomial bits.length+2)*2^(R.arityCapacity bits):=by\n  have hb:=base_le bits.length\n  have he:1 ≤ (2:Nat)^(R.arityCapacity bits):=Nat.pow_pos (by decide)\n  have h0:=Nat.mul_le_mul_left (polynomial bits.length) he\n  have h2:=Nat.mul_le_mul_left 2 he\n  unfold historyAllowance rowAllowance at hh\n  unfold R.capacity R.baseCapacity\n  simp only [List.length_singleton]\n  nlinarith only [hb,hh,h0,h2]\n/-- Same actual full row timeBound at the current history size; no repeated-growth clock recurrence. -/\ntheorem dispatcher_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (factorCount (bitValue bits))) (hist:List Bool) (hh:hist.length ≤ historyAllowance bits) :\n    DS.timeBound (DR.originalCode (vertex (bitValue bits) f)) (DR.rawFields bits (vertex (bitValue bits) f))\n      (scopeWords bits f.val) hist [false] ≤\n        (10^130*(polynomial bits.length+factorAllowance bits.length*polynomial bits.length+2)^18)*\n          2^(19*R.arityCapacity bits):=by\n  have h:=R.timeBound_original bits hc hN f hist [false]\n  have hp:=Nat.pow_le_pow_left (capacity_le bits hist hh) 18\n  rw [mul_pow] at hp\n  have hm:=Nat.mul_le_mul_left (10^130) (Nat.mul_le_mul_right (2^(R.arityCapacity bits)) hp)\n  rw [Nat.mul_assoc,exponent_join] at hm\n  exact h.trans (by simpa only [Nat.mul_assoc] using hm)\n/-- Parsing, real full component, physical cleanup and EOF fit the same per-row width polynomial. -/\ntheorem row_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (f:Fin (factorCount (bitValue bits))) (hist:List Bool) (hh:hist.length ≤ historyAllowance bits) :\n    rowBudget bits f.val f hist [false]+1+polynomial bits.length ≤\n      rowPolynomial bits.length*2^(19*R.arityCapacity bits):=by\n  have ht:=dispatcher_le bits hc hN f hist hh\n  have hcl:=cleanup_le bits hc hN f\n  have he:1 ≤ (2:Nat)^(19*R.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hp:=Nat.mul_le_mul_left (2*polynomial bits.length) he\n  unfold rowBudget rowPolynomial\n  nlinarith only [ht,hcl,hp]\n/-- Every current history and every not-yet-emitted row fits one invariant total byte allowance. -/\ntheorem loop_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (n:Nat) (fs:List (Fin (factorCount (bitValue bits))))\n    (hseq:fs.map Fin.val=List.range' n fs.length) (hist:List Bool)\n    (hh:hist.length+fs.length*rowAllowance bits ≤ historyAllowance bits) :\n    loopBudget bits n fs hist [false] ≤ fs.length*(rowPolynomial bits.length*2^(19*R.arityCapacity bits)):=by\n  induction fs generalizing n hist with\n  | nil=>simp only [loopBudget,List.length_nil,Nat.zero_mul,Nat.le_refl]\n  | cons f fs ih=>\n    have horder:=cons_values (bitValue bits) n f fs hseq\n    have hhist:hist.length ≤ historyAllowance bits:=by omega\n    have hr:=row_le bits hc hN f hist hhist\n    rw [horder.1] at hr\n    have hhnext:(afterRow bits n f hist [false]).length+fs.length*rowAllowance bits ≤ historyAllowance bits:=by\n      have hi:=history_increment bits hc hN f hist [false]\n      have hc0:=row_cap_le bits hc hN f\n      rw [horder.1] at hi\n      simp only [List.length_cons] at hh\n      nlinarith only [hi,hc0,hh]\n    cases fs with\n    | nil=>\n      simp only [loopBudget,List.length_cons,List.length_nil,ite_true,Nat.add_zero,Nat.zero_add,Nat.one_mul]\n      omega\n    | cons g gs=>\n      have hg:=cons_values (bitValue bits) (n+1) g gs horder.2\n      have hq:=query_le bits hc hN g\n      rw [hg.1] at hq\n      have hi:=ih (n+1) horder.2 (afterRow bits n f hist [false]) hhnext\n      change rowBudget bits n f hist [false]+1+\n        (SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key (n+1))+2+\n          loopBudget bits (n+1) (g::gs) (afterRow bits n f hist [false]) [false]) ≤\n        ((g::gs).length+1)*(rowPolynomial bits.length*2^(19*R.arityCapacity bits))\n      nlinarith only [hr,hq,hi]\n/-- Actual complete output history uses at most one paid row allowance per original factor. -/\ntheorem history_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    (afterRows bits 0 (indices (bitValue bits)) [] [false]).length ≤ historyAllowance bits:=by\n  have h:=history_length_le bits hc hN 0 (indices (bitValue bits)) (indices_sequence (bitValue bits)) [] [false]\n  have hs:((indices (bitValue bits)).map (rowCap bits)).sum ≤\n      (indices (bitValue bits)).length*rowAllowance bits:=by\n    induction indices (bitValue bits) with\n    | nil=>simp\n    | cons f fs ih=>\n      have hr:=row_cap_le bits hc hN f\n      simp only [List.map_cons,List.sum_cons,List.length_cons]\n      nlinarith only [hr,ih]\n  have hf:=factor_count_le bits hc hN\n  rw [indices_length] at hs\n  have hm:=Nat.mul_le_mul_right (rowAllowance bits) hf\n  unfold historyAllowance\n  simp only [List.length_nil,Nat.add_zero] at h\n  omega\n/-- Whole SAME N-only acquisition, including setup, every acquired row/query, reversal and halt. -/\ntheorem timeBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    timeBound bits ≤ runBound bits:=by\n  have hf:=factor_count_le bits hc hN\n  have hi:([]:List Bool).length+(indices (bitValue bits)).length*rowAllowance bits ≤ historyAllowance bits:=by\n    rw [indices_length]\n    simpa only [List.length_nil,Nat.zero_add,historyAllowance] using Nat.mul_le_mul_right (rowAllowance bits) hf\n  have hl:=loop_le bits hc hN 0 (indices (bitValue bits)) (indices_sequence (bitValue bits)) [] hi\n  rw [indices_length] at hl\n  have hloop:=Nat.mul_le_mul_right (rowPolynomial bits.length*2^(19*R.arityCapacity bits)) hf\n  have hh:=history_le bits hc hN\n  have hs:=setup_le bits\n  have hex:=exponent_le (R.arityCapacity bits)\n  have hhist:=Nat.mul_le_mul_left (factorAllowance bits.length*polynomial bits.length) hex\n  have he:1 ≤ (2:Nat)^(19*R.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hsetup:=Nat.mul_le_mul_left (polynomial bits.length+4) he\n  unfold historyAllowance rowAllowance at hh\n  unfold timeBound runBound runPolynomial\n  nlinarith only [hl,hloop,hh,hs,hhist,hsetup]\n/-- The complete actual fixed1454-role source now has one original-width fixed-rate bound. -/\ntheorem source_run_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t ≤ runBound bits,C.run program t (initial bits)=some (done bits):=by\n  obtain ⟨t,ht,hr⟩:=source_run bits hc hN\n  exact ⟨t,ht.trans (timeBound_le bits hc hN),hr⟩\nend RiemannGaussian.SemiprimeD1StackFullFactorCatalogueBounds\n","RiemannGaussian.SemiprimeD1StackFullFactorCatalogueLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFullFactorCatalogueFinish\nimport RiemannGaussian.SemiprimeD1BooleanFactorCatalogueIndices\n/-! # Actual original-order ALL-factor sweep with full branch clocks and history -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 3000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 1000000\nnamespace RiemannGaussian.SemiprimeD1StackFullFactorCatalogueLoop\nopen SemiprimeD1StackFullFactorCatalogue SemiprimeD1StackFullFactorCatalogueView\nopen SemiprimeD1StackFullFactorCatalogueSource SemiprimeD1StackFullFactorCatalogueRows\nopen SemiprimeD1StackFullFactorCatalogueFields SemiprimeD1StackFullFactorCatalogueCleanup\nopen SemiprimeD1StackProcedureFragments (Runs)\nopen SemiprimeD1BooleanFactorCatalogueIndices (key scopeWords indices vertex descriptorTape)\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (factorCount)\n/-- Actual remaining descriptor queue, retaining every other acquired catalogue word. -/\ndef catalogue (bits:List Bool) (fs:List (Fin (factorCount (bitValue bits)))) :V.Stack→List Bool:=\n  Function.update (VS.result bits) catalogueOutput (descriptorTape (bitValue bits) fs)\n/-- Exact reached shared-source, five empty raw caches and caller accumulation state. -/\ndef loopData (bits:List Bool) (n:Nat) (fs:List (Fin (factorCount (bitValue bits))))\n    (hist out:List Bool) :Stack→List Bool:=\n  data (FS.result bits (key n)) (catalogue bits fs) (fun _=>[]) hist out\n/-- After physical drains and key advancement, every filter operand except the retained key is empty. -/\ndef nextData (bits:List Bool) (n:Nat) (fs:List (Fin (factorCount (bitValue bits))))\n    (hist out:List Bool) :Stack→List Bool:=\n  data (SemiprimeD1StackFactorScopeFibre.afterSource bits (key n)) (catalogue bits fs) (fun _=>[]) hist out\n/-- Proof-side actual appended row history; no history/table getter exists in control. -/\ndef afterRow (bits:List Bool) (n:Nat) (f:Fin (factorCount (bitValue bits))) (hist out:List Bool) :List Bool:=\n  DS.nextHistory (DR.originalCode (vertex (bitValue bits) f)) (DR.rawFields bits (vertex (bitValue bits) f))\n    (scopeWords bits n) hist out\n/-- Actual chronological accumulator after all original factors, including every arithmetic tag. -/\ndef afterRows (bits:List Bool) :Nat→List (Fin (factorCount (bitValue bits)))→List Bool→List Bool→List Bool\n  | _,[],hist,_=>hist\n  | n,f::fs,hist,out=>afterRows bits (n+1) fs (afterRow bits n f hist out) out\n/-- SAME actual full component clock plus five physical parses/drains, full scope drain and key push. -/\ndef rowBudget (bits:List Bool) (n:Nat) (f:Fin (factorCount (bitValue bits))) (hist out:List Bool) :Nat:=\n  DS.timeBound (DR.originalCode (vertex (bitValue bits) f)) (DR.rawFields bits (vertex (bitValue bits) f))\n    (scopeWords bits n) hist out+9*mass (E.vertex (vertex (bitValue bits) f))+\n    (SemiprimeD1TensorTapeCodec.vectorBits (scopeWords bits n)).length+49\n/-- Whole real branch-clock sum: accumulated history is charged at every actual full source call. -/\ndef loopBudget (bits:List Bool) :Nat→List (Fin (factorCount (bitValue bits)))→List Bool→List Bool→Nat\n  | _,[],_,_=>0\n  | n,f::fs,hist,out=>rowBudget bits n f hist out+1+\n      if fs=[] then 0 else SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key (n+1))+2+\n        loopBudget bits (n+1) fs (afterRow bits n f hist out) out\n/-- Acquired original descriptor reader contains exactly the reached physical suffix. -/\ntheorem catalogue_reader (bits:List Bool) (fs:List (Fin (factorCount (bitValue bits)))) :\n    catalogue bits fs catalogueOutput=descriptorTape (bitValue bits) fs:=Function.update_self _ _ _\n/-- Five actual field reads consume exactly one complete original descriptor. -/\ntheorem catalogue_tail (bits:List Bool) (f:Fin (factorCount (bitValue bits)))\n    (fs:List (Fin (factorCount (bitValue bits)))) :\n    Function.update (catalogue bits (f::fs)) catalogueOutput (descriptorTape (bitValue bits) fs)=catalogue bits fs:=by\n  unfold catalogue;rw [Function.update_idem]\n/-- The real five-frame parser consumes exactly the original vertex descriptor encoding. -/\ntheorem descriptor_record {r t digits:Nat} (v:SemiprimeMacroGraph.SubdividedVertex r t digits) (tail:List Bool) :\n    SemiprimeD1VertexCatalogueEncoding.vertex v tail=suffix (E.vertex v) 0 tail:=by\n  rw [←SemiprimeD1EdgeCatalogueEncoding.record_vertex v tail]\n  rfl\n/-- Every constructor, including empty tag zero, has a nonempty actual five-frame record. -/\ntheorem descriptor_head {r t digits:Nat} (v:SemiprimeMacroGraph.SubdividedVertex r t digits) (tail:List Bool) :\n    ∃head rest,SemiprimeD1VertexCatalogueEncoding.vertex v tail=head::rest:=by\n  rw [descriptor_record]\n  change ∃head rest,SemiprimeSourceHistogramKeyBits.frame (E.vertex v 0) _=head::rest\n  cases E.vertex v 0 with\n  | nil=>exact ⟨false,_,rfl⟩\n  | cons b bs=>exact ⟨true,_,rfl⟩\n/-- Original N remains physically retained for every repeated real factor query. -/\ntheorem retained_N_key (bits keyBytes:List Bool) :FS.result bits keyBytes F.originalInput=bits:=rfl\n/-- One COMPLETE actual row: real EOF peek, five field parsers, actual18-tag/full table source,\nall original field/scope drains and one unary factor-key push. -/\ntheorem row_step (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (n:Nat) (f:Fin (factorCount (bitValue bits))) (fs:List (Fin (factorCount (bitValue bits))))\n    (hist out:List Bool) :\n    ∃t≤rowBudget bits n f hist out,Runs program t (.local .loop) (loopData bits n (f::fs) hist out)\n      (.local .next) (nextData bits (n+1) fs (afterRow bits n f hist out) out):=by\n  let v:=vertex (bitValue bits) f\n  let histNext:=afterRow bits n f hist out\n  obtain ⟨b,rest,he⟩:=descriptor_head v (descriptorTape (bitValue bits) fs)\n  have h0:Runs program 1 (.local .loop) (loopData bits n (f::fs) hist out)\n      (.local (.field 0)) (loopData bits n (f::fs) hist out):=by\n    apply SemiprimeD1StackPhysicalLoops.peek_nonempty program (.local .loop) (.local .reverse) (.local (.field 0))\n      descriptorReader rfl _ b rest\n    change catalogue bits (f::fs) catalogueOutput=b::rest\n    rw [catalogue_reader];exact he\n  have hr:catalogue bits (f::fs) catalogueOutput=suffix (E.vertex v) 0 (descriptorTape (bitValue bits) fs):=by\n    rw [catalogue_reader]\n    exact descriptor_record v _\n  have h1:=parse_run (FS.result bits (key n)) (catalogue bits (f::fs)) (E.vertex v)\n    (descriptorTape (bitValue bits) fs) hist out hr\n  rw [catalogue_tail] at h1\n  obtain ⟨t,ht,h2⟩:=descriptor_call bits hc hN v (FS.result bits (key n)) (catalogue bits fs) hist out\n    (scopeWords bits n) (retained_N_key bits (key n)) (SemiprimeD1BooleanFactorCatalogueIndices.source_output bits n)\n  have h3:=clear_fields (FS.result bits (key n)) (catalogue bits fs) (E.vertex v) histNext out\n  have h4:=clear_scope (FS.result bits (key n)) (catalogue bits fs) histNext out\n  rw [result_clear] at h4\n  have h5:=advance_run (SemiprimeD1StackFactorScopeFibre.afterSource bits (key n)) (catalogue bits fs) histNext out\n  change Runs program 1 (.local .advance) _ (.local .next)\n    (data (Function.update (SemiprimeD1StackFactorScopeFibre.afterSource bits (key n)) F.query (true::key n))\n      (catalogue bits fs) (fun _=>[]) histNext out) at h5\n  rw [afterSource_key,←SemiprimeD1BooleanFactorCatalogueIndices.key_succ] at h5\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans (h4.trans h5))))\n  refine ⟨1+((8*mass (E.vertex v)+40)+((t+1)+((mass (E.vertex v)+5)+\n    (((FS.result bits (key n) F.output).length+1)+1)))),?_,h⟩\n  unfold rowBudget\n  rw [SemiprimeD1BooleanFactorCatalogueIndices.source_output]\n  dsimp only [v] at ht ⊢\n  omega\n/-- Entire actual descriptor sweep, retaining one acquired pair catalogue and all full branch clocks. -/\ntheorem rows_run (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (n:Nat) (fs:List (Fin (factorCount (bitValue bits))))\n    (hseq:fs.map Fin.val=List.range' n fs.length) (hne:fs≠[]) (hist out:List Bool) :\n    ∃t≤loopBudget bits n fs hist out,Runs program t (.local .loop) (loopData bits n fs hist out)\n      (.local .reverse) (nextData bits (n+fs.length) [] (afterRows bits n fs hist out) out):=by\n  induction fs generalizing n hist with\n  | nil=>exact (hne rfl).elim\n  | cons f fs ih=>\n    have horder:f.val=n ∧ fs.map Fin.val=List.range' (n+1) fs.length:=by\n      simpa only [List.map_cons,List.length_cons,List.range'_succ,List.cons.injEq] using hseq\n    obtain ⟨t,ht,h0⟩:=row_step bits hc hN n f fs hist out\n    let histNext:=afterRow bits n f hist out\n    cases fs with\n    | nil=>\n      have h1:Runs program 1 (.local .next) (nextData bits (n+1) [] histNext out)\n          (.local .reverse) (nextData bits (n+1) [] histNext out):=by\n        apply SemiprimeD1StackPhysicalLoops.peek_empty program (.local .next) (.local .reverse)\n          (.local .query) (.local .query) descriptorReader rfl _\n        exact catalogue_reader bits []\n      refine ⟨t+1,?_,h0.trans h1⟩\n      change t+1≤rowBudget bits n f hist out+1+0;omega\n    | cons g gs=>\n      obtain ⟨b,rest,he⟩:=descriptor_head (vertex (bitValue bits) g) (descriptorTape (bitValue bits) gs)\n      have h1:Runs program 1 (.local .next) (nextData bits (n+1) (g::gs) histNext out)\n          (.local .query) (nextData bits (n+1) (g::gs) histNext out):=by\n        apply SemiprimeD1StackPhysicalLoops.peek_nonempty program (.local .next) (.local .reverse) (.local .query)\n          descriptorReader rfl _ b rest\n        change catalogue bits (g::gs) catalogueOutput=b::rest\n        rw [catalogue_reader];exact he\n      have h2:=query_call bits (key (n+1)) (catalogue bits (g::gs)) histNext out\n      obtain ⟨u,hu,h3⟩:=ih (n+1) horder.2 (by simp) histNext\n      have hi:n+1+(g::gs).length=n+(f::g::gs).length:=by simp only [List.length_cons];omega\n      rw [hi] at h3\n      have h:=h0.trans (h1.trans (h2.trans h3))\n      refine ⟨t+(1+((SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key (n+1))+2)+u)),?_,h⟩\n      change t+(1+(SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key (n+1))+2+u))≤\n        rowBudget bits n f hist out+1+(SemiprimeD1StackFactorScopeFibreExecution.preparedTime bits (key (n+1))+2+\n          loopBudget bits (n+1) (g::gs) histNext out)\n      omega\nend RiemannGaussian.SemiprimeD1StackFullFactorCatalogueLoop\n","RiemannGaussian.SemiprimeD1StackFullFactorCatalogueResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackFullFactorCatalogueBounds\n/-! # Fixed growth and all compiled prefix cells for actual all-factor acquisition -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackFullFactorCatalogueResources\nopen SemiprimeD1StackFullFactorCatalogue SemiprimeD1StackFullFactorCatalogueExecution\nopen SemiprimeD1StackFullFactorCatalogueBounds SemiprimeD1StackFullFactorCatalogueCapacities\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeReportPolynomialGrowth (Bound constant_bound identity_bound add_bound mul_bound pow_bound)\n/-- Fixed natural coefficient and degree exist for the actual explicit width polynomial. -/\ntheorem polynomial_monomial :∃A d:Nat,∀n,runPolynomial n ≤ A*(n+1)^d:=by\n  have hp:Bound polynomial:=⟨coefficient,108,fun _=>Nat.le_refl _⟩\n  have hf:Bound factorAllowance:=mul_bound (constant_bound 12800) identity_bound\n  have ha:Bound (fun n=>polynomial n+factorAllowance n*polynomial n+2):=\n    add_bound (add_bound hp (mul_bound hf hp)) (constant_bound 2)\n  have hr:Bound rowPolynomial:=add_bound\n    (mul_bound (constant_bound (10^130)) (pow_bound ha 18))\n    (mul_bound (constant_bound 2) hp)\n  exact add_bound (add_bound (add_bound hp (mul_bound hf hr))\n    (mul_bound (mul_bound (constant_bound 2) hf) hp)) (constant_bound 4)\n/-- Complete genuine1454-role machine certificate under its own original-family rate bound. -/\nnoncomputable def machineBounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (runBound bits):=by\n  rw [SemiprimeD1StackFullFactorCatalogueFinish.initial_configuration]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (.local .main) program\n  have h:=source_run_bounded bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Every original source prefix counts all1454 data roles and every actual return cell. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (finish:C.State Stack Label) (hr:C.run program fuel (initial bits)=some finish) :\n    (∑k:Stack,(finish.data k).length)+finish.frames.length ≤ 1455*(bits.length+runBound bits):=by\n  exact (SemiprimeD1StackFullFactorCatalogueExecution.prefix_cells bits hc hN fuel finish hr).trans\n    (Nat.mul_le_mul_left 1455 (Nat.add_le_add_left (timeBound_le bits hc hN) bits.length))\n/-- Same own clock bounds every compiled prefix, including the physical return stack. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 1455*(bits.length+runBound bits):=by\n  exact (SemiprimeD1StackFullFactorCatalogueExecution.machine_prefix_cells bits hc hN fuel cfg hr).trans\n    (Nat.mul_le_mul_left 1455 (Nat.add_le_add_left (timeBound_le bits hc hN) bits.length))\n/-- Fixed rate witnesses apply to the SAME actual source trace for the entire original family. -/\ntheorem source_run_monomial :∃A d:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (_hN:0<bitValue bits),\n    ∃t ≤ A*(bits.length+1)^d*2^(19*R.arityCapacity bits),\n      C.run program t (initial bits)=some (done bits):=by\n  obtain ⟨A,d,ha⟩:=polynomial_monomial\n  refine ⟨A,d,?_⟩\n  intro bits hc hN\n  obtain ⟨t,ht,hr⟩:=source_run_bounded bits hc hN\n  exact ⟨t,ht.trans (Nat.mul_le_mul_right _ (ha bits.length)),hr⟩\n/-- Fixed polynomial storage witnesses cover every compiled prefix of the same original source. -/\ntheorem machine_prefix_monomial :∃A d:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (_hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg),\n    (fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg →\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      A*(bits.length+1)^d*2^(19*R.arityCapacity bits):=by\n  have hp:Bound runPolynomial:=polynomial_monomial\n  have hs:Bound (fun n=>1455*(n+runPolynomial n)):=\n    mul_bound (constant_bound 1455) (add_bound identity_bound hp)\n  obtain ⟨A,d,ha⟩:=hs\n  refine ⟨A,d,?_⟩\n  intro bits hc hN fuel cfg hr\n  have h:=machine_prefix_cells bits hc hN fuel cfg hr\n  have he:1 ≤ (2:Nat)^(19*R.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hn:=Nat.mul_le_mul_left bits.length he\n  have hpoly:=Nat.mul_le_mul_right (2^(19*R.arityCapacity bits)) (ha bits.length)\n  unfold runBound at h\n  nlinarith only [h,hn,hpoly]\n/-- The exponent is the established original three-quarter-power cap, never a claimed square-root cap. -/\ntheorem scope_exponent_fourth (bits:List Bool) (h:0<bits.length) :\n    (R.arityCapacity bits)^4 ≤ 512^4*bits.length^3:=\n  SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity_fourth bits h\n/-- Each actual compiled transition uses at most four fundamental commands. -/\ntheorem compile_depth (pc:Label) :SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤ 4:=\n  SemiprimeD1StackCalls.compile_depth (.local .main:Label) (program pc)\nend RiemannGaussian.SemiprimeD1StackFullFactorCatalogueResources\n","RiemannGaussian.SemiprimeD1StackInputDescriptorRecordExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackInputDescriptorRecord\nimport RiemannGaussian.SemiprimeD1StackDescriptorRecordExecution\n/-! # Concrete physical input descriptor initialization and entire old input row -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackInputDescriptorRecordExecution\nopen SemiprimeD1StackInputDescriptorRecord\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace T\nexport SemiprimeD1StackPublicInputTableTrace (answer budget actual_trace)\nend T\n/-- Six physical source fields equal their literal coordinate projection;\nthis is proof-side extensionality, never an executed metadata supplier. -/\ntheorem fields_eta (inputFields : Fin 6→List Bool) :\n    fields (inputFields 0) (inputFields 1) (inputFields 2) (inputFields 3) (inputFields 4) (inputFields 5)=inputFields := by\n  funext i;fin_cases i <;> rfl\n/-- Arbitrary actual acquired fields initialize EXACTLY the frozen original\ninput template: only binary N and the original coord1 input-index markers. -/\ntheorem selected_fields (inputFields : Fin 6→List Bool) :\n    SemiprimeD1StackDescriptorRecord.selected sourceMap inputFields=I.inputTemplate (inputFields 0) (inputFields 3) := by\n  have h:=selected_template (inputFields 0) (inputFields 1) (inputFields 2) (inputFields 3) (inputFields 4) (inputFields 5)\n  rw [fields_eta] at h\n  exact h\n/-- Whole139-role result after real load, compilation, scope conversion and logging. -/\ndef done (inputFields : Fin 6→List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    SemiprimeD1StackCalls.State Stack Label :=\n  SemiprimeD1StackDescriptorRecord.done I.static sourceMap inputFields words\n    (T.answer (inputFields 0) (inputFields 3)) hist out\n/-- Complete actual source clock, including the arbitrary dirty template. -/\ndef timeBound (oldTemplate : Checker→List Bool) (inputFields : Fin 6→List Bool) (words : List (List Bool))\n    (hist out : List Bool) : Nat :=\n  SemiprimeD1StackDescriptorRecordExecution.timeBound I.static sourceMap oldTemplate inputFields words\n    (T.answer (inputFields 0) (inputFields 3)) (T.budget (inputFields 0) (inputFields 3)) hist out\n/-- The real52-role template loader's complete trace; all original descriptor\nfields and every non-template component role are retained exactly. -/\ntheorem template_run (oldTemplate : Checker→List Bool) (inputFields : Fin 6→List Bool) (bank hist out : List Bool) :\n    ∃t≤SemiprimeD1StackDescriptorRecordExecution.prepareBound I.static oldTemplate inputFields bank hist out,\n      SemiprimeD1StackProcedureTrace.Runs program t (.inl .start) (initial oldTemplate inputFields bank hist out).data\n        (.inl .record) (SemiprimeD1StackDescriptorRecord.data\n          (SemiprimeD1StackPublicInputRecord.initial (inputFields 0) (inputFields 3) bank hist out).data inputFields []) := by\n  have h:=SemiprimeD1StackDescriptorRecordExecution.prepare_call I.static sourceMap oldTemplate inputFields bank hist out\n  simpa only [SemiprimeD1StackDescriptorRecord.afterLoad,selected_fields,\n    SemiprimeD1StackInputDescriptorRecord.program,SemiprimeD1StackInputDescriptorRecord.initial,\n    SemiprimeD1StackPublicInputRecord.initial] using h\n/-- Fully concrete actual source: no checker/template/count/table/verdict\nsupplier premise remains. Scope and all six source words are already acquired. -/\ntheorem source_run (oldTemplate : Checker→List Bool) (inputFields : Fin 6→List Bool)\n    (hb : inputFields 0≠[]) (words : List (List Bool)) (hist out : List Bool) :\n    ∃t≤timeBound oldTemplate inputFields words hist out,SemiprimeD1StackCalls.run program t\n      (initial oldTemplate inputFields (vectorBits words) hist out)=some (done inputFields words hist out) := by\n  apply SemiprimeD1StackDescriptorRecordExecution.source_run I.static sourceMap oldTemplate inputFields\n  · rw [selected_fields];rfl\n  · rw [selected_fields]\n    exact T.actual_trace (inputFields 0) (inputFields 3) hb\n/-- Genuine finite-machine trace with the same full actual own source clock. -/\nnoncomputable def recordInTime (oldTemplate : Checker→List Bool) (inputFields : Fin 6→List Bool)\n    (hb : inputFields 0≠[]) (words : List (List Bool)) (hist out : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial oldTemplate inputFields (vectorBits words) hist out))\n      (some (SemiprimeD1StackCalls.configuration (done inputFields words hist out)))\n      (timeBound oldTemplate inputFields words hist out) := by\n  apply SemiprimeD1StackDescriptorRecordExecution.recordInTime I.static sourceMap oldTemplate inputFields\n  · rw [selected_fields];rfl\n  · rw [selected_fields]\n    exact T.actual_trace (inputFields 0) (inputFields 3) hb\n/-- Every actual component data cell agrees with the frozen concrete132-role\ninput-record result, after physical descriptor initialization rather than advice. -/\ntheorem component_done (inputFields : Fin 6→List Bool) (words : List (List Bool)) (hist out : List Bool)\n    (k : SemiprimeD1StackPublicInputRecord.Stack) :\n    (done inputFields words hist out).data (D.recordStack k)=\n      (SemiprimeD1StackPublicInputRecordExecution.done (inputFields 0) (inputFields 3) words hist out).data k := by\n  unfold done SemiprimeD1StackDescriptorRecord.done\n  rw [selected_fields]\n  rfl\n/-- All six actual source words are retained byte for byte, including tag and unused coordinates. -/\ntheorem retained_source (inputFields : Fin 6→List Bool) (words : List (List Bool)) (hist out : List Bool) (i : Fin 6) :\n    (done inputFields words hist out).data (D.source i)=inputFields i := rfl\n/-- The actual loader scratch is physically empty at completion. -/\ntheorem scratch_clear (inputFields : Fin 6→List Bool) (words : List (List Bool)) (hist out : List Bool) :\n    (done inputFields words hist out).data D.scratch=[] := rfl\nend RiemannGaussian.SemiprimeD1StackInputDescriptorRecordExecution\n","RiemannGaussian.SemiprimeD1StackJetFoldOperators":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetFoldPrimitives\nimport RiemannGaussian.SemiprimeD1StackJetFoldProjection\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Real frozen multiplication, unit and addition calls of the same fold\nEvery component execution is the concrete immutable source trace, with actual\nshared operand/cache words and actual physical return transitions.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackJetFoldOperators\nopen SemiprimeD1StackJetFold SemiprimeD1StackJetFoldState SemiprimeD1StackJetFoldProjection\nopen SemiprimeD1StackJetFoldWords SemiprimeD1StackProcedureTrace\nopen SemiprimeD1JetAxes (Context)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackUnaryDivmod (unary)\nlocal notation \"ctl\" => Label.local\n/-- Actual physical multiplier input inventory, used only to state its proved source allowance. -/\ndef mulBound (ctx:Context) (v:Values):Nat:=\n  2000000*(SemiprimeD1StackJetMulBounds.inputSize ctx (cache v)+1)^6+1\n/-- One actual whole dense multiplication, including every point calculation and the real caller return. -/\ntheorem multiply_call (ctx:Context) (hp:ctx.Positive) (v:Values) (a b:Jet)\n    (ha:v .left=jetTape a) (hb:v .product=jetTape b)\n    (hx:v .axes=vectorBits (ctx.axes.map unary)) (hw:(v .width).length=ctx.precision)\n    (hr:v .rank=unary ctx.rank) (ho:v .result=[]):\n    ∃time ≤ mulBound ctx v,Runs program time (ctl .multiply) (data v) (ctl .clearLeft)\n      (data (Function.update v .result (jetTape (SemiprimeD1JetRingBits.mul ctx a b).words))):=by\n  obtain ⟨time,ht,hrun⟩:=SemiprimeD1StackJetMulBounds.source_run_polynomial ctx hp (cache v) a b ha hb hx hw hr\n  let source:=M.initial (v .left) (v .product) (v .axes) (v .width) (v .rank)\n  let out:SemiprimeD1StackCalls.State M.Stack M.Label:=⟨none,none,none,\n    SemiprimeD1StackJetMulExecution.data (cache v) [] [] (jetTape (SemiprimeD1JetRingBits.mul ctx a b).words),[]⟩\n  have hin:SemiprimeD1StackMultiplierLink.DataRel main (data v) source.data (data v):=by\n    constructor\n    · intro k\n      rw [data_main,ho]\n      exact (congrFun (SemiprimeD1StackJetMulExecution.initial_data (cache v)) k).symm\n    · intro k _;rfl\n  refine ⟨time+1,by unfold mulBound;omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program main Label.multiply Sum.inl_injective\n    M.program .start (fun _=>rfl) (ctl .multiply) (ctl .clearLeft) rfl time source out _ _\n    rfl rfl rfl rfl hrun hin\n  have h:=SemiprimeD1StackMultiplierLink.data_update main Sum.inl_injective (data v) source.data (data v) hin M.output\n    (jetTape (SemiprimeD1JetRingBits.mul ctx a b).words)\n  have he:Function.update source.data M.output (jetTape (SemiprimeD1JetRingBits.mul ctx a b).words)=out.data:=by\n    change Function.update (M.initial (cache v).a (cache v).b (cache v).axes (cache v).width (cache v).rank).data\n      M.output (jetTape (SemiprimeD1JetRingBits.mul ctx a b).words)=_\n    rw [SemiprimeD1StackJetMulExecution.initial_data,SemiprimeD1StackJetMulExecution.data_output_update]\n  rw [he] at h\n  change SemiprimeD1StackMultiplierLink.DataRel main (data v) out.data\n    (Function.update (data v) (address .result) (jetTape (SemiprimeD1JetRingBits.mul ctx a b).words)) at h\n  rw [←data_update] at h\n  exact h\n/-- Updating the real unit output preserves all acquired cache and zero private roles. -/\ntheorem unit_output_update (width rank out:List Bool):\n    Function.update (SemiprimeD1StackJetUnit.bank width rank [] [] []) U.output out=\n      SemiprimeD1StackJetUnit.bank width rank [] [] out:=by\n  funext k;fin_cases k <;> rfl\n/-- One real unit call computes the native empty product from the physically acquired counters. -/\ntheorem unit_call (ctx:Context) (v:Values) (hw:(v .width).length=ctx.precision)\n    (hr:(v .rank).length=ctx.rank) (hb:v .product=[]):\n    Runs program (SemiprimeD1StackJetUnitExecution.totalTime (v .width) (v .rank)+1)\n      (ctl .unit) (data v) (ctl .returning)\n      (data (Function.update v .product (jetTape (SemiprimeD1JetAffineCoefficient.one ctx).words))):=by\n  let source:=SemiprimeD1StackJetUnit.initial (v .width) (v .rank)\n  let out:SemiprimeD1StackCalls.State U.Stack U.Label:=⟨none,none,none,\n    SemiprimeD1StackJetUnit.bank (v .width) (v .rank) [] [] (jetTape (SemiprimeD1JetAffineCoefficient.one ctx).words),[]⟩\n  have hin:SemiprimeD1StackMultiplierLink.DataRel unitStack (data v) source.data (data v):=by\n    constructor\n    · intro k;rw [data_unit,hb];rfl\n    · intro k _;rfl\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program unitStack Label.unit unit_injective\n    U.program .seed0 (fun _=>rfl) (ctl .unit) (ctl .returning) rfl _ source out _ _\n    rfl rfl rfl rfl (SemiprimeD1StackJetUnitExecution.source_run ctx _ _ hw hr) hin\n  have h:=SemiprimeD1StackMultiplierLink.data_update unitStack unit_injective (data v) source.data (data v) hin U.output\n    (jetTape (SemiprimeD1JetAffineCoefficient.one ctx).words)\n  have he:Function.update source.data U.output (jetTape (SemiprimeD1JetAffineCoefficient.one ctx).words)=out.data:=\n    unit_output_update _ _ _\n  rw [he] at h\n  change SemiprimeD1StackMultiplierLink.DataRel unitStack (data v) out.data\n    (Function.update (data v) (address .product) (jetTape (SemiprimeD1JetAffineCoefficient.one ctx).words)) at h\n  rw [←data_update] at h\n  exact h\n/-- The actual adder consumes both physical operands and writes only its real output. -/\ntheorem add_store_updates (width rank a b out:List Bool):\n    Function.update (Function.update (Function.update\n      (A.store [] [] [] [] width [] a b rank [] [] [] [] [] []) (.inr .leftTape) []) (.inr .rightTape) []) (.inr .output) out=\n      A.store [] [] [] [] width [] [] [] rank [] [] out [] [] []:=by\n  funext k;fin_cases k <;> rfl\n/-- Exact actual dense addition uses the literal right-fold product and saved tail-sum operands. -/\ntheorem add_call (ctx:Context) (v:Values) (a b:Jet)\n    (ha:v .product=jetTape a) (hb:v .tailSum=jetTape b)\n    (hw:(v .width).length=ctx.precision) (hr:(v .rank).length=ctx.rank) (ho:v .sum=[]):\n    Runs program (SemiprimeD1StackJetAddExecution.totalTime (v .width) (v .rank) a b+1)\n      (ctl .add) (data v) (ctl .returning)\n      (data (Function.update (Function.update (Function.update v .product []) .tailSum []) .sum\n        (jetTape (SemiprimeD1JetRingBits.add ctx a b).words))):=by\n  let source:=SemiprimeD1StackJetAdd.state (some .start) none none [] [] [] [] (v .width) []\n    (jetTape a) (jetTape b) (v .rank) [] [] [] [] [] []\n  let out:=SemiprimeD1StackJetAdd.state none none none [] [] [] [] (v .width) [] [] [] (v .rank) [] []\n    (jetTape (SemiprimeD1JetRingBits.add ctx a b).words) [] [] []\n  have hin:SemiprimeD1StackMultiplierLink.DataRel addStack (data v) source.data (data v):=by\n    constructor\n    · intro k;rw [data_add,ha,hb,ho];rfl\n    · intro k _;rfl\n  have hrun:=SemiprimeD1StackJetAddExecution.source_run (v .width) (v .rank) a b\n  rw [SemiprimeD1StackJetAddExecution.rows_eq_original ctx _ _ a b hw hr] at hrun\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program addStack Label.add add_injective\n    A.program .start (fun _=>rfl) (ctl .add) (ctl .returning) rfl _ source out _ _ rfl rfl rfl rfl hrun hin\n  have h0:=SemiprimeD1StackMultiplierLink.data_update addStack add_injective (data v) source.data (data v) hin (.inr .leftTape) []\n  have h1:=SemiprimeD1StackMultiplierLink.data_update addStack add_injective (data v) _ _ h0 (.inr .rightTape) []\n  have h2:=SemiprimeD1StackMultiplierLink.data_update addStack add_injective (data v) _ _ h1 (.inr .output)\n    (jetTape (SemiprimeD1JetRingBits.add ctx a b).words)\n  have he:Function.update (Function.update (Function.update source.data (.inr .leftTape) []) (.inr .rightTape) []) (.inr .output)\n      (jetTape (SemiprimeD1JetRingBits.add ctx a b).words)=out.data:=add_store_updates _ _ _ _ _\n  rw [he] at h2\n  change SemiprimeD1StackMultiplierLink.DataRel addStack (data v) out.data\n    (Function.update (Function.update (Function.update (data v) (address .product) []) (address .tailSum) []) (address .sum)\n      (jetTape (SemiprimeD1JetRingBits.add ctx a b).words)) at h2\n  rw [←data_update,←data_update,←data_update] at h2\n  exact h2\nend RiemannGaussian.SemiprimeD1StackJetFoldOperators\n","RiemannGaussian.SemiprimeD1StackJetPointOrder":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetPoint\nimport RiemannGaussian.SemiprimeD1JetRingBits\nimport RiemannGaussian.SemiprimeSourceCompactWordIds\n/-! # Proof-side descending convolution order\nThese definitions describe the scalar effects of the physical counter loops;\nthey are specifications, not executable instruction or coefficient suppliers.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackJetPointOrder\nopen SemiprimeBitArithmetic (bitValue bitValue_lt_width)\nopen SemiprimeD1JetAxes (Context)\nnamespace S\nexport SemiprimeD1JetScalarBits (add mul)\nend S\nnamespace J\nexport SemiprimeD1JetRingBits (plan term mulAt read)\nend J\n\n/-- The actual nested physical decrement loops visit these pairs. -/\ndef descending (rank : ℕ) : List (ℕ×ℕ) :=\n  (List.range rank).reverse.flatMap (fun i=>(List.range rank).reverse.map (fun j=>(i,j)))\n\n/-- Descending visits contain exactly the original pairs, including duplicates. -/\ntheorem descending_perm (rank : ℕ) : (descending rank).Perm (J.plan rank) := by\n  apply List.Perm.flatMap (List.reverse_perm _)\n  intro i hi\n  exact (List.reverse_perm _).map (fun j=>(i,j))\n\n/-- Proof-side scalar effect of one physically routed pair. -/\ndef pairStep (ctx : Context) (a b : List (List Bool)) (k : ℕ) (ij : ℕ×ℕ) (acc : List Bool) : List Bool :=\n  if SemiprimeD1JetRouting.admissible ctx.axes ij.1 ij.2 ∧\n      SemiprimeD1JetRouting.sumIndex ctx.axes ij.1 ij.2=k then\n    (S.add ctx.precision (S.mul ctx.precision (J.read a ij.1).bits (J.read b ij.2).bits).bits acc).bits\n  else acc\n\n/-- Every acquired scalar effect is the original term plus the current sum. -/\ntheorem pairStep_value (ctx : Context) (a b : List (List Bool)) (k : ℕ) (ij : ℕ×ℕ) (acc : List Bool) :\n    (bitValue (pairStep ctx a b k ij acc):ZMod (2^ctx.precision))=\n      (bitValue (J.term ctx a b k ij).bits:ZMod (2^ctx.precision))+(bitValue acc:ZMod (2^ctx.precision)) := by\n  rw [SemiprimeD1JetRingBits.term_value]\n  unfold pairStep\n  split_ifs with h\n  · rw [SemiprimeD1JetScalarBits.add_zmod,SemiprimeD1JetScalarBits.mul_zmod]\n    simp only [SemiprimeD1JetRingBits.read_bits,SemiprimeD1JetRingBits.coefficient]\n  · simp\n\n/-- Proof-side fold of the physical pair order. -/\ndef accumulate (ctx : Context) (a b : List (List Bool)) (k : ℕ) : List (ℕ×ℕ) → List Bool → List Bool\n  | [],acc => acc\n  | ij::rest,acc => accumulate ctx a b k rest (pairStep ctx a b k ij acc)\n\n/-- All scalar effects add to the exact original finite term sum. -/\ntheorem accumulate_value (ctx : Context) (a b : List (List Bool)) (k : ℕ)\n    (pairs : List (ℕ×ℕ)) (acc : List Bool) :\n    (bitValue (accumulate ctx a b k pairs acc):ZMod (2^ctx.precision))=\n      (pairs.map (fun ij=>(bitValue (J.term ctx a b k ij).bits:ZMod (2^ctx.precision)))).sum+\n        (bitValue acc:ZMod (2^ctx.precision)) := by\n  induction pairs generalizing acc with\n  | nil => simp [accumulate]\n  | cons ij rest ih =>\n    rw [accumulate,ih,pairStep_value,List.map_cons,List.sum_cons]\n    abel\n\n/-- Every intermediate scalar output is canonical, including all skipped terms. -/\ntheorem accumulate_compact (ctx : Context) (a b : List (List Bool)) (k : ℕ)\n    (pairs : List (ℕ×ℕ)) (acc : List Bool) (hc : SemiprimeSourceCompactBits.Compact acc) :\n    SemiprimeSourceCompactBits.Compact (accumulate ctx a b k pairs acc) := by\n  induction pairs generalizing acc with\n  | nil => exact hc\n  | cons ij rest ih =>\n    apply ih\n    unfold pairStep\n    split_ifs\n    · exact SemiprimeD1JetScalarBits.add_compact _ _ _\n    · exact hc\n\n/-- Every intermediate scalar has the actual precision width. -/\ntheorem accumulate_length (ctx : Context) (a b : List (List Bool)) (k : ℕ)\n    (pairs : List (ℕ×ℕ)) (acc : List Bool) (hc : acc.length ≤ ctx.precision) :\n    (accumulate ctx a b k pairs acc).length ≤ ctx.precision := by\n  induction pairs generalizing acc with\n  | nil => exact hc\n  | cons ij rest ih =>\n    apply ih\n    unfold pairStep\n    split_ifs\n    · exact SemiprimeD1JetScalarBits.add_length _ _ _\n    · exact hc\n\n/-- Descending scalar accumulation has exactly the original coefficient bytes.\nNo positivity, input word bound or intermediate fit oracle is required. -/\ntheorem descending_eq_original (ctx : Context) (a b : List (List Bool)) (k : ℕ) :\n    accumulate ctx a b k (descending ctx.rank) []=(J.mulAt ctx a b k).bits := by\n  have hv:=accumulate_value ctx a b k (descending ctx.rank) []\n  have hp:=(descending_perm ctx.rank).map (fun ij=>(bitValue (J.term ctx a b k ij).bits:ZMod (2^ctx.precision)))\n  rw [hp.sum_eq] at hv\n  have ht : (bitValue (J.mulAt ctx a b k).bits:ZMod (2^ctx.precision))=\n      ((J.plan ctx.rank).map (fun ij=>(bitValue (J.term ctx a b k ij).bits:ZMod (2^ctx.precision)))).sum := by\n    simpa only [SemiprimeD1JetRingBits.mulAt,List.map_map,Function.comp_def] using\n      SemiprimeD1JetRingBits.sumReports_value ctx.precision ((J.plan ctx.rank).map (J.term ctx a b k))\n  have he : (bitValue (accumulate ctx a b k (descending ctx.rank) []):ZMod (2^ctx.precision))=\n      (bitValue (J.mulAt ctx a b k).bits:ZMod (2^ctx.precision)) := by\n    simp only [bitValue,Nat.cast_zero,add_zero] at hv\n    exact hv.trans ht.symm\n  have hc:=accumulate_compact ctx a b k (descending ctx.rank) [] (by trivial)\n  have hl:=accumulate_length ctx a b k (descending ctx.rank) [] (by simp)\n  have hr:=SemiprimeD1JetRingBits.mulAt_length ctx a b k\n  have hlo : bitValue (accumulate ctx a b k (descending ctx.rank) [])<2^ctx.precision :=\n    (bitValue_lt_width _).trans_le (Nat.pow_le_pow_right (by decide : 1≤2) hl)\n  have hro : bitValue (J.mulAt ctx a b k).bits<2^ctx.precision :=\n    (bitValue_lt_width _).trans_le (Nat.pow_le_pow_right (by decide : 1≤2) hr)\n  let _ : NeZero (2^ctx.precision) := ⟨by positivity⟩\n  have hn:=congrArg ZMod.val he\n  simp only [ZMod.val_natCast,Nat.mod_eq_of_lt hlo,Nat.mod_eq_of_lt hro] at hn\n  exact SemiprimeSourceCompactWordIds.compact_value_injective _ _ hc\n    (SemiprimeD1JetRingBits.mulAt_compact _ _ _ _) hn\n\nend RiemannGaussian.SemiprimeD1StackJetPointOrder\n","RiemannGaussian.SemiprimeD1StackJetRouteCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRoute\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\n/-! # Included physical mixed-radix operand acquisition calls -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteCalls\nopen SemiprimeD1StackJetRoute\nnamespace Trace\nexport SemiprimeD1StackProcedureTrace (Runs At included_call one_base runs_trans)\nend Trace\nlocal notation \"ctl\" => SemiprimeD1StackJetRoute.control\n\n/-- Literal staging bank, with all unlisted work stacks physically empty. -/\ndef bank (axes records left right result radix q d quotLeft remLeft quotRight remRight valid : List Bool) : Stack→List Bool\n  | .axes=>axes\n  | .records=>records\n  | .left=>left\n  | .right=>right\n  | .result=>result\n  | .radix=>radix\n  | .q=>q\n  | .d=>d\n  | .quotLeft=>quotLeft\n  | .remLeft=>remLeft\n  | .quotRight=>quotRight\n  | .remRight=>remRight\n  | .valid=>valid\n  | _=>[]\n@[simp] theorem bank_apply (axes records left right result radix q d quotLeft remLeft quotRight remRight valid: List Bool) (k : Stack) :\n    bank axes records left right result radix q d quotLeft remLeft quotRight remRight valid k = match k with\n    | .axes=>axes\n    | .records=>records\n    | .left=>left\n    | .right=>right\n    | .result=>result\n    | .radix=>radix\n    | .q=>q\n    | .d=>d\n    | .quotLeft=>quotLeft\n    | .remLeft=>remLeft\n    | .quotRight=>quotRight\n    | .remRight=>remRight\n    | .valid=>valid\n    | _=>[] := rfl\n\ntheorem copy_injective (b : Bool) : Function.Injective (copyStack b) := by\n  intro x y h\n  cases b <;> fin_cases x <;> fin_cases y <;> simp_all [copyStack]\n\n/-- The actual first index is copied once, preserving its original unary input. -/\ntheorem copy_left (axes left right : List Bool) :\n    Trace.Runs code (5*left.length+4) (ctl .copyLeft)\n      (bank axes [] left right [] [] [] [] [] [] [] [] [])\n      (ctl .copyRight) (bank axes [] left right left [] [] [] [] [] [] [] []) := by\n  have hr := SemiprimeD1StackCopy.copy_words left [] none\n  apply Trace.included_call code (copyStack false) copyLeftLabel (copy_injective false)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (ctl .copyLeft) (ctl .copyRight) rfl\n    (5*left.length+3) _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; fin_cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; fin_cases k <;> simp [copyStack,SemiprimeD1StackCopy.done,SemiprimeD1StackCopy.payload]\n    · intro k hk\n      cases k <;> first | rfl | exact (hk 1 rfl).elim\n\n/-- The second actual index is copied onto the retained first index. -/\ntheorem copy_right (axes left right result : List Bool) :\n    Trace.Runs code (5*right.length+4) (ctl .copyRight)\n      (bank axes [] left right result [] [] [] [] [] [] [] [])\n      (ctl .suffixCall) (bank axes [] left right (right++result) [] [] [] [] [] [] [] []) := by\n  have hr := SemiprimeD1StackCopy.copy_words right result none\n  apply Trace.included_call code (copyStack true) copyRightLabel (copy_injective true)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (ctl .copyRight) (ctl .suffixCall) rfl\n    (5*right.length+3) _ _ _ _ rfl rfl hr\n  · constructor\n    · intro k; fin_cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; fin_cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk 1 rfl).elim\n\ntheorem suffix_injective : Function.Injective suffixStack := by\n  intro x y h\n  cases x <;> cases y <;> simp_all [suffixStack]\n\n/-- The closed route really calls the original-axis supplier; no acquired record\nor rank is an input to this caller. The retained sum and indices are untouched. -/\ntheorem suffix_call (axes : List ℕ) (hp : ∀q∈axes,0<q) (left right result : List Bool) :\n    ∃m≤100*(axes.length+1)*(axes.prod+1)+2,\n      Trace.Runs code m (ctl .suffixCall)\n        (bank (SemiprimeD1TensorTapeCodec.vectorBits (axes.map SemiprimeD1StackUnaryDivmod.unary))\n          [] left right result [] [] [] [] [] [] [] [])\n        (ctl .suffixDone)\n        (bank [] (SemiprimeD1StackJetSuffixOriginal.recordTape axes 1 []) left right result\n          (SemiprimeD1StackUnaryDivmod.unary axes.prod) [] [] [] [] [] [] [true]) := by\n  obtain ⟨m,hm,hr⟩ := SemiprimeD1StackJetSuffixOriginal.acquire_run axes hp\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureInclusion.included_call code suffixStack suffixLabel suffix_injective\n    SemiprimeD1StackJetSuffix.code (SemiprimeD1StackJetSuffix.control .vector) (fun _=>rfl)\n    (ctl .suffixCall) (ctl .suffixDone) rfl m _ _ _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk; rfl\n  · constructor\n    · intro k; cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact (hk .axes rfl).elim | exact (hk .radix rfl).elim | exact (hk .records rfl).elim | exact (hk .valid rfl).elim\n\nend RiemannGaussian.SemiprimeD1StackJetRouteCalls\n","RiemannGaussian.SemiprimeD1StackJetRouteExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackJetRouteLoop\n/-! # Closed original-context physical mixed-radix execution -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackJetRouteExecution\nopen SemiprimeD1StackJetRoute SemiprimeD1StackJetRouteCalls SemiprimeD1StackJetRouteStep\nopen SemiprimeD1StackJetRouteControl SemiprimeD1StackJetRouteBase SemiprimeD1StackJetRouteLoop\nopen SemiprimeD1StackJetRouteRecords (tape acquired_tape original_tape_length)\nopen SemiprimeD1StackJetRouteFailure (compose)\nopen SemiprimeD1StackUnaryDivmod (unary unary_add)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nlocal notation \"ctl\" => SemiprimeD1StackJetRoute.control\n\n/-- Polynomial transition envelope in actual rank, axis count and original unary indices. -/\ndef budget (axes : List ℕ) (i j : ℕ) : ℕ :=\n  20000*(axes.length+1)^2*(axes.prod+i+j+1)\n\n/-- Literal original-context inputs: axes and indices are physical tapes;\nno suffix, route, compatibility or rank answer is provided. -/\ndef initial (axes : List ℕ) (i j : ℕ) : SemiprimeD1StackCalls.State Stack Label :=\n  ⟨some (ctl .copyLeft),none,none,\n    bank (vectorBits (axes.map unary)) [] (unary i) (unary j) [] [] [] [] [] [] [] [] [],[]⟩\n\n/-- Exact bytes at the original mixed-radix route boundary. -/\ndef final (axes : List ℕ) (i j : ℕ) : SemiprimeD1StackCalls.State Stack Label :=\n  ⟨none,none,none,answer (decide (SemiprimeD1JetRouting.admissible axes i j)) (unary (i+j)),[]⟩\n\n/-- Original axes internally acquire every suffix product before the actual\nrecord loop. The destination is a cached physical sum, retained only on success. -/\ntheorem route_trace (axes : List ℕ) (hp : ∀q∈axes,0<q) (i j : ℕ) :\n    ∃m≤budget axes i j,Trace.Runs code m (ctl .copyLeft) (initial axes i j).data\n      (ctl .halt) (final axes i j).data := by\n  have h1 := copy_left (vectorBits (axes.map unary)) (unary i) (unary j)\n  have h2 := copy_right (vectorBits (axes.map unary)) (unary i) (unary j) (unary i)\n  rw [←unary_add j i,Nat.add_comm j i] at h2\n  obtain ⟨a,ha,h3⟩ := suffix_call axes hp (unary i) (unary j) (unary (i+j))\n  rw [acquired_tape] at h3\n  have h4 := flag_true (ctl .suffixDone) (ctl .clearRank) rfl []\n    (tape (SemiprimeD1StackRouteArithmetic.records axes)) (unary i) (unary j) (unary (i+j))\n    (unary axes.prod) [] [] [] [] [] []\n  have h5 := clear_rank (tape (SemiprimeD1StackRouteArithmetic.records axes))\n    (unary i) (unary j) (unary (i+j)) (unary axes.prod)\n  obtain ⟨b,hb,h6⟩ := loop (SemiprimeD1StackRouteArithmetic.records axes) i j (unary (i+j))\n  rw [SemiprimeD1StackRouteArithmetic.compatible_records] at h6\n  have h := compose h1 (compose h2 (compose h3 (compose h4 (compose h5 h6))))\n  refine ⟨_,?_,h⟩\n  have hlen : (SemiprimeD1StackRouteArithmetic.records axes).length=axes.length := by\n    clear hp ha hb h h1 h2 h3 h4 h5 h6\n    induction axes with\n    | nil=>rfl\n    | cons q qs ih=>simp [SemiprimeD1StackRouteArithmetic.records,ih]\n  rw [hlen] at hb\n  have ht := original_tape_length axes hp\n  simp only [unary,List.length_replicate] at hb ⊢\n  have hlinear : (tape (SemiprimeD1StackRouteArithmetic.records axes)).length+i+j+(i+j)+1≤\n      4*(axes.length+1)*(axes.prod+i+j+1) := by\n    ring_nf at ht ⊢\n    omega\n  have hscaled := Nat.mul_le_mul_left (4000*(axes.length+1)) hlinear\n  unfold budget\n  ring_nf at ha hb hscaled ⊢\n  omega\n\n/-- Closed literal clean-halt execution with the final halt transition paid. -/\ntheorem route_run (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive) (i j : ℕ) :\n    ∃m≤budget ctx.axes i j+1,\n      SemiprimeD1StackCalls.run code m (initial ctx.axes i j)=some (final ctx.axes i j) := by\n  obtain ⟨m,hm,ht⟩ := route_trace ctx.axes hp i j\n  obtain ⟨out,hr,ho⟩ := ht [] (initial ctx.axes i j) ⟨rfl,rfl,rfl⟩\n  have hh := SemiprimeD1StackProcedureTrace.halt_run code (ctl .halt) rfl\n    (final ctx.axes i j).data [] out ho\n  refine ⟨m+1,by omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  exact hh\n\n/-- The sole physical output Boolean and unary destination specify exactly the\nfrozen original route, including all rejected/out-of-range indices. -/\ntheorem final_value (axes : List ℕ) (i j : ℕ) :\n    (if (final axes i j).data .valid=[true] then\n      some ((final axes i j).data .result).length else none)=\n      (SemiprimeD1JetRouting.route axes i j).value := by\n  rw [SemiprimeD1StackRouteArithmetic.route_eq_add]\n  by_cases ha : SemiprimeD1JetRouting.admissible axes i j <;>\n    simp [final,answer,bank,ha,unary]\nend RiemannGaussian.SemiprimeD1StackJetRouteExecution\n","RiemannGaussian.SemiprimeD1StackKernelLinearNormalizeBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackKernelLinearArithmeticBounds\n/-! # Own fixed polynomial for the whole real normalization continuation -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackKernelLinearNormalizeBounds\nopen SemiprimeD1StackKernelLinearView SemiprimeD1StackKernelLinearArithmeticBounds\nopen SemiprimeBitDivision\nnamespace Norm\nexport SemiprimeD1StackKernelLinearNormalize (timeBound mag scanned signed zeroed prepared divided)\nend Norm\nnamespace Scan\nexport SemiprimeD1StackKernelLinearScan (timeBound timeBound_le leading_le result)\nend Scan\nnamespace Tail\nexport SemiprimeD1StackKernelLinearTail (prepareTime divideTime quotient remainder)\nend Tail\nnamespace Finish\nexport SemiprimeD1StackKernelLinearFinish (timeBound)\nend Finish\n/-- The acquired-cache normalization time depends only on actual physical word lengths.\nNo old native clock, factor width advice or arithmetic callback is a premise. -/\ntheorem timeBound_le (w:Words) (r:Nat) (hj:w.j.length ≤ r) (hd:w.displacement.length ≤ r)\n    (ha:w.alpha.length ≤ r) (hb:w.buffer.length ≤ r):Norm.timeBound w ≤ 1000000*(r+2)^2:=by\n  have hm:(Norm.mag w).length ≤ r:=by\n    rw [Norm.mag,magnitude_length]\n    exact max_le hj hd\n  have ho:(SemiprimeD1StackKernelLinearSpec.odd (Norm.mag w)).length ≤ r:=\n    (odd_length (Norm.mag w)).trans hm\n  have hl:=Scan.leading_le (Norm.mag w)\n  have hc:(SemiprimeD1StackKernelLinearSpec.power\n      (SemiprimeD1StackKernelLinearSpec.leading (Norm.mag w))).length ≤ r+1:=by\n    rw [SemiprimeD1StackKernelLinearSpec.power_length]\n    omega\n  have h0:=signedTime_le w r hj hd\n  have h1:Scan.timeBound (Norm.mag w) ≤ 10*(r+1):=(Scan.timeBound_le (Norm.mag w)).trans (by omega)\n  have h2:((Norm.scanned w).content.length+3)+(5*(Norm.scanned w).alpha.length+4)+1 ≤ 6*r+9:=by\n    change (SemiprimeD1StackKernelLinearSpec.power\n      (SemiprimeD1StackKernelLinearSpec.leading (Norm.mag w))).length+3+(5*w.alpha.length+4)+1 ≤ _\n    omega\n  have h3:Finish.timeBound (Norm.zeroed w) (Norm.mag w) [] [] ≤ 2*r+13:=by\n    change (Norm.mag w).length+w.buffer.length+0+0+13 ≤ _\n    omega\n  have h4:Tail.prepareTime (Norm.scanned w) (Norm.mag w) ≤ 10*(r+1):=by\n    change (5*(SemiprimeD1StackKernelLinearSpec.odd (Norm.mag w)).length+4)+\n      ((SemiprimeD1StackKernelLinearSpec.odd (Norm.mag w)).length+3)+((Norm.mag w).length+3) ≤ _\n    omega\n  have h5:=divideTime_le (Norm.prepared w) r ha hc\n  have hq:(Tail.quotient (Norm.prepared w)).length ≤ r:=by\n    rw [Tail.quotient,(divideLoop_widths _ _).2.1]\n    exact ha\n  have hr:(Tail.remainder (Norm.prepared w)).length ≤ r+1:=by\n    rw [Tail.remainder,(divideLoop_widths _ _).1]\n    exact hc\n  have h6:Finish.timeBound (Norm.divided w) [] (Tail.remainder (Norm.prepared w))\n      (Tail.quotient (Norm.prepared w)) ≤ 3*r+14:=by\n    change 0+w.buffer.length+(Tail.quotient (Norm.prepared w)).length+(Tail.remainder (Norm.prepared w)).length+13 ≤ _\n    omega\n  have hp:r+1 ≤ (r+2)^2:=by nlinarith\n  unfold Norm.timeBound\n  split\n  · nlinarith only [h0,h1,h2,h3,hp]\n  · nlinarith only [h0,h1,h4,h5,h6,hp]\nend RiemannGaussian.SemiprimeD1StackKernelLinearNormalizeBounds\n","RiemannGaussian.SemiprimeD1StackLeafState":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeaf\n/-! # Exact declarative registers between the leaf's actual included calls -/\nset_option autoImplicit false\nset_option synthInstance.maxSize 131072\nset_option maxRecDepth 131072\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackLeafState\nopen SemiprimeD1StackLeaf\nnamespace PS\nexport SemiprimeD1StackVertexProductState (Values Slot data address data_get data_other data_update)\nend PS\n/-- The only outer registers that can be live between included calls. -/\ninductive Slot where\n  | widthBits | catalogue | sum | sumResult | valid | unaryInput | counter | zero\n  deriving DecidableEq,Repr\ninstance : Fintype Slot := Fintype.ofList [.widthBits,.catalogue,.sum,.sumResult,.valid,.unaryInput,.counter,.zero]\n  (by intro s; cases s <;> simp)\n/-- Fixed physical addresses of the outer register tuple. -/\ndef address : Slot→Stack\n  | .widthBits => aux .widthBits\n  | .catalogue => aux .catalogue\n  | .sum => aux .sum\n  | .sumResult => aux .sumResult\n  | .valid => aux .valid\n  | .unaryInput => unaryStack .left\n  | .counter => unaryStack .output\n  | .zero => enumerationWork .word\n/-- Distinct slots are genuinely distinct physical registers. -/\ntheorem address_injective : Function.Injective address := by decide\n/-- Outer live register tuple, a proof-side finite record only. -/\nabbrev Values := Slot→List Bool\n/-- Physical state invariant: exact product registers and outer live tuple;\nall other work registers are empty. -/\ndef data (p : PS.Values) (v : Values) : Stack→List Bool\n  | .inl k => PS.data p k\n  | k => if k=address .widthBits then v .widthBits else\n      if k=address .catalogue then v .catalogue else\n      if k=address .sum then v .sum else\n      if k=address .sumResult then v .sumResult else\n      if k=address .valid then v .valid else\n      if k=address .unaryInput then v .unaryInput else\n      if k=address .counter then v .counter else\n      if k=address .zero then v .zero else []\n/-- Product registers are stored directly, without a decoder or semantic getter. -/\ntheorem data_product (p : PS.Values) (v : Values) (k : P.Stack) :\n    data p v (productStack k)=PS.data p k := rfl\n/-- Every original product slot has its declared physical contents. -/\ntheorem data_product_get (p : PS.Values) (v : Values) (s : PS.Slot) :\n    data p v (productStack (PS.address s))=p s := PS.data_get p s\n/-- Every outer register has its declared physical contents. -/\ntheorem data_get (p : PS.Values) (v : Values) (s : Slot) : data p v (address s)=v s := by\n  cases s <;> simp [data,address,aux,unaryStack,enumerationWork]\n/-- Every unmentioned outer work register is genuinely empty. -/\ntheorem data_other (p : PS.Values) (v : Values) (k : Stack)\n    (hp : ∀j,k ≠ productStack j) (hk : ∀s,k ≠ address s) : data p v k=[] := by\n  cases k with\n  | inl k => exact (hp k rfl).elim\n  | inr k => simp [data,hk]\n/-- Replacing an outer slot changes exactly its one physical stack. -/\ntheorem data_update (p : PS.Values) (v : Values) (s : Slot) (word : List Bool) :\n    data p (Function.update v s word)=Function.update (data p v) (address s) word := by\n  funext k\n  by_cases hex : ∃t,k=address t\n  · obtain ⟨t,rfl⟩:=hex\n    rw [data_get]\n    by_cases he : t=s\n    · subst t; simp\n    · have hn : address t ≠ address s := fun hh=>he (address_injective hh)\n      simp only [Function.update_of_ne he,Function.update_of_ne hn,data_get]\n  · have hk : ∀t,k ≠ address t := by simpa only [not_exists] using hex\n    cases k with\n    | inl k =>\n      have hn : productStack k ≠ address s := hk s\n      change PS.data p k=Function.update (data p v) (address s) word (productStack k)\n      rw [Function.update_of_ne hn]\n      rfl\n    | inr k =>\n      rw [data_other _ _ (.inr k) (by intro j; simp [productStack]) hk,\n        Function.update_of_ne (hk s),data_other _ _ (.inr k) (by intro j; simp [productStack]) hk]\n/-- Replacing an actual product slot changes exactly its shared physical stack. -/\ntheorem data_product_update (p : PS.Values) (v : Values) (s : PS.Slot) (word : List Bool) :\n    data (Function.update p s word) v=\n      Function.update (data p v) (productStack (PS.address s)) word := by\n  funext k\n  cases k with\n  | inl k =>\n    change PS.data (Function.update p s word) k=_\n    rw [PS.data_update]\n    by_cases he : k=PS.address s\n    · subst k; simp [productStack]\n    · simp [productStack,he,data]\n  | inr k => simp [data,productStack]\n/-- Direct product inclusion has no hidden work-bank contents. -/\ntheorem product_project (p : PS.Values) (v : Values) (k : P.Stack) :\n    data p v (productStack k)=PS.data p k := rfl\n/-- Real catalogue parser sees exactly its current physical stream and assignment. -/\ntheorem field_project (p : PS.Values) (v : Values) (k : F.Stack) :\n    data p v (fieldStack k)=\n      match k with\n      | .inl .input => v .catalogue\n      | .inl .scratch => []\n      | .inl .output => p .assignment\n      | .inr _ => v .valid := by\n  fin_cases k\n  · exact data_get p v .catalogue\n  · rfl\n  · exact data_product_get p v .assignment\n  · exact data_get p v .valid\n\nend RiemannGaussian.SemiprimeD1StackLeafState\n","RiemannGaussian.SemiprimeD1StackLeafValue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackLeafLoop\n/-! # Exact original eager-leaf bytes of the actual assignment-sum order -/\nset_option autoImplicit false\nset_option maxHeartbeats 1500000\nnamespace RiemannGaussian.SemiprimeD1StackLeafValue\nopen scoped BigOperators\nopen SemiprimeD1StackLeafLoop\nopen SemiprimeD1JetInterpretation (interpret)\nopen SemiprimeD1TensorTables (GoodWords)\n\n/-- The actual counter-generated catalogue is a permutation of precisely the\noriginal finite Boolean assignments. Order differences require only addition. -/\ntheorem catalogue_perm (M : ℕ) :\n    (SemiprimeD1StackAssignmentOrder.assignments (2^M) (List.replicate M false)).Perm\n      ((Finset.univ : Finset (Fin M→Bool)).toList.map List.ofFn) := by\n  apply (List.perm_ext_iff_of_nodup (SemiprimeD1StackAssignmentOrder.zero_nodup M)\n    (List.Nodup.map List.ofFn_injective (Finset.nodup_toList (Finset.univ : Finset (Fin M→Bool))))).mpr\n  intro word\n  rw [SemiprimeD1StackAssignmentOrder.zero_complete]\n  constructor\n  · intro hlen\n    let f : Fin M→Bool := fun i=>word[i.val]'(by omega)\n    have he : List.ofFn f=word := by\n      apply List.ext_getElem (by simp [hlen])\n      intro i hi hj\n      simp only [List.getElem_ofFn]\n      rfl\n    exact List.mem_map.mpr ⟨f,by simp,he⟩\n  · intro h\n    obtain ⟨f,_,rfl⟩:=List.mem_map.mp h\n    simp\n\n/-- The reached physical dense sum represents exactly the sum of all parsed\nassignment-product values plus the previous accumulator. -/\ntheorem summed_interpret (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (assignments : List (List Bool)) (acc : List (List Bool)) :\n    interpret ctx (summed ctx vertices assignments acc)=\n      (assignments.map (fun bits=>interpret ctx (SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices bits).words)).sum+\n        interpret ctx acc := by\n  induction assignments generalizing acc with\n  | nil => simp [summed]\n  | cons bits rest ih =>\n    simp only [summed,ih,List.map_cons,List.sum_cons,SemiprimeD1JetOperations.interpret_add ctx _ _ hp]\n    ac_rfl\n\n/-- Every actual sum prefix after a canonical accumulator is canonical. -/\ntheorem summed_good (ctx : SemiprimeD1JetAxes.Context) (vertices : List SemiprimeD1LeafCounter.Vertex)\n    (assignments : List (List Bool)) (acc : List (List Bool)) (ha : GoodWords ctx acc) :\n    GoodWords ctx (summed ctx vertices assignments acc) := by\n  induction assignments generalizing acc with\n  | nil => exact ha\n  | cons bits rest ih => exact ih _ (SemiprimeD1LeafCounterBounds.add_good ctx _ _)\n\n/-- The complete real enumeration/dense-fold bytes equal the SAME frozen\nTensorTapeLeaf.run words, independently of its materialized-table sum order. -/\ntheorem summed_original (M : ℕ) (ctx : SemiprimeD1JetAxes.Context) (hp : ctx.Positive)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) :\n    summed ctx vertices (SemiprimeD1StackAssignmentOrder.assignments (2^M) (List.replicate M false)) []=\n      (SemiprimeD1TensorTapeLeaf.run M ctx vertices).words := by\n  let catalogue:=SemiprimeD1StackAssignmentOrder.assignments (2^M) (List.replicate M false)\n  have hnon : catalogue ≠ [] := by\n    have hl:=SemiprimeD1StackAssignmentOrder.assignments_length (2^M) (List.replicate M false)\n    have hp : 0<2^M := by positivity\n    intro he\n    change catalogue.length=2^M at hl\n    rw [he] at hl\n    simp only [List.length_nil] at hl\n    omega\n  have ha : GoodWords ctx (summed ctx vertices catalogue []) := by\n    cases he : catalogue with\n    | nil => exact (hnon he).elim\n    | cons bits rest =>\n      exact summed_good ctx vertices rest _ (SemiprimeD1LeafCounterBounds.add_good ctx _ _)\n  have hb : GoodWords ctx (SemiprimeD1TensorTapeLeaf.run M ctx vertices).words := by\n    rw [SemiprimeD1TensorTapeLeaf.run_words]\n    exact SemiprimeD1LeafCounterBounds.run_good M ctx vertices\n  apply SemiprimeD1JetInterpretation.interpret_injective ctx _ _ hp ha.1 hb.1\n    (fun w hw=>(ha.2 w hw).1) (fun w hw=>(hb.2 w hw).1)\n    (fun w hw=>(ha.2 w hw).2) (fun w hw=>(hb.2 w hw).2)\n  rw [summed_interpret ctx hp]\n  have hz : interpret ctx []=0 := by simp [SemiprimeD1JetInterpretation.interpret,SemiprimeD1JetInterpretation.basis,\n    SemiprimeD1JetRingBits.coefficient,SemiprimeBitArithmetic.bitValue]\n  rw [hz,add_zero]\n  have hs:=(catalogue_perm M).map\n    (fun bits=>interpret ctx (SemiprimeD1TensorTapeLeaf.evaluateAssignment ctx vertices bits).words)\n  rw [hs.sum_eq,List.map_map]\n  rw [←List.sum_toFinset _ (Finset.nodup_toList (Finset.univ : Finset (Fin M→Bool)))]\n  simp only [Finset.toList_toFinset]\n  rw [SemiprimeD1TensorTapeLeaf.run_words,SemiprimeD1LeafCounter.run_value M ctx hp vertices]\n  apply Finset.sum_congr rfl\n  intro bits _\n  dsimp only [Function.comp_def]\n  rw [SemiprimeD1TensorTapeLeaf.evaluateAssignment_words,\n    SemiprimeD1LeafCounter.evaluateAssignment_value ctx hp vertices bits]\n\nend RiemannGaussian.SemiprimeD1StackLeafValue\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputTable":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticWordTable\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputCompactBounds\nimport RiemannGaussian.SemiprimeD1StackPublicInputTable\n/-! # One fixed144-role whole marked input-table source\nInputs are only binary N, actual unary descriptor index, actual side singleton\nand the physically acquired scope bank. Every actual DFS leaf executes the\nimmutable66 source followed by real binary compaction before word framing.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputTable\nnamespace P\nexport SemiprimeD1StackMarkedPublicInputCompact (Stack Label program initial coefficient)\nend P\nnamespace M\nexport SemiprimeD1StackMarkedPublicInput (checker word product aux)\nend M\nnamespace G\nexport SemiprimeD1StackStaticWordTable (Static)\nend G\n/-- Literal inventory of all66 real checker/helper/shadow words before N. -/\ndef roles : List P.Stack :=\n  SemiprimeD1StackPublicInputTable.roles.map M.checker++\n  (List.finRange 5).map M.word++\n  ([.multiplier,.multiplicand,.scratch,.product] : List SemiprimeD1StackUnaryProduct.Stack).map M.product++\n  ([.side,.widthTemplate,.shifted,.copyScratch,.output] : List SemiprimeD1StackMarkedPublicInput.Aux).map M.aux\n/-- Every physical role is visited once, including the temporarily used trim shadow. -/\ntheorem roles_nodup : roles.Nodup := by decide\n/-- Exactly66 literal physical positions. -/\ntheorem roles_length : roles.length=66 := by decide\n/-- Dormant aliases and all checker caches are included in physical clearing. -/\ntheorem roles_complete (k : P.Stack) : k∈roles := by\n  have he : roles.toFinset=(Finset.univ : Finset P.Stack) := by decide\n  have hk : k∈roles.toFinset := by rw [he];exact Finset.mem_univ k\n  exact List.mem_toFinset.mp hk\n/-- ONE static source program/inventory before every original input or arity. -/\ndef static : G.Static P.Stack P.Label :=\n  ⟨P.program,SemiprimeD1StackMarkedPublicInputCompact.ctl .start,\n    M.checker SemiprimeD1StackPublicInput.assignment,M.aux .output,roles,roles_complete,roles_nodup⟩\n/-- Checker66, actual original-input template66, count7 and DFS5. -/\nabbrev Stack := SemiprimeD1StackStaticWordTable.Stack P.Stack\n/-- Fixed finite labels; neither arity nor an original number enters control. -/\nabbrev Label := SemiprimeD1StackStaticWordTable.Label P.Label roles.length\n/-- Parameterless literal whole marked-table compiler. -/\ndef program : Label → SemiprimeD1StackCalls.Instruction Stack Label :=\n  SemiprimeD1StackStaticWordTable.program static\n/-- Only original N, index and side are in the template; the raw operand is empty. -/\ndef inputTemplate (bits indexWord : List Bool) (side : Bool) : P.Stack → List Bool :=\n  (P.initial bits [] indexWord side).data\n/-- Actual binary scope-ID vector is physically parsed/counted, never advised as arity. -/\ndef initial (bits indexWord : List Bool) (side : Bool) (bank : List Bool) :\n    SemiprimeD1StackCalls.State Stack Label :=\n  SemiprimeD1StackStaticWordTable.initial static (inputTemplate bits indexWord side) bank\n/-- Genuine finite source fixed before all original inputs and scopes. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackStaticWordTable.machine static\n/-- Every leaf's raw-assignment slot is initially physically empty. -/\ntheorem template_raw (bits indexWord : List Bool) (side : Bool) :\n    inputTemplate bits indexWord side static.raw=[] := rfl\n/-- Actual assignment reversal produces the ordinary compact source initial bank. -/\ntheorem template_raw_update (bits raw indexWord : List Bool) (side : Bool) :\n    Function.update (inputTemplate bits indexWord side) static.raw raw=\n      (P.initial bits raw indexWord side).data := by\n  change Function.update\n    (Sum.elim (SemiprimeD1StackPublicInput.initial bits [] indexWord).data\n      (SemiprimeD1StackMarkedPublicInput.privateInput [side]))\n    (Sum.inl SemiprimeD1StackPublicInput.assignment) raw=_\n  rw [Sum.update_elim_inl]\n  have h := SemiprimeD1StackPublicInputTable.template_raw_update bits raw indexWord\n  change Function.update (SemiprimeD1StackPublicInput.initial bits [] indexWord).data\n    SemiprimeD1StackPublicInput.assignment raw=(SemiprimeD1StackPublicInput.initial bits raw indexWord).data at h\n  rw [h]\n  rfl\n/-- Complete physical inventory including both66-role banks and every helper. -/\ntheorem stack_card : Fintype.card Stack=144 := by\n  rw [SemiprimeD1StackStaticWordTable.stack_card,SemiprimeD1StackMarkedPublicInputCompact.stack_card]\n/-- Every original number and assignment stays in Boolean data words. -/\ntheorem control_finite : Finite machine.σ := SemiprimeD1StackStaticWordTable.control_finite static\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputTable\n\n","RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableBounds\nimport RiemannGaussian.SemiprimeD1ZeroBoundaryTables\nimport RiemannGaussian.SemiprimeSourceHistogramPortKeys\n/-! # Exact whole original marked input table and canonical root shape\nThe reference is proof-side old ordered materialization with the new LOCAL\nnonnegative integer coefficients. Its report component is never used as a\nmachine clock. Every actual leaf is acquired by the fixed physical144 source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option synthInstance.maxSize 262144\nset_option maxRecDepth 32768\nnamespace RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableOriginal\nopen SemiprimeD1StackMarkedPublicInputTable SemiprimeD1StackMarkedPublicInputTableTrace\nopen SemiprimeD1StackMarkedPublicInputTableExecution SemiprimeD1StackMarkedPublicInputTableBounds\nopen SemiprimeD1StackStaticWordTableSpec (tree leafWords tree_entry)\nopen SemiprimeD1TensorTables SemiprimeD1TensorTapeCodec\nopen SemiprimeMacroGraph SemiprimeMacroParameters SemiprimeBitArithmetic\n/-- Canonical mathematical integer encoding, used ONLY in the reference table. -/\ndef wordOf (n : Nat) : List Bool := (SemiprimeSourceHistogramPortKeys.encodeKey n).bits\n/-- Exact original ordered input arity; proof-side descriptor notation only. -/\ndef inputArity (N : Nat) (side : Fin 2) (i : Fin (firstAxis (bitLength N)*secondAxis (bitLength N))) : Nat :=\n  arity (.input side i : Vertex (firstAxis (bitLength N)) (secondAxis (bitLength N)) (digitCount (bitLength N)))\n/-- Original ordered materializer at the marked LOCAL integer coefficient.\nThis logical reference is never invoked by the physical source. -/\nnoncomputable def reference (N : Nat) (hN : 0<N) (v : SemiprimePublicAcquiredExecution.PublicVertex N) :\n    Table (subdividedArity v) :=\n  (build (subdividedArity v) (fun raw =>\n    ⟨[wordOf (SemiprimeD1PackedMomentPrecision.coefficient N hN v\n      (fun j => (raw.toArray[j.val]?).getD false))],0⟩)).table\n/-- Original materialization reads the exact ordered finite assignment.\nThis generic lemma precedes concrete descriptor/configuration instantiation. -/\ntheorem reference_entry (N : Nat) (hN : 0<N) (v : SemiprimePublicAcquiredExecution.PublicVertex N)\n    (input : Fin (subdividedArity v) → Bool) :\n    valueAt (reference N hN v) input=[wordOf (SemiprimeD1PackedMomentPrecision.coefficient N hN v input)] := by\n  unfold reference\n  rw [SemiprimeD1ZeroBoundaryTables.build_entry]\n  have hget : (fun j : Fin (subdividedArity v) =>\n      ((List.ofFn input).toArray[j.val]?).getD false)=input := by\n    funext j\n    simp only [List.getElem?_toArray,List.getElem?_ofFn,j.isLt,dite_true,Option.getD_some]\n  exact congrArg (fun f => [wordOf (SemiprimeD1PackedMomentPrecision.coefficient N hN v f)]) hget\n/-- The compact source word is literally the unique canonical original integer\ncoefficient, on ALL finite local assignments and both original input sides. -/\ntheorem word_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (side : Fin 2)\n    (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val)\n    (input : Fin (arity (.input side i : Vertex (firstAxis (bitLength (bitValue bits)))\n      (secondAxis (bitLength (bitValue bits))) (digitCount (bitLength (bitValue bits))))) → Bool) :\n    answer bits indexWord (decide (side=1)) (List.ofFn input)=\n      wordOf (SemiprimeD1PackedMomentPrecision.coefficient (bitValue bits) hN (.inl (.input side i)) input) := by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective\n  · exact SemiprimeD1StackMarkedPublicInputCompactBounds.coefficient_compact _ _ _ _\n  · exact SemiprimeSourceHistogramPortKeys.encodeKey_compact _\n  · rw [show bitValue (answer bits indexWord (decide (side=1)) (List.ofFn input))=\n        bitValue (SemiprimeD1StackMarkedPublicInputEncoding.coefficient bits (List.ofFn input) indexWord (decide (side=1))) from\n      SemiprimeD1StackMarkedPublicInputCompactBounds.coefficient_value _ _ _ _]\n    rw [SemiprimeD1StackMarkedPublicInputMeaning.coefficient_original bits hc hN side i indexWord hi input]\n    exact (SemiprimeSourceHistogramPortKeys.encodeKey_value _).symm\n/-- WHOLE exact table equality in original first-port-outermost false-first order,\nrather than an entrywise value or a permutation of the input ports. -/\ntheorem table_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (side : Fin 2)\n    (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val) :\n    tree (answer bits indexWord (decide (side=1))) [] (inputArity (bitValue bits) side i)=\n      reference (bitValue bits) hN (.inl (.input side i)) := by\n  apply SemiprimeD1ZeroBoundaryTables.table_ext\n  intro input\n  have ht := tree_entry (answer bits indexWord (decide (side=1))) []\n    (inputArity (bitValue bits) side i) input\n  simp only [List.nil_append,leafWords] at ht\n  exact ht.trans ((congrArg (fun w => [w]) (word_original bits hc hN side i indexWord hi input)).trans\n    (reference_entry (bitValue bits) hN (.inl (.input side i)) input).symm)\n/-- Actual generated words satisfy BOTH compactness and width, including\nzero[], first/second sides, inactive rows and arbitrary physical assignment padding. -/\ntheorem tree_good (bits indexWord : List Bool) (side : Bool) (front : List Bool) (n : Nat) :\n    Good ⟨[],2*bits.length⟩ (tree (answer bits indexWord side) front n) := by\n  induction n generalizing front with\n  | zero =>\n    refine ⟨rfl,?_⟩\n    intro word hw\n    have he : word=answer bits indexWord side front := List.mem_singleton.mp hw\n    subst word\n    exact ⟨SemiprimeD1StackMarkedPublicInputCompactBounds.coefficient_compact _ _ _ _,\n      SemiprimeD1StackMarkedPublicInputCompactBounds.coefficient_length _ _ _ _⟩\n  | succ n ih => exact ⟨ih (front++[false]),ih (front++[true])⟩\n/-- ENTIRE actual tape matches the original marked table when the physically\ncounted scope has the original arity; actual scope routing remains caller work. -/\ntheorem tape_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (side : Fin 2)\n    (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val) (words : List (List Bool))\n    (ha : words.length=inputArity (bitValue bits) side i) :\n    outputTape bits indexWord (decide (side=1)) words=\n      tape (reference (bitValue bits) hN (.inl (.input side i))) := by\n  unfold outputTape SemiprimeD1StackStaticWordTableExecution.outputTape\n  rw [ha]\n  exact congrArg (fun t => tape t) (table_original bits hc hN side i indexWord hi)\n/-- The original materialized table is Good at the NEW public2ell scalar root;\nold precision2 is never substituted for it. -/\ntheorem reference_good (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (side : Fin 2)\n    (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val) :\n    Good ⟨[],SemiprimeD1PackedMomentPrecision.precision (bitValue bits)⟩\n      (reference (bitValue bits) hN (.inl (.input side i))) := by\n  rw [←table_original bits hc hN side i indexWord hi]\n  have hh := tree_good bits indexWord (decide (side=1)) [] (inputArity (bitValue bits) side i)\n  rw [SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc] at hh\n  exact hh\n/-- SAME actual whole144 source, exact original marked bytes and Good2ell,\nwith its own polynomial-per-actual-assignment clock; no source result is advised. -/\ntheorem source_run_original (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits)\n    (hN : 0<bitValue bits) (side : Fin 2)\n    (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n    (indexWord : List Bool) (hi : indexWord.length=i.val) (words : List (List Bool))\n    (ha : words.length=inputArity (bitValue bits) side i) :\n    ∃ t ≤ polynomial bits indexWord words,\n      SemiprimeD1StackCalls.run program t (initial bits indexWord (decide (side=1)) (vectorBits words))=\n        some (done bits indexWord (decide (side=1)) words) ∧\n      (done bits indexWord (decide (side=1)) words).data (SemiprimeD1StackStaticWordTable.aux .output)=\n        tape (reference (bitValue bits) hN (.inl (.input side i))) ∧\n      Good ⟨[],SemiprimeD1PackedMomentPrecision.precision (bitValue bits)⟩\n        (reference (bitValue bits) hN (.inl (.input side i))) := by\n  have hb : bits≠[] := by intro he;rw [he] at hN;exact (Nat.lt_irrefl 0) hN\n  obtain ⟨t,ht,hr⟩ := source_run_bounded bits indexWord (decide (side=1)) words hb\n  exact ⟨t,ht,hr,(output_bytes _ _ _ _).trans (tape_original bits hc hN side i indexWord hi words ha),\n    reference_good bits hc hN side i indexWord hi⟩\nend RiemannGaussian.SemiprimeD1StackMarkedPublicInputTableOriginal\n\n","RiemannGaussian.SemiprimeD1StackMarkedRootRecordsPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackMarkedRootRecords\n/-! # Paid copies, reversals and physical parsers in the marked record source -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackMarkedRootRecordsPrimitives\nopen SemiprimeD1StackMarkedRootRecords SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Concatenation in this one literal caller, retaining arbitrary real outer returns. -/\ntheorem join {m n : Nat} {pc mid finish : Label} {before between after : Stack → List Bool}\n    (h : Runs program m pc before mid between) (g : Runs program n mid between finish after) :\n    Runs program (m+n) pc before finish after :=\n  runs_trans program m n pc mid finish before between after h g\n/-- Every real copy reads a distinct retained source and target. -/\ntheorem copy_source_ne_target (site:Copy) : copySource site≠copyTarget site := by cases site <;> decide\n/-- The real restoring scratch is disjoint from every copy target. -/\ntheorem copy_scratch_ne_target (site:Copy) : scratch≠copyTarget site := by cases site <;> decide\n/-- The actual complete restoring-copy call charges all source cells and the real return. -/\ntheorem copy_call (site:Copy) (pc finish:Control)\n    (hcode:program (ctl pc)=.call (copyLabel site 0) (ctl finish))\n    (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copySource site)=xs) (hy:before (copyTarget site)=ys) (hz:before scratch=[]) :\n    Runs program (5*xs.length+4) (ctl pc) before (ctl finish)\n      (Function.update before (copyTarget site) (xs++ys)) := by\n  apply included_call program (copyStack site) (copyLabel site) (copy_injective site)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (ctl pc) (ctl finish) hcode (5*xs.length+3)\n    (SemiprimeD1StackCopy.state 0 none xs ys []) (SemiprimeD1StackCopy.done xs (xs++ys)) before _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words xs ys none\n  · constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hz\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update before (copyTarget site) (xs++ys) (copySource site)=xs\n        rw [Function.update_of_ne (copy_source_ne_target site),hx]\n      · exact Function.update_self _ _ _\n      · change Function.update before (copyTarget site) (xs++ys) scratch=[]\n        rw [Function.update_of_ne (copy_scratch_ne_target site),hz]\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 he.symm) _ _\n/-- Each real reversal has distinct input and output roles. -/\ntheorem reverse_ne (second:Bool) : reverseStack second 0≠reverseStack second 1 := by cases second <;> decide\n/-- One real consuming reversal call includes every pop/push, EOF, halt and caller return. -/\ntheorem reverse_call (second:Bool) (pc finish:Control)\n    (hcode:program (ctl pc)=.call (reverseLabel second 0) (ctl finish))\n    (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (reverseStack second 0)=xs) (hy:before (reverseStack second 1)=ys) :\n    Runs program (2*xs.length+3) (ctl pc) before (ctl finish)\n      (Function.update (Function.update before (reverseStack second 0) [])\n        (reverseStack second 1) (xs.reverse++ys)) := by\n  apply included_call program (reverseStack second) (reverseLabel second) (reverse_injective second)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) (ctl pc) (ctl finish) hcode (2*xs.length+2)\n    (SemiprimeD1StackReverseWord.state none xs ys) (SemiprimeD1StackReverseWord.done (xs.reverse++ys)) before _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackReverseWord.reverse_run xs ys none\n  · constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update (Function.update before (reverseStack second 0) [])\n          (reverseStack second 1) (xs.reverse++ys) (reverseStack second 0)=[]\n        rw [Function.update_of_ne (reverse_ne second),Function.update_self]\n      · exact Function.update_self _ _ _\n    · intro k hk\n      rw [Function.update_of_ne (fun he=>hk 1 he.symm),Function.update_of_ne (fun he=>hk 0 he.symm)]\n/-- One real included field parser consumes one frame and copies its literal word. -/\ntheorem parse_call (what:Field) (bank:Stack→List Bool) (word tail:List Bool)\n    (hi:bank (fieldReader what)=frame word tail) (ho:bank (fieldTarget what)=[])\n    (hs:bank (aux .fieldScratch)=[]) (hv:bank (aux .status)=[]) :\n    Runs program (8*word.length+7) (ctl (.field what)) bank (ctl (.valid what))\n      (Function.update (Function.update (Function.update bank (fieldReader what) tail)\n        (fieldTarget what) word) (aux .status) [true]) :=by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let after:SemiprimeD1StackBytecode.State F.Stack F.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack what) bank before.store bank :=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k <;> simp [fieldStack,before,SemiprimeD1TensorTapeFieldBytecode.initial,\n          SemiprimeD1TensorTapeFieldMachine.contents,hi,ho,hs]\n      · cases k;exact hv\n    · intro k _;rfl\n  apply included_call program (fieldStack what) (fieldLabel what) (field_injective what) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (ctl (.field what)) (ctl (.valid what)) rfl\n    (8*word.length+6) before after _ _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin\n  have h0:=Link.data_update (fieldStack what) (field_injective what) bank before.store bank hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack what) (field_injective what) bank _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack what) (field_injective what) bank _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update before.store (.inl .input) tail)\n      (.inl .output) word) (.inr ()) [true]=after.store :=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  simpa only [he,fieldStack] using h2\nend RiemannGaussian.SemiprimeD1StackMarkedRootRecordsPrimitives\n","RiemannGaussian.SemiprimeD1StackNetworkRowsFactors":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkRowsRecords\nimport RiemannGaussian.SemiprimeD1StackNetworkRowsRow\n/-! # Actual complete factor record, all actual port scans, row logger and factor/occurrence tallies -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkRowsFactors\nopen SemiprimeD1StackNetworkRows SemiprimeD1StackNetworkRowsPrimitives SemiprimeD1StackNetworkRowsView\nopen SemiprimeD1StackNetworkRowsEncoding SemiprimeD1StackNetworkRowsPorts SemiprimeD1StackNetworkRowsRow\nopen SemiprimeD1StackNetworkRowsRecords SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Mathematical expected row from the physical local-port order; never a runtime owner supplier. -/\ndef rowWords (route:Nat→List Bool) (v:SemiprimeD1LeafCounter.Vertex) :List (List Bool) :=v.ports.map route\n/-- Actual full-factor cap sums the actual parser, lookup-loop, row-construction and row-log caps. -/\ndef factorBudget (n:Nat) (dictionary:List Bool) (v:SemiprimeD1LeafCounter.Vertex) :Nat :=\n  8*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n  9*(SemiprimeD1TensorTapeCodec.tape v.table).length+18+\n  1000*(n+dictionary.length+2)*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n  40*(2*(n+2)*v.ports.length+2)\n/-- Each expected owner is identified by the actual singleton scan of the actual acquired catalogue. -/\ntheorem related_ports (ports:List Nat) (route:Nat→List Bool) (rows:List (List Bool×List Bool)) (n:Nat)\n    (hp:∀p∈ports,SemiprimeD1StackOwnerFibre.values (SemiprimeD1StackUnaryDivmod.unary p) rows=[route p] ∧ (route p).length≤ n+1) :\n    List.Forall₂ (fun key owner=>SemiprimeD1StackOwnerFibre.values key rows=[owner] ∧ owner.length≤ n+1)\n      (ports.map SemiprimeD1StackUnaryDivmod.unary) (ports.map route) :=by\n  induction ports with\n  | nil=>exact List.Forall₂.nil\n  | cons p ports ih=>\n    exact List.Forall₂.cons (hp p (List.mem_cons_self)) (ih (fun q hq=>hp q (List.mem_cons_of_mem p hq)))\n/-- WHOLEactual factor step: parse/drain the complete table, resolve/log every port, emit ONErow and tallyONEfactor. -/\ntheorem factor_step (index:I.Stack→List Bool) (tail history factors occurrences:List Bool)\n    (v:SemiprimeD1LeafCounter.Vertex) (route:Nat→List Bool) (rows:List (List Bool×List Bool)) (n:Nat)\n    (hd:index .output=SemiprimeD1StackOwnerFibre.records rows [])\n    (hp:∀p∈v.ports,SemiprimeD1StackOwnerFibre.values (SemiprimeD1StackUnaryDivmod.unary p) rows=[route p] ∧ (route p).length≤ n+1) :\n    ∃q≤ factorBudget n (SemiprimeD1StackOwnerFibre.records rows []) v,Runs program q (ctl .factorLoop)\n      (view index (SemiprimeD1StackNetworkOwnerIndexLoop.vertexBytes v++tail) [] [] history factors occurrences) (ctl .factorLoop)\n      (view index tail [] [] ((chunk (SemiprimeD1TensorTapeCodec.vectorBits (rowWords route v))).reverse++history)\n        (true::factors) (List.replicate v.ports.length true++occurrences)) :=by\n  have h0:=factor_fields index history factors occurrences (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n    (SemiprimeD1TensorTapeCodec.tape v.table) tail\n  rw [←SemiprimeD1StackNetworkOwnerIndexLoop.vertexBytes_append] at h0\n  obtain ⟨b,hb,h1⟩:=ports_run index tail [] history factors occurrences\n    (v.ports.map SemiprimeD1StackUnaryDivmod.unary) (v.ports.map route) rows n hd (related_ports v.ports route rows n hp)\n  simp only [List.append_nil,List.length_map] at h1\n  have hw:∀w∈rowWords route v,w.length≤ n+1:=by\n    intro w hw\n    obtain ⟨p,hp0,rfl⟩:=List.mem_map.mp hw\n    exact (hp p hp0).2\n  obtain ⟨c,hc,h2⟩:=finish_row_bounded index tail history factors\n    (List.replicate v.ports.length true++occurrences) (rowWords route v) n hw\n  have hh:=join (join h0 h1) h2\n  have hpClock:=portClock_le n (SemiprimeD1StackOwnerFibre.records rows []) (v.ports.map SemiprimeD1StackUnaryDivmod.unary)\n  change portClock n (SemiprimeD1StackOwnerFibre.records rows []) (v.ports.map SemiprimeD1StackUnaryDivmod.unary)≤\n    1000*(n+(SemiprimeD1StackOwnerFibre.records rows []).length+2)*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length at hpClock\n  have hl:(rowWords route v).length=v.ports.length:=by simp only [rowWords,List.length_map]\n  rw [hl] at hc\n  refine ⟨(8*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length+\n    9*(SemiprimeD1TensorTapeCodec.tape v.table).length+18)+b+c,?_,hh⟩\n  unfold factorBudget\n  omega\n/-- Per-factor primitive caps are charged by ACTUALvertex-record bytes and the ACTUALcatalogue width. -/\ntheorem factorBudget_le (n:Nat) (dictionary:List Bool) (v:SemiprimeD1LeafCounter.Vertex) :\n    factorBudget n dictionary v≤ 10000*(n+dictionary.length+2)*(SemiprimeD1StackNetworkOwnerIndexLoop.vertexBytes v).length :=by\n  have hl:=vector_length (v.ports.map SemiprimeD1StackUnaryDivmod.unary)\n  change (SemiprimeD1StackVertexReadExecution.portTape v.ports).length=\n    2*((v.ports.map SemiprimeD1StackUnaryDivmod.unary).map List.length).sum+2*(v.ports.map SemiprimeD1StackUnaryDivmod.unary).length+1 at hl\n  rw [List.length_map] at hl\n  have hd:v.ports.length≤(SemiprimeD1StackVertexReadExecution.portTape v.ports).length:=by omega\n  have hprod:80*(n+2)*v.ports.length≤ 80*(n+dictionary.length+2)*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length:=by gcongr;omega\n  rw [SemiprimeD1StackNetworkOwnerIndexLoop.vertexBytes_length]\n  unfold factorBudget\n  nlinarith [Nat.zero_le (n*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length),\n    Nat.zero_le (dictionary.length*(SemiprimeD1StackVertexReadExecution.portTape v.ports).length),\n    Nat.zero_le (n*(SemiprimeD1TensorTapeCodec.tape v.table).length),\n    Nat.zero_le (dictionary.length*(SemiprimeD1TensorTapeCodec.tape v.table).length)]\n/-- Exact sum of ACTUALfactor caps is paid by the actual original factor-record prefix. -/\ntheorem factorsBudget_le (n:Nat) (dictionary:List Bool) (factors:List SemiprimeD1LeafCounter.Vertex) :\n    (factors.map (factorBudget n dictionary)).sum≤ 10000*(n+dictionary.length+2)*\n      (SemiprimeD1StackNetworkOwnerIndexLoop.vertexPrefix factors).length :=by\n  induction factors with\n  | nil=>simp [SemiprimeD1StackNetworkOwnerIndexLoop.vertexPrefix]\n  | cons v factors ih=>\n    have h:=factorBudget_le n dictionary v\n    change factorBudget n dictionary v+(factors.map (factorBudget n dictionary)).sum≤\n      10000*(n+dictionary.length+2)*(SemiprimeD1StackNetworkOwnerIndexLoop.vertexBytes v++SemiprimeD1StackNetworkOwnerIndexLoop.vertexPrefix factors).length\n    rw [List.length_append,Nat.mul_add]\n    exact Nat.add_le_add h ih\nend RiemannGaussian.SemiprimeD1StackNetworkRowsFactors\n","RiemannGaussian.SemiprimeD1StackNetworkRowsPorts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNetworkRowsLookup\n/-! # Actual per-factor port→catalogue scan→binary-owner vector loop\nKey and expected-owner lists below are proof descriptions of actual parsed and\nreturned words. The program accepts ONLYthe original record/count tapes, and\nperforms every dictionary copy, lookup, singleton test, frame and tally push.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackNetworkRowsPorts\nopen SemiprimeD1StackNetworkRows SemiprimeD1StackNetworkRowsPrimitives\nopen SemiprimeD1StackNetworkRowsView SemiprimeD1StackNetworkRowsEncoding SemiprimeD1StackNetworkRowsLookup\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => Label.local\n/-- Paid actual per-query cap in physical dictionary/key bytes and actual acquired owner width. -/\ndef portBudget (n:Nat) (dictionary key:List Bool) :Nat :=\n  100*(key.length+1)*(dictionary.length+1)+5*dictionary.length+9*key.length+19*(n+1)+41\n/-- Whole physical port-loop cap, including its final actual FALSEvector-tag pop. -/\ndef portClock (n:Nat) (dictionary:List Bool) (keys:List (List Bool)) :Nat :=\n  (keys.map (portBudget n dictionary)).sum+1\n/-- One actual parsed port copies/scans the actual catalogue and counts exactly ONEreturned/validated owner. -/\ntheorem port_step (index:I.Stack→List Bool) (reader rowHistory history factors occurrences key owner:List Bool)\n    (keys:List (List Bool)) (rows:List (List Bool×List Bool)) (n:Nat)\n    (hd:index .output=SemiprimeD1StackOwnerFibre.records rows [])\n    (hs:SemiprimeD1StackOwnerFibre.values key rows=[owner]) (hw:owner.length≤ n+1) :\n    ∃q≤ portBudget n (SemiprimeD1StackOwnerFibre.records rows []) key,\n      Runs program q (ctl .portLoop) (view index reader (vectorBits (key::keys)) rowHistory history factors occurrences)\n        (ctl .portLoop) (view index reader (vectorBits keys) ((chunk owner).reverse++rowHistory) history factors (true::occurrences)) :=by\n  let tail:=vectorBits keys\n  let b1:=view index reader (frame key tail) rowHistory history factors occurrences\n  let clean:=view index reader tail rowHistory history factors occurrences\n  let b2:=Function.update (Function.update clean (aux .key) key) (aux .valid) [true]\n  have h0:=pop_run .portLoop (ctl .abort) (ctl .rowSeed) (ctl .keyField) (aux .ports)\n    (view index reader (vectorBits (key::keys)) rowHistory history factors occurrences) (true::frame key tail) rfl rfl\n  change Runs program 1 (ctl .portLoop) _ (ctl .keyField)\n    (Function.update (view index reader (vectorBits (key::keys)) rowHistory history factors occurrences) (aux .ports) (frame key tail)) at h0\n  rw [view_ports] at h0\n  have h1:=field_call .key .keyField .keyValid rfl b1 key tail rfl rfl rfl rfl\n  change Runs program (8*key.length+7) (ctl .keyField) b1 (ctl .keyValid)\n    (Function.update (Function.update (Function.update b1 (aux .ports) tail) (aux .key) key) (aux .valid) [true]) at h1\n  rw [view_ports] at h1\n  have h2:=pop_run .keyValid (ctl .abort) (ctl .abort) (ctl .copyDictionary) (aux .valid) b2 [true] rfl rfl\n  have he2:Function.update b2 (aux .valid) []=keyed index reader tail rowHistory history factors occurrences key:=by\n    funext k;rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · cases k <;> rfl\n  change Runs program 1 (ctl .keyValid) b2 (ctl .copyDictionary) (Function.update b2 (aux .valid) []) at h2\n  rw [he2] at h2\n  obtain ⟨b,hb,h3⟩:=lookup_run index reader tail rowHistory history factors occurrences key owner rows hd hs\n  have h4:=singleton_run index reader tail rowHistory history factors occurrences key owner\n  have h5:=emit_owner index reader tail rowHistory history factors occurrences key owner\n  have hh:=join (join (join (join (join h0 h1) h2) h3) h4) h5\n  refine ⟨1+(8*key.length+7)+1+b+(8*owner.length+11)+(11*owner.length+key.length+16),?_,hh⟩\n  unfold portBudget SemiprimeD1StackOwnerFibreBounds.runBound at *\n  omega\n/-- One real FALSEvector-tag pop ends the current factor's local port stream. -/\ntheorem port_end (index:I.Stack→List Bool) (reader rowHistory history factors occurrences:List Bool) :\n    Runs program 1 (ctl .portLoop) (view index reader (vectorBits []) rowHistory history factors occurrences)\n      (ctl .rowSeed) (view index reader [] rowHistory history factors occurrences) :=by\n  have h:=pop_run .portLoop (ctl .abort) (ctl .rowSeed) (ctl .keyField) (aux .ports)\n    (view index reader (vectorBits []) rowHistory history factors occurrences) [false] rfl rfl\n  rw [view_ports] at h\n  exact h\n/-- Whole actual port loop, with semantic singleton facts derived later for EVERYoriginal well-formed network. -/\ntheorem ports_run (index:I.Stack→List Bool) (reader rowHistory history factors occurrences:List Bool)\n    (keys owners:List (List Bool)) (rows:List (List Bool×List Bool)) (n:Nat)\n    (hd:index .output=SemiprimeD1StackOwnerFibre.records rows [])\n    (hp:List.Forall₂ (fun key owner=>SemiprimeD1StackOwnerFibre.values key rows=[owner] ∧ owner.length≤ n+1) keys owners) :\n    ∃q≤ portClock n (SemiprimeD1StackOwnerFibre.records rows []) keys,\n      Runs program q (ctl .portLoop) (view index reader (vectorBits keys) rowHistory history factors occurrences)\n        (ctl .rowSeed)\n        (view index reader [] ((payload owners).reverse++rowHistory) history factors (List.replicate owners.length true++occurrences)) :=by\n  induction hp generalizing rowHistory occurrences with\n  | nil=>\n    refine ⟨1,by rfl,?_⟩\n    exact port_end index reader rowHistory history factors occurrences\n  | @cons key owner keys owners h hp ih=>\n    obtain ⟨b,hb,h0⟩:=port_step index reader rowHistory history factors occurrences key owner keys rows n hd h.1 h.2\n    obtain ⟨c,hc,h1⟩:=ih ((chunk owner).reverse++rowHistory) (true::occurrences)\n    have hh:=join h0 h1\n    refine ⟨b+c,?_,?_⟩\n    · unfold portClock at *\n      simp only [List.map_cons,List.sum_cons]\n      omega\n    · have hrep:List.replicate owners.length true++true::occurrences=List.replicate (owners.length+1) true++occurrences:=by\n        rw [show List.replicate (owners.length+1) true=List.replicate owners.length true++[true] from List.replicate_add _ _ _]\n        rw [List.append_assoc]\n        rfl\n      simpa only [payload,List.foldr_cons,List.reverse_append,List.append_assoc,List.length_cons,hrep] using hh\n/-- Fixed physical-byte cap for one actual scan and scalar/port cleanup. -/\ntheorem portBudget_le (n:Nat) (dictionary key:List Bool) :\n    portBudget n dictionary key≤ 500*(n+dictionary.length+2)*(key.length+1) :=by\n  unfold portBudget\n  nlinarith [Nat.zero_le (n*key.length),Nat.zero_le (dictionary.length*key.length)]\n/-- Sum of query costs is charged by ACTUALport tape bytes, not a supplied arity/lookup estimate. -/\ntheorem portClock_le (n:Nat) (dictionary:List Bool) (keys:List (List Bool)) :\n    portClock n dictionary keys≤ 1000*(n+dictionary.length+2)*(vectorBits keys).length :=by\n  have hs:(keys.map (portBudget n dictionary)).sum≤ 500*(n+dictionary.length+2)*\n      ((keys.map List.length).sum+keys.length):=by\n    induction keys with\n    | nil=>simp\n    | cons key keys ih=>\n      have h:=portBudget_le n dictionary key\n      simp only [List.map_cons,List.sum_cons,List.length_cons]\n      nlinarith only [h,ih]\n  have hl:=vector_length keys\n  let S:=(keys.map List.length).sum+keys.length\n  let K:=500*(n+dictionary.length+2)\n  have hK:1≤ K:=by dsimp [K];omega\n  have hS:S+1≤(vectorBits keys).length:=by dsimp [S];omega\n  calc\n    portClock n dictionary keys≤ K*(S+1):=by\n      unfold portClock\n      rw [Nat.mul_add,Nat.mul_one]\n      change (keys.map (portBudget n dictionary)).sum+1≤ 500*(n+dictionary.length+2)*S+K\n      change (keys.map (portBudget n dictionary)).sum≤ 500*(n+dictionary.length+2)*S at hs\n      omega\n    _≤ K*(vectorBits keys).length:=Nat.mul_le_mul_left K hS\n    _≤ 1000*(n+dictionary.length+2)*(vectorBits keys).length:=\n      Nat.mul_le_mul_right _ (Nat.mul_le_mul_right _ (by decide :500≤ 1000))\nend RiemannGaussian.SemiprimeD1StackNetworkRowsPorts\n","RiemannGaussian.SemiprimeD1StackOwnerEqualityKeyBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerEqualityKey\n/-! # Actual transition and all-prefix cell bounds for endpoint sentinel-copy -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeD1StackOwnerEqualityKeyBounds\nopen SemiprimeD1StackOwnerEqualityKey\n/-- The acquired-record stage has one actual input tape and no preloaded output. -/\ntheorem initial_eq (record:List Bool) :\n    Turing.initList machine record=SemiprimeD1StackCalls.configuration (initial record) := by\n  have hs:initial record=SemiprimeD1StackCalls.initial (0:Stack) (.inl 0:Label) record := by\n    unfold initial SemiprimeD1StackCalls.initial\n    congr 1\n    funext k;fin_cases k <;> rfl\n  rw [hs]\n  exact (SemiprimeD1StackCalls.initial_correct (0:Stack) 1 (.inl 0:Label) program record).symm\n/-- No successful prefix can execute past the actual final halt. -/\ntheorem prefix_fuel (record:List Bool) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial record)=some out) : fuel≤5*record.length+6 := by\n  by_contra hn\n  have h:fuel=(5*record.length+6)+(1+(fuel-(5*record.length+7))):=by omega\n  rw [h,SemiprimeD1StackReturnLink.run_add,source_run,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add] at hr\n  have hz:C.run program 1 (done record)=none:=rfl\n  rw [hz,Option.bind_none] at hr\n  cases hr\n/-- All three Boolean data stacks and actual return frames at EVERY prefix. -/\ntheorem prefix_cells (record:List Bool) (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial record)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤23*record.length+24 := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel record.length _ out (by\n    intro k;fin_cases k <;> simp [initial,SemiprimeD1StackCopy.payload]) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤3*(record.length+fuel):=by\n    calc\n      _≤∑_k:Stack,(record.length+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp\n  have ht:=prefix_fuel record fuel out hr\n  omega\n/-- Actual fixed finite-machine execution certificate, not a retained clock. -/\nnoncomputable def keyInTime (record:List Bool) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine record)\n      (some (SemiprimeD1StackCalls.configuration (done record))) (5*record.length+6) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect (0:Stack) 1 (.inl 0:Label) program\n  exact ⟨⟨5*record.length+6,source_run record⟩,le_rfl⟩\nend RiemannGaussian.SemiprimeD1StackOwnerEqualityKeyBounds\n","RiemannGaussian.SemiprimeD1StackOwnerFibreBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerFibreExecution\n/-! # Actual scan cost and every physical stack/return cell at every prefix -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerFibreBounds\nopen SemiprimeD1StackOwnerFibre SemiprimeD1StackOwnerFibreExecution\nopen SemiprimeSourceHistogramKeyBits (frame_length)\n/-- Exact actual stream inventory, counting both padded ID fields. -/\ntheorem records_length (rows:List (List Bool×List Bool)) (tail:List Bool) :\n    (records rows tail).length=2*(rows.map (fun x=>x.1.length+x.2.length)).sum+3*rows.length+tail.length+1 :=\n  SemiprimeD1StackOwnerLookupBounds.records_length rows tail\n/-- Physical emission never creates more selected row bytes than its source inventory. -/\ntheorem selected_length (query:List Bool) (rows:List (List Bool×List Bool)) :\n    (selected query rows).length≤2*(rows.map (fun x=>x.1.length+x.2.length)).sum+2*rows.length := by\n  induction rows with\n  | nil=>simp [selected,values]\n  | cons row rows ih=>\n    rcases row with ⟨key,value⟩\n    rw [selected_cons]\n    split_ifs <;> simp only [List.length_append,List.length_cons,frame_length,List.length_nil,\n      List.map_cons,List.sum_cons,List.length_cons] <;> omega\n/-- Every row pays two parsers, equality, selected framing and payload erasure. -/\ntheorem loopTime_le (query:List Bool) (rows:List (List Bool×List Bool)) :\n    loopTime query rows≤20*(rows.map (fun x=>x.1.length+x.2.length)).sum+(7*query.length+43)*rows.length+1 := by\n  induction rows with\n  | nil=>simp [loopTime]\n  | cons row rows ih=>\n    rcases row with ⟨key,value⟩\n    have he:=SemiprimeD1StackWordEqualExecution.executionTime_le key query\n    simp only [loopTime,List.map_cons,List.sum_cons,List.length_cons]\n    split_ifs <;> nlinarith\n/-- Fixed polynomial in actual acquired bytes and actual query width. -/\ndef runBound (query:List Bool) (rows:List (List Bool×List Bool)) : ℕ :=\n  100*(query.length+1)*((records rows []).length+1)\ntheorem time_le (query:List Bool) (rows:List (List Bool×List Bool)) :\n    totalTime query rows≤runBound query rows := by\n  have h:=loopTime_le query rows\n  have hsel:=selected_length query rows\n  unfold runBound\n  rw [records_length]\n  simp only [List.length_nil,Nat.add_zero]\n  let K:=100*(query.length+1)\n  let s:=(rows.map (fun x=>x.1.length+x.2.length)).sum\n  have hs:24*s≤K*(2*s) := by\n    calc\n      _≤(K*2)*s:=Nat.mul_le_mul_right s (by dsimp [K];omega)\n      _=_:=by ring\n  have hr:(7*query.length+47)*rows.length≤K*(3*rows.length) := by\n    calc\n      _≤(K*3)*rows.length:=Nat.mul_le_mul_right rows.length (by dsimp [K];omega)\n      _=_:=by ring\n  have hc:8≤K*2:=by dsimp [K];omega\n  calc\n    _≤24*s+(7*query.length+47)*rows.length+8:=by\n      unfold totalTime\n      dsimp [s]\n      nlinarith only [h,hsel]\n    _≤K*(2*s)+K*(3*rows.length)+K*2:=Nat.add_le_add (Nat.add_le_add hs hr) hc\n    _=_:=by dsimp [K,s];ring\n/-- The physically routed-port fibre source has a SAME-code time certificate. -/\ndef sourceFibre (query:List Bool) (rows:List (List Bool×List Bool)) (tail:List Bool) :\n    StateTransition.EvalsToInTime (C.step program) (initial query (records rows tail))\n      (some (done query rows tail)) (runBound query rows) :=\n  ⟨⟨_,source_run query rows tail⟩,time_le query rows⟩\n/-- One fixed finite machine, with the same actual lookup trace. -/\ndef machineFibre (query:List Bool) (rows:List (List Bool×List Bool)) (tail:List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial query (records rows tail)))\n      (some (SemiprimeD1StackCalls.configuration (done query rows tail))) (runBound query rows) :=\n  SemiprimeD1StackCalls.evalsCorrect (.inr .reader:Stack) (.inr .output:Stack) Label.loop program _ _ _\n    (sourceFibre query rows tail)\ntheorem prefix_fuel_le (query:List Bool) (rows:List (List Bool×List Bool)) (tail:List Bool)\n    (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial query (records rows tail))=some out) : fuel≤totalTime query rows := by\n  by_contra hn\n  have he:fuel=totalTime query rows+(1+(fuel-(totalTime query rows+1))):=by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,source_run,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add] at hr\n  have hz:C.run program 1 (done query rows tail)=none:=rfl\n  rw [hz,Option.bind_none] at hr\n  cases hr\n/-- Every prefix counts all fourteen actual Bool roles and actual return frames. -/\ntheorem prefix_cells (query:List Bool) (rows:List (List Bool×List Bool)) (tail:List Bool)\n    (fuel:ℕ) (out:C.State Stack Label)\n    (hr:C.run program fuel (initial query (records rows tail))=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length≤\n      15*(query.length+(records rows tail).length+runBound query rows) := by\n  let I:=query.length+(records rows tail).length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (by\n    intro k;rcases k with k|k <;> cases k <;> simp [initial,data,SemiprimeD1StackAdder.store,I]) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length)≤14*(I+fuel):=by\n    calc\n      _≤∑_k:Stack,(I+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _=_:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=(prefix_fuel_le query rows tail fuel out hr).trans (time_le query rows)\n  change _≤15*(I+runBound query rows)\n  omega\n/-- Same complete inventory for every genuine compiled-machine prefix. -/\ntheorem machine_prefix_cells (query:List Bool) (rows:List (List Bool×List Bool)) (tail:List Bool)\n    (fuel:ℕ) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial query (records rows tail))))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      15*(query.length+(records rows tail).length+runBound query rows) := by\n  have he:=SemiprimeD1StackCalls.run_correct (.inr .reader) (.inr .output) Label.loop program fuel\n    (initial query (records rows tail))\n  change (C.run program fuel (initial query (records rows tail))).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial query (records rows tail)))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial query (records rows tail)) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells query rows tail fuel out hc\nend RiemannGaussian.SemiprimeD1StackOwnerFibreBounds\n","RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogue":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOwnerRoutingResources\n/-! # N-only actual all-original-owner fibre catalogue source\nAfter actual original routing, the source copies its retained E tally and M-ID\nbank. It physically reads the FIRST E bank words, copies the actual routed tape\nfor every owner, executes real fibre filtering and emits each owner with its\nactual ordered scope-ID vector. No owner list, E/M count, scope list, degree or\npermutation is supplied. Execution proofs follow in separate modules.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogue\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run step execute)\nend C\nnamespace R\nexport SemiprimeD1StackPortOwnerRouting (Stack Label program originalInput input)\nend R\nnamespace V\nexport SemiprimeD1StackOwnerFibre (Stack Label program)\nend V\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Nine fixed reader, actual E-loop, parser and output-collector roles. -/\ninductive Aux where\n  | readerIds | ownerCount | copyScratch | fieldScratch | valid | frameBuffer | frameScratch | reversed | output\n  deriving DecidableEq\ninstance : Fintype Aux :=Fintype.ofList [.readerIds,.ownerCount,.copyScratch,.fieldScratch,.valid,\n  .frameBuffer,.frameScratch,.reversed,.output] (by intro k;cases k <;> simp)\n/-- Complete actual routing source, real fourteen-role fibre filter and nine private outer roles. -/\nabbrev Stack :=R.Stack⊕(V.Stack⊕Aux)\n/-- Actual upstream N-only routing inclusion, retained across ALL owners. -/\ndef source (k:R.Stack) : Stack :=.inl k\n/-- Actual numeric owner-fibre filter inclusion. -/\ndef fibreStack (k:V.Stack) : Stack :=.inr (.inl k)\n/-- Actual private outer metadata/reader/output role. -/\ndef aux (k:Aux) : Stack :=.inr (.inr k)\n/-- Only original binary N is initially loaded. -/\ndef originalInput : Stack :=source R.originalInput\n/-- Actual original E tally retained from the physical old edge scan. -/\ndef sourceCount : Stack :=source (SemiprimeD1StackPortOwnerRouting.mapStack\n  (SemiprimeD1StackOwnerCatalogue.source SemiprimeD1StackRootScopeBank.wireCount))\n/-- Actual original M-word bank retained from real tally allocation and increment generation. -/\ndef sourceIds : Stack :=source (SemiprimeD1StackPortOwnerRouting.mapStack\n  (SemiprimeD1StackOwnerCatalogue.source SemiprimeD1StackRootScopeBank.ids))\n/-- Actual computed factor-major original owner/scope routing tape. -/\ndef sourcePairs : Stack :=source (SemiprimeD1StackPortOwnerRouting.aux .output)\n/-- Actual preserving E-count, whole M-bank and per-owner routed-tape copies. -/\ndef copyStack (part:Fin 3) (k:Fin 3) : Stack :=\n  if k=0 then (if part=0 then sourceCount else if part=1 then sourceIds else sourcePairs)\n  else if k=1 then (if part=0 then aux .ownerCount else if part=1 then aux .readerIds else fibreStack (.inr .reader))\n  else aux .copyScratch\n/-- The next owner query is physically parsed from the actual bank into the real filter's query role. -/\ndef fieldStack : F.Stack→Stack\n  | .inl .input=>aux .readerIds | .inl .scratch=>aux .fieldScratch\n  | .inl .output=>fibreStack (.inr .query) | .inr _=>aux .valid\n/-- Actual output is owner ID then its complete ACTUALLY filtered ordered scope-ID vector bytes. -/\ndef frameStack (scopes:Bool) (k:Fin 3) : Stack :=\n  if k=0 then fibreStack (.inr (if scopes then .output else .query))\n  else if k=1 then aux .frameBuffer else aux .frameScratch\n/-- Actual per-field or whole-catalogue physical reversal. -/\ndef reverseStack (finish:Bool) (k:Fin 2) : Stack :=\n  if k=0 then (if finish then aux .reversed else aux .frameBuffer)\n  else if finish then aux .output else aux .reversed\n/-- ALL fourteen actually used filter words are physically drained between original owners. -/\ndef fibreRole : Fin 14→V.Stack :=\n  ![.inl .left,.inl .right,.inl .scratch,.inl .output,.inr .query,.inr .reader,\n    .inr .fieldScratch,.inr .valid,.inr .copyScratch,.inr .payload,.inr .output,\n    .inr .frameBuffer,.inr .frameScratch,.inr .reversed]\n/-- Finite original E-loop and physical parser/logger positions. -/\ninductive Control where\n  | main | copyCount | copyIds | loop | bankTag | field | valid | copyPairs | filter | emitTag\n  | emitField (scopes:Bool) | emitReverse (scopes:Bool) | clearFibre (part:Fin 14)\n  | finalTag | finalReverse | halt | abort\n  deriving Fintype\n/-- Static source/filter and real bytecode call labels, all fixed before every N. -/\ninductive Label where\n  | local (pc:Control) | source (pc:R.Label) | fibre (pc:V.Label)\n  | copy (part:Fin 3) (pc:Fin 9) | field (pc:F.Label)\n  | frame (scopes:Bool) (pc:Fin 11) | reverse (finish:Bool) (pc:Fin 4)\n  deriving Fintype\n/-- Actual original-N acquisition and FIRST-E-owner loop, with no E=M or 2e+endpoint assumption. -/\ndef program : Label→C.Instruction Stack Label\n  | .source pc=>SemiprimeD1StackValidationLink.instruction source Label.source (R.program pc)\n  | .fibre pc=>SemiprimeD1StackValidationLink.instruction fibreStack Label.fibre (V.program pc)\n  | .copy part pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack part) (Label.copy part) (SemiprimeD1StackCopy.code pc)\n  | .field pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (F.code pc)\n  | .frame scopes pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack scopes) (Label.frame scopes) (SemiprimeD1StackFrame.code pc)\n  | .reverse finish pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack finish) (Label.reverse finish) (SemiprimeD1StackReverseWord.code pc)\n  | .local .main=>.call (.source (.local .main)) (.local .copyCount)\n  | .local .copyCount=>.call (.copy 0 0) (.local .copyIds)\n  | .local .copyIds=>.call (.copy 1 0) (.local .loop)\n  | .local .loop=>.base (.pop (aux .ownerCount) (.local .finalTag) (.local .abort) (.local .bankTag))\n  | .local .bankTag=>.base (.pop (aux .readerIds) (.local .abort) (.local .abort) (.local .field))\n  | .local .field=>.call (.field (F.active .tagPop (none,false))) (.local .valid)\n  | .local .valid=>.base (.pop (aux .valid) (.local .abort) (.local .abort) (.local .copyPairs))\n  | .local .copyPairs=>.call (.copy 2 0) (.local .filter)\n  | .local .filter=>.call (.fibre .loop) (.local .emitTag)\n  | .local .emitTag=>.base (.push (aux .reversed) true (.local (.emitField false)))\n  | .local (.emitField scopes)=>.call (.frame scopes 0) (.local (.emitReverse scopes))\n  | .local (.emitReverse scopes)=>.call (.reverse false 0)\n      (if scopes then .local (.clearFibre 0) else .local (.emitField true))\n  | .local (.clearFibre part)=>\n      let next:Label:=if h:part.val<13 then .local (.clearFibre ⟨part.val+1,by omega⟩) else .local .loop\n      .base (.pop (fibreStack (fibreRole part)) next (.local (.clearFibre part)) (.local (.clearFibre part)))\n  | .local .finalTag=>.base (.push (aux .reversed) false (.local .finalReverse))\n  | .local .finalReverse=>.call (.reverse true 0) (.local .halt)\n  | .local .halt | .local .abort=>.base .halt\n/-- Original binary N alone, with no owner key, tally, ID bank, scope fibre or count answer input. -/\ndef input (bits:List Bool) : Stack→List Bool :=Sum.elim (R.input bits) (fun _=>[])\n/-- Actual all-owner fibre catalogue entry. -/\ndef initial (bits:List Bool) :C.State Stack Label:=⟨some (.local .main),none,none,input bits,[]⟩\n/-- One fixed genuine finite machine for all original owner-fibre acquisition. -/\ndef machine :Turing.FinTM2:=SemiprimeD1StackCalls.machine originalInput (aux .output) (.local .main) program\n/-- Every data and return alphabet is finite before every original binary input. -/\ntheorem all_alphabets_finite :∀k,Finite (machine.Γ k):=\n  SemiprimeD1StackCalls.all_alphabets_finite originalInput (aux .output) (.local .main) program\n/-- All305 actual data roles, including both retained source banks and real fibre work. -/\ntheorem stack_card :Fintype.card Stack=305:=by decide\nend RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogue\n","RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueRead":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueCalls\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueRead\nopen SemiprimeD1StackOwnerFibreCatalogue SemiprimeD1StackOwnerFibreCatalogueSource\nopen SemiprimeD1StackOwnerFibreCatalogueView SemiprimeD1StackOwnerFibreCatalogueCalls\nopen SemiprimeD1StackProcedureTrace (Runs runs_trans one_base)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Actual empty-reader filter state after its query was physically parsed from the acquired bank. -/\ndef queried (query:List Bool) :V.Stack→List Bool:=\n  (SemiprimeD1StackOwnerFibre.initial query []).data\n/-- Only the next actual owner query is present; every real filter work role remains empty. -/\ntheorem query_update (query:List Bool) :\n    Function.update (fun _:V.Stack=>[]) (.inr .query) query=queried query:=by\n  funext k;rcases k with k|k <;> cases k <;> rfl\n/-- Actual real field-parser result, with its actual validity byte consumed. -/\ntheorem field_read (s:R.Stack→List Bool) (query count ids raw:List Bool) :\n    Runs program (8*query.length+8) (.local .field)\n      (data s (fun _=>[]) (rowAux count (frame query ids) raw)) (.local .copyPairs)\n      (data s (queried query) (rowAux count ids raw)) := by\n  let a:=rowAux count ids raw\n  have hf:=field_call (data s (fun _=>[]) (rowAux count (frame query ids) raw)) query ids rfl rfl rfl rfl\n  have hi:Function.update (rowAux count (frame query ids) raw) .readerIds ids=a:=by\n    funext k;cases k <;> rfl\n  simp only [update_aux,update_fibre,query_update,hi] at hf\n  have hv:Runs program 1 (.local .valid) (data s (queried query) (Function.update a .valid [true]))\n      (.local .copyPairs) (data s (queried query) a):=by\n    apply one_base program _ _ (.pop (aux .valid) (.local .abort) (.local .abort) (.local .copyPairs)) _ _ rfl\n    · simp only [SemiprimeD1StackBytecode.execute,data_aux,Function.update_same,\n        SemiprimeD1StackBytecode.choose,List.head?_cons]\n    · simp only [SemiprimeD1StackBytecode.execute,data_aux,Function.update_same,update_aux,\n        Function.update_idem,List.tail_cons]\n      have he:Function.update a .valid []=a:=by\n        change Function.update a .valid (a .valid)=a\n        exact Function.update_eq_self _ _\n      rw [he]\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hf hv\n  simpa only [show (8*query.length+7)+1=8*query.length+8 by omega,a] using h\n/-- Consume ONE actual E-tally bit and ONE actual vector tag; E and M remain separate domains. -/\ntheorem headers (s:R.Stack→List Bool) (query count ids raw:List Bool) :\n    Runs program 2 (.local .loop) (data s (fun _=>[]) (rowAux (true::count) (true::frame query ids) raw))\n      (.local .field) (data s (fun _=>[]) (rowAux count (frame query ids) raw)) := by\n  let a0:=rowAux (true::count) (true::frame query ids) raw\n  let a1:=rowAux count (true::frame query ids) raw\n  let a2:=rowAux count (frame query ids) raw\n  have hc:Runs program 1 (.local .loop) (data s (fun _=>[]) a0) (.local .bankTag) (data s (fun _=>[]) a1):=by\n    apply one_base program _ _ (.pop (aux .ownerCount) (.local .finalTag) (.local .abort) (.local .bankTag)) _ _ rfl rfl\n    simp only [SemiprimeD1StackBytecode.execute,data_aux,update_aux]\n    congr 1\n    funext k;cases k <;> rfl\n  have ht:Runs program 1 (.local .bankTag) (data s (fun _=>[]) a1) (.local .field) (data s (fun _=>[]) a2):=by\n    apply one_base program _ _ (.pop (aux .readerIds) (.local .abort) (.local .abort) (.local .field)) _ _ rfl rfl\n    simp only [SemiprimeD1StackBytecode.execute,data_aux,update_aux]\n    congr 1\n    funext k;cases k <;> rfl\n  exact runs_trans program _ _ _ _ _ _ _ _ hc ht\n/-- Physically acquire the next original owner query from the actual M bank under the actual E counter. -/\ntheorem query_read (s:R.Stack→List Bool) (query count ids raw:List Bool) :\n    Runs program (8*query.length+10) (.local .loop)\n      (data s (fun _=>[]) (rowAux (true::count) (true::frame query ids) raw)) (.local .copyPairs)\n      (data s (queried query) (rowAux count ids raw)) := by\n  have h:=runs_trans program _ _ _ _ _ _ _ _ (headers s query count ids raw) (field_read s query count ids raw)\n  simpa only [show 2+(8*query.length+8)=8*query.length+10 by omega] using h\n/-- Complete actual routed pair tape is copied into the real filter reader for THIS owner. -/\ntheorem pairs_copy (s:R.Stack→List Bool) (a:Aux→List Bool) (query:List Bool) (hs:a .copyScratch=[]) :\n    Runs program (5*(s (SemiprimeD1StackPortOwnerRouting.aux .output)).length+4) (.local .copyPairs)\n      (data s (queried query) a) (.local .filter)\n      (data s (SemiprimeD1StackOwnerFibre.initial query (s (SemiprimeD1StackPortOwnerRouting.aux .output))).data a) := by\n  have h:=copy_call 2 (data s (queried query) a) (.local .copyPairs) (.local .filter) rfl hs\n  change Runs program _ _ _ _ (Function.update _ (fibreStack (.inr .reader))\n    (s (SemiprimeD1StackPortOwnerRouting.aux .output)++[])) at h\n  rw [List.append_nil,update_fibre] at h\n  have he:Function.update (queried query) (.inr .reader) (s (SemiprimeD1StackPortOwnerRouting.aux .output))=\n      (SemiprimeD1StackOwnerFibre.initial query (s (SemiprimeD1StackPortOwnerRouting.aux .output))).data:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h\n  exact h\n/-- SAME-source actual routed-tape copy followed by real numeric owner-fibre filtering. -/\ntheorem copy_filter_run (s:R.Stack→List Bool) (a:Aux→List Bool) (query:List Bool) (hs:a .copyScratch=[])\n    (rows:List (List Bool×List Bool))\n    (hm:s (SemiprimeD1StackPortOwnerRouting.aux .output)=SemiprimeD1StackOwnerFibre.records rows []) :\n    ∃time≤5*(SemiprimeD1StackOwnerFibre.records rows []).length+\n      SemiprimeD1StackOwnerFibreBounds.runBound query rows+5,\n      Runs program time (.local .copyPairs) (data s (queried query) a) (.local .emitTag)\n        (data s (SemiprimeD1StackOwnerFibre.done query rows []).data a) := by\n  have hc:=pairs_copy s a query hs\n  rw [hm] at hc\n  have hf:=filter_call s a query rows\n  have h:=runs_trans program _ _ _ _ _ _ _ _ hc hf\n  refine ⟨_,?_,h⟩\n  have ht:=SemiprimeD1StackOwnerFibreBounds.time_le query rows\n  omega\nend RiemannGaussian.SemiprimeD1StackOwnerFibreCatalogueRead\n","RiemannGaussian.SemiprimeD1StackOwnerPrefix":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1OwnerPrefixBits\nimport RiemannGaussian.SemiprimeD1StackWordEqualExecution\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\n\n/-! # Actual physical owner-prefix compatibility acquisition\nThe fixed finite program parses actual framed wire keys, copies the retained\nquery key, executes literal binary equality, and reads each original value bit.\nIts two finite compatibility flags are COMPUTED; no prefix/count/allowed oracle\nor numeric value is hidden in its instruction table or transient control.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerPrefix\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace E\nexport SemiprimeD1StackWordEqual (Label code)\nexport SemiprimeD1StackAdder (Stack store)\nend E\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Six literal caller roles, in addition to all four actual equality roles. -/\ninductive Aux where | query | reader | fieldScratch | valid | copyScratch | output\n  deriving DecidableEq,Repr\ninstance : Fintype Aux := Fintype.ofList [.query,.reader,.fieldScratch,.valid,.copyScratch,.output]\n  (by intro k;cases k <;> simp)\n/-- Every data role is a fixed Boolean tape before every wire and prefix. -/\nabbrev Stack := E.Stack⊕Aux\n/-- At most three computed Boolean flags occur in finite control. -/\ninductive Label where\n  | loop (low high : Bool) | parse (low high : Bool) | parsed (low high : Bool)\n  | copyKey (low high : Bool) | compare (low high : Bool) | matched (low high : Bool)\n  | value (low high same : Bool)\n  | high (low high : Bool) | low (low : Bool) | done | abort\n  | field (low high : Bool) (pc : F.Label)\n  | copy (low high : Bool) (pc : Fin 9)\n  | equal (low high : Bool) (pc : E.Label)\n  deriving Fintype\n/-- Literal parser operands share only its actual key output with equality. -/\ndef fieldStack : F.Stack→Stack\n  | .inl .input=>.inr .reader\n  | .inl .scratch=>.inr .fieldScratch\n  | .inl .output=>.inl .left\n  | .inr _=>.inr .valid\n/-- Physical copy preserves query bytes; each comparison consumes its own copy. -/\ndef copyStack (k : Fin 3) : Stack :=\n  if k=0 then .inr .query else if k=1 then .inl .right else .inr .copyScratch\n/-- ONE fixed finite instruction table; all key matching executes actual code. -/\ndef program : Label→C.Instruction Stack Label\n  | .loop low high=>.base (.pop (.inr .reader) (.high low high) (.high low high) (.parse low high))\n  | .parse low high=>.call (.field low high (F.active .tagPop (none,false))) (.parsed low high)\n  | .parsed low high=>.base (.pop (.inr .valid) .abort .abort (.copyKey low high))\n  | .copyKey low high=>.call (.copy low high 0) (.compare low high)\n  | .compare low high=>.call (.equal low high .loop) (.matched low high)\n  | .matched low high=>.base (.pop (.inl .output) .abort (.value low high false) (.value low high true))\n  | .value low high same=>.base (.pop (.inr .reader) .abort\n      (.loop low (high && !same)) (.loop (low && !same) high))\n  | .high low high=>.base (.push (.inr .output) high (.low low))\n  | .low low=>.base (.push (.inr .output) low .done)\n  | .done | .abort=>.base .halt\n  | .field low high pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack (Label.field low high) (F.code pc)\n  | .copy low high pc=>SemiprimeD1StackMultiplierLink.instruction copyStack (Label.copy low high) (SemiprimeD1StackCopy.code pc)\n  | .equal low high pc=>SemiprimeD1StackMultiplierLink.instruction Sum.inl (Label.equal low high) (E.code pc)\n/-- Mathematical projection of physical data; never an executed source getter. -/\ndef data (query reader left right comparison valid output : List Bool) : Stack→List Bool\n  | .inl k=>E.store left right [] comparison k\n  | .inr .query=>query\n  | .inr .reader=>reader\n  | .inr .valid=>valid\n  | .inr .output=>output\n  | .inr .fieldScratch | .inr .copyScratch=>[]\n/-- Only the original binary wire key and actual framed prefix are initial data. -/\ndef initial (query reader : List Bool) : C.State Stack Label :=\n  ⟨some (.loop true true),none,none,data query reader [] [] [] [] [],[]⟩\n/-- Literal complete halt data: retained key/tail and physically acquired flags. -/\ndef done (query : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool) : C.State Stack Label :=\n  let answer:=SemiprimeD1OwnerPrefixBits.scan query rows true true\n  ⟨none,none,none,data query tail [] [] [] [] [answer.1,answer.2],[]⟩\n/-- One actual fixed finite machine, with no key/prefix length in its control. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (.inr .reader) (.inr .output) (.loop true true) program\n/-- All ten actual Boolean roles are included in resource inventory. -/\ntheorem stack_card : Fintype.card Stack=10 := by decide\n/-- Actual key/parser/work ports are distinct. -/\ntheorem field_injective : Function.Injective fieldStack := by decide\n/-- Actual query/comparison/copy-scratch roles are distinct. -/\ntheorem copy_injective : Function.Injective copyStack := by decide\n/-- All data and real return alphabets are fixed and finite. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (.inr .reader) (.inr .output) (.loop true true) program\n/-- Transient flags/labels contain no natural/list/function/table/clock payload. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite (.inr .reader) (.inr .output) (.loop true true) program\nend RiemannGaussian.SemiprimeD1StackOwnerPrefix\n","RiemannGaussian.SemiprimeD1StackOwnerRecordsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordsExecution\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordsNumeric\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecordsBounds\nopen SemiprimeD1StackOwnerRecords SemiprimeD1StackOwnerRecordsView\nopen SemiprimeD1StackOwnerRecordsLoop SemiprimeD1StackOwnerRecordsAcquisition\nopen SemiprimeD1StackOwnerRecordsOriginal SemiprimeD1StackOwnerRecordsNumeric\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (wireCount)\nopen SemiprimeD1OwnerPrefixBits (records)\nopen SemiprimeReportPolynomialGrowth (Bound constant_bound identity_bound add_bound mul_bound)\nnamespace P\nexport SemiprimeD1StackOwnerLookupOriginal.Public (occurrences occurrences_eq encode)\nend P\nnamespace F\nexport SemiprimeD1StackOwnerFibreOriginal (scopeWord scopeWord_length scopeWord_value enumeration enumeration_length original_fibre rows routed)\nend F\n/-- BOTH actual whole305-state retention and real E tally are bounded, without E=M. -/\ndef baseCap (n:Nat) :Nat:=SemiprimeD1StackOwnerFibreCatalogueBounds.baseCap n+\n  306*(n+SemiprimeD1StackOwnerFibreCatalogueBounds.polynomial n)\n/-- Whole actual source bound in original input length and physically present caller prefix bytes. -/\ndef runCap (n P:Nat) :Nat:=SemiprimeD1StackOwnerFibreCatalogueBounds.polynomial n+5*baseCap n+\n  3*baseCap n*rowCap (2*baseCap n) P+100\n/-- Fixed EMPTY-prefix original-N polynomial, accounting for real prefix initialization. -/\ndef polynomial (n:Nat) :Nat:=runCap n 1\n/-- Actual retained catalogue byte bound comes from its OWN source's full physical inventory. -/\ntheorem catalogue_length (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    (catalogueBytes bits hN).length≤baseCap bits.length:=by\n  obtain ⟨t,_,hr⟩:=SemiprimeD1StackOwnerFibreCatalogueBounds.source_run_polynomial bits hc hN\n  have hs:=SemiprimeD1StackOwnerFibreCatalogueResources.prefix_cells bits hc hN t _ hr\n  have ho:=Finset.single_le_sum (fun k (_:k∈(Finset.univ:Finset S.Stack))=>\n    Nat.zero_le (((SemiprimeD1StackOwnerFibreCatalogueExecution.done bits hN).data k).length))\n    (Finset.mem_univ (SemiprimeD1StackOwnerFibreCatalogue.aux .output))\n  change (∑k:S.Stack,((SemiprimeD1StackOwnerFibreCatalogueExecution.done bits hN).data k).length)+0≤_ at hs\n  unfold catalogueBytes baseCap;omega\ntheorem owners_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    wireCount (bitValue bits)≤baseCap bits.length:=by\n  have h:=SemiprimeD1StackOwnerFibreCatalogueBounds.count_bound bits hc hN\n  unfold baseCap;omega\ntheorem occurrences_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    P.occurrences (bitValue bits)≤2*baseCap bits.length:=by\n  rw [P.occurrences_eq _ hN]\n  exact Nat.mul_le_mul_left 2 (owners_bound bits hc hN)\n/-- Generic selection keeps only ACTUAL payloads; it never changes a selected scope word. -/\ntheorem values_all (query:List Bool) (rows:List (List Bool×List Bool)) (PropWord:List Bool→Prop)\n    (h:∀pair∈rows,PropWord pair.2) :∀w∈SemiprimeD1StackOwnerFibre.values query rows,PropWord w:=by\n  induction rows with\n  | nil=>simp only [SemiprimeD1StackOwnerFibre.values,List.not_mem_nil,IsEmpty.forall_iff,implies_true]\n  | cons pair rows ih=>\n    have ht:=ih (fun p hp=>h p (List.mem_cons_of_mem pair hp))\n    have hh:=h pair List.mem_cons_self\n    rcases pair with ⟨owner,scope⟩\n    simp only [SemiprimeD1StackOwnerFibre.values]\n    split\n    · intro w hw\n      rcases List.mem_cons.mp hw with he|he\n      · simpa only [he] using hh\n      · exact ht w he\n    · exact ht\n/-- Generic opaque-enumeration rank bound, proved BEFORE original-N specialization. -/\ntheorem enumeration_rank_bound {A:Type} [DecidableEq A]\n    (en:OAI.Algorithms.SubexponentialSAT.Subexp.ConstructivePacking.FiniteEnumeration A) (p:A) :\n    (en.equivFin.symm p).val≤en.values.length:=\n  (en.equivFin.symm p).isLt.le\n/-- Physical original scope value is bounded through the SAME generic rank theorem. -/\ntheorem scope_value_bound (N:Nat) (p:SemiprimeD1RootTensorTables.Port N) :\n    bitValue (F.scopeWord N p)≤P.occurrences N:=by\n  have h:=enumeration_rank_bound (F.enumeration N) p\n  have he:=F.scopeWord_value N p\n  rw [←he,F.enumeration_length N] at h\n  exact h\n/-- Physical ALL-original-owner query widths remain M bits, while values remain in E. -/\ntheorem original_key_width (N:Nat) (hN:0<N) (r:Row) (hr:r∈originalRows N hN) :\n    (keyOf r).length≤P.occurrences N:=by\n  have hall:∀r∈originalRows N hN,(keyOf r).length≤P.occurrences N:=by\n    unfold originalRows\n    rw [List.forall_mem_ofFn_iff]\n    intro e\n    change (SemiprimeD1OrdinalBankSpec.idAt (P.occurrences N) e.val).length≤P.occurrences N\n    have he:e.val<P.occurrences N:=by\n      rw [P.occurrences_eq N hN]\n      have hh:=e.isLt\n      omega\n    exact (SemiprimeD1OrdinalBankSpec.id_length (P.occurrences N) e.val he).le\n  exact hall r hr\n/-- Actual scope words are unchanged selections from the original M-occurrence stream. -/\ntheorem original_scope_width (N:Nat) (hN:0<N) (r:Row) (hr:r∈originalRows N hN)\n    (w:List Bool) (hw:w∈wordsOf r) :w.length≤P.occurrences N:=by\n  have hall:∀r∈originalRows N hN,∀w∈wordsOf r,w.length≤P.occurrences N:=by\n    unfold originalRows\n    rw [List.forall_mem_ofFn_iff]\n    intro e\n    change ∀w∈SemiprimeD1StackOwnerFibre.values (P.encode N e) (F.rows N hN),w.length≤P.occurrences N\n    apply values_all\n    intro pair hp\n    change pair∈(F.enumeration N).values.map _ at hp\n    obtain ⟨p,_,rfl⟩:=List.mem_map.mp hp\n    exact (F.scopeWord_length N p).le\n  exact hall r hr w hw\n/-- Scope VALUE bounds are in the M-occurrence domain, independent of owner E ordering. -/\ntheorem original_scope_value (N:Nat) (hN:0<N) (r:Row) (hr:r∈originalRows N hN)\n    (w:List Bool) (hw:w∈wordsOf r) :bitValue w≤P.occurrences N:=by\n  have hall:∀r∈originalRows N hN,∀w∈wordsOf r,bitValue w≤P.occurrences N:=by\n    unfold originalRows\n    rw [List.forall_mem_ofFn_iff]\n    intro e\n    change ∀w∈SemiprimeD1StackOwnerFibre.values (P.encode N e) (F.rows N hN),bitValue w≤P.occurrences N\n    apply values_all\n    intro pair hp\n    change pair∈(F.enumeration N).values.map _ at hp\n    obtain ⟨p,_,rfl⟩:=List.mem_map.mp hp\n    exact scope_value_bound N p\n  exact hall r hr w hw\n/-- The number of iterations is exactly original E, derived from actual acquired owner rows. -/\ntheorem original_loop_budget (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    loopBudget (originalRows (bitValue bits) hN) (prefixRows (bitValue bits) fixed) tail≤\n      baseCap bits.length*rowCap (2*baseCap bits.length) (records (prefixRows (bitValue bits) fixed) tail).length:=by\n  have hm:=occurrences_bound bits hc hN\n  have h:=loop_budget_le (originalRows (bitValue bits) hN) (prefixRows (bitValue bits) fixed) tail\n    (2*baseCap bits.length)\n    (fun r hr=>(original_key_width _ hN r hr).trans hm)\n    (fun r hr w hw=>(original_scope_width _ hN r hr w hw).trans hm)\n    (fun r hr w hw=>(original_scope_value _ hN r hr w hw).trans hm)\n  simp only [originalRows,List.length_ofFn] at h\n  exact h.trans (Nat.mul_le_mul_right _ (owners_bound bits hc hN))\n/-- EVERY prefix/copy/parser/cleanup cell of the SAME whole original source is paid. -/\ntheorem budget_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    SemiprimeD1StackOwnerRecordsExecution.budget bits hN fixed tail+1≤\n      runCap bits.length (records (prefixRows (bitValue bits) fixed) tail).length:=by\n  have hcata:=catalogue_length bits hc hN\n  have hl:=original_loop_budget bits hc hN fixed tail\n  have hb:=bytes_budget (originalRows (bitValue bits) hN) (prefixRows (bitValue bits) fixed) tail\n  unfold SemiprimeD1StackOwnerRecordsExecution.budget acquisitionBudget runCap\n  simp only [Nat.mul_assoc];omega\n/-- Fixed C,d before every N; no externally supplied source/cost answer. -/\ntheorem polynomial_monomial :∃C d:Nat,∀n,polynomial n≤C*(n+1)^d:=by\n  have hs :Bound (fun n=>SemiprimeD1StackOwnerFibreCatalogueBounds.polynomial n):=\n    SemiprimeD1StackOwnerFibreCatalogueBounds.polynomial_monomial\n  have hr :Bound (fun n=>SemiprimeD1StackPortOwnerRoutingBounds.polynomial n):=\n    SemiprimeD1StackPortOwnerRoutingBounds.polynomial_monomial\n  have h0 :Bound (fun n=>SemiprimeD1StackOwnerFibreCatalogueBounds.baseCap n):=\n    mul_bound (constant_bound 283) (add_bound identity_bound hr)\n  have hb :Bound baseCap:=\n    add_bound h0 (mul_bound (constant_bound 306) (add_bound identity_bound hs))\n  have hc :Bound (fun n=>rowCap (2*baseCap n) 1):=\n    mul_bound (mul_bound (constant_bound 10000)\n      (add_bound (mul_bound (constant_bound 2) hb) (constant_bound 1))) (constant_bound 2)\n  exact add_bound (add_bound (add_bound hs (mul_bound (constant_bound 5) hb))\n    (mul_bound (mul_bound (constant_bound 3) hb) hc)) (constant_bound 100)\n/-- Complete real N-only all-owner source with its OWN uniform fixed polynomial. -/\ntheorem source_run_polynomial (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃time≤polynomial bits.length,C.run program time (initial bits)=\n      some (SemiprimeD1StackOwnerRecordsExecution.done bits hN [] []):=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackOwnerRecordsExecution.source_run bits hc hN\n  refine ⟨t,ht.trans ?_,hr⟩\n  exact budget_le bits hc hN [] []\nend RiemannGaussian.SemiprimeD1StackOwnerRecordsBounds\n","RiemannGaussian.SemiprimeD1StackOwnerRecordsCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerRecordsView\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackOwnerRecordsCalls\nopen SemiprimeD1StackOwnerRecords SemiprimeD1StackOwnerRecordsView\nopen SemiprimeD1StackProcedureTrace (Runs included_call)\nopen SemiprimeD1StackPortOwnerRecipeCalls (update_rel)\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Rel\nexport SemiprimeD1StackMultiplierLink (DataRel)\nend Rel\ntheorem copy_injective :∀part:Bool,Function.Injective (copyStack part):=by decide\ntheorem copy_call (part:Bool) (store:Stack→List Bool) (pc next:Label)\n    (hc:program pc=.call (.copy part 0) next) (hs:store (aux .copyScratch)=[]) :\n    Runs program (5*(store (copyStack part 0)).length+4) pc store next\n      (Function.update store (copyStack part 1) (store (copyStack part 0)++store (copyStack part 1))) := by\n  let word:=store (copyStack part 0)\n  let tail:=store (copyStack part 1)\n  let before:=SemiprimeD1StackCopy.state 0 none word tail []\n  let after:=SemiprimeD1StackCopy.done word (word++tail)\n  have hi:Rel.DataRel (copyStack part) store before.store store:=by\n    constructor\n    · intro k;fin_cases k <;> simp [before,SemiprimeD1StackCopy.state,SemiprimeD1StackCopy.payload,copyStack,word,tail,hs]\n    · intro k _;rfl\n  apply included_call program (copyStack part) (Label.copy part) (copy_injective part)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hc _ before after\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words word tail none\n  · exact hi\n  · have he:Function.update before.store (1:Fin 3) (word++tail)=after.store:=by funext k;fin_cases k <;> rfl\n    simpa only [he] using update_rel (copyStack part) (copy_injective part) store before.store store hi 1 (word++tail)\ntheorem field_injective :∀scopes:Bool,Function.Injective (fieldStack scopes):=by decide\n/-- Physically parse the actual next M-bank payload directly into the real owner filter query. -/\ntheorem field_call (scopes:Bool) (store:Stack→List Bool) (word tail:List Bool)\n    (hi:store (aux .reader)=frame word tail) (ho:store ((if scopes then bank else key))=[])\n    (hs:store (aux .fieldScratch)=[]) (hv:store (aux .valid)=[]) :\n    Runs program (8*word.length+7) (.local (.field scopes)) store (.local (.valid scopes))\n      (Function.update (Function.update (Function.update store (aux .reader) tail)\n        ((if scopes then bank else key)) word) (aux .valid) [true]) := by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let after:SemiprimeD1StackBytecode.State F.Stack F.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Rel.DataRel (fieldStack scopes) store before.store store:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k <;> simp [fieldStack,before,SemiprimeD1TensorTapeFieldBytecode.initial,\n          SemiprimeD1TensorTapeFieldMachine.contents,hi,ho,hs]\n      · cases k;exact hv\n    · intro k _;rfl\n  apply included_call program (fieldStack scopes) (Label.field scopes) (field_injective scopes) F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) (.local (.field scopes)) (.local (.valid scopes))\n    rfl (8*word.length+6) before after\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · exact hin\n  · have h0:=update_rel (fieldStack scopes) (field_injective scopes) store before.store store hin (.inl .input) tail\n    have h1:=update_rel (fieldStack scopes) (field_injective scopes) store _ _ h0 (.inl .output) word\n    have h2:=update_rel (fieldStack scopes) (field_injective scopes) store _ _ h1 (.inr ()) [true]\n    have he:Function.update (Function.update (Function.update before.store (.inl .input) tail)\n        (.inl .output) word) (.inr ()) [true]=after.store:=by\n      funext k;rcases k with k|k <;> cases k <;> rfl\n    simpa only [he,fieldStack] using h2\n\nend RiemannGaussian.SemiprimeD1StackOwnerRecordsCalls\n","RiemannGaussian.SemiprimeD1StackOwnerTableBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackOwnerTableExecution\n/-! # Whole actual owner-table clock and all eighteen roles/real frames\nScope records and prefix keys are physically consumed/scanned, every constant\noutput byte is pushed. Their original acquisition remains caller work.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1StackOwnerTableBounds\nopen SemiprimeD1StackOwnerTable SemiprimeD1StackOwnerTableExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1OwnerPrefixBits (records)\n\n/-- Complete own bound: actual scope scan, full prefix/equality work, all output\nand local degree/flag/call/halt work. Fixed before all scope/key/prefix streams. -/\ndef runBound (key : List Bool) (rows : List (List Bool×Bool)) (scopeWords : List (List Bool)) : ℕ :=\n  11*(vectorBits scopeWords).length+SemiprimeD1StackOwnerPrefixBounds.runBound key rows+100\n/-- The SAME actual trace satisfies the closed byte/word-width bound. -/\ntheorem traceTime_le (key : List Bool) (rows : List (List Bool×Bool))\n    (scopeWords : List (List Bool)) (hs : scopeWords.length≤2) : traceTime key rows scopeWords hs≤runBound key rows scopeWords := by\n  have hc:=SemiprimeD1StackDigitCountExecution.totalTime_le scopeWords\n  have hp:=SemiprimeD1StackOwnerPrefixBounds.time_le key rows\n  have ht:=SemiprimeD1OwnerTablePalette.bytes_le (actualDegree scopeWords hs)\n    (SemiprimeD1OwnerPrefixBits.scan key rows true true).1 (SemiprimeD1OwnerPrefixBits.scan key rows true true).2\n  dsimp only [traceTime,runBound]\n  omega\n/-- Whole source with all caller data/flags/returns accounted for. -/\ndef sourceTable (key : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (scopeWords : List (List Bool)) (hs : scopeWords.length≤2) :\n    StateTransition.EvalsToInTime (C.step program) (initial key (records rows tail) (vectorBits scopeWords))\n      (some (done key rows tail scopeWords hs)) (runBound key rows scopeWords) :=\n  ⟨⟨_,source_run key rows tail scopeWords hs⟩,traceTime_le key rows scopeWords hs⟩\n/-- ONE genuine finite machine; initial data contains no degree/allowed/table\nanswer, coefficient evaluator, input-dependent instruction or clock. -/\ndef machineTable (key : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (scopeWords : List (List Bool)) (hs : scopeWords.length≤2) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial key (records rows tail) (vectorBits scopeWords)))\n      (some (SemiprimeD1StackCalls.configuration (done key rows tail scopeWords hs))) (runBound key rows scopeWords) :=\n  SemiprimeD1StackCalls.evalsCorrect reader output Label.start program _ _ _ (sourceTable key rows tail scopeWords hs)\n/-- Every source prefix stops before the SAME literal source's completed halt. -/\ntheorem prefix_fuel_le (key : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (scopeWords : List (List Bool)) (hs : scopeWords.length≤2) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial key (records rows tail) (vectorBits scopeWords))=some out) :\n    fuel≤traceTime key rows scopeWords hs := by\n  by_contra hn\n  have he:fuel=traceTime key rows scopeWords hs+(1+(fuel-(traceTime key rows scopeWords hs+1))) := by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,source_run key rows tail scopeWords hs,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add] at hr\n  have hz:C.run program 1 (done key rows tail scopeWords hs)=none := rfl\n  rw [hz,Option.bind_none] at hr\n  cases hr\n/-- Every actual prefix counts ALL18 Boolean roles and actual finite-label\nreturn cells, including key/scope retention, query copies and parser work. -/\ntheorem prefix_cells (key : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (scopeWords : List (List Bool)) (hs : scopeWords.length≤2) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial key (records rows tail) (vectorBits scopeWords))=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤\n      19*(key.length+(records rows tail).length+(vectorBits scopeWords).length+runBound key rows scopeWords) := by\n  let I:=key.length+(records rows tail).length+(vectorBits scopeWords).length\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel I _ out (by\n    intro k\n    rcases k with k|k\n    · rcases k with k|k <;> cases k <;>\n        simp [initial,data,P.data,SemiprimeD1StackAdder.store,I] <;> omega\n    · rcases k with k|k\n      · cases k <;> simp [initial,data,D.data,I]\n      · cases k;simp [initial,data,I]) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hi:(∑k : Stack,(out.data k).length)≤18*(I+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(I+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=(prefix_fuel_le key rows tail scopeWords hs fuel out hr).trans (traceTime_le key rows scopeWords hs)\n  change _≤19*(I+runBound key rows scopeWords)\n  omega\n/-- The SAME all-role/real-return inventory for every compiled-machine prefix. -/\ntheorem machine_prefix_cells (key : List Bool) (rows : List (List Bool×Bool)) (tail : List Bool)\n    (scopeWords : List (List Bool)) (hs : scopeWords.length≤2) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial key (records rows tail) (vectorBits scopeWords))))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      19*(key.length+(records rows tail).length+(vectorBits scopeWords).length+runBound key rows scopeWords) := by\n  have he:=SemiprimeD1StackCalls.run_correct reader output Label.start program fuel\n    (initial key (records rows tail) (vectorBits scopeWords))\n  change (C.run program fuel (initial key (records rows tail) (vectorBits scopeWords))).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial key (records rows tail) (vectorBits scopeWords)))) at he\n  have hh:=he.trans hr\n  cases hc:C.run program fuel (initial key (records rows tail) (vectorBits scopeWords)) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells key rows tail scopeWords hs fuel out hc\nend RiemannGaussian.SemiprimeD1StackOwnerTableBounds\n","RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryArithmetic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryEncoding\nimport RiemannGaussian.SemiprimeD1PackedMomentRecovery\n/-! # Exact arithmetic of physically computed discriminants and half words\nThese are specification proofs about actual component output words, never\nruntime arithmetic operands or clocks. The source consumes only N and V.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryArithmetic\nopen SemiprimeD1StackPackedFactorRecoveryEncoding SemiprimeBitArithmetic SemiprimeBitDivision\n/-- Actual borrow is FALSE exactly on the required non-underflow branch. -/\ntheorem no_borrow (xs ys : List Bool) (h : bitValue ys≤bitValue xs) : (subBits xs ys false).borrow=false := by\n  cases hb:(subBits xs ys false).borrow with\n  | false=>rfl\n  | true=>\n    have ht:=(subBits_borrow_iff xs ys false).mp hb\n    simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero] at ht\n    omega\n/-- The two literal FALSE pushes multiply by four without unary expansion. -/\ntheorem fourWord_value (n : List Bool) : bitValue (fourWord n)=4*bitValue n := by\n  simp only [fourWord,bitValue,bitNat,Bool.false_eq_true,ite_false,Nat.zero_add]\n  ring\n/-- The actual subtraction is nonnegative on every pair of true ordered factors. -/\ntheorem discriminant_borrow (n s : List Bool) (p q : ℕ) (hn : bitValue n=p*q) (hs : bitValue s=p+q) :\n    (discriminantReport n s).borrow=false := by\n  apply no_borrow\n  rw [fourWord_value,squareWord,mulBits_correct,hn,hs]\n  nlinarith [sq_nonneg (p-q : ℤ)]\n/-- The actual binary discriminant equals the integer prime-gap square. -/\ntheorem discriminant_value (n s : List Bool) (p q : ℕ) (hn : bitValue n=p*q)\n    (hs : bitValue s=p+q) (hpq : p≤q) : bitValue (discriminant n s)=(q-p)^2 := by\n  have hb:=discriminant_borrow n s p q hn hs\n  rw [discriminant,discriminantReport,subBits_difference hb,squareWord,mulBits_correct,fourWord_value,hn,hs]\n  simpa only [pow_two] using SemiprimeD1PackedMomentRecovery.discriminant p q hpq\n/-- The ENTIRE frozen source's actual root output is exactly the ordered factor gap. -/\ntheorem rootWord_value (n s : List Bool) (p q : ℕ) (hn : bitValue n=p*q)\n    (hs : bitValue s=p+q) (hpq : p≤q) : bitValue (rootWord n s)=q-p := by\n  rw [rootWord,SemiprimeD1StackBinarySquareRootArithmetic.output_value,discriminant_value n s p q hn hs hpq,Nat.sqrt_eq']\n/-- A physical least-significant-bit pop divides the represented binary value by two. -/\ntheorem tail_value (xs : List Bool) : bitValue xs.tail=bitValue xs/2 := by\n  cases xs with\n  | nil=>rfl\n  | cons b xs=>cases b <;> simp only [List.tail_cons,bitValue,bitNat,Bool.false_eq_true,ite_false,ite_true] <;> omega\n/-- Positive even numerator words really contain a FALSE digit; EOF is never substituted. -/\ntheorem even_head (xs : List Bool) (p : ℕ) (hp : 0<p) (hv : bitValue xs=2*p) :\n    ∃tail, xs=false::tail := by\n  cases xs with\n  | nil=>simp only [bitValue] at hv;omega\n  | cons b xs=>\n    cases b with\n    | false=>exact ⟨xs,rfl⟩\n    | true=>simp only [bitValue,bitNat,ite_true] at hv;omega\n/-- Real low-bit pop and real high-zero compaction retain the exact half integer. -/\ntheorem halfWord_exact (xs : List Bool) (p : ℕ) (hv : bitValue xs=2*p) : bitValue (halfWord xs)=p := by\n  rw [halfWord_value,tail_value,hv,Nat.mul_div_right _ (by decide : 0<2)]\n/-- The lower numerator has an actual FALSE borrow, positive even value and exact lower half. -/\ntheorem minus_exact (s root : List Bool) (p q : ℕ) (hp : 0<p) (hpq : p≤q)\n    (hs : bitValue s=p+q) (hr : bitValue root=q-p) :\n    (minusReport s root).borrow=false ∧ (∃tail,(minusReport s root).result.bits=false::tail) ∧\n      bitValue (halfWord (minusReport s root).result.bits)=p := by\n  have hb : (minusReport s root).borrow=false := no_borrow s root (by omega)\n  have hv : bitValue (minusReport s root).result.bits=2*p := by\n    rw [minusReport,subBits_difference hb,hs,hr]\n    omega\n  exact ⟨hb,even_head _ p hp hv,halfWord_exact _ p hv⟩\n/-- The upper numerator has an actual FALSE parity digit and exact upper half. -/\ntheorem plus_exact (s root : List Bool) (p q : ℕ) (hq : 0<q) (hpq : p≤q)\n    (hs : bitValue s=p+q) (hr : bitValue root=q-p) :\n    (∃tail,plusWord s root=false::tail) ∧ bitValue (halfWord (plusWord s root))=q := by\n  have hv : bitValue (plusWord s root)=2*q := by\n    rw [plusWord,addBits_correct]\n    simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero]\n    omega\n  exact ⟨even_head _ q hq hv,halfWord_exact _ q hv⟩\nend RiemannGaussian.SemiprimeD1StackPackedFactorRecoveryArithmetic\n","RiemannGaussian.SemiprimeD1StackPacketModeAcquireResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketModeAcquireBounds\n/-! # All44 actual words and real return cells at every compiled prefix\nThe source front door is the three actual prepared tapes, not original N alone.\nThe SAME whole program supplies its own source clock and storage certificates.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketModeAcquireResources\nopen SemiprimeD1StackPacketModeAcquire SemiprimeD1StackPacketModeAcquireEncoding\nopen SemiprimeD1StackPacketModeAcquireExecution SemiprimeD1StackPacketModeAcquireBounds\nopen SemiprimeD1StackCalls (run configuration)\n/-- Every actual initialized word is paid by physical input bytes, with computed tile VALUE retained in the envelope. -/\ntheorem initial_length (packets:List (List Bool)) (i precision:Nat) (k:Stack):\n    ((source packets i precision).data k).length ≤ inputSize packets i precision:=by\n  have hp:precision ≤ inputSize packets i precision:=by\n    change precision ≤ (SemiprimeD1TensorTapeCodec.vectorBits packets).length+i+2^(i+1)+precision+1\n    exact (Nat.le_add_left _ _).trans (Nat.le_add_right _ _)\n  have hi:i ≤ inputSize packets i precision:=by\n    change i ≤ (SemiprimeD1TensorTapeCodec.vectorBits packets).length+i+2^(i+1)+precision+1\n    exact (((Nat.le_add_left _ _).trans (Nat.le_add_right _ _)).trans (Nat.le_add_right _ _)).trans (Nat.le_add_right _ _)\n  have hb:(SemiprimeD1TensorTapeCodec.vectorBits packets).length ≤ inputSize packets i precision:=by\n    change (SemiprimeD1TensorTapeCodec.vectorBits packets).length ≤ (SemiprimeD1TensorTapeCodec.vectorBits packets).length+i+2^(i+1)+precision+1\n    exact (((Nat.le_add_right _ _).trans (Nat.le_add_right _ _)).trans (Nat.le_add_right _ _)).trans (Nat.le_add_right _ _)\n  rcases k with k|k\n  · have h:=SemiprimeD1StackWeightedModeCatalogueBounds.initial_length 0 0 precision k\n    change ((M.initial [] [] (List.replicate precision true)).data k).length ≤ inputSize packets i precision\n    exact h.trans (by simpa only [Nat.zero_add] using hp)\n  · cases k <;> change _ ≤ inputSize packets i precision\n    · exact hb\n    · change (List.replicate i true).length ≤ inputSize packets i precision\n      simpa only [List.length_replicate] using hi\n    all_goals exact Nat.zero_le _\n/-- Actual successful prefixes stop before this SAME source's genuine final halt. -/\ntheorem prefix_fuel (packets:List (List Bool)) (i precision fuel:Nat) (out:C.State Stack Label)\n    (hr:run program fuel (source packets i precision)=some out):fuel ≤ runBound packets i precision:=by\n  obtain ⟨q,hq,hfinal⟩:=source_run_bounded packets i precision\n  have hh:run program 1 (done packets i precision)=none:=rfl\n  have hf:fuel ≤ q:=by\n    by_contra hn\n    have he:fuel=q+(1+(fuel-(q+1))):=by omega\n    rw [he,SemiprimeD1StackReturnLink.run_add,hfinal,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans hq\n/-- All44 actual source/callee/parser/doubling words and every real return frame are counted. -/\ntheorem prefix_cells (packets:List (List Bool)) (i precision fuel:Nat) (out:C.State Stack Label)\n    (hr:run program fuel (source packets i precision)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      45*(inputSize packets i precision+runBound packets i precision):=by\n  have ht:=prefix_fuel packets i precision fuel out hr\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel (inputSize packets i precision)\n    _ _ (initial_length packets i precision) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ _ hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length) ≤ 44*(inputSize packets i precision+fuel):=by\n    calc\n      _ ≤ ∑_k:Stack,(inputSize packets i precision+fuel):=Finset.sum_le_sum (fun k _=>hd k)\n      _= _:=by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  omega\n/-- Genuine compiled execution certificate starts with precisely the three honest physical source inputs. -/\nnoncomputable def modesInTime (packets:List (List Bool)) (i precision:Nat):\n    StateTransition.EvalsToInTime machine.step (configuration (source packets i precision))\n      (some (configuration (done packets i precision))) (runBound packets i precision):=by\n  apply SemiprimeD1StackCalls.evalsCorrect (aux .packets) output (.local .start) program\n  have h:=source_run_bounded packets i precision\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Every genuine compiled prefix counts ALL44 data words and its actual finite-label return stack. -/\ntheorem machine_prefix_cells (packets:List (List Bool)) (i precision fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (configuration (source packets i precision)))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      45*(inputSize packets i precision+runBound packets i precision):=by\n  have he:=SemiprimeD1StackCalls.run_correct (aux .packets) output (.local .start) program fuel (source packets i precision)\n  have hh:=he.trans hr\n  cases hout:run program fuel (source packets i precision) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells packets i precision fuel out hout\n/-- Every actual source instruction compiles to fixed-depth finite statements. -/\ntheorem compile_depth (pc:Label):SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤ 4:=by\n  change SemiprimeD1StackBytecode.statementDepth\n    (SemiprimeD1StackCalls.compileInstruction (Label.local Control.start) (program pc)) ≤ 4\n  exact SemiprimeD1StackCalls.compile_depth (Label.local Control.start) (program pc)\nend RiemannGaussian.SemiprimeD1StackPacketModeAcquireResources\n","RiemannGaussian.SemiprimeD1StackPacketOrientationCompare":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketOrientationPrimitives\n/-! # Real paid strict comparison of the two acquired colour words\nOnly actual preserving copies feed the real five-role WordLess source. Its\ncomputed Boolean is physically popped; the whole other bank, including both\nactual colour words and every caller return, survives this fragment.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketOrientationCompare\nopen SemiprimeD1StackPacketOrientation SemiprimeD1StackPacketOrientationPrimitives\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Complete nineteen-role comparison bank; all other sixteen words retain their actual prior values. -/\ndef view (retained:Stack→List Bool) (left right result:List Bool) :Stack→List Bool :=\n  fun k=>if k=operand false then left else if k=operand true then right\n    else if k=answer then result else retained k\n/-- One actual left comparison update preserves every other physical stack. -/\ntheorem update_left (retained:Stack→List Bool) (left right result word:List Bool) :\n    Function.update (view retained left right result) (operand false) word=view retained word right result :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- One actual right comparison update preserves every other physical stack. -/\ntheorem update_right (retained:Stack→List Bool) (left right result word:List Bool) :\n    Function.update (view retained left right result) (operand true) word=view retained left word result :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- One actual result comparison update preserves every other physical stack. -/\ntheorem update_result (retained:Stack→List Bool) (left right result word:List Bool) :\n    Function.update (view retained left right result) answer word=view retained left right word :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- The chosen colour directions are compared by real copied operand words, with no supplied order Boolean. -/\ntheorem compare_run (backward:Bool) (retained:Stack→List Bool) (first second:List Bool)\n    (hn:retained (copyStack (.operand backward false) 0)=first)\n    (ho:retained (copyStack (.operand backward true) 0)=second)\n    (hc:retained (aux .copyScratch)=[]) (hs:retained scratch=[])\n    (hd:retained buffer=[]) :\n    Runs program (5*first.length+5*second.length+\n        SemiprimeD1StackWordLessExecution.totalTime first second+10)\n      (ctl (.copyOperand backward false)) (view retained [] [] [])\n      (ctl (if SemiprimeD1StackWordLessExecution.answer first second then\n        (if backward then .slot false true else .slot true false) else\n        (if backward then .padding else .copyOperand true false)))\n      (view retained [] [] []) :=by\n  have h0:=copy_call (.operand backward false) (.copyOperand backward false) (.copyOperand backward true) rfl\n    (view retained [] [] []) first [] (by cases backward <;> exact hn) rfl hc\n  change Runs program _ _ _ _\n    (Function.update (view retained [] [] []) (operand false) (first++[])) at h0\n  rw [List.append_nil,update_left] at h0\n  have h1:=copy_call (.operand backward true) (.copyOperand backward true) (.compare backward) rfl\n    (view retained first [] []) second [] (by cases backward <;> exact ho) rfl hc\n  change Runs program _ _ _ _\n    (Function.update (view retained first [] []) (operand true) (second++[])) at h1\n  rw [List.append_nil,update_right] at h1\n  have h2:=less_call backward (view retained first second []) first second rfl rfl hs hd rfl\n  rw [update_left,update_right,update_result] at h2\n  let low:Control:=if backward then .padding else .copyOperand true false\n  let high:Control:=if backward then .slot false true else .slot true false\n  have hcode:program (ctl (.compared backward))=.base (.pop answer (ctl .reject) (ctl low) (ctl high)):=by cases backward <;> rfl\n  have h3:=pop_run (.compared backward) (ctl .reject) (ctl low) (ctl high) answer\n    (view retained [] [] [SemiprimeD1StackWordLessExecution.answer first second])\n    [SemiprimeD1StackWordLessExecution.answer first second] hcode rfl\n  change Runs program 1 _ _ _ (Function.update\n    (view retained [] [] [SemiprimeD1StackWordLessExecution.answer first second]) answer []) at h3\n  rw [update_result] at h3\n  have hp:SemiprimeD1StackBytecode.choose (ctl .reject) (ctl low) (ctl high)\n      [SemiprimeD1StackWordLessExecution.answer first second].head?=\n      ctl (if SemiprimeD1StackWordLessExecution.answer first second then high else low):=by\n    cases SemiprimeD1StackWordLessExecution.answer first second <;> rfl\n  rw [hp] at h3\n  have h:=join (join (join h0 h1) h2) h3\n  have ht:(5*first.length+4)+(5*second.length+4)+\n      (SemiprimeD1StackWordLessExecution.totalTime first second+1)+1=\n      5*first.length+5*second.length+SemiprimeD1StackWordLessExecution.totalTime first second+10:=by omega\n  simpa only [ht,low,high] using h\n/-- Empty comparison overrides are exactly the original caller bank once its three real words are clear. -/\ntheorem view_empty (retained:Stack→List Bool) (hl:retained (operand false)=[])\n    (hr:retained (operand true)=[]) (ho:retained answer=[]) :view retained [] [] []=retained :=by\n  funext k\n  by_cases h0:k=operand false\n  · subst k;simp only [view,ite_true];exact hl.symm\n  · by_cases h1:k=operand true\n    · subst k;simp only [view,h0,ite_false,ite_true];exact hr.symm\n    · by_cases h2:k=answer\n      · subst k;simp only [view,h0,h1,ite_false,ite_true];exact ho.symm\n      · simp only [view,h0,h1,h2,ite_false]\nend RiemannGaussian.SemiprimeD1StackPacketOrientationCompare\n","RiemannGaussian.SemiprimeD1StackPacketRowsLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPacketRowsLog\n/-! # Entire paired physical EOF/colour-field loop, with no coordinate operand\nThe actual two raw streams determine the loop length. Every empty colour field\nstill has one real false delimiter and is parsed/logged. Only two simultaneous\nphysical EOFs finish the loop; no native row count is decoded or supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPacketRowsLoop\nopen SemiprimeD1StackPacketRows SemiprimeD1StackPacketRowsPrimitives SemiprimeD1StackPacketRowsRowView\nopen SemiprimeD1StackPacketRowsEncoding (row rowsPrefix serialize_cons_nonempty)\nopen SemiprimeD1StackPacketRowsLog SemiprimeD1StackProcedureTrace\nnamespace R\nexport SemiprimeD1PacketRows (serialize)\nend R\nlocal notation \"ctl\" => Label.local\n/-- The two actual fixed raw stream roles, interpreted only in proof statements. -/\ndef streams (left right:List (List Bool)) (side:Bool) :List Bool :=if side then R.serialize right else R.serialize left\n/-- Complete actual reverse-row histories after scanning the remaining raw colour fields. -/\ndef finalHistories (histories:Bool→List Bool) (left right:List (List Bool)) (side:Bool) :List Bool :=\n  (rowsPrefix (if side then right else left)).reverse++histories side\n/-- Exact actual two-EOF or paired-field logger clock. -/\ndef loopTime :List (List Bool)→List (List Bool)→Nat\n  | [],[]=>2\n  | l::ls,r::rs=>19*l.length+19*r.length+42+loopTime ls rs\n  | _,_=>2\n/-- A nonempty real row stream passes the actual peek even when its first byte is the empty-field false delimiter. -/\ntheorem nonempty_peek (pc:Control) (empty next:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program (ctl pc)=.base (.peek k empty next next)) (hx:before k=xs) (hn:xs≠[]) :\n    Runs program 1 (ctl pc) before next before :=by\n  have h:=peek_run pc empty next next k before xs hc hx\n  cases xs with\n  | nil=>exact (hn rfl).elim\n  | cons b xs=>cases b <;> exact h\n/-- Whole actual paired loop logs every original field once and finishes only at real simultaneous EOF. -/\ntheorem loop_run (key catalogue:List Bool) (left right:List (List Bool))\n    (histories outputs:Bool→List Bool) (hlen:left.length=right.length) :\n    Runs program (loopTime left right) (ctl .leftEOF)\n      (rowView key catalogue (streams left right) (fun _=>[]) histories outputs [])\n      (ctl .reverseLeft)\n      (rowView key catalogue (streams [] []) (fun _=>[]) (finalHistories histories left right) outputs []) :=by\n  induction left generalizing right histories with\n  | nil=>\n    cases right with\n    | cons r rs=>simp only [List.length_nil,List.length_cons] at hlen;omega\n    | nil=>\n      have h0:=peek_run .leftEOF (ctl .rightEOF) (ctl .rightNonempty) (ctl .rightNonempty) (rowBytes false)\n        (rowView key catalogue (streams [] []) (fun _=>[]) histories outputs []) [] rfl rfl\n      have h1:=peek_run .rightEOF (ctl .reverseLeft) (ctl .reject) (ctl .reject) (rowBytes true)\n        (rowView key catalogue (streams [] []) (fun _=>[]) histories outputs []) [] rfl rfl\n      have he:finalHistories histories [] []=histories:=by funext side;cases side <;> rfl\n      rw [he]\n      exact join h0 h1\n  | cons l ls ih=>\n    cases right with\n    | nil=>simp only [List.length_nil,List.length_cons] at hlen;omega\n    | cons r rs=>\n      let before:=rowView key catalogue (streams (l::ls) (r::rs)) (fun _=>[]) histories outputs []\n      have h0:=nonempty_peek .leftEOF (ctl .rightEOF) (ctl .rightNonempty) (rowBytes false)\n        before (R.serialize (l::ls)) rfl rfl (serialize_cons_nonempty l ls)\n      have h1:=nonempty_peek .rightNonempty (ctl .reject) (ctl (.parseColour false)) (rowBytes true)\n        before (R.serialize (r::rs)) rfl rfl (serialize_cons_nonempty r rs)\n      have h2:=colour_run false key catalogue (streams (l::ls) (r::rs)) histories outputs l (R.serialize ls) rfl\n      let midStreams:=Function.update (streams (l::ls) (r::rs)) false (R.serialize ls)\n      let midHistories:=Function.update histories false ((row l).reverse++histories false)\n      have h3:=colour_run true key catalogue midStreams midHistories outputs r (R.serialize rs) rfl\n      have hs:Function.update midStreams true (R.serialize rs)=streams ls rs:=by funext side;cases side <;> rfl\n      let nextHistories:Bool→List Bool:=fun side=>if side then (row r).reverse++histories true else (row l).reverse++histories false\n      have hh:Function.update midHistories true ((row r).reverse++midHistories true)=nextHistories:=by funext side;cases side <;> rfl\n      rw [hs,hh] at h3\n      have h4:=ih rs nextHistories (by simp only [List.length_cons] at hlen;omega)\n      have hf:finalHistories nextHistories ls rs=finalHistories histories (l::ls) (r::rs):=by\n        funext side\n        cases side <;> simp only [finalHistories,nextHistories,Bool.false_eq_true,ite_false,ite_true,\n          rowsPrefix,List.flatMap_cons,List.reverse_append,List.append_assoc]\n      rw [hf] at h4\n      have h:=join (join (join (join h0 h1) h2) h3) h4\n      have ht:1+1+(19*l.length+20)+(19*r.length+20)+loopTime ls rs=19*l.length+19*r.length+42+loopTime ls rs:=by omega\n      simpa only [ht,before,loopTime] using h\n/-- Actual paired field/EOF work is linear in both complete raw row payloads, including zero-field delimiters. -/\ntheorem loopTime_le (left right:List (List Bool)) (hlen:left.length=right.length) :\n    loopTime left right ≤ 100*((R.serialize left).length+(R.serialize right).length+1) :=by\n  induction left generalizing right with\n  | nil=>cases right with\n    | nil=>simp only [loopTime,R.serialize,List.length_nil];omega\n    | cons r rs=>simp only [List.length_nil,List.length_cons] at hlen;omega\n  | cons l ls ih=>cases right with\n    | nil=>simp only [List.length_nil,List.length_cons] at hlen;omega\n    | cons r rs=>\n      have h:=ih rs (by simp only [List.length_cons] at hlen;omega)\n      simp only [loopTime,R.serialize,SemiprimeSourceHistogramKeyBits.frame_length]\n      omega\nend RiemannGaussian.SemiprimeD1StackPacketRowsLoop\n","RiemannGaussian.SemiprimeD1StackPhaseBankRestorePrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseBankRestore\n\n/-! # Actual heap call, physical field parsing and consumed validation flags -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackPhaseBankRestorePrimitives\nopen SemiprimeD1StackPhaseBankRestore SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact trace composition for this one fixed cache consumer. -/\ntheorem join {m n:Nat} {pc mid finish:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between finish after) :\n    Runs program (m+n) pc before finish after :=runs_trans program m n pc mid finish before between after h g\n/-- Updating one restored phase word retains the entire physical heap reader. -/\ntheorem update_phase (p:P.Stack→List Bool) (h:H.Stack→List Bool) (k:P.Stack) (word:List Bool) :\n    Function.update (data p h) (phaseStack k) word=data (Function.update p k word) h :=by\n  unfold data phaseStack\n  rw [Sum.update_elim_inl]\n/-- Updating one actual heap-reader word retains every phase word. -/\ntheorem update_heap (p:P.Stack→List Bool) (h:H.Stack→List Bool) (k:H.Stack) (word:List Bool) :\n    Function.update (data p h) (heapStack k) word=data p (Function.update h k word) :=by\n  unfold data heapStack\n  rw [Sum.update_elim_inr]\n/-- Parsed-field boundary; all heap-read work except its physical output and flag is clear. -/\ndef view (p:P.Stack→List Bool) (heap counter reference reader valid:List Bool) :Stack→List Bool :=\n  data p (SemiprimeD1StackHeapReadExecution.payload heap counter reference [] [] [] reader valid)\n/-- Actual reader update changes only the unconsumed suffix of the dereferenced record. -/\ntheorem view_reader (p:P.Stack→List Bool) (heap counter reference reader valid word:List Bool) :\n    Function.update (view p heap counter reference reader valid) (heapStack .output) word=\n      view p heap counter reference word valid :=by\n  unfold view\n  rw [update_heap]\n  congr 1\n  funext k;cases k <;> simp [SemiprimeD1StackHeapReadExecution.payload,Function.update]\n/-- Actual validation writes and pops preserve both heap and restored coefficient parameters. -/\ntheorem view_valid (p:P.Stack→List Bool) (heap counter reference reader valid word:List Bool) :\n    Function.update (view p heap counter reference reader valid) (heapStack .valid) word=\n      view p heap counter reference reader word :=by\n  unfold view\n  rw [update_heap]\n  congr 1\n  funext k;cases k <;> simp [SemiprimeD1StackHeapReadExecution.payload,Function.update]\n/-- A field writes directly into its actual bank role, with no reconstruction callback. -/\ntheorem view_phase (p:P.Stack→List Bool) (heap counter reference reader valid word:List Bool) (k:P.Stack) :\n    Function.update (view p heap counter reference reader valid) (phaseStack k) word=\n      view (Function.update p k word) heap counter reference reader valid :=by\n  exact update_phase p _ k word\n/-- The real included heap program reads the issued ordinal and returns its actual stored bytes. -/\ntheorem heap_call (records:List (List Bool)) (i:Fin records.length) :\n    Runs program (SemiprimeD1StackHeapReadBounds.readTimeAt records i+1) (ctl .start)\n      (initial (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n        (List.replicate i.val true)).data (ctl .heapCheck)\n      (view (fun _=>[]) (SemiprimeD1StackHeapAllocate.heapBytes records)\n        (List.replicate records.length true) (List.replicate i.val true) records[i.val] [true]) :=by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program heapStack heapLabel Sum.inr_injective\n    H.program (.inl .start) (fun _=>rfl) (ctl .start) (ctl .heapCheck) rfl\n    (SemiprimeD1StackHeapReadBounds.readTimeAt records i)\n    (H.initial (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n      (List.replicate i.val true))\n    (H.done (SemiprimeD1StackHeapAllocate.heapBytes records) (List.replicate records.length true)\n      (List.replicate i.val true) records[i.val]) _ _ rfl rfl rfl rfl\n    (SemiprimeD1StackHeapReadBounds.read_run records i)\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · exact (hk k rfl).elim\n/-- One real included field parser consumes one frame and copies its literal word. -/\ntheorem parse_call (part:Fin 48) (bank:Stack→List Bool) (word tail:List Bool)\n    (hi:bank (heapStack .output)=frame word tail) (ho:bank (phaseStack (I.role part))=[])\n    (hs:bank (heapStack .fieldScratch)=[]) (hv:bank (heapStack .valid)=[]) :\n    Runs program (8*word.length+7) (ctl (.field part)) bank (ctl (.check part))\n      (Function.update (Function.update (Function.update bank (heapStack .output) tail)\n        (phaseStack (I.role part)) word) (heapStack .valid) [true]) :=by\n  let before:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let after:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack part) bank before.store bank :=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k <;> simp [fieldStack,before,SemiprimeD1TensorTapeFieldBytecode.initial,\n          SemiprimeD1TensorTapeFieldMachine.contents,hi,ho,hs]\n      · cases k;exact hv\n    · intro k _;rfl\n  apply included_call program (fieldStack part) (fieldLabel part) (field_injective part) Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) (ctl (.field part)) (ctl (.check part)) rfl\n    (8*word.length+6) before after _ _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin\n  have h0:=Link.data_update (fieldStack part) (field_injective part) bank before.store bank hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack part) (field_injective part) bank _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack part) (field_injective part) bank _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update before.store (.inl .input) tail)\n      (.inl .output) word) (.inr ()) [true]=after.store :=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  simpa only [he,fieldStack] using h2\n/-- Physically consume a true validity flag before entering the actual next label. -/\ntheorem valid_run (pc:Control) (finish:Label) (bank:Stack→List Bool)\n    (hcode:program (ctl pc)=.base (.pop (heapStack .valid) (ctl .abort) (ctl .abort) finish))\n    (hv:bank (heapStack .valid)=[true]) :\n    Runs program 1 (ctl pc) bank finish (Function.update bank (heapStack .valid) []) :=by\n  apply one_base program (ctl pc) finish\n    (.pop (heapStack .valid) (ctl .abort) (ctl .abort) finish) bank _ hcode\n  · simp [SemiprimeD1StackBytecode.execute,SemiprimeD1StackBytecode.choose,hv]\n  · simp [SemiprimeD1StackBytecode.execute,hv]\n/-- One full actual field step includes the real parser call and consumed validity flag. -/\ntheorem field_run (part:Fin 48) (p:P.Stack→List Bool) (heap counter reference word tail:List Bool)\n    (ho:p (I.role part)=[]) :\n    Runs program (8*word.length+8) (ctl (.field part))\n      (view p heap counter reference (frame word tail) []) (next part)\n      (view (Function.update p (I.role part) word) heap counter reference tail []) :=by\n  have h0:=parse_call part (view p heap counter reference (frame word tail) []) word tail rfl ho rfl rfl\n  rw [view_reader,view_phase,view_valid] at h0\n  have h1:=valid_run (.check part) (next part)\n    (view (Function.update p (I.role part) word) heap counter reference tail [true]) rfl rfl\n  rw [view_valid] at h1\n  simpa only [Nat.add_assoc] using join h0 h1\n/-- The complete record is physically checked for EOF before successful return. -/\ntheorem eof_run (p:P.Stack→List Bool) (heap counter reference:List Bool) :\n    Runs program 1 (ctl .eof) (view p heap counter reference [] []) (ctl .done)\n      (view p heap counter reference [] []) :=by\n  apply one_base program (ctl .eof) (ctl .done)\n    (.peek (heapStack .output) (ctl .done) (ctl .abort) (ctl .abort)) _ _ rfl\n  · rfl\n  · rfl\nend RiemannGaussian.SemiprimeD1StackPhaseBankRestorePrimitives\n","RiemannGaussian.SemiprimeD1StackPhaseGeometryValuation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPhaseGeometrySubtract\n/-! # Real low-bit scan, paid padding cleanup, and zero-order reset -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeD1StackPhaseGeometryValuation\nopen SemiprimeD1StackPhaseGeometry SemiprimeD1StackPhaseGeometryArithmetic\nopen SemiprimeD1StackPhaseGeometryPrimitives SemiprimeD1StackProcedureTrace\n/-- Exact order/scan fields; original inputs, binary powers and magnitude are retained. -/\ndef scanData (a t mag sign xs : List Bool) (n : Nat) (zero : List Bool) : Stack→List Bool :=\n  data a t [] (powerWord a.length) (powerWord (a.length+1)) sign zero (List.replicate n true) xs [] [] mag\n/-- Provisional prefix count contributes only if a real one bit is eventually seen. -/\ndef scanOrder (xs : List Bool) (n : Nat) : Nat :=if SemiprimeBitArithmetic.bitValue xs=0 then 0 else n+valuation xs\n/-- Exact scan result, including the actual singleton zero flag. -/\ndef scanResult (a t mag sign xs : List Bool) (n : Nat) : Stack→List Bool :=\n  scanData a t mag sign [] (scanOrder xs n) [decide (SemiprimeBitArithmetic.bitValue xs=0)]\n/-- One actual low zero writes exactly one provisional order marker. -/\ntheorem false_step (a t mag sign xs : List Bool) (n : Nat) :\n    Runs program 2 .scan (scanData a t mag sign (false::xs) n [])\n      .scan (scanData a t mag sign xs (n+1) []) :=by\n  have h0:Runs program 1 .scan (scanData a t mag sign (false::xs) n [])\n      .increment (scanData a t mag sign xs n []):=by\n    apply one_base program .scan .increment (.pop (aux .scan) .clearOrder .increment .clearScan) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k <;> cases k <;> rfl\n  have h1:=push .increment .scan (aux .order) true (scanData a t mag sign xs n []) rfl\n  have he:Function.update (scanData a t mag sign xs n []) (aux .order)\n      (true::scanData a t mag sign xs n [] (aux .order))=scanData a t mag sign xs (n+1) []:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h1\n  exact join h0 h1\n/-- EOF physically drains ALL provisional order markers, so padded zero has order0. -/\ntheorem empty_run (a t mag sign : List Bool) (n : Nat) :\n    Runs program (n+3) .scan (scanData a t mag sign [] n [])\n      .done (scanData a t mag sign [] 0 [true]) :=by\n  have h0:Runs program 1 .scan (scanData a t mag sign [] n [])\n      .clearOrder (scanData a t mag sign [] n []):=by\n    apply one_base program .scan .clearOrder (.pop (aux .scan) .clearOrder .increment .clearScan) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k <;> cases k <;> rfl\n  have h1:=SemiprimeD1StackPhysicalLoops.drain program .clearOrder (.saveZero true) (aux .order)\n    rfl (scanData a t mag sign [] n []) (List.replicate n true)\n  have hi:Function.update (scanData a t mag sign [] n []) (aux .order) (List.replicate n true)=\n      scanData a t mag sign [] n []:=Function.update_eq_self _ _\n  have ho:Function.update (scanData a t mag sign [] n []) (aux .order) []=\n      scanData a t mag sign [] 0 []:=by funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [hi,ho,List.length_replicate] at h1\n  have h2:=push (.saveZero true) .done (aux .zero) true (scanData a t mag sign [] 0 []) rfl\n  have he:Function.update (scanData a t mag sign [] 0 []) (aux .zero)\n      (true::scanData a t mag sign [] 0 [] (aux .zero))=scanData a t mag sign [] 0 [true]:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  convert join (join h0 h1) h2 using 1\n  omega\n/-- After the first actual one, EVERY remaining padding/data cell is physically erased. -/\ntheorem true_run (a t mag sign xs : List Bool) (n : Nat) :\n    Runs program (xs.length+3) .scan (scanData a t mag sign (true::xs) n [])\n      .done (scanData a t mag sign [] n [false]) :=by\n  have h0:Runs program 1 .scan (scanData a t mag sign (true::xs) n [])\n      .clearScan (scanData a t mag sign xs n []):=by\n    apply one_base program .scan .clearScan (.pop (aux .scan) .clearOrder .increment .clearScan) _ _ rfl\n    · rfl\n    · funext k;rcases k with k|k <;> cases k <;> rfl\n  have h1:=SemiprimeD1StackPhysicalLoops.drain program .clearScan (.saveZero false) (aux .scan)\n    rfl (scanData a t mag sign xs n []) xs\n  have hi:Function.update (scanData a t mag sign xs n []) (aux .scan) xs=\n      scanData a t mag sign xs n []:=Function.update_eq_self _ _\n  have ho:Function.update (scanData a t mag sign xs n []) (aux .scan) []=\n      scanData a t mag sign [] n []:=by funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [hi,ho] at h1\n  have h2:=push (.saveZero false) .done (aux .zero) false (scanData a t mag sign [] n []) rfl\n  have he:Function.update (scanData a t mag sign [] n []) (aux .zero)\n      (false::scanData a t mag sign [] n [] (aux .zero))=scanData a t mag sign [] n [false]:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  convert join (join h0 h1) h2 using 1\n  omega\n/-- Whole actual scan is linear in ALL physical input/padding and prior count cells. -/\ntheorem scan_run (a t mag sign xs : List Bool) (n : Nat) :\n    ∃q≤10*(xs.length+1)+2*n,Runs program q .scan (scanData a t mag sign xs n [])\n      .done (scanResult a t mag sign xs n) :=by\n  induction xs generalizing n with\n  | nil=>\n    refine ⟨n+3,by simp only [List.length_nil];omega,?_⟩\n    exact empty_run a t mag sign n\n  | cons b xs ih=>\n    cases b with\n    | true=>\n      refine ⟨xs.length+3,by simp only [List.length_cons];omega,?_⟩\n      have hz:SemiprimeBitArithmetic.bitValue (true::xs)≠0:=by\n        change 1+2*SemiprimeBitArithmetic.bitValue xs≠0\n        omega\n      have he:scanResult a t mag sign (true::xs) n=scanData a t mag sign [] n [false]:=by\n        simp only [scanResult,scanOrder,hz,ite_false,valuation,Nat.add_zero,decide_false]\n      rw [he]\n      exact true_run a t mag sign xs n\n    | false=>\n      obtain ⟨q,hq,hr⟩:=ih (n+1)\n      have hh:=join (false_step a t mag sign xs n) hr\n      have hz:(SemiprimeBitArithmetic.bitValue (false::xs)=0)↔SemiprimeBitArithmetic.bitValue xs=0:=by\n        change (0+2*SemiprimeBitArithmetic.bitValue xs=0)↔_\n        omega\n      have ho:scanOrder (false::xs) n=scanOrder xs (n+1):=by\n        unfold scanOrder\n        simp only [hz]\n        by_cases h:SemiprimeBitArithmetic.bitValue xs=0\n        · simp only [h,ite_true]\n        · simp only [h,ite_false,valuation]\n          omega\n      have he:scanResult a t mag sign (false::xs) n=scanResult a t mag sign xs (n+1):=by\n        unfold scanResult\n        rw [ho]\n        simp only [hz]\n      refine ⟨2+q,by simp only [List.length_cons];omega,?_⟩\n      rw [he]\n      exact hh\nend RiemannGaussian.SemiprimeD1StackPhaseGeometryValuation\n","RiemannGaussian.SemiprimeD1StackPortCatalogueEmit":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortCataloguePrimitives\nimport RiemannGaussian.SemiprimeD1StackPortCatalogueView\nimport RiemannGaussian.SemiprimeD1StackEdgeCatalogueEmit\n/-! # Actual eight-field occurrence framing, with all copy/reversal transitions -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortCatalogueEmit\nopen SemiprimeD1StackPortCatalogue SemiprimeD1StackPortCataloguePrimitives\nopen SemiprimeD1StackPortCatalogueView\nopen SemiprimeD1StackProcedureFragments (Runs)\nopen SemiprimeD1EdgeCatalogueEncoding (Record record)\nopen SemiprimeSourceHistogramKeyBits (frame frame_length)\n/-- Static next field, then the actual local-slot counter increment. -/\ndef nextField (part:Fin 8) : Label :=\n  if h:part.val<7 then .local (.emitFrame ⟨part.val+1,by omega⟩) else .local .incrementSlot\n/-- Literal cached occurrence/factor/local ordinals precede the original descriptor. -/\ndef sourceField (words:Record) (slot factor occurrence:List Bool) (part:Fin 8) : List Bool :=\n  if part.val=0 then occurrence else if part.val=1 then factor else if part.val=2 then slot\n  else words ⟨part.val-3,by omega⟩\n/-- Every emitted field is physically present in its mapped source stack. -/\ntheorem source_clean (base:V.Stack→List Bool) (tape:List Bool) (words:Record)\n    (raw slot edges factor occurrence remaining:List Bool) (part:Fin 8) :\n    clean base tape words raw slot edges factor occurrence remaining (frameSource part)=\n      sourceField words slot factor occurrence part := by fin_cases part <;> rfl\n/-- One real Frame call and one real Reverse call emit the actual cached field. -/\ntheorem field_run (base:V.Stack→List Bool) (tape:List Bool) (words:Record)\n    (raw slot edges factor occurrence remaining:List Bool) (part:Fin 8) :\n    Runs program (10*(sourceField words slot factor occurrence part).length+10) (.local (.emitFrame part))\n      (clean base tape words raw slot edges factor occurrence remaining) (nextField part)\n      (clean base tape words ((frame (sourceField words slot factor occurrence part) []).reverse++raw) slot edges factor occurrence remaining) := by\n  let before:=clean base tape words raw slot edges factor occurrence remaining\n  let word:=sourceField words slot factor occurrence part\n  have hf:=frame_call part before rfl rfl\n  have hsource:before (frameSource part)=word:=source_clean base tape words raw slot edges factor occurrence remaining part\n  rw [hsource] at hf\n  have hr:=reverse_call false (Function.update before (oldAux .frameBuffer) (frame word []))\n    (.local (.emitReverse part)) (nextField part) rfl\n  have hi:(Function.update before (oldAux .frameBuffer) (frame word [])) (reverseInput false)=frame word []:=\n    Function.update_self _ _ _\n  have ho:(Function.update before (oldAux .frameBuffer) (frame word [])) (reverseOutput false)=raw:=by\n    simp [reverseOutput,before,clean,store,oldClean,oldAux,edgeStack,E.aux,Function.update]\n  rw [hi,ho] at hr\n  change Runs program _ _ _ _ (Function.update (Function.update\n    (Function.update before (oldAux .frameBuffer) (frame word [])) (oldAux .frameBuffer) [])\n      (oldAux .reversed) ((frame word []).reverse++raw)) at hr\n  rw [Function.update_idem] at hr\n  have he:Function.update before (oldAux .frameBuffer) []=before:=by\n    have hh:before (oldAux .frameBuffer)=[]:=rfl\n    rw [←hh]\n    exact Function.update_eq_self _ _\n  rw [he,clean_raw] at hr\n  have h:=hf.trans hr\n  rw [frame_length,List.length_nil] at h\n  simpa only [show (6*word.length+5)+(2*(2*word.length+0+1)+3)=10*word.length+10 by omega] using h\n\n/-- Actual eight-field byte record, including every ordinal rather than an advised ID. -/\ndef record8 (words:Record) (slot factor occurrence tail:List Bool) : List Bool :=\n  frame occurrence (frame factor (frame slot (record words tail)))\n/-- Exact byte mass copied by the eight physical component pairs. -/\ndef mass8 (words:Record) (slot factor occurrence:List Bool) : ℕ :=\n  occurrence.length+factor.length+slot.length+SemiprimeD1StackEdgeCatalogueParse.wordMass words\n/-- The actual eight-call output has the exact original ordinal/descriptor order. -/\ntheorem reverse_record8 (words:Record) (slot factor occurrence raw:List Bool) :\n    (frame (words 4) []).reverse++((frame (words 3) []).reverse++((frame (words 2) []).reverse++\n      ((frame (words 1) []).reverse++((frame (words 0) []).reverse++((frame slot []).reverse++\n        ((frame factor []).reverse++((frame occurrence []).reverse++raw)))))))=\n      (record8 words slot factor occurrence []).reverse++raw := by\n  symm\n  unfold record8 record\n  rw [SemiprimeD1StackEdgeCatalogueEmit.frame_append occurrence,\n    SemiprimeD1StackEdgeCatalogueEmit.frame_append factor,\n    SemiprimeD1StackEdgeCatalogueEmit.frame_append slot,\n    SemiprimeD1StackEdgeCatalogueEmit.frame_append (words 0),\n    SemiprimeD1StackEdgeCatalogueEmit.frame_append (words 1),\n    SemiprimeD1StackEdgeCatalogueEmit.frame_append (words 2),\n    SemiprimeD1StackEdgeCatalogueEmit.frame_append (words 3)]\n  simp only [List.reverse_append,List.append_assoc]\n/-- All eight actual fields execute once each, including the actual occurrence/local IDs. -/\ntheorem record_run (base:V.Stack→List Bool) (tape:List Bool) (words:Record)\n    (raw slot edges factor occurrence remaining:List Bool) :\n    Runs program (10*mass8 words slot factor occurrence+80) (.local (.emitFrame 0))\n      (clean base tape words raw slot edges factor occurrence remaining) (.local .incrementSlot)\n      (clean base tape words ((record8 words slot factor occurrence []).reverse++raw)\n        slot edges factor occurrence remaining) := by\n  let r1:=(frame (occurrence) []).reverse++raw\n  let r2:=(frame (factor) []).reverse++r1\n  let r3:=(frame (slot) []).reverse++r2\n  let r4:=(frame (words 0) []).reverse++r3\n  let r5:=(frame (words 1) []).reverse++r4\n  let r6:=(frame (words 2) []).reverse++r5\n  let r7:=(frame (words 3) []).reverse++r6\n  have h0:=field_run base tape words raw slot edges factor occurrence remaining 0\n  have h1:=field_run base tape words r1 slot edges factor occurrence remaining 1\n  have h2:=field_run base tape words r2 slot edges factor occurrence remaining 2\n  have h3:=field_run base tape words r3 slot edges factor occurrence remaining 3\n  have h4:=field_run base tape words r4 slot edges factor occurrence remaining 4\n  have h5:=field_run base tape words r5 slot edges factor occurrence remaining 5\n  have h6:=field_run base tape words r6 slot edges factor occurrence remaining 6\n  have h7:=field_run base tape words r7 slot edges factor occurrence remaining 7\n  have h:=h0.trans (h1.trans (h2.trans (h3.trans (h4.trans (h5.trans (h6.trans (h7)))))))\n  change Runs program _ _ _ (.local .incrementSlot) (clean base tape words\n    ((frame (words 4) []).reverse++((frame (words 3) []).reverse++((frame (words 2) []).reverse++\n      ((frame (words 1) []).reverse++((frame (words 0) []).reverse++((frame slot []).reverse++\n        ((frame factor []).reverse++((frame occurrence []).reverse++raw))))))))\n    slot edges factor occurrence remaining) at h\n  rw [reverse_record8] at h\n  have ht:(10*occurrence.length+10+(10*factor.length+10+(10*slot.length+10+\n      (10*(words 0).length+10+(10*(words 1).length+10+(10*(words 2).length+10+\n        (10*(words 3).length+10+(10*(words 4).length+10))))))))=\n      10*mass8 words slot factor occurrence+80:=by\n    unfold mass8 SemiprimeD1StackEdgeCatalogueParse.wordMass\n    omega\n  change Runs program (10*occurrence.length+10+(10*factor.length+10+(10*slot.length+10+\n      (10*(words 0).length+10+(10*(words 1).length+10+(10*(words 2).length+10+\n        (10*(words 3).length+10+(10*(words 4).length+10)))))))) _ _ _ _ at h\n  rw [ht] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackPortCatalogueEmit\n","RiemannGaussian.SemiprimeD1StackPortCatalogueSource":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortCataloguePrimitives\n/-! # Original-N source calls of the complete physical port producer -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortCatalogueSource\nopen SemiprimeD1StackPortCatalogue SemiprimeD1StackPortCatalogueComponents\nopen SemiprimeD1StackPortCataloguePrimitives\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\n/-- Exact data after the real original vertex catalogue, all new work initially empty. -/\ndef afterVertex (bits:List Bool) : Stack→List Bool :=\n  Sum.elim (SemiprimeD1StackEdgeCatalogueExecution.afterCat bits) (fun _=>[])\n/-- Actual physically copied source descriptors before the shared edge parser executes. -/\ndef copied (bits:List Bool) : Stack→List Bool :=\n  Function.update (afterVertex bits) (aux .reader) (afterVertex bits vertexReader)\n/-- Actual data after original edge generation, preserving the private descriptor copy. -/\ndef afterEdges (bits:List Bool) : Stack→List Bool :=\n  Sum.elim (SemiprimeD1StackEdgeCatalogueExecution.result bits)\n    (Function.update (fun _=>[]) Aux.reader (afterVertex bits vertexReader))\n/-- Actual nonempty binary-input guard; input N is never converted to unary. -/\ntheorem input_guard (bits:List Bool) (hb:bits≠[]) :\n    Runs program 1 (.local .main) (input bits) (.local .callVertex) (input bits) := by\n  apply one_base program _ _ (.peek originalInput (.local .halt) (.local .callVertex) (.local .callVertex)) _ _ rfl\n  · change some (SemiprimeD1StackBytecode.choose (Label.local .halt) (.local .callVertex)\n      (.local .callVertex) bits.head?)=some (.local .callVertex)\n    cases bits with\n    | nil => exact False.elim (hb rfl)\n    | cons b bs => cases b <;> rfl\n  · rfl\n/-- The whole vertex source executes ONCE from original binary N, not from a prepared graph. -/\ntheorem vertex_call (bits:List Bool) (hb:bits≠[]) :\n    ∃ time ≤ 10000000000000*(bits.length+1)^5+1,\n      Runs program time (.local .callVertex) (input bits) (.local .copyVertex) (afterVertex bits) := by\n  obtain ⟨m,hm,hr⟩:=SemiprimeD1StackVertexCatalogueBounds.source_run_polynomial bits hb\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program vertexStack Label.vertex vertexStack_injective\n    V.program (.inl .main) (fun _=>rfl) (.local .callVertex) (.local .copyVertex) rfl m\n    (SemiprimeD1StackVertexCatalogue.initial bits) (SemiprimeD1StackVertexCatalogueExecution.done bits)\n    (input bits) (afterVertex bits)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with (k|k)|k\n      · exact False.elim (hk k rfl)\n      · rcases k with k|k <;> rfl\n      · rfl\n/-- The private source copy is paid before its original is consumed by edge acquisition. -/\ntheorem copy_vertex (bits:List Bool) :\n    Runs program (5*(afterVertex bits vertexReader).length+4) (.local .copyVertex)\n      (afterVertex bits) (.local .callEdges) (copied bits) := by\n  have h:=copy_call (afterVertex bits) rfl\n  simpa only [show afterVertex bits (aux .reader)=[] from rfl,List.append_nil,copied] using h\n/-- Shared original edge stage executes without rerunning metadata or the vertex catalogue. -/\ntheorem edge_source (bits:List Bool) :\n    ∃ time ≤ 56*(SemiprimeD1EdgeCatalogueEncoding.tape\n      (SemiprimeD1StackEdgeCatalogueExecution.records bits) []).length+5,\n      C.run E.program time\n        (⟨some (.inl .parse),none,none,SemiprimeD1StackEdgeCatalogueExecution.afterCat bits,[]⟩:C.State E.Stack E.Label)=\n          some (SemiprimeD1StackEdgeCatalogueExecution.done bits) := by\n  obtain ⟨m,hm,h⟩:=SemiprimeD1StackEdgeCatalogueExecution.ready_original bits\n  obtain ⟨finish,hr,hout⟩:=h []\n    (⟨some (.inl .parse),none,none,SemiprimeD1StackEdgeCatalogueExecution.afterCat bits,[]⟩:C.State E.Stack E.Label)\n    ⟨rfl,rfl,rfl⟩\n  refine ⟨m+1,by omega,?_⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n  rcases hout with ⟨hpc,hdata,hframes⟩\n  change C.step E.program finish=some (SemiprimeD1StackEdgeCatalogueExecution.done bits)\n  simp [C.step,SemiprimeD1StackCalls.step,hpc,E.program,C.execute,SemiprimeD1StackCalls.execute,hdata,hframes,\n    SemiprimeD1StackEdgeCatalogueExecution.done]\n/-- The actual parser call retains the original descriptor copy and all foreign counters. -/\ntheorem edges_call (bits:List Bool) :\n    ∃ time ≤ 56*(SemiprimeD1EdgeCatalogueEncoding.tape\n      (SemiprimeD1StackEdgeCatalogueExecution.records bits) []).length+6,\n      Runs program time (.local .callEdges) (copied bits) (.local .parse) (afterEdges bits) := by\n  obtain ⟨m,hm,hr⟩:=edge_source bits\n  refine ⟨m+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program edgeStack Label.edges edgeStack_injective\n    E.program (.inl .parse) (fun _=>rfl) (.local .callEdges) (.local .parse) rfl m\n    (⟨some (.inl .parse),none,none,SemiprimeD1StackEdgeCatalogueExecution.afterCat bits,[]⟩:C.State E.Stack E.Label)\n    (SemiprimeD1StackEdgeCatalogueExecution.done bits) (copied bits) (afterEdges bits)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;simp [copied,afterVertex,edgeStack,aux,Function.update]\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k => exact False.elim (hk k rfl)\n      | inr k => cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackPortCatalogueSource\n","RiemannGaussian.SemiprimeD1StackPortCatalogueTransduction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortCatalogueScan\n/-! # Complete original factor-major transduction of all actual acquired descriptors -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortCatalogueTransduction\nopen SemiprimeD1StackPortCatalogue SemiprimeD1StackPortCatalogueView\nopen SemiprimeD1StackPortCatalogueArity SemiprimeD1StackPortCatalogueLoop\nopen SemiprimeD1StackPortCatalogueEmit (record8)\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeD1EdgeCatalogueEncoding (Record record vertex tape)\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeMacroGraph\n/-- Mathematical output of the actual factor-major port loop. -/\ndef output {r t digits:ℕ} : List (SubdividedVertex r t digits)→ℕ→ℕ→List Bool→List Bool\n  | [],_,_,tail => tail\n  | v::vs,f,n,tail => records (vertex v) (subdividedArity v) n f 0\n      (output vs (f+1) (n+subdividedArity v) tail)\n/-- Actual accumulated local transition upper bounds, retaining arity work for every vertex. -/\ndef scanTime {r t digits:ℕ} : List (SubdividedVertex r t digits)→ℕ→ℕ→ℕ\n  | [],_,_ => 0\n  | v::vs,f,n => SemiprimeD1StackPortCatalogueScan.recordTime v n f+\n      scanTime vs (f+1) (n+subdividedArity v)\n/-- Exact total number of original occurrences, independent of serialized-byte length. -/\ndef count {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) : ℕ :=\n  (vs.map subdividedArity).sum\n/-- Every recursive record constructor preserves its literal actual suffix. -/\ntheorem records_append (words:Record) (fuel n f slot:ℕ) (tail:List Bool) :\n    records words fuel n f slot tail=records words fuel n f slot []++tail := by\n  induction fuel generalizing n slot with\n  | zero => rfl\n  | succ fuel ih =>\n    simp only [records]\n    rw [ih,SemiprimeD1StackPortCatalogueLoop.record8_append]\n    conv_rhs => rw [SemiprimeD1StackPortCatalogueLoop.record8_append]\n    simp only [List.append_assoc]\n/-- The physical recursive loop is the exact ascending original local-slot enumeration. -/\ntheorem records_range (words:Record) (fuel n f slot:ℕ) (tail:List Bool) :\n    records words fuel n f slot tail=(List.range fuel).foldr\n      (fun j rest=>SemiprimeD1PortCatalogueEncoding.encode (n+j) f (slot+j) words rest) tail := by\n  induction fuel generalizing n slot with\n  | zero => rfl\n  | succ fuel ih =>\n    rw [List.range_succ_eq_map,List.foldr_cons,List.foldr_map,records,ih]\n    simp only [Nat.add_zero,record8,SemiprimeD1PortCatalogueEncoding.encode]\n    simp only [Nat.succ_eq_add_one,Nat.add_left_comm,Nat.add_comm]\n/-- Exact original factor-major port specification, preserving all duplicates and zero-arity factors. -/\ntheorem output_original {r t digits:ℕ} (vs:List (SubdividedVertex r t digits)) (f n:ℕ) (tail:List Bool) :\n    output vs f n tail=SemiprimeD1PortCatalogueEncoding.fromVertices vs f n tail := by\n  induction vs generalizing f n with\n  | nil => rfl\n  | cons v vs ih =>\n    rw [output,ih,SemiprimeD1PortCatalogueEncoding.fromVertices,records_range]\n    simp only [Nat.zero_add,SemiprimeD1PortCatalogueEncoding.slots]\n/-- All original factors are actually traversed, including every zero-arity factor. -/\ntheorem scan_run {r t digits:ℕ} (vs:List (SubdividedVertex r t digits))\n    (base:V.Stack→List Bool) (hm:Metadata r t digits base) (raw edges:List Bool) (f n:ℕ) :\n    ∃ time ≤ scanTime vs f n,Runs program time (.local .parse)\n      (clean base (tape (vs.map vertex) []) (fun _=>[]) raw [] edges (unary f) (unary n) [])\n      (.local .parse)\n      (clean base [] (fun _=>[]) ((output vs f n []).reverse++raw)\n        [] edges (unary (f+vs.length)) (unary (n+count vs)) []) := by\n  induction vs generalizing raw f n with\n  | nil =>\n    refine ⟨0,by exact Nat.le_refl 0,?_⟩\n    simpa only [tape,List.foldr_nil,List.map_nil,output,List.reverse_nil,List.nil_append,List.length_nil,\n      count,List.sum_nil,Nat.add_zero] using\n      (Runs.refl program (.local .parse) (clean base [] (fun _=>[]) raw [] edges (unary f) (unary n) []))\n  | cons v vs ih =>\n    obtain ⟨a,ha,h0⟩:=SemiprimeD1StackPortCatalogueScan.record_run v base hm\n      (tape (vs.map vertex) []) raw edges f n\n    let nextRaw:=(records (vertex v) (subdividedArity v) n f 0 []).reverse++raw\n    obtain ⟨b,hb,h1⟩:=ih nextRaw (f+1) (n+subdividedArity v)\n    have h:=h0.trans h1\n    have hout:(output vs (f+1) (n+subdividedArity v) []).reverse++nextRaw=\n        (output (v::vs) f n []).reverse++raw:=by\n      rw [output,records_append]\n      simp only [List.reverse_append,List.append_assoc,nextRaw]\n    rw [hout] at h\n    refine ⟨a+b,by simp only [scanTime];omega,?_⟩\n    simpa only [List.map_cons,tape,List.foldr_cons,List.length_cons,count,List.map_cons,List.sum_cons,\n      show f+1+vs.length=f+(vs.length+1) by omega,\n      show n+subdividedArity v+(vs.map subdividedArity).sum=\n        n+(subdividedArity v+(vs.map subdividedArity).sum) by omega] using h\n/-- Final physical data retain the complete edge tape and both acquired cardinality tallies. -/\ndef finalData (base:V.Stack→List Bool) (edges ports:List Bool) (f n:ℕ) : Stack→List Bool :=\n  Function.update (clean base [] (fun _=>[]) [] [] edges (unary f) (unary n) []) (aux .output) ports\n/-- Actual final EOF peek does not discard any payload. -/\ntheorem eof_run (base:V.Stack→List Bool) (raw edges:List Bool) (f n:ℕ) :\n    Runs program 1 (.local .parse) (clean base [] (fun _=>[]) raw [] edges (unary f) (unary n) [])\n      (.local .finalReverse) (clean base [] (fun _=>[]) raw [] edges (unary f) (unary n) []) := by\n  apply one_base program _ _ (.peek (aux .reader) (.local .finalReverse)\n    (.local (.field 0)) (.local (.field 0))) _ _ rfl\n  · rfl\n  · rfl\n/-- Whole real transducer, including its final reverse and physically retained counts. -/\ntheorem ready {r t digits:ℕ} (vs:List (SubdividedVertex r t digits))\n    (base:V.Stack→List Bool) (hm:Metadata r t digits base) (edges:List Bool) :\n    ∃ time ≤ scanTime vs 0 0+2*(output vs 0 0 []).length+4,\n      Runs program time (.local .parse)\n        (clean base (tape (vs.map vertex) []) (fun _=>[]) [] [] edges [] [] []) (.local .halt)\n        (finalData base edges (output vs 0 0 []) vs.length (count vs)) := by\n  obtain ⟨a,ha,h0⟩:=scan_run vs base hm [] edges 0 0\n  simp only [Nat.zero_add,List.append_nil,show unary 0=[] from rfl] at h0\n  have h1:=eof_run base (output vs 0 0 []).reverse edges vs.length (count vs)\n  have h2:=SemiprimeD1StackPortCataloguePrimitives.reverse_call true\n    (clean base [] (fun _=>[]) (output vs 0 0 []).reverse [] edges (unary vs.length) (unary (count vs)) [])\n    (.local .finalReverse) (.local .halt) rfl\n  change Runs program (2*(output vs 0 0 []).reverse.length+3) _ _ _\n    (Function.update (Function.update\n      (clean base [] (fun _=>[]) (output vs 0 0 []).reverse [] edges (unary vs.length) (unary (count vs)) [])\n        (oldAux .reversed) []) (aux .output) ((output vs 0 0 []).reverse.reverse++[])) at h2\n  rw [List.length_reverse,List.reverse_reverse,List.append_nil,clean_raw] at h2\n  refine ⟨a+(1+(2*(output vs 0 0 []).length+3)),by omega,?_⟩\n  exact h0.trans (h1.trans h2)\nend RiemannGaussian.SemiprimeD1StackPortCatalogueTransduction\n","RiemannGaussian.SemiprimeD1StackPortOrdinalStreamExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortOrdinalStreamComponents\nimport RiemannGaussian.SemiprimeD1StackDigitBankSpec\n/-! # Whole physical binary-ID stream conversion -/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortOrdinalStreamExecution\nopen SemiprimeD1StackPortOrdinalStream SemiprimeD1StackPortOrdinalStreamComponents\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackDigitBankSpec (entries entries_vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => SemiprimeD1StackPortOrdinalStream.Label.control\n/-- Exact metadata-only converted words, never a runtime supplier. -/\ndef unaryWords (words:List (List Bool)) : List (List Bool) :=\n  words.map fun w=>List.replicate (SemiprimeBitArithmetic.bitValue w) true\n/-- Every parser, unary conversion, logger and cleanup is retained. -/\ndef loopBudget : List (List Bool)→Nat\n  | [] => 1\n  | w::ws => 21*SemiprimeBitArithmetic.bitValue w+14*w.length+40+loopBudget ws\n/-- The actual EOF-controlled loop processes every record, including zero IDs. -/\ntheorem loop_run (words:List (List Bool)) (bank hist:List Bool) :\n    ∃t≤loopBudget words,Runs program t (ctl .next)\n      (data bank (SemiprimeD1TensorTapeCodec.vectorBits words) [] [] [] hist [])\n      (ctl .finish) (data bank [] [] [] [] ((entries (unaryWords words)).reverse++hist) []) := by\n  induction words generalizing hist with\n  | nil =>\n    refine ⟨1,le_refl _,?_⟩\n    simp only [unaryWords,List.map_nil,entries,List.reverse_nil,List.nil_append]\n    apply one_base program (ctl .next) (ctl .finish)\n      (.pop .reader (ctl .finish) (ctl .finish) (ctl .parse)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  | cons w ws ih =>\n    let tail:=SemiprimeD1TensorTapeCodec.vectorBits ws\n    let u:=List.replicate (SemiprimeBitArithmetic.bitValue w) true\n    let nextHist:=(true::frame u []).reverse++hist\n    have h0 : Runs program 1 (ctl .next)\n        (data bank (SemiprimeD1TensorTapeCodec.vectorBits (w::ws)) [] [] [] hist [])\n        (ctl .parse) (data bank (frame w tail) [] [] [] hist []) := by\n      apply one_base program (ctl .next) (ctl .parse)\n        (.pop .reader (ctl .finish) (ctl .finish) (ctl .parse)) _ _ rfl\n      · rfl\n      · funext k;cases k <;> rfl\n    have h1:=field_call bank w tail hist\n    have h2:=clear_valid bank tail w hist\n    obtain ⟨a,ha,h3⟩:=unary_call bank tail w hist\n    obtain ⟨b,hb,h4⟩:=log_call bank tail u hist\n    have h5:=clear_unary bank tail u nextHist\n    obtain ⟨t,ht,h6⟩:=ih nextHist\n    have h:=runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _\n        (runs_trans program _ _ _ _ _ _ _ _\n          (runs_trans program _ _ _ _ _ _ _ _\n            (runs_trans program _ _ _ _ _ _ _ _\n              (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3) h4) h5) h6\n    refine ⟨1+(8*w.length+7)+1+a+b+(u.length+1)+t,?_,?_⟩\n    · have hu:u.length=SemiprimeBitArithmetic.bitValue w:=List.length_replicate\n      simp only [loopBudget]\n      omega\n    · simpa only [unaryWords,List.map_cons,entries,List.reverse_append,List.append_assoc] using h\n\n\n/-- Explicit whole trace allowance includes the final physical log reversal. -/\ndef timeBound (words:List (List Bool)) : Nat :=\n  5*(SemiprimeD1TensorTapeCodec.vectorBits words).length+loopBudget words+\n    2*(entries (unaryWords words)).length+7\n/-- Exact halt keeps the original binary bank and clears every private role. -/\ndef done (words:List (List Bool)) : C.State Stack Label :=\n  ⟨none,none,none,data (SemiprimeD1TensorTapeCodec.vectorBits words) [] [] [] [] []\n    (SemiprimeD1StackPortOrdinalStream.result words),[]⟩\n/-- Closed actual stream execution; neither decoded ports nor unary answers enter. -/\ntheorem source_run (words:List (List Bool)) :\n    ∃t≤timeBound words,SemiprimeD1StackCalls.run program t\n      (initial (SemiprimeD1TensorTapeCodec.vectorBits words))=some (done words) := by\n  let bank:=SemiprimeD1TensorTapeCodec.vectorBits words\n  let encoded:=entries (unaryWords words)\n  have h0:=copy_call bank\n  obtain ⟨m,hm,h1⟩:=loop_run words bank []\n  simp only [List.append_nil] at h1\n  have h2 : Runs program 1 (ctl .finish) (data bank [] [] [] [] encoded.reverse [])\n      (ctl .reverse) (data bank [] [] [] [] encoded.reverse [false]) := by\n    apply one_base program (ctl .finish) (ctl .reverse) (.push .output false (ctl .reverse)) _ _ rfl\n    · rfl\n    · funext k;cases k <;> rfl\n  have h3:=reverse_run encoded.reverse bank [false]\n  simp only [List.length_reverse,List.reverse_reverse] at h3\n  have h:=runs_trans program _ _ _ _ _ _ _ _\n    (runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2) h3\n  obtain ⟨finish,hr,ho⟩:=h [] (initial bank) ⟨rfl,by funext k;cases k <;> rfl,rfl⟩\n  have he:=halt_run program (ctl .done) rfl\n    (data bank [] [] [] [] [] (encoded++[false])) [] finish ho\n  refine ⟨(5*bank.length+4)+m+1+(2*encoded.length+1)+1,?_,?_⟩\n  · change (5*bank.length+4)+m+1+(2*encoded.length+1)+1 ≤\n      5*bank.length+loopBudget words+2*encoded.length+7\n    omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,he]\n    have hvec:encoded++[false]=SemiprimeD1StackPortOrdinalStream.result words := entries_vectorBits _\n    rw [hvec]\n    rfl\nend RiemannGaussian.SemiprimeD1StackPortOrdinalStreamExecution\n","RiemannGaussian.SemiprimeD1StackPortScopeTransduction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPortScopeScan\n/-! # Whole actual equal-length port/ID stream transduction -/\nset_option autoImplicit false\nset_option maxHeartbeats 2000000\nset_option maxRecDepth 32000\nset_option synthInstance.maxSize 131072\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackPortScopeTransduction\nopen SemiprimeD1StackPortScopeRecords SemiprimeD1StackPortScopeView\nopen SemiprimeD1StackProcedureFragments (Runs one_base)\nopen SemiprimeD1PortScopeEncoding (Port portFrame portTape scopeFrame output portMass)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame_length)\n/-- Exact local actual transition sum over the physically matched streams. -/\ndef scanTime : List Port→List (List Bool)→ℕ\n  | w::ws,id::ids => SemiprimeD1StackPortScopeScan.recordTime w id+scanTime ws ids\n  | _,_ => 0\n/-- Both streams are consumed in their actual order; no provided index inverse or gather answer. -/\ntheorem scan_run (ports:List Port) (ids:List (List Bool)) (hlen:ports.length=ids.length)\n    (base:S.Stack→List Bool) (raw:List Bool) :\n    Runs program (scanTime ports ids) (.local .parse)\n      (clean base (portTape ports []) (vectorBits ids) (fun _=>[]) raw) (.local .parse)\n      (clean base [] [false] (fun _=>[]) ((output ports ids []).reverse++raw)) := by\n  induction ports generalizing ids raw with\n  | nil =>\n    have he:ids=[]:=List.eq_nil_of_length_eq_zero hlen.symm\n    subst ids\n    simpa only [scanTime,portTape,List.foldr_nil,vectorBits,output,List.reverse_nil,List.nil_append] using\n      Runs.refl program (.local .parse) (clean base [] [false] (fun _=>[]) raw)\n  | cons w ws ih =>\n    cases ids with\n    | nil => simp at hlen\n    | cons id ids =>\n      have hr:ws.length=ids.length:=by simpa only [List.length_cons,Nat.add_right_cancel_iff] using hlen\n      have h0:=SemiprimeD1StackPortScopeScan.record_run base w id (portTape ws []) (vectorBits ids) raw\n      let nextRaw:=(scopeFrame w id []).reverse++raw\n      have h1:=ih ids hr nextRaw\n      have h:=h0.trans h1\n      have hout:(output ws ids []).reverse++nextRaw=(output (w::ws) (id::ids) []).reverse++raw:=by\n        rw [output,SemiprimeD1PortScopeEncoding.scopeFrame_append]\n        simp only [List.reverse_append,List.append_assoc,nextRaw]\n      rw [hout] at h\n      exact h\n/-- All actual loop transitions are bounded by actual input bytes, including ID widths and every copy. -/\ntheorem scanTime_le (ports:List Port) (ids:List (List Bool)) (hlen:ports.length=ids.length) :\n    scanTime ports ids≤100*((portTape ports []).length+(vectorBits ids).length) := by\n  induction ports generalizing ids with\n  | nil => cases ids <;> simp_all [scanTime]\n  | cons w ws ih =>\n    cases ids with\n    | nil => simp at hlen\n    | cons id ids =>\n      have hr:ws.length=ids.length:=by simpa only [List.length_cons,Nat.add_right_cancel_iff] using hlen\n      have h:=ih ids hr\n      change SemiprimeD1StackPortScopeScan.recordTime w id+scanTime ws ids≤\n        100*((portFrame w (portTape ws [])).length+(true::SemiprimeSourceHistogramKeyBits.frame id (vectorBits ids)).length)\n      rw [SemiprimeD1PortScopeEncoding.portFrame_length,List.length_cons,frame_length]\n      unfold SemiprimeD1StackPortScopeScan.recordTime\n      omega\n/-- Every emitted ID-tagged record is bounded by its actual two source streams. -/\ntheorem output_length_le (ports:List Port) (ids:List (List Bool)) (hlen:ports.length=ids.length) :\n    (output ports ids []).length≤(portTape ports []).length+(vectorBits ids).length := by\n  induction ports generalizing ids with\n  | nil => cases ids <;> simp_all [output,portTape,vectorBits]\n  | cons w ws ih =>\n    cases ids with\n    | nil => simp at hlen\n    | cons id ids =>\n      have hr:ws.length=ids.length:=by simpa only [List.length_cons,Nat.add_right_cancel_iff] using hlen\n      have h:=ih ids hr\n      change (SemiprimeSourceHistogramKeyBits.frame id (portFrame w (output ws ids []))).length≤\n        (portFrame w (portTape ws [])).length+(true::SemiprimeSourceHistogramKeyBits.frame id (vectorBits ids)).length\n      rw [frame_length,SemiprimeD1PortScopeEncoding.portFrame_length,\n        SemiprimeD1PortScopeEncoding.portFrame_length,List.length_cons,frame_length]\n      omega\n/-- Exact final physical data after both copied readers and every field were consumed. -/\ndef finalData (base:S.Stack→List Bool) (out:List Bool) : Stack→List Bool :=\n  Function.update (clean base [] [] (fun _=>[]) []) (aux .output) out\n/-- Three real EOF/tag checks consume the actual vector nil marker. -/\ntheorem eof_run (base:S.Stack→List Bool) (raw:List Bool) :\n    Runs program 3 (.local .parse) (clean base [] [false] (fun _=>[]) raw)\n      (.local .finalReverse) (clean base [] [] (fun _=>[]) raw) := by\n  have h0:Runs program 1 (.local .parse) (clean base [] [false] (fun _=>[]) raw)\n      (.local .bankEnd) (clean base [] [false] (fun _=>[]) raw):=by\n    apply one_base program _ _ (.peek (aux .readerPorts) (.local .bankEnd) (.local (.field 0)) (.local (.field 0))) _ _ rfl <;> rfl\n  have h1:Runs program 1 (.local .bankEnd) (clean base [] [false] (fun _=>[]) raw)\n      (.local .bankEOF) (clean base [] [] (fun _=>[]) raw):=by\n    apply one_base program _ _ (.pop (aux .readerIds) (.local .abort) (.local .bankEOF) (.local .abort)) _ _ rfl\n    · rfl\n    · change Function.update (clean base [] [false] (fun _=>[]) raw) (aux .readerIds) []=_\n      rw [clean_ids]\n  have h2:Runs program 1 (.local .bankEOF) (clean base [] [] (fun _=>[]) raw)\n      (.local .finalReverse) (clean base [] [] (fun _=>[]) raw):=by\n    apply one_base program _ _ (.peek (aux .readerIds) (.local .finalReverse) (.local .abort) (.local .abort)) _ _ rfl <;> rfl\n  exact h0.trans (h1.trans h2)\n/-- Complete actual one-pass zipper, including the literal final reversal. -/\ntheorem ready (ports:List Port) (ids:List (List Bool)) (hlen:ports.length=ids.length)\n    (base:S.Stack→List Bool) :\n    ∃ time ≤ 102*((portTape ports []).length+(vectorBits ids).length)+6,\n      Runs program time (.local .parse) (clean base (portTape ports []) (vectorBits ids) (fun _=>[]) [])\n        (.local .halt) (finalData base (output ports ids [])) := by\n  have h0:=scan_run ports ids hlen base []\n  rw [List.append_nil] at h0\n  have h1:=eof_run base (output ports ids []).reverse\n  have h2:=SemiprimeD1StackPortScopePrimitives.reverse_call true\n    (clean base [] [] (fun _=>[]) (output ports ids []).reverse) (.local .finalReverse) (.local .halt) rfl\n  change Runs program (2*(output ports ids []).reverse.length+3) _ _ _\n    (Function.update (Function.update (clean base [] [] (fun _=>[]) (output ports ids []).reverse)\n      (aux .reversed) []) (aux .output) ((output ports ids []).reverse.reverse++[])) at h2\n  rw [List.length_reverse,List.reverse_reverse,List.append_nil,clean_raw] at h2\n  have h:=h0.trans (h1.trans h2)\n  refine ⟨scanTime ports ids+(3+(2*(output ports ids []).length+3)),?_,h⟩\n  have hs:=scanTime_le ports ids hlen\n  have ho:=output_length_le ports ids hlen\n  omega\nend RiemannGaussian.SemiprimeD1StackPortScopeTransduction\n","RiemannGaussian.SemiprimeD1StackProductCheckFields":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductCheckReject\n\n/-! # Actual three-field parsing inside the product checker\nThese are literal enclosing-program traces. Framing hypotheses identify the\nactual acquired cache layout; no operand value or parser verdict is an input.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 4096\nset_option maxHeartbeats 1200000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackProductCheckFields\nopen SemiprimeD1StackProductCheck SemiprimeD1StackProductCheckAcquisition\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- An actual vector-entry tag is consumed before its field parser executes. -/\ntheorem tag_run (i : Fin 3) (data : Stack→List Bool) (tail : List Bool)\n    (hvec : data vectorRole=true::tail) :\n    Runs program 1 (.tag i) data (.read i) (Function.update data vectorRole tail) := by\n  apply one_base program (.tag i) (.read i) (.pop vectorRole .bad .bad (.read i)) _ _ rfl\n  · simp [SemiprimeD1StackBytecode.execute,hvec,SemiprimeD1StackBytecode.choose]\n  · simp only [SemiprimeD1StackBytecode.execute,hvec,List.tail_cons]\n\n/-- Physical output of one real field call; shared parser scratch is cleared. -/\ndef fieldData (i : Fin 3) (data : Stack→List Bool) (word tail : List Bool) : Stack→List Bool :=\n  Function.update (Function.update (Function.update data vectorRole tail) (operand i) word) (auxiliary 1) [true]\n\n/-- Complete actual Field bytecode obtains exactly the raw payload and true\nvalidity cell, preserving every other physical caller cell. -/\ntheorem field_call (i : Fin 3) (data : Stack→List Bool) (word tail : List Bool)\n    (hvec : data vectorRole=frame word tail) (hop : data (operand i)=[])\n    (hscratch : data (auxiliary 0)=[]) (hvalid : data (auxiliary 1)=[]) :\n    Runs program (8*word.length+7) (.read i) data (.parsed i) (fieldData i data word tail) := by\n  apply included_call program (fieldStack i) (Label.field i) (fieldStack_injective i)\n    F.code (F.active .tagPop (none,false)) (fun _=>rfl) (.read i) (.parsed i) rfl (8*word.length+6)\n    (SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩:\n      SemiprimeD1StackBytecode.State F.Stack F.Label)\n    data (fieldData i data word tail)\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · constructor\n    · intro k\n      rcases k with k|k\n      · cases k <;> simpa only [fieldStack,vectorRole] using (by first | exact hvec | exact hscratch | exact hop)\n      · cases k;exact hvalid\n    · intro k _;rfl\n  · constructor\n    · intro k\n      simp only [auxiliary] at hscratch\n      fin_cases i <;> rcases k with k|k <;> cases k <;>\n        simp [fieldData,Function.update,fieldStack,operand,vectorRole,vectorStack,SemiprimeD1StackWordVector.output,\n          auxiliary,equalPrivate,multiplyStack,multiplyLeft,multiplyRight,SemiprimeD1TensorTapeFieldMachine.contents,\n          hscratch]\n    · intro k hk\n      have hv : k≠vectorRole := by intro h;subst k;exact hk (.inl .input) rfl\n      have ho : k≠operand i := by intro h;subst k;exact hk (.inl .output) rfl\n      have hf : k≠auxiliary 1 := by intro h;subst k;exact hk (.inr ()) rfl\n      simp only [fieldData,Function.update_of_ne hv,Function.update_of_ne ho,Function.update_of_ne hf]\n\n/-- The actual parser's singleton validity flag is physically consumed. -/\ntheorem parsed_run (i : Fin 3) (data : Stack→List Bool) (hvalid : data (auxiliary 1)=[true]) :\n    Runs program 1 (.parsed i) data (afterField i) (Function.update data (auxiliary 1) []) := by\n  apply one_base program (.parsed i) (afterField i)\n    (.pop (auxiliary 1) .bad .bad (afterField i)) _ _ rfl\n  · simp [SemiprimeD1StackBytecode.execute,hvalid,SemiprimeD1StackBytecode.choose]\n  · simp only [SemiprimeD1StackBytecode.execute,hvalid,List.tail_cons]\n\nend RiemannGaussian.SemiprimeD1StackProductCheckFields\n","RiemannGaussian.SemiprimeD1StackProductTableBootstrap":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductTableBootstrapParts\n/-! # Entire N-only product-table bootstrap and its OWN physical clock\nOriginal N is actually copied, public constants are acquired ONCE, three actual\nword scans acquire arity, and every public/checker role is physically cleared.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackProductTableBootstrap\nopen SemiprimeD1StackProductTable SemiprimeD1StackProductTableState\nopen SemiprimeD1StackProductTableBootstrapParts SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nnamespace A\nexport SemiprimeD1BinaryPublicAcquisition (Stack Label program initial)\nend A\n/-- The closed start has only original N, not a width/table/cache answer. -/\ntheorem initial_data (bits : List Bool) : (initial bits).data=data bits 0 [] [] := by\n  funext k\n  cases k with\n  | inl k=>rfl\n  | inr k=>cases k <;> rfl\n/-- Actual retained-N copy into the public source's real input register. -/\ntheorem source_copy (bits : List Bool) :\n    Runs program (5*bits.length+4) .start (initial bits).data .bootstrap (checkerReady bits [] []) := by\n  rw [initial_data]\n  have h:=SemiprimeD1StackProductTablePrimitives.copy_call .source .start .bootstrap rfl (data bits 0 [] []) rfl rfl\n  have hr:rawReady bits [] []=data bits 0 [] [] := by\n    rw [rawReady,List.reverse_nil]\n    exact Function.update_eq_self _ _\n  rw [checkerReady,hr]\n  exact h\n/-- The literal public acquirer executes INSIDE this one fixed larger program.\nIts own balanced trace justifies the real call/return, never an evaluator. -/\ntheorem public_call (bits : List Bool) (hb : bits≠[]) :\n    ∃t≤SemiprimeD1BinaryPublicAcquisitionExecution.timeBound bits,\n      Runs program (t+1) .bootstrap (checkerReady bits [] []) (.arityCopy 0) (bootData bits 0 []) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1BinaryPublicAcquisitionExecution.source_run bits hb\n  refine ⟨t,ht,?_⟩\n  rw [checkerReady_input]\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program (fun k : A.Stack=>.inl (.inl k))\n    Label.acquisition (by intro a b h;exact Sum.inl.inj (Sum.inl.inj h))\n    A.program (SemiprimeD1BinaryPublicAcquisition.mainLabel .start) (fun _=>rfl)\n    .bootstrap (.arityCopy 0) rfl t (A.initial bits)\n    (⟨none,none,none,SemiprimeD1BinaryPublicAcquisitionComponents.result bits,[]⟩:C.State A.Stack A.Label)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact hr\n  · constructor\n    · intro k;rfl\n    · intro k hk;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      cases k with\n      | inl k=>\n        cases k with\n        | inl k=>exact (hk k rfl).elim\n        | inr k=>\n          change []=SemiprimeD1StackProductCheck.input [] [] k\n          unfold SemiprimeD1StackProductCheck.input\n          split\n          · rfl\n          · split <;> rfl\n      | inr k=>cases k <;> rfl\n/-- The actual source prefix budget before clearing public/checker caches. -/\ndef preparationBound (bits : List Bool) : ℕ :=\n  SemiprimeD1BinaryPublicAcquisitionExecution.timeBound bits+5*bits.length+\n    21*(SemiprimeD1StackPublicProductExecution.cached bits).length+20\n/-- Closed acquired-arity source prefix from original binary N ONLY. -/\ntheorem preparation_run (bits : List Bool) (hb : bits≠[]) :\n    ∃t≤preparationBound bits,Runs program t .start (initial bits).data .bootstrapClear\n      (bootData bits (SemiprimeD1StackProductTableSpec.arity bits) []) := by\n  have h0:=source_copy bits\n  obtain ⟨a,ha,h1⟩:=public_call bits hb\n  have h2:=arity_run bits\n  have h:=chain h0 (chain h1 h2)\n  refine ⟨_,?_,h⟩\n  unfold preparationBound\n  omega\n/-- Preparation is genuinely quadratic in ORIGINAL physical binary input width. -/\ntheorem preparationBound_le (bits : List Bool) : preparationBound bits≤10000000*(bits.length+1)^2 := by\n  have hc:=SemiprimeD1StackPublicProductBounds.cached_length_le bits\n  have hp:=Nat.pow_le_pow_right (by omega : 1≤bits.length+1) (by decide : 1≤2)\n  simp only [pow_one] at hp\n  unfold preparationBound SemiprimeD1BinaryPublicAcquisitionExecution.timeBound\n  omega\n/-- Every initial physical role fits the actual supplied N length. -/\ntheorem initial_length (bits : List Bool) (k : Stack) : ((initial bits).data k).length≤bits.length := by\n  rw [initial_data]\n  cases k with\n  | inl k=>exact Nat.zero_le _\n  | inr k=>cases k <;> first | exact le_rfl | exact Nat.zero_le _\n/-- Actual completed preparation trace bounds ALL76 checker cells before\nclearing, rather than estimating an unexecuted report or supplied cache. -/\ntheorem boot_inventory_le (bits : List Bool) (hb : bits≠[]) :\n    SemiprimeD1StackProductTableCleanup.inventory\n      (bootData bits (SemiprimeD1StackProductTableSpec.arity bits) [])≤76*(bits.length+preparationBound bits) := by\n  obtain ⟨t,ht,hpre⟩:=preparation_run bits hb\n  obtain ⟨finish,hr,hout⟩:=hpre [] (initial bits) ⟨rfl,rfl,rfl⟩\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program t bits.length _ finish (initial_length bits) hr\n  rw [hout.2.1] at hd\n  unfold SemiprimeD1StackProductTableCleanup.inventory\n  calc\n    _ ≤ ∑_k : P.Stack,(bits.length+preparationBound bits) :=\n      Finset.sum_le_sum (fun k _=>(hd (.inl k)).trans (by omega))\n    _ = _ := by simp only [Finset.sum_const,Finset.card_univ,SemiprimeD1StackPublicProduct.stack_card,smul_eq_mul]\n/-- Own complete bootstrap bound, fixed before every original binary N. -/\ndef bootstrapBound (bits : List Bool) : ℕ :=100000000000000*(bits.length+1)^2\n/-- COMPLETE N-only bootstrap: real original-input source, acquired arity,\nphysical ALL76-role cleanup and real return to the recursive tree builder. -/\ntheorem bootstrap_run (bits : List Bool) (hb : bits≠[]) :\n    ∃t≤bootstrapBound bits,Runs program t .start (initial bits).data .build\n      (data bits (SemiprimeD1StackProductTableSpec.arity bits) [] []) := by\n  obtain ⟨a,ha,h0⟩:=preparation_run bits hb\n  let bs:=bootData bits (SemiprimeD1StackProductTableSpec.arity bits) []\n  obtain ⟨m,hm,hclear⟩:=SemiprimeD1StackProductTableCleanup.clear_returns bs\n  have h1:=SemiprimeD1StackProcedureReturns.call program m .bootstrapClear (.clear 0) .build\n    bs (SemiprimeD1StackProductTableCleanup.clean bs) rfl hclear\n  have he:SemiprimeD1StackProductTableCleanup.clean bs=data bits (SemiprimeD1StackProductTableSpec.arity bits) [] []:=\n    clean_bootData bits _\n  rw [he] at h1\n  have h:=chain h0 h1\n  refine ⟨a+(1+m),?_,h⟩\n  have hi:=boot_inventory_le bits hb\n  change SemiprimeD1StackProductTableCleanup.inventory bs≤76*(bits.length+preparationBound bits) at hi\n  have hp:=preparationBound_le bits\n  have hq:=Nat.pow_le_pow_right (by omega : 1≤bits.length+1) (by decide : 1≤2)\n  simp only [pow_one] at hq\n  unfold bootstrapBound\n  omega\n/-- Every physical data role is part of one fixed83-role inventory. -/\ntheorem stack_card : Fintype.card Stack=83 := by decide\nend RiemannGaussian.SemiprimeD1StackProductTableBootstrap\n","RiemannGaussian.SemiprimeD1StackProductTableBootstrapParts":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductTableState\n/-! # Actual product-table arity acquisition from the retained binary M word\nThe word VALUE never becomes an arity. Three real copies/scans count its\nphysical cells, including every zero bit, by pushing actual depth markers.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1600000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackProductTableBootstrapParts\nopen SemiprimeD1StackProductTable SemiprimeD1StackProductTableState\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackPublicProductExecution (context cached)\n/-- Actual acquired public bank and otherwise empty reusable checker bank. -/\ndef checker (bits : List Bool) : P.Stack→List Bool :=Sum.elim (context bits) (fun _=>[])\n/-- Correctness view of actual acquired caches, actual depth and scanned word. -/\ndef bootData (bits : List Bool) (depth : ℕ) (work : List Bool) : Stack→List Bool :=\n  Function.update (withChecker (data bits depth [] []) (checker bits)) (.inr .work) work\n/-- Every actual copied modulus cell contributes exactly one real depth marker. -/\ndef scanNext (pass : Fin 3) : Label :=\n  if h:pass.val<2 then .arityCopy ⟨pass.val+1,by omega⟩ else .bootstrapClear\n/-- Real physical fragment composition for the same source code. -/\ntheorem chain {m n : ℕ} {pc mid next : Label} {input middle output : Stack→List Bool}\n    (h : Runs program m pc input mid middle) (g : Runs program n mid middle next output) :\n    Runs program (m+n) pc input next output := runs_trans program _ _ _ _ _ _ _ _ h g\n/-- Complete real word scan, accepting EVERY marker bit pattern, with no supplied\nword length/count. Only the actual input EOF selects the next fixed pass. -/\ntheorem scan_run (pass : Fin 3) (bits : List Bool) (depth : ℕ) (work : List Bool) :\n    Runs program (2*work.length+1) (.arityScan pass) (bootData bits depth work)\n      (scanNext pass) (bootData bits (depth+work.length) []) := by\n  induction work generalizing depth with\n  | nil=>\n    apply one_base program (.arityScan pass) (scanNext pass)\n      (.pop (.inr .work) (scanNext pass) (.arityPush pass) (.arityPush pass)) _ _ rfl\n    · rfl\n    · funext k\n      cases k with\n      | inl k=>rfl\n      | inr k=>cases k <;> rfl\n  | cons b work ih=>\n    have h0 : Runs program 1 (.arityScan pass) (bootData bits depth (b::work))\n        (.arityPush pass) (bootData bits depth work) := by\n      apply one_base program (.arityScan pass) (.arityPush pass)\n        (.pop (.inr .work) (scanNext pass) (.arityPush pass) (.arityPush pass)) _ _ rfl\n      · cases b <;> rfl\n      · funext k\n        cases k with\n        | inl k=>rfl\n        | inr k=>cases k <;> rfl\n    have h1 : Runs program 1 (.arityPush pass) (bootData bits depth work)\n        (.arityScan pass) (bootData bits (depth+1) work) := by\n      apply one_base program (.arityPush pass) (.arityScan pass)\n        (.push (.inr .depth) true (.arityScan pass)) _ _ rfl\n      · rfl\n      · funext k\n        cases k with\n        | inl k=>rfl\n        | inr k=>cases k <;> rfl\n    have h:=chain h0 (chain h1 (ih (depth+1)))\n    have ht:1+(1+(2*work.length+1))=2*(b::work).length+1 := by simp only [List.length_cons];omega\n    have hd:depth+1+work.length=depth+(b::work).length := by simp only [List.length_cons];omega\n    rw [ht,hd] at h\n    exact h\n/-- A real preserving copy of the ACTUALLY acquired binary M word, whose physical\nlength is then scanned; no modulus/width/value supplier is an initial operand. -/\ntheorem copy_arity (pass : Fin 3) (bits : List Bool) (depth : ℕ) :\n    Runs program (5*(cached bits).length+4) (.arityCopy pass) (bootData bits depth [])\n      (.arityScan pass) (bootData bits depth (cached bits)) := by\n  have h:=SemiprimeD1StackProductTablePrimitives.copy_call .arity (.arityCopy pass) (.arityScan pass)\n    rfl (bootData bits depth []) rfl rfl\n  change Runs program (5*(cached bits).length+4) (.arityCopy pass) (bootData bits depth [])\n    (.arityScan pass) (Function.update (bootData bits depth []) (.inr .work) (cached bits)) at h\n  simpa only [bootData,Function.update_idem] using h\n/-- All copy/scan/EOF work in one fixed physical pass. -/\ntheorem arity_round (pass : Fin 3) (bits : List Bool) (depth : ℕ) :\n    Runs program (7*(cached bits).length+5) (.arityCopy pass) (bootData bits depth [])\n      (scanNext pass) (bootData bits (depth+(cached bits).length) []) := by\n  have h:=chain (copy_arity pass bits depth) (scan_run pass bits depth (cached bits))\n  have ht:(5*(cached bits).length+4)+(2*(cached bits).length+1)=7*(cached bits).length+5 := by omega\n  rw [ht] at h\n  exact h\n/-- THREE actual scans acquire the complete three-word product arity, preserving\nthe entire actual public bank. Their fixed finite pass labels contain no n. -/\ntheorem arity_run (bits : List Bool) :\n    Runs program (3*(7*(cached bits).length+5)) (.arityCopy 0) (bootData bits 0 [])\n      .bootstrapClear (bootData bits (SemiprimeD1StackProductTableSpec.arity bits) []) := by\n  have h0:=arity_round 0 bits 0\n  have h1:=arity_round 1 bits (0+(cached bits).length)\n  have h2:=arity_round 2 bits (0+(cached bits).length+(cached bits).length)\n  have h:=chain h0 (chain h1 h2)\n  have ht:(7*(cached bits).length+5)+((7*(cached bits).length+5)+(7*(cached bits).length+5))=\n      3*(7*(cached bits).length+5) := by omega\n  have hd:0+(cached bits).length+(cached bits).length+(cached bits).length=\n      SemiprimeD1StackProductTableSpec.arity bits := by unfold SemiprimeD1StackProductTableSpec.arity;omega\n  rw [ht,hd] at h\n  exact h\n/-- Physically draining the public/checker bank retains the acquired depth. -/\ntheorem clean_bootData (bits : List Bool) (depth : ℕ) :\n    SemiprimeD1StackProductTableCleanup.clean (bootData bits depth [])=data bits depth [] [] := by\n  funext k\n  cases k with\n  | inl k=>rfl\n  | inr k=>cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackProductTableBootstrapParts\n","RiemannGaussian.SemiprimeD1StackProductTableDFS":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackProductTableLeaf\nimport RiemannGaussian.SemiprimeD1StackProductTableDFSParts\n/-! # Complete actual product truth-table DFS and every leaf's own bit clock\nBoth real recursive calls restore depth/prefix physically. Every scalar comes\nfrom the embedded original-N product checker, then ALL76 roles are drained.\nThe resulting tape has EXACT old first-port-outermost, false-first order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackProductTableDFS\nopen SemiprimeD1StackProductTable SemiprimeD1StackProductTableState SemiprimeD1StackProductTableSpec\nopen SemiprimeD1StackProductTableLeaf SemiprimeD1StackProductTableDFSParts\nopen SemiprimeD1StackProcedureTrace SemiprimeD1StackProcedureReturns\nopen SemiprimeD1TensorTapeCodec (tape)\n/-- Prepend a literal body trace to a proved physical caller-frame return. -/\ntheorem returns_after {m n : ℕ} {pc mid : Label} {input middle output : Stack→List Bool}\n    (h : Runs program m pc input mid middle) (g : Returns program n mid middle output) :\n    Returns program (m+n) pc input output := by\n  intro next frames before hb\n  obtain ⟨between,hr,hm⟩:=h (next::frames) before hb\n  obtain ⟨finish,hfinish,hout⟩:=g next frames between hm\n  refine ⟨finish,?_,hout⟩\n  rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,hfinish]\n/-- All leaves in a subtree have the SAME total physical assignment width. -/\ndef weight (bits : List Bool) (width : ℕ) : ℕ :=1000000000000000000*(bits.length+width+2)^3+20\n/-- COMPLETE actual recursive visit, not an assumed evaluator/callback.\nThe same closed fixed code executes one actual public checker per real leaf,\nboth finite-label calls per fork, and all byte writes/restores/cleanup/returns. -/\ntheorem visit_returns (bits : List Bool) (hb : bits≠[]) (n : ℕ) (front hist : List Bool) :\n    ∃t,t+10≤weight bits (front.length+n)*2^n ∧ Returns program t .visit (data bits n front hist)\n      (data bits n front ((tape (tree bits front.reverse n)).reverse++hist)) := by\n  induction n generalizing front hist with\n  | zero=>\n    obtain ⟨t,ht,hret⟩:=leaf_returns bits front hist hb\n    rw [leaf_bytes] at hret\n    have h:=returns_after (visit_zero bits front hist) hret\n    refine ⟨1+t,?_,h⟩\n    simp only [Nat.add_zero,pow_zero,Nat.mul_one,weight]\n    unfold leafBound at ht\n    omega\n  | succ n ih=>\n    let lowBytes:=tape (tree bits (front.reverse++[false]) n)\n    let highBytes:=tape (tree bits (front.reverse++[true]) n)\n    obtain ⟨tl,hl,hleft⟩:=ih (false::front) (true::hist)\n    obtain ⟨tr,hr,hright⟩:=ih (true::front) (lowBytes.reverse++true::hist)\n    simp only [List.reverse_cons] at hleft hright\n    have h0:=visit_succ bits n front hist\n    have h1:=fork_push bits n front hist\n    have h2:=low_push bits n front (true::hist)\n    have h3:=SemiprimeD1StackProcedureReturns.call program tl .high .visit .afterLow\n      _ _ rfl hleft\n    have h4:=low_pop bits n front (lowBytes.reverse++true::hist)\n    have h5:=high_push bits n front (lowBytes.reverse++true::hist)\n    have h6:=SemiprimeD1StackProcedureReturns.call program tr .afterHigh .visit .restore\n      _ _ rfl hright\n    have h7:=high_pop bits n front (highBytes.reverse++(lowBytes.reverse++true::hist))\n    have h8:=depth_restore bits n front (highBytes.reverse++(lowBytes.reverse++true::hist))\n    have h:=chain h0 (chain h1 (chain h2 (chain h3 (chain h4 (chain h5 (chain h6 (chain h7 h8)))))))\n    have hlog:highBytes.reverse++(lowBytes.reverse++true::hist)=\n        (tape (tree bits front.reverse (n+1))).reverse++hist := by\n      change highBytes.reverse++(lowBytes.reverse++true::hist)=(true::(lowBytes++highBytes)).reverse++hist\n      simp only [List.reverse_cons,List.reverse_append,List.append_assoc,List.singleton_append]\n    rw [hlog] at h\n    have hret:=of_runs program _ .visit .leafReturn _ _ h rfl\n    refine ⟨_,?_,hret⟩\n    have hw:(false::front).length+n=front.length+(n+1) := by simp only [List.length_cons];omega\n    have hw':(true::front).length+n=front.length+(n+1) := by simp only [List.length_cons];omega\n    rw [hw] at hl\n    rw [hw'] at hr\n    rw [pow_succ,←Nat.mul_assoc]\n    omega\nend RiemannGaussian.SemiprimeD1StackProductTableDFS\n","RiemannGaussian.SemiprimeD1StackPublicCarryRecordOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicCarryRecordBounds\nimport RiemannGaussian.SemiprimeD1StackPublicCarryTableOriginal\nimport RiemannGaussian.SemiprimeD1StackBooleanRecordOriginal\n/-! # Entire original carry tensor and chronological old record bytes\nThe caller acquires the actual ordered numeric scope and descriptor index.\nNo assignment, table, native evaluator or verdict is supplied to the source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 100000\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicCarryRecordOriginal\nopen SemiprimeD1StackPublicCarryRecord SemiprimeD1StackPublicCarryRecordExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\nnamespace Bank\nexport SemiprimeD1OrdinalBankSpec (idAt)\nend Bank\nnamespace Log\nexport SemiprimeD1StackVertexRecordStreamExecution (rows history)\nend Log\n/-- The read-only template is ONLY original N and descriptor index bytes;\nall raw assignments, metadata, caches, results and clock fields start empty. -/\ntheorem initial_template_only (bits indexWord bank hist out : List Bool) (k : SemiprimeD1StackPublicCarry.Stack) :\n    (initial bits indexWord bank hist out).data (G.tableStack (SemiprimeD1StackStaticTable.template k))=\n      if k=SemiprimeD1StackPublicCarryTable.P.inputRole then bits\n      else if k=SemiprimeD1StackPublicCarryTable.P.index then indexWord else [] :=\n  SemiprimeD1StackPublicCarryTableTrace.template_only bits indexWord k\n/-- Same proof-side original carry vertex with the caller's ordered numeric scope. -/\nabbrev vertex :=SemiprimeD1StackBooleanRecordOriginal.vertex\nvariable (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n  (i : Fin (firstAxis (bitLength (bitValue bits))*secondAxis (bitLength (bitValue bits))))\n  (indexWord : List Bool) (hi : indexWord.length=i.val) (M : Nat) (ports : List Nat)\n  (hp : ∀j∈ports,j<M)\n  (hlen : ports.length=SemiprimeMacroGraph.subdividedArity\n    (.inl (.carry i):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits)))\ninclude hc hi hp\n/-- Exactly the complete original carry table and unchanged unary port order. -/\ntheorem row_original :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicCarryTableExecution.table bits indexWord (ports.map (Bank.idAt M)))=\n      SemiprimeD1StackVertexRecordStream.row\n        (SemiprimeD1StackVertexReadExecution.portTape (vertex (bitValue bits) hN (.inl (.carry i)) ports hlen).ports)\n        (SemiprimeD1TensorTapeCodec.tape (vertex (bitValue bits) hN (.inl (.carry i)) ports hlen).table) := by\n  have hs:=SemiprimeD1StackPortOrdinalStreamOriginal.selected_portTape M ports hp\n  have ht:=SemiprimeD1StackPublicCarryTableOriginal.table_original bits hc hN i indexWord hi\n    (ports.map (Bank.idAt M)) (by simpa only [List.length_map] using hlen)\n  rw [hs,ht]\n  exact congrArg (SemiprimeD1StackVertexRecordStream.row (SemiprimeD1StackVertexReadExecution.portTape ports))\n    (SemiprimeD1StackBooleanRecordOriginal.tape_cast hlen.symm\n      (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.carry i)))).symm\n/-- Literal actual row prepends exactly the unchanged old product-reader record. -/\ntheorem record_bytes_original (rest : List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicCarryTableExecution.table bits indexWord (ports.map (Bank.idAt M)))++\n      SemiprimeD1StackVertexProduct.records rest=\n      SemiprimeD1StackVertexProduct.records\n        (vertex (bitValue bits) hN (.inl (.carry i)) ports hlen::rest) := by\n  rw [row_original bits hc hN i indexWord hi M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStream.row_records _ rest\n/-- Appending one actual input row retains the chronological order of all old rows. -/\ntheorem history_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    (done bits indexWord (ports.map (Bank.idAt M)) (Log.history previous old) out).data G.history=\n      Log.history (previous++[vertex (bitValue bits) hN (.inl (.carry i)) ports hlen]) old := by\n  rw [history_row,row_original bits hc hN i indexWord hi M ports hp hlen]\n  simp only [Log.history,SemiprimeD1StackVertexRecordStreamExecution.rows_append,Log.rows,\n    List.append_nil,List.reverse_append,List.append_assoc]\n/-- One final actual logger reversal emits the exact forward old records and\none final false tag, without copying the accumulated tail at every node. -/\ntheorem reverse_original (previous : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    SemiprimeD1StackBytecode.run SemiprimeD1StackVertexRecordStream.code\n      (2*(Log.rows (previous++[vertex (bitValue bits) hN (.inl (.carry i)) ports hlen])).length+2)\n      ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] []\n        ((done bits indexWord (ports.map (Bank.idAt M)) (Log.history previous []) (false::out)).data G.history) (false::out)⟩=\n      some ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] []\n        (SemiprimeD1StackVertexProduct.records\n          (previous++[vertex (bitValue bits) hN (.inl (.carry i)) ports hlen])++out)⟩ := by\n  rw [history_original bits hc hN i indexWord hi M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStreamExecution.reverse_original _ out\n/-- The actual source execution and exact old chronological record hold together. -/\ntheorem source_run_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    ∃t≤timeBound bits indexWord (ports.map (Bank.idAt M)),∃finish,\n      SemiprimeD1StackCalls.run program t\n        (initial bits indexWord (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M)))\n          (Log.history previous old) out)=some finish ∧\n      finish=done bits indexWord (ports.map (Bank.idAt M)) (Log.history previous old) out ∧\n      finish.data G.history=Log.history\n        (previous++[vertex (bitValue bits) hN (.inl (.carry i)) ports hlen]) old := by\n  have hb:bits≠[]:=by intro he;subst bits;exact (Nat.not_lt_zero _ hN).elim\n  obtain ⟨t,ht,hr⟩:=source_run bits indexWord hb (ports.map (Bank.idAt M)) (Log.history previous old) out\n  exact ⟨t,ht,_,hr,rfl,history_original bits hc hN i indexWord hi M ports hp hlen previous old out⟩\nomit hp in\n/-- Each individual acquired coefficient is the exact original integer0/1. -/\ntheorem literal_original_coefficient\n    (input : Fin (SemiprimeMacroGraph.arity (.carry i : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal []\n        (SemiprimeD1StackStaticTableSpec.leafWords (T.answer bits indexWord) (List.ofFn input)))=\n      if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.carry i) input).accepted\n        then 1 else 0 :=\n  SemiprimeD1StackPublicCarryTableOriginal.literal_original_coefficient bits hc hN i indexWord hi input\nend RiemannGaussian.SemiprimeD1StackPublicCarryRecordOriginal\n","RiemannGaussian.SemiprimeD1StackPublicScaleRecordOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicScaleRecordBounds\nimport RiemannGaussian.SemiprimeD1StackPublicScaleTableOriginal\nimport RiemannGaussian.SemiprimeD1StackBooleanRecordOriginal\n/-! # Entire original scale tensor and chronological old record bytes\nThe caller acquires the actual ordered numeric scope and descriptor index.\nNo assignment, table, native evaluator or verdict is supplied to the source.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 100000\nset_option maxHeartbeats 1600000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicScaleRecordOriginal\nopen SemiprimeD1StackPublicScaleRecord SemiprimeD1StackPublicScaleRecordExecution\nopen SemiprimeMacroParameters SemiprimeBitArithmetic\nopen SemiprimeD1StackUnaryDivmod (unary)\nopen SemiprimeD1StackPublicScaleFinite (selector)\nnamespace Bank\nexport SemiprimeD1OrdinalBankSpec (idAt)\nend Bank\nnamespace Log\nexport SemiprimeD1StackVertexRecordStreamExecution (rows history)\nend Log\n/-- Exactly N, physical j/k markers and the singleton selector initialize the\nread-only template; all arithmetic sources/caches/raw/results remain empty. -/\ntheorem initial_template_only (bits stride frequency : List Bool) (inverse : Bool)\n    (bank hist out : List Bool) (k : SemiprimeD1StackPublicScale.Stack) :\n    (initial bits stride frequency inverse bank hist out).data\n      (G.tableStack (SemiprimeD1StackStaticTable.template k))=\n      if k=SemiprimeD1StackPublicScaleTable.P.inputRole then bits else\n      if k=SemiprimeD1StackPublicScaleTable.P.stride then stride else\n      if k=SemiprimeD1StackPublicScaleTable.P.frequency then frequency else\n      if k=SemiprimeD1StackPublicScaleTable.P.selector then [inverse] else [] :=\n  SemiprimeD1StackPublicScaleTableTrace.template_only bits stride frequency inverse k\n/-- Same proof-side original scale vertex with the caller's ordered numeric scope. -/\nabbrev vertex :=SemiprimeD1StackBooleanRecordOriginal.vertex\nvariable (bits : List Bool) (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits)\n  (tr : SemiprimeMacroGraph.Transform)\n  (j : Fin (firstAxis (bitLength (bitValue bits)))) (k : Fin (secondAxis (bitLength (bitValue bits))))\n  (M : Nat) (ports : List Nat)\n  (hp : ∀j∈ports,j<M)\n  (hlen : ports.length=SemiprimeMacroGraph.subdividedArity\n    (.inl (.scale tr j k):SemiprimePublicAcquiredExecution.PublicVertex (bitValue bits)))\ninclude hc hp\n/-- Exactly the complete original scale table and unchanged unary port order. -/\ntheorem row_original :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicScaleTableExecution.table bits (unary j.val) (unary k.val) (selector tr) (ports.map (Bank.idAt M)))=\n      SemiprimeD1StackVertexRecordStream.row\n        (SemiprimeD1StackVertexReadExecution.portTape (vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen).ports)\n        (SemiprimeD1TensorTapeCodec.tape (vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen).table) := by\n  have hs:=SemiprimeD1StackPortOrdinalStreamOriginal.selected_portTape M ports hp\n  have ht:=SemiprimeD1StackPublicScaleTableOriginal.table_original bits hc hN tr j k\n    (ports.map (Bank.idAt M)) (by simpa only [List.length_map] using hlen)\n  rw [hs,ht]\n  exact congrArg (SemiprimeD1StackVertexRecordStream.row (SemiprimeD1StackVertexReadExecution.portTape ports))\n    (SemiprimeD1StackBooleanRecordOriginal.tape_cast hlen.symm\n      (SemiprimeD1BooleanRootTablesOriginal.reference (bitValue bits) hN (.inl (.scale tr j k)))).symm\n/-- Literal actual row prepends exactly the unchanged old product-reader record. -/\ntheorem record_bytes_original (rest : List SemiprimeD1LeafCounter.Vertex) :\n    SemiprimeD1StackVertexRecordStream.row\n      (SemiprimeD1StackPortOrdinalStream.result (ports.map (Bank.idAt M)))\n      (SemiprimeD1StackPublicScaleTableExecution.table bits (unary j.val) (unary k.val) (selector tr) (ports.map (Bank.idAt M)))++\n      SemiprimeD1StackVertexProduct.records rest=\n      SemiprimeD1StackVertexProduct.records\n        (vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen::rest) := by\n  rw [row_original bits hc hN tr j k M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStream.row_records _ rest\n/-- Appending one actual input row retains the chronological order of all old rows. -/\ntheorem history_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    (done bits (unary j.val) (unary k.val) (selector tr) (ports.map (Bank.idAt M)) (Log.history previous old) out).data G.history=\n      Log.history (previous++[vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen]) old := by\n  rw [history_row,row_original bits hc hN tr j k M ports hp hlen]\n  simp only [Log.history,SemiprimeD1StackVertexRecordStreamExecution.rows_append,Log.rows,\n    List.append_nil,List.reverse_append,List.append_assoc]\n/-- One final actual logger reversal emits the exact forward old records and\none final false tag, without copying the accumulated tail at every node. -/\ntheorem reverse_original (previous : List SemiprimeD1LeafCounter.Vertex) (out : List Bool) :\n    SemiprimeD1StackBytecode.run SemiprimeD1StackVertexRecordStream.code\n      (2*(Log.rows (previous++[vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen])).length+2)\n      ⟨some .reverse,none,SemiprimeD1StackVertexRecordStream.data [] []\n        ((done bits (unary j.val) (unary k.val) (selector tr) (ports.map (Bank.idAt M)) (Log.history previous []) (false::out)).data G.history) (false::out)⟩=\n      some ⟨none,none,SemiprimeD1StackVertexRecordStream.data [] [] []\n        (SemiprimeD1StackVertexProduct.records\n          (previous++[vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen])++out)⟩ := by\n  rw [history_original bits hc hN tr j k M ports hp hlen]\n  exact SemiprimeD1StackVertexRecordStreamExecution.reverse_original _ out\n/-- The actual source execution and exact old chronological record hold together. -/\ntheorem source_run_original (previous : List SemiprimeD1LeafCounter.Vertex) (old out : List Bool) :\n    ∃t≤timeBound bits (unary j.val) (unary k.val) (selector tr) (ports.map (Bank.idAt M)),∃finish,\n      SemiprimeD1StackCalls.run program t\n        (initial bits (unary j.val) (unary k.val) (selector tr) (SemiprimeD1TensorTapeCodec.vectorBits (ports.map (Bank.idAt M)))\n          (Log.history previous old) out)=some finish ∧\n      finish=done bits (unary j.val) (unary k.val) (selector tr) (ports.map (Bank.idAt M)) (Log.history previous old) out ∧\n      finish.data G.history=Log.history\n        (previous++[vertex (bitValue bits) hN (.inl (.scale tr j k)) ports hlen]) old := by\n  obtain ⟨t,ht,hr⟩:=source_run bits (unary j.val) (unary k.val) (selector tr) (by simp only [unary,List.length_replicate])\n    (by simp only [unary,List.length_replicate]) hc hN (ports.map (Bank.idAt M)) (Log.history previous old) out\n  exact ⟨t,ht,_,hr,rfl,history_original bits hc hN tr j k M ports hp hlen previous old out⟩\nomit hp in\n/-- Each individual acquired coefficient is the exact original integer0/1. -/\ntheorem literal_original_coefficient\n    (input : Fin (SemiprimeMacroGraph.arity (.scale tr j k : SemiprimeMacroGraph.Vertex\n      (firstAxis (bitLength (bitValue bits))) (secondAxis (bitLength (bitValue bits)))\n      (digitCount (bitLength (bitValue bits)))))→Bool) :\n    SemiprimeD1JetAlgebra.coefficient (SemiprimeD1JetBoxIndex.dims [])\n      (SemiprimeD1JetBoxIndex.exponent [] 0)\n      (SemiprimeD1JetBoxIndex.exponent_inBox [] 0 (by simp) (by decide))\n      (SemiprimeD1JetLiteralLift.literal []\n        (SemiprimeD1StackStaticTableSpec.leafWords (T.answer bits (unary j.val) (unary k.val) (selector tr)) (List.ofFn input)))=\n      if (SemiprimeMacroEntryBitCheck.publicBitEntry (bitValue bits) hN (.scale tr j k) input).accepted\n        then 1 else 0 :=\n  SemiprimeD1StackPublicScaleTableOriginal.literal_original_coefficient bits hc hN tr j k input\nend RiemannGaussian.SemiprimeD1StackPublicScaleRecordOriginal\n","RiemannGaussian.SemiprimeD1StackPublicTransformLoopControl":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformQueryClosure\n/-! # Physical countdown and terminal cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformLoopControl\nopen SemiprimeD1StackPublicTransform SemiprimeD1StackPublicTransformState\nopen SemiprimeD1StackPublicTransformLoopState SemiprimeD1StackPublicTransformPrimitives\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackUnaryDivmod (unary)\n/-- Actual pop, drain and restoring copy prepare a descending output query. -/\ntheorem prepare (bits raw : List Bool) (second inverse : Bool) (n f : ℕ) :\n    Runs program (1+(f+1)+(5*n+4)) .loop (data (steady bits raw second inverse (n+1) f))\n      .evaluate (data (steady bits raw second inverse n n)) := by\n  have h0:=pop .loop .accept .clearFrequency .clearFrequency (.aux .remaining) rfl\n    (data (steady bits raw second inverse (n+1) f))\n  rw [remaining_value] at h0\n  simp only [unary,List.replicate_succ,List.head?_cons,List.tail_cons,\n    SemiprimeD1StackBytecode.choose] at h0\n  change Runs program 1 .loop _ .clearFrequency\n    (Function.update (data (steady bits raw second inverse (n+1) f)) (.aux .remaining) (unary n)) at h0\n  rw [remaining_update] at h0\n  have h1:=drain .clearFrequency .copyFrequency (.dot (.inl .frequency)) rfl\n    (data (steady bits raw second inverse n f))\n  rw [frequency_value] at h1\n  change Runs program ((unary f).length+1) .clearFrequency _ .copyFrequency\n    (Function.update (data (steady bits raw second inverse n f)) (.dot (.inl .frequency)) (unary 0)) at h1\n  rw [frequency_update] at h1\n  have h2:=copy_call .frequency .copyFrequency .evaluate rfl\n    (data (steady bits raw second inverse n 0)) (frequency_value bits raw second inverse n 0)\n    (steady_scratch bits raw second inverse n 0)\n  change Runs program (5*(data (steady bits raw second inverse n 0) (.aux .remaining)).length+4)\n    .copyFrequency _ .evaluate\n    (Function.update (data (steady bits raw second inverse n 0)) (.dot (.inl .frequency))\n      (data (steady bits raw second inverse n 0) (.aux .remaining))) at h2\n  rw [remaining_value,frequency_update] at h2\n  simpa only [unary,List.length_replicate] using\n    runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n/-- Actual EOF selects acceptance. -/\ntheorem empty (bits raw : List Bool) (second inverse : Bool) (f : ℕ) :\n    Runs program 1 .loop (data (steady bits raw second inverse 0 f)) .accept\n      (data (steady bits raw second inverse 0 f)) := by\n  have h:=pop .loop .accept .clearFrequency .clearFrequency (.aux .remaining) rfl\n    (data (steady bits raw second inverse 0 f))\n  rw [remaining_value] at h\n  simp only [unary,List.replicate_zero,List.head?_nil,List.tail_nil,\n    SemiprimeD1StackBytecode.choose] at h\n  have he : data (steady bits raw second inverse 0 f) (.aux .remaining)=[] := remaining_value bits raw second inverse 0 f\n  rw [←he,Function.update_eq_self] at h\n  exact h\n/-- Literal final output and marker cleanup. -/\ndef finished (p : Parts) (answer : Bool) : Parts :=\n  set (set (set p (.aux .output) [answer]) (.aux .remaining) []) (.dot (.inl .frequency)) []\n/-- Every remaining cell is physically popped before halt. -/\ntheorem finish (p : Parts) (answer : Bool) (ho : data p (.aux .output)=[]) :\n    Runs program (1+((data p (.aux .remaining)).length+1)+((data p (.dot (.inl .frequency))).length+1))\n      (if answer then .accept else .reject) (data p) .done (data (finished p answer)) := by\n  have h0 : Runs program 1 (if answer then .accept else .reject) (data p) .clearRemaining\n      (Function.update (data p) (.aux .output) [answer]) := by\n    cases answer\n    · simpa only [Bool.false_eq_true,ite_false,ho] using\n        push .reject .clearRemaining (.aux .output) false rfl (data p)\n    · simpa only [ite_true,ho] using\n        push .accept .clearRemaining (.aux .output) true rfl (data p)\n  have h1:=drain .clearRemaining .clearFinalFrequency (.aux .remaining) rfl\n    (Function.update (data p) (.aux .output) [answer])\n  have h2:=drain .clearFinalFrequency .done (.dot (.inl .frequency)) rfl\n    (Function.update (Function.update (data p) (.aux .output) [answer]) (.aux .remaining) [])\n  have h:=runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n  simpa only [finished,data_set,Function.update_of_ne (by decide : Stack.aux .remaining≠.aux .output),\n    Function.update_of_ne (by decide : Stack.dot (.inl .frequency)≠.aux .remaining),\n    Function.update_of_ne (by decide : Stack.dot (.inl .frequency)≠.aux .output)] using h\n/-- Terminal data is independent of the last physical countdown values. -/\ntheorem finished_steady (bits raw : List Bool) (second inverse answer : Bool) (n f : ℕ) :\n    data (finished (steady bits raw second inverse n f) answer)=\n      data (finished (steady bits raw second inverse 0 0) answer) := by\n  simp only [finished,data_set,steady_data]\n  funext k\n  by_cases h0 : k=Stack.dot (.inl .frequency)\n  · subst k; simp only [Function.update_same]\n  by_cases h1 : k=Stack.aux .remaining\n  · subst k; simp only [Function.update_of_ne (by decide : Stack.aux .remaining≠.dot (.inl .frequency)),Function.update_same]\n  by_cases h2 : k=Stack.aux .output\n  · subst k; simp only [Function.update_of_ne (by decide : Stack.aux .output≠.dot (.inl .frequency)),\n      Function.update_of_ne (by decide : Stack.aux .output≠.aux .remaining),Function.update_same]\n  simp only [Function.update_of_ne h0,Function.update_of_ne h1,Function.update_of_ne h2]\nend RiemannGaussian.SemiprimeD1StackPublicTransformLoopControl\n","RiemannGaussian.SemiprimeD1StackPublicTransformTraceBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackPublicTransformOriginal\n/-! # Closed original-input transform execution\nThe executing program takes only binary N, raw assignment bytes and two finite\nstage/direction flags. Every source, vector, guard and query is actually run.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 100000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackPublicTransformTraceBudget\nopen SemiprimeD1StackPublicTransform SemiprimeD1StackPublicTransformState\nopen SemiprimeD1StackPublicTransformSetup SemiprimeD1StackPublicTransformWords\nopen SemiprimeD1StackPublicTransformGuards SemiprimeD1StackPublicTransformMetadata\nopen SemiprimeD1StackPublicTransformLoopState SemiprimeD1StackPublicTransformLoopControl\nopen SemiprimeD1StackProcedureTrace SemiprimeBitArithmetic\nopen SemiprimeD1StackPublicTransformExecution\n/-- Sum of retained source/vector/guard/query budgets, not an assumed clock. -/\ndef timeBound (bits raw : List Bool) (second inverse : Bool) : ℕ :=\n  SemiprimeD1StackRootSourceBounds.timeBound bits+1+2+\n    metadataBudget (rootData bits) second inverse+normalizationBudget (rootData bits) second inverse+\n    wordsBudget (rootData bits) raw second+frontBudget (rootData bits) raw second+\n    (if acceptedInputs bits raw second then\n      SemiprimeD1StackPublicTransformLoop.budget bits raw second inverse (size bits second) 0 else 0)+3\n/-- Whole real source trace with no supplied words, canonicality, root,\nnormalizer, evaluator, count, equality verdict or component clock. -/\ntheorem source_run_bounded (bits raw : List Bool) (second inverse : Bool)\n    (hc : SemiprimeSourceCompactBits.Compact bits) (hN : 0<bitValue bits) :\n    ∃t≤timeBound bits raw second inverse,Runs program t .start (initial bits raw second inverse).data .done\n      (data (finalParts bits raw second inverse)) := by\n  have hb : bits≠[] := by intro h;subst bits;exact (Nat.lt_irrefl 0 hN)\n  obtain ⟨t,ht,h0⟩:=acquire_run bits raw second inverse hb\n  obtain ⟨u,hu,h1⟩:=words_run (rootData bits) raw second inverse\n  obtain ⟨v,hv,h2⟩:=front_run (rootData bits) raw second inverse\n  have front:=runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n  cases hi : inputFlag (rootData bits) raw second with\n  | false=>\n    simp only [hi,Bool.false_and] at front\n    have hfinish:=finish (frontResult (rootData bits) raw second inverse) false (by\n      simp only [frontResult,hi,Bool.false_eq_true,ite_false]\n      rfl)\n    have hr : data (frontResult (rootData bits) raw second inverse) (.aux .remaining)=[] := by\n      simp only [frontResult,hi,Bool.false_eq_true,ite_false];rfl\n    have hf : data (frontResult (rootData bits) raw second inverse) (.dot (.inl .frequency))=[] := by\n      simp only [frontResult,hi,Bool.false_eq_true,ite_false];rfl\n    rw [hr,hf] at hfinish\n    norm_num only [List.length_nil] at hfinish\n    have h:=runs_trans program _ _ _ _ _ _ _ _ front hfinish\n    exact ⟨t+u+v+3,by unfold timeBound; simp only [acceptedInputs,hi,Bool.false_and,Bool.false_eq_true,ite_false];omega,by simpa only [finalParts,acceptedInputs,hi,Bool.false_and,Bool.false_eq_true,ite_false] using h⟩\n  | true=>\n    cases ho : outputFlag (rootData bits) raw second with\n    | false=>\n      simp only [hi,ho,Bool.true_and] at front\n      have hfinish:=finish (frontResult (rootData bits) raw second inverse) false (by\n        simp only [frontResult,hi,ho,ite_true,Bool.false_eq_true,ite_false]\n        rfl)\n      have hr : data (frontResult (rootData bits) raw second inverse) (.aux .remaining)=[] := by\n        simp only [frontResult,hi,ho,ite_true,Bool.false_eq_true,ite_false];rfl\n      have hf : data (frontResult (rootData bits) raw second inverse) (.dot (.inl .frequency))=[] := by\n        simp only [frontResult,hi,ho,ite_true,Bool.false_eq_true,ite_false];rfl\n      rw [hr,hf] at hfinish\n      norm_num only [List.length_nil] at hfinish\n      have h:=runs_trans program _ _ _ _ _ _ _ _ front hfinish\n      exact ⟨t+u+v+3,by unfold timeBound; simp only [acceptedInputs,hi,ho,Bool.true_and,Bool.false_eq_true,ite_false];omega,by simpa only [finalParts,acceptedInputs,hi,ho,Bool.true_and,Bool.false_eq_true,ite_false] using h⟩\n    | true=>\n      simp only [hi,ho,Bool.true_and,ite_true,frontResult] at front\n      obtain ⟨w,hw,hloop⟩:=SemiprimeD1StackPublicTransformLoop.loop_run bits raw second inverse hc hN hi (size bits second) 0\n      rw [loop_initial] at hloop\n      have h:=runs_trans program _ _ _ _ _ _ _ _ front hloop\n      exact ⟨t+u+v+w,by unfold timeBound; simp only [acceptedInputs,hi,ho,Bool.true_and,ite_true];omega,by simpa only [finalParts,acceptedInputs,hi,ho,Bool.true_and,ite_true] using h⟩\nend RiemannGaussian.SemiprimeD1StackPublicTransformTraceBudget\n","RiemannGaussian.SemiprimeD1StackRationalNormalizeSpec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRationalNormalize\nimport RiemannGaussian.SemiprimeD1StackAssignmentOrder\n/-! # Exact legacy rational bytes, including raw quotient padding and both zero signs\nOnly these proof interpretations mention rational values, natural GCD, lengths,\nor legacy reports. The finite source uses actual scans and arithmetic calls.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRationalNormalizeSpec\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeBitIndexClipping (SignedWord floorSignedBits)\nopen SemiprimeRationalBits (RationalWord zeroWord reduceBits)\n/-- Interpretation of the actually acquired compact GCD word. -/\ndef gcd (num den:List Bool) :List Bool:=(SemiprimeD1StackEuclidGCDSpec.answer num den).word\n/-- Literal restoring-division numerator quotient; its original dividend width is retained. -/\ndef numerator (num den:List Bool) :List Bool:=(SemiprimeBitDivision.divideLoop num (gcd num den)).quotient\n/-- Literal restoring-division denominator quotient; its original dividend width is retained. -/\ndef denominator (num den:List Bool) :List Bool:=(SemiprimeBitDivision.divideLoop den (gcd num den)).quotient\n/-- Exact result interpretation of the actual denominator scan and the two real quotient calls. -/\ndef word (negative:Bool) (num den:List Bool) :RationalWord:=\n  if bitValue den=0 then zeroWord else ⟨⟨negative,numerator num den⟩,denominator num den⟩\n/-- Actual compact GCD keeps its exact natural value. -/\ntheorem gcd_value (num den:List Bool) :bitValue (gcd num den)=(bitValue num).gcd (bitValue den):=\n  SemiprimeD1StackEuclidGCDSpec.answer_value num den\n/-- An actually positive denominator makes the acquired divisor genuinely positive. -/\ntheorem gcd_positive (num den:List Bool) (hd:0<bitValue den) :0<bitValue (gcd num den):=by\n  rw [gcd_value]\n  exact Nat.gcd_pos_of_pos_right _ hd\n/-- Quotient bytes depend only on a positive divisor's value and the actual dividend width. -/\ntheorem quotient_eq (xs a b:List Bool) (ha:0<bitValue a) (hb:0<bitValue b) (hab:bitValue a=bitValue b) :\n    (SemiprimeBitDivision.divideLoop xs a).quotient=(SemiprimeBitDivision.divideBits xs b).quotient:=by\n  apply SemiprimeD1StackAssignmentOrder.word_value_injective\n  · exact (SemiprimeBitDivision.divideLoop_widths xs a).2.1.trans\n      (SemiprimeBitDivision.divideBits_widths hb).2.symm\n  · rw [(SemiprimeD1StackDividerExecution.output_values xs a ha).1,\n      (SemiprimeBitDivision.divideBits_correct xs b).1,hab]\n/-- A true GCD divides the original magnitude, so legacy signed-floor correction is actually false.\nThe legacy sign is retained even when the quotient is zero. -/\ntheorem floor_gcd_exact (negative:Bool) (num den:List Bool) :\n    (floorSignedBits ⟨negative,num⟩ (SemiprimeBitGcd.gcdBits num den).bits).word=\n      ⟨negative,(SemiprimeBitDivision.divideBits num (SemiprimeBitGcd.gcdBits num den).bits).quotient⟩:=by\n  have hr:bitValue (SemiprimeBitDivision.divideBits num (SemiprimeBitGcd.gcdBits num den).bits).remainder=0:=by\n    rw [(SemiprimeBitDivision.divideBits_correct _ _).2,(SemiprimeBitGcd.gcdBits_correct num den).1]\n    exact Nat.mod_eq_zero_of_dvd (Nat.gcd_dvd_left _ _)\n  have hf:(SemiprimeBitDivision.nonzeroBits (SemiprimeBitDivision.divideBits num\n      (SemiprimeBitGcd.gcdBits num den).bits).remainder).nonzero=false:=by\n    apply Bool.eq_false_of_not_eq_true\n    intro h\n    have hp:=(SemiprimeBitDivision.nonzeroBits_correct _).mp h\n    omega\n  simp only [floorSignedBits,hf,Bool.and_false,Bool.false_eq_true,ite_false]\n/-- Whole exact legacy byte equality, covering padded-zero denominators and preserving negative zero on positive denominators. -/\ntheorem word_legacy (negative:Bool) (num den:List Bool) :\n    word negative num den=(reduceBits ⟨⟨negative,num⟩,den⟩).word:=by\n  by_cases hz:bitValue den=0\n  · have hc:¬(SemiprimeBitDivision.nonzeroBits den).nonzero=true:=by\n      intro h;have hp:=(SemiprimeBitDivision.nonzeroBits_correct den).mp h;omega\n    simp only [word,hz,ite_true,reduceBits,ite_eq_right hc]\n  · have hd:0<bitValue den:=by omega\n    have hc:=(SemiprimeBitDivision.nonzeroBits_correct den).mpr hd\n    have hg:=gcd_positive num den hd\n    have hgold:0<bitValue (SemiprimeBitGcd.gcdBits num den).bits:=by\n      rw [(SemiprimeBitGcd.gcdBits_correct num den).1]\n      exact Nat.gcd_pos_of_pos_right _ hd\n    have hv:bitValue (gcd num den)=bitValue (SemiprimeBitGcd.gcdBits num den).bits:=by\n      rw [gcd_value,(SemiprimeBitGcd.gcdBits_correct num den).1]\n    have hn:=quotient_eq num (gcd num den) (SemiprimeBitGcd.gcdBits num den).bits hg hgold hv\n    have hdq:=quotient_eq den (gcd num den) (SemiprimeBitGcd.gcdBits num den).bits hg hgold hv\n    simp only [word,ite_eq_right hz,reduceBits,ite_eq_left hc]\n    rw [floor_gcd_exact]\n    exact congrArg₂ RationalWord.mk (congrArg (SignedWord.mk negative) hn) hdq\n/-- Exact canonical integer numerator and positive denominator of the original input rational. -/\ntheorem word_components (negative:Bool) (num den:List Bool) :\n    (word negative num den).numerator.value=(⟨⟨negative,num⟩,den⟩:RationalWord).value.num ∧\n      bitValue (word negative num den).denominator=(⟨⟨negative,num⟩,den⟩:RationalWord).value.den:=by\n  rw [word_legacy]\n  exact SemiprimeRationalBits.reduceBits_components _\n/-- Normalization preserves the original rational value, including the physically guarded zero-denominator totalization. -/\ntheorem word_value (negative:Bool) (num den:List Bool) :\n    (word negative num den).value=(⟨⟨negative,num⟩,den⟩:RationalWord).value:=by\n  rw [word_legacy]\n  exact SemiprimeRationalBits.reduceBits_value _\n/-- Every actual normalized result has a positive denominator, including the literal zero-denominator branch. -/\ntheorem word_valid (negative:Bool) (num den:List Bool) :(word negative num den).Valid:=by\n  rw [word_legacy]\n  exact SemiprimeRationalBits.reduceBits_valid _\n/-- The actual numerator quotient has exactly its original magnitude's physical byte width. -/\ntheorem numerator_length (num den:List Bool) :(numerator num den).length=num.length:=\n  (SemiprimeBitDivision.divideLoop_widths num (gcd num den)).2.1\n/-- The actual denominator quotient has exactly its original denominator's physical byte width. -/\ntheorem denominator_length (num den:List Bool) :(denominator num den).length=den.length:=\n  (SemiprimeBitDivision.divideLoop_widths den (gcd num den)).2.1\nend RiemannGaussian.SemiprimeD1StackRationalNormalizeSpec\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineReadClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineReadBuffers\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffinePrimitives\n/-! # Actual skipped coefficient and unread-tail drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineReadClear\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\nopen SemiprimeD1StackRecoveryAffineReadBuffers SemiprimeD1StackProcedureTrace\nnamespace T\nexport SemiprimeD1StackRecoveryAffinePrimitives (join drain_loop)\nend T\n/-- Both skipped signed/denominator words are actually drained before the next byte-index step. -/\ntheorem skip_run (part:Part) (w:Words) (x:SemiprimeRationalBits.RationalWord) (reader todo:List Bool)\n    (hn:w.registers (.numBase,false)=[]) (hd:w.registers (.numBase,true)=[]):\n    Runs program ((signed x).length+1+x.denominator.length+1)\n      (.local (.clearReadWord part false)) (bank (putReg (buffers w reader todo) .numBase x))\n      (.local (.readCount part)) (bank (buffers w reader todo)):=by\n  let start:=putReg (buffers w reader todo) .numBase x\n  let first:Words:={start with registers:=Function.update start.registers (.numBase,false) []}\n  have h0:=T.drain_loop (.local (.clearReadWord part false)) (.local (.clearReadWord part true)) (reg .numBase false) rfl\n    (bank start) (signed x) (putReg_fields (buffers w reader todo) .numBase x).1\n  rw [update_register] at h0\n  change Runs program _ _ _ _ (bank first) at h0\n  have hx:first.registers (.numBase,true)=x.denominator:=by\n    change Function.update start.registers (.numBase,false) [] (.numBase,true)=_\n    simp only [Function.update_of_ne (show ((.numBase,true):SemiprimeD1StackRecoveryGrid.Reg×Bool)≠(.numBase,false) from by decide)]\n    exact (putReg_fields (buffers w reader todo) .numBase x).2\n  have h1:=T.drain_loop (.local (.clearReadWord part true)) (.local (.readCount part)) (reg .numBase true) rfl\n    (bank first) x.denominator hx\n  rw [update_register] at h1\n  have he:{first with registers:=Function.update first.registers (.numBase,true) []}=buffers w reader todo:=by\n    exact erase_put (buffers w reader todo) x hn hd\n  rw [he] at h1\n  simpa only [Nat.add_assoc] using T.join h0 h1\n/-- After a selected physical row, all unread vector bytes are paid and consumed. -/\ntheorem tail_run (part:Part) (w:Words) (x:SemiprimeRationalBits.RationalWord) (reader todo:List Bool):\n    Runs program (reader.length+1) (.local (.clearReadTail part)) (bank (putReg (buffers w reader todo) .numBase x))\n      (.local (.factor part)) (bank (putReg (buffers w [] todo) .numBase x)):=by\n  rw [put_buffers]\n  have h:=T.drain_loop (.local (.clearReadTail part)) (.local (.factor part)) (aux .reader) rfl\n    (bank (buffers (putReg w .numBase x) reader todo)) reader rfl\n  rw [update_reader] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineReadClear\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineReadMissing":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineReadBuffers\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffinePrimitives\n/-! # Actual EOF-limited zero extension, including q0 and W0 -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineReadMissing\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\nopen SemiprimeD1StackRecoveryAffineReadBuffers SemiprimeD1StackProcedureTrace\nnamespace T\nexport SemiprimeD1StackRecoveryAffinePrimitives (join drain_loop push_run)\nend T\n/-- After actual vector EOF, remaining byte markers are consumed and literal legacy ZERO is pushed. -/\ntheorem missing_run (part:Part) (w:Words) (todo:List Bool)\n    (hn:w.registers (.numBase,false)=[]) (hd:w.registers (.numBase,true)=[]):\n    Runs program (todo.length+4) (.local (.missingReader part)) (bank (buffers w [] todo))\n      (.local (.factor part)) (bank (putReg (buffers w [] []) .numBase SemiprimeRationalBits.zeroWord)):=by\n  let w0:=buffers w [] []\n  let w1:Words:={w0 with registers:=Function.update w0.registers (.numBase,true) [true]}\n  have h0:=T.drain_loop (.local (.missingReader part)) (.local (.missingTodo part)) (aux .reader) rfl\n    (bank (buffers w [] todo)) [] rfl\n  rw [update_reader] at h0\n  have h1:=T.drain_loop (.local (.missingTodo part)) (.local (.missingDen part)) (aux .readTodo) rfl\n    (bank (buffers w [] todo)) todo rfl\n  rw [update_todo] at h1\n  have h2:=T.push_run (.local (.missingDen part)) (.local (.missingSign part)) (reg .numBase true) true (bank w0) rfl\n  change Runs program _ _ _ _ (Function.update (bank w0) (reg .numBase true) (true::w.registers (.numBase,true))) at h2\n  rw [hd,update_register] at h2\n  change Runs program _ _ _ _ (bank w1) at h2\n  have h3:=T.push_run (.local (.missingSign part)) (.local (.factor part)) (reg .numBase false) false (bank w1) rfl\n  have hx:w1.registers (.numBase,false)=[]:=by\n    dsimp only [w1,w0,buffers]\n    simp [hn]\n  change Runs program _ _ _ _ (Function.update (bank w1) (reg .numBase false) (false::w1.registers (.numBase,false))) at h3\n  rw [hx,update_register] at h3\n  have he:{w1 with registers:=Function.update w1.registers (.numBase,false) [false]}=\n      putReg w0 .numBase SemiprimeRationalBits.zeroWord:=by\n    dsimp only [w1,putReg]\n    congr 1\n    congr 1\n    funext slot\n    rcases slot with ⟨r,b⟩\n    cases r <;> cases b <;> simp [signed,SemiprimeRationalBits.zeroWord]\n  rw [he] at h3\n  have h:=T.join (T.join (T.join h0 h1) h2) h3\n  convert h using 1\n  simp only [List.length_nil]\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineReadMissing\n","RiemannGaussian.SemiprimeD1StackRecoveryAffineWordCaps":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineCleanup\nimport RiemannGaussian.SemiprimeD1StackRecoveryAffineCache\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridWordCaps\n/-! # Actual112-word boundary caps preserve semantic register widths and all foreign bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryAffineWordCaps\nopen SemiprimeD1StackRecoveryAffine SemiprimeD1StackRecoveryAffineView\nopen SemiprimeD1StackRecoveryGrid (Reg)\n/-- Every original or borrowed signed rational cache has its actual semantic byte cap. -/\ndef Registers (w:Words) (B:Nat):Prop:=∀r b,(w.registers (r,b)).length≤B\n/-- Every112 allocated actual tape, including all added arrays and shadow roles, is counted. -/\ndef Data (w:Words) (L:Nat):Prop:=∀slot,(bank w slot).length≤L\n/-- One actual field write retains the cap of every other111 physical word. -/\ntheorem update_le (before:Stack→List Bool) (slot:Stack) (xs:List Bool) (L:Nat)\n    (h:∀k,(before k).length≤L) (hx:xs.length≤L):∀k,(Function.update before slot xs k).length≤L:=by\n  intro k\n  by_cases he:k=slot\n  · subst k\n    simpa only [Function.update_self] using hx\n  · rw [Function.update_of_ne he]\n    exact h k\n/-- Two actual cache writes preserve every unrelated original/additional role. -/\ntheorem bank_putReg (w:Words) (r:Reg) (x:SemiprimeRationalBits.RationalWord):\n    Function.update (Function.update (bank w) (reg r false) (signed x)) (reg r true) x.denominator=bank (putReg w r x):=by\n  rw [update_register,update_register]\n  rfl\n/-- Fitted/literal word widths, rather than elapsed execution, bound each updated scalar register. -/\ntheorem put_registers (w:Words) (r:Reg) (x:SemiprimeRationalBits.RationalWord) (B:Nat)\n    (hw:Registers w B) (hn:x.numerator.magnitude.length+1≤B) (hd:x.denominator.length≤B):Registers (putReg w r x) B:=\n  SemiprimeD1StackRecoveryGridWordCaps.put_registers w.toWords r x B hw hn hd\n/-- The actual new signed and denominator bytes preserve the complete112-tape cap. -/\ntheorem put_data (w:Words) (r:Reg) (x:SemiprimeRationalBits.RationalWord) (L:Nat)\n    (hw:Data w L) (hn:x.numerator.magnitude.length+1≤L) (hd:x.denominator.length≤L):Data (putReg w r x) L:=by\n  have h0:=update_le (bank w) (reg r false) (signed x) L hw hn\n  have h1:=update_le (Function.update (bank w) (reg r false) (signed x)) (reg r true) x.denominator L h0 hd\n  rw [bank_putReg] at h1\n  exact h1\n/-- Any actual added-word replacement retains all old104 register fields. -/\ntheorem added_registers (w:Words) (slot:Aux) (xs:List Bool) (B:Nat) (hw:Registers w B):\n    Registers {w with added:=Function.update w.added slot xs} B:=hw\n/-- Every newly stored actual counter/vector byte is charged explicitly. -/\ntheorem added_data (w:Words) (slot:Aux) (xs:List Bool) (L:Nat) (hw:Data w L) (hx:xs.length≤L):\n    Data {w with added:=Function.update w.added slot xs} L:=by\n  have h:=update_le (bank w) (aux slot) xs L hw hx\n  rw [update_added] at h\n  exact h\n/-- Literal byte-count word replacement preserves the actual whole bank cap. -/\ntheorem counter_data (w:Words) (n L:Nat) (hw:Data w L) (hn:n≤L):Data (SemiprimeD1StackRecoveryAffineCache.counter w n) L:=by\n  apply added_data w .k _ L hw\n  simpa only [SemiprimeD1StackRecoveryAffineReadCount.unary,List.length_replicate] using hn\n/-- Actual112-word mass pays every allocated data role, with no omitted alias shadow. -/\ntheorem mass_le (w:Words) (L:Nat) (hw:Data w L):SemiprimeD1StackRecoveryAffineCleanup.mass (bank w)≤112*L:=\n  SemiprimeD1StackRecoveryAffineCleanup.word_sum (bank w) L hw\nend RiemannGaussian.SemiprimeD1StackRecoveryAffineWordCaps\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinate":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedExecution\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedBounds\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackReverseWord\n/-! # Actual column acquisition from retained phase-block bytes\nOnly a physical phase/block/word vector and a binary coordinate enter the\nfixed21-role program. No coordinate cache, rank, precision or getter is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinate\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace I\nexport SemiprimeD1StackRecoveryEntriesIndexed (Stack Label Aux program aux initial input)\nend I\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Nine literal retained-bank/parser/two-level logger roles. -/\ninductive Aux where\n  | phases | reader | blocks | valid | rowHistory | rowOutput | history | buffer | output\n  deriving DecidableEq,Repr\ninstance :Fintype Aux:=Fintype.ofList [.phases,.reader,.blocks,.valid,.rowHistory,.rowOutput,.history,.buffer,.output]\n  (by intro k;cases k <;> simp)\n/-- Full12-role binary reader and all9 allocated outer roles. -/\nabbrev Stack:=I.Stack⊕Aux\n/-- The actual binary indexed reader inclusion. -/\ndef indexed:I.Stack→Stack:=Sum.inl\n/-- Actual phase source/parser/logger tape. -/\ndef aux:Aux→Stack:=Sum.inr\n/-- Retained original raw binary coordinate; high-zero padding is allowed. -/\ndef coordinate:Stack:=indexed (I.aux .query)\n/-- Current physically parsed block vector. -/\ndef block:Stack:=indexed (I.aux .cache)\n/-- Actual selected/default coefficient word. -/\ndef selected:Stack:=indexed (I.aux .value)\n/-- Shared real restoring-copy/parser/frame scratch, empty between all calls. -/\ndef scratch:Stack:=indexed (I.aux .copy)\n/-- Actual resulting nested child-coordinate vector. -/\ndef output:Stack:=aux .output\n/-- One preserving copy of the whole original phase bank. -/\ndef copyStack (k:Fin 3):Stack:=if k=0 then aux .phases else if k=1 then aux .reader else scratch\n/-- Two physical parser inclusions: a phase payload, then each actual block. -/\ndef fieldStack (inner:Bool):F.Stack→Stack\n  | .inl .input=>if inner then aux .blocks else aux .reader\n  | .inl .scratch=>scratch\n  | .inl .output=>if inner then block else aux .blocks\n  | .inr () =>aux .valid\n/-- Two real preserving frame sites; coefficients and completed phase rows. -/\ndef frameStack (phase:Bool) (k:Fin 3):Stack:=\n  if k=0 then if phase then aux .rowOutput else selected\n  else if k=1 then aux .buffer else scratch\n/-- Four genuine reversals, with two separate accumulated histories. -/\ndef reverseStack (site:Fin 4) (k:Fin 2):Stack:=\n  if k=0 then if site=0 ∨site=2 then aux .buffer else if site=1 then aux .rowHistory else aux .history\n  else if site=0 then aux .rowHistory else if site=1 then aux .rowOutput else if site=2 then aux .history else output\n/-- Literal finite nested-vector/lookup/logger control. -/\ninductive Control where\n  | start | sentinel | phaseLoop | phaseField | phaseValid | rowSeed | blockLoop | blockField | blockValid\n  | lookup | coefficientFrame | coefficientTag | coefficientReverse | clearBlock | clearSelected\n  | rowReverse | phaseFrame | phaseTag | phaseReverse | clearRow | finish | done | abort\n  deriving DecidableEq,Repr\ninstance :Fintype Control:=Fintype.ofList [.start,.sentinel,.phaseLoop,.phaseField,.phaseValid,.rowSeed,.blockLoop,.blockField,.blockValid,\n  .lookup,.coefficientFrame,.coefficientTag,.coefficientReverse,.clearBlock,.clearSelected,\n  .rowReverse,.phaseFrame,.phaseTag,.phaseReverse,.clearRow,.finish,.done,.abort] (by intro k;cases k <;> simp)\n/-- All component entry and saved-return labels are fixed before both tapes. -/\ninductive Label where\n  | local (pc:Control) | indexed (pc:I.Label) | copy (pc:Fin 9)\n  | field (inner:Bool) (pc:F.Label) | frame (phase:Bool) (pc:Fin 11) | reverse (site:Fin 4) (pc:Fin 4)\n  deriving DecidableEq,Fintype,Repr\nlocal notation \"ctl\"=>Label.local\n/-- The ONE parameterless physical coordinate source, including every call, drain and halt. -/\ndef program:Label→C.Instruction Stack Label\n  | .local .start=>.call (.copy 0) (ctl .sentinel)\n  | .local .sentinel=>.base (.push output false (ctl .phaseLoop))\n  | .local .phaseLoop=>.base (.pop (aux .reader) (ctl .abort) (ctl .finish) (ctl .phaseField))\n  | .local .phaseField=>.call (.field false (F.active .tagPop (none,false))) (ctl .phaseValid)\n  | .local .phaseValid=>.base (.pop (aux .valid) (ctl .abort) (ctl .abort) (ctl .rowSeed))\n  | .local .rowSeed=>.base (.push (aux .rowOutput) false (ctl .blockLoop))\n  | .local .blockLoop=>.base (.pop (aux .blocks) (ctl .abort) (ctl .rowReverse) (ctl .blockField))\n  | .local .blockField=>.call (.field true (F.active .tagPop (none,false))) (ctl .blockValid)\n  | .local .blockValid=>.base (.pop (aux .valid) (ctl .abort) (ctl .abort) (ctl .lookup))\n  | .local .lookup=>.call (.indexed (.local .start)) (ctl .coefficientFrame)\n  | .local .coefficientFrame=>.call (.frame false 0) (ctl .coefficientTag)\n  | .local .coefficientTag=>.base (.push (aux .buffer) true (ctl .coefficientReverse))\n  | .local .coefficientReverse=>.call (.reverse 0 0) (ctl .clearBlock)\n  | .local .clearBlock=>.base (.pop block (ctl .clearSelected) (ctl .clearBlock) (ctl .clearBlock))\n  | .local .clearSelected=>.base (.pop selected (ctl .blockLoop) (ctl .clearSelected) (ctl .clearSelected))\n  | .local .rowReverse=>.call (.reverse 1 0) (ctl .phaseFrame)\n  | .local .phaseFrame=>.call (.frame true 0) (ctl .phaseTag)\n  | .local .phaseTag=>.base (.push (aux .buffer) true (ctl .phaseReverse))\n  | .local .phaseReverse=>.call (.reverse 2 0) (ctl .clearRow)\n  | .local .clearRow=>.base (.pop (aux .rowOutput) (ctl .phaseLoop) (ctl .clearRow) (ctl .clearRow))\n  | .local .finish=>.call (.reverse 3 0) (ctl .done)\n  | .local .done|.local .abort=>.base .halt\n  | .indexed pc=>SemiprimeD1StackValidationLink.instruction indexed Label.indexed (I.program pc)\n  | .copy pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .field inner pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack inner) (Label.field inner) (F.code pc)\n  | .frame phase pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack phase) (Label.frame phase) (SemiprimeD1StackFrame.code pc)\n  | .reverse site pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack site) (Label.reverse site) (SemiprimeD1StackReverseWord.code pc)\n/-- Exactly the retained actual phase bank and raw binary coordinate are initialized. -/\ndef input (phases key:List Bool):Stack→List Bool:=\n  Function.update (Function.update (fun _=>[]) (aux .phases) phases) coordinate key\n/-- Both real operands enter with every work/output role empty. -/\ndef initial (phases key:List Bool):C.State Stack Label:=⟨some (ctl .start),none,none,input phases key,[]⟩\n/-- Genuine finite21-tape machine with no prepared coordinate-cache operand. -/\ndef machine:Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .phases) output (ctl .start) program\n/-- All21 allocated physical roles are counted. -/\ntheorem stack_card:Fintype.card Stack=21:=by decide\n/-- Full reader inclusion retains all12 real roles. -/\ntheorem indexed_injective:Function.Injective indexed:=Sum.inl_injective\n/-- Actual phase-bank copy has distinct physical operands. -/\ntheorem copy_injective:Function.Injective copyStack:=by decide\n/-- Both physical field parsers use distinct operands. -/\ntheorem field_injective (inner:Bool):Function.Injective (fieldStack inner):=by cases inner <;> decide\n/-- Both physical preserving frame sites use distinct operands. -/\ntheorem frame_injective (phase:Bool):Function.Injective (frameStack phase):=by cases phase <;> decide\n/-- All four actual reversals have different source and target roles. -/\ntheorem reverse_injective (site:Fin 4):Function.Injective (reverseStack site):=by fin_cases site <;> decide\n/-- Every data/return alphabet is finite before the input bytes. -/\ntheorem alphabets_finite:∀k,Finite (machine.Γ k):=\n  SemiprimeD1StackCalls.all_alphabets_finite (aux .phases) output (ctl .start) program\n/-- No address value, list, evaluator or supplied result inhabits runtime control. -/\ntheorem control_finite:Finite machine.σ:=SemiprimeD1StackCalls.control_finite (aux .phases) output (ctl .start) program\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinate\n","RiemannGaussian.SemiprimeD1StackRecoveryCoordinatePhase":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryCoordinateBlocks\n/-! # Complete actual per-phase column acquisition and occurrence-preserving log\nThe actual block payload comes from the parsed phase field. Every empty phase\nstill contributes one literal empty child row. No coordinate cache is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryCoordinatePhase\nopen SemiprimeD1StackRecoveryCoordinate SemiprimeD1StackRecoveryCoordinateState\nopen SemiprimeD1StackRecoveryCoordinatePrimitives SemiprimeD1StackRecoveryCoordinateFields\nopen SemiprimeD1StackRecoveryCoordinateLogger SemiprimeD1StackRecoveryCoordinateEncoding\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nnamespace B\nexport SemiprimeD1StackRecoveryCoordinateBlocks (budget blocks_run)\nend B\n/-- Actual completed phase row, including its one physical false sentinel. -/\ndef phaseRow (key:List Bool) (blocks:List (List (List Bool))):List Bool:=vectorBits (row key blocks)\n/-- Actual whole phase clock, independent of the prior outer phase history. -/\ndef phaseTime (key:List Bool) (blocks:List (List (List Bool))):Nat:=\n  1+(8*(vectorBits (blocks.map vectorBits)).length+8)+1+B.budget key blocks []+\n    (6*(phaseRow key blocks).length+5)+1+(2*(chunk (phaseRow key blocks)).length+3)+((phaseRow key blocks).length+1)\n/-- Real phase parse, all physical block lookups, exact child-row framing, outer log and cleanup. -/\ntheorem phase_run (key original history out:List Bool) (blocks:List (List (List Bool))) (rest:Phases):\n    Runs program (phaseTime key blocks) (.local .phaseLoop)\n      (data key (words {phases:=original,reader:=tape (blocks::rest),history:=history,output:=out})) (.local .phaseLoop)\n      (data key (words {phases:=original,reader:=tape rest,history:=(chunk (phaseRow key blocks)).reverse++history,output:=out})):=by\n  let v:Words:={phases:=original,reader:=tape (blocks::rest),history:=history,output:=out}\n  let afterTag:Words:={v with reader:=SemiprimeSourceHistogramKeyBits.frame (vectorBits (blocks.map vectorBits)) (tape rest)}\n  let parsed:Words:={v with reader:=tape rest,blocks:=vectorBits (blocks.map vectorBits)}\n  let acquired:Words:={v with reader:=tape rest,rowOutput:=phaseRow key blocks}\n  let framed:Words:={acquired with buffer:=SemiprimeSourceHistogramKeyBits.frame (phaseRow key blocks) []}\n  let tagged:Words:={framed with buffer:=chunk (phaseRow key blocks)}\n  let logged:Words:={acquired with history:=(chunk (phaseRow key blocks)).reverse++history}\n  have h0:=pop_run (.local .phaseLoop) (.local .abort) (.local .finish) (.local .phaseField)\n    .reader key (words v) (tape (blocks::rest)) rfl rfl\n  change Runs program 1 (.local .phaseLoop) (data key (words v)) (.local .phaseField)\n    (data key (Function.update (words v) .reader afterTag.reader)) at h0\n  rw [words_update] at h0\n  have h1:=field_read false key (words afterTag) (vectorBits (blocks.map vectorBits)) (tape rest) rfl rfl rfl\n  simp only [words_update,setWord] at h1\n  have h2:=push_run (.local .rowSeed) (.local .blockLoop) .rowOutput false key (words parsed) rfl\n  rw [words_update] at h2\n  have h3:=B.blocks_run key original (tape rest) [false] history out blocks []\n  simp only [List.reverse_nil,List.nil_append,chunks_vector] at h3\n  have h4:=frame_call true key (words acquired)\n  rw [words_update] at h4\n  have h5:=push_run (.local .phaseTag) (.local .phaseReverse) .buffer true key (words framed) rfl\n  rw [words_update] at h5\n  have h6:=reverse_call 2 (.local .phaseReverse) (.local .clearRow) key (words tagged) rfl\n  simp only [words_update,setWord] at h6\n  have h7:=drain_run (.local .clearRow) (.local .phaseLoop) .rowOutput key (words logged) (phaseRow key blocks) rfl rfl\n  rw [words_update] at h7\n  have h:=join (join (join (join (join (join (join h0 h1) h2) h3) h4) h5) h6) h7\n  exact h\nend RiemannGaussian.SemiprimeD1StackRecoveryCoordinatePhase\n","RiemannGaussian.SemiprimeD1StackRecoveryEntries":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexed\nimport RiemannGaussian.SemiprimeD1StackFrame\nimport RiemannGaussian.SemiprimeD1StackReverseWord\n/-! # Actual recovery-entry acquisition from row and nested-child tapes\nOnly the actual five-field canonical row tape and actual nested child-word\nvector are supplied. Two real binary indexed scans acquire each coefficient.\nFour actual frames and two physical reversal stages preserve exact entry order.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntries\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State run)\nend C\nnamespace I\nexport SemiprimeD1StackRecoveryEntriesIndexed (Stack Label Aux program initial input aux)\nend I\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend F\n/-- Thirteen literal retained/source/row/logger roles beside the whole12-role lookup bank. -/\ninductive Aux where\n  | rows | reader | node | index | sign | magnitude | denominator | selectedRow | child\n  | valid | history | frameBuffer | output\n  deriving DecidableEq,Repr\ninstance :Fintype Aux:=Fintype.ofList [.rows,.reader,.node,.index,.sign,.magnitude,.denominator,\n  .selectedRow,.child,.valid,.history,.frameBuffer,.output] (by intro k;cases k <;> simp)\n/-- All25 actual roles include both unused original lookup query/value shadows. -/\nabbrev Stack:=I.Stack⊕Aux\n/-- Complete physical indexed-reader bank, retaining every private/shadow role. -/\ndef indexed:I.Stack → Stack:=Sum.inl\n/-- Original row, parsed metadata and physical entry logger fields. -/\ndef aux:Aux → Stack:=Sum.inr\n/-- Original nested child-word tape remains directly in the actual retained cache role. -/\ndef children:Stack:=indexed (I.aux .cache)\n/-- Complete acquired entry tape. -/\ndef output:Stack:=aux .output\n/-- Restoring-copy scratch is reused only while the indexed reader is genuinely stopped clean. -/\ndef scratch:Stack:=indexed (I.aux .copy)\n/-- Fixed outer/inner lookup inclusion; both allocated original query/value shadows remain counted. -/\ndef indexStack (inner:Bool) (k:I.Stack):Stack:=\n  if k=I.aux .cache then if inner then aux .selectedRow else children\n  else if k=I.aux .query then if inner then aux .index else aux .node\n  else if k=I.aux .value then if inner then aux .child else aux .selectedRow else indexed k\n/-- Actual five source fields, never a field getter runtime operand. -/\ndef fieldTarget (part:Fin 5):Stack:=\n  if part=0 then aux .node else if part=1 then aux .index else if part=2 then aux .sign\n  else if part=3 then aux .magnitude else aux .denominator\n/-- Actual four-role canonical-row field parser. -/\ndef fieldStack (part:Fin 5):F.Stack → Stack\n  | .inl .input=>aux .reader | .inl .scratch=>scratch | .inl .output=>fieldTarget part | .inr () =>aux .valid\n/-- Actual retained input copy, executed once before any row scan. -/\ndef copyStack (k:Fin 3):Stack:=if k=0 then aux .rows else if k=1 then aux .reader else scratch\n/-- Reverse-order framing physically prepends child,D,magnitude,sign onto the row buffer. -/\ndef frameSource (part:Fin 4):Stack:=\n  if part=0 then aux .child else if part=1 then aux .denominator else if part=2 then aux .magnitude else aux .sign\n/-- Actual real preserving Frame operands. -/\ndef frameStack (part:Fin 4) (k:Fin 3):Stack:=if k=0 then frameSource part else if k=1 then aux .frameBuffer else scratch\n/-- Both actual reversal stages consume their real source bytes. -/\ndef reverseStack (finish:Bool) (k:Fin 2):Stack:=\n  if k=0 then if finish then aux .history else aux .frameBuffer\n  else if finish then output else aux .history\n/-- Seven per-row acquired metadata/payload words are physically cleared after logging. -/\ndef clearTarget (part:Fin 7):Stack:=\n  if part=0 then aux .node else if part=1 then aux .index else if part=2 then aux .sign\n  else if part=3 then aux .magnitude else if part=4 then aux .denominator\n  else if part=5 then aux .selectedRow else aux .child\n/-- Fixed finite entry-loop control; no address, row, count or answer inhabits it. -/\ninductive Control where\n  | start | sentinel | loop | field (part:Fin 5) | valid (part:Fin 5)\n  | outer | normalize | emptyRow | inner | frame (part:Fin 4) | tag | rowReverse\n  | clear (part:Fin 7) | finish | done | abort\n  deriving DecidableEq,Fintype,Repr\n/-- Actual component and all real saved return labels are finite before both input tapes. -/\ninductive Label where\n  | local (pc:Control) | indexed (inner:Bool) (pc:I.Label) | field (part:Fin 5) (pc:F.Label)\n  | copy (pc:Fin 9) | frame (part:Fin 4) (pc:Fin 11) | reverse (finish:Bool) (pc:Fin 4)\n  deriving DecidableEq,Fintype,Repr\nlocal notation \"ctl\"=>Label.local\n/-- Static successor of an actual source-field parse. -/\ndef nextField (part:Fin 5):Label:=if h:part.val+1<5 then ctl (.field ⟨part.val+1,h⟩) else ctl .outer\n/-- Static successor of an actual preserving frame call. -/\ndef nextFrame (part:Fin 4):Label:=if h:part.val+1<4 then ctl (.frame ⟨part.val+1,h⟩) else ctl .tag\n/-- Static successor of an actual per-row drain. -/\ndef nextClear (part:Fin 7):Label:=if h:part.val+1<7 then ctl (.clear ⟨part.val+1,h⟩) else ctl .loop\n/-- One fixed finite entry source; numeric addresses remain binary and every lookup stops at actual vector EOF. -/\ndef program:Label → C.Instruction Stack Label\n  | .local .start=>.call (.copy 0) (ctl .sentinel)\n  | .local .sentinel=>.base (.push output false (ctl .loop))\n  | .local .loop=>.base (.pop (aux .reader) (ctl .abort) (ctl .finish) (ctl (.field 0)))\n  | .local (.field part)=>.call (.field part (F.active .tagPop (none,false))) (ctl (.valid part))\n  | .local (.valid part)=>.base (.pop (aux .valid) (ctl .abort) (ctl .abort) (nextField part))\n  | .local .outer=>.call (.indexed false (.local .start)) (ctl .normalize)\n  | .local .normalize=>.base (.peek (aux .selectedRow) (ctl .emptyRow) (ctl .inner) (ctl .inner))\n  | .local .emptyRow=>.base (.push (aux .selectedRow) false (ctl .inner))\n  | .local .inner=>.call (.indexed true (.local .start)) (ctl (.frame 0))\n  | .local (.frame part)=>.call (.frame part 0) (nextFrame part)\n  | .local .tag=>.base (.push (aux .frameBuffer) true (ctl .rowReverse))\n  | .local .rowReverse=>.call (.reverse false 0) (ctl (.clear 0))\n  | .local (.clear part)=>.base (.pop (clearTarget part) (nextClear part) (ctl (.clear part)) (ctl (.clear part)))\n  | .local .finish=>.call (.reverse true 0) (ctl .done)\n  | .local .done|.local .abort=>.base .halt\n  | .indexed inner pc=>SemiprimeD1StackValidationLink.instruction (indexStack inner) (Label.indexed inner) (I.program pc)\n  | .field part pc=>SemiprimeD1StackMultiplierLink.instruction (fieldStack part) (Label.field part) (F.code pc)\n  | .copy pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copy (SemiprimeD1StackCopy.code pc)\n  | .frame part pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack part) (Label.frame part) (SemiprimeD1StackFrame.code pc)\n  | .reverse finish pc=>SemiprimeD1StackMultiplierLink.instruction (reverseStack finish) (Label.reverse finish) (SemiprimeD1StackReverseWord.code pc)\n/-- Exactly two real source tapes, with no template, Entry structure, node/index getter or selected coefficient supplied. -/\ndef input (rowTape childTape:List Bool):Stack → List Bool:=\n  Function.update (Function.update (fun _=>[]) (aux .rows) rowTape) children childTape\n/-- Actual two-tape source entry starts with all private/result/counter/shadow roles clear. -/\ndef initial (rowTape childTape:List Bool):C.State Stack Label:=\n  ⟨some (ctl .start),none,none,input rowTape childTape,[]⟩\n/-- One parameterless fixed finite entry-acquisition machine. -/\ndef machine:Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .rows) output (ctl .start) program\n/-- Every allocated physical tape and both unused indexed input/result shadows are counted. -/\ntheorem stack_card:Fintype.card Stack=25:=by decide\n/-- Both actual binary reader inclusions have distinct physical roles. -/\ntheorem index_injective (inner:Bool):Function.Injective (indexStack inner):=by cases inner <;> decide\n/-- Every actual row parser has four distinct physical operands. -/\ntheorem field_injective (part:Fin 5):Function.Injective (fieldStack part):=by fin_cases part <;> decide\n/-- The one retained-row copy has three distinct actual operands. -/\ntheorem copy_injective:Function.Injective copyStack:=by decide\n/-- Every real preserving frame has three distinct actual roles. -/\ntheorem frame_injective (part:Fin 4):Function.Injective (frameStack part):=by fin_cases part <;> decide\n/-- Both real reversals have separate source and target words. -/\ntheorem reverse_injective (finish:Bool):Function.Injective (reverseStack finish):=by cases finish <;> decide\n/-- Data and actual saved-return alphabets are fixed finite before both tapes. -/\ntheorem alphabets_finite:∀k,Finite (machine.Γ k):=\n  SemiprimeD1StackCalls.all_alphabets_finite (aux .rows) output (ctl .start) program\n/-- No natural value, list, getter, evaluator or answer occupies runtime transient control. -/\ntheorem control_finite:Finite machine.σ:=\n  SemiprimeD1StackCalls.control_finite (aux .rows) output (ctl .start) program\nend RiemannGaussian.SemiprimeD1StackRecoveryEntries\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedExecution\n/-! # Own physical-byte binary-query scan clock, independent of address value\nThe acquired ordinal grows only with actual scanned fields. All comparisons,\nfull binary increments, materialized payloads, unread suffix drains and real\nreturns are bounded by actual cache/query bytes, never by numeric query value.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedBounds\nopen SemiprimeD1StackRecoveryEntriesIndexed SemiprimeD1StackRecoveryEntriesIndexedSpec\nopen SemiprimeD1StackRecoveryEntriesIndexedOperators SemiprimeD1StackRecoveryEntriesIndexedLoop\nopen SemiprimeD1StackRecoveryEntriesIndexedExecution\nopen SemiprimeD1TensorTapeCodec (vectorBits)\n/-- Actual full numeric comparison plus two real operand copies and physical decision pop is linear in binary bytes. -/\ntheorem compare_time (query counter:List Bool):compareTime query counter ≤10*(query.length+counter.length+2):=by\n  have h:=SemiprimeD1StackWordEqualExecution.executionTime_le query counter\n  unfold compareTime\n  omega\n/-- Actual full increment adder clock is linear in the acquired binary ordinal's physical width. -/\ntheorem add_time (counter:List Bool):addTime counter ≤10*(counter.length+2):=by\n  have h:=increment_length counter\n  have hm:max counter.length 1 ≤counter.length+1:=max_le (by omega) (by omega)\n  unfold addTime\n  omega\n/-- All actual counter copies, drains, one-bit seed, full adder and restored output are paid. -/\ntheorem increment_time (counter:List Bool):incrementTime counter ≤100*(counter.length+1):=by\n  have h:=increment_length counter\n  have ha:=add_time counter\n  unfold incrementTime\n  omega\n/-- Exact physical vector-byte recurrence, including true marker and frame delimiter. -/\ntheorem vector_cons_length (word:List Bool) (words:List (List Bool)):\n    (vectorBits (word::words)).length=2*word.length+(vectorBits words).length+2:=by\n  simp only [vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n/-- Every actual future field and every ordinal increment is paid by remaining source fields, not query magnitude. -/\ntheorem budget_cap (words:List (List Bool)) (query counter:List Bool) (cap L:Nat)\n    (hc:counter.length+2*words.length ≤cap) (hl:(vectorBits words).length ≤L):\n    budget query counter words ≤1000*(words.length+1)*(query.length+cap+L+1):=by\n  induction words generalizing counter with\n  | nil=>\n    simp only [budget,List.length_nil,Nat.mul_zero,Nat.add_zero] at hc ⊢\n    omega\n  | cons word words ih=>\n    have hv:=vector_cons_length word words\n    have hn:(increment counter).length+2*words.length ≤cap:=by\n      have hi:=increment_length counter\n      simp only [List.length_cons] at hc\n      omega\n    have ht:=ih (increment counter) hn (by omega)\n    have he:=compare_time query counter\n    have hi:=increment_time counter\n    have hcounter:counter.length ≤cap:=by omega\n    have hw:word.length ≤L:=by omega\n    have hrest:(vectorBits words).length ≤L:=by omega\n    unfold budget\n    split\n    · have hstep:(1+compareTime query counter)+(8*word.length+8)+((vectorBits words).length+1)+(counter.length+1) ≤\n        1000*(query.length+cap+L+1):=by omega\n      have hm:1000*(query.length+cap+L+1) ≤1000*((word::words).length+1)*(query.length+cap+L+1):=by\n        have hpos:1 ≤(word::words).length+1:=by omega\n        have h:=Nat.mul_le_mul_right (query.length+cap+L+1) (Nat.mul_le_mul_left 1000 hpos)\n        simpa only [Nat.mul_one] using h\n      simpa only [Nat.add_assoc] using hstep.trans hm\n    · have hstep:(1+compareTime query counter)+(9*word.length+9)+incrementTime counter ≤\n        1000*(query.length+cap+L+1):=by omega\n      simp only [List.length_cons]\n      nlinarith only [hstep,ht]\n/-- SAME actual complete binary-index source has a fixed quadratic bound in its two physical input lengths. -/\ndef runBound (words:List (List Bool)) (query:List Bool):Nat:=1000000*((vectorBits words).length+query.length+1)^2\n/-- All actual source copies/branches/returns and genuine halt fit the same physical-byte quadratic. -/\ntheorem timeBound_le (words:List (List Bool)) (query:List Bool):timeBound words query ≤runBound words query:=by\n  let C:=(vectorBits words).length\n  let S:=C+query.length+1\n  have hv:=SemiprimeD1TensorTapeCodec.vectorBits_length words\n  have hc:2*words.length ≤C:=by dsimp [C];omega\n  have hb:=budget_cap words query [] (2*words.length) C (by simp) (by rfl)\n  have hn:words.length+1 ≤S:=by dsimp [S];omega\n  have hinner:query.length+2*words.length+C+1 ≤2*S:=by dsimp [S];omega\n  have hh:(words.length+1)*(query.length+2*words.length+C+1) ≤2*S^2:=by\n    calc\n      _ ≤S*(2*S):=Nat.mul_le_mul hn hinner\n      _=2*S^2:=by ring\n  have hb':budget query [] words ≤2000*S^2:=by\n    calc\n      _ ≤1000*((words.length+1)*(query.length+2*words.length+C+1)):=by simpa only [Nat.mul_assoc] using hb\n      _ ≤1000*(2*S^2):=Nat.mul_le_mul_left 1000 hh\n      _=2000*S^2:=by ring\n  have hpos:1 ≤S:=by dsimp [S];omega\n  have hs:S ≤S^2:=by simpa only [pow_one] using Nat.pow_le_pow_right hpos (by decide:1 ≤2)\n  have hC:C+1 ≤S:=by dsimp [S];omega\n  have hlinear:5*C+5 ≤10*S^2:=by omega\n  change 5*C+4+budget query [] words+1 ≤1000000*S^2\n  omega\n/-- Every actual physical vector field is bounded by its acquired source bytes. -/\ntheorem member_length (words:List (List Bool)) (word:List Bool) (h:word∈words):\n    word.length ≤(vectorBits words).length:=by\n  induction words with\n  | nil=>cases h\n  | cons head words ih=>\n    have hv:=vector_cons_length head words\n    simp only [List.mem_cons] at h\n    rcases h with rfl|h\n    · omega\n    · have ht:=ih h\n      omega\n/-- Actual selected field or EOF default never exceeds the actual physical cache length. -/\ntheorem result_length (words:List (List Bool)) (query:List Bool):\n    ((words[SemiprimeBitArithmetic.bitValue query]?).getD []).length ≤(vectorBits words).length:=by\n  cases h:words[SemiprimeBitArithmetic.bitValue query]? with\n  | none=>simp\n  | some word=>\n    have hm:word∈words:=List.mem_of_getElem? h\n    exact member_length words word hm\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesIndexedBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryEntriesRead":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryEntriesCalls\n/-! # Actual two-level child acquisition with literal EOF defaults\nThe outer lookup acquires one actual encoded row. A missing row is physically\nnormalized by one false push, then the inner binary lookup reads the coefficient.\nBoth original source tapes and every parsed row byte remain retained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryEntriesRead\nopen SemiprimeD1StackRecoveryEntries SemiprimeD1StackRecoveryEntriesState\nopen SemiprimeD1StackRecoveryEntriesPrimitives SemiprimeD1StackRecoveryEntriesCalls\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeD1StackRecoveryEntriesEncoding (childTape selectedChild)\nopen SemiprimeD1StackRecoveryDenominatorEncoding (Row)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeBitArithmetic (bitValue)\n/-- Actual missing-row byte normalization, a literal false sentinel rather than a child answer. -/\ndef normalized:List Bool → List Bool\n  | []=>[false]\n  | b::bs=>b::bs\n/-- The physical normalization test and optional literal push have their own actual clock. -/\ndef normalizeTime:List Bool → Nat\n  | []=>2\n  | _::_=>1\n/-- One actual peek and, exactly at physical EOF, one actual false push. -/\ntheorem normalize_run (children:List Bool) (w:Aux → List Bool) (row:List Bool) (hr:w .selectedRow=row):\n    Runs program (normalizeTime row) (.local .normalize) (data children w) (.local .inner)\n      (data children (Function.update w .selectedRow (normalized row))):=by\n  have h0:=peek_run (.local .normalize) (.local .emptyRow) (.local .inner) (.local .inner) .selectedRow children w row rfl hr\n  cases row with\n  | nil=>\n    have h1:=push_run (.local .emptyRow) (.local .inner) .selectedRow false children w rfl\n    rw [hr] at h1\n    exact join h0 h1\n  | cons b bs=>\n    have he:Function.update w .selectedRow (b::bs)=w:=by rw [←hr];exact Function.update_eq_self _ _\n    rw [show normalized (b::bs)=b::bs from rfl,he]\n    cases b <;> exact h0\n/-- Actual outer selected-row bytes, before its real missing-row normalization. -/\ndef outerBytes (children:List (List (List Bool))) (node:List Bool):List Bool:=\n  ((children.map vectorBits)[bitValue node]?).getD []\n/-- The actual normalized cache is exactly the encoded original child row or encoded empty default. -/\ntheorem normalized_outer (children:List (List (List Bool))) (node:List Bool):\n    normalized (outerBytes children node)=vectorBits ((children[bitValue node]?).getD []):=by\n  unfold outerBytes\n  rw [List.getElem?_map]\n  cases h:children[bitValue node]? with\n  | none=>rfl\n  | some row=>cases row <;> rfl\n/-- Exact actual outer scan, physical EOF normalization and inner scan elapsed count. -/\ndef time (children:List (List (List Bool))) (r:Row):Nat:=\n  (IX.timeBound (children.map vectorBits) (r 0)+1)+normalizeTime (outerBytes children (r 0))+\n    (IX.timeBound ((children[bitValue (r 0)]?).getD []) (r 1)+1)\n/-- Complete real node/index acquisition from ONLY actual nested child bytes and actual parsed binary fields. -/\ntheorem read_run (children:List (List (List Bool))) (original reader:List Bool) (r:Row) (history buffer out:List Bool):\n    Runs program (time children r) (.local .outer)\n      (data (childTape children) (words original reader r [] [] [] history buffer out)) (.local (.frame 0))\n      (data (childTape children) (words original reader r\n        (vectorBits ((children[bitValue (r 0)]?).getD [])) (selectedChild children (r 0) (r 1)) [] history buffer out)):=by\n  have h0:=index_call false (childTape children) (words original reader r [] [] [] history buffer out) (children.map vectorBits) rfl rfl\n  change Runs program (IX.timeBound (children.map vectorBits) (r 0)+1) (.local .outer)\n    (data (childTape children) (words original reader r [] [] [] history buffer out)) (.local .normalize)\n    (data (childTape children) (Function.update (words original reader r [] [] [] history buffer out) .selectedRow (outerBytes children (r 0)))) at h0\n  rw [update_row] at h0\n  have h1:=normalize_run (childTape children) (words original reader r (outerBytes children (r 0)) [] [] history buffer out) (outerBytes children (r 0)) rfl\n  rw [update_row,normalized_outer] at h1\n  have h2:=index_call true (childTape children)\n    (words original reader r (vectorBits ((children[bitValue (r 0)]?).getD [])) [] [] history buffer out)\n    ((children[bitValue (r 0)]?).getD []) rfl rfl\n  change Runs program (IX.timeBound ((children[bitValue (r 0)]?).getD []) (r 1)+1) (.local .inner)\n    (data (childTape children) (words original reader r (vectorBits ((children[bitValue (r 0)]?).getD [])) [] [] history buffer out))\n    (.local (.frame 0)) (data (childTape children) (Function.update\n      (words original reader r (vectorBits ((children[bitValue (r 0)]?).getD [])) [] [] history buffer out) .child (selectedChild children (r 0) (r 1)))) at h2\n  rw [update_child] at h2\n  exact join (join h0 h1) h2\nend RiemannGaussian.SemiprimeD1StackRecoveryEntriesRead\n","RiemannGaussian.SemiprimeD1StackRecoveryFinishCorrection":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishMoves\nimport RiemannGaussian.SemiprimeD1StackRecoveryFinishOperators\n/-! # Actual Newton correction-cache scalar sum\nBoth operands are physically copied, the real modular scalar adder is called,\nthe previous correction cache is drained, and the real output is moved/drained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 65536\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryFinishCorrection\nopen SemiprimeD1StackRecoveryFinish SemiprimeD1StackRecoveryFinishState\nopen SemiprimeD1StackRecoveryFinishPrimitives SemiprimeD1StackRecoveryFinishMoves\nopen SemiprimeD1StackRecoveryFinishProjection SemiprimeD1StackRecoveryFinishOperators SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\"=>Label.local\n/-- Actual real scalar-adder operands/result are empty before their paid preparation. -/\nstructure Clean (v:Values):Prop where\n  /-- Actual left operand is empty. -/\n  left:v .addLeft=[]\n  /-- Actual right operand is empty. -/\n  right:v .addRight=[]\n  /-- Actual output word is empty. -/\n  output:v .addOutput=[]\n/-- Exact real correction-cache word. -/\ndef word (v:Values):List Bool:=\n  (SemiprimeD1JetScalarBits.add (v .width).length (v (.aux .two)) (v (.aux .opposite))).bits\n/-- Actual whole-controller result clears all real adder work and replaces only the correction cache. -/\ndef result (v:Values):Values:=Function.update v (.aux .correction) (word v)\n/-- Actual two preserving copies, real scalar adder, cache drain and output move, with all real returns. -/\ndef time (v:Values):Nat:=\n  (5*(v (.aux .two)).length+4)+(5*(v (.aux .opposite)).length+4)+\n    (AE.totalTime (v (.aux .two)) (v (.aux .opposite)) (v .width)+1)+\n    ((v (.aux .correction)).length+3)+(6*(word v).length+7)\n/-- The SAME fixed Newton source actually writes the exact canonical scalar correction and physically clears all work. -/\ntheorem source_run (v:Values) (hc:Clean v) (hs:v (.aux .copyScratch)=[]):\n    Runs program (time v) (ctl .addLeft) (data v) (ctl .roundUpdate) (data (result v)):=by\n  let v1:=Function.update v .addLeft (v (.aux .two))\n  let v2:=Function.update v1 .addRight (v (.aux .opposite))\n  let v3:=Function.update v .addOutput (word v)\n  let v4:=Function.update v3 (.aux .correction) []\n  have h0:=copy_view .addLeft (ctl .addLeft) (ctl .addRight) v rfl hs\n  simp only [copyFrom,copyTo,hc.left,List.append_nil] at h0\n  change Runs program (5*(v (.aux .two)).length+4) _ _ _ (data v1) at h0\n  have hs1:v1 (.aux .copyScratch)=[]:=by simp [v1,hs]\n  have h1:=copy_view .addRight (ctl .addRight) (ctl .add) v1 rfl hs1\n  have ho1:v1 (.aux .opposite)=v (.aux .opposite):=rfl\n  have hr1:v1 .addRight=[]:=by simp [v1,hc.right]\n  simp only [copyFrom,copyTo,ho1,hr1,List.append_nil] at h1\n  change Runs program (5*(v (.aux .opposite)).length+4) _ _ _ (data v2) at h1\n  have h2:=add_call (ctl .add) (ctl .clearCorrection) v2 rfl (by simp [v2,v1,hc.output])\n  have hword:addWord v2=word v:=by simp [addWord,AE.result,word,v2,v1]\n  have htime:addTime v2=AE.totalTime (v (.aux .two)) (v (.aux .opposite)) (v .width)+1:=by\n    simp [addTime,v2,v1]\n  rw [hword,htime] at h2\n  have he2:added v2 (word v)=v3:=by\n    funext s\n    cases s with\n    | addLeft=>simp [added,v2,v1,v3,hc.left]\n    | addRight=>simp [added,v2,v1,v3,hc.right]\n    | _=>rfl\n  rw [he2] at h2\n  have h3:=drain_call (ctl .clearCorrection) (ctl .saveCorrection) (.aux .correction) v3 rfl\n  have hv3:v3 (.aux .correction)=v (.aux .correction):=rfl\n  rw [hv3] at h3\n  have hs4:v4 (.aux .copyScratch)=[]:=by simp [v4,v3,hs]\n  have h4:=move_call .correction (ctl .saveCorrection) (ctl .roundUpdate) v4 rfl hs4\n  change Runs program (6*(v4 .addOutput).length+7) _ _ _ _ at h4\n  have ho4:v4 .addOutput=word v:=by simp [v4,v3]\n  rw [ho4] at h4\n  have he4:moved v4 .correction=result v:=by\n    funext s\n    cases s with\n    | aux a=>cases a <;> simp [moved,v4,v3,moveFrom,moveTo,result]\n    | _=>simp [moved,v4,v3,moveFrom,moveTo,result,hc.output]\n  rw [he4] at h4\n  exact join (join (join (join h0 h1) h2) h3) h4\nend RiemannGaussian.SemiprimeD1StackRecoveryFinishCorrection\n","RiemannGaussian.SemiprimeD1StackRecoveryGridEnvelope":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridStageBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridResource\n/-! # Fixed numerical envelopes for actual grid stage clocks -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridEnvelope\nnamespace S\nexport SemiprimeD1StackRecoveryGridStageBounds (siteCap powerCap)\nend S\n/-- The cubic physical-word envelope and sixth-power arithmetic width are both charged to the original paid resource. -/\ntheorem sum_le (r b l:Nat) (hr:1≤r) (hb:b≤2*r) (hl:l≤2*10^9*r^3) :\n    104*l+b^6+1≤10^12*r^6:=by\n  have hp: r^3≤r^6:=Nat.pow_le_pow_right hr (by decide:3≤6)\n  have hp0:1≤r^6:=Nat.one_le_pow 6 _ hr\n  have hb6:=Nat.pow_le_pow_left hb 6\n  rw [mul_pow] at hb6\n  norm_num1 at hb6 ⊢\n  omega\n/-- Each same-trace actual normalized/fitted operation has a fixed sixth-degree cap. -/\ntheorem site_le (r b l:Nat) (hr:1≤r) (hb:b≤2*r) (hl:l≤2*10^9*r^3) :\n    S.siteCap b l≤10^49*r^6:=by\n  have h:=sum_le r b l hr hb hl\n  unfold S.siteCap\n  calc\n    _≤10^36*(10^12*r^6):=Nat.mul_le_mul_left _ h\n    _≤_:=by norm_num1;omega\n/-- Each actual acquired-count power loop has a fixed seventh-degree cap, paying count VALUE. -/\ntheorem power_le (r b l m:Nat) (hr:1≤r) (hb:b≤2*r) (hl:l≤10^9*r^3) (hm:m≤3*r) :\n    S.powerCap m b l≤10^53*r^7:=by\n  have h0:=sum_le r b l hr hb (by omega)\n  have hs:l+b^6+1≤10^12*r^6:=by omega\n  have hm0:m+2≤5*r:=by omega\n  have hp:=Nat.mul_le_mul hm0 hs\n  unfold S.powerCap\n  have he:(5*r)*(10^12*r^6)=5*10^12*r^7:=by ring\n  rw [he] at hp\n  calc\n    _=10^40*((m+2)*(l+b^6+1)):=by ring\n    _≤10^40*(5*10^12*r^7):=Nat.mul_le_mul_left _ hp\n    _≤_:=by norm_num1;omega\n/-- Every repeated slope frame newly emitted in a row fits the global physical-word envelope. -/\ntheorem frame_bytes_le (r w m:Nat) (hr:1≤r) (hw:w≤r) (hm:m≤3*r) :\n    m*(4*w+5)≤10^9*r^3:=by\n  have h0:4*w+5≤9*r:=by omega\n  have h1:=Nat.mul_le_mul hm h0\n  have h2:r^2≤r^3:=Nat.pow_le_pow_right hr (by decide:2≤3)\n  norm_num1\n  nlinarith\n/-- The whole actual row-body clock is bounded from physical source widths, acquired multiplicity and emitted frame bytes. -/\ntheorem work_le (r h u order w m b l:Nat) (hr:1≤r) (hh:h≤3*r) (hu:u≤r) (ho:order≤r)\n    (hw:w≤r) (hm:m≤3*r) (hb:b≤2*r) (hl:l=10^9*r^3) :\n    100*(h+u+order+1)^2+5*S.siteCap b l+2*S.powerCap m b l+\n      100*(m+1)*(w+1)+2*S.siteCap b (2*l)+3000*(2*l+1)≤10^54*r^8:=by\n  have hs:=site_le r b l hr hb (by omega)\n  have hs2:=site_le r b (2*l) hr hb (by omega)\n  have hp:=power_le r b l m hr hb (by omega) hm\n  have hsum:h+u+order+1≤6*r:=by omega\n  have hsquare:=Nat.pow_le_pow_left hsum 2\n  have hmw:=Nat.mul_le_mul (show m+1≤4*r by omega) (show w+1≤2*r by omega)\n  have h28:r^2≤r^8:=Nat.pow_le_pow_right hr (by decide:2≤8)\n  have h38:r^3≤r^8:=Nat.pow_le_pow_right hr (by decide:3≤8)\n  have h68:r^6≤r^8:=Nat.pow_le_pow_right hr (by decide:6≤8)\n  have h78:r^7≤r^8:=Nat.pow_le_pow_right hr (by decide:7≤8)\n  have h08:1≤r^8:=Nat.one_le_pow 8 _ hr\n  rw [mul_pow] at hsquare\n  have he:(4*r)*(2*r)=8*r^2:=by ring\n  rw [he] at hmw\n  rw [hl] at hs hs2 hp ⊢\n  norm_num1 at hsquare hs hs2 hp ⊢\n  nlinarith\nend RiemannGaussian.SemiprimeD1StackRecoveryGridEnvelope\n","RiemannGaussian.SemiprimeD1StackRecoveryGridLoopMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridExecution\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridOriginalStep\n/-! # Exact legacy forward-order whole grid payload\nDescending physical execution is the original forward-list right fold. Every\nrepeat and raw padded byte agrees; no old clock field is transported.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridLoopMeaning\nnamespace Loop\nexport SemiprimeD1StackRecoveryGridLoop (iterate)\nend Loop\nnamespace Old\nexport SemiprimeD1StackRecoveryGridOriginalStep (loop payload step_original)\nexport SemiprimeD1RecoveryGridBits (acquire)\nexport SemiprimeD1RecoveryScalarRun (indices_value)\nexport SemiprimeD1RecoveryWeightRun (geometry_size)\nend Old\nnamespace Dec\nexport SemiprimeD1StackRecoveryGridDecrement (difference difference_value)\nexport SemiprimeD1StackRecoveryGridLoopPrimitives (difference_width)\nend Dec\n/-- Exact legacy list order: physical q=count−1 down to0 realizes the original forward range right fold. -/\ntheorem iterate_original (a M u selected count:Nat) (t q width:List Bool) (qs:List Nat)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected) (hselected:selected<2^(a+1))\n    (hc:count≤2^(a+1)) (hl:q.length=a+2) (hv:SemiprimeBitArithmetic.bitValue q=count-1) :\n    Loop.iterate a M u t width count q (Old.loop a M u selected width qs)=\n      Old.loop a M u selected width (List.range count++qs):=by\n  induction count generalizing q qs with\n  | zero=>rfl\n  | succ n ih=>\n    have hq:SemiprimeBitArithmetic.bitValue q=n:=by omega\n    have hn:n<2^(a+1):=by omega\n    rw [Loop.iterate,Old.step_original a M u selected n t q width qs ht hselected hq hl hn]\n    cases n with\n    | zero=>rfl\n    | succ n=>\n      have hp:0<SemiprimeBitArithmetic.bitValue q:=by omega\n      have hl':(Dec.difference q).length=a+2:=Dec.difference_width a q hl\n      have hv':SemiprimeBitArithmetic.bitValue (Dec.difference q)=(n+1)-1:=by\n        rw [Dec.difference_value q hp]\n        omega\n      rw [ih (Dec.difference q) ((n+1)::qs) (by omega) hl' hv']\n      simp only [List.range_succ,List.append_assoc,List.cons_append,List.nil_append]\n/-- All actual original five-input payload bytes equal the full original range fold. -/\ntheorem payload_original (a M u selected:Nat) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected) (hs:selected<2^(a+1)) :\n    SemiprimeD1StackRecoveryGridExecution.payload a M u t width=\n      Old.loop a M u selected width (List.range (2^(a+1))):=by\n  have hl: (SemiprimeD1StackRecoveryGridExecution.firstWord a).length=a+2:=\n    SemiprimeD1StackRecoveryGridFront.q_width a M u t width\n  have hv:SemiprimeBitArithmetic.bitValue (SemiprimeD1StackRecoveryGridExecution.firstWord a)=2^(a+1)-1:=\n    SemiprimeD1StackRecoveryGridFront.q_value a M u t width\n  have h:=iterate_original a M u selected (2^(a+1)) t (SemiprimeD1StackRecoveryGridExecution.firstWord a) width [] ht hs le_rfl hl hv\n  have hone:Old.loop a M u selected width []=SemiprimeD1StackRecoveryGridModel.one:=rfl\n  rw [hone] at h\n  simpa only [SemiprimeD1StackRecoveryGridExecution.payload,List.append_nil] using h\n/-- Actual payload equals the authoritative acquire report's three grid fields for every original finite index and raw binary padding. -/\ntheorem acquire_payload (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) :\n    SemiprimeD1StackRecoveryGridExecution.payload a M u t width=\n      Old.payload (Old.acquire width a M u selected).grid:=by\n  rw [payload_original a M u selected.val t width ht selected.isLt]\n  change Old.loop a M u selected.val width (List.range (2^(a+1)))=\n    Old.payload (SemiprimeD1RecoveryGridBits.loop width a (SemiprimeD1TaperedLoss.height M u) u selected.val\n      (SemiprimeD1RecoveryWeightRun.geometry a selected.val)\n      (SemiprimeD1StackRecoveryGridModel.center a width) (SemiprimeD1StackRecoveryGridModel.alpha a width)\n      (SemiprimeD1RecoveryGridBits.index a selected.val).word\n      (SemiprimeD1RecoveryScalarRun.indices (SemiprimeD1RecoveryWeightRun.geometry a selected.val).size).value)\n  rw [Old.indices_value,Old.geometry_size]\n  rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryGridLoopMeaning\n","RiemannGaussian.SemiprimeD1StackRecoveryGridOperationInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridCalls\n/-! # Four real operand copies before every grid rational operation\nCopies finish before any aliased destination register is erased. The fixed\noperation site chooses only actual source/destination addresses, never values.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridOperationInput\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackProcedureTrace\n/-- Real operation bank with only the actual supplied W template retained. -/\ndef emptyRational (width:List Bool) :R.Stack→List Bool:=SemiprimeD1StackRationalOperation.input [] [] [] [] width\n/-- Literal four-front-field update, corresponding exactly to the four executed preserving copies. -/\ndef filled (width ls ld rs rd:List Bool) :R.Stack→List Bool:=\n  Function.update (Function.update (Function.update (Function.update (emptyRational width)\n    (SemiprimeD1StackRationalOperation.aux .leftSigned) ls) (SemiprimeD1StackRationalOperation.aux .leftDen) ld)\n    (SemiprimeD1StackRationalOperation.aux .rightSigned) rs) (SemiprimeD1StackRationalOperation.aux .rightDen) rd\n/-- The actual four writes form EXACTLY the sealed R36 source's honest five-tape input bank. -/\ntheorem filled_input (width ls ld rs rd:List Bool) :\n    filled width ls ld rs rd=SemiprimeD1StackRationalOperation.input ls ld rs rd width:=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rcases k with k|k\n      · rcases k with k|k <;> cases k <;> rfl\n      · cases k <;> rfl\n    · cases k <;> rfl\n  · rcases k with k|k\n    · rcases k with k|k\n      · fin_cases k <;> rfl\n      · cases k <;> rfl\n    · cases k <;> rfl\n/-- Four actual preserving copies include all input bytes, restoration loops and real caller returns. -/\ndef inputsTime (ls ld rs rd:List Bool) :Nat:=5*(ls.length+ld.length+rs.length+rd.length)+16\n/-- Actual cached operands initialize R36 before an aliased output register may be changed. -/\ntheorem inputs_run (site:Site) (w:Words) (width ls ld rs rd:List Bool)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hls:w.registers (operand site false,false)=ls) (hld:w.registers (operand site false,true)=ld)\n    (hrs:w.registers (operand site true,false)=rs) (hrd:w.registers (operand site true,true)=rd) :\n    Runs program (inputsTime ls ld rs rd) (.operation site (.copyInput false false)) (bank w)\n      (.operation site .call) (bank {w with rational:=SemiprimeD1StackRationalOperation.input ls ld rs rd width}):=by\n  let rls:=SemiprimeD1StackRationalOperation.aux .leftSigned\n  let rld:=SemiprimeD1StackRationalOperation.aux .leftDen\n  let rrs:=SemiprimeD1StackRationalOperation.aux .rightSigned\n  let rrd:=SemiprimeD1StackRationalOperation.aux .rightDen\n  let w1:Words:={w with rational:=Function.update w.rational rls ls}\n  let w2:Words:={w1 with rational:=Function.update w1.rational rld ld}\n  let w3:Words:={w2 with rational:=Function.update w2.rational rrs rs}\n  let w4:Words:={w3 with rational:=Function.update w3.rational rrd rd}\n  have hz0:bank w (copyTarget (.operationInput site false false))=[]:=by\n    change w.rational rls=[]\n    rw [hr]\n    rfl\n  have h0:=PTrace.copy_call (.operationInput site false false) (.operation site (.copyInput false false))\n    (.operation site (.copyInput false true)) rfl (bank w) ls [] hls hz0 hs\n  change Runs _ _ _ _ _ (Function.update (bank w) (rationalStack rls) (ls++[])) at h0\n  rw [List.append_nil,update_rational] at h0\n  have hz1:bank w1 (copyTarget (.operationInput site false true))=[]:=by\n    change Function.update w.rational rls ls rld=[]\n    rw [hr]\n    rfl\n  have h1:=PTrace.copy_call (.operationInput site false true) (.operation site (.copyInput false true))\n    (.operation site (.copyInput true false)) rfl (bank w1) ld [] hld hz1 hs\n  change Runs _ _ _ _ _ (Function.update (bank w1) (rationalStack rld) (ld++[])) at h1\n  rw [List.append_nil,update_rational] at h1\n  have hz2:bank w2 (copyTarget (.operationInput site true false))=[]:=by\n    change Function.update (Function.update w.rational rls ls) rld ld rrs=[]\n    rw [hr]\n    rfl\n  have h2:=PTrace.copy_call (.operationInput site true false) (.operation site (.copyInput true false))\n    (.operation site (.copyInput true true)) rfl (bank w2) rs [] hrs hz2 hs\n  change Runs _ _ _ _ _ (Function.update (bank w2) (rationalStack rrs) (rs++[])) at h2\n  rw [List.append_nil,update_rational] at h2\n  have hz3:bank w3 (copyTarget (.operationInput site true true))=[]:=by\n    change Function.update (Function.update (Function.update w.rational rls ls) rld ld) rrs rs rrd=[]\n    rw [hr]\n    rfl\n  have h3:=PTrace.copy_call (.operationInput site true true) (.operation site (.copyInput true true))\n    (.operation site .call) rfl (bank w3) rd [] hrd hz3 hs\n  change Runs _ _ _ _ _ (Function.update (bank w3) (rationalStack rrd) (rd++[])) at h3\n  rw [List.append_nil,update_rational] at h3\n  have hw:w4={w with rational:=SemiprimeD1StackRationalOperation.input ls ld rs rd width}:=by\n    change {w with rational:=Function.update (Function.update (Function.update (Function.update w.rational rls ls) rld ld) rrs rs) rrd rd}=_\n    rw [hr]\n    change {w with rational:=filled width ls ld rs rd}=_\n    rw [filled_input]\n  have h:=PTrace.join (PTrace.join (PTrace.join h0 h1) h2) h3\n  change Runs program _ _ _ _ (bank w4) at h\n  rw [hw] at h\n  convert h using 1\n  unfold inputsTime\n  omega\nend RiemannGaussian.SemiprimeD1StackRecoveryGridOperationInput\n","RiemannGaussian.SemiprimeD1StackRecoveryGridPower":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridPowerLoop\n/-! # Complete internal actual power used by the whole original grid source\nThe only runtime exponent is the physically copied actual marker tape. The\nwhole-grid caller acquires it from originala or its actual computedm. Zero\ncount returns the exact literal oneWord even at zero rational width.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridPower\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackRecoveryGridRegisters SemiprimeD1StackRecoveryGridOperationInput\nopen SemiprimeD1StackRecoveryGridPowerSeed SemiprimeD1StackRecoveryGridPowerLoop\nopen SemiprimeD1StackProcedureTrace\n/-- Own whole helper clock includes both real old-accumulator drains, three literal one cells, actual counter reads and all R36 calls. -/\ndef runBound (part:PowerSite) (width:List Bool) (x:SemiprimeRationalBits.RationalWord) (n:Nat) (w:Words) :Nat:=\n  seedTime part w+loopTime part width x 0 n (putReg w (powerDestination part) SemiprimeJetBits.oneWord)\n/-- Actual internal whole power: every fitted multiplication consumes the actual counter and preserves the exact original operand orientation. -/\ntheorem power_run (part:PowerSite) (width:List Bool) (x:SemiprimeRationalBits.RationalWord) (n:Nat) (w:Words)\n    (hr:w.rational=emptyRational width) (hs:w.auxiliary .copyScratch=[])\n    (hc:w.auxiliary .powerTodo=List.replicate n true)\n    (hx:w.registers (powerBase part,false)=signed x) (hxd:w.registers (powerBase part,true)=x.denominator) :\n    ∃q ≤ runBound part width x n w,Runs program q (.power part .clearSigned) (bank w) (.power part .done)\n      (bank (finish w part (SemiprimeD1RecoveryPowerBits.power width x n).word)):=by\n  let seeded:=putReg w (powerDestination part) SemiprimeJetBits.oneWord\n  have h0:=seed_run part w\n  have hr1:seeded.rational=emptyRational width:=hr\n  have hs1:seeded.auxiliary .copyScratch=[]:=hs\n  have hc1:seeded.auxiliary .powerTodo=List.replicate n true:=hc\n  have ha1:seeded.registers (powerDestination part,false)=signed (SemiprimeD1RecoveryPowerBits.power width x 0).word:=\n    (putReg_fields w (powerDestination part) SemiprimeJetBits.oneWord).1\n  have had1:seeded.registers (powerDestination part,true)=(SemiprimeD1RecoveryPowerBits.power width x 0).word.denominator:=\n    (putReg_fields w (powerDestination part) SemiprimeJetBits.oneWord).2\n  have hx1:seeded.registers (powerBase part,false)=signed x:=\n    (power_base_retained w part SemiprimeJetBits.oneWord false).trans hx\n  have hxd1:seeded.registers (powerBase part,true)=x.denominator:=\n    (power_base_retained w part SemiprimeJetBits.oneWord true).trans hxd\n  obtain ⟨q,hq,h1⟩:=loop_run part width x 0 n seeded hr1 hs1 hc1 ha1 had1 hx1 hxd1\n  change Runs program q _ _ _ (bank (finish (putReg w (powerDestination part) SemiprimeJetBits.oneWord)\n    part (SemiprimeD1RecoveryPowerBits.power width x (0+n)).word)) at h1\n  rw [finish_putReg,Nat.zero_add] at h1\n  refine ⟨seedTime part w+q,?_,PTrace.join h0 h1⟩\n  exact Nat.add_le_add_left hq (seedTime part w)\nend RiemannGaussian.SemiprimeD1StackRecoveryGridPower\n","RiemannGaussian.SemiprimeD1StackRecoveryGridPowerBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridOperationBounds\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridWordCaps\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridPowerSource\n/-! # Own whole physical power clocks from semantic cache widths\nEach loop iteration uses W-fitted cache words or the literal one seed. Neither\noperand lengths nor the number of iterations are inferred from elapsed time.\nThe actual copied counter markers and every real return are explicitly paid.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridPowerBounds\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView\nnamespace Caps\nexport SemiprimeD1StackRecoveryGridWordCaps (Registers Data auxiliary_data auxiliary_registers put_registers put_data power_width mass_le)\nend Caps\nnamespace PLoop\nexport SemiprimeD1StackRecoveryGridPowerLoop (loopTime afterPop afterStep)\nend PLoop\nnamespace Whole\nexport SemiprimeD1StackRecoveryGridPower (runBound)\nexport SemiprimeD1StackRecoveryGridPowerSeed (seedTime)\nend Whole\nnamespace Source\nexport SemiprimeD1StackRecoveryGridPowerSource (runBound exponent ready)\nend Source\nnamespace Op\nexport SemiprimeD1StackRecoveryGridOperation (timeBound)\nexport SemiprimeD1StackRecoveryGridOperationBounds (time_le)\nend Op\n/-- One actual counter-read/whole-operation/real-return envelope, with a fixed coefficient before all inputs. -/\ndef cap (B L:Nat) :Nat:=10^38*(L+B^6+1)\n/-- Actual operation cleanup charges retained foreign words additively, while source operands retain their semantic widths. -/\ntheorem step_cap (q B L:Nat) (hq:q≤10^35*(104*L+B^6+1)) :q+3≤ cap B L:=by\n  unfold cap\n  omega\n/-- Pure arithmetic composition for the same actual loop, abstracting proof-side payload terms only. -/\ntheorem recursion_cap (q previous C n:Nat) (hq:q+3≤ C) (hp:previous≤ n*C+1) :\n    1+(q+2)+previous≤(n+1)*C+1:=by\n  simp only [Nat.add_mul,Nat.one_mul]\n  omega\nattribute [local irreducible] Op.timeBound cap\n/-- Every physical power iteration has a uniform own cap from W, actual cache widths and retained words. -/\ntheorem loop_le (part:PowerSite) (width:List Bool) (x:SemiprimeRationalBits.RationalWord) (k n:Nat) (w:Words) (B L:Nat)\n    (hW:width.length+2≤ B) (hBL:B≤ L) (hx:x.numerator.magnitude.length≤ B) (hd:x.denominator.length≤ B)\n    (hn:n≤ L) (hr:Caps.Registers w B) (hw:Caps.Data w L) :\n    PLoop.loopTime part width x k n w≤ n*cap B L+1:=by\n  induction n generalizing k w with\n  | zero=>simp only [PLoop.loopTime,Nat.zero_mul,Nat.zero_add,le_refl]\n  | succ n ih=>\n    let popped:=PLoop.afterPop w n\n    have hpR:Caps.Registers popped B:=hr\n    have hpD:Caps.Data popped L:=Caps.auxiliary_data w .powerTodo (List.replicate n true) L hw\n      (by simp only [List.length_replicate];omega)\n    have hpMass:=Caps.mass_le popped L hpD\n    have hacc:=Caps.power_width width x k B hW\n    let acc:=(SemiprimeD1RecoveryPowerBits.power width x k).word\n    have hOp:=Op.time_le (.power part) popped acc.numerator.negative acc.numerator.magnitude acc.denominator\n      x.numerator.negative x.numerator.magnitude x.denominator width B (by omega) (by exact Nat.le_trans (Nat.le_add_right _ _) hacc.1)\n      hacc.2 hx hd (by omega) (hpR _ false) (hpR _ true)\n    have hOp':Op.timeBound (.power part) popped acc.numerator.negative acc.numerator.magnitude acc.denominator\n        x.numerator.negative x.numerator.magnitude x.denominator width≤10^35*(104*L+B^6+1):=\n      hOp.trans (Nat.mul_le_mul_left _ (by omega))\n    have hstep:=step_cap _ B L hOp'\n    have hnxt:=Caps.power_width width x (k+1) B hW\n    let next:=PLoop.afterStep part width x k n w\n    have hnR:Caps.Registers next B:=Caps.put_registers popped (powerDestination part)\n      (SemiprimeD1RecoveryPowerBits.power width x (k+1)).word B hpR hnxt.1 hnxt.2\n    have hnD:Caps.Data next L:=Caps.put_data popped (powerDestination part)\n      (SemiprimeD1RecoveryPowerBits.power width x (k+1)).word L hpD (hnxt.1.trans hBL) (hnxt.2.trans hBL)\n    have hnext:=ih (k+1) next (by omega) hnR hnD\n    change 1+(Op.timeBound (.power part) popped acc.numerator.negative acc.numerator.magnitude acc.denominator\n      x.numerator.negative x.numerator.magnitude x.denominator width+2)+PLoop.loopTime part width x (k+1) n next≤(n+1)*cap B L+1\n    exact recursion_cap _ _ _ n hstep hnext\n/-- The two old-accumulator drains and three literal seed pushes are charged before any multiply. -/\ntheorem seed_le (part:PowerSite) (w:Words) (B:Nat) (hr:Caps.Registers w B) :Whole.seedTime part w≤2*B+5:=by\n  have hn:=hr (powerDestination part) false\n  have hd:=hr (powerDestination part) true\n  unfold Whole.seedTime\n  omega\n/-- The positive fixed physical resource envelope absorbs the literal seed and both EOF branches. -/\ntheorem seed_cap (B L:Nat) (hBL:B≤ L) :2*B+6≤ cap B L:=by\n  unfold cap\n  omega\n/-- The actual complete helper, including literal n0 oneWord, is paid from the same source-word/marker envelope. -/\ntheorem helper_le (part:PowerSite) (width:List Bool) (x:SemiprimeRationalBits.RationalWord) (n:Nat) (w:Words) (B L:Nat)\n    (hW:width.length+2≤ B) (hBL:B≤ L) (hx:x.numerator.magnitude.length≤ B) (hd:x.denominator.length≤ B)\n    (hn:n≤ L) (hr:Caps.Registers w B) (hw:Caps.Data w L) :Whole.runBound part width x n w≤(n+1)*cap B L:=by\n  let seeded:=putReg w (powerDestination part) SemiprimeJetBits.oneWord\n  have hsR:Caps.Registers seeded B:=Caps.put_registers w _ SemiprimeJetBits.oneWord B hr (by change 2≤ B;omega) (by change 1≤ B;omega)\n  have hsD:Caps.Data seeded L:=Caps.put_data w _ SemiprimeJetBits.oneWord L hw (by change 2≤ L;omega) (by change 1≤ L;omega)\n  have hloop:=loop_le part width x 0 n seeded B L hW hBL hx hd hn hsR hsD\n  have hseed:=seed_le part w B hr\n  have hcap:=seed_cap B L hBL\n  unfold Whole.runBound\n  change Whole.seedTime part w+PLoop.loopTime part width x 0 n seeded≤(n+1)*cap B L\n  rw [Nat.add_mul,Nat.one_mul]\n  omega\n/-- Exact finite alpha selector contributes only one physically pushed count marker. -/\ntheorem exponent_le (part:PowerSite) (n:Nat) :Source.exponent part n≤ n+1:=by\n  unfold Source.exponent\n  split <;> omega\n/-- Pure actual-copy/call/return accounting, with no payload evaluation in the arithmetic proof. -/\ntheorem outer_cap (Q n e delta S:Nat) (hQ:Q≤(e+1)*(10^38*S)) (he:e≤ n+1) (hd:delta≤1) (hS:1≤ S) :\n    (5*n+4)+delta+Q+2≤10^40*(n+2)*S:=by\n  have h1:(e+1)*S≤(n+2)*S:=Nat.mul_le_mul_right S (by omega)\n  have h2:n+2≤(n+2)*S:=by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (n+2) hS\n  norm_num1 at hQ ⊢\n  nlinarith\n/-- Whole actual power-source call pays the acquired counter copy, literal alpha marker, helper and both real return transitions. -/\ntheorem source_le (part:PowerSite) (w:Words) (width:List Bool) (x:SemiprimeRationalBits.RationalWord) (n B L:Nat)\n    (hW:width.length+2≤ B) (hBL:B≤ L) (hx:x.numerator.magnitude.length≤ B) (hd:x.denominator.length≤ B)\n    (hn:n+1≤ L) (hr:Caps.Registers w B) (hw:Caps.Data w L) :\n    Source.runBound part w width x n≤10^40*(n+2)*(L+B^6+1):=by\n  have he:=exponent_le part n\n  have hreadyR:Caps.Registers (Source.ready part w n) B:=hr\n  have hreadyD:Caps.Data (Source.ready part w n) L:=Caps.auxiliary_data w .powerTodo\n    (List.replicate (Source.exponent part n) true) L hw (by simp only [List.length_replicate];omega)\n  have h:=helper_le part width x (Source.exponent part n) (Source.ready part w n) B L hW hBL hx hd (by omega) hreadyR hreadyD\n  have hdlt:(if part=.alpha then 1 else 0)≤1:=by split <;> omega\n  unfold Source.runBound\n  have hcap:cap B L=10^38*(L+B^6+1):=by unfold cap;rfl\n  rw [hcap] at h\n  exact outer_cap _ n _ _ _ h he hdlt (by omega)\nend RiemannGaussian.SemiprimeD1StackRecoveryGridPowerBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryGridRowStart":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridGeometry\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridNode\n/-! # Actual row-marker consumption, true geometry and copied signed index -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridRowStart\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackProcedureTrace\nnamespace Geometry\nexport SemiprimeD1StackRecoveryGridGeometry (result geometry_run)\nend Geometry\n/-- Actual row starts by consuming its physical TRUE marker, not by testing a supplied row index/count. -/\ndef popped (w:Words) (n:Nat) :Words:={w with auxiliary:=Function.update w.auxiliary .todo (List.replicate n true)}\n/-- Complete true geometry acquired for the actual current binary q after the row marker is consumed. -/\ndef result (w:Words) (a:Nat) (q:List Bool) (n:Nat) :Words:=\n  Geometry.result (popped w n) (List.replicate a true) q\n/-- Own actual row-entry geometry/point-drain clock. -/\ndef runBound (a:Nat) (q:List Bool) :Nat:=1+\n  (SemiprimeD1StackPhaseGeometryComponents.runBound (List.replicate a true) q+1+\n    (SemiprimeD1StackPhaseGeometryArithmetic.magnitude a q).length+1)\n/-- One genuine row-marker pop followed by real true-geometry acquisition and actual shared-point cleanup. -/\ntheorem row_start_run (w:Words) (a n:Nat) (q:List Bool)\n    (ht:w.auxiliary .todo=List.replicate (n+1) true)\n    (ha:w.auxiliary .originalA=List.replicate a true) (hq:w.auxiliary .q=q)\n    (hg:∀k,w.geometry k=[]) (hr:∀k,w.rational (SemiprimeD1StackRationalOperation.adderStack k)=[]) :\n    ∃t≤runBound a q,Runs program t (.local .row) (bank w) (.local .center) (bank (result w a q n)):=by\n  have h0:=PTrace.pop_run (.local .row) (.local .scalarInverse) (.local .abort) (.local .rowGeometry)\n    (aux .todo) (bank w) (true::List.replicate n true) rfl (by change w.auxiliary .todo=true::List.replicate n true;simpa only [List.replicate_succ] using ht)\n  rw [update_auxiliary] at h0\n  change Runs program 1 _ _ (.local .rowGeometry) (bank (popped w n)) at h0\n  have hi:∀k,bank (popped w n) (geometryStack k)=SemiprimeD1StackPhaseGeometry.input (List.replicate a true) q k:=by\n    intro k\n    rcases k with k|k\n    · cases k <;> exact hr _\n    · cases k\n      · exact ha\n      · exact hq\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n      · exact hg _\n  obtain ⟨t,htime,h1⟩:=Geometry.geometry_run .row (popped w n) (List.replicate a true) q hi (hr .output)\n  refine ⟨1+t,?_,PTrace.join h0 h1⟩\n  unfold runBound\n  simpa only [List.length_replicate] using Nat.add_le_add_left htime 1\n/-- Actual singleton center-test bit, retained after the physical peek. -/\ntheorem center_run (w:Words) (b:Bool) (hb:w.geometry .zero=[b]) :\n    Runs program 1 (.local .center) (bank w)\n      (if b then .local (.clearTransient false 0) else .local .equalQ) (bank w):=by\n  have h:=PTrace.peek_run (.local .center) (.local .abort) (.local .equalQ) (.local (.clearTransient false 0))\n    (geometryAux .zero) (bank w) [b] rfl hb\n  cases b <;> exact h\n/-- Exact physical signed integer word acquired from the current q buffer. -/\ndef index (q:List Bool) :SemiprimeRationalBits.RationalWord:=⟨⟨false,q⟩,[true]⟩\n/-- Paid row index acquisition, with no fit against rational W and no unary expansion of q. -/\ntheorem index_run (w:Words) (q:List Bool) (hq:w.auxiliary .q=q)\n    (hs:w.auxiliary .copyScratch=[]) (hn:w.registers (.index,false)=[]) (hd:w.registers (.index,true)=[]) :\n    Runs program (5*q.length+4+2) (.local .index) (bank w) (.local .levels) (bank (putReg w .index (index q))):=by\n  let copied:Words:={w with registers:=Function.update w.registers (.index,false) q}\n  have h0:=PTrace.copy_call .index (.local .index) (.local .indexSign) rfl (bank w) q [] hq hn hs\n  change Runs program _ _ _ _ (Function.update (bank w) (reg .index false) (q++[])) at h0\n  rw [List.append_nil,update_registers _ (.index,false)] at h0\n  have h1:=PTrace.push_run (.local .indexSign) (.local .indexDen) (reg .index false) false (bank copied) rfl\n  change Runs program 1 _ _ _ (Function.update (bank copied) (reg .index false) (false::q)) at h1\n  rw [update_registers _ (.index,false)] at h1\n  let signed:Words:={copied with registers:=Function.update copied.registers (.index,false) (false::q)}\n  have h2:=PTrace.push_run (.local .indexDen) (.local .levels) (reg .index true) true (bank signed) rfl\n  change Runs program 1 _ _ _ (Function.update (bank signed) (reg .index true) (true::w.registers (.index,true))) at h2\n  rw [hd,update_registers _ (.index,true)] at h2\n  have h:=PTrace.join (PTrace.join h0 h1) h2\n  dsimp only [copied,signed] at h\n  rw [Function.update_idem] at h\n  change Runs program _ _ _ _ (bank (putReg w .index (index q))) at h\n  exact h\n/-- A true fixed-width current q gives exactly the legacy original signed index bytes. -/\ntheorem index_original (a n:Nat) (q:List Bool)\n    (hl:q.length=a+2) (hv:SemiprimeBitArithmetic.bitValue q=n) (hn:n<2^(a+1)) :\n    index q=(SemiprimeD1RecoveryGridBits.index a n).word:=by\n  have hb:n<2^(a+2):=by\n    have hp:2^(a+2)=2^(a+1)*2:=by rw [show a+2=(a+1)+1 by omega,pow_succ]\n    rw [hp]\n    omega\n  have he:q=(SemiprimeEncodedRowSelection.digits (a+2) n).bits:=by\n    apply SemiprimeD1StackAssignmentOrder.word_value_injective\n    · rw [hl,SemiprimeEncodedRowSelection.digits_length]\n    · rw [hv,SemiprimeEncodedRowSelection.digits_value _ _ hb]\n  unfold index\n  rw [he]\n  rfl\nend RiemannGaussian.SemiprimeD1StackRecoveryGridRowStart\n","RiemannGaussian.SemiprimeD1StackRecoveryGridTransient":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridCleanup\n/-! # Complete physical transient-cache cleanup in the original grid fold -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridTransient\nopen SemiprimeD1StackRecoveryGrid SemiprimeD1StackRecoveryGridView SemiprimeD1StackRecoveryGridCalls\nopen SemiprimeD1StackRecoveryGridCleanup SemiprimeD1StackProcedureTrace\n/-- Exactly eight actual transient rational caches, each with both physical fields. -/\ndef caches :List Reg:=[.index,.negative,.numBase,.denBase,.numPower,.denPower,.reciprocal,.slope]\n/-- The fixed drain list is an explicit finite list of actual cache fields. -/\ntheorem role_list :roles transientRole=[reg .index false,reg .index true,reg .negative false,reg .negative true,reg .numBase false,reg .numBase true,reg .denBase false,reg .denBase true,reg .numPower false,reg .numPower true,reg .denPower false,reg .denPower true,reg .reciprocal false,reg .reciprocal true,reg .slope false,reg .slope true]:=by rfl\n/-- Fixed physical cache inventory agrees with the sixteen already compiled drain loops. -/\ntheorem mem_reg (r:Reg) (b:Bool) :reg r b∈roles transientRole↔r∈caches:=by\n  rw [role_list]\n  cases r <;> cases b <;> simp [reg,caches]\n/-- Every allocated transient role is one of those signed/denominator cache fields. -/\ntheorem role_cache (i:Fin 16) :∃r b,r∈caches ∧transientRole i=reg r b:=by\n  fin_cases i\n  · exact ⟨.index,false,by decide,rfl⟩\n  · exact ⟨.index,true,by decide,rfl⟩\n  · exact ⟨.negative,false,by decide,rfl⟩\n  · exact ⟨.negative,true,by decide,rfl⟩\n  · exact ⟨.numBase,false,by decide,rfl⟩\n  · exact ⟨.numBase,true,by decide,rfl⟩\n  · exact ⟨.denBase,false,by decide,rfl⟩\n  · exact ⟨.denBase,true,by decide,rfl⟩\n  · exact ⟨.numPower,false,by decide,rfl⟩\n  · exact ⟨.numPower,true,by decide,rfl⟩\n  · exact ⟨.denPower,false,by decide,rfl⟩\n  · exact ⟨.denPower,true,by decide,rfl⟩\n  · exact ⟨.reciprocal,false,by decide,rfl⟩\n  · exact ⟨.reciprocal,true,by decide,rfl⟩\n  · exact ⟨.slope,false,by decide,rfl⟩\n  · exact ⟨.slope,true,by decide,rfl⟩\n/-- No original, arithmetic, geometry or auxiliary role belongs to the transient-cache drain inventory. -/\ntheorem mem_iff (k:Stack) :k∈roles transientRole↔∃r b,r∈caches ∧k=reg r b:=by\n  constructor\n  · intro hk\n    obtain ⟨i,_,hi⟩:=List.mem_map.mp hk\n    obtain ⟨r,b,hr,he⟩:=role_cache i\n    exact ⟨r,b,hr,hi.symm.trans he⟩\n  · rintro ⟨r,b,hr,rfl⟩\n    exact (mem_reg r b).mpr hr\n/-- Exact stopped full bank after all sixteen actual transient drains. -/\ndef result (w:Words) :Words:=\n  {w with registers:=fun k=>if k.1∈caches then [] else w.registers k}\n/-- Entire physical cleanup preserves every external word and all retained grid/final caches. -/\ntheorem cleared_result (w:Words) :cleared transientRole (bank w) 16=bank (result w):=by\n  classical\n  funext k\n  rw [cleared_full]\n  rcases k with k|k\n  · have hn:¬Sum.inl k∈roles transientRole:=by\n      rw [mem_iff]\n      rintro ⟨r,b,_,h⟩;cases h\n    rw [ite_eq_right hn]\n    rfl\n  · rcases k with k|k\n    · have hn:¬Sum.inr (Sum.inl k)∈roles transientRole:=by\n        rw [mem_iff]\n        rintro ⟨r,b,_,h⟩;cases h\n      rw [ite_eq_right hn]\n      rfl\n    · rcases k with k|k\n      · have hn:¬Sum.inr (Sum.inr (Sum.inl k))∈roles transientRole:=by\n          rw [mem_iff]\n          rintro ⟨r,b,_,h⟩;cases h\n        rw [ite_eq_right hn]\n        rfl\n      · rcases k with k|k\n        · have hn:¬Sum.inr (Sum.inr (Sum.inr (Sum.inl k)))∈roles transientRole:=by\n            rw [mem_iff]\n            rintro ⟨r,b,_,h⟩;cases h\n          rw [ite_eq_right hn]\n          rfl\n        · rcases k with k|k\n          · rcases k with ⟨r,b⟩\n            change (if reg r b∈roles transientRole then [] else w.registers (r,b))=_\n            rw [mem_reg]\n            by_cases hh:r∈caches <;> simp only [bank,result,Sum.elim_inr,Sum.elim_inl,hh,ite_true,ite_false]\n          · have hn:¬aux k∈roles transientRole:=by\n              rw [mem_iff]\n              rintro ⟨r,b,_,h⟩;cases h\n            change (if aux k∈roles transientRole then [] else w.auxiliary k)=w.auxiliary k\n            exact ite_eq_right hn\n/-- All sixteen actual EOF drains execute before the row/final continuation; no hidden cache fields remain. -/\ntheorem transient_run (finish:Bool) (w:Words) :\n    ∃t≤16*(mass (bank w)+1),Runs program t (.local (.clearTransient finish 0)) (bank w)\n      (if finish then .local .clearFinalQ else .local .clearMultiplicity) (bank (result w)):=by\n  obtain ⟨t,ht,h⟩:=transient_cleanup finish (bank w)\n  rw [cleared_result] at h\n  exact ⟨t,ht,h⟩\nend RiemannGaussian.SemiprimeD1StackRecoveryGridTransient\n","RiemannGaussian.SemiprimeD1StackRecoveryGridValues":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryGridOriginal\nimport RiemannGaussian.SemiprimeD1RecoveryNodeBits\n/-! # Original-dimension Valid/Fits discharge for the actual whole grid source\nWidth comes from the literal original a/M polynomial, and u≤M from guard\nlineage. No operation-by-operation Fits or coefficient answer is assumed.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryGridValues\nopen SemiprimeD1StackRecoveryGrid\nnamespace Exec\nexport SemiprimeD1StackRecoveryGridExecution (result payload)\nend Exec\nnamespace E\nexport SemiprimeD1StackRecoveryGridEncoding (outputWord)\nend E\nnamespace Old\nexport SemiprimeD1RecoveryGridBits (acquire gridWidth acquire_grid_correct acquire_scalar_correct acquire_argument_correct)\nend Old\n/-- The actual original width producer supplies the whole grid's normalization/fit capacity from dimensions alone. -/\ntheorem width_sufficient (a M u:Nat) (width:List Bool) (hu:u≤M)\n    (hW:SemiprimeD1RecoveryNodeBits.width a M≤width.length) :Old.gridWidth a (SemiprimeD1TaperedLoss.height M u) u≤width.length:=\n  (SemiprimeD1RecoveryNodeBits.grid_width_le a M u hu).trans hW\n/-- Both physically acquired grid products have exact original values and positive actual binary denominators. -/\ntheorem grid_products (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (hu:u≤M)\n    (hW:SemiprimeD1RecoveryNodeBits.width a M≤width.length) :\n    let native:=SemiprimeD1RecoveryWeightRun.gridRows (SemiprimeD1RecoveryWeightRun.geometry a selected.val)\n      (SemiprimeD1TaperedLoss.height M u) u selected.val\n      (SemiprimeD1RecoveryScalarRun.indices (SemiprimeD1RecoveryWeightRun.geometry a selected.val).size).value\n    (E.outputWord (Exec.result a M u t width) .gridNum).value=(native.numerator:ℚ) ∧\n    (E.outputWord (Exec.result a M u t width) .gridDen).value=(native.denominator:ℚ) ∧\n    (E.outputWord (Exec.result a M u t width) .gridNum).Valid ∧\n    (E.outputWord (Exec.result a M u t width) .gridDen).Valid:=by\n  have h:=Old.acquire_grid_correct width a M u selected (width_sufficient a M u width hu hW)\n  dsimp only\n  rw [SemiprimeD1StackRecoveryGridOriginal.result_original a M u selected t width ht,\n    SemiprimeD1StackRecoveryGridEncoding.numerator_original a M u selected t width,SemiprimeD1StackRecoveryGridEncoding.denominator_original a M u selected t width]\n  exact ⟨h.1,h.2.1,h.2.2.2.1,h.2.2.2.2.1⟩\n/-- Every physically framed slope, including all repetitions and original forward order, is valid and has the exact original rational value. -/\ntheorem slope_values (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (hu:u≤M)\n    (hW:SemiprimeD1RecoveryNodeBits.width a M≤width.length) :\n    (Exec.payload a M u t width).slopes.map SemiprimeRationalBits.RationalWord.value=\n      (SemiprimeD1RecoveryWeightRun.gridRows (SemiprimeD1RecoveryWeightRun.geometry a selected.val)\n        (SemiprimeD1TaperedLoss.height M u) u selected.val\n        (SemiprimeD1RecoveryScalarRun.indices (SemiprimeD1RecoveryWeightRun.geometry a selected.val).size).value).slopes ∧\n    (∀x∈(Exec.payload a M u t width).slopes,x.Valid):=by\n  have h:=Old.acquire_grid_correct width a M u selected (width_sufficient a M u width hu hW)\n  rw [SemiprimeD1StackRecoveryGridLoopMeaning.acquire_payload a M u selected t width ht]\n  exact ⟨h.2.2.1,h.2.2.2.2.2.1⟩\n/-- Actual Ezero is normalized and fitted with capacity derived from the original dimensions; no raw answer or Fits sequence is supplied. -/\ntheorem scalar_value (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (hu:u≤M)\n    (hW:SemiprimeD1RecoveryNodeBits.width a M≤width.length) :\n    (E.outputWord (Exec.result a M u t width) .scalar).value=\n      SemiprimeD1JetRecoveryGrid.Ezero a (SemiprimeD1TaperedLoss.height M u) u selected.val ∧\n    (E.outputWord (Exec.result a M u t width) .scalar).Valid ∧\n    SemiprimeRationalBits.Width (E.outputWord (Exec.result a M u t width) .scalar) width.length:=by\n  rw [SemiprimeD1StackRecoveryGridOriginal.result_original a M u selected t width ht,\n    SemiprimeD1StackRecoveryGridEncoding.scalar_original a M u selected t width]\n  exact Old.acquire_scalar_correct width a M u selected (width_sufficient a M u width hu hW)\n/-- Actual local argument retains the same exact original value, valid denominator and paid fitted width. -/\ntheorem argument_value (a M u:Nat) (selected:Fin (2^(a+1))) (t width:List Bool)\n    (ht:SemiprimeBitArithmetic.bitValue t=selected.val) (hu:u≤M)\n    (hW:SemiprimeD1RecoveryNodeBits.width a M≤width.length) :\n    (E.outputWord (Exec.result a M u t width) .argument).value=SemiprimeD1WeightPrecision.argument a selected.val ∧\n    (E.outputWord (Exec.result a M u t width) .argument).Valid ∧\n    SemiprimeRationalBits.Width (E.outputWord (Exec.result a M u t width) .argument) width.length:=by\n  rw [SemiprimeD1StackRecoveryGridOriginal.result_original a M u selected t width ht,\n    SemiprimeD1StackRecoveryGridEncoding.argument_original a M u selected t width]\n  exact Old.acquire_argument_correct width a M u selected (width_sufficient a M u width hu hW)\nend RiemannGaussian.SemiprimeD1StackRecoveryGridValues\n","RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCodec":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryNodeInputs\n/-! # Exact shared rational-array bytes across actual affine, inverse and powers calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCodec\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Existing framed payloads append their actual tail without changing any signed or high-zero byte. -/\ntheorem frame_append (word xs ys : List Bool) : frame word xs++ys=frame word (xs++ys) := by\n  induction word with\n  | nil=>rfl\n  | cons b word ih=>\n    change true::b::(frame word xs++ys)=true::b::frame word (xs++ys)\n    rw [ih]\n/-- The actual old affine output ABI is EXACTLY the complete inverse input ABI, not a decoded/value-only conversion. -/\ntheorem affine_tape (words : List SemiprimeRationalBits.RationalWord) :\n    SemiprimeD1StackRecoveryAffineView.vector words=SemiprimeD1StackNormalizedInverse.tape words := rfl\n/-- A real chronological powers row has exactly the same two signed/denominator frames and TRUE tag. -/\ntheorem powers_row (word : SemiprimeRationalBits.RationalWord) (tail : List Bool) :\n    SemiprimeD1StackRecoveryPowersSpec.row word++tail=SemiprimeD1StackNormalizedInverse.row word tail := by\n  unfold SemiprimeD1StackRecoveryPowersSpec.row SemiprimeD1StackNormalizedInverse.row\n  rw [List.cons_append,frame_append,frame_append,List.nil_append]\n  rfl\n/-- The complete ACTUAL powers source output is directly readable by the already literal inverse array readers. -/\ntheorem powers_tape (words : List SemiprimeRationalBits.RationalWord) :\n    SemiprimeD1StackRecoveryPowersSpec.vector words=SemiprimeD1StackNormalizedInverse.tape words := by\n  induction words with\n  | nil=>rfl\n  | cons word words ih=>\n    change SemiprimeD1StackRecoveryPowersSpec.row word++SemiprimeD1StackRecoveryPowersSpec.vector words=\n      SemiprimeD1StackNormalizedInverse.row word (SemiprimeD1StackNormalizedInverse.tape words)\n    rw [ih,powers_row]\nend RiemannGaussian.SemiprimeD1StackRecoveryNodeInputsCodec\n","RiemannGaussian.SemiprimeD1StackRecoveryWeights":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseReadCall\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseOperationCall\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseFinalCleanup\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsIncluded\n/-! # Fixed60-role complete local-weight source from six actual words\nOnly actual inverse/power arrays, actual scalar signed numerator/denominator,\npaid unary q and paid W enter. Reused finite read/operation helpers physically\nparse and multiply/add every field; the inverse WHOLE source is never replayed.\nThe old prefixReverse role is the IMMUTABLE power tape in THIS program, and is\ntherefore excluded from THIS source's dedicated53-role final cleanup.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeights\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace I\nexport SemiprimeD1StackNormalizedInverse (Stack Label program Reg Aux ReadSite)\nend I\n/-- The original actual Ezero scalar remains retained in two additional tapes. -/\ninductive Scalar where | signed | den deriving DecidableEq,Repr\n/-- Literal two-word scalar inventory before every input. -/\ninstance :Fintype Scalar:=Fintype.ofList [.signed,.den] (by intro k;cases k <;> simp)\n/-- ALL58 reused words, including unused shadows, plus actual scalar2. -/\nabbrev Stack:=I.Stack⊕Scalar\n/-- Injective complete actual helper-bank inclusion. -/\ndef helper:I.Stack→Stack:=Sum.inl\n/-- Both actual retained scalar inputs. -/\ndef scalar:Scalar→Stack:=Sum.inr\n/-- Actual helper controller address; powers are retained at prefixReverse. -/\ndef aux (slot:I.Aux):Stack:=helper (SemiprimeD1StackNormalizedInverse.aux slot)\n/-- Actual two-field coefficient cache address. -/\ndef reg (slot:I.Reg) (den:Bool):Stack:=helper (SemiprimeD1StackNormalizedInverse.reg slot den)\n/-- Actual retained paid W, with no width shadow. -/\ndef template:Stack:=helper SemiprimeD1StackNormalizedInverse.template\n/-- Literal actual53-role inventory: all helper work EXCEPT immutable powers. -/\ndef workRole (i:Fin 53):Stack:=helper (SemiprimeD1StackNormalizedInverse.workRole ⟨i.val,by omega⟩)\n/-- Paid preserving copies initialize actual counters or final scalar/total operands. -/\ninductive Copy where | count | terms | subtract | aIndex | bIndex | scalar (den:Bool) | total (den:Bool)\n  deriving DecidableEq,Repr,Fintype\n/-- Sources are physically acquired inputs, current j/count or the actual sum. -/\ndef copySource:Copy→Stack\n  | .count|.terms|.bIndex=>aux .originalQ | .subtract=>aux .remaining | .aIndex=>aux .terms\n  | .scalar false=>scalar .signed | .scalar true=>scalar .den | .total den=>reg .acc den\n/-- Every copy destination is a distinct physically emptied counter/cache word. -/\ndef copyTarget:Copy→Stack\n  | .count=>aux .remaining | .terms=>aux .terms | .subtract=>aux .readTodo\n  | .aIndex=>aux .aIndex | .bIndex=>aux .bIndex | .scalar den=>reg .left den | .total den=>reg .right den\n/-- Real restoring-copy operands retain the original source and restore helper scratch. -/\ndef copyStack (site:Copy) (i:Fin 3):Stack:=if i=0 then copySource site else if i=1 then copyTarget site else aux .copyScratch\n/-- Final scalar product is framed directly BEFORE all coefficient fields are drained. -/\ndef frameStack (den:Bool) (i:Fin 3):Stack:=if i=0 then reg .product den else if i=1 then aux .output else aux .fieldFrameScratch\n/-- All literal outer/pair/cleanup stages are finite before the actual q/W. -/\ninductive Control where\n  | start | copyCount | outer | seedZero (den:Bool) | copyTerms | copySubtract | subtract | removeTerm\n  | copyA | predecessorA | copyB | predecessorB | terms\n  | readInverse | checkedInverse | readPower | checkedPower | product | checkedProduct | sum | checkedSum\n  | clearPair (i:Fin 6) | decrementA | decrementB | clearIndices (second:Bool)\n  | scalar (den:Bool) | total (den:Bool) | finalProduct | checkedFinalProduct\n  | frame (den:Bool) | tag | clearCoefficient (i:Fin 8) | clean (reject:Bool) (i:Fin 53)\n  | abortOutput | abortTerminal | done\n  deriving DecidableEq,Repr,Fintype\n/-- Reused finite helper labels and actual caller labels, never numerical indices. -/\ninductive Label where\n  | local (pc:Control) | helper (pc:I.Label) | copy (site:Copy) (pc:Fin 9) | frame (den:Bool) (pc:Fin 11)\n  deriving Fintype\n/-- Literal rejection cleanup entry; every retained input is preserved. -/\ndef abort:Label:=.local (.clean true 0)\n/-- ONE fixed actual source; no coefficient/array/Fits/result/clock evaluator operand. -/\ndef program:Label→C.Instruction Stack Label\n  | .local .start=>.base (.push (aux .output) false (.local .copyCount))\n  | .local .copyCount=>.call (.copy .count 0) (.local .outer)\n  | .local .outer=>.base (.pop (aux .remaining) (.local (.clean false 0)) abort (.local (.seedZero false)))\n  | .local (.seedZero den)=>.base (.push (reg .acc den) den (.local (if den then .copyTerms else .seedZero true)))\n  | .local .copyTerms=>.call (.copy .terms 0) (.local .copySubtract)\n  | .local .copySubtract=>.call (.copy .subtract 0) (.local .subtract)\n  | .local .subtract=>.base (.pop (aux .readTodo) (.local .copyA) abort (.local .removeTerm))\n  | .local .removeTerm=>.base (.pop (aux .terms) abort abort (.local .subtract))\n  | .local .copyA=>.call (.copy .aIndex 0) (.local .predecessorA)\n  | .local .predecessorA=>.base (.pop (aux .aIndex) abort abort (.local .copyB))\n  | .local .copyB=>.call (.copy .bIndex 0) (.local .predecessorB)\n  | .local .predecessorB=>.base (.pop (aux .bIndex) abort abort (.local .terms))\n  | .local .terms=>.base (.pop (aux .terms) (.local (.clearIndices false)) abort (.local .readInverse))\n  | .local .readInverse=>.call (.helper (.read .denominator .copyArray)) (.local .checkedInverse)\n  | .local .checkedInverse=>.base (.pop (aux .valid) abort abort (.local .readPower))\n  | .local .readPower=>.call (.helper (.read .prefix .copyArray)) (.local .checkedPower)\n  | .local .checkedPower=>.base (.pop (aux .valid) abort abort (.local .product))\n  | .local .product=>.call (.helper (.operation .product (.copyInput false false))) (.local .checkedProduct)\n  | .local .checkedProduct=>.base (.pop (aux .valid) abort abort (.local .sum))\n  | .local .sum=>.call (.helper (.operation .sum (.copyInput false false))) (.local .checkedSum)\n  | .local .checkedSum=>.base (.pop (aux .valid) abort abort (.local (.clearPair 0)))\n  | .local (.clearPair i)=>.base (.pop (helper (SemiprimeD1StackNormalizedInverse.regRole ⟨i.val,by omega⟩))\n      (if h:i.val<5 then .local (.clearPair ⟨i.val+1,by omega⟩) else .local .decrementA)\n      (.local (.clearPair i)) (.local (.clearPair i)))\n  | .local .decrementA=>.base (.pop (aux .aIndex) (.local .decrementB) abort (.local .decrementB))\n  | .local .decrementB=>.base (.pop (aux .bIndex) (.local .terms) abort (.local .terms))\n  | .local (.clearIndices second)=>.base (.pop (aux (if second then .bIndex else .aIndex))\n      (.local (if second then .scalar false else .clearIndices true))\n      (.local (.clearIndices second)) (.local (.clearIndices second)))\n  | .local (.scalar den)=>.call (.copy (.scalar den) 0) (.local (if den then .total false else .scalar true))\n  | .local (.total den)=>.call (.copy (.total den) 0) (.local (if den then .finalProduct else .total true))\n  | .local .finalProduct=>.call (.helper (.operation .product (.copyInput false false))) (.local .checkedFinalProduct)\n  | .local .checkedFinalProduct=>.base (.pop (aux .valid) abort abort (.local (.frame true)))\n  | .local (.frame den)=>.call (.frame den 0) (.local (if den then .frame false else .tag))\n  | .local .tag=>.base (.push (aux .output) true (.local (.clearCoefficient 0)))\n  | .local (.clearCoefficient i)=>.base (.pop (helper (SemiprimeD1StackNormalizedInverse.regRole i))\n      (if h:i.val<7 then .local (.clearCoefficient ⟨i.val+1,by omega⟩) else .local .outer)\n      (.local (.clearCoefficient i)) (.local (.clearCoefficient i)))\n  | .local (.clean reject i)=>.base (.pop (workRole i)\n      (if h:i.val<52 then .local (.clean reject ⟨i.val+1,by omega⟩) else .local (if reject then .abortOutput else .done))\n      (.local (.clean reject i)) (.local (.clean reject i)))\n  | .local .abortOutput=>.base (.pop (aux .output) (.local .abortTerminal) (.local .abortOutput) (.local .abortOutput))\n  | .local .abortTerminal=>.base (.push (aux .output) false (.local .done))\n  | .local .done=>.base .halt\n  | .helper pc=>SemiprimeD1StackValidationLink.instruction helper Label.helper (I.program pc)\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n  | .frame den pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack den) (Label.frame den) (SemiprimeD1StackFrame.code pc)\n/-- Six actual original words ONLY; every other54 tape, including all helper shadows, is EMPTY. -/\ndef input (inverse powers signed den q width:List Bool):Stack→List Bool:=\n  Sum.elim (SemiprimeD1StackNormalizedInverse.bank (fun k=>if k=SemiprimeD1StackRationalOperation.aux .template then width else [])\n    (fun _=>[]) (fun k=>match k with | .denominator=>inverse | .prefixReverse=>powers | .originalQ=>q | _=>[]))\n    (fun k=>match k with | .signed=>signed | .den=>den)\n/-- Honest whole prepared entry, before any row/count/current/array acquisition. -/\ndef initial (inverse powers signed den q width:List Bool):C.State Stack Label:=\n  ⟨some (.local .start),none,none,input inverse powers signed den q width,[]⟩\n/-- One fixed finite60-role source with no numerical/evaluator/clock control operands. -/\ndef machine:Turing.FinTM2:=SemiprimeD1StackCalls.machine (aux .denominator) (aux .output) (.local .start) program\n/-- Every helper word, private unused shadow, scalar tape and real data role is counted. -/\ntheorem stack_card:Fintype.card Stack=60:=by simp only [Stack,Fintype.card_sum];decide\n/-- Every actual preserving copy has three distinct operands. -/\ntheorem copy_injective (site:Copy):Function.Injective (copyStack site):=by\n  cases site <;> first | decide | (rename_i den;cases den <;> decide)\n/-- Both preserving Frames have three distinct physical operands. -/\ntheorem frame_injective (den:Bool):Function.Injective (frameStack den):=by cases den <;> decide\n/-- All transient states are finite before the actual six inputs. -/\ntheorem control_finite:Finite machine.σ:=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- All data and genuine saved-return alphabets are finite. -/\ntheorem alphabets_finite:∀k,Finite (machine.Γ k):=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackRecoveryWeights\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsIndexClear":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsInner\n/-! # BOTH actual decreasing-index words are drained even at the zero-term EOF\nNo missing index reset is represented by a mathematical state shortcut.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsIndexClear\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsView\nopen SemiprimeD1StackRecoveryWeightsCalls SemiprimeD1StackRecoveryWeightsIndices SemiprimeD1StackProcedureTrace\nopen SemiprimeRationalBits (RationalWord)\n/-- Exact mathematical result of the two actual index drains, with every other word retained. -/\ndef emptied (w:Words):Words:={w with auxiliary:=Function.update (Function.update w.auxiliary .aIndex []) .bIndex []}\n/-- Both actual index words, including both final empty tests, are charged before scalar multiplication. -/\ntheorem clear_run (w:Words):\n    Runs program ((w.auxiliary .aIndex).length+1+(w.auxiliary .bIndex).length+1)\n      (.local (.clearIndices false)) (bank w) (.local (.scalar false)) (bank (emptied w)):=by\n  let first:Words:={w with auxiliary:=Function.update w.auxiliary .aIndex []}\n  have h0:=P.drain_loop (.local (.clearIndices false)) (.local (.clearIndices true)) (aux .aIndex) rfl\n    (bank w) (w.auxiliary .aIndex) rfl\n  rw [update_aux] at h0\n  have h1:=P.drain_loop (.local (.clearIndices true)) (.local (.scalar false)) (aux .bIndex) rfl\n    (bank first) (w.auxiliary .bIndex) rfl\n  rw [update_aux] at h1\n  simpa only [first,emptied,Nat.add_assoc] using P.join h0 h1\n/-- The last descending-index state restores all originally empty counters literally; the acquired total is retained. -/\ntheorem clear_indexed (w:Words) (j:Nat) (acc:RationalWord)\n    (ht:w.auxiliary .terms=[]) (ha:w.auxiliary .aIndex=[]) (hb:w.auxiliary .bIndex=[]):\n    emptied (indexed w 0 0 (j-1) acc)=putReg w .acc acc:=by\n  dsimp only [emptied,indexed,putReg,replace,SemiprimeD1StackNormalizedInverseIndices.indexed,\n    SemiprimeD1StackNormalizedInverseIndices.counters,SemiprimeD1StackNormalizedInverseView.putReg]\n  congr 1\n  congr 1\n  funext k\n  cases k <;> simp [ht,ha,hb,SemiprimeD1StackNormalizedInverseReadBuffers.unary]\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsIndexClear\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsIndices":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsCalls\nimport RiemannGaussian.SemiprimeD1StackNormalizedInverseIndices\n/-! # Both actual decreasing physical indices and remaining pair markers\nThe reused counter functions describe stores only. Every transition below is\nproved for THIS fixed60-role program by actual Boolean pops, including EOF.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsIndices\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsView\nopen SemiprimeD1StackRecoveryWeightsCalls SemiprimeD1StackProcedureTrace\nopen SemiprimeRationalBits (RationalWord)\n/-- Every q/index marker is physically present and paid. -/\ndef unary (n:Nat):List Bool:=List.replicate n true\n/-- Proof-side view of THREE actual marker words, preserving all six original inputs. -/\ndef counters (w:Words) (terms a b:Nat):Words:=replace w (SemiprimeD1StackNormalizedInverseIndices.counters w.toWords terms a b)\n/-- Actual accumulator plus the exact reached physical pair counters. -/\ndef indexed (w:Words) (terms a b:Nat) (acc:RationalWord):Words:=replace w (SemiprimeD1StackNormalizedInverseIndices.indexed w.toWords terms a b acc)\n/-- One real terms pop changes precisely its actual remaining unary word. -/\ntheorem update_terms (w:Words) (terms a b next:Nat):\n    Function.update (bank (counters w terms a b)) (aux .terms) (unary next)=bank (counters w next a b):=by\n  rw [show aux .terms=helper (SemiprimeD1StackNormalizedInverse.aux .terms) from rfl,update_helper]\n  dsimp only [counters,replace]\n  exact congrArg (fun d:I.Stack→List Bool=>Sum.elim d w.scalarInputs)\n    (SemiprimeD1StackNormalizedInverseIndices.update_terms w.toWords terms a b next)\n/-- One real inverse-index pop changes precisely its actual unary index word. -/\ntheorem update_a (w:Words) (terms a b next:Nat):\n    Function.update (bank (counters w terms a b)) (aux .aIndex) (unary next)=bank (counters w terms next b):=by\n  rw [show aux .aIndex=helper (SemiprimeD1StackNormalizedInverse.aux .aIndex) from rfl,update_helper]\n  dsimp only [counters,replace]\n  exact congrArg (fun d:I.Stack→List Bool=>Sum.elim d w.scalarInputs)\n    (SemiprimeD1StackNormalizedInverseIndices.update_a w.toWords terms a b next)\n/-- One real power-index pop changes precisely its actual unary index word. -/\ntheorem update_b (w:Words) (terms a b next:Nat):\n    Function.update (bank (counters w terms a b)) (aux .bIndex) (unary next)=bank (counters w terms a next):=by\n  rw [show aux .bIndex=helper (SemiprimeD1StackNormalizedInverse.aux .bIndex) from rfl,update_helper]\n  dsimp only [counters,replace]\n  exact congrArg (fun d:I.Stack→List Bool=>Sum.elim d w.scalarInputs)\n    (SemiprimeD1StackNormalizedInverseIndices.update_b w.toWords terms a b next)\n/-- Disjoint physical counter writes commute with an acquired scalar-cache write. -/\ntheorem counters_put (w:Words) (r:I.Reg) (word:RationalWord) (terms a b:Nat):\n    counters (putReg w r word) terms a b=putReg (counters w terms a b) r word:=rfl\n/-- Actual TRUE remaining-pair pop starts the next TWO physical coefficient reads. -/\ntheorem term_succ (w:Words) (j n:Nat) (acc:RationalWord):\n    Runs program 1 (.local .terms) (bank (indexed w (n+1) n (j+n) acc)) (.local .readInverse)\n      (bank (indexed w n n (j+n) acc)):=by\n  let base:=putReg w .acc acc\n  have h:=P.pop_run (.local .terms) (.local (.clearIndices false)) abort (.local .readInverse) (aux .terms)\n    (bank (indexed w (n+1) n (j+n) acc)) (true::unary n) rfl (by\n      change Function.update (Function.update (Function.update w.auxiliary .terms (unary (n+1))) .aIndex (unary n)) .bIndex (unary (j+n)) .terms=_\n      simp [unary,List.replicate_succ])\n  simp only [List.head?_cons,List.tail_cons,SemiprimeD1StackBytecode.choose] at h\n  change Runs program 1 _ _ _ (Function.update (bank (counters base (n+1) n (j+n))) (aux .terms) (unary n)) at h\n  rw [update_terms,counters_put] at h\n  exact h\n/-- Both inverse and power indices are physically popped, including literal EOF when their values are zero. -/\ntheorem decrement_run (w:Words) (j n:Nat) (acc:RationalWord):\n    Runs program 2 (.local .decrementA) (bank (indexed w n n (j+n) acc)) (.local .terms)\n      (bank (indexed w n (n-1) (j+n-1) acc)):=by\n  let base:=putReg w .acc acc\n  have h0:=P.pop_run (.local .decrementA) (.local .decrementB) abort (.local .decrementB) (aux .aIndex)\n    (bank (counters base n n (j+n))) (unary n) rfl (by\n      change Function.update (Function.update (Function.update base.auxiliary .terms (unary n)) .aIndex (unary n)) .bIndex (unary (j+n)) .aIndex=_\n      simp)\n  have ht:(unary n).tail=unary (n-1):=by cases n <;> simp [unary,List.replicate_succ]\n  have hc:SemiprimeD1StackBytecode.choose (Label.local .decrementB) abort (.local .decrementB) (unary n).head?=.local .decrementB:=by\n    cases n <;> simp [unary,List.replicate_succ,SemiprimeD1StackBytecode.choose]\n  rw [ht,hc,update_a] at h0\n  have h1:=P.pop_run (.local .decrementB) (.local .terms) abort (.local .terms) (aux .bIndex)\n    (bank (counters base n (n-1) (j+n))) (unary (j+n)) rfl (by\n      change Function.update (Function.update (Function.update base.auxiliary .terms (unary n)) .aIndex (unary (n-1))) .bIndex (unary (j+n)) .bIndex=_\n      exact Function.update_self _ _ _)\n  have ht1:(unary (j+n)).tail=unary (j+n-1):=by cases j+n <;> simp [unary,List.replicate_succ]\n  have hc1:SemiprimeD1StackBytecode.choose (Label.local .terms) abort (.local .terms) (unary (j+n)).head?=.local .terms:=by\n    cases j+n <;> simp [unary,List.replicate_succ,SemiprimeD1StackBytecode.choose]\n  rw [ht1,hc1,update_b] at h1\n  exact P.join h0 h1\n/-- Actual terms EOF retains the acquired sum and starts full disposal of BOTH index words. -/\ntheorem term_zero (w:Words) (j:Nat) (acc:RationalWord):\n    Runs program 1 (.local .terms) (bank (indexed w 0 0 (j-1) acc)) (.local (.clearIndices false))\n      (bank (indexed w 0 0 (j-1) acc)):=by\n  let base:=putReg w .acc acc\n  have h:=P.pop_run (.local .terms) (.local (.clearIndices false)) abort (.local .readInverse) (aux .terms)\n    (bank (counters base 0 0 (j-1))) [] rfl (by\n      change Function.update (Function.update (Function.update base.auxiliary .terms []) .aIndex []) .bIndex (unary (j-1)) .terms=[]\n      simp)\n  change Runs program 1 _ _ _ (Function.update (bank (counters base 0 0 (j-1))) (aux .terms) (unary 0)) at h\n  rw [update_terms,counters_put] at h\n  exact h\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsIndices\n","RiemannGaussian.SemiprimeD1StackRecoveryWeightsScalarBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWeightsBankBounds\n/-! # Own final-scalar/copies/frame/drain clock, with the full retained output physically charged -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWeightsScalarBounds\nopen SemiprimeD1StackRecoveryWeights SemiprimeD1StackRecoveryWeightsView\nopen SemiprimeD1StackRecoveryWeightsWidths\nopen SemiprimeD1StackRecoveryWeightsScalar SemiprimeD1StackRecoveryWeightsScalarInput\nopen SemiprimeD1StackNormalizedInverseBankBounds\nopen SemiprimeRationalBits (RationalWord)\n/-- Actual final inputs, the fitted product and both preserving frames retain bounded complete-bank mass. -/\ntheorem beforeClear_bound (w:Words) (scalar total:RationalWord) (width:List Bool) (s:Nat)\n    (hs:1 ≤ s) (hw:width.length ≤ s) (hbank:BoundedBank w.toWords s (5*s) (14*s^2))\n    (hscalar:B.bytes scalar ≤ 5*s) (htotal:B.bytes total ≤ 5*s):\n    BoundedBank (beforeClear w scalar total width).toWords s (5*s) (30*s^2):=by\n  have hf:BoundedBank (filled w scalar total).toWords s (5*s) (14*s^2):=\n    put_bound _ _ _ _ (put_bound _ _ _ _ hbank .left scalar hscalar) .right total htotal\n  have ha:BoundedBank (SemiprimeD1StackRecoveryWeightsCalls.afterOperation .product (filled w scalar total) width).toWords s (5*s) (14*s^2):=\n    after_bound .product _ width _ _ _ hf (by omega)\n  have hs2:s ≤ s^2:=Nat.le_pow (by decide:0<2)\n  refine ⟨ha.1,ha.2.1,?_⟩\n  intro k\n  by_cases he:k=.output\n  · subst k\n    change (SemiprimeD1StackNormalizedInverse.row (output scalar total width) (w.auxiliary .output)).length ≤ _\n    rw [B.row_bytes]\n    have hb:B.bytes (output scalar total width)=2*width.length+1:=B.execute_bytes .mul scalar total width\n    have ho:=hbank.2.2 .output\n    nlinarith only [hb,ho,hw,hs,hs2]\n  · change (Function.update w.auxiliary .output _ k).length ≤ _\n    rw [Function.update_of_ne he]\n    have hh:=hbank.2.2 k\n    omega\n/-- Pure numerical accounting avoids reducing any rational payload in the clock proof. -/\nprivate theorem scalar_arithmetic (s width x y z call mass:Nat) (hs:1 ≤ s) (hw:width ≤ s)\n    (hx:x ≤ 5*s) (hy:y ≤ 5*s) (hz:z=2*width+1)\n    (hc:call ≤ 10^36*s^6) (hm:mass ≤ 36*s+8*(5*s)+14*(30*s^2)):\n    5*(x+y)+16+call+(6*z+11)+8*(mass+1) ≤ 10^38*s^6:=by\n  have hs6:s ≤ s^6:=Nat.le_pow (by decide:0<6)\n  have hs26:s^2 ≤ s^6:=Nat.pow_le_pow_right hs (by decide:2≤6)\n  have h16:1 ≤ s^6:=Nat.one_le_pow _ _ hs\n  nlinarith only [hc,hm,hz,hx,hy,hw,hs6,hs26,h16]\n/-- Every actual four-copy/whole-R36/two-frame/eight-drain step has a fixed physical-bit cap. -/\ntheorem scalar_bound (w:Words) (scalar total:RationalWord) (width:List Bool) (s:Nat)\n    (hs:1 ≤ s) (hw:width.length ≤ s) (hbank:BoundedBank w.toWords s (5*s) (14*s^2))\n    (hscalar:B.bytes scalar ≤ 5*s) (htotal:B.bytes total ≤ 5*s):\n    SemiprimeD1StackRecoveryWeightsScalar.timeBound w scalar total width ≤ 10^38*s^6:=by\n  have hf:BoundedBank (filled w scalar total).toWords s (5*s) (14*s^2):=\n    put_bound _ _ _ _ (put_bound _ _ _ _ hbank .left scalar hscalar) .right total htotal\n  have hc:=SemiprimeD1StackNormalizedInversePairBounds.small_call .product (filled w scalar total).toWords width s hs hw hf\n  have hm:=mass_le (beforeClear w scalar total width).toWords s (5*s) (30*s^2)\n    (beforeClear_bound w scalar total width s hs hw hbank hscalar htotal)\n  have hb:B.bytes (output scalar total width)=2*width.length+1:=B.execute_bytes .mul scalar total width\n  have hinputs:SemiprimeD1StackRecoveryWeightsScalarInput.timeBound scalar total=5*(B.bytes scalar+B.bytes total)+16:=by\n    unfold SemiprimeD1StackRecoveryWeightsScalarInput.timeBound SemiprimeD1StackNormalizedInverseWidths.bytes\n    omega\n  unfold SemiprimeD1StackRecoveryWeightsScalar.timeBound\n  rw [hinputs]\n  exact scalar_arithmetic s width.length (B.bytes scalar) (B.bytes total) (B.bytes (output scalar total width)) _ _ hs hw hscalar htotal hb hc hm\nend RiemannGaussian.SemiprimeD1StackRecoveryWeightsScalarBounds\n","RiemannGaussian.SemiprimeD1StackRecoveryWidthPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRecoveryWidth\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Actual preserving copies and paid byte scans/drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRecoveryWidthPrimitives\nopen SemiprimeD1StackRecoveryWidth SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Label)\n    (hc:program pc=.call (.copier what 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) pc before next\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) pc next hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Label) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)) :\n    Runs program 1 pc before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes only the actual physical Boolean head. -/\ntheorem pop_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Every actual source peek preserves the entire acquired word. -/\ntheorem peek_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every quotient/remainder/GCD/magnitude cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Label) (next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) pc before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- One literal static jump advances fixed source syntax without touching any actual word. -/\ntheorem jump_run (pc next:Label) (before:Stack→List Bool) (hc:program pc=.base (.jump next)) :\n    Runs program 1 pc before next before:=one_base program _ _ _ _ _ hc rfl rfl\n/-- Real unary multiplication consumes every actual left marker, preserves the exact directly aliased right word,\nand emits the actual product markers into its fresh physical destination. -/\ntheorem product_call (g:W.Gate) (before:Stack→List Bool) (m d:List Bool)\n    (hm:before (productStack g .multiplier)=m) (hd:before (productStack g .multiplicand)=d)\n    (hs:before (productStack g .scratch)=[]) (ho:before (productStack g .product)=[]) :\n    ∃q≤5*(m.length*(2*d.length+3)+1)+1,Runs program q (.multiply g) before (nextGate g)\n      (Function.update (Function.update before (aux .multiplier) []) (reg g)\n        (SemiprimeD1StackUnaryDivmod.unary (m.length*d.length))) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackUnaryProductRaw.product_run m d\n  let start:SemiprimeD1StackBytecode.State P.Stack P.Label:=⟨some P.entry,none,P.contents m d [] []⟩\n  let stop:SemiprimeD1StackBytecode.State P.Stack P.Label:=⟨none,none,P.contents [] d [] (SemiprimeD1StackUnaryDivmod.unary (m.length*d.length))⟩\n  have hin:Link.DataRel (productStack g) before start.store before:=by\n    constructor\n    · intro k;cases k\n      · exact hm\n      · exact hd\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update (productStack g) (product_injective g) before start.store before hin .multiplier []\n  have h1:=Link.data_update (productStack g) (product_injective g) before _ _ h0 .product\n    (SemiprimeD1StackUnaryDivmod.unary (m.length*d.length))\n  have he:Function.update (Function.update start.store .multiplier []) .product\n      (SemiprimeD1StackUnaryDivmod.unary (m.length*d.length))=stop.store:=by\n    funext k;cases k <;> rfl\n  rw [he] at h1\n  refine ⟨q+1,by omega,?_⟩\n  exact included_call program (productStack g) (Label.product g) (product_injective g) P.code P.entry\n    (fun _=>rfl) (.multiply g) (nextGate g) rfl q start stop before _ rfl rfl hr hin h1\nend RiemannGaussian.SemiprimeD1StackRecoveryWidthPrimitives\n","RiemannGaussian.SemiprimeD1StackResidueSubBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackResidueSubExecution\nimport RiemannGaussian.SemiprimeBitFermatArithmetic\nimport RiemannGaussian.SemiprimeD1StackAssignmentOrder\n/-! # General-modulus subtraction machine time, all-prefix storage and exact bytes -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1000000\nnamespace RiemannGaussian.SemiprimeD1StackResidueSubBounds\nopen SemiprimeD1StackResidueSub SemiprimeD1StackResidueSubExecution\nopen SemiprimeBitArithmetic SemiprimeBitDivision\n\n/-- Fixed physical-input polynomial; no operand VALUE determines this bound. -/\ndef timeBound (n m p : ℕ) : ℕ := 1000*(n+m+2*p+4)^2+30*(n+m+p+3)\n\n/-- Original physical inputs derive all actual intermediate lengths and work. -/\ntheorem totalTime_le (a b cached : List Bool) :\n    totalTime a b cached≤timeBound a.length b.length cached.length := by\n  have ha := (SemiprimeD1StackAdderExecution.sourceAdd a cached false).steps_le_m\n  change addTime a cached≤5*(a.length+cached.length)+7 at ha\n  have hs := (addBits_counts a cached false).2.2.2.2\n  change (sum a cached).length≤max a.length cached.length+1 at hs\n  have hamax : max a.length cached.length≤a.length+cached.length := max_le (by omega) (by omega)\n  have hb := (SemiprimeD1StackSubtractorExecution.sourceSubtract (sum a cached) b false).steps_le_m\n  change subtractTime a b cached≤5*((sum a cached).length+b.length)+8 at hb\n  have hl := (subBits_counts (sum a cached) b false).2.2.2.2\n  change (difference a b cached).length=max (sum a cached).length b.length at hl\n  have hdiff : (difference a b cached).length≤a.length+b.length+cached.length+1 := by\n    rw [hl]\n    exact max_le (by omega) (by omega)\n  have hd := (SemiprimeD1StackDividerExecution.source_time (difference a b cached) cached).trans\n    (SemiprimeD1StackDividerExecution.timeBound_le_square (difference a b cached).length cached.length)\n  have hdBound : 1000*((difference a b cached).length+cached.length+2)^2≤\n      1000*(a.length+b.length+2*cached.length+4)^2 := by\n    apply Nat.mul_le_mul_left\n    exact Nat.pow_le_pow_left (by omega) 2\n  have hd' := hd.trans hdBound\n  have hq := (divideLoop_widths (difference a b cached) cached).2.1\n  change (quotient a b cached).length=(difference a b cached).length at hq\n  unfold totalTime timeBound\n  omega\n\n/-- One fixed quadratic monomial bounds the complete actual pipeline. -/\ntheorem timeBound_le_square (n m p : ℕ) : timeBound n m p≤5000*(n+m+p+3)^2 := by\n  let u:=n+m+p+3\n  have hu : 1≤u := by omega\n  have hd : 1000*(n+m+2*p+4)^2≤4000*u^2 := by\n    calc\n      _ ≤ 1000*(2*u)^2 := Nat.mul_le_mul_left 1000 (Nat.pow_le_pow_left (by dsimp [u];omega) 2)\n      _ = _ := by ring\n  have h1 : u≤u^2 := by simpa only [pow_one] using Nat.pow_le_pow_right hu (by decide : 1≤2)\n  change 1000*(n+m+2*p+4)^2+30*u≤5000*u^2\n  omega\n\n/-- A cubic-compatible envelope is available for uniform public arithmetic joins. -/\ntheorem timeBound_le_cube (n m p : ℕ) : timeBound n m p≤5000*(n+m+p+3)^3 :=\n  (timeBound_le_square n m p).trans (Nat.mul_le_mul_left 5000\n    (Nat.pow_le_pow_right (by omega : 1≤n+m+p+3) (by decide : 2≤3)))\n\n/-- Actual source execution certificate, with no supplied elapsed count. -/\ndef sourceSubtract (a b cached : List Bool) :\n    StateTransition.EvalsToInTime (C.step program) (initial a b cached)\n      (some (done a b cached)) (timeBound a.length b.length cached.length) :=\n  ⟨⟨_,source_run a b cached⟩,totalTime_le a b cached⟩\n\n/-- Genuine FinTM2 certificate for exactly the same finite instruction table. -/\ndef machineSubtract (a b cached : List Bool) :\n    StateTransition.EvalsToInTime machine.step\n      (SemiprimeD1StackCalls.configuration (initial a b cached))\n      (some (SemiprimeD1StackCalls.configuration (done a b cached)))\n      (timeBound a.length b.length cached.length) :=\n  SemiprimeD1StackCalls.evalsCorrect (K:=Stack) (L:=Label) (.inl (.left : A.Stack)) output Label.start program\n    _ _ _ (sourceSubtract a b cached)\n\n/-- Every raw input returns exactly the physical cached-modulus width. -/\ntheorem residue_width (a b cached : List Bool) : (residue a b cached).length=cached.length :=\n  (divideLoop_widths (difference a b cached) cached).1\n\n/-- The actual binary sum has its original arithmetic value. -/\ntheorem sum_value (a cached : List Bool) : bitValue (sum a cached)=bitValue a+bitValue cached := by\n  simpa only [sum,bitNat,Bool.false_eq_true,ite_false,Nat.add_zero] using addBits_correct a cached false\n\n/-- ORIGINAL right-residue validity proves the actual subtractor never underflows;\nno intermediate borrow answer is supplied to runtime or to this conclusion. -/\ntheorem actual_borrow_false (a b cached : List Bool) (hb : bitValue b<bitValue cached) :\n    borrow a b cached=false := by\n  have hnot : (subBits (sum a cached) b false).borrow≠true := by\n    intro h\n    have hlt := (subBits_borrow_iff (sum a cached) b false).mp h\n    simp only [bitNat,Bool.false_eq_true,ite_false,Nat.add_zero,sum_value] at hlt\n    omega\n  change (subBits (sum a cached) b false).borrow=false\n  cases h : (subBits (sum a cached) b false).borrow with\n  | false=>rfl\n  | true=>exact (hnot h).elim\n\n/-- The actually acquired difference is x+M-y, from original input validity. -/\ntheorem difference_equation (a b cached : List Bool) (hb : bitValue b<bitValue cached) :\n    bitValue (difference a b cached)+bitValue b=bitValue a+bitValue cached := by\n  have he := subBits_equation (sum a cached) b false\n  have hborrow := actual_borrow_false a b cached hb\n  change (subBits (sum a cached) b false).borrow=false at hborrow\n  simp only [hborrow,bitNat,Bool.false_eq_true,ite_false,Nat.mul_zero,Nat.add_zero,sum_value] at he\n  change bitValue (subBits (sum a cached) b false).result.bits+bitValue b=_\n  omega\n\n/-- Actual positive-modulus restoring division value, with no quotient advice. -/\ntheorem residue_value (a b cached : List Bool) (hm : 0<bitValue cached) :\n    bitValue (residue a b cached)=bitValue (difference a b cached)%bitValue cached := by\n  change bitValue (divideLoop (difference a b cached) cached).remainder=_\n  rw [←(SemiprimeD1StackDividerExecution.divideBits_outputs (difference a b cached) cached hm).2]\n  exact (divideBits_correct (difference a b cached) cached).2\n\n/-- ORIGINAL canonical operand guards give EXACT frozen residueSubBits bytes.\nLiteral-width equality preserves arbitrary high-zero padding in the cache. -/\ntheorem residue_original (a b cached : List Bool)\n    (ha : bitValue a<bitValue cached) (hb : bitValue b<bitValue cached) :\n    residue a b cached=(SemiprimeBitFermatArithmetic.residueSubBits cached a b).output.bits := by\n  apply SemiprimeD1StackAssignmentOrder.word_value_injective\n  · exact (residue_width a b cached).trans (SemiprimeBitFermatArithmetic.residueSubBits_width cached a b).symm\n  · rw [residue_value a b cached (by omega)]\n    have hold := SemiprimeBitFermatArithmetic.residueSubBits_exact ha hb\n    have hnew := difference_equation a b cached hb\n    cases h : (subBits a b false).borrow with\n    | false=>\n      simp only [h,bitNat,Bool.false_eq_true,ite_false,Nat.mul_zero,Nat.add_zero] at hold\n      have hd : bitValue (difference a b cached)=\n          bitValue (SemiprimeBitFermatArithmetic.residueSubBits cached a b).output.bits+bitValue cached := by omega\n      rw [hd,Nat.add_mod_right,Nat.mod_eq_of_lt hold.1]\n    | true=>\n      simp only [h,bitNat,ite_true,Nat.mul_one] at hold\n      have hd : bitValue (difference a b cached)=\n          bitValue (SemiprimeBitFermatArithmetic.residueSubBits cached a b).output.bits := by omega\n      rw [hd,Nat.mod_eq_of_lt hold.1]\n\n/-- The raw binary modulus cache survives literally, including all padding. -/\ntheorem retained_modulus (a b cached : List Bool) : finalData a b cached modulus=cached := rfl\n/-- Only the actual computed remainder is designated as output. -/\ntheorem output_residue (a b cached : List Bool) : finalData a b cached output=residue a b cached := rfl\n\n/-- Every reached prefix is before or at the actual complete source halt. -/\ntheorem prefix_fuel_le (a b cached : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial a b cached)=some out) : fuel≤totalTime a b cached := by\n  by_contra hn\n  have he : fuel=totalTime a b cached+(1+(fuel-(totalTime a b cached+1))) := by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,source_run,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add] at hr\n  have hz : C.run program 1 (done a b cached)=none := rfl\n  rw [hz,Option.bind_none] at hr\n  cases hr\n\n/-- All twenty-one Boolean stacks and real finite-label return cells are paid\nat EVERY actual prefix, including both modulus copies and all arithmetic work. -/\ntheorem prefix_cells (a b cached : List Bool) (fuel : ℕ) (out : C.State Stack Label)\n    (hr : C.run program fuel (initial a b cached)=some out) :\n    (∑k : Stack,(out.data k).length)+out.frames.length≤120000*(a.length+b.length+cached.length+3)^2 := by\n  have hd := SemiprimeD1StackReturnLink.run_data_bound program fuel (a.length+b.length+cached.length)\n    (initial a b cached) out (by\n      intro k\n      rcases k with k|k\n      · cases k <;> simp [initial,input,store,A.store]; omega\n      · rcases k with k|k\n        · cases k <;> simp [initial,input,store,A.store]; omega\n        · rcases k with k|k\n          · rcases k with k|k <;> cases k <;> simp [initial,input,store,D.payload]\n          · cases k <;> simp [initial,input,store]) hr\n  have hf := SemiprimeD1StackCalls.run_frame_bound program fuel _ out hr\n  change out.frames.length≤0+fuel at hf\n  have hs : (∑k : Stack,(out.data k).length)≤21*(a.length+b.length+cached.length+fuel) := by\n    calc\n      _ ≤ ∑_k : Stack,(a.length+b.length+cached.length+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht := ((prefix_fuel_le a b cached fuel out hr).trans (totalTime_le a b cached)).trans\n    (timeBound_le_square a.length b.length cached.length)\n  have hu : 1≤a.length+b.length+cached.length+3 := by omega\n  have hbase : a.length+b.length+cached.length≤(a.length+b.length+cached.length+3)^2 := by\n    have hh := Nat.pow_le_pow_right hu (by decide : 1≤2)\n    simp only [pow_one] at hh\n    omega\n  omega\n\n/-- Same complete all-prefix storage inventory for the genuine compiled machine. -/\ntheorem machine_prefix_cells (a b cached : List Bool) (fuel : ℕ) (cfg : machine.Cfg)\n    (hr : (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial a b cached)))=some cfg) :\n    (∑k : Stack,(cfg.stk (some k)).length)+(cfg.stk none).length≤\n      120000*(a.length+b.length+cached.length+3)^2 := by\n  have he := SemiprimeD1StackCalls.run_correct (.inl (.left : A.Stack)) output .start program fuel\n    (initial a b cached)\n  have hh := he.trans hr\n  cases hc : C.run program fuel (initial a b cached) with\n  | none=>rw [hc] at hh;cases hh\n  | some out=>\n    rw [hc] at hh\n    have hcfg : SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells a b cached fuel out hc\nend RiemannGaussian.SemiprimeD1StackResidueSubBounds\n","RiemannGaussian.SemiprimeD1StackRootControllerMetadataOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootControllerMetadataBounds\n\n/-! # Exact original root metadata from N alone, with one own polynomial clock\nThe same acquired occurrence count applies to every original fixed prefix,\nincluding repeated and conflicting prescribed values. Its E wire count stays\nseparate. All original schedule outputs are physically acquired too; s and\nthe square-root leaf threshold remain the next acquisition obligation.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackRootControllerMetadataOriginal\nopen SemiprimeD1StackRootControllerMetadata SemiprimeD1StackRootControllerMetadataExecution\nopen SemiprimeD1StackRootControllerMetadataBounds\nopen SemiprimeBitArithmetic (bitValue)\nnamespace O\nexport SemiprimeD1StackRootScheduleOriginal (originalLambda)\nend O\n/-- Every original graph/source/cache cell is retained byte for byte. -/\ntheorem source_preserved (bits:List Bool) (k:S.Stack) : result bits (sourceStack k)=S.result bits k := rfl\n/-- Exact schedule projection, including the original N role shared with the source. -/\ntheorem schedule_projection (bits:List Bool) (k:R.Stack) : result bits (scheduleStack k)=R.result bits k :=\n  payload_schedule (S.result bits) (R.result bits)\n    ((source_retained_N bits).trans (SemiprimeD1StackRootScheduleOriginal.input_preserved bits).symm) k\n/-- N remains the same binary word; no second initial N payload is introduced. -/\ntheorem input_preserved (bits:List Bool) : result bits originalInput=bits := source_retained_N bits\n/-- The unused private shared-input shadow really stays empty and is still counted. -/\ntheorem shadow_empty (bits:List Bool) : result bits (.inr (R.boot .input))=[] := by rfl\n/-- Actual M word is the original root network edge cardinality, for EVERY fixed prefix. -/\ntheorem edges_original (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) :\n    result bits edges=List.replicate (SemiprimeD1TensorNetwork.edgeCount\n      (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) true := by\n  change S.result bits S.count=_\n  rw [(SemiprimeD1StackRootScopeBankExecution.result_counts bits).1,\n    SemiprimeD1StackRootScopeBankOriginal.occurrence_count bits hN fixed]\n/-- The separate E word counts original Boolean wires, never occurrence ordinals. -/\ntheorem wires_original (bits:List Bool) :\n    result bits wires=List.replicate (SemiprimePublicAcquiredExecution.wireCount (bitValue bits)) true := by\n  change S.result bits S.wireCount=_\n  rw [(SemiprimeD1StackRootScopeBankExecution.result_counts bits).2,\n    SemiprimeD1StackRootScopeBankOriginal.wire_count bits]\n/-- The two real counters satisfy M=2E; no equality of their identifier domains is asserted. -/\ntheorem count_lengths (bits:List Bool) : (result bits edges).length=2*(result bits wires).length := by\n  change (S.result bits S.count).length=2*(S.result bits S.wireCount).length\n  rw [(SemiprimeD1StackRootScopeBankExecution.result_counts bits).1,\n    (SemiprimeD1StackRootScopeBankExecution.result_counts bits).2]\n  simp only [List.length_replicate,SemiprimeD1StackRootScopeBankExecution.occurrenceCount]\n/-- Actual original logarithm from N, without a supplied log or width operand. -/\ntheorem lambda_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits lambda=List.replicate (O.originalLambda (bitValue bits)) true := by\n  change result bits (scheduleStack (R.aux .lambda))=_\n  rw [schedule_projection]\n  exact SemiprimeD1StackRootScheduleOriginal.lambda_original_word bits hc\n/-- Actual original root dyadic level counter. -/\ntheorem levels_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits levels=List.replicate (SemiprimeD1Schedule.levels (O.originalLambda (bitValue bits)) 0) true := by\n  change result bits (scheduleStack (R.aux .levels))=_\n  rw [schedule_projection]\n  exact SemiprimeD1StackRootScheduleOriginal.levels_original_word bits hc\n/-- Actual original root cumulative exponent counter. -/\ntheorem exponent_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits exponent=List.replicate (SemiprimeD1Schedule.exponent (O.originalLambda (bitValue bits)) 0) true := by\n  change result bits (scheduleStack (R.aux .exponent))=_\n  rw [schedule_projection]\n  exact SemiprimeD1StackRootScheduleOriginal.exponent_original_word bits hc\n/-- Actual original minimum-level guard, with both its logarithm and marker writes paid. -/\ntheorem minimum_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits minimum=List.replicate (SemiprimeD1PrecisionEnvelope.minimumLevels\n      (O.originalLambda (bitValue bits))) true := by\n  change result bits (scheduleStack (R.aux .minimum))=_\n  rw [schedule_projection]\n  exact SemiprimeD1StackRootScheduleOriginal.minimum_original_word bits hc\n/-- Actual canonical original-input width is retained for scale acquisition. -/\ntheorem width_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) :\n    result bits (scheduleStack (R.boot .width))=List.replicate\n      (SemiprimeMacroParameters.bitLength (bitValue bits)) true := by\n  rw [schedule_projection]\n  exact SemiprimeD1StackRootScheduleOriginal.retained_width bits hc\n/-- One actual run and all original output correspondences hold simultaneously for every N. -/\ntheorem source_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤10^50*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^10,\n      SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) ∧\n      (∀fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool),\n        result bits edges=List.replicate (SemiprimeD1TensorNetwork.edgeCount\n          (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) true) ∧\n      result bits lambda=List.replicate (O.originalLambda (bitValue bits)) true ∧\n      result bits levels=List.replicate (SemiprimeD1Schedule.levels (O.originalLambda (bitValue bits)) 0) true ∧\n      result bits exponent=List.replicate (SemiprimeD1Schedule.exponent (O.originalLambda (bitValue bits)) 0) true ∧\n      result bits minimum=List.replicate (SemiprimeD1PrecisionEnvelope.minimumLevels\n        (O.originalLambda (bitValue bits))) true ∧ result bits originalInput=bits := by\n  obtain ⟨t,ht,hr⟩:=source_run_polynomial bits hc hN\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  refine ⟨t,?_,hr,edges_original bits hN,lambda_original bits hc,levels_original bits hc,\n    exponent_original bits hc,minimum_original bits hc,input_preserved bits⟩\n  simpa only [hw] using ht\n/-- Genuine N-only finite-machine acquisition under that same whole original-bitlength clock. -/\nnoncomputable def originalInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits)))\n      (10^50*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^10) := by\n  have h:=acquireInTime bits hc hN\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simpa only [hw] using h\n/-- Every original-N prefix pays ALL98 roles, shared-input shadow and actual return cells. -/\ntheorem original_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      10^53*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^10 := by\n  have h:=(machine_prefix_cells bits hc hN fuel cfg hr).trans (polynomial_space bits)\n  have hw:=SemiprimeD1StackRootScheduleOriginal.width_original bits hc\n  simpa only [hw] using h\nend RiemannGaussian.SemiprimeD1StackRootControllerMetadataOriginal\n","RiemannGaussian.SemiprimeD1StackRootNetworkRecordsOriginal":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootNetworkRecordsExecution\nimport RiemannGaussian.SemiprimeD1StackRootNetworkRecordsResources\nimport RiemannGaussian.SemiprimeD1RootRecordCoordinates\n\n/-! # Exact whole original root-network record output\nThe two actual source tapes are joined in the literal original vertex order.\nAll prescribed prefixes, including repeats/conflicts and retained physical tails,\nare covered. No native root constructor or byte append is a runtime instruction.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackRootNetworkRecordsOriginal\nopen SemiprimeD1StackRootNetworkRecords SemiprimeD1StackRootNetworkRecordsExecution\nopen SemiprimeBitArithmetic (bitValue)\nnamespace V\nexport SemiprimeD1StackVertexProduct (records)\nend V\nnamespace L\nexport SemiprimeD1StackVertexRecordStream (row row_records)\nend L\n/-- Chronological original record bytes, excluding only the final vector marker. -/\ndef recordBytes (vs:List SemiprimeD1LeafCounter.Vertex) : List Bool :=\n  (vs.map (fun v=>L.row (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n    (SemiprimeD1TensorTapeCodec.tape v.table))).flatten\n/-- Joining two whole original lists puts precisely the first payload ahead of the second list. -/\ntheorem records_append (vs ws:List SemiprimeD1LeafCounter.Vertex) :\n    recordBytes vs++V.records ws=V.records (vs++ws) := by\n  induction vs with\n  | nil=>rfl\n  | cons v vs ih=>\n    change (L.row (SemiprimeD1StackVertexReadExecution.portTape v.ports)\n      (SemiprimeD1TensorTapeCodec.tape v.table)++recordBytes vs)++V.records ws=V.records ((v::vs)++ws)\n    rw [List.append_assoc,ih]\n    exact L.row_records v (vs++ws)\n/-- The actual owner's false-terminated source supplies exactly its chronological payload. -/\ntheorem owner_payload (bits:List Bool) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    ownerBytes bits hN fixed=recordBytes (SemiprimeD1StackOwnerRecordsOriginal.vertices (bitValue bits) hN fixed) := by\n  have h0:=owner_output bits hN fixed tail\n  have h1:=SemiprimeD1StackOwnerRecordsExecution.output_original bits hN fixed tail\n  have h2:=SemiprimeD1StackOwnerRecordsOriginal.flatten_records\n    (SemiprimeD1StackOwnerRecordsOriginal.vertices (bitValue bits) hN fixed)\n  exact List.append_cancel_right (h0.symm.trans (h1.trans h2.symm))\n/-- The actual complete factor source supplies every old factor in its unchanged original order. -/\ntheorem factors_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    factorTape bits=V.records (SemiprimeD1StackFullFactorCatalogueOriginal.factorVertices (bitValue bits) hN\n      (SemiprimeD1BooleanFactorCatalogueIndices.indices (bitValue bits))) :=\n  (factor_output bits).symm.trans (SemiprimeD1StackFullFactorCatalogueOriginal.final_output bits hc hN)\n/-- Exact old cached network tape, with owners first and all factors second, for EVERY original prefix. -/\ntheorem output_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    (done bits hN fixed tail).data output=V.records (SemiprimeD1TensorNetwork.vertices\n      (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) := by\n  change ownerBytes bits hN fixed++factorTape bits=_\n  rw [owner_payload bits hN fixed tail,factors_original bits hc hN,\n    SemiprimeD1RootRecordCoordinates.vertices_original]\n  exact records_append _ _\n/-- One genuine original-prefix execution with exact full old root record bytes. -/\ntheorem source_prefix_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool) :\n    ∃t ≤ timeBound bits hN fixed tail,SemiprimeD1StackCalls.run program t\n      (initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail))=\n        some (done bits hN fixed tail) ∧\n      (done bits hN fixed tail).data output=V.records (SemiprimeD1TensorNetwork.vertices\n        (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) := by\n  obtain ⟨t,ht,hr⟩:=source_run_prefix bits hc hN fixed tail\n  exact ⟨t,ht,hr,output_original bits hc hN fixed tail⟩\n/-- N alone suffices to acquire the entire old original root-network input tape. -/\ntheorem source_original (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t ≤ timeBound bits hN [] []+1,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits hN [] []) ∧\n      (done bits hN [] []).data output=V.records (SemiprimeD1TensorNetwork.vertices\n        (SemiprimeD1RootStateResources.root (bitValue bits) hN [])) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits hc hN\n  exact ⟨t,ht,hr,output_original bits hc hN [] []⟩\n/-- The complete original-input acquisition and exact output share ONE actual global source clock. -/\ntheorem source_original_bounded (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits) :\n    ∃t ≤ SemiprimeD1StackRootNetworkRecordsBounds.runBound bits,\n      SemiprimeD1StackCalls.run program t (initial bits)=some (done bits hN [] []) ∧\n      (done bits hN [] []).data output=V.records (SemiprimeD1TensorNetwork.vertices\n        (SemiprimeD1RootStateResources.root (bitValue bits) hN [])) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRootNetworkRecordsBounds.source_run_bounded bits hc hN\n  exact ⟨t,ht,hr,output_original bits hc hN [] []⟩\n/-- Fixed constants precede every N; the bound covers the SAME exact original-N acquisition. -/\ntheorem uniform_original :∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits),\n    ∃t ≤ coef*(SemiprimeMacroParameters.bitLength (bitValue bits)+1)^degree*\n      2^(19*SemiprimeMacroParameters.scopeBound (SemiprimeMacroParameters.bitLength (bitValue bits))),\n      SemiprimeD1StackCalls.run program t (initial bits)=some (done bits hN [] []) ∧\n      (done bits hN [] []).data output=V.records (SemiprimeD1TensorNetwork.vertices\n        (SemiprimeD1RootStateResources.root (bitValue bits) hN [])) := by\n  obtain ⟨coef,degree,h⟩:=SemiprimeD1StackRootNetworkRecordsResources.source_run_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN\n  obtain ⟨t,ht,hr⟩:=h bits hc hN\n  have hw:=SemiprimeD1BinaryDigitAcquisitionBounds.canonical_width bits hc\n  refine ⟨t,?_,hr,output_original bits hc hN [] []⟩\n  simpa only [SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity,hw] using ht\n/-- The same fixed program covers every physical caller prefix/tail with its full input size paid. -/\ntheorem uniform_prefix_original :∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fixed:List (Fin (SemiprimePublicAcquiredExecution.wireCount (bitValue bits))×Bool)) (tail:List Bool),\n    ∃t ≤ coef*(bits.length+(SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail).length+1)^degree*\n      2^(19*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits),\n      SemiprimeD1StackCalls.run program t\n        (initialPrefix bits (SemiprimeD1StackRootNetworkRecordsAcquisition.prescription bits fixed tail))=\n          some (done bits hN fixed tail) ∧\n      (done bits hN fixed tail).data output=V.records (SemiprimeD1TensorNetwork.vertices\n        (SemiprimeD1RootStateResources.root (bitValue bits) hN fixed)) := by\n  obtain ⟨coef,degree,h⟩:=SemiprimeD1StackRootNetworkRecordsResources.source_run_prefix_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN fixed tail\n  obtain ⟨t,ht,hr⟩:=h bits hc hN fixed tail\n  exact ⟨t,ht,hr,output_original bits hc hN fixed tail⟩\n/-- Actual initialization is the genuine finite machine's binary-N-only Turing.initList. -/\nnoncomputable def machineOriginal (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits hN [] [])))\n      (SemiprimeD1StackRootNetworkRecordsBounds.runBound bits) :=\n  SemiprimeD1StackRootNetworkRecordsResources.rootRecordsInTime bits hc hN\nend RiemannGaussian.SemiprimeD1StackRootNetworkRecordsOriginal\n","RiemannGaussian.SemiprimeD1StackRootOwnerIndexResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootOwnerIndex\nimport RiemannGaussian.SemiprimeD1StackRootOwnerIndexBounds\n/-! # Genuine N-only owner-index initialization and all1821-role resources\nBoth full source banks and the two unused index-input shadows are included.\nTime and prefix bounds are attached to the same actual finite caller program.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootOwnerIndexResources\nopen SemiprimeD1StackRootOwnerIndex\nopen SemiprimeD1StackCalls (run configuration)\nlocal notation \"main\" => (Sum.inl Control.start :Label)\n/-- Both allocated source-input shadows and every other private empty index role are physically empty. -/\ntheorem private_empty (k:I.Stack):privateView (fun _=>[]) k=[]:=by cases k <;> rfl\n/-- The actual standard source initializes exactly one original binary-N word. -/\ntheorem input_single (bits:List Bool):input bits=fun k=>if k=originalInput then bits else []:=by\n  funext k\n  rcases k with k|k\n  · have h:=congrFun (SemiprimeD1StackRootNetworkRecordsResources.input_single bits) k\n    simpa only [input,data,Sum.elim_inl,originalInput,rootStack,Sum.inl.injEq] using h\n  · change privateView (fun _=>[]) k=[]\n    exact private_empty k\n/-- Every actually initialized N-only word is paid by the physical binary input length. -/\ntheorem initial_length (bits:List Bool) (k:Stack):((initial bits).data k).length ≤bits.length:=by\n  change (input bits k).length ≤bits.length\n  rw [input_single]\n  by_cases hk:k=originalInput <;> simp [hk]\n/-- The explicit caller-prefix front door initializes only its actual N and prescription bytes. -/\ntheorem initial_prefix_length (bits pre:List Bool) (k:Stack):\n    ((initialPrefix bits pre).data k).length ≤bits.length+pre.length:=by\n  rcases k with k|k\n  · exact SemiprimeD1StackRootNetworkRecordsResources.initial_prefix_length bits pre k\n  · change (privateView (fun _=>[]) k).length ≤bits.length+pre.length\n    rw [private_empty,List.length_nil]\n    exact Nat.zero_le _\n/-- A concrete halt bounds every successful prefix of the same deterministic actual caller. -/\ntheorem prefix_time {start finish:C.State Stack Label} (B:Nat)\n    (he:∃time ≤B,run program time start=some finish) (hh:run program 1 finish=none)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel start=some out):fuel ≤B:=by\n  obtain ⟨time,ht,he⟩:=he\n  have hf:fuel ≤time:=by\n    by_contra hn\n    have h:fuel=time+(1+(fuel-(time+1))):=by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add,hh,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- Genuine compiled standard initialization starts with N alone at the literal source entry. -/\ntheorem initial_eq (bits:List Bool):Turing.initList machine bits=configuration (initial bits):=by\n  have hi:initial bits=SemiprimeD1StackCalls.initial originalInput main bits:=by\n    unfold initial SemiprimeD1StackCalls.initial\n    rw [input_single]\n  rw [hi]\n  exact (SemiprimeD1StackCalls.initial_correct originalInput output main program bits).symm\nopen SemiprimeD1StackRootOwnerIndexBounds\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimePublicAcquiredExecution (wireCount)\nattribute [local irreducible] runBound runBoundPrefix prefixPolynomial\n/-- No successful N-only prefix passes the same source's actual final halt. -/\ntheorem prefix_fuel (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (initial bits)=some out):fuel ≤runBound bits:=\n  prefix_time _ (source_run_bounded bits hc hN) rfl fuel out hr\n/-- The actual prescribed bytes and retained tail use the same successful source's own bounded clock. -/\ntheorem prefix_fuel_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:run program fuel (initialPrefix bits (RE.prescription bits fixed tail))=some out):\n    fuel ≤runBoundPrefix bits (RE.prescription bits fixed tail).length:=\n  prefix_time _ (source_run_prefix_bounded bits hc hN fixed tail) rfl fuel out hr\n/-- Every1821allocated role, both empty input shadows, and all actual return cells are charged at every prefix. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label) (hr:run program fuel (initial bits)=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤1822*(bits.length+runBound bits):=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length _ _ (initial_length bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ _ hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:=SemiprimeD1StackRootNetworkRecordsResources.word_sum_le out.data (bits.length+fuel) hd\n  rw [stack_card] at hs\n  have ht:=prefix_fuel bits hc hN fuel out hr\n  omega\n/-- Caller-prefix bytes and both complete source banks remain included at every actual prefix. -/\ntheorem prefix_cells_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:run program fuel (initialPrefix bits (RE.prescription bits fixed tail))=some out):\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤\n      1822*(bits.length+(RE.prescription bits fixed tail).length+\n        runBoundPrefix bits (RE.prescription bits fixed tail).length):=by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel\n    (bits.length+(RE.prescription bits fixed tail).length) _ _\n    (initial_prefix_length bits (RE.prescription bits fixed tail)) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel _ _ hr\n  change out.frames.length ≤0+fuel at hf\n  have hs:=SemiprimeD1StackRootNetworkRecordsResources.word_sum_le out.data\n    (bits.length+(RE.prescription bits fixed tail).length+fuel) hd\n  rw [stack_card] at hs\n  have ht:=prefix_fuel_prefix bits hc hN fixed tail fuel out hr\n  omega\n/-- Genuine compiled certificate starts at true Turing.initList with binary N alone. -/\nnoncomputable def ownerIndexInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits):StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (configuration (X.done bits hN [] []))) (runBound bits):=by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output main program\n  have h:=source_run_bounded bits hc hN\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- Genuine caller-prefix certificate executes the same fixed program on the actual input/tail bytes. -/\nnoncomputable def ownerIndexPrefixInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool):\n    StateTransition.EvalsToInTime machine.step\n      (configuration (initialPrefix bits (RE.prescription bits fixed tail)))\n      (some (configuration (X.done bits hN fixed tail)))\n      (runBoundPrefix bits (RE.prescription bits fixed tail).length):=by\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output main program\n  have h:=source_run_prefix_bounded bits hc hN fixed tail\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\n/-- All compiled N-only prefixes count every actual data word and real fixed-alphabet return symbol. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤1822*(bits.length+runBound bits):=by\n  rw [initial_eq] at hr\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output main program fuel (initial bits)\n  have hh:=he.trans hr\n  cases hout:run program fuel (initial bits) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hout\n/-- Explicit-prefix compiled states retain the same complete source/shadow and real-return accounting. -/\ntheorem machine_prefix_cells_prefix (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits)\n    (hN:0 < bitValue bits) (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel]\n      (some (configuration (initialPrefix bits (RE.prescription bits fixed tail))))=some cfg):\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤\n      1822*(bits.length+(RE.prescription bits fixed tail).length+\n        runBoundPrefix bits (RE.prescription bits fixed tail).length):=by\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output main program fuel\n    (initialPrefix bits (RE.prescription bits fixed tail))\n  have hh:=he.trans hr\n  cases hout:run program fuel (initialPrefix bits (RE.prescription bits fixed tail)) with\n  | none=>rw [hout] at hh;cases hh\n  | some out=>\n    rw [hout] at hh\n    have hcfg:configuration out=cfg:=Option.some.inj hh\n    subst cfg\n    exact prefix_cells_prefix bits hc hN fixed tail fuel out hout\n/-- A fixed coefficient and degree precede every original N in the actual whole-source time statement. -/\ntheorem source_run_monomial:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits),∃time ≤\n      coef*(bits.length+1)^degree*2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits),\n        run program time (initial bits)=some (X.done bits hN [] []):=by\n  obtain ⟨coef,degree,hp⟩:=polynomial_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN\n  obtain ⟨time,ht,hr⟩:=source_run_bounded bits hc hN\n  have hb:runBound bits ≤coef*(bits.length+1)^degree*\n      2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBound runBoundPrefix\n    exact Nat.mul_le_mul_right _ (hp bits.length)\n  exact ⟨time,ht.trans hb,hr⟩\n/-- Actual prefix/tail bytes have fixed polynomial witnesses before N and every prescribed list. -/\ntheorem source_run_prefix_monomial:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool),∃time ≤\n      coef*(bits.length+(RE.prescription bits fixed tail).length+1)^degree*\n        2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits),\n      run program time (initialPrefix bits (RE.prescription bits fixed tail))=some (X.done bits hN fixed tail):=by\n  obtain ⟨coef,degree,hp⟩:=prefix_polynomial_monomial\n  refine ⟨coef,degree,?_⟩\n  intro bits hc hN fixed tail\n  obtain ⟨time,ht,hr⟩:=source_run_prefix_bounded bits hc hN fixed tail\n  have hb:runBoundPrefix bits (RE.prescription bits fixed tail).length ≤\n      coef*(bits.length+(RE.prescription bits fixed tail).length+1)^degree*\n        2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBoundPrefix\n    exact Nat.mul_le_mul_right _ (hp bits.length (RE.prescription bits fixed tail).length)\n  exact ⟨time,ht.trans hb,hr⟩\n/-- Each actual source step expands into at most four genuine fixed-machine statements. -/\ntheorem compile_depth (pc:Label):SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤4:=\n  SemiprimeD1StackCalls.compile_depth main (program pc)\n/-- The complete data/return cap inherits fixed polynomial witnesses without changing its actual exponent. -/\ntheorem cell_cap (n P poly coef degree E:Nat) (hp:poly ≤coef*(n+P+1)^degree) (he:1 ≤E):\n    1822*(n+P+poly*E) ≤1822*(1+coef)*(n+P+1)^(degree+1)*E:=by\n  let S:=n+P+1\n  have hs:1 ≤S:=by dsimp [S];omega\n  have hd:S^degree ≤S^(degree+1):=Nat.pow_le_pow_right hs (by omega)\n  have hself:S ≤S^(degree+1):=by\n    simpa only [pow_one] using Nat.pow_le_pow_right hs (by omega:1 ≤degree+1)\n  have hbase:n+P ≤S^(degree+1)*E:=by\n    have h0:n+P ≤S^(degree+1):=(by dsimp [S];omega:n+P ≤S).trans hself\n    exact h0.trans (by simpa only [Nat.mul_one] using Nat.mul_le_mul_left (S^(degree+1)) he)\n  have hpoly:poly*E ≤coef*S^(degree+1)*E:=\n    Nat.mul_le_mul_right E (hp.trans (Nat.mul_le_mul_left coef hd))\n  change _ ≤1822*(1+coef)*S^(degree+1)*E\n  calc\n    _ ≤1822*(S^(degree+1)*E+coef*S^(degree+1)*E):=Nat.mul_le_mul_left 1822 (Nat.add_le_add hbase hpoly)\n    _= _:=by ring\n/-- Fixed monomial witnesses bound all actual N-only data/return prefixes before original N. -/\ntheorem prefix_monomial:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (_hN:0 < bitValue bits) (fuel:Nat) (out:C.State Stack Label),\n    run program fuel (initial bits)=some out→\n      (∑k:Stack,(out.data k).length)+out.frames.length ≤coef*(bits.length+1)^degree*\n        2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n  obtain ⟨coef,degree,hp⟩:=polynomial_monomial\n  refine ⟨1822*(1+coef),degree+1,?_⟩\n  intro bits hc hN fuel out hr\n  have he:1 ≤2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hcap:1822*(bits.length+runBound bits) ≤1822*(1+coef)*(bits.length+1)^(degree+1)*\n      2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBound runBoundPrefix\n    simpa only [Nat.add_zero] using cell_cap bits.length 0 (prefixPolynomial bits.length 1) coef degree\n      (2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits))\n      (by simpa only [Nat.add_zero] using hp bits.length) he\n  exact (prefix_cells bits hc hN fuel out hr).trans hcap\n/-- Every actual caller-prefix byte and both complete banks obey fixed monomial prefix witnesses. -/\ntheorem prefix_monomial_prefix:∃coef degree:Nat,∀(bits:List Bool)\n    (_hc:SemiprimeSourceCompactBits.Compact bits) (_hN:0 < bitValue bits)\n    (fixed:List (Fin (wireCount (bitValue bits))×Bool)) (tail:List Bool) (fuel:Nat) (out:C.State Stack Label),\n    run program fuel (initialPrefix bits (RE.prescription bits fixed tail))=some out→\n      (∑k:Stack,(out.data k).length)+out.frames.length ≤\n        coef*(bits.length+(RE.prescription bits fixed tail).length+1)^degree*\n          2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n  obtain ⟨coef,degree,hp⟩:=prefix_polynomial_monomial\n  refine ⟨1822*(1+coef),degree+1,?_⟩\n  intro bits hc hN fixed tail fuel out hr\n  have he:1 ≤2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=Nat.pow_pos (by decide)\n  have hcap:1822*(bits.length+(RE.prescription bits fixed tail).length+\n      runBoundPrefix bits (RE.prescription bits fixed tail).length) ≤\n      1822*(1+coef)*(bits.length+(RE.prescription bits fixed tail).length+1)^(degree+1)*\n        2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits):=by\n    unfold runBoundPrefix\n    exact cell_cap bits.length (RE.prescription bits fixed tail).length\n      (prefixPolynomial bits.length (RE.prescription bits fixed tail).length) coef degree\n      (2^(38*SemiprimeD1StackAllDescriptorRecordRootBounds.arityCapacity bits))\n      (hp bits.length (RE.prescription bits fixed tail).length) he\n  exact (prefix_cells_prefix bits hc hN fixed tail fuel out hr).trans hcap\nend RiemannGaussian.SemiprimeD1StackRootOwnerIndexResources\n","RiemannGaussian.SemiprimeD1StackRootPacketPaddingInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPacketPaddingPrimitives\n/-! # Actual selected-key/dimension transfers with the retained source scratch -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPacketPaddingInput\nopen SemiprimeD1StackRootPacketPadding SemiprimeD1StackRootPacketPaddingView\nopen SemiprimeD1StackRootPacketPaddingPrimitives SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- Only the literal next source's two input fields are populated. -/\ndef paddingReady (root:R.Stack→List Bool) :Q.Stack→List Bool :=\n  Function.update (Function.update (fun _=>[])\n    (Q.frequencyStack (SemiprimeD1StackSourceKeyFrequency.aux .source)) (root R.output))\n    (Q.aux .exponent) (root (R.parameterStack SemiprimeD1StackRootParameters.exponent))\n/-- The two actual writes yield exactly the next real source's honest physical input bank. -/\ntheorem paddingReady_input (root:R.Stack→List Bool) :paddingReady root=\n    (Q.initial (root R.output) (root (R.parameterStack SemiprimeD1StackRootParameters.exponent))).data :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n  · cases k <;> rfl\n/-- Both restoring copies pay every actual key/dimension byte and both real returns. -/\ndef paddingCopyTime (root:R.Stack→List Bool) :Nat :=\n  5*((root R.output).length+(root (R.parameterStack SemiprimeD1StackRootParameters.exponent)).length)+8\n/-- The original producer bank is retained literally, including its reused scratch restored to empty. -/\ntheorem padding_input_run (root:R.Stack→List Bool) (hs:root R.copyScratch=[]) :\n    Runs program (paddingCopyTime root) (ctl (.copy .keys)) (data root (fun _=>[]))\n      (ctl .padding) (data root (paddingReady root)) :=by\n  let s0:Q.Stack→List Bool:=fun _=>[]\n  let s1:=Function.update s0 (Q.frequencyStack (SemiprimeD1StackSourceKeyFrequency.aux .source)) (root R.output)\n  let s2:=Function.update s1 (Q.aux .exponent) (root (R.parameterStack SemiprimeD1StackRootParameters.exponent))\n  have h0:=copy_call .keys (data root s0) (root R.output) [] rfl rfl hs\n  simp only [List.append_nil] at h0\n  change Runs program _ _ _ _ (Function.update (data root s0)\n    (paddingStack (Q.frequencyStack (SemiprimeD1StackSourceKeyFrequency.aux .source))) (root R.output)) at h0\n  rw [data_padding] at h0\n  have h1:=copy_call .dimension (data root s1) (root (R.parameterStack SemiprimeD1StackRootParameters.exponent)) [] rfl rfl hs\n  simp only [List.append_nil] at h1\n  change Runs program _ _ _ _ (Function.update (data root s1)\n    (paddingStack (Q.aux .exponent)) (root (R.parameterStack SemiprimeD1StackRootParameters.exponent))) at h1\n  rw [data_padding] at h1\n  have h:=join h0 h1\n  change Runs program _ _ _ (ctl .padding) _ at h\n  change Runs program _ _ _ _ (data root s2)\n  convert h using 1\n  unfold paddingCopyTime\n  omega\nend RiemannGaussian.SemiprimeD1StackRootPacketPaddingInput\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecords":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseParametersOriginal\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsInventory\n/-! # N-only chronological complete fresh-coefficient cache records\nThe actual phase-bank producer runs ONCE. Its actual issued-reference vector is\ncopied ONCE, physically parsed and dereferenced by the real143-role cache/Fresh\nconsumer. All85 actual Fresh words are framed into a SEPARATE actual heap. The\nsource heap/counter and the literal root old-axis header are physically retained.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecords\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace R\nexport SemiprimeD1StackRootPhaseParameters (Stack Label program input initial originalInput output heap aux)\nend R\nnamespace Q\nexport SemiprimeD1StackPhaseCacheFresh (Stack Label program initial freshStack restoreStack)\nend Q\nnamespace F\nexport SemiprimeD1StackPhaseChildContextFresh (Stack)\nend F\nnamespace I\nexport SemiprimeD1StackRootPhaseFreshRecordsInventory (role clearRole sourceHeap sourceCounter sourceReference oldHeader)\nend I\nnamespace Field\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active)\nend Field\nnamespace Body\nexport SemiprimeD1StackAssignmentBody (Stack Label code entry)\nend Body\nnamespace V\nexport SemiprimeD1StackVertexRecordStream (Stack Label code)\nend V\n/-- Fourteen actual pointer, fresh-record, independent-heap and chronological-log fields. -/\ninductive Aux where\n  | reader | pointer | fieldScratch | valid | copyScratch | record | recordScratch\n  | heap | counter | reference | counterScratch | refsHistory | refsOutput | refScratch\n  deriving DecidableEq,Repr\ninstance :Fintype Aux :=Fintype.ofList\n  [.reader,.pointer,.fieldScratch,.valid,.copyScratch,.record,.recordScratch,.heap,.counter,.reference,.counterScratch,.refsHistory,.refsOutput,.refScratch]\n  (by intro k;cases k <;> simp)\n/-- All345 actual roles include retained188, allocated143 with all alias-shadows and14 new words. -/\nabbrev Stack :=R.Stack⊕(Q.Stack⊕Aux)\n/-- Every original-N phase-source cell is retained in its literal own address. -/\ndef rootStack :R.Stack→Stack :=Sum.inl\n/-- Every allocated private client address exists, including all three new unused alias-shadows. -/\ndef cachePrivate (k:Q.Stack) :Stack :=.inr (.inl k)\n/-- Literal new pointer/record/heap/log role inclusion. -/\ndef aux (k:Aux) :Stack :=.inr (.inr k)\n/-- The client reads the ACTUAL retained source heap/counter and the ACTUALLY parsed\npointer. All other client roles keep their own private addresses. -/\ndef cacheStack :Q.Stack→Stack\n  | .inl (.inr .heap)=>rootStack R.heap\n  | .inl (.inr .counter)=>rootStack (R.aux .counter)\n  | .inl (.inr .reference)=>aux .pointer\n  | k=>cachePrivate k\n/-- Fixed left inverse shows the whole actual client map is injective despite intentional sharing. -/\ndef cacheInverse :Stack→Q.Stack\n  | .inl (.inr (.inr .heap))=>I.sourceHeap\n  | .inl (.inr (.inr .counter))=>I.sourceCounter\n  | .inr (.inr .pointer)=>I.sourceReference\n  | .inr (.inl k)=>k\n  | _=>I.sourceHeap\n/-- Actual85-word Fresh projection uses the client's SHARED restored P48 bank,\nnever its forty-eight unused private P48 shadow slots. -/\ndef freshStack (k:F.Stack) :Stack :=cacheStack (Q.freshStack k)\n/-- Persistent root old-axis header. The program writes its singleton false ONCE. -/\ndef oldHeader :Stack :=cacheStack I.oldHeader\n/-- Original binary N is the ONLY whole-entry payload. -/\ndef originalInput :Stack :=rootStack R.originalInput\n/-- Separate fresh-record heap; the input phase heap is never allocated into. -/\ndef heap :Stack :=aux .heap\n/-- Chronological issued references into the separate fresh-record heap. -/\ndef output :Stack :=aux .refsOutput\n/-- Paid whole-reference-vector copy has three disjoint literal operands. -/\ndef copyStack (i:Fin 3) :Stack :=\n  if i=0 then rootStack R.output else if i=1 then aux .reader else aux .copyScratch\n/-- Real parser consumes one actual issued unary ordinal field from the copied vector. -/\ndef fieldStack :Field.Stack→Stack\n  | .inl .input=>aux .reader | .inl .scratch=>aux .fieldScratch\n  | .inl .output=>aux .pointer | .inr _=>aux .valid\n/-- One fixed logical Fresh role is physically framed and restored at each static position. -/\ndef frameStack (i:Fin 85) (k:Fin 3) :Stack :=\n  if k=0 then freshStack (I.role i) else if k=1 then aux .record else aux .copyScratch\n/-- Separate actual record heap/counter/reference and both restoration scratch fields. -/\ndef heapStack (k:Fin 6) :Stack :=\n  if k=0 then aux .record else if k=1 then aux .heap else if k=2 then aux .recordScratch\n  else if k=3 then aux .counter else if k=4 then aux .reference else aux .counterScratch\n/-- Actual restoring body logs the issued NEW heap ordinal, not a predicted ordinal. -/\ndef bodyStack :Body.Stack→Stack\n  | .word=>aux .reference | .scratch=>aux .refScratch | .history=>aux .refsHistory\n/-- Exactly one final real reversal of the complete issued-reference history. -/\ndef reverseStack :V.Stack→Stack\n  | .ports=>aux .recordScratch | .table=>aux .refScratch\n  | .history=>aux .refsHistory | .output=>aux .refsOutput\n/--140logical client drains exclude immutable sourceheap/counter/header. Then\nthree RAW alias-shadows, currentrecord and newreference are explicitly drained.\nThe shared issued-source pointer is included exactly ONCE in the logical140. -/\ndef clearStack (i:Fin 145) :Stack :=\n  if h:i.val<140 then cacheStack (I.clearRole ⟨i.val,h⟩)\n  else if i.val=140 then cachePrivate I.sourceHeap\n  else if i.val=141 then cachePrivate I.sourceCounter\n  else if i.val=142 then cachePrivate I.sourceReference\n  else if i.val=143 then aux .record else aux .reference\n/-- Whole-source, pointer-read, actual-client, finite85-frame and finite145-drain labels. -/\ninductive Label where\n  | start | copy | seedHeader | header | parse | check | freshCall\n  | serialize (position:Fin 86) | allocate | logReference | clear (position:Fin 146)\n  | finishSeed | reverseCall | done | abort\n  | root (pc:R.Label) | cache (pc:Q.Label) | copier (pc:Fin 9) | field (pc:Field.Label)\n  | frame (i:Fin 85) (pc:Fin 11) | allocator (pc:Fin 22) | body (pc:Body.Label) | reverse (pc:V.Label)\n  deriving Fintype\n/-- ONE fixed original-N program, with no decoded bank/phase/coefficient/rank/P/value/clock operand. -/\ndef program :Label→C.Instruction Stack Label\n  | .start=>.call (.root .start) .copy\n  | .copy=>.call (.copier 0) .seedHeader\n  | .seedHeader=>.base (.push oldHeader false .header)\n  | .header=>.base (.pop (aux .reader) .finishSeed .finishSeed .parse)\n  | .parse=>.call (.field (Field.active .tagPop (none,false))) .check\n  | .check=>.base (.pop (aux .valid) .abort .abort .freshCall)\n  | .freshCall=>.call (.cache (.inl .start)) (.serialize 0)\n  | .serialize i=>if h:i.val<85 then\n      .call (.frame ⟨84-i.val,by omega⟩ 0) (.serialize ⟨i.val+1,by omega⟩)\n      else .base (.jump .allocate)\n  | .allocate=>.call (.allocator 0) .logReference\n  | .logReference=>.call (.body Body.entry) (.clear 0)\n  | .clear i=>if h:i.val<145 then\n      .base (.pop (clearStack ⟨i.val,h⟩) (.clear ⟨i.val+1,by omega⟩) (.clear i) (.clear i))\n      else .base (.jump .header)\n  | .finishSeed=>.base (.push output false .reverseCall)\n  | .reverseCall=>.call (.reverse .reverse) .done\n  | .done|.abort=>.base .halt\n  | .root pc=>SemiprimeD1StackValidationLink.instruction rootStack Label.root (R.program pc)\n  | .cache pc=>SemiprimeD1StackValidationLink.instruction cacheStack Label.cache (Q.program pc)\n  | .copier pc=>SemiprimeD1StackMultiplierLink.instruction copyStack Label.copier (SemiprimeD1StackCopy.code pc)\n  | .field pc=>SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (Field.code pc)\n  | .frame i pc=>SemiprimeD1StackMultiplierLink.instruction (frameStack i) (Label.frame i) (SemiprimeD1StackFrame.code pc)\n  | .allocator pc=>SemiprimeD1StackMultiplierLink.instruction heapStack Label.allocator (SemiprimeD1StackHeapAllocate.code pc)\n  | .body pc=>SemiprimeD1StackMultiplierLink.instruction bodyStack Label.body (Body.code pc)\n  | .reverse pc=>SemiprimeD1StackMultiplierLink.instruction reverseStack Label.reverse (V.code pc)\n/-- Complete physical payload; the mathematical views never become runtime suppliers. -/\ndef data (root:R.Stack→List Bool) (cache:Q.Stack→List Bool) (work:Aux→List Bool) :Stack→List Bool :=\n  Sum.elim root (Sum.elim cache work)\n/-- Only original binary N is initially populated across all345 physical fields. -/\ndef input (bits:List Bool) :Stack→List Bool :=data (R.input bits) (fun _=>[]) (fun _=>[])\n/-- Whole N-only source entry before original phase/grid/heap/coefficient acquisition. -/\ndef initial (bits:List Bool) :C.State Stack Label :=⟨some .start,none,none,input bits,[]⟩\n/-- Genuine fixed345-role finite machine with real finite return cells. -/\ndef machine :Turing.FinTM2 :=SemiprimeD1StackCalls.machine originalInput output .start program\n/-- Every real client role has an exact static inverse on its actual included address. -/\ntheorem cache_inverse (k:Q.Stack) :cacheInverse (cacheStack k)=k :=by\n  rcases k with k|k\n  · rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n  · rfl\n/-- Whole-client sharing does not identify two different client operands. -/\ntheorem cache_injective :Function.Injective cacheStack :=by\n  intro a b h\n  have he:=congrArg cacheInverse h\n  simpa only [cache_inverse] using he\n/-- Every original-N source field remains physically distinct. -/\ntheorem root_injective :Function.Injective rootStack :=Sum.inl_injective\n/-- The exact actual Fresh85 projection lies in private client storage; no source heap operand is framed. -/\ntheorem fresh_private (k:F.Stack) :freshStack k=cachePrivate (Q.freshStack k) :=by\n  rcases k with k|k\n  · rcases k with k|k <;> rfl\n  · rfl\n/-- Paid source-reference copy has distinct source/destination/scratch fields. -/\ntheorem copy_injective :Function.Injective copyStack :=by decide\n/-- Every physical pointer parse uses four distinct operands. -/\ntheorem field_injective :Function.Injective fieldStack :=by decide\n/-- Every85word framing call has disjoint actual input/record/restoration operands. -/\ntheorem frame_injective (i:Fin 85) :Function.Injective (frameStack i) :=by\n  intro a b h\n  fin_cases a <;> fin_cases b <;> simp [frameStack,fresh_private,cachePrivate,aux] at h ⊢\n/-- Independent fresh-record heap operands are physically distinct. -/\ntheorem heap_injective :Function.Injective heapStack :=by decide\n/-- Actual issued-reference logging has separate word/scratch/history fields. -/\ntheorem body_injective :Function.Injective bodyStack :=by decide\n/-- Exactly one final reverse has distinct actual data roles. -/\ntheorem reverse_injective :Function.Injective reverseStack :=by decide\n/-- All source/client/alias-shadow/new fields are included in the physical345 count. -/\ntheorem stack_card :Fintype.card Stack=345 :=by\n  rw [Fintype.card_sum,SemiprimeD1StackRootPhaseParameters.stack_card,Fintype.card_sum,SemiprimeD1StackPhaseCacheFresh.stack_card]\n  decide\n/-- All flags and remembered return labels are fixed finite before original N. -/\ntheorem control_finite :Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Every Boolean and actual return alphabet is fixed finite before original N. -/\ntheorem alphabets_finite (k:machine.K) :Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _ k\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecords\n","RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsEncoding\n/-! # Literal alias-preserving bank updates, physical pointer copies and record framing -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsPrimitives\nopen SemiprimeD1StackRootPhaseFreshRecords SemiprimeD1StackRootPhaseFreshRecordsEncoding\nopen SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update data_unique)\nend Link\n/-- Trace fragments compose on the SAME fixed345-role source and retain outer frames. -/\ntheorem compose {m n:Nat} {pc mid next:Label} {before middle after:Stack→List Bool}\n    (h:Runs program m pc before mid middle) (g:Runs program n mid middle next after) :\n    Runs program (m+n) pc before next after :=runs_trans program _ _ _ _ _ _ _ _ h g\n/-- A logical client change touches only the actual included client addresses.\nThe three unused raw alias-shadows and all other caller words retain their bytes. -/\ntheorem view_rel (root:R.Stack→List Bool) (before after:Q.Stack→List Bool) (w:Aux→List Bool) :\n    Link.DataRel cacheStack (view root before w) after (view root after w) :=by\n  constructor\n  · intro k;exact view_cache _ _ _ _\n  · intro k hk\n    rcases k with k|k\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k <;> first | rfl | exact (hk I.sourceHeap rfl).elim | exact (hk I.sourceCounter rfl).elim\n    · rcases k with k|k\n      · rcases k with k|k\n        · rcases k with k|k\n          · exact (hk (.inl (.inl k)) rfl).elim\n          · cases k with\n            | heap | counter | reference=>rfl\n            | reader=>exact (hk (.inl (.inr .reader)) rfl).elim\n            | depth=>exact (hk (.inl (.inr .depth)) rfl).elim\n            | referenceWork=>exact (hk (.inl (.inr .referenceWork)) rfl).elim\n            | temporary=>exact (hk (.inl (.inr .temporary)) rfl).elim\n            | fieldScratch=>exact (hk (.inl (.inr .fieldScratch)) rfl).elim\n            | output=>exact (hk (.inl (.inr .output)) rfl).elim\n            | valid=>exact (hk (.inl (.inr .valid)) rfl).elim\n        · exact (hk (.inr k) rfl).elim\n      · cases k <;> first | rfl | exact (hk I.sourceReference rfl).elim\n/-- One actual included-client write has precisely its alias-preserving whole-bank effect. -/\ntheorem update_cache (root:R.Stack→List Bool) (q:Q.Stack→List Bool) (w:Aux→List Bool)\n    (k:Q.Stack) (word:List Bool) :\n    Function.update (view root q w) (cacheStack k) word=view root (Function.update q k word) w :=by\n  have h0:=view_rel root q q w\n  have h1:=Link.data_update cacheStack cache_injective (view root q w) q (view root q w) h0 k word\n  exact Link.data_unique cacheStack (view root q w) (Function.update q k word) _ _ h1\n    (view_rel root q (Function.update q k word) w)\n/-- A caller auxiliary write other than the shared source pointer leaves client data intact. -/\ntheorem update_aux (root:R.Stack→List Bool) (q:Q.Stack→List Bool) (w:Aux→List Bool)\n    (k:Aux) (hk:k≠.pointer) (word:List Bool) :\n    Function.update (view root q w) (aux k) word=view root q (Function.update w k word) :=by\n  funext slot\n  rcases slot with slot|slot\n  · rfl\n  · rcases slot with slot|slot\n    · rfl\n    · cases k <;> cases slot <;> first | rfl | exact (hk rfl).elim\n/-- A real pointer parse writes the SAME actual source reference input, never a predicted ordinal. -/\ntheorem update_pointer (root:R.Stack→List Bool) (q:Q.Stack→List Bool) (w:Aux→List Bool) (word:List Bool) :\n    Function.update (view root q w) (aux .pointer) word=view root (Function.update q I.sourceReference word) w :=\n  update_cache root q w I.sourceReference word\n/-- The single real preserving copy consumes/reconstructs the actual complete source reference vector. -/\ntheorem copy_call (bank:Stack→List Bool) (hd:bank (aux .reader)=[]) (hs:bank (aux .copyScratch)=[]) :\n    Runs program (5*(bank (rootStack R.output)).length+4) .copy bank .seedHeader\n      (Function.update bank (aux .reader) (bank (rootStack R.output))) :=by\n  apply included_call program copyStack Label.copier copy_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) .copy .seedHeader rfl (5*(bank (rootStack R.output)).length+3)\n    (SemiprimeD1StackCopy.state 0 none (bank (rootStack R.output)) [] [])\n    (SemiprimeD1StackCopy.done (bank (rootStack R.output)) (bank (rootStack R.output)++[]))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words _ [] none\n  · constructor\n    · intro i;fin_cases i\n      · rfl\n      · exact hd\n      · exact hs\n    · intro k _;rfl\n  · constructor\n    · intro i;fin_cases i\n      · rfl\n      · simp only [List.append_nil]\n        rfl\n      · change Function.update bank (aux .reader) _ (aux .copyScratch)=[]\n        rw [Function.update_of_ne (by decide :aux .copyScratch≠aux .reader),hs]\n    · intro k hk\n      exact Function.update_of_ne (fun h=>hk 1 h.symm) _ _\n/-- Every85-word record frame pays its actual input cells, source restoration,\nrecord writes, delimiter and real return while retaining every other field. -/\ntheorem frame_call (position:Fin 86) (h:position.val<85) (bank:Stack→List Bool)\n    (hs:bank (aux .copyScratch)=[]) :\n    let i:Fin 85:=⟨84-position.val,by omega⟩\n    Runs program (6*(bank (freshStack (I.role i))).length+5) (.serialize position) bank\n      (.serialize ⟨position.val+1,by omega⟩)\n      (Function.update bank (aux .record)\n        (SemiprimeSourceHistogramKeyBits.frame (bank (freshStack (I.role i))) (bank (aux .record)))) :=by\n  dsimp only\n  let i:Fin 85:=⟨84-position.val,by omega⟩\n  apply included_call program (frameStack i) (Label.frame i) (frame_injective i)\n    SemiprimeD1StackFrame.code 0 (fun _=>rfl) (.serialize position)\n    (.serialize ⟨position.val+1,by omega⟩) (by simp only [program,dite_eq_left h];rfl)\n    (6*(bank (freshStack (I.role i))).length+4)\n    (SemiprimeD1StackFrame.state 0 none (bank (freshStack (I.role i))) (bank (aux .record)) [])\n    (SemiprimeD1StackFrame.done (bank (freshStack (I.role i)))\n      (SemiprimeSourceHistogramKeyBits.frame (bank (freshStack (I.role i))) (bank (aux .record))))\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackFrame.frame_words _ _ none\n  · constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact hs\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update bank (aux .record) _ (freshStack (I.role i))=bank (freshStack (I.role i))\n        exact Function.update_of_ne (by rw [fresh_private];simp [cachePrivate,aux]) _ _\n      · change Function.update bank (aux .record) _ (aux .record)=_\n        exact Function.update_same _ _ _\n      · change Function.update bank (aux .record) _ (aux .copyScratch)=[]\n        rw [Function.update_of_ne (by decide :aux .copyScratch≠aux .record),hs]\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 he.symm) _ _\n/-- One literal finite serialization-sentinel jump. -/\ntheorem serialization_end (bank:Stack→List Bool) :Runs program 1 (.serialize 85) bank .allocate bank :=by\n  apply one_base program _ _ (.jump .allocate) _ _ rfl\n  · rfl\n  · rfl\n/-- Every physical clear position pops ALL actual bytes and pays its own EOF read. -/\ntheorem clear_call (position:Fin 146) (h:position.val<145) (bank:Stack→List Bool) :\n    Runs program ((bank (clearStack ⟨position.val,h⟩)).length+1) (.clear position) bank\n      (.clear ⟨position.val+1,by omega⟩) (Function.update bank (clearStack ⟨position.val,h⟩) []) :=by\n  have hd:=SemiprimeD1StackPhysicalLoops.drain program (.clear position) (.clear ⟨position.val+1,by omega⟩)\n    (clearStack ⟨position.val,h⟩) (by simp only [program,dite_eq_left h]) bank (bank (clearStack ⟨position.val,h⟩))\n  simpa only [Function.update_eq_self] using hd\n/-- One literal finite cleanup-sentinel jump back to the physical pointer header. -/\ntheorem cleanup_end (bank:Stack→List Bool) :Runs program 1 (.clear 145) bank .header bank :=by\n  apply one_base program _ _ (.jump .header) _ _ rfl\n  · rfl\n  · rfl\nend RiemannGaussian.SemiprimeD1StackRootPhaseFreshRecordsPrimitives\n","RiemannGaussian.SemiprimeD1StackRootRecursiveControlBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootRecursiveControlExecution\n\n/-! # Original-input acquisition and branch share one actual polynomial clock\nThe branch cost is bounded by the size of the actual acquired parameter\nwords. No native report clock or solved-value supplier is transported.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 131072\nnamespace RiemannGaussian.SemiprimeD1StackRootRecursiveControlBounds\nopen SemiprimeD1StackRootRecursiveControl SemiprimeD1StackRootRecursiveControlEncoding\nopen SemiprimeD1StackRootRecursiveControlExecution\nopen SemiprimeBitArithmetic (bitValue)\n/-- Genuine one-input initialization of the existing parameter source. -/\ntheorem source_input (bits:List Bool) (k:P.Stack) :\n    P.input bits k=(if k=P.originalInput then bits else []) := by\n  have hi:=SemiprimeD1StackCalls.initial_correct P.originalInput P.leaf (.inl .start) P.program bits\n  have he:=hi.trans (SemiprimeD1StackRootParametersBounds.initial_eq bits)\n  exact (congrArg (fun cfg:SemiprimeD1StackRootParameters.machine.Cfg=>cfg.stk (some k)) he).symm\n/-- The controller has no second input, advised branch or prepared root metadata. -/\ntheorem initial_eq (bits:List Bool) :\n    Turing.initList machine bits=SemiprimeD1StackCalls.configuration (initial bits) := by\n  have hs:SemiprimeD1StackCalls.initial originalInput (.inl .start) bits=initial bits := by\n    apply congrArg (fun d=>(⟨some (.inl .start),none,none,d,[]⟩:C.State Stack Label))\n    funext k\n    cases k with\n    | inl k=>\n      change (if (Sum.inl k:Stack)=originalInput then bits else [])=P.input bits k\n      rw [source_input]\n      simp only [originalInput,sourceStack,Sum.inl.injEq]\n    | inr k=>rfl\n  exact (SemiprimeD1StackCalls.initial_correct originalInput output (.inl .start) program bits).symm.trans\n    (congrArg SemiprimeD1StackCalls.configuration hs)\n/-- Actual produced-word capacity follows from the source's own successful run. -/\ntheorem produced_word_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∀k:P.Stack,(P.result bits k).length ≤ bits.length+SemiprimeD1StackRootParameters.runBound bits := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackRootParametersExecution.source_run bits hc hN\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound P.program t bits.length (P.initial bits) (P.done bits)\n    (SemiprimeD1StackRootParametersBounds.initial_role_bound bits) hr\n  intro k\n  exact (hd k).trans (Nat.add_le_add_left ht bits.length)\n/-- Every actual gate operand comes from a produced source word or a physically empty fresh role. -/\ntheorem gate_input_bound (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∀k:G.Stack,((GS.initial (parentExponent bits) (values bits)).data k).length ≤\n      bits.length+SemiprimeD1StackRootParameters.runBound bits := by\n  intro k\n  rw [←initial_projection bits hc k]\n  cases he:gateStack k with\n  | inl p=>exact produced_word_bound bits hc hN p\n  | inr f=>exact Nat.zero_le _\n/-- Generic word accounting for this actual gate, independent of all original graph enumeration. -/\ntheorem gate_time_of_words (a:List Bool) (v:SemiprimeD1StackScheduleActive.Param→Nat) (C:Nat)\n    (h:∀k:G.Stack,((GS.initial a v).data k).length ≤ C) : GS.runBound a v ≤ 300*(5*C+1) := by\n  have hl:=h (.inl .leaf)\n  have hm:=h (.inl .minimum)\n  have hu:=h (.inl .levels)\n  have he:=h (.inl .edges)\n  have ha:=h (.inr .exponent)\n  change (List.replicate (v .leaf) true).length ≤ C at hl\n  change (List.replicate (v .minimum) true).length ≤ C at hm\n  change (List.replicate (v .levels) true).length ≤ C at hu\n  change (List.replicate (v .edges) true).length ≤ C at he\n  change a.length ≤ C at ha\n  simp only [List.length_replicate] at hl hm hu he\n  unfold SemiprimeD1StackRecursiveSchedule.runBound SemiprimeD1StackScheduleActiveExecution.volume\n  omega\n/-- One fixed degree-ten bound retains every actual original-input and branch operation. -/\ntheorem runBound_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    runBound bits ≤ 10^55*(bits.length+1)^10 := by\n  have hp:=SemiprimeD1StackRootParametersBounds.runBound_le bits\n  have hg:=gate_time_of_words (parentExponent bits) (values bits)\n    (bits.length+SemiprimeD1StackRootParameters.runBound bits) (gate_input_bound bits hc hN)\n  have hn:bits.length+1 ≤ (bits.length+1)^10 := by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega:1 ≤ bits.length+1) (by decide:1 ≤ 10)\n  unfold runBound\n  omega\n/-- Same actual original-input execution, not merely an equal-output report. -/\ntheorem source_run_polynomial (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    ∃t≤10^55*(bits.length+1)^10,SemiprimeD1StackCalls.run program t (initial bits)=some (done bits) := by\n  obtain ⟨t,ht,hr⟩:=source_run bits hc hN\n  exact ⟨t,ht.trans (runBound_le bits hc hN),hr⟩\n/-- Genuine finite-machine root control from original binary N alone. -/\nnoncomputable def controlInTime (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    StateTransition.EvalsToInTime machine.step (Turing.initList machine bits)\n      (some (SemiprimeD1StackCalls.configuration (done bits))) (10^55*(bits.length+1)^10) := by\n  rw [initial_eq]\n  apply SemiprimeD1StackCalls.evalsCorrect originalInput output (.inl .start) program\n  let h:=source_run_polynomial bits hc hN\n  let t:=Classical.choose h\n  have ht:=Classical.choose_spec h\n  exact ⟨⟨t,ht.2⟩,ht.1⟩\n/-- Every initial role is charged to the sole original input word. -/\ntheorem initial_role_bound (bits:List Bool) (k:Stack) : ((initial bits).data k).length ≤ bits.length := by\n  cases k with\n  | inl k=>change (P.input bits k).length ≤ bits.length;rw [source_input];split <;> simp\n  | inr k=>exact Nat.zero_le _\n/-- Successful real prefixes cannot extend beyond this same program's actual halt. -/\ntheorem prefix_fuel_le (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (initial bits)=some out) : fuel ≤ runBound bits := by\n  obtain ⟨t,ht,he⟩:=source_run bits hc hN\n  have hf:fuel ≤ t := by\n    by_contra hn\n    have h:fuel=t+(1+(fuel-(t+1))) := by omega\n    rw [h,SemiprimeD1StackReturnLink.run_add,he,Option.bind_some,\n      SemiprimeD1StackReturnLink.run_add] at hr\n    have hz:SemiprimeD1StackCalls.run program 1 (done bits)=none := rfl\n    rw [hz,Option.bind_none] at hr\n    cases hr\n  exact hf.trans ht\n/-- All119 physical roles and every actual return cell are included at every reached source prefix. -/\ntheorem prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (out:C.State Stack Label)\n    (hr:SemiprimeD1StackCalls.run program fuel (initial bits)=some out) :\n    (∑k:Stack,(out.data k).length)+out.frames.length ≤ 120*(bits.length+runBound bits+1) := by\n  have hd:=SemiprimeD1StackReturnLink.run_data_bound program fuel bits.length (initial bits) out\n    (initial_role_bound bits) hr\n  have hf:=SemiprimeD1StackCalls.run_frame_bound program fuel (initial bits) out hr\n  change out.frames.length ≤ 0+fuel at hf\n  have hs:(∑k:Stack,(out.data k).length) ≤ 119*(bits.length+fuel) := by\n    calc\n      _ ≤ ∑_k:Stack,(bits.length+fuel) := Finset.sum_le_sum (fun k _=>hd k)\n      _ = _ := by simp only [Finset.sum_const,Finset.card_univ,stack_card,smul_eq_mul]\n  have ht:=prefix_fuel_le bits hc hN fuel out hr\n  omega\n/-- The same complete inventory applies to every actual compiled original-input prefix. -/\ntheorem machine_prefix_cells (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits)\n    (fuel:Nat) (cfg:machine.Cfg)\n    (hr:(fun q=>q.bind machine.step)^[fuel] (some (Turing.initList machine bits))=some cfg) :\n    (∑k:Stack,(cfg.stk (some k)).length)+(cfg.stk none).length ≤ 120*(bits.length+runBound bits+1) := by\n  rw [initial_eq] at hr\n  have he:=SemiprimeD1StackCalls.run_correct originalInput output (.inl .start) program fuel (initial bits)\n  change (SemiprimeD1StackCalls.run program fuel (initial bits)).map SemiprimeD1StackCalls.configuration=\n    (fun q=>q.bind machine.step)^[fuel]\n      (some (SemiprimeD1StackCalls.configuration (initial bits))) at he\n  have hh:=he.trans hr\n  cases hrun:SemiprimeD1StackCalls.run program fuel (initial bits) with\n  | none=>rw [hrun] at hh;cases hh\n  | some out=>\n    rw [hrun] at hh\n    have hcfg:SemiprimeD1StackCalls.configuration out=cfg := Option.some.inj hh\n    subst cfg\n    exact prefix_cells bits hc hN fuel out hrun\n/-- A fixed polynomial includes every actual data and real-return cell. -/\ntheorem polynomial_space (bits:List Bool) (hc:SemiprimeSourceCompactBits.Compact bits) (hN:0<bitValue bits) :\n    120*(bits.length+runBound bits+1) ≤ 10^58*(bits.length+1)^10 := by\n  have hn:bits.length+1 ≤ (bits.length+1)^10 := by\n    simpa only [pow_one] using Nat.pow_le_pow_right (by omega:1 ≤ bits.length+1) (by decide:1 ≤ 10)\n  have ht:=runBound_le bits hc hN\n  omega\n/-- Every actual compiled step uses at most four fundamental commands. -/\ntheorem compile_depth (pc:Label) : SemiprimeD1StackBytecode.statementDepth (machine.m pc) ≤ 4 :=\n  SemiprimeD1StackCalls.compile_depth (.inl .start:Label) (program pc)\nend RiemannGaussian.SemiprimeD1StackRootRecursiveControlBounds\n","RiemannGaussian.SemiprimeD1StackRootScheduleHalves":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootScheduleLoops\n/-! # Seventeen real halving calls and physical root-level delivery -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackRootScheduleHalves\nopen SemiprimeD1StackRootSchedule SemiprimeD1StackRootSchedulePrimitives\nopen SemiprimeD1StackRootScheduleLoops SemiprimeD1StackProcedureTrace\n/-- The bounded remaining count appears only in proof-side static label indexing. -/\ndef index (remaining : Nat) (h : remaining≤17) : Fin 18 :=⟨17-remaining,by omega⟩\n/-- Real transfer of the final quotient into the retained root-level word. -/\ntheorem finish_levels (base : Stack→List Bool) (n : Nat) :\n    Runs program (2*n+1) (.halve 17) (clean base n) .copyFirst\n      (Function.update (clean base 0) (aux .levels) (D.unary n++base (aux .levels))) := by\n  have h:=SemiprimeD1StackPhysicalLoops.move_unary program (.halve 17) .pushLevel .copyFirst\n    (divStack .input) (aux .levels) (by decide) rfl rfl (clean base 0) n (base (aux .levels))\n  have he0:Function.update (Function.update (clean base 0) (aux .levels) (base (aux .levels)))\n      (divStack .input) (D.unary n)=clean base n:=by\n    funext k;rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · cases k <;> simp [clean,withDiv,D.contents,D.unary,aux,divStack,Function.update]\n      · cases k <;> simp [clean,withDiv,aux,divStack,Function.update]\n  have he1:Function.update (Function.update (clean base 0) (aux .levels)\n      (D.unary n++base (aux .levels))) (divStack .input) []=\n      Function.update (clean base 0) (aux .levels) (D.unary n++base (aux .levels)):=by\n    funext k;rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · cases k <;> simp [clean,withDiv,D.contents,D.unary,aux,divStack,Function.update]\n      · cases k <;> simp [clean,withDiv,aux,divStack,Function.update]\n  dsimp only [D.unary] at he0 he1\n  rw [he0,he1] at h\n  exact h\n/-- Every one of the fixed seventeen divisions is an actual included call;\nall discarded remainders and copied quotient cells are physically paid. -/\ntheorem halves (base : Stack→List Bool) (remaining : Nat) (hr : remaining≤17) (n : Nat) :\n    ∃t≤10000*(n+1)*(remaining+1),Runs program t (.halve (index remaining hr))\n      (clean base n) .copyFirst\n      (Function.update (clean base 0) (aux .levels) (D.unary (n/2^remaining)++base (aux .levels))) := by\n  induction remaining generalizing n with\n  | zero=>\n    refine ⟨2*n+1,by omega,?_⟩\n    have he:index 0 hr=(17:Fin 18):=by apply Fin.ext;rfl\n    rw [he,pow_zero,Nat.div_one]\n    exact finish_levels base n\n  | succ r ih=>\n    have hlt:17-(r+1)<17:=by omega\n    let p:Fin 17:=⟨17-(r+1),hlt⟩\n    have hc:program (.halve (index (r+1) hr))=.call (.division Div.entry) (.clearRemainder (.half p)):=by\n      simp [program,index,p,show 16-r<17 by omega]\n    obtain ⟨td,hd,hdiv⟩:=division_call (.halve (index (r+1) hr)) (.clearRemainder (.half p)) hc base n\n    have hm:=cleanup_move (.half p) base (n/2) (n%2)\n    have hp:afterMove (.half p)=.halve (index r (by omega)):=by\n      apply congrArg Label.halve\n      apply Fin.ext\n      dsimp [afterMove,p,index]\n      omega\n    rw [hp] at hm\n    obtain ⟨tr,ht,hrec⟩:=ih (by omega) (n/2)\n    have h:=join (join hdiv hm) hrec\n    have hq:(n/2)/2^r=n/2^(r+1):=by rw [Nat.div_div_eq_div_mul,pow_succ']\n    rw [hq] at h\n    refine ⟨td+((n%2+1)+(2*(n/2)+1))+tr,?_,h⟩\n    have hm2:n%2<2:=Nat.mod_lt n (by decide)\n    have hqn:n/2≤n:=Nat.div_le_self n 2\n    have ht':tr≤10000*(n+1)*(r+1):=ht.trans (Nat.mul_le_mul_right _ (Nat.mul_le_mul_left _ (by omega)))\n    nlinarith\nend RiemannGaussian.SemiprimeD1StackRootScheduleHalves\n","RiemannGaussian.SemiprimeD1StackRootSchedulePrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootSchedule\n/-! # Literal root-schedule copies, writes and actual divider calls -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1StackRootSchedulePrimitives\nopen SemiprimeD1StackRootSchedule SemiprimeD1StackProcedureTrace\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Replace only the actual six physical divider fields. -/\ndef withDiv (base : Stack→List Bool) (componentData : D.Stack→List Bool) : Stack→List Bool\n  | .inr (.inl k)=>componentData k | k=>base k\n/-- Clean actual division input; the two-marker divisor was physically seeded. -/\ndef clean (base : Stack→List Bool) (n : Nat) : Stack→List Bool :=\n  withDiv base (D.contents (D.unary n) (D.unary 2) [] [] [] [])\n/-- Size-loop input with one actual accumulated metadata destination. -/\ndef ready (base : Stack→List Bool) (minimum : Bool) (n : Nat) (tail : List Bool) : Stack→List Bool :=\n  clean (Function.update base (sizeOutput minimum) tail) n\n/-- Concatenate two actual fragments, retaining every real outer frame. -/\ntheorem join {m n : Nat} {pc mid next : Label} {before between after : Stack→List Bool}\n    (h : Runs program m pc before mid between) (g : Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- One physically executed literal write. -/\ntheorem push (pc next : Label) (key : Stack) (d : Stack→List Bool)\n    (hc : program pc=.base (.push key true next)) :\n    Runs program 1 pc d next (Function.update d key (true::d key)) := by\n  apply one_base program pc next (.push key true next) _ _ hc <;> rfl\n/-- A bounded static chain accounts for EVERY actual marker push. All concrete\nuses have fixed lengths20,8,4,2 before N; the machine never receives this chain. -/\ntheorem push_chain (phase : Nat→Label) (limit : Nat) (key : Stack)\n    (hc : ∀i<limit,program (phase i)=.base (.push key true (phase (i+1))))\n    (n start : Nat) (hbound : start+n≤limit) (d : Stack→List Bool) :\n    Runs program n (phase start) d (phase (start+n))\n      (Function.update d key (D.unary n++d key)) := by\n  induction n generalizing start d with\n  | zero=>simpa only [Nat.add_zero,D.unary,List.replicate_zero,List.nil_append,Function.update_eq_self] using runs_refl program (phase start) d\n  | succ n ih=>\n    have h0:=push (phase start) (phase (start+1)) key d (hc start (by omega))\n    have h1:=ih (start+1) (by omega) (Function.update d key (true::d key))\n    have h:=join h0 h1\n    have he:Function.update (Function.update d key (true::d key)) key\n        (D.unary n++(Function.update d key (true::d key)) key)=\n      Function.update d key (D.unary (n+1)++d key) := by\n      funext k\n      by_cases hk:k=key\n      · subst k\n        simp only [Function.update_self]\n        exact SemiprimeD1StackUnaryDivmod.unary_bump n (d key)\n      · simp only [Function.update_of_ne hk]\n    rw [he] at h\n    have ht:1+n=n+1:=by omega\n    have hp:start+1+n=start+(n+1):=by omega\n    rw [ht,hp] at h\n    exact h\n/-- One actual preserving copy, allowing the second level block to append to\nan existing exponent. No old bank is synthesized or silently reset. -/\ntheorem copy_call (kind : Fin 3) (pc next : Label)\n    (hc : program pc=.call (.copy kind 0) next) (d : Stack→List Bool)\n    (hz : d (aux .scratch)=[]) :\n    Runs program (5*(d (copySource kind)).length+4) pc d next\n      (Function.update d (copyTarget kind) (d (copySource kind)++d (copyTarget kind))) := by\n  let xs:=d (copySource kind)\n  let ys:=d (copyTarget kind)\n  have hin:Link.DataRel (copyStack kind) d (SemiprimeD1StackCopy.state 0 none xs ys []).store d:=by\n    constructor\n    · intro k;fin_cases k\n      · rfl\n      · rfl\n      · exact hz\n    · intro k _;rfl\n  have hout:=Link.data_update (copyStack kind) (copy_injective kind) _ _ _ hin (1:Fin 3) (xs++ys)\n  have he:Function.update (SemiprimeD1StackCopy.state 0 none xs ys []).store 1 (xs++ys)=\n      (SemiprimeD1StackCopy.done xs (xs++ys)).store:=by funext k;fin_cases k <;> rfl\n  rw [he] at hout\n  exact included_call program (copyStack kind) (Label.copy kind) (copy_injective kind)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) pc next hc (5*xs.length+3)\n    (SemiprimeD1StackCopy.state 0 none xs ys []) (SemiprimeD1StackCopy.done xs (xs++ys))\n    d _ rfl rfl (SemiprimeD1StackCopy.copy_words xs ys none) hin hout\n/-- The literal full unary divider is executed on the actual input and two\nphysical divisor markers. Its quotient/remainder are never initialized as advice. -/\ntheorem division_call (pc next : Label) (hc : program pc=.call (.division Div.entry) next)\n    (base : Stack→List Bool) (n : Nat) :\n    ∃t≤100*(n+3)+1,Runs program t pc (clean base n) next\n      (withDiv base (D.contents [] (D.unary 2) [] [] (D.unary (n/2)) (D.unary (n%2)))) := by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackUnaryDivmodBytecode.divide_run n 2\n  refine ⟨t+1,by omega,?_⟩\n  apply included_call program divStack Label.division div_injective Div.code Div.entry (fun _=>rfl)\n    pc next hc t ⟨some Div.entry,none,D.contents (D.unary n) (D.unary 2) [] [] [] []⟩\n    ⟨none,none,D.contents [] (D.unary 2) [] [] (D.unary (n/2)) (D.unary (n%2))⟩ _ _ rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · exact (hk k rfl).elim\n        · rfl\nend RiemannGaussian.SemiprimeD1StackRootSchedulePrimitives\n","RiemannGaussian.SemiprimeD1StackRootSelectionAcquire":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackRootNetworkRowsOriginal\nimport RiemannGaussian.SemiprimeD1StackRootParametersOriginal\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireOriginal\n/-! # Binary N alone to the original complete selected-key vector\nThe real row source, real root-parameter source and real whole selection\nsource execute once each. Four preserving copies connect their physical\nwords. The shared copy scratch is an allocated selection-source word; all\n2114 roles remain counted. No row, graph, count, dimension, selected prefix,\ndictionary, score or answer is a physical input.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackRootSelectionAcquire\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace R\nexport SemiprimeD1StackRootNetworkRows (Stack Label program input initial originalInput output stack_card)\nexport SemiprimeD1StackRootNetworkRowsOriginal (leftCount)\nend R\nnamespace P\nexport SemiprimeD1StackRootParameters (Stack Label program initial originalInput exponent stack_card)\nend P\nnamespace Q\nexport SemiprimeD1StackSourceSelectionAcquire\n  (Stack Label program initial occurrenceStack alphabetStack keyStack copyScratch stack_card)\nend Q\n/-- Every actual retained row/parameter/selection source role is allocated. -/\nabbrev Stack :=R.Stack⊕(P.Stack⊕Q.Stack)\n/-- Complete real original-N row/record/index bank. -/\ndef rootStack :R.Stack→Stack :=Sum.inl\n/-- Complete real original-N scheduling bank. -/\ndef parameterStack (k:P.Stack) :Stack :=.inr (.inl k)\n/-- Complete real row-to-selected-key acquisition bank. -/\ndef acquisitionStack (k:Q.Stack) :Stack :=.inr (.inr k)\n/-- The actual already allocated selection copy scratch is reused before its source call. -/\ndef copyScratch :Stack :=acquisitionStack Q.copyScratch\n/-- Four fixed physical input handoffs; no input-derived address occurs. -/\ninductive Copy where | number | rows | owners | dimension deriving DecidableEq,Repr\ninstance :Fintype Copy :=Fintype.ofList [.number,.rows,.owners,.dimension] (by intro k;cases k <;> simp)\n/-- Every handoff reads an actual input or actual stopped producer word. -/\ndef copySource :Copy→Stack\n  | .number=>rootStack R.originalInput\n  | .rows=>rootStack R.output\n  | .owners=>rootStack R.leftCount\n  | .dimension=>parameterStack P.exponent\n/-- Only the next real source's literal physical inputs are populated. -/\ndef copyTarget :Copy→Stack\n  | .number=>parameterStack P.originalInput\n  | .rows=>acquisitionStack (Q.occurrenceStack .rows)\n  | .owners=>acquisitionStack (Q.occurrenceStack .number)\n  | .dimension=>acquisitionStack (Q.alphabetStack (SemiprimeD1StackSourceAlphabet64.aux .source))\n/-- Real preserving copies use three distinct physical words. -/\ndef copyStack (site:Copy) (k:Fin 3) :Stack :=\n  if k=0 then copySource site else if k=1 then copyTarget site else copyScratch\n/-- Fixed finite whole-source control, independent of N and every derived value. -/\ninductive Control where | copy (site:Copy) | parameters | root | acquire | done\n  deriving DecidableEq,Fintype\n/-- Actual component and copy return labels are finite before the whole input family. -/\ninductive Label where\n  | local (pc:Control) | root (pc:R.Label) | parameters (pc:P.Label)\n  | acquire (pc:Q.Label) | copy (site:Copy) (pc:Fin 9)\n  deriving Fintype\nlocal notation \"ctl\" => Label.local\n/-- Exact real continuation of every paid preserving copy. -/\ndef copyNext :Copy→Label\n  | .number=>ctl .parameters\n  | .rows=>ctl (.copy .owners)\n  | .owners=>ctl (.copy .dimension)\n  | .dimension=>ctl .acquire\n/-- One finite program acquires rows/counts/dimension and every original selected key from N alone. -/\ndef program :Label→C.Instruction Stack Label\n  | .local (.copy site)=>.call (.copy site 0) (copyNext site)\n  | .local .parameters=>.call (.parameters (.inl .start)) (ctl .root)\n  | .local .root=>.call (.root (.inl .start)) (ctl (.copy .rows))\n  | .local .acquire=>.call (.acquire (.local .start)) (ctl .done)\n  | .local .done=>.base .halt\n  | .root pc=>SemiprimeD1StackValidationLink.instruction rootStack Label.root (R.program pc)\n  | .parameters pc=>SemiprimeD1StackValidationLink.instruction parameterStack Label.parameters (P.program pc)\n  | .acquire pc=>SemiprimeD1StackValidationLink.instruction acquisitionStack Label.acquire (Q.program pc)\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction\n      (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n/-- All2114 actual source/cache/output/shadow words are included in the physical boundary. -/\ndef data (root:R.Stack→List Bool) (parameters:P.Stack→List Bool) (acquisition:Q.Stack→List Bool) :Stack→List Bool :=\n  Sum.elim root (Sum.elim parameters acquisition)\n/-- Sole actual input is binary N; every derived bank starts genuinely empty. -/\ndef input (bits:List Bool) :Stack→List Bool :=data (R.input bits) (fun _=>[]) (fun _=>[])\n/-- The whole N-only source starts by really copying N before either producer executes. -/\ndef initial (bits:List Bool) :C.State Stack Label :=\n  ⟨some (ctl (.copy .number)),none,none,input bits,[]⟩\n/-- Actual sole input address is inherited from the original row source. -/\ndef originalInput :Stack :=rootStack R.originalInput\n/-- Actual compact selected-key vector remains in the executed acquisition bank. -/\ndef output :Stack :=acquisitionStack (Q.keyStack (SemiprimeD1StackSourceSelectedKeys.aux .output))\n/-- One genuine fixed finite original-binary-input machine. -/\ndef machine :Turing.FinTM2 :=SemiprimeD1StackCalls.machine originalInput output (ctl (.copy .number)) program\n/-- All actual preserving-copy operands remain distinct, including the reused scratch. -/\ntheorem copy_injective (site:Copy) :Function.Injective (copyStack site) :=by cases site <;> decide\n/-- All2114 physical data roles, including every unused shadow, remain counted. -/\ntheorem stack_card :Fintype.card Stack=2114 :=by\n  rw [Fintype.card_sum,R.stack_card,Fintype.card_sum,P.stack_card,Q.stack_card]\n/-- No graph, count, evaluator, continuation or natural value inhabits runtime control. -/\ntheorem control_finite :Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Data and actual return alphabets are fixed finite before all original N. -/\ntheorem alphabets_finite :∀k,Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackRootSelectionAcquire\n","RiemannGaussian.SemiprimeD1StackScheduleActive":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackUnarySumLessBytecode\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1Schedule\n\n/-! # Literal original active-call guard\nAll four bounded metadata counters live on Boolean stacks. Three actual\ncomparisons, preserving copies and physical verdict reads replace the native\nactive predicate. Acquiring those counters remains the caller's obligation.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackScheduleActive\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace Less\nexport SemiprimeD1StackUnarySumLess (Stack contents)\nexport SemiprimeD1StackUnarySumLessBytecode (Label code entry)\nend Less\n/-- Four retained bounded-metadata operands. -/\ninductive Param where\n  | leaf | minimum | levels | edges\n  deriving DecidableEq,Repr\ninstance : Fintype Param where\n  elems := {.leaf,.minimum,.levels,.edges}\n  complete := by intro k;cases k <;> simp\n/-- Ten fixed Boolean roles, including every comparator and copy work stack. -/\ninductive Stack where\n  | leaf | minimum | levels | edges | left | right | limit | valid | scratch | output\n  deriving DecidableEq,Repr\ninstance : Fintype Stack where\n  elems := {.leaf,.minimum,.levels,.edges,.left,.right,.limit,.valid,.scratch,.output}\n  complete := by intro k;cases k <;> simp\n/-- The three fixed checks, independent of any input sizes. -/\ninductive Test where\n  | leaf | minimum | maximum\n  deriving DecidableEq,Repr\ninstance : Fintype Test where\n  elems := {.leaf,.minimum,.maximum}\n  complete := by intro k;cases k <;> simp\n/-- Fixed phases of the three actual comparison invocations. -/\ninductive Control where\n  | left (test:Test) | right (test:Test) | compare (test:Test) | branch (test:Test)\n  | emit (value:Bool) | done\n  deriving DecidableEq,Fintype,Repr\n/-- Included literal copy and comparator labels. -/\nabbrev Label := Control ⊕ (((Test×Bool)×Fin 9) ⊕ (Test×Less.Label))\n/-- Retained parameter stack associated with a metadata field. -/\ndef paramStack : Param→Stack\n  | .leaf=>.leaf | .minimum=>.minimum | .levels=>.levels | .edges=>.edges\n/-- Literal operand choice for each of the three strict comparisons. -/\ndef operand : Test→Bool→Param\n  | .leaf,false=>.leaf | .leaf,true=>.edges\n  | .minimum,false=>.levels | .minimum,true=>.minimum\n  | .maximum,false=>.edges | .maximum,true=>.levels\n/-- Actual preserving-copy operands, with no numerical control. -/\ndef copyStack (test:Test) (right:Bool) (k:Fin 3) : Stack :=\n  if k=0 then paramStack (operand test right)\n  else if k=1 then if right then .limit else .left else .scratch\n/-- Four real consuming-comparator roles; its spare summand is physically empty. -/\ndef lessStack : Less.Stack→Stack\n  | .left=>.left | .right=>.right | .limit=>.limit | .valid=>.valid\n/-- Included copy entry and continuation labels. -/\ndef copyLabel (test:Test) (right:Bool) (pc:Fin 9) : Label := .inr (.inl ((test,right),pc))\n/-- Included actual comparator labels. -/\ndef lessLabel (test:Test) (pc:Less.Label) : Label := .inr (.inr (test,pc))\n/-- Finite verdict routing implements the conjunction without an arithmetic predicate. -/\ndef afterCheck : Test → Bool → Control\n  | .leaf,true=>.left .minimum | .minimum,false=>.left .maximum\n  | .maximum,false=>.emit true | _,_=>.emit false\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- One fixed literal guard program for every prepared metadata instance. -/\ndef program : Label→C.Instruction Stack Label\n  | .inl (.left test)=>.call (copyLabel test false 0) (ctl (.right test))\n  | .inl (.right test)=>.call (copyLabel test true 0) (ctl (.compare test))\n  | .inl (.compare test)=>.call (lessLabel test Less.entry) (ctl (.branch test))\n  | .inl (.branch test)=>.base (.pop .valid (ctl (.emit false))\n      (ctl (afterCheck test false)) (ctl (afterCheck test true)))\n  | .inl (.emit value)=>.base (.push .output value (ctl .done))\n  | .inl .done=>.base .halt\n  | .inr (.inl ((test,right),pc))=>SemiprimeD1StackMultiplierLink.instruction\n      (copyStack test right) (copyLabel test right) (SemiprimeD1StackCopy.code pc)\n  | .inr (.inr (test,pc))=>SemiprimeD1StackMultiplierLink.instruction\n      lessStack (lessLabel test) (Less.code pc)\n/-- Exact physical payload; comparator spare and copy scratch are explicitly empty. -/\ndef data (words:Param→List Bool) (left limit valid out:List Bool) : Stack→List Bool\n  | .leaf=>words .leaf | .minimum=>words .minimum | .levels=>words .levels | .edges=>words .edges\n  | .left=>left | .limit=>limit | .valid=>valid | .output=>out | _=>[]\n/-- Original metadata counters are payload, never numerical internal registers. -/\ndef words (leaf minimum levels edges:Nat) : Param→List Bool\n  | .leaf=>List.replicate leaf true | .minimum=>List.replicate minimum true\n  | .levels=>List.replicate levels true | .edges=>List.replicate edges true\n/-- Prepared guard input has no advised branch or verdict. -/\ndef initial (leaf minimum levels edges:Nat) : C.State Stack Label :=\n  ⟨some (ctl (.left .leaf)),none,none,data (words leaf minimum levels edges) [] [] [] [],[]⟩\n/-- Fixed genuine finite Boolean-stack guard machine. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.leaf Stack.output\n  (ctl (.left .leaf)) program\n/-- Preserving-copy operands never alias. -/\ntheorem copyStack_injective (test:Test) (right:Bool) : Function.Injective (copyStack test right) := by\n  cases test <;> cases right <;> decide\n/-- The consuming comparator has four distinct physical operands. -/\ntheorem lessStack_injective : Function.Injective lessStack := by decide\n/-- Every physical data role is included in storage accounting. -/\ntheorem stack_card : Fintype.card Stack=10 := by decide\n/-- Every actual alphabet, including real return labels, is finite. -/\ntheorem alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\n/-- Internal state contains only finite read and return-label flags. -/\ntheorem control_finite : Finite machine.σ := SemiprimeD1StackCalls.control_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackScheduleActive\n","RiemannGaussian.SemiprimeD1StackSourceAlphabet64Colours":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Digits\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\n/-! # Actual six-bit compact-colour normalization and paid row framing -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceAlphabet64Colours\nopen SemiprimeD1StackSourceAlphabet64 SemiprimeD1StackSourceAlphabet64Encoding\nopen SemiprimeD1StackSourceAlphabet64Primitives SemiprimeD1StackSourceAlphabet64Digits\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Six actual active words replace only their physical addresses in an arbitrary retained caller bank. -/\ndef view (base:Stack→List Bool) (bits raw tr col buf hist:List Bool) :Stack→List Bool\n  | .inr .bitsReverse=>bits | .inr .colourRaw=>raw | .inr .trimScratch=>tr\n  | .inr .colour=>col | .inr .frameBuffer=>buf | .inr .rowHistory=>hist | k=>base k\n/-- One real physical bitsReverse write changes only that word. -/\ntheorem update_bits (base:Stack→List Bool) (bits raw tr col buf hist next:List Bool) :\n    Function.update (view base bits raw tr col buf hist) (aux .bitsReverse) next=\n      view base next raw tr col buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One real physical colourRaw write changes only that word. -/\ntheorem update_raw (base:Stack→List Bool) (bits raw tr col buf hist next:List Bool) :\n    Function.update (view base bits raw tr col buf hist) (aux .colourRaw) next=\n      view base bits next tr col buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One real physical trimScratch write changes only that word. -/\ntheorem update_tr (base:Stack→List Bool) (bits raw tr col buf hist next:List Bool) :\n    Function.update (view base bits raw tr col buf hist) (aux .trimScratch) next=\n      view base bits raw next col buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One real physical colour write changes only that word. -/\ntheorem update_col (base:Stack→List Bool) (bits raw tr col buf hist next:List Bool) :\n    Function.update (view base bits raw tr col buf hist) (aux .colour) next=\n      view base bits raw tr next buf hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One real physical frameBuffer write changes only that word. -/\ntheorem update_buf (base:Stack→List Bool) (bits raw tr col buf hist next:List Bool) :\n    Function.update (view base bits raw tr col buf hist) (aux .frameBuffer) next=\n      view base bits raw tr col next hist :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One real physical rowHistory write changes only that word. -/\ntheorem update_hist (base:Stack→List Bool) (bits raw tr col buf hist next:List Bool) :\n    Function.update (view base bits raw tr col buf hist) (aux .rowHistory) next=\n      view base bits raw tr col buf next :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- Every complete physical six-bit block is read, compacted, framed and logged;\nall thirty caller/source/power/ID words outside these six live addresses are retained. -/\ntheorem colour_run (base:Stack→List Bool) (bits tail hist:List Bool) (hlen:bits.length=6)\n    (hl:base (aux .trimLeft)=[]) (hr:base (aux .trimRight)=[]) (hs:base (aux .frameScratch)=[]) :\n    ∃q ≤ 200,Runs program q .colourStart (view base (bits++tail) [] [] [] [] hist) .colourStart\n      (view base tail [] [] [] [] ((frame (compact bits.reverse) []).reverse++hist)) :=by\n  let col:=compact bits.reverse\n  have h0:Runs program 1 .colourStart (view base (bits++tail) [] [] [] [] hist)\n      (.readColour 0) (view base (bits++tail) [] [] [] [] hist):=by\n    cases bits with\n    | nil=>simp only [List.length_nil] at hlen;omega\n    | cons b bits=>\n      exact SemiprimeD1StackPhysicalLoops.peek_nonempty program .colourStart .reverseRow\n        (.readColour 0) (aux .bitsReverse) rfl _ b (bits++tail) rfl\n  have h1:=read_colour 6 0 rfl (view base (bits++tail) [] [] [] [] hist) bits tail hlen rfl\n  rw [update_bits,update_raw] at h1\n  change Runs program 13 (.readColour 0) _ .reverseColour (view base tail (bits.reverse++[]) [] [] [] hist) at h1\n  rw [List.append_nil] at h1\n  have h2:=reverse_call .colour .reverseColour (.normalize .colour) rfl\n    (view base tail bits.reverse [] [] [] hist)\n  change Runs program (2*bits.reverse.length+3) .reverseColour _ (.normalize .colour)\n    (Function.update (Function.update (view base tail bits.reverse [] [] [] hist) (aux .colourRaw) [])\n      (aux .trimScratch) (bits.reverse.reverse++[])) at h2\n  rw [update_raw,update_tr,List.reverse_reverse,List.append_nil] at h2\n  have h3:=trim_call .colour (view base tail [] bits [] [] hist) hl hr\n  change Runs program (SemiprimeD1StackReduceExecution.trimTime bits+1) (.normalize .colour) _ .frameColour\n    (Function.update (Function.update (view base tail [] bits [] [] hist) (aux .trimScratch) [])\n      (aux .colour) (SemiprimeD1StackReduceExecution.trimReverse bits++[])) at h3\n  have ht:=trim_reverse bits.reverse\n  rw [List.reverse_reverse] at ht\n  rw [update_tr,update_col,List.append_nil,ht] at h3\n  have h4:=frame_call .colour .frameColour .reverseColourFrame rfl (view base tail [] [] col [] hist) hs\n  rw [update_buf] at h4\n  change Runs program (6*col.length+5) .frameColour _ .reverseColourFrame\n    (view base tail [] [] col (frame col []) hist) at h4\n  have h5:=reverse_call .colourFrame .reverseColourFrame .clearColour rfl\n    (view base tail [] [] col (frame col []) hist)\n  change Runs program (2*(frame col []).length+3) .reverseColourFrame _ .clearColour\n    (Function.update (Function.update (view base tail [] [] col (frame col []) hist) (aux .frameBuffer) [])\n      (aux .rowHistory) ((frame col []).reverse++hist)) at h5\n  rw [update_buf,update_hist] at h5\n  have h6:=SemiprimeD1StackPhysicalLoops.drain program .clearColour .colourStart (aux .colour) rfl\n    (view base tail [] [] col [] ((frame col []).reverse++hist)) col\n  rw [update_col,update_col] at h6\n  have hall:=compose (compose (compose (compose (compose (compose h0 h1) h2) h3) h4) h5) h6\n  refine ⟨_,?_,hall⟩\n  have hc:col.length ≤ 6:=(SemiprimeSourceCompactBits.trim_length bits.reverse).trans (by rw [List.length_reverse,hlen])\n  have hp:=SemiprimeD1StackReduceExecution.trimTime_le bits\n  rw [SemiprimeSourceHistogramKeyBits.frame_length,List.length_nil,List.length_reverse,hlen] at *\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceAlphabet64Colours\n","RiemannGaussian.SemiprimeD1StackSourceEnvironmentView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentExtend\n/-! # Literal physical boundary stores for retained source prefix environments -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceEnvironmentView\nopen SemiprimeD1StackSourceEnvironment SemiprimeD1StackSourceEnvironmentExtend\n/-- All25words at source boundaries; every temporary not listed is physically EMPTY. -/\ndef view (dict key chosen q pfx reader reversed found lookupReader out:List Bool) :Stack→List Bool :=\n  Sum.elim (L.data q lookupReader [] [] [] [] [] out) (fun k=>match k with\n    | .dictionary=>dict | .nextKey=>key | .chosenID=>chosen | .prefix=>pfx | .reader=>reader\n    | .reversedPrefix=>reversed | .found=>found | _=>[])\n/-- One actual dictionary update retains every other physical source/cache/lookup word. -/\ntheorem view_dictionary (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .dictionary) word=\n      view word key chosen q pfx reader reversed found lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual nextKey update retains every other physical source/cache/lookup word. -/\ntheorem view_nextKey (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .nextKey) word=\n      view dict word chosen q pfx reader reversed found lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual chosenID update retains every other physical source/cache/lookup word. -/\ntheorem view_chosenID (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .chosenID) word=\n      view dict key word q pfx reader reversed found lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual prefix update retains every other physical source/cache/lookup word. -/\ntheorem view_prefix (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .prefix) word=\n      view dict key chosen q word reader reversed found lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual reader update retains every other physical source/cache/lookup word. -/\ntheorem view_reader (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .reader) word=\n      view dict key chosen q pfx word reversed found lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual reversedPrefix update retains every other physical source/cache/lookup word. -/\ntheorem view_reversedPrefix (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .reversedPrefix) word=\n      view dict key chosen q pfx reader word found lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual found update retains every other physical source/cache/lookup word. -/\ntheorem view_found (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (aux .found) word=\n      view dict key chosen q pfx reader reversed word lookupReader out :=by\n  funext k\n  rcases k with k|k\n  · rfl\n  · cases k <;> rfl\n/-- One actual lookup-reader update retains every private environment/prefix word. -/\ntheorem view_lookup_reader (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (lookupStack (.inr .reader)) word=\n      view dict key chosen q pfx reader reversed found word out :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · rfl\n/-- One actual lookup-output update retains every private environment/prefix word. -/\ntheorem view_lookup_output (dict key chosen q pfx reader reversed found lookupReader out word:List Bool) :\n    Function.update (view dict key chosen q pfx reader reversed found lookupReader out) (lookupStack (.inr .output)) word=\n      view dict key chosen q pfx reader reversed found lookupReader word :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · rfl\n/-- Every extension work field is actually empty at the literal clean boundary. -/\ntheorem view_clear (dict key chosen q pfx reader reversed found lookupReader out:List Bool) :\n    ExtendClear (view dict key chosen q pfx reader reversed found lookupReader out) :=by\n  intro k hk\n  simp only [List.mem_cons,List.not_mem_nil,or_false] at hk\n  rcases hk with h|h|h|h|h|h|h <;> subst k <;> rfl\n/-- Source initialization equals this literal all25word view without any next-key/dictionary answer. -/\ntheorem input_eq (pfx:List Bool) :input pfx=view [] [] [] [] pfx [] [] [] [] [] :=by\n  funext k\n  rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\nend RiemannGaussian.SemiprimeD1StackSourceEnvironmentView\n","RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectSpec\nimport RiemannGaussian.SemiprimeD1StackSourceEnvironmentOriginal\nimport RiemannGaussian.SemiprimeSourceHistogramDictRefinement\nimport RiemannGaussian.SemiprimeSourceHistogramAcquiredSums\n/-! # Original incidence-only query meaning for the prepared selector\nThese mathematical identities bind actual compact owner/factor keys and actual\nprefix IDs to the OLDoriginal D1 query, retaining every ordered incidence pair.\nNo histogram, graph function, score function or environment getter is an operand\nof the literal controller. The physical47source will supply its own trace and\nbinary-result identity, once its source group is FINAL.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectMeaning\nopen SemiprimeBitArithmetic (bitValue)\nopen SemiprimeSourceIncidenceCountFormula (classifiedCount)\nnamespace Keys\nexport SemiprimeSourceHistogramHeadRefinement (numberKey numberKey_value numberKey_compact)\nend Keys\n/-- Mathematical original prefix ID label; code reads its actual marked dictionary payload instead. -/\ndef idLabel (ids:List (List Bool)) (i:Nat) :Nat :=bitValue (SemiprimeSourceHistogramPrefix.expected ids i)\n/-- Every actual original prefix/default payload remains an acquired candidate ID. -/\ntheorem expected_mem (r a:Nat) [NeZero r] (ids:List (List Bool))\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) (i:Nat) :\n    SemiprimeSourceHistogramPrefix.expected ids i∈(SemiprimeSourceCompactWordBank.acquire r a).ids :=by\n  have h:=SemiprimeSourceHistogramDictRefinement.stored_mem r a ids hf (Keys.numberKey i)\n  rw [SemiprimeSourceHistogramPrefix.stored_eq ids _ (Keys.numberKey_compact i),Keys.numberKey_value] at h\n  exact h\n/-- Every expected original/default ID is canonical, including zero[]. -/\ntheorem expected_compact (ids:List (List Bool)) (i:Nat) :\n    SemiprimeSourceCompactBits.Compact (SemiprimeSourceHistogramPrefix.expected ids i) :=\n  SemiprimeSourceCompactBits.trim_compact _\n/-- Actual compact payload decode equals the exact original finite environment label. -/\ntheorem expected_decode (r a:Nat) [NeZero r] (ids:List (List Bool)) (i:Nat) :\n    SemiprimeSourceWordBankSemantics.decode r a (SemiprimeSourceHistogramPrefix.expected ids i)=\n      SemiprimeSourceHistogramDictRefinement.labels r a ids i :=by\n  have h:=SemiprimeSourceHistogramDictRefinement.stored_decode r a ids (Keys.numberKey i) (Keys.numberKey_compact i)\n  rw [SemiprimeSourceHistogramPrefix.stored_eq ids _ (Keys.numberKey_compact i),Keys.numberKey_value] at h\n  exact h\n/-- Numeric actual candidate ID equality is EXACToriginal whole-word equality for every valid selected prefix. -/\ntheorem label_eq_iff (r a:Nat) [NeZero r] (ids:List (List Bool))\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) (i j:Nat) :\n    idLabel ids i=idLabel ids j ↔\n      SemiprimeSourceHistogramDictRefinement.labels r a ids i=SemiprimeSourceHistogramDictRefinement.labels r a ids j :=by\n  constructor\n  · intro h\n    have he:=SemiprimeSourceCompactWordIds.compact_value_injective _ _ (expected_compact ids i) (expected_compact ids j) h\n    exact (expected_decode r a ids i).symm.trans ((congrArg (SemiprimeSourceWordBankSemantics.decode r a) he).trans (expected_decode r a ids j))\n  · intro h\n    have he:=SemiprimeSourceCompactWordBank.decode_injective r a (expected_mem r a ids hf i) (expected_mem r a ids hf j)\n      ((expected_decode r a ids i).trans (h.trans (expected_decode r a ids j).symm))\n    exact congrArg bitValue he\n/-- The two original labels can be replaced by their actual compact numeric IDs, without changing a single lane. -/\ntheorem classified_original (r a L:Nat) [NeZero r] (ids:List (List Bool))\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids)\n    (remaining:List Nat) (u v w z:Nat) :\n    classifiedCount L remaining (idLabel ids) u v w z=\n      classifiedCount L remaining (SemiprimeSourceHistogramDictRefinement.labels r a ids) u v w z :=by\n  unfold classifiedCount SemiprimeSourceIncidenceCountFormula.pairOK\n  simp only [label_eq_iff r a ids hf u w,label_eq_iff r a ids hf v z]\n/-- Exact ordered physical key list in the old acquired original incidence order. -/\ndef originalKeys (n F a:Nat) (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) :List (List Bool×List Bool) :=\n  (SemiprimeSourceHistogramMetadata.acquire n F a arity).incidences.map\n    (fun i=>(Keys.numberKey (owner i).val,Keys.numberKey (n+i.1.val)))\n/-- Mathematical scalar sum represented by the actual ordered-pair source; no such sum opcode occurs at runtime. -/\ndef codeScore (L:Nat) (remaining:List Nat) (ids:List (List Bool)) (rows:List (List Bool×List Bool)) :Nat :=\n  (rows.map (fun left=>(rows.map (fun right=>classifiedCount L remaining (idLabel ids)\n    (bitValue left.1) (bitValue left.2) (bitValue right.1) (bitValue right.2))).sum)).sum\n/-- Actual compact numeric keys encode the exact OLDordered incidence count, including every duplicate pair. -/\ntheorem counts_original (n F r a:Nat) [NeZero r] (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (ids:List (List Bool)) (s:Nat)\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    (SemiprimeSourceHistogramQueryCorrectness.originalCounts n F r a arity owner ids s).incidence=\n      codeScore (r^a) (List.range' ids.length s) ids (originalKeys n F a arity owner) :=by\n  unfold SemiprimeSourceHistogramQueryCorrectness.originalCounts\n  dsimp only\n  rw [SemiprimeSourceHistogramAcquiredSums.original_terms,\n    ←(SemiprimeSourceHistogramMetadata.original_fields n F a arity).2,\n    SemiprimeSourceHistogramOriginalSums.compiled_incidence_sum]\n  unfold codeScore originalKeys SemiprimeSourceHistogramGrouping.pairs\n  simp only [List.map_map,Function.comp_def,Keys.numberKey_value,\n    SemiprimeSourceHistogramPortKeys.indexCode_inl,SemiprimeSourceHistogramPortKeys.indexCode_inr]\n  apply congrArg List.sum\n  apply List.map_congr_left\n  intro i _\n  apply congrArg List.sum\n  apply List.map_congr_left\n  intro j _\n  have hi: (owner i).val < n:=(owner i).isLt\n  have hj: (owner j).val < n:=(owner j).isLt\n  have hp:=SemiprimeSourceIncidenceCountFormula.paddedLocal_formula r a (NeZero.pos r)\n    (owner i).val (n+i.1.val) (owner j).val (n+j.1.val) (List.range' ids.length s)\n    (SemiprimeSourceHistogramHeadOriginal.originalEnv r a ids) (List.nodup_range')\n    (by omega) (by omega) (by omega) (by omega)\n  simp only [SemiprimeSourceHeadCountFormula.alphabet] at hp\n  rw [hp]\n  change classifiedCount (r^a) (List.range' ids.length s)\n      (SemiprimeMaterializedScoreEnvironment.denote\n        (SemiprimeMaterializedScoreEnvironment.baseEnvironment (SemiprimeSourceWordBankSemantics.decode r a [])\n          (ids.map (SemiprimeSourceWordBankSemantics.decode r a)))) _ _ _ _=_\n  rw [SemiprimeSourceHistogramDictRefinement.labels_original]\n  exact (classified_original r a (r^a) ids hf (List.range' ids.length s) _ _ _ _).symm\n/-- Exact incidence-only ORIGINALquery scalar; no head query or generic weight is introduced. -/\ntheorem query_value_original (n F r a:Nat) [NeZero r] (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (ids:List (List Bool)) (s:Nat)\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    (SemiprimeD1IncidenceSearch.query (SemiprimeSourceHistogramSetup.acquire n F r a 0 arity owner) ids s).word.value=\n      (codeScore (r^a) (List.range' ids.length s) ids (originalKeys n F a arity owner):Rat) :=by\n  rw [SemiprimeD1IncidenceSearch.query_value n F r a arity owner ids s hf,\n    counts_original n F r a arity owner ids s hf]\n/-- Exact mathematical next winner of the physical forward catalogue scan. -/\ndef stepChoice (L:Nat) (rows:List (List Bool×List Bool)) (s:Nat)\n    (ids:List (List Bool)) (first:List Bool) (rest:List (List Bool)) :List Bool :=\n  SemiprimeD1StackSourceIncidenceSelectSpec.tailChoice\n    (fun id=>codeScore L (List.range' (ids.length+1) s) (id::ids) rows) first rest\n/-- The concrete numeric scan returns the exact original query choice, including every equality. -/\ntheorem stepChoice_original (n F r a:Nat) [NeZero r] (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (ids:List (List Bool)) (s:Nat)\n    (first:List Bool) (rest:List (List Bool))\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids)\n    (hm:∀id∈first::rest,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    stepChoice (r^a) (originalKeys n F a arity owner) s ids first rest=\n      (SemiprimeSourceChoiceBits.choose\n        (fun id=>SemiprimeD1IncidenceSearch.query\n          (SemiprimeSourceHistogramSetup.acquire n F r a 0 arity owner) (id::ids) s) first rest).value :=by\n  apply SemiprimeD1StackSourceIncidenceSelectSpec.tailChoice_reports\n  · intro id _\n    exact SemiprimeD1IncidenceSearch.query_valid _ _ _\n  · intro id hid\n    simpa only [List.length_cons] using query_value_original n F r a arity owner (id::ids) s\n      (SemiprimeSourceWordIdControl.inMenu_cons _ ids id (hm id hid) hf)\n/-- Exact selected-ID specification controlled by the physically consumed marker list. -/\ndef select (L:Nat) (rows:List (List Bool×List Bool)) (first:List Bool) (rest:List (List Bool)) :\n    List Bool→List (List Bool)→List (List Bool)\n  | [],ids=>ids\n  | _::tokens,ids=>\n    let id:=stepChoice L rows tokens.length ids first rest\n    select L rows first rest tokens (id::ids)\n/-- The physical scan specification preserves exact original assignment at every selected prefix. -/\ntheorem select_original (n F r a:Nat) [NeZero r] (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) (first:List Bool) (rest:List (List Bool))\n    (tokens:List Bool) (ids:List (List Bool))\n    (hf:∀id∈ids,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids)\n    (hm:∀id∈first::rest,id∈(SemiprimeSourceCompactWordBank.acquire r a).ids) :\n    select (r^a) (originalKeys n F a arity owner) first rest tokens ids=\n      (SemiprimeSourceChoiceBits.assign first rest\n        (fun todo fixed=>SemiprimeD1IncidenceSearch.query\n          (SemiprimeSourceHistogramSetup.acquire n F r a 0 arity owner) fixed todo.length) tokens ids).value :=by\n  induction tokens generalizing ids with\n  | nil=>simp only [select,SemiprimeSourceChoiceBits.assign,SemiprimeSourceChoiceBits.copyIDs_value]\n  | cons token tokens ih=>\n    have hw:=stepChoice_original n F r a arity owner ids tokens.length first rest hf hm\n    have hmem:=SemiprimeD1StackSourceIncidenceSelectSpec.tailChoice_mem\n      (fun id=>codeScore (r^a) (List.range' (ids.length+1) tokens.length) (id::ids)\n        (originalKeys n F a arity owner)) first rest\n    change stepChoice (r^a) (originalKeys n F a arity owner) tokens.length ids first rest∈first::rest at hmem\n    have hnew:=SemiprimeSourceWordIdControl.inMenu_cons _ ids _ (hm _ hmem) hf\n    rw [select,ih _ hnew,SemiprimeSourceChoiceBits.assign,SemiprimeSourceChoiceBits.copyIDs_value,hw]\n/-- Marker values carry no hidden iteration count; only the paid physical list shape is used. -/\ntheorem select_replicate (L:Nat) (rows:List (List Bool×List Bool)) (first:List Bool)\n    (rest:List (List Bool)) (n:Nat) (left right:Bool) (ids:List (List Bool)) :\n    select L rows first rest (List.replicate n left) ids=\n      select L rows first rest (List.replicate n right) ids :=by\n  induction n generalizing ids with\n  | zero=>rfl\n  | succ n ih=>simp only [List.replicate_succ,select,List.length_replicate];exact ih _\n/-- The complete prepared scalar/choice specification is EXACT the original incidence-only run. -/\ntheorem select_run_original (n F r a:Nat) [NeZero r] (arity:Fin F→Nat)\n    (owner:((e:Fin F)×Fin (arity e))→Fin n) :\n    select (r^a) (originalKeys n F a arity owner) []\n      (SemiprimeSourceCompactWordBank.acquire r a).ids.tail (List.replicate (n+F) true) []=\n        (SemiprimeD1IncidenceSearch.run n F r a arity owner).value :=by\n  rw [select_replicate (r^a) (originalKeys n F a arity owner) [] _ (n+F) true false,\n    select_original n F r a arity owner [] _ _ [] (by simp) (SemiprimeSourceHistogramSearch.candidates_valid r a)]\n  simp only [SemiprimeD1IncidenceSearch.run,SemiprimeSourceChoiceBits.run,\n    SemiprimeSourceChoiceBits.acquireTokens_value,SemiprimeSourceHistogramSetup.bank_actual,\n    SemiprimeSourceHistogramSetup.metadata_actual]\n  rw [(SemiprimeSourceHistogramMetadata.sizes n F a arity).2.2.2.2]\nend RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectMeaning\n","RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyEncoding":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceKeyFrequency\nimport RiemannGaussian.SemiprimeD1PortOwnerKeys\n/-! # Proof interpretation of raw-key dictionary overrides and all actual physical words -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyEncoding\nopen SemiprimeD1StackSourceKeyFrequency\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeSourceHistogramKeyBits (frame)\n/-- Each comparison key is the actual sentinel-copy result, including for an empty raw key. -/\ndef encoded (raw:List Bool) :List Bool :=raw++[true]\n/-- Literal raw-byte identity is equivalent to the real numeric equality on sentinel keys. -/\ntheorem encoded_eq (a b:List Bool) :\n    SemiprimeBitArithmetic.bitValue (encoded a)=SemiprimeBitArithmetic.bitValue (encoded b) ↔ a=b :=by\n  constructor\n  · intro h\n    have hh:=SemiprimeSourceCompactWordIds.compact_value_injective (encoded a) (encoded b)\n      (SemiprimeD1PortOwnerKeys.compact_sentinel a) (SemiprimeD1PortOwnerKeys.compact_sentinel b) h\n    exact List.append_cancel_right hh\n  · intro h;rw [h]\n/-- Raw keys remain proof-side raw lists; only their physically generated sentinel bytes are stored in actual records. -/\nabbrev Rows :=List (List Bool×List Bool)\n/-- Fixed record grammar carries encoded raw keys and compact binary frequency payloads. -/\ndef coded (rows:Rows) :Rows :=rows.map (fun row=>(encoded row.1,row.2))\n/-- Exact physical dictionary including every retained obsolete newest-first override. -/\ndef dictionary (rows:Rows) :List Bool :=SemiprimeD1StackOwnerLookup.records (coded rows) []\n/-- The real first-match result, not an evaluator supplied to the machine. -/\ndef read (rows:Rows) (raw:List Bool) :List Bool :=\n  (SemiprimeD1StackOwnerLookup.result (encoded raw) (coded rows) []).1\n/-- Physical unread tail after the same actual first-match scan. -/\ndef unread (rows:Rows) (raw:List Bool) :List Bool :=\n  (SemiprimeD1StackOwnerLookup.result (encoded raw) (coded rows) []).2\n/-- A new count is the physical compact successor of the actual old payload, with absence encoding zero. -/\ndef nextCount (rows:Rows) (raw:List Bool) :List Bool :=SemiprimeD1StackSourceEnvironmentEncoding.successor (read rows raw)\n/-- Only the actual strict comparison Boolean controls maximum replacement. -/\ndef nextMaximum (maximum count:List Bool) :List Bool :=\n  if SemiprimeD1StackWordLessExecution.answer maximum count then count else maximum\n/-- Mathematical state describes the already physically acquired dictionary and maximum. -/\nstructure Summary where\n  /-- All newest-first retained override records. -/\n  rows:Rows\n  /-- Actual compact binary maximum. -/\n  maximum:List Bool\n/-- One literal row's interpretation: real increment, strict maximum and head override. -/\ndef step (s:Summary) (raw:List Bool) :Summary :=\n  ⟨(raw,nextCount s.rows raw)::s.rows,nextMaximum s.maximum (nextCount s.rows raw)⟩\n/-- Empty physical dictionary and zero maximum before the first parsed raw key. -/\ndef empty :Summary :=⟨[],[]⟩\n/-- Original chronological order and every duplicate are retained by the physical fold. -/\ndef acquire (keys:List (List Bool)) :Summary :=keys.foldl step empty\n/-- Complete literal21-role boundary store; fields are proof-side names for physical Boolean words. -/\nstructure Words where\n  /-- Actual source word. -/\n  source:List Bool:=[]\n  /-- Actual reader word. -/\n  reader:List Bool:=[]\n  /-- Actual raw word. -/\n  raw:List Bool:=[]\n  /-- Actual dictionary word. -/\n  dictionary:List Bool:=[]\n  /-- Actual count word. -/\n  count:List Bool:=[]\n  /-- Actual maximum word. -/\n  maximum:List Bool:=[]\n  /-- Actual incScratch word. -/\n  incScratch:List Bool:=[]\n  /-- Actual incNext word. -/\n  incNext:List Bool:=[]\n  /-- Actual trimScratch word. -/\n  trimScratch:List Bool:=[]\n  /-- Actual frameScratch word. -/\n  frameScratch:List Bool:=[]\n  /-- Actual query word. -/\n  query:List Bool:=[]\n  /-- Actual lookupReader word. -/\n  lookupReader:List Bool:=[]\n  /-- Actual left word. -/\n  left:List Bool:=[]\n  /-- Actual right word. -/\n  right:List Bool:=[]\n  /-- Actual eqScratch word. -/\n  eqScratch:List Bool:=[]\n  /-- Actual comparison word. -/\n  comparison:List Bool:=[]\n  /-- Actual valid word. -/\n  valid:List Bool:=[]\n  /-- Actual discard word. -/\n  discard:List Bool:=[]\n  /-- Actual oldCount word. -/\n  oldCount:List Bool:=[]\n  /-- Actual fieldScratch word. -/\n  fieldScratch:List Bool:=[]\n  /-- Actual copyScratch word. -/\n  copyScratch:List Bool:=[]\n/-- No word in the fixed physical inventory is hidden or omitted. -/\ndef bank (w:Words) :Stack→List Bool\n  | .inr .source=>w.source\n  | .inr .reader=>w.reader\n  | .inr .raw=>w.raw\n  | .inr .dictionary=>w.dictionary\n  | .inr .count=>w.count\n  | .inr .maximum=>w.maximum\n  | .inr .incScratch=>w.incScratch\n  | .inr .incNext=>w.incNext\n  | .inr .trimScratch=>w.trimScratch\n  | .inr .frameScratch=>w.frameScratch\n  | .inl (.inr .query)=>w.query\n  | .inl (.inr .reader)=>w.lookupReader\n  | .inl (.inl .left)=>w.left\n  | .inl (.inl .right)=>w.right\n  | .inl (.inl .scratch)=>w.eqScratch\n  | .inl (.inl .output)=>w.comparison\n  | .inl (.inr .valid)=>w.valid\n  | .inl (.inr .discard)=>w.discard\n  | .inl (.inr .output)=>w.oldCount\n  | .inl (.inr .fieldScratch)=>w.fieldScratch\n  | .inl (.inr .copyScratch)=>w.copyScratch\n/-- A physical source write preserves every other actual word. -/\ntheorem update_source (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .source) xs=bank {w with source:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical reader write preserves every other actual word. -/\ntheorem update_reader (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .reader) xs=bank {w with reader:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical raw write preserves every other actual word. -/\ntheorem update_raw (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .raw) xs=bank {w with raw:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical dictionary write preserves every other actual word. -/\ntheorem update_dictionary (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .dictionary) xs=bank {w with dictionary:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical count write preserves every other actual word. -/\ntheorem update_count (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .count) xs=bank {w with count:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical maximum write preserves every other actual word. -/\ntheorem update_maximum (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .maximum) xs=bank {w with maximum:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical incScratch write preserves every other actual word. -/\ntheorem update_incScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .incScratch) xs=bank {w with incScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical incNext write preserves every other actual word. -/\ntheorem update_incNext (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .incNext) xs=bank {w with incNext:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical trimScratch write preserves every other actual word. -/\ntheorem update_trimScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .trimScratch) xs=bank {w with trimScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical frameScratch write preserves every other actual word. -/\ntheorem update_frameScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (aux .frameScratch) xs=bank {w with frameScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical query write preserves every other actual word. -/\ntheorem update_query (w:Words) (xs:List Bool) :\n    Function.update (bank w) (query) xs=bank {w with query:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical lookupReader write preserves every other actual word. -/\ntheorem update_lookupReader (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inr .reader)) xs=bank {w with lookupReader:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical left write preserves every other actual word. -/\ntheorem update_left (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inl .left)) xs=bank {w with left:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical right write preserves every other actual word. -/\ntheorem update_right (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inl .right)) xs=bank {w with right:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical eqScratch write preserves every other actual word. -/\ntheorem update_eqScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inl .scratch)) xs=bank {w with eqScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical comparison write preserves every other actual word. -/\ntheorem update_comparison (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inl .output)) xs=bank {w with comparison:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical valid write preserves every other actual word. -/\ntheorem update_valid (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inr .valid)) xs=bank {w with valid:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical discard write preserves every other actual word. -/\ntheorem update_discard (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inr .discard)) xs=bank {w with discard:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical oldCount write preserves every other actual word. -/\ntheorem update_oldCount (w:Words) (xs:List Bool) :\n    Function.update (bank w) (oldCount) xs=bank {w with oldCount:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical fieldScratch write preserves every other actual word. -/\ntheorem update_fieldScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (lookupStack (.inr .fieldScratch)) xs=bank {w with fieldScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- A physical copyScratch write preserves every other actual word. -/\ntheorem update_copyScratch (w:Words) (xs:List Bool) :\n    Function.update (bank w) (copyScratch) xs=bank {w with copyScratch:=xs} :=by\n  funext k;rcases k with k|k\n  · rcases k with k|k <;> cases k <;> rfl\n  · cases k <;> rfl\n/-- Clean loop boundary retains source, unread forward vector, dictionary and maximum. -/\ndef loopWords (source reader:List Bool) (s:Summary) :Words :=\n  {source:=source,reader:=reader,dictionary:=dictionary s.rows,maximum:=s.maximum}\n/-- Sole key-vector source; no count, dictionary or maximum is prepared as an input. -/\ndef source (keys:List (List Bool)) :C.State Stack Label :=initial (vectorBits keys)\n/-- Actual stopped21-role bank with all18 other roles empty. -/\ndef result (keys:List (List Bool)) :Stack→List Bool :=bank (loopWords (vectorBits keys) [] (acquire keys))\n/-- Literal actual halt also clears both flags and all real source-call returns. -/\ndef done (keys:List (List Bool)) :C.State Stack Label :=⟨none,none,none,result keys,[]⟩\n/-- Whole physical input size counts every framing bit and terminator. -/\ndef inputSize (keys:List (List Bool)) :Nat :=(vectorBits keys).length+1\nend RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyEncoding\n","RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceKeyFrequency\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n/-! # Literal paid frequency-source primitive calls and actual counter return -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyPrimitives\nopen SemiprimeD1StackSourceKeyFrequency SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\n/-- Exact chronological source-fragment composition preserves every real outer return. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- Actual complete preserving copy, including both restoration loops and its real caller return. -/\ntheorem copy_call (what:Copy) (pc next:Label)\n    (hc:program pc=.call (.copier what 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hs:before (copyStack what 2)=[]) :\n    Runs program (5*xs.length+4) pc before next\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  let start:=SemiprimeD1StackCopy.state 0 none xs ys []\n  let stop:=SemiprimeD1StackCopy.done xs (xs++ys)\n  have hi:Link.DataRel (copyStack what) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (copyStack what) (copy_injective what) before start.store before hi (1:Fin 3) (xs++ys)\n  have he:Function.update start.store 1 (xs++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (copyStack what) (Label.copier what) (copy_injective what) SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) pc next hc (5*xs.length+3) start stop before _ rfl rfl\n    (SemiprimeD1StackCopy.copy_words xs ys none) hi ho\n/-- Complete real field read, with actual true-valid marker retained until its physical pop. -/\ntheorem field_call (pc next:Label)\n    (hc:program pc=.call (.parser (Field.active .tagPop (none,false))) next)\n    (before:Stack→List Bool) (word tail:List Bool) (hi:before (aux .reader)=frame word tail)\n    (ho:before (aux .raw)=[]) (hs:before (lookupStack (.inr .fieldScratch))=[]) (hv:before (lookupStack (.inr .valid))=[]) :\n    Runs program (8*word.length+7) pc before next\n      (Function.update (Function.update (Function.update before (aux .reader) tail)\n        (aux .raw) word) (lookupStack (.inr .valid)) [true]) :=by\n  let start:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let stop:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel fieldStack before start.store before:=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hi\n        · exact hs\n        · exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  have h0:=Link.data_update fieldStack field_injective before start.store before hin (.inl .input) tail\n  have h1:=Link.data_update fieldStack field_injective before _ _ h0 (.inl .output) word\n  have h2:=Link.data_update fieldStack field_injective before _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update start.store (.inl .input) tail) (.inl .output) word) (.inr ()) [true]=stop.store:=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  rw [he] at h2\n  exact included_call program fieldStack Label.parser field_injective Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) pc next hc (8*word.length+6) start stop before _ rfl rfl\n    (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin h2\n/-- Real preserving Frame writes a physical field onto its existing dictionary/vector tail. -/\ntheorem frame_call (part:Frame) (pc next:Label)\n    (hc:program pc=.call (.framer part 0) next) (before:Stack→List Bool) (word buffer:List Bool)\n    (hw:before (frameStack part 0)=word) (hb:before (frameStack part 1)=buffer) (hs:before (frameStack part 2)=[]) :\n    Runs program (6*word.length+5) pc before next\n      (Function.update before (frameStack part 1) (frame word buffer)) :=by\n  let start:=SemiprimeD1StackFrame.state 0 none word buffer []\n  let stop:=SemiprimeD1StackFrame.done word (frame word buffer)\n  have hi:Link.DataRel (frameStack part) before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hw\n      · exact hb\n      · exact hs\n    · intro k _;rfl\n  have ho:=Link.data_update (frameStack part) (frame_injective part) before start.store before hi (1:Fin 3) (frame word buffer)\n  have he:Function.update start.store 1 (frame word buffer)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at ho\n  exact included_call program (frameStack part) (Label.framer part) (frame_injective part) SemiprimeD1StackFrame.code 0 (fun _=>rfl)\n    pc next hc (6*word.length+4) start stop before _ rfl rfl\n    (SemiprimeD1StackFrame.frame_words word buffer none) hi ho\n/-- Every inner-owner/row/final reversal consumes its real source and pays all bytes and return cells. -/\ntheorem reverse_call (pc next:Label)\n    (hc:program pc=.call (.reversal 0) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (reverseStack 0)=xs) (hy:before (reverseStack 1)=ys) :\n    Runs program (2*xs.length+3) pc before next\n      (Function.update (Function.update before (reverseStack 0) []) (reverseStack 1) (xs.reverse++ys)) :=by\n  let start:=SemiprimeD1StackReverseWord.state none xs ys\n  let stop:=SemiprimeD1StackReverseWord.done (xs.reverse++ys)\n  have hi:Link.DataRel reverseStack before start.store before:=by\n    constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n    · intro k _;rfl\n  have h0:=Link.data_update reverseStack reverse_injective before start.store before hi (0:Fin 2) []\n  have h1:=Link.data_update reverseStack reverse_injective before _ _ h0 (1:Fin 2) (xs.reverse++ys)\n  have he:Function.update (Function.update start.store 0 []) 1 (xs.reverse++ys)=stop.store:=by funext k;fin_cases k <;> rfl\n  rw [he] at h1\n  exact included_call program reverseStack Label.reversal reverse_injective\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) pc next hc (2*xs.length+2) start stop before _ rfl rfl\n    (SemiprimeD1StackReverseWord.reverse_run xs ys none) hi h1\n/-- Actual high-zero stripping/reversal, with both other reducer operands physically empty. -/\ntheorem trim_call (pc next:Label)\n    (hc:program pc=.call (.reducer .trim) next) (before:Stack→List Bool) (xs ys:List Bool)\n    (hl:before (trimStack .left)=[]) (hr:before (trimStack .right)=[])\n    (hs:before (trimStack .scratch)=xs) (ho:before (trimStack .output)=ys) :\n    Runs program (SemiprimeD1StackReduceExecution.trimTime xs+1) pc before next\n      (Function.update (Function.update before (trimStack .scratch) []) (trimStack .output)\n        (SemiprimeD1StackReduceExecution.trimReverse xs++ys)) :=by\n  let start:=SemiprimeD1StackReduce.state (some .trim) none [] [] xs ys\n  let stop:=SemiprimeD1StackReduce.state none none [] [] [] (SemiprimeD1StackReduceExecution.trimReverse xs++ys)\n  have hi:Link.DataRel trimStack before start.store before:=by\n    constructor\n    · intro k;cases k\n      · exact hl\n      · exact hr\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update trimStack trim_injective before start.store before hi .scratch []\n  have h1:=Link.data_update trimStack trim_injective before _ _ h0 .output\n    (SemiprimeD1StackReduceExecution.trimReverse xs++ys)\n  have he:Function.update (Function.update start.store .scratch []) .output\n      (SemiprimeD1StackReduceExecution.trimReverse xs++ys)=stop.store:=by funext k;cases k <;> rfl\n  rw [he] at h1\n  exact included_call program trimStack Label.reducer trim_injective R.code .trim (fun _=>rfl)\n    pc next hc (SemiprimeD1StackReduceExecution.trimTime xs) start stop before _ rfl rfl\n    (SemiprimeD1StackReduceExecution.trim_run xs ys none) hi h1\n/-- Actual key increment consumes the old word and emits its REALoverflow prefix and wrapped bits. -/\ntheorem increment_call (before:Stack→List Bool) (word:List Bool)\n    (hw:before oldCount=word) (hs:before (aux .incScratch)=[]) (ho:before (aux .incNext)=[]) :\n    ∃q≤10*word.length+16,Runs program q .increment before .popOverflow\n      (Function.update (Function.update before oldCount []) (aux .incNext)\n        (SemiprimeD1StackIncrement.overflow word::SemiprimeD1StackIncrement.wrapped word)) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackIncrementBytecode.increment_run word []\n  refine ⟨q+1,by omega,?_⟩\n  let start:SemiprimeD1StackBytecode.State I.Stack I.Label:=⟨some I.entry,none,SemiprimeD1TensorTapeFieldMachine.contents word [] []⟩\n  let stop:SemiprimeD1StackBytecode.State I.Stack I.Label:=⟨none,none,SemiprimeD1TensorTapeFieldMachine.contents [] []\n    (SemiprimeD1StackIncrement.overflow word::SemiprimeD1StackIncrement.wrapped word)⟩\n  have hi:Link.DataRel incrementStack before start.store before:=by\n    constructor\n    · intro k;cases k\n      · exact hw\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  have h0:=Link.data_update incrementStack increment_injective before start.store before hi .input []\n  have h1:=Link.data_update incrementStack increment_injective before _ _ h0 .output\n    (SemiprimeD1StackIncrement.overflow word::SemiprimeD1StackIncrement.wrapped word)\n  have he:Function.update (Function.update start.store .input []) .output\n      (SemiprimeD1StackIncrement.overflow word::SemiprimeD1StackIncrement.wrapped word)=stop.store:=by funext k;cases k <;> rfl\n  rw [he] at h1\n  apply included_call program incrementStack Label.incrementCode increment_injective I.code I.entry (fun _=>rfl)\n    .increment .popOverflow rfl q start stop before _ rfl rfl\n  · simpa only [List.append_nil] using hr\n  · exact hi\n  · exact h1\n/-- The actual eleven-role first-match scan runs only after the preserving physical catalogue copy. -/\ntheorem lookup_call (before:Stack→List Bool) (key:List Bool) (rows:List (List Bool×List Bool))\n    (hi:∀k,before (lookupStack k)=(SemiprimeD1StackOwnerLookup.initial key (SemiprimeD1StackOwnerLookup.records rows [])).data k) :\n    ∃q≤SemiprimeD1StackOwnerLookupBounds.runBound key rows+1,Runs program q .lookup before .clearReader\n      (Sum.elim (SemiprimeD1StackOwnerLookup.done key rows []).data (fun k=>before (aux k))) :=by\n  refine ⟨SemiprimeD1StackOwnerLookupExecution.loopTime key rows+2,?_,?_⟩\n  · have ht:=SemiprimeD1StackOwnerLookupBounds.time_le key rows\n    omega\n  · apply SemiprimeD1StackProcedureCallsTrace.included_call program lookupStack Label.lookupCode Sum.inl_injective\n      L.program .loop (fun _=>rfl) .lookup .clearReader rfl\n      (SemiprimeD1StackOwnerLookupExecution.loopTime key rows+1)\n      (SemiprimeD1StackOwnerLookup.initial key (SemiprimeD1StackOwnerLookup.records rows [])) (SemiprimeD1StackOwnerLookup.done key rows []) _ _\n      rfl rfl rfl rfl (SemiprimeD1StackOwnerLookupExecution.source_run key rows [])\n    · constructor\n      · exact hi\n      · intro k _;rfl\n    · constructor\n      · intro k;rfl\n      · intro k hk\n        rcases k with k|k\n        · exact (hk k rfl).elim\n        · rfl\n/-- One literal local push preserves the entire other physical bank and all real outer returns. -/\ntheorem push_run (pc:Label) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program pc=.base (.push k b next)) :\n    Runs program 1 pc before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One literal local pop consumes ONLYthe actual physical Boolean head. -/\ntheorem pop_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) (Function.update before k xs.tail) :=by\n  apply one_base program pc _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Real EOF peek does not silently discard any remaining singleton-result bytes. -/\ntheorem peek_run (pc:Label) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program pc=.base (.peek k empty low high)) (hx:before k=xs) :\n    Runs program 1 pc before (SemiprimeD1StackBytecode.choose empty low high xs.head?) before :=by\n  apply one_base program pc _ (.peek k empty low high) before before hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · rfl\n/-- Every table/key/owner/row cleanup actually visits every byte and its final empty branch. -/\ntheorem drain_loop (pc:Label) (next:Label) (k:Stack)\n    (hc:program pc=.base (.pop k next pc pc)) (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) pc before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next pc pc k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next pc pc k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- A literal same-program local call executes its ACTUALreturn instruction and preserves every outer return cell. -/\ntheorem local_call (pc entry next:Label)\n    (hc:program pc=.call entry next)\n    (q:Nat) (before after:Stack→List Bool)\n    (hr:Runs program q entry before .counterReturn after) :\n    Runs program (q+2) pc before next after :=by\n  intro frames target h\n  let mid:=SemiprimeD1StackCalls.execute (.call entry next) target\n  have hm:SemiprimeD1StackCalls.run program 1 target=some mid:=by\n    change SemiprimeD1StackCalls.step program target=some mid\n    simp only [SemiprimeD1StackCalls.step,h.1,Option.map_some,hc,mid]\n  have hat:At entry before (next::frames) mid:=by\n    exact ⟨rfl,h.2.1,by simpa only [mid,SemiprimeD1StackCalls.execute] using congrArg (List.cons next) h.2.2⟩\n  obtain ⟨finish,hf,hfAt⟩:=hr (next::frames) mid hat\n  let last:SemiprimeD1StackCalls.State Stack Label:=⟨some next,finish.flag,some next,after,frames⟩\n  have hl:SemiprimeD1StackCalls.run program 1 finish=some last:=by\n    change SemiprimeD1StackCalls.step program finish=some last\n    simp only [SemiprimeD1StackCalls.step,hfAt.1,Option.map_some,program,SemiprimeD1StackCalls.execute,hfAt.2.1,hfAt.2.2]\n    rfl\n  refine ⟨last,?_,rfl,rfl,rfl⟩\n  have he:q+2=1+(q+1):=by omega\n  rw [he,SemiprimeD1StackReturnLink.run_add,hm,Option.bind_some,\n    SemiprimeD1StackReturnLink.run_add,hf,Option.bind_some]\n  exact hl\nend RiemannGaussian.SemiprimeD1StackSourceKeyFrequencyPrimitives\n","RiemannGaussian.SemiprimeD1StackSourceOccurrencesPrimitives":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceOccurrences\n/-! # Actual row-source copies, parsers, binary-key frames, counter and literal drains -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceOccurrencesPrimitives\nopen SemiprimeD1StackSourceOccurrences SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nnamespace Link\nexport SemiprimeD1StackMultiplierLink (DataRel data_update)\nend Link\nlocal notation \"ctl\" => Label.local\n/-- Actual fragments concatenate in this same literal record source. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after :=runs_trans program m n pc mid next before between after h g\n/-- The actual copy operands name separate physical words. -/\ntheorem copy_ne (what:Copy) :copyStack what 0≠copyStack what 1 :=by cases what <;> decide\n/-- Copy restoration scratch never aliases the actual destination. -/\ntheorem copy_scratch_ne (what:Copy) :Stack.copyScratch≠copyStack what 1 :=by cases what <;> decide\n/-- One real preserving copy charges all source bytes and its actual return. -/\ntheorem copy_call (what:Copy) (pc next:Control)\n    (hc:program (ctl pc)=.call (.copy what 0) (ctl next))\n    (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (copyStack what 0)=xs) (hy:before (copyStack what 1)=ys) (hz:before .copyScratch=[]) :\n    Runs program (5*xs.length+4) (ctl pc) before (ctl next)\n      (Function.update before (copyStack what 1) (xs++ys)) :=by\n  apply included_call program (copyStack what) (Label.copy what) (copy_injective what)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (5*xs.length+3)\n    (SemiprimeD1StackCopy.state 0 none xs ys []) (SemiprimeD1StackCopy.done xs (xs++ys)) before _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackCopy.copy_words xs ys none\n  · constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hz\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update before (copyStack what 1) (xs++ys) (copyStack what 0)=xs\n        rw [Function.update_of_ne (copy_ne what),hx]\n      · exact Function.update_self _ _ _\n      · change Function.update before (copyStack what 1) (xs++ys) .copyScratch=[]\n        rw [Function.update_of_ne (copy_scratch_ne what),hz]\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 he.symm) _ _\n/-- Actual field reader address for the current record or port field. -/\ndef fieldInput (part:Part) :Stack :=fieldStack part (.inl .input)\n/-- Actual field destination; all three field caches are private. -/\ndef fieldOutput (part:Part) :Stack :=fieldStack part (.inl .output)\n/-- One actual parser consumes and copies the field, retaining its true validity marker. -/\ntheorem field_call (part:Part) (pc next:Control)\n    (hc:program (ctl pc)=.call (.field part (Field.active .tagPop (none,false))) (ctl next))\n    (before:Stack→List Bool) (word tail:List Bool)\n    (hi:before (fieldInput part)=frame word tail) (ho:before (fieldOutput part)=[])\n    (hs:before .fieldScratch=[]) (hv:before .valid=[]) :\n    Runs program (8*word.length+7) (ctl pc) before (ctl next)\n      (Function.update (Function.update (Function.update before (fieldInput part) tail)\n        (fieldOutput part) word) .valid [true]) :=by\n  let start:=SemiprimeD1TensorTapeFieldBytecode.initial (frame word tail) []\n  let stop:SemiprimeD1StackBytecode.State Field.Stack Field.Label:=\n    ⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩\n  have hin:Link.DataRel (fieldStack part) before start.store before :=by\n    constructor\n    · intro k;rcases k with k|k\n      · cases k\n        · exact hi\n        · exact hs\n        · exact ho\n      · cases k;exact hv\n    · intro k _;rfl\n  apply included_call program (fieldStack part) (Label.field part) (field_injective part) Field.code\n    (Field.active .tagPop (none,false)) (fun _=>rfl) (ctl pc) (ctl next) hc (8*word.length+6)\n    start stop before _ rfl rfl (SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []) hin\n  have h0:=Link.data_update (fieldStack part) (field_injective part) before start.store before hin (.inl .input) tail\n  have h1:=Link.data_update (fieldStack part) (field_injective part) before _ _ h0 (.inl .output) word\n  have h2:=Link.data_update (fieldStack part) (field_injective part) before _ _ h1 (.inr ()) [true]\n  have he:Function.update (Function.update (Function.update start.store (.inl .input) tail)\n      (.inl .output) word) (.inr ()) [true]=stop.store :=by\n    funext k;rcases k with k|k <;> cases k <;> rfl\n  simpa only [he,fieldInput,fieldOutput,fieldStack] using h2\n/-- Actual frame source never aliases the shared pair buffer. -/\ntheorem frame_ne (what:Frame) :frameStack what 0≠Stack.frameBuffer :=by cases what <;> decide\n/-- One preserving frame physically copies either the binary owner or the actual unary port key. -/\ntheorem frame_call (what:Frame) (pc next:Control)\n    (hc:program (ctl pc)=.call (.frame what 0) (ctl next))\n    (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (frameStack what 0)=xs) (hy:before .frameBuffer=ys) (hz:before .frameScratch=[]) :\n    Runs program (6*xs.length+5) (ctl pc) before (ctl next)\n      (Function.update before .frameBuffer (frame xs ys)) :=by\n  apply included_call program (frameStack what) (Label.frame what) (frame_injective what)\n    SemiprimeD1StackFrame.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (6*xs.length+4)\n    (SemiprimeD1StackFrame.state 0 none xs ys []) (SemiprimeD1StackFrame.done xs (frame xs ys)) before _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackFrame.frame_words xs ys none\n  · constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n      · exact hz\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update before .frameBuffer (frame xs ys) (frameStack what 0)=xs\n        rw [Function.update_of_ne (frame_ne what),hx]\n      · exact Function.update_self _ _ _\n      · change Function.update before .frameBuffer (frame xs ys) .frameScratch=[]\n        rw [Function.update_of_ne (by decide:Stack.frameScratch≠.frameBuffer),hz]\n    · intro k hk\n      exact Function.update_of_ne (fun he=>hk 1 he.symm) _ _\n/-- Both actual reversal operands are distinct for every literal call site. -/\ntheorem reverse_ne (what:Reverse) :reverseStack what 0≠reverseStack what 1 :=by cases what <;> decide\n/-- Real consuming reversal includes every pop/push, branch, halt and caller return. -/\ntheorem reverse_call (what:Reverse) (pc next:Control)\n    (hc:program (ctl pc)=.call (.reverse what 0) (ctl next))\n    (before:Stack→List Bool) (xs ys:List Bool)\n    (hx:before (reverseStack what 0)=xs) (hy:before (reverseStack what 1)=ys) :\n    Runs program (2*xs.length+3) (ctl pc) before (ctl next)\n      (Function.update (Function.update before (reverseStack what 0) [])\n        (reverseStack what 1) (xs.reverse++ys)) :=by\n  apply included_call program (reverseStack what) (Label.reverse what) (reverse_injective what)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (2*xs.length+2)\n    (SemiprimeD1StackReverseWord.state none xs ys) (SemiprimeD1StackReverseWord.done (xs.reverse++ys)) before _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackReverseWord.reverse_run xs ys none\n  · constructor\n    · intro k;fin_cases k\n      · exact hx\n      · exact hy\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update (Function.update before (reverseStack what 0) [])\n          (reverseStack what 1) (xs.reverse++ys) (reverseStack what 0)=[]\n        rw [Function.update_of_ne (reverse_ne what),Function.update_self]\n      · exact Function.update_self _ _ _\n    · intro k hk\n      rw [Function.update_of_ne (fun he=>hk 1 he.symm),Function.update_of_ne (fun he=>hk 0 he.symm)]\n/-- Actual fixed-width binary increment; both counter transfer reversals remain caller work. -/\ntheorem increment_call (part:Counter) (before:Stack→List Bool) (xs:List Bool)\n    (hx:before .counter=xs) (hs:before .incrementScratch=[]) (ho:before .next=[]) :\n    ∃q ≤5*(2*xs.length+3)+1,Runs program q (ctl (.increment part)) before (ctl (.carry part))\n      (Function.update (Function.update before .counter []) .next\n        (SemiprimeD1StackIncrement.overflow xs::SemiprimeD1StackIncrement.wrapped xs)) :=by\n  obtain ⟨q,hq,hr⟩:=SemiprimeD1StackIncrementBytecode.increment_run xs []\n  simp only [List.append_nil] at hr\n  refine ⟨q+1,by omega,?_⟩\n  let start:SemiprimeD1StackBytecode.State SemiprimeD1TensorTapeFieldMachine.Stack Inc.Label:=\n    ⟨some Inc.entry,none,SemiprimeD1TensorTapeFieldMachine.contents xs [] []⟩\n  let stop:SemiprimeD1StackBytecode.State SemiprimeD1TensorTapeFieldMachine.Stack Inc.Label:=\n    ⟨none,none,SemiprimeD1TensorTapeFieldMachine.contents [] []\n      (SemiprimeD1StackIncrement.overflow xs::SemiprimeD1StackIncrement.wrapped xs)⟩\n  have hin:Link.DataRel incrementStack before start.store before :=by\n    constructor\n    · intro k;cases k\n      · exact hx\n      · exact hs\n      · exact ho\n    · intro k _;rfl\n  apply included_call program incrementStack Label.increment increment_injective Inc.code Inc.entry (fun _=>rfl)\n    (ctl (.increment part)) (ctl (.carry part)) rfl q start stop before _ rfl rfl hr hin\n  have h0:=Link.data_update incrementStack increment_injective before start.store before hin .input []\n  have h1:=Link.data_update incrementStack increment_injective before _ _ h0 .output\n    (SemiprimeD1StackIncrement.overflow xs::SemiprimeD1StackIncrement.wrapped xs)\n  have he:Function.update (Function.update start.store .input []) .output\n      (SemiprimeD1StackIncrement.overflow xs::SemiprimeD1StackIncrement.wrapped xs)=stop.store :=by\n    funext k;cases k <;> rfl\n  simpa only [he,incrementStack] using h1\n/-- One real local push, with the entire remaining physical bank retained. -/\ntheorem push_run (pc:Control) (next:Label) (k:Stack) (b:Bool) (before:Stack→List Bool)\n    (hc:program (ctl pc)=.base (.push k b next)) :\n    Runs program 1 (ctl pc) before next (Function.update before k (b::before k)) :=\n  one_base program _ _ _ _ _ hc rfl rfl\n/-- One real local pop exposes the actual Boolean head and consumes precisely one physical cell. -/\ntheorem pop_run (pc:Control) (empty low high:Label) (k:Stack) (before:Stack→List Bool) (xs:List Bool)\n    (hc:program (ctl pc)=.base (.pop k empty low high)) (hx:before k=xs) :\n    Runs program 1 (ctl pc) before (SemiprimeD1StackBytecode.choose empty low high xs.head?)\n      (Function.update before k xs.tail) :=by\n  apply one_base program (ctl pc) _ (.pop k empty low high) before _ hc\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n  · simp only [SemiprimeD1StackBytecode.execute,hx]\n/-- Literal cleanup visits every current key/table byte and its empty branch. -/\ntheorem drain_loop (pc:Control) (next:Label) (k:Stack)\n    (hc:program (ctl pc)=.base (.pop k next (ctl pc) (ctl pc)))\n    (before:Stack→List Bool) (xs:List Bool) (hx:before k=xs) :\n    Runs program (xs.length+1) (ctl pc) before next (Function.update before k []) :=by\n  induction xs generalizing before with\n  | nil=>exact pop_run pc next (ctl pc) (ctl pc) k before [] hc hx\n  | cons b xs ih=>\n    have h0:=pop_run pc next (ctl pc) (ctl pc) k before (b::xs) hc hx\n    have h1:=ih (Function.update before k xs) (Function.update_self _ _ _)\n    have hh:=join (by cases b <;> exact h0) h1\n    simpa only [List.length_cons,Function.update_idem,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n/-- Literal fixed return target of each normalization call. -/\ndef afterTrim :Trim→Label | .factor=>ctl .ownerTag | .owner=>ctl .frameFactor\n/-- The REAL frozen reducer.trim entry consumes actual reverse bits and emits canonical magnitude bytes. -/\ntheorem trim_call (kind:Trim) (bank:Stack→List Bool)\n    (hl:bank (trimStack kind .left)=[]) (hr:bank (trimStack kind .right)=[]) :\n    Runs program (SemiprimeD1StackReduceExecution.trimTime (bank Stack.normScratch)+1) (ctl (.normalize kind)) bank\n      (afterTrim kind)\n      (Function.update (Function.update bank Stack.normScratch []) (trimStack kind .output)\n        (SemiprimeD1StackReduceExecution.trimReverse (bank Stack.normScratch)++bank (trimStack kind .output))) :=by\n  let before:=SemiprimeD1StackReduce.state (some .trim) none [] []\n    (bank Stack.normScratch) (bank (trimStack kind .output))\n  let after:=SemiprimeD1StackReduce.state none none [] [] []\n    (SemiprimeD1StackReduceExecution.trimReverse (bank Stack.normScratch)++bank (trimStack kind .output))\n  have hin:Link.DataRel (trimStack kind) bank before.store bank:=by\n    constructor\n    · intro k;cases k\n      · exact hl\n      · exact hr\n      · rfl\n      · rfl\n    · intro k _;rfl\n  apply included_call program (trimStack kind) (Label.trim kind) (trim_injective kind) Reduce.code .trim\n    (fun _=>rfl) (ctl (.normalize kind)) _ rfl (SemiprimeD1StackReduceExecution.trimTime (bank Stack.normScratch))\n    before after _ _ rfl rfl (SemiprimeD1StackReduceExecution.trim_run _ _ none) hin\n  have h0:=Link.data_update (trimStack kind) (trim_injective kind) bank before.store bank hin .scratch []\n  have h1:=Link.data_update (trimStack kind) (trim_injective kind) bank _ _ h0 .output\n    (SemiprimeD1StackReduceExecution.trimReverse (bank Stack.normScratch)++bank (trimStack kind .output))\n  have he:Function.update (Function.update before.store .scratch []) .output\n      (SemiprimeD1StackReduceExecution.trimReverse (bank Stack.normScratch)++bank (trimStack kind .output))=after.store:=by\n    funext k;cases k <;> rfl\n  simpa only [he,show trimStack kind .scratch=Stack.normScratch from rfl] using h1\nend RiemannGaussian.SemiprimeD1StackSourceOccurrencesPrimitives\n","RiemannGaussian.SemiprimeD1StackSourcePacketPaddingBits":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingEncoding\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingPrimitives\n/-! # Real unary-controlled bit cut and literal zero-prefix loops -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourcePacketPaddingBits\nopen SemiprimeD1StackSourcePacketPadding SemiprimeD1StackSourcePacketPaddingEncoding\nopen SemiprimeD1StackSourcePacketPaddingPrimitives SemiprimeD1StackProcedureTrace\nnamespace Old\nexport SemiprimeD1PacketRoundBits (cut)\nend Old\n/-- An empty actual binary suffix has no true low bit at any acquired exponent. -/\ntheorem cut_nil (a:Nat) :(Old.cut a []).low=false ∧ (Old.cut a []).high=[] :=by cases a <;> exact ⟨rfl,rfl⟩\n/-- Only physically active cut/count words differ from the arbitrary retained25-word caller bank. -/\ndef cutWords (w:Words) (a:Nat) (bits:List Bool) :Words:=\n  {w with cutTodo:=List.replicate a true,frequency:={w.frequency with oldCount:=bits}}\n/-- Every exponent marker and every corresponding actual bit/EOF pop is paid; the finite OR flag is computed, never advised. -/\ntheorem cut_run (a:Nat) (bits:List Bool) (low:Bool) (w:Words) :\n    Runs program (2*a+1) (.cut low) (bank (cutWords w a bits)) (.cutDone (low||(Old.cut a bits).low))\n      (bank (cutWords w 0 (Old.cut a bits).high)) :=by\n  induction a generalizing bits low with\n  | zero=>\n    have h:=pop_run (.cut low) (.cutDone low) .abort (.cutBit low) (aux .cutTodo)\n      (bank (cutWords w 0 bits)) [] rfl rfl\n    rw [update_cutTodo] at h\n    change Runs program 1 (.cut low) (bank (cutWords w 0 bits)) (.cutDone low) (bank (cutWords w 0 bits)) at h\n    simpa only [Old.cut,SemiprimeSourceCompactBits.copy_bits,Bool.or_false,Nat.mul_zero,Nat.zero_add] using h\n  | succ a ih=>\n    have h0:=pop_run (.cut low) (.cutDone low) .abort (.cutBit low) (aux .cutTodo)\n      (bank (cutWords w (a+1) bits)) (true::List.replicate a true) rfl rfl\n    rw [update_cutTodo] at h0\n    change Runs program 1 (.cut low) (bank (cutWords w (a+1) bits)) (.cutBit low) (bank (cutWords w a bits)) at h0\n    cases bits with\n    | nil=>\n      have h1:=pop_run (.cutBit low) (.cut low) (.cut low) (.cut true) (frequencyStack F.oldCount)\n        (bank (cutWords w a [])) [] rfl rfl\n      rw [update_oldCount] at h1\n      have h2:=ih [] low\n      have h:=join (join h0 h1) h2\n      simp only [(cut_nil a).1,(cut_nil a).2,Bool.or_false] at h\n      simp only [Old.cut,Bool.or_false]\n      convert h using 1; omega\n    | cons b bits=>\n      have h1:=pop_run (.cutBit low) (.cut low) (.cut low) (.cut true) (frequencyStack F.oldCount)\n        (bank (cutWords w a (b::bits))) (b::bits) rfl rfl\n      rw [update_oldCount] at h1\n      have hlabel:SemiprimeD1StackBytecode.choose (Label.cut low) (Label.cut low) (Label.cut true) (b::bits).head?=Label.cut (low||b):=by cases b <;> cases low <;> rfl\n      rw [hlabel] at h1\n      have h2:=ih bits (low||b)\n      have h:=join (join h0 h1) h2\n      rw [Bool.or_assoc] at h\n      simp only [Old.cut]\n      convert h using 1; omega\n/-- A literal false pushed during each marker visit has exactly the intended zero-prefix order. -/\ntheorem zeros_push (a:Nat) (word:List Bool) :\n    List.replicate a false++false::word=List.replicate (a+1) false++word :=by\n  induction a with\n  | zero=>rfl\n  | succ a ih=>simpa only [List.replicate_succ,List.cons_append] using congrArg (List.cons false) ih\n/-- Only the actual second exponent copy and actual high counter word vary in this physical loop. -/\ndef prefixWords (w:Words) (a:Nat) (bits:List Bool) :Words:=\n  {w with prefixTodo:=List.replicate a true,frequency:={w.frequency with count:=bits}}\n/-- Exactly one actual false bit per acquired exponent marker, never a unary packet-size or unary numerical maximum expansion. -/\ntheorem prefix_run (a:Nat) (bits:List Bool) (w:Words) :\n    Runs program (2*a+1) .prefix (bank (prefixWords w a bits)) .reverse\n      (bank (prefixWords w 0 (List.replicate a false++bits))) :=by\n  induction a generalizing bits with\n  | zero=>\n    have h:=pop_run .prefix .reverse .abort .zero (aux .prefixTodo) (bank (prefixWords w 0 bits)) [] rfl rfl\n    rw [update_prefixTodo] at h\n    exact h\n  | succ a ih=>\n    have h0:=pop_run .prefix .reverse .abort .zero (aux .prefixTodo) (bank (prefixWords w (a+1) bits)) (true::List.replicate a true) rfl rfl\n    rw [update_prefixTodo] at h0\n    have h1:=push_run .zero .prefix (frequencyStack (F.aux .count)) false (bank (prefixWords w a bits)) rfl\n    rw [update_count] at h1\n    have h2:=ih (false::bits)\n    have h:=join (join h0 h1) h2\n    rw [zeros_push] at h\n    convert h using 1; omega\nend RiemannGaussian.SemiprimeD1StackSourcePacketPaddingBits\n","RiemannGaussian.SemiprimeD1StackSourcePacketPaddingBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingExecution\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingMeaning\n/-! # Same whole source has a fixed physical-input polynomial bit clock -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourcePacketPaddingBounds\nopen SemiprimeD1StackSourcePacketPadding SemiprimeD1StackSourcePacketPaddingEncoding\nopen SemiprimeD1StackSourcePacketPaddingExecution SemiprimeD1StackSourcePacketPaddingMeaning\nopen SemiprimeD1StackSourcePacketPaddingSetup SemiprimeD1StackSourcePacketPaddingFinish\nnamespace FB\nexport SemiprimeD1StackSourceKeyFrequencyBytes (Sized step_sized empty_sized input_bounds)\nend FB\n/-- The actual whole frequency fold has one retained override and at most one added counter bit per occurrence. -/\ntheorem fold_sized (keys:List (List Bool)) (m W:Nat) (s:FE.Summary) (hs:FB.Sized m W s)\n    (hr:∀raw∈keys,raw.length≤ W) :\n    FB.Sized (m+keys.length) W (keys.foldl SemiprimeD1StackSourceKeyFrequencyEncoding.step s) :=by\n  induction keys generalizing m s with\n  | nil=>simpa only [List.foldl_nil,List.length_nil,Nat.add_zero] using hs\n  | cons raw keys ih=>\n    have hraw:=hr raw List.mem_cons_self\n    simpa only [List.foldl_cons,List.length_cons,Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using\n      ih (m+1) (SemiprimeD1StackSourceKeyFrequencyEncoding.step s raw) (FB.step_sized m W s raw hs hraw)\n        (fun raw hh=>hr raw (List.mem_cons_of_mem _ hh))\n/-- Actual acquired maximum width comes from the executed binary increments, with no supplied counter Fits premise. -/\ntheorem maximum_length (keys:List (List Bool)) :(FE.acquire keys).maximum.length≤ keys.length :=by\n  have h:=fold_sized keys 0 (FE.inputSize keys) SemiprimeD1StackSourceKeyFrequencyEncoding.empty\n    (FB.empty_sized _) (FB.input_bounds keys).2.2\n  simpa only [Nat.zero_add,SemiprimeD1StackSourceKeyFrequencyEncoding.acquire] using h.maximum\n/-- The separately paid adapter is linear in actual unary exponent bytes and binary maximum bytes. -/\ntheorem roundTime_le (a:Nat) (bits:List Bool) :roundTime a bits≤1000*(a+bits.length+1) :=by\n  have hp:=prefixed_length a bits\n  have ht:=SemiprimeD1StackReduceExecution.trimTime_le (prefixed a bits).reverse\n  rw [List.length_reverse] at ht\n  unfold roundTime setupTime finishTime\n  omega\n/-- Conservative fifth-degree clock for the whole two-input actual frequency-and-padding program. -/\ndef polynomial (keys:List (List Bool)) (a:Nat) :Nat:=100000000000*(inputSize keys a)^5\n/-- Every old dictionary record, exponent marker, actual low read and returned bit belongs to this SAME physical clock. -/\ntheorem runBound_le (keys:List (List Bool)) (a:Nat) :runBound keys a≤ polynomial keys a :=by\n  let S:=inputSize keys a\n  have hF:FE.inputSize keys≤ S:=by dsimp [S,inputSize];omega\n  have hS:1≤ S:=(FB.input_bounds keys).1.trans hF\n  have ha:a≤ S:=by dsimp [S,inputSize];omega\n  have hm:(FE.acquire keys).maximum.length≤ S:=\n    (maximum_length keys).trans ((FB.input_bounds keys).2.1.trans hF)\n  have ht:=SemiprimeD1StackSourceKeyFrequencyBounds.runBound_le keys\n  unfold SemiprimeD1StackSourceKeyFrequencyBounds.polynomial at ht\n  have hp:(FE.inputSize keys)^5≤ S^5:=Nat.pow_le_pow_left hF 5\n  have hfreq:SemiprimeD1StackSourceKeyFrequencyExecution.runBound keys≤1000000000*S^5:=\n    ht.trans (Nat.mul_le_mul_left _ hp)\n  have hround:=roundTime_le a (FE.acquire keys).maximum\n  have h15:S≤ S^5:=Nat.le_pow (by decide:0<(5:Nat))\n  change runBound keys a≤100000000000*S^5\n  unfold runBound\n  nlinarith only [hfreq,hround,ha,hm,hS,h15]\n/-- Complete actual source produces its exact compact output within the fixed whole physical-input clock. -/\ntheorem source_run_bounded (keys:List (List Bool)) (a:Nat) :\n    ∃q≤ polynomial keys a,SemiprimeD1StackCalls.run program q (source keys a)=some (done keys a) :=by\n  obtain ⟨q,hq,hr⟩:=source_run keys a\n  exact ⟨q,hq.trans (runBound_le keys a),hr⟩\n/-- The genuine25-role finite machine has the SAME polynomial whole-source certificate. -/\nnoncomputable def machineSource (keys:List (List Bool)) (a:Nat) :\n    StateTransition.EvalsToInTime machine.step (SemiprimeD1StackCalls.configuration (source keys a))\n      (some (SemiprimeD1StackCalls.configuration (done keys a))) (polynomial keys a) :=by\n  apply SemiprimeD1StackCalls.evalsCorrect (frequencyStack (F.aux .source)) (aux .padding) .start program\n  let h:=source_run_bounded keys a\n  exact ⟨⟨Classical.choose h,(Classical.choose_spec h).2⟩,(Classical.choose_spec h).1⟩\nend RiemannGaussian.SemiprimeD1StackSourcePacketPaddingBounds\n","RiemannGaussian.SemiprimeD1StackSourcePacketPaddingMeaning":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourcePacketPaddingEncoding\n/-! # Exact original packet-multiple ceiling, including zero and exponent zero -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourcePacketPaddingMeaning\nopen SemiprimeD1StackSourcePacketPaddingEncoding\nopen SemiprimeBitArithmetic (bitValue)\n/-- Actual reverse/trim preserves the zero-prefixed high-suffix value. -/\ntheorem rounded_value (a:Nat) (bits:List Bool) :\n    bitValue (rounded a bits)=2^a*(bitValue (high a bits)+if (SemiprimeD1PacketRoundBits.cut a bits).low then 1 else 0) :=by\n  rw [rounded,SemiprimeD1StackReduceExecution.trimReverse_value,List.reverse_reverse,prefixed,\n    SemiprimeD1PacketRoundBits.zero_prefix_value]\n  unfold roundedHigh\n  split_ifs <;> simp only [SemiprimeD1StackSourceEnvironmentEncoding.successor_value,Nat.add_zero]\n/-- The returned binary word has no high-order zeros, including the empty zero encoding. -/\ntheorem rounded_compact (a:Nat) (bits:List Bool) :SemiprimeSourceCompactBits.Compact (rounded a bits) :=\n  SemiprimeD1StackReduceExecution.trimReverse_compact _\n/-- The entire actual output word equals the frozen original PacketRoundBits ceiling; its old report clock is unused. -/\ntheorem rounded_original (a:Nat) (bits:List Bool) :rounded a bits=(SemiprimeD1PacketRoundBits.round a bits).bits :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ (rounded_compact a bits)\n    (SemiprimeD1PacketRoundBits.round_compact a bits)\n  rw [rounded_value,SemiprimeD1PacketRoundBits.round_value]\n  rfl\n/-- Zero maximum remains zero for every acquired unary exponent, with no forced packet allocation. -/\ntheorem rounded_zero (a:Nat) :rounded a []=[] :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective (rounded a []) [] (rounded_compact a []) trivial\n  rw [rounded_value]\n  cases a <;> rfl\n/-- At exponent zero the source preserves every compact binary maximum exactly. -/\ntheorem rounded_at_zero (bits:List Bool) (h:SemiprimeSourceCompactBits.Compact bits) :rounded 0 bits=bits :=by\n  apply SemiprimeSourceCompactWordIds.compact_value_injective _ _ (rounded_compact 0 bits) h\n  rw [rounded_value]\n  simp only [SemiprimeD1PacketRoundBits.cut,high,SemiprimeSourceCompactBits.copy_bits,pow_zero,Bool.false_eq_true,ite_false,Nat.add_zero,Nat.one_mul]\n/-- No word longer than the acquired exponent plus the actual maximum and one carry is constructed as the final padded binary word. -/\ntheorem prefixed_length (a:Nat) (bits:List Bool) :(prefixed a bits).length≤ a+bits.length+1 :=by\n  have hh:(high a bits).length≤ bits.length:=SemiprimeD1PacketRoundBits.cut_length a bits\n  have hs:=SemiprimeD1StackSourceEnvironmentEncoding.successor_length (high a bits)\n  unfold prefixed roundedHigh\n  split_ifs <;> simp only [List.length_append,List.length_replicate] <;> omega\nend RiemannGaussian.SemiprimeD1StackSourcePacketPaddingMeaning\n","RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLookup":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysView\n/-! # Actual TRUEfound guarded ID lookup, paid ID saves and complete temporary cleanup -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLookup\nopen SemiprimeD1StackSourceSelectedKeys SemiprimeD1StackSourceSelectedKeysEncoding\nopen SemiprimeD1StackSourceSelectedKeysPrimitives SemiprimeD1StackSourceSelectedKeysView\nopen SemiprimeD1StackProcedureTrace\n/-- Proof-side current raw variable-key word, determined by the fixed owner/factor source address. -/\ndef queryWord :Part→List Bool→List Bool→List Bool | .owner,own,_=>own | .factor,_,fac=>fac\n/-- The actual key address retains the physically parsed bytes for its fixed role. -/\ntheorem variable_projection (i:Inputs) (q present returned reader own fac ownID key valid buffer hist out:List Bool) (part:Part) :\n    view i q present returned reader own fac ownID key valid buffer hist out (variableKey part)=queryWord part own fac :=by\n  cases part <;> rfl\n/-- Own actual complete-copy/lookup clock for the current physically acquired variable key. -/\ndef lookupClock (i:Inputs) (word:List Bool) :Nat :=\n  201*(word.length+1)*((Env.dictionary i.ids).length+1)+10*(word.length+(readID i.ids word).length+1)+20\n/-- Physical key copy and real dictionary call reach actualfoundTRUE; fixedIDzero remains a valid present payload. -/\ntheorem lookup_stage (i:Inputs) (part:Part) (reader own fac ownID key valid buffer hist out:List Bool)\n    (hp:SemiprimeBitArithmetic.bitValue (queryWord part own fac) < i.ids.length) :\n    ∃t≤201*((queryWord part own fac).length+1)*((Env.dictionary i.ids).length+1)+5*(queryWord part own fac).length+5,\n      Runs program t (.copyQuery part) (view i [] [] [] reader own fac ownID key valid buffer hist out) (.readFound part)\n        (view i (queryWord part own fac) [true] (readID i.ids (queryWord part own fac)) reader own fac ownID key valid buffer hist out) :=by\n  have h0:=copy_call (.query part) (.copyQuery part) (.lookup part) rfl\n    (view i [] [] [] reader own fac ownID key valid buffer hist out) rfl rfl\n  change Runs program (5*(view i [] [] [] reader own fac ownID key valid buffer hist out (variableKey part)).length+4) _ _ _\n    (Function.update (view i [] [] [] reader own fac ownID key valid buffer hist out) query\n      (view i [] [] [] reader own fac ownID key valid buffer hist out (variableKey part))) at h0\n  rw [variable_projection,update_q] at h0\n  change Runs program (5*(queryWord part own fac).length+4) _ _ _\n    (view i (queryWord part own fac) [] [] reader own fac ownID key valid buffer hist out) at h0\n  obtain ⟨t,ht,h1⟩:=lookup_call part (view i (queryWord part own fac) [] [] reader own fac ownID key valid buffer hist out)\n    i.ids i.chosen (queryWord part own fac) i.pfx\n    (environment_projection i (queryWord part own fac) reader own fac ownID key valid buffer hist out)\n  have he:Sum.elim (SemiprimeD1StackSourceEnvironmentExecution.lookupDone i.ids i.chosen (queryWord part own fac) i.pfx).data\n      (fun k=>view i (queryWord part own fac) [] [] reader own fac ownID key valid buffer hist out (aux k))=\n      view i (queryWord part own fac) [decide (SemiprimeBitArithmetic.bitValue (queryWord part own fac) < i.ids.length)]\n        (if SemiprimeBitArithmetic.bitValue (queryWord part own fac) < i.ids.length then\n          readID i.ids (queryWord part own fac) else []) reader own fac ownID key valid buffer hist out:=by\n    funext k\n    rcases k with k|k\n    · rfl\n    · cases k <;> rfl\n  rw [he] at h1\n  simp only [hp,decide_true,ite_true] at h1\n  exact ⟨_,by omega,join h0 h1⟩\n/-- The actual true-found singleton is physically popped before any returned ID is used. -/\ntheorem found_true (i:Inputs) (part:Part) (q returned reader own fac ownID key valid buffer hist out:List Bool) :\n    Runs program 1 (.readFound part) (view i q [true] returned reader own fac ownID key valid buffer hist out) (.copyID part)\n      (view i q [] returned reader own fac ownID key valid buffer hist out) :=by\n  have h:=pop_run (.readFound part) .abort .abort (.copyID part) found\n    (view i q [true] returned reader own fac ownID key valid buffer hist out) [true] rfl rfl\n  change Runs program 1 _ _ _\n    (Function.update (view i q [true] returned reader own fac ownID key valid buffer hist out) found []) at h\n  rw [update_present] at h\n  exact h\n/-- The actual owner ID is saved before the second physical lookup changes the shared returned-ID slot. -/\ntheorem save_owner (i:Inputs) (q returned reader own fac valid buffer hist out:List Bool) :\n    Runs program (5*returned.length+4) (.copyID .owner) (view i q [] returned reader own fac [] [] valid buffer hist out)\n      (.clearID .owner) (view i q [] returned reader own fac returned [] valid buffer hist out) :=by\n  have h:=copy_call (.id .owner) (.copyID .owner) (.clearID .owner) rfl\n    (view i q [] returned reader own fac [] [] valid buffer hist out) rfl rfl\n  change Runs program (5*returned.length+4) _ _ _\n    (Function.update (view i q [] returned reader own fac [] [] valid buffer hist out) (aux .ownerID) returned) at h\n  rw [update_ownID] at h\n  exact h\n/-- The actual factor ID is copied directly into the eventual joint-key raw tail, paying every bit. -/\ntheorem save_factor (i:Inputs) (q returned reader own fac ownID valid buffer hist out:List Bool) :\n    Runs program (5*returned.length+4) (.copyID .factor) (view i q [] returned reader own fac ownID [] valid buffer hist out)\n      (.clearID .factor) (view i q [] returned reader own fac ownID returned valid buffer hist out) :=by\n  have h:=copy_call (.id .factor) (.copyID .factor) (.clearID .factor) rfl\n    (view i q [] returned reader own fac ownID [] valid buffer hist out) rfl rfl\n  change Runs program (5*returned.length+4) _ _ _\n    (Function.update (view i q [] returned reader own fac ownID [] valid buffer hist out) (aux .key) returned) at h\n  rw [update_key] at h\n  exact h\n/-- Each actual returned ID and query is physically drained, restoring the shared Env25 operation slots. -/\ntheorem cleanup (i:Inputs) (part:Part) (q returned reader own fac ownID key valid buffer hist out:List Bool) :\n    Runs program ((returned.length+1)+(q.length+1)) (.clearID part)\n      (view i q [] returned reader own fac ownID key valid buffer hist out) (afterLookup part)\n      (view i [] [] [] reader own fac ownID key valid buffer hist out) :=by\n  have h0:=drain_loop (.clearID part) (.clearQuery part) idOutput rfl\n    (view i q [] returned reader own fac ownID key valid buffer hist out) returned rfl\n  rw [update_returned] at h0\n  have h1:=drain_loop (.clearQuery part) (afterLookup part) query rfl\n    (view i q [] [] reader own fac ownID key valid buffer hist out) q rfl\n  rw [update_q] at h1\n  exact join h0 h1\n/-- Complete actual owner-ID read with a true-found guard and all shared lookup temporaries cleared. -/\ntheorem owner_run (i:Inputs) (reader own fac hist:List Bool) (hp:SemiprimeBitArithmetic.bitValue own < i.ids.length) :\n    ∃q≤lookupClock i own,Runs program q (.copyQuery .owner) (view i [] [] [] reader own fac [] [] [] [] hist [])\n      (.copyQuery .factor) (view i [] [] [] reader own fac (readID i.ids own) [] [] [] hist []) :=by\n  obtain ⟨q,hq,h0⟩:=lookup_stage i .owner reader own fac [] [] [] [] hist [] hp\n  have h1:=found_true i .owner own (readID i.ids own) reader own fac [] [] [] [] hist []\n  have h2:=save_owner i own (readID i.ids own) reader own fac [] [] hist []\n  have h3:=cleanup i .owner own (readID i.ids own) reader own fac (readID i.ids own) [] [] [] hist []\n  refine ⟨_,?_,join (join (join h0 h1) h2) h3⟩\n  unfold lookupClock\n  change q≤201*(own.length+1)*((Env.dictionary i.ids).length+1)+5*own.length+5 at hq\n  omega\n/-- Complete actual factor-ID read leaves the saved owner ID and RAWfactor-ID joint tail ready for real Frame. -/\ntheorem factor_run (i:Inputs) (reader own fac hist:List Bool) (hp:SemiprimeBitArithmetic.bitValue fac < i.ids.length) :\n    ∃q≤lookupClock i fac,Runs program q (.copyQuery .factor)\n      (view i [] [] [] reader own fac (readID i.ids own) [] [] [] hist []) .frameJoint\n      (view i [] [] [] reader own fac (readID i.ids own) (readID i.ids fac) [] [] hist []) :=by\n  obtain ⟨q,hq,h0⟩:=lookup_stage i .factor reader own fac (readID i.ids own) [] [] [] hist [] hp\n  have h1:=found_true i .factor fac (readID i.ids fac) reader own fac (readID i.ids own) [] [] [] hist []\n  have h2:=save_factor i fac (readID i.ids fac) reader own fac (readID i.ids own) [] [] hist []\n  have h3:=cleanup i .factor fac (readID i.ids fac) reader own fac (readID i.ids own) (readID i.ids fac) [] [] hist []\n  refine ⟨_,?_,join (join (join h0 h1) h2) h3⟩\n  unfold lookupClock\n  change q≤201*(fac.length+1)*((Env.dictionary i.ids).length+1)+5*fac.length+5 at hq\n  omega\nend RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLookup\n","RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLoop":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysParse\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysBody\n/-! # Complete physical occurrence traversal and exact chronological selected-key log -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLoop\nopen SemiprimeD1StackSourceSelectedKeys SemiprimeD1StackSourceSelectedKeysEncoding\nopen SemiprimeD1StackSourceSelectedKeysPrimitives SemiprimeD1StackSourceSelectedKeysView\nopen SemiprimeD1StackSourceSelectedKeysParse SemiprimeD1StackSourceSelectedKeysBody\nopen SemiprimeD1StackProcedureTrace\n/-- Actual row clock includes original pair-tag/field parsing and every subsequent physical producer stage. -/\ndef rowTime (i:Inputs) (own fac:List Bool) :Nat :=8*(own.length+fac.length)+17+bodyTime i own fac\n/-- Own complete scan upper clock, with its actual terminal false pop. -/\ndef rowsTime (i:Inputs) (rows:List (List Bool×List Bool)) :Nat :=\n  rows.foldr (fun row rest=>rowTime i row.1 row.2+rest) 1\n/-- Each physical original occurrence emits exactly one complete oldjoint key in its input position. -/\ntheorem rows_run (i:Inputs) (rows:List (List Bool×List Bool)) (hist:List Bool)\n    (hc:∀row∈rows,SemiprimeBitArithmetic.bitValue row.1 < i.ids.length ∧ SemiprimeBitArithmetic.bitValue row.2 < i.ids.length) :\n    ∃q≤rowsTime i rows,\n      Runs program q .header (view i [] [] [] (Records.records rows []) [] [] [] [] [] [] hist []) .eof\n        (view i [] [] [] [] [] [] [] [] [] [] ((stream i.ids rows).reverse++hist) []) :=by\n  induction rows generalizing hist with\n  | nil=>\n    have h:=pop_run .header .abort .eof (.parse .owner) (aux .reader)\n      (view i [] [] [] (Records.records [] []) [] [] [] [] [] [] hist []) [false] rfl rfl\n    change Runs program 1 _ _ _ (Function.update\n      (view i [] [] [] (Records.records [] []) [] [] [] [] [] [] hist []) (aux .reader) []) at h\n    rw [update_reader] at h\n    exact ⟨1,le_rfl,h⟩\n  | cons row rows ih=>\n    rcases row with ⟨own,fac⟩\n    have hh:=hc (own,fac) List.mem_cons_self\n    have ht:∀row∈rows,SemiprimeBitArithmetic.bitValue row.1 < i.ids.length ∧ SemiprimeBitArithmetic.bitValue row.2 < i.ids.length:=\n      fun row h=>hc row (List.mem_cons_of_mem _ h)\n    have h0:=read_row i own fac hist rows\n    obtain ⟨q,hq,h1⟩:=body_run i (Records.records rows []) own fac hist hh.1 hh.2\n    obtain ⟨u,hu,h2⟩:=ih ((chunk i.ids (own,fac)).reverse++hist) ht\n    have h:=join (join h0 h1) h2\n    have he:(stream i.ids ((own,fac)::rows)).reverse++hist=\n        (stream i.ids rows).reverse++((chunk i.ids (own,fac)).reverse++hist):=by\n      change (chunk i.ids (own,fac)++stream i.ids rows).reverse++hist=_\n      rw [List.reverse_append,List.append_assoc]\n    refine ⟨_,?_,by rw [he];exact h⟩\n    change 8*(own.length+fac.length)+17+q+u ≤ rowTime i own fac+rowsTime i rows\n    unfold rowTime\n    omega\nend RiemannGaussian.SemiprimeD1StackSourceSelectedKeysLoop\n","RiemannGaussian.SemiprimeD1StackSourceSelectionAcquire":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceOccurrencesOriginal\nimport RiemannGaussian.SemiprimeD1StackSourceAlphabet64Original\nimport RiemannGaussian.SemiprimeD1StackSourceIncidenceSelectOriginal\nimport RiemannGaussian.SemiprimeD1StackSourceSelectedKeysOriginal\n/-! # Actual rows/count/dimension to the complete original selected-key vector\nOnly the physical owner-row tape, actual unary n and actual unary a enter.\nThe program really acquires occurrences/F, acquires the complete alphabet and\npowers, selects every original variable, then reads every selected joint key.\nEleven preserving copies connect the actual stopped banks. Every154 allocated\nrole is counted. No graph, selected prefix, dictionary, count, score or key\ngetter is a runtime operand; original-N acquisition is an upstream caller join.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectionAcquire\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State)\nend C\nnamespace Occ\nexport SemiprimeD1StackSourceOccurrences (Stack Label program initial stack_card)\nend Occ\nnamespace Alpha\nexport SemiprimeD1StackSourceAlphabet64 (Stack Label program initial aux stack_card)\nend Alpha\nnamespace Select\nexport SemiprimeD1StackSourceIncidenceSelect\n  (Stack Label program queryStack aux dictionary nextKey selected stack_card)\nend Select\nnamespace Keys\nexport SemiprimeD1StackSourceSelectedKeys (Stack Label program environmentStack aux stack_card)\nend Keys\nnamespace Env\nexport SemiprimeD1StackSourceEnvironment (Stack aux)\nend Env\n/-- All21 occurrence,30 alphabet,63 selector,39 selected-key and one actual copy-scratch roles. -/\nabbrev Stack :=Occ.Stack⊕(Alpha.Stack⊕(Select.Stack⊕(Keys.Stack⊕Unit)))\n/-- Complete actual occurrence acquisition bank. -/\ndef occurrenceStack :Occ.Stack→Stack :=Sum.inl\n/-- Complete actual alphabet acquisition bank. -/\ndef alphabetStack (k:Alpha.Stack) :Stack :=.inr (.inl k)\n/-- Complete actual selector bank, including every actual query/cache field. -/\ndef selectorStack (k:Select.Stack) :Stack :=.inr (.inr (.inl k))\n/-- Complete actual selected-key source bank, including every retained environment field. -/\ndef keyStack (k:Keys.Stack) :Stack :=.inr (.inr (.inr (.inl k)))\n/-- One restoring-copy scratch; every component shadow remains allocated. -/\ndef copyScratch :Stack :=.inr (.inr (.inr (.inr ())))\n/-- Eleven fixed copy code sites, independent of every data count or selected value. -/\ninductive Copy where\n  | occurrences | catalogue | square | cube | fourth | owners | factors | dictionary | nextKey | prefix | keySource\n  deriving DecidableEq,Repr\ninstance :Fintype Copy :=Fintype.ofList\n  [.occurrences,.catalogue,.square,.cube,.fourth,.owners,.factors,.dictionary,.nextKey,.prefix,.keySource]\n  (by intro k;cases k <;> simp)\n/-- Every handoff reads an actual acquired or selected physical word. -/\ndef copySource :Copy→Stack\n  | .occurrences=>occurrenceStack .output\n  | .catalogue=>alphabetStack (Alpha.aux .output)\n  | .square=>alphabetStack (Alpha.aux .square)\n  | .cube=>alphabetStack (Alpha.aux .cube)\n  | .fourth=>alphabetStack (Alpha.aux .fourth)\n  | .owners=>occurrenceStack .number\n  | .factors=>occurrenceStack .factors\n  | .dictionary=>selectorStack Select.dictionary\n  | .nextKey=>selectorStack Select.nextKey\n  | .prefix=>selectorStack Select.selected\n  | .keySource=>selectorStack (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .source))\n/-- Only the literal source/cache roles required by the next real component are populated. -/\ndef copyTarget :Copy→Stack\n  | .occurrences=>selectorStack (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .source))\n  | .catalogue=>selectorStack (Select.aux .catalogue)\n  | .square=>selectorStack (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .square))\n  | .cube=>selectorStack (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .cube))\n  | .fourth=>selectorStack (Select.queryStack (SemiprimeD1StackSourceIncidence.aux .fourth))\n  | .owners=>selectorStack (Select.aux .owners)\n  | .factors=>selectorStack (Select.aux .factors)\n  | .dictionary=>keyStack (Keys.environmentStack (Env.aux .dictionary))\n  | .nextKey=>keyStack (Keys.environmentStack (Env.aux .nextKey))\n  | .prefix=>keyStack (Keys.environmentStack (Env.aux .prefix))\n  | .keySource=>keyStack (Keys.aux .source)\n/-- All actual preserving copies have separate source, destination and restoration scratch. -/\ndef copyStack (site:Copy) (k:Fin 3) :Stack :=\n  if k=0 then copySource site else if k=1 then copyTarget site else copyScratch\n/-- Whole acquisition/copy/selection/key/halt control is fixed finite before all input families. -/\ninductive Control where | start | alphabet | copy (site:Copy) | select | keys | done\n  deriving DecidableEq,Fintype\n/-- All four actual component and primitive return labels are fixed finite. -/\ninductive Label where\n  | local (pc:Control) | occurrence (pc:Occ.Label) | alphabet (pc:Alpha.Label)\n  | selector (pc:Select.Label) | keys (pc:Keys.Label) | copy (site:Copy) (pc:Fin 9)\n  deriving Fintype\nlocal notation \"ctl\" => Label.local\n/-- The literal next code address at each actual paid copy site. -/\ndef copyNext :Copy→Label\n  | .occurrences=>ctl (.copy .catalogue)\n  | .catalogue=>ctl (.copy .square)\n  | .square=>ctl (.copy .cube)\n  | .cube=>ctl (.copy .fourth)\n  | .fourth=>ctl (.copy .owners)\n  | .owners=>ctl (.copy .factors)\n  | .factors=>ctl .select\n  | .dictionary=>ctl (.copy .nextKey)\n  | .nextKey=>ctl (.copy .prefix)\n  | .prefix=>ctl (.copy .keySource)\n  | .keySource=>ctl .keys\n/-- One actual three-input source performs every occurrence/alphabet/selector/selected-key stage. -/\ndef program :Label→C.Instruction Stack Label\n  | .local .start=>.call (.occurrence (.local .start)) (ctl .alphabet)\n  | .local .alphabet=>.call (.alphabet .start) (ctl (.copy .occurrences))\n  | .local (.copy site)=>.call (.copy site 0) (copyNext site)\n  | .local .select=>.call (.selector (.local .start)) (ctl (.copy .dictionary))\n  | .local .keys=>.call (.keys .start) (ctl .done)\n  | .local .done=>.base .halt\n  | .occurrence pc=>SemiprimeD1StackValidationLink.instruction occurrenceStack Label.occurrence (Occ.program pc)\n  | .alphabet pc=>SemiprimeD1StackValidationLink.instruction alphabetStack Label.alphabet (Alpha.program pc)\n  | .selector pc=>SemiprimeD1StackValidationLink.instruction selectorStack Label.selector (Select.program pc)\n  | .keys pc=>SemiprimeD1StackValidationLink.instruction keyStack Label.keys (Keys.program pc)\n  | .copy site pc=>SemiprimeD1StackMultiplierLink.instruction (copyStack site) (Label.copy site) (SemiprimeD1StackCopy.code pc)\n/-- Every actual component/cache/shadow word and the one scratch are included in the physical boundary. -/\ndef data (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool)\n    (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) :Stack→List Bool :=\n  Sum.elim occurrences (Sum.elim alphabet (Sum.elim selector (Sum.elim keys (fun _=>scratch))))\n/-- Exactly three original physical words, with every derived154-role word initially empty. -/\ndef input (rows number dimension:List Bool) :Stack→List Bool :=\n  data (Occ.initial rows number).data (Alpha.initial dimension).data (fun _=>[]) (fun _=>[]) []\n/-- Prepared row/count/dimension front door; no graph, F, alphabet, selection, dictionary or answer is supplied. -/\ndef initial (rows number dimension:List Bool) :C.State Stack Label :=\n  ⟨some (ctl .start),none,none,input rows number dimension,[]⟩\n/-- Genuine fixed finite154-role three-input acquisition machine. -/\ndef machine :Turing.FinTM2 :=SemiprimeD1StackCalls.machine\n  (occurrenceStack .rows) (keyStack (Keys.aux .output)) (ctl .start) program\n/-- No actual preserving-copy operand aliases either its destination or scratch. -/\ntheorem copy_injective (site:Copy) :Function.Injective (copyStack site) :=by cases site <;> decide\n/-- All154 physical data roles, including every empty component helper/shadow, are counted. -/\ntheorem stack_card :Fintype.card Stack=154 :=by\n  rw [Fintype.card_sum,Occ.stack_card,Fintype.card_sum,Alpha.stack_card,Fintype.card_sum,Select.stack_card,\n    Fintype.card_sum,Keys.stack_card]\n  decide\n/-- No natural counter, callback, row getter, selected cache or score enters runtime control. -/\ntheorem control_finite :Finite machine.σ :=SemiprimeD1StackCalls.control_finite _ _ _ _\n/-- Every actual data and return alphabet is fixed finite before the whole infinite input family. -/\ntheorem alphabets_finite :∀k,Finite (machine.Γ k) :=SemiprimeD1StackCalls.all_alphabets_finite _ _ _ _\nend RiemannGaussian.SemiprimeD1StackSourceSelectionAcquire\n","RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireCalls":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquirePrimitives\n/-! # Four real complete acquisition calls with all other154-role fields retained -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireCalls\nopen SemiprimeD1StackSourceSelectionAcquire SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => Label.local\n/-- One real complete occurrence source call pays its own clock and preserves every other physical word. -/\ntheorem occurrence_call (n:Nat) (rows:List (List (List Bool))) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) :\n    ∃t ≤ SemiprimeD1StackSourceOccurrencesExecution.timeBound n rows+1,Runs program t (ctl .start)\n      (data (SemiprimeD1StackSourceOccurrencesExecution.source n rows).data alphabet selector keys scratch) (ctl .alphabet) (data (SemiprimeD1StackSourceOccurrencesExecution.done n rows).data alphabet selector keys scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceOccurrencesExecution.source_run n rows\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program occurrenceStack Label.occurrence\n    (fun _ _ h=>Sum.inl.inj (h)) Occ.program (.local .start) (fun _=>rfl) (ctl .start) (ctl .alphabet) rfl t\n    (SemiprimeD1StackSourceOccurrencesExecution.source n rows) (SemiprimeD1StackSourceOccurrencesExecution.done n rows) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · exact (hk k rfl).elim\n      · rfl\n/-- One real complete alphabet source call pays its own clock and preserves every other physical word. -/\ntheorem alphabet_call (a:Nat) (occurrences:Occ.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) :\n    ∃t ≤ 10000*(a+1)*(64^a+1)+1,Runs program t (ctl .alphabet)\n      (data occurrences (Alpha.initial (List.replicate a true)).data selector keys scratch) (ctl (.copy .occurrences)) (data occurrences (SemiprimeD1StackSourceAlphabet64Encoding.done a).data selector keys scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceAlphabet64Bounds.source_run_bounded a\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program alphabetStack Label.alphabet\n    (fun _ _ h=>Sum.inl.inj (Sum.inr.inj (h))) Alpha.program .start (fun _=>rfl) (ctl .alphabet) (ctl (.copy .occurrences)) rfl t\n    (Alpha.initial (List.replicate a true)) (SemiprimeD1StackSourceAlphabet64Encoding.done a) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · exact (hk k rfl).elim\n        · rfl\n/-- One real complete selector source call pays its own clock and preserves every other physical word. -/\ntheorem selector_call (i:SemiprimeD1StackSourceIncidenceSelectExecution.Inputs) (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) :\n    ∃t ≤ SemiprimeD1StackSourceIncidenceSelectClock.polynomial i+1,Runs program t (ctl .select)\n      (data occurrences alphabet (SemiprimeD1StackSourceIncidenceSelectExecution.source i).data keys scratch) (ctl (.copy .dictionary)) (data occurrences alphabet (SemiprimeD1StackSourceIncidenceSelectExecution.done i).data keys scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceIncidenceSelectClock.source_run_bounded i\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program selectorStack Label.selector\n    (fun _ _ h=>Sum.inl.inj (Sum.inr.inj (Sum.inr.inj (h)))) Select.program (.local .start) (fun _=>rfl) (ctl .select) (ctl (.copy .dictionary)) rfl t\n    (SemiprimeD1StackSourceIncidenceSelectExecution.source i) (SemiprimeD1StackSourceIncidenceSelectExecution.done i) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · exact (hk k rfl).elim\n          · rfl\n/-- One real complete keys source call pays its own clock and preserves every other physical word. -/\ntheorem keys_call (i:SemiprimeD1StackSourceSelectedKeysEncoding.Inputs) (hc:SemiprimeD1StackSourceSelectedKeysEncoding.Complete i) (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (scratch:List Bool) :\n    ∃t ≤ SemiprimeD1StackSourceSelectedKeysBounds.polynomial i+1,Runs program t (ctl .keys)\n      (data occurrences alphabet selector (SemiprimeD1StackSourceSelectedKeysEncoding.source i).data scratch) (ctl .done) (data occurrences alphabet selector (SemiprimeD1StackSourceSelectedKeysEncoding.done i).data scratch) :=by\n  obtain ⟨t,ht,hr⟩:=SemiprimeD1StackSourceSelectedKeysBounds.source_run_bounded i hc\n  refine ⟨t+1,by omega,?_⟩\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program keyStack Label.keys\n    (fun _ _ h=>Sum.inl.inj (Sum.inr.inj (Sum.inr.inj (Sum.inr.inj (h))))) Keys.program .start (fun _=>rfl) (ctl .keys) (ctl .done) rfl t\n    (SemiprimeD1StackSourceSelectedKeysEncoding.source i) (SemiprimeD1StackSourceSelectedKeysEncoding.done i) _ _ rfl rfl rfl rfl hr\n  · constructor\n    · intro k;rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · rcases k with k|k\n          · rfl\n          · rcases k with k|k\n            · exact (hk k rfl).elim\n            · rfl\nend RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireCalls\n\n","RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireView":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSourceSelectionAcquire\n/-! # Complete actual154-role source/cache boundaries and literal updates -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxRecDepth 32768\nset_option synthInstance.maxSize 262144\nnamespace RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireView\nopen SemiprimeD1StackSourceSelectionAcquire\n/-- An actual occurrences update preserves every other physical component and copy scratch. -/\ntheorem data_occurrences (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch xs:List Bool) (k:Occ.Stack) :\n    Function.update (data occurrences alphabet selector keys scratch) (occurrenceStack k) xs=data (Function.update occurrences k xs) alphabet selector keys scratch :=by\n  funext p\n  rcases p with p|p\n  · simp only [data,occurrenceStack,Function.update_apply,Sum.elim_inl,Sum.inl.injEq]\n  · rfl\n/-- Every actual occurrences word has its identical physical source projection. -/\ntheorem occurrences_word (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) (k:Occ.Stack) :\n    data occurrences alphabet selector keys scratch (occurrenceStack k)=occurrences k :=rfl\n/-- An actual alphabet update preserves every other physical component and copy scratch. -/\ntheorem data_alphabet (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch xs:List Bool) (k:Alpha.Stack) :\n    Function.update (data occurrences alphabet selector keys scratch) (alphabetStack k) xs=data occurrences (Function.update alphabet k xs) selector keys scratch :=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · simp only [data,alphabetStack,Function.update_apply,Sum.elim_inr,Sum.inr.injEq,Sum.elim_inl,Sum.inl.injEq]\n    · rfl\n/-- Every actual alphabet word has its identical physical source projection. -/\ntheorem alphabet_word (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) (k:Alpha.Stack) :\n    data occurrences alphabet selector keys scratch (alphabetStack k)=alphabet k :=rfl\n/-- An actual selector update preserves every other physical component and copy scratch. -/\ntheorem data_selector (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch xs:List Bool) (k:Select.Stack) :\n    Function.update (data occurrences alphabet selector keys scratch) (selectorStack k) xs=data occurrences alphabet (Function.update selector k xs) keys scratch :=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · rfl\n    · rcases p with p|p\n      · simp only [data,selectorStack,Function.update_apply,Sum.elim_inr,Sum.inr.injEq,Sum.elim_inl,Sum.inl.injEq]\n      · rfl\n/-- Every actual selector word has its identical physical source projection. -/\ntheorem selector_word (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) (k:Select.Stack) :\n    data occurrences alphabet selector keys scratch (selectorStack k)=selector k :=rfl\n/-- An actual keys update preserves every other physical component and copy scratch. -/\ntheorem data_keys (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch xs:List Bool) (k:Keys.Stack) :\n    Function.update (data occurrences alphabet selector keys scratch) (keyStack k) xs=data occurrences alphabet selector (Function.update keys k xs) scratch :=by\n  funext p\n  rcases p with p|p\n  · rfl\n  · rcases p with p|p\n    · rfl\n    · rcases p with p|p\n      · rfl\n      · rcases p with p|p\n        · simp only [data,keyStack,Function.update_apply,Sum.elim_inr,Sum.inr.injEq,Sum.elim_inl,Sum.inl.injEq]\n        · rfl\n/-- Every actual keys word has its identical physical source projection. -/\ntheorem keys_word (occurrences:Occ.Stack→List Bool) (alphabet:Alpha.Stack→List Bool) (selector:Select.Stack→List Bool) (keys:Keys.Stack→List Bool) (scratch:List Bool) (k:Keys.Stack) :\n    data occurrences alphabet selector keys scratch (keyStack k)=keys k :=rfl\nend RiemannGaussian.SemiprimeD1StackSourceSelectionAcquireView\n\n","RiemannGaussian.SemiprimeD1StackStaticRecordExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticRecordComponents\n/-! # Whole actual static-table and acquired-scope original record execution -/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1200000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackStaticRecordExecution\nopen SemiprimeD1StackStaticRecord SemiprimeD1StackStaticRecordComponents\nopen SemiprimeD1StackStaticTableSpec (CheckerTrace)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : T.Static K L)\n/-- Complete same-source clock, including table compilation, actual ordinal\nconversion, both consumed frames, all calls/returns and the final halt. -/\ndef timeBound (template : K→List Bool) (words : List (List Bool))\n    (answer : List Bool→Bool) (budget : Nat→Nat) : Nat :=\n  SemiprimeD1StackStaticTableExecution.timeBound s template words answer budget+\n    SemiprimeD1StackPortOrdinalStreamExecution.timeBound words+\n    R.recordTime (S.result words) (SemiprimeD1StackStaticTableExecution.outputTape answer words)+4\n/-- Whole actual join. The checker contract is a proof about the fixed literal\nchecker; no answer predicate, arity, table or clock belongs to the program. -/\ntheorem source_run (template : K→List Bool) (hraw : template s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat) (hc : CheckerTrace s template answer budget)\n    (words : List (List Bool)) (hist out : List Bool) :\n    ∃t≤timeBound s template words answer budget,C.run (program s) t\n      (initial s template (vectorBits words) hist out)=some (done s template words answer hist out) := by\n  obtain ⟨a,ha,h0⟩:=table_call s template hraw answer budget hc words hist out\n  obtain ⟨b,hb,h1⟩:=scope_call s template words answer hist out\n  have h2:=record_call s template words answer hist out\n  have h:=SemiprimeD1StackProcedureTrace.runs_trans (program s) _ _ _ _ _ _ _ _\n    (SemiprimeD1StackProcedureTrace.runs_trans (program s) _ _ _ _ _ _ _ _ h0 h1) h2\n  obtain ⟨finish,hr,hAt⟩:=h [] (initial s template (vectorBits words) hist out) ⟨rfl,rfl,rfl⟩\n  refine ⟨((a+1)+(b+1))+\n    (R.recordTime (S.result words) (SemiprimeD1StackStaticTableExecution.outputTape answer words)+1)+1,?_,?_⟩\n  · unfold timeBound;omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some]\n    rcases hAt with ⟨hpc,hd,hframes⟩\n    change SemiprimeD1StackCalls.step (program s) finish=some (done s template words answer hist out)\n    simp [SemiprimeD1StackCalls.step,hpc,program,SemiprimeD1StackCalls.execute,hd,hframes,done]\n/-- The same trace on the genuine finite-control machine and real return stack. -/\nnoncomputable def recordInTime [Fintype L] (template : K→List Bool) (hraw : template s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat) (hc : CheckerTrace s template answer budget)\n    (words : List (List Bool)) (hist out : List Bool) :\n    StateTransition.EvalsToInTime (machine s).step\n      (SemiprimeD1StackCalls.configuration (initial s template (vectorBits words) hist out))\n      (some (SemiprimeD1StackCalls.configuration (done s template words answer hist out)))\n      (timeBound s template words answer budget) := by\n  apply SemiprimeD1StackCalls.evalsCorrect original output (.inl .start) (program s)\n  let h:=source_run s template hraw answer budget hc words hist out\n  let t:=Classical.choose h\n  have ht:=Classical.choose_spec h\n  exact ⟨⟨t,ht.2⟩,ht.1⟩\nend RiemannGaussian.SemiprimeD1StackStaticRecordExecution\n","RiemannGaussian.SemiprimeD1StackStaticTableExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackStaticTableDFS\n/-! # Complete physical scope count, static-checker DFS and final tape reversal\nEvery runtime operand is a Boolean tape word. The checker program is static;\ntrace contracts and mathematical predicates occur only in correctness proofs.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nset_option maxHeartbeats 1800000\nset_option synthInstance.maxSize 16384\nnamespace RiemannGaussian.SemiprimeD1StackStaticTableExecution\nopen SemiprimeD1StackStaticTable SemiprimeD1StackStaticTableSpec SemiprimeD1StackStaticTableDFS\nopen SemiprimeD1StackStaticTablePrimitives SemiprimeD1StackProcedureTrace\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nvariable {K L : Type} [DecidableEq K] [Fintype K] (s : Static K L)\n/-- Actual complete output bytes, specified at the physically counted scope arity. -/\ndef outputTape (answer : List Bool→Bool) (words : List (List Bool)) : List Bool :=tape (tree answer [] words.length)\n/-- The final real store keeps the original template, original scope bank and\nthe acquired count; every checker/work/prefix/reversal scratch role is empty. -/\ndef result (original : K→List Bool) (words : List (List Bool)) (answer : List Bool→Bool) : Stack K→List Bool :=\n  Function.update (data original (vectorBits words) words.length [] []) (aux .output) (outputTape answer words)\n/-- The real final halt clears finite Boolean/return flags and actual frames. -/\ndef done (original : K→List Bool) (words : List (List Bool)) (answer : List Bool→Bool) :\n    C.State (Stack K) (Label L s.roles.length) :=⟨none,none,none,result original words answer,[]⟩\nomit [Fintype K] in\n/-- The actual bank scanner acquires arity from real record tags, including\nempty ordinal-zero fields, while retaining all original checker inputs. -/\ntheorem count_call (original : K→List Bool) (words : List (List Bool)) :\n    Runs (program s) (SemiprimeD1StackDigitCountExecution.totalTime words+1) .start\n      (data original (vectorBits words) 0 [] []) .build\n      (data original (vectorBits words) words.length [] []) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call (program s) counter Label.counter\n    (by intro a b h;exact Sum.inl.inj (Sum.inr.inj (Sum.inr.inj h))) D.program (.inl .main)\n    (fun _=>rfl) .start .build rfl _\n    (SemiprimeD1StackDigitCountExecution.initial (vectorBits words))\n    (SemiprimeD1StackDigitCountExecution.done words)\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackDigitCountExecution.acquire_run words\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;cases k <;> rfl\n    · intro k hk\n      rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k with\n          | inl k=>exact (hk k rfl).elim\n          | inr k=>rfl\nomit [Fintype K] in\n/-- Exactly one physical consuming reversal writes the complete original-order tape. -/\ntheorem reverse_table (original : K→List Bool) (words : List (List Bool)) (answer : List Bool→Bool) :\n    Runs (program s) (2*(outputTape answer words).length+3) .finish\n      (data original (vectorBits words) words.length [] (outputTape answer words).reverse) .done\n      (result original words answer) := by\n  have h:=reverse_call s true .finish .done rfl\n    (data original (vectorBits words) words.length [] (outputTape answer words).reverse)\n  have hd:Function.update\n      (data original (vectorBits words) words.length [] (outputTape answer words).reverse) (aux .reversed) []=\n      data original (vectorBits words) words.length [] [] := by\n    funext k\n    rcases k with k|k\n    · rfl\n    · rcases k with k|k\n      · rfl\n      · rcases k with k|k\n        · rfl\n        · cases k <;> rfl\n  change Runs (program s) (2*(outputTape answer words).reverse.length+3) .finish\n    (data original (vectorBits words) words.length [] (outputTape answer words).reverse) .done\n    (Function.update (Function.update\n      (data original (vectorBits words) words.length [] (outputTape answer words).reverse) (aux .reversed) [])\n      (aux .output) ((outputTape answer words).reverse.reverse++[])) at h\n  rw [List.length_reverse,List.reverse_reverse,List.append_nil,hd] at h\n  exact h\n/-- This SAME source's complete actual own clock, including all scope-byte\nscanning, per-leaf template copies/checks/drains, real returns and final output. -/\ndef timeBound (original : K→List Bool) (words : List (List Bool))\n    (answer : List Bool→Bool) (budget : Nat→Nat) : Nat :=\n  SemiprimeD1StackDigitCountExecution.totalTime words+\n    weight s original budget words.length*2^words.length+2*(outputTape answer words).length+7\n/-- Whole actual source from only the original checker-input template and a\nphysical scope-ID vector. No count, raw assignment, table or verdict is input. -/\ntheorem source_run (original : K→List Bool) (hraw : original s.raw=[])\n    (answer : List Bool→Bool) (budget : Nat→Nat) (hc : CheckerTrace s original answer budget)\n    (words : List (List Bool)) :\n    ∃t≤ timeBound s original words answer budget,C.run (program s) t\n      (initial s original (vectorBits words))=some (done s original words answer) := by\n  have h0:=count_call s original words\n  obtain ⟨t,ht,hvisit⟩:=visit_returns s original hraw answer budget hc (vectorBits words) words.length [] []\n  simp only [List.length_nil,Nat.zero_add,List.reverse_nil,List.append_nil] at ht hvisit\n  have h1:=SemiprimeD1StackProcedureReturns.call (program s) t .build .visit .finish _ _ rfl hvisit\n  have h2:=reverse_table s original words answer\n  have h:=runs_trans (program s) _ _ _ _ _ _ _ _ h0 (runs_trans (program s) _ _ _ _ _ _ _ _ h1 h2)\n  obtain ⟨finish,hr,hout⟩:=h [] (initial s original (vectorBits words)) ⟨rfl,rfl,rfl⟩\n  have hh:=halt_run (program s) .done rfl (result original words answer) [] finish hout\n  refine ⟨(SemiprimeD1StackDigitCountExecution.totalTime words+1)+\n    ((1+t)+(2*(outputTape answer words).length+3))+1,?_,?_⟩\n  · unfold timeBound;omega\n  · rw [SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,hh]\n    rfl\nend RiemannGaussian.SemiprimeD1StackStaticTableExecution\n","RiemannGaussian.SemiprimeD1StackVectorCanonical":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWordLessExecution\nimport RiemannGaussian.SemiprimeD1TensorTapeFieldBytecode\nimport RiemannGaussian.SemiprimeD1StackCopy\nimport RiemannGaussian.SemiprimeD1StackProcedureCallsTrace\n\n/-! # Actual canonical-word guard for a complete physical vector\nThe program copies the retained vector, parses actual framed words, copies the\nbinary modulus before each destructive comparison, and reads each real answer.\nA rejected suffix is physically drained. No canonicality verdict is supplied.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVectorCanonical\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace F\nexport SemiprimeD1TensorTapeFieldBytecode (Stack Label code active initial)\nend F\nnamespace W\nexport SemiprimeD1StackWordLess (Stack Label program store initial)\nend W\n\n/-- Ten fixed Boolean roles, with genuinely shared restored scratch. -/\ninductive Stack where\n  | cache | modulus | reader | word | scratch | valid | difference | copiedModulus | lessFlag | output\n  deriving DecidableEq,Repr\ninstance : Fintype Stack := Fintype.ofList\n  [.cache,.modulus,.reader,.word,.scratch,.valid,.difference,.copiedModulus,.lessFlag,.output]\n  (by intro k;cases k <;> simp)\n/-- Real preserving vector/modulus copy wiring. -/\ndef copyStack (modulus : Bool) (k : Fin 3) : Stack :=\n  if k=0 then (if modulus then .modulus else .cache) else\n  if k=1 then (if modulus then .copiedModulus else .reader) else .scratch\n/-- Actual framed field parser consumes the live vector reader. -/\ndef fieldStack : F.Stack→Stack\n  | .inl .input => .reader | .inl .scratch => .scratch | .inl .output => .word | .inr _ => .valid\n/-- Actual complete numeric comparison consumes a word and a fresh modulus copy. -/\ndef lessStack : W.Stack→Stack\n  | .inl .left => .word | .inl .right => .copiedModulus | .inl .scratch => .scratch\n  | .inl .output => .difference | .inr _ => .lessFlag\n/-- Fixed physical parser, guard and cleanup locations. -/\ninductive Label where\n  | start | loop | parse | parsed | copyModulus | compare | compared\n  | accept | reject | clearReader | done | bad\n  | copy (modulus : Bool) (pc : Fin 9) | field (pc : F.Label) | less (pc : W.Label)\n  deriving DecidableEq,Fintype\n/-- ONE closed program with actual canonicality-dependent control flow. -/\ndef program : Label→C.Instruction Stack Label\n  | .start => .call (.copy false 0) .loop\n  | .loop => .base (.pop .reader .bad .accept .parse)\n  | .parse => .call (.field (F.active .tagPop (none,false))) .parsed\n  | .parsed => .base (.pop .valid .bad .bad .copyModulus)\n  | .copyModulus => .call (.copy true 0) .compare\n  | .compare => .call (.less .start) .compared\n  | .compared => .base (.pop .lessFlag .bad .reject .loop)\n  | .accept => .base (.push .output true .done)\n  | .reject => .base (.push .output false .clearReader)\n  | .clearReader => .base (.pop .reader .done .clearReader .clearReader)\n  | .done | .bad => .base .halt\n  | .copy modulus pc => SemiprimeD1StackMultiplierLink.instruction (copyStack modulus) (Label.copy modulus)\n      (SemiprimeD1StackCopy.code pc)\n  | .field pc => SemiprimeD1StackMultiplierLink.instruction fieldStack Label.field (F.code pc)\n  | .less pc => SemiprimeD1StackValidationLink.instruction lessStack Label.less (W.program pc)\n/-- Reached clean payload view; actual scratch is empty between all real calls. -/\ndef store (cache cached reader word copied valid difference compared output : List Bool) : Stack→List Bool\n  | .cache => cache | .modulus => cached | .reader => reader | .word => word | .scratch => []\n  | .valid => valid | .difference => difference | .copiedModulus => copied | .lessFlag => compared | .output => output\n/-- Original physical vector and binary modulus are the only input tapes. -/\ndef initial (cache cached : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,store cache cached [] [] [] [] [] [] [],[]⟩\n/-- Actual copies never alias their source, destination or scratch. -/\ntheorem copyStack_injective (modulus : Bool) : Function.Injective (copyStack modulus) := by cases modulus <;> decide\n/-- Actual parser roles are physically distinct. -/\ntheorem fieldStack_injective : Function.Injective fieldStack := by\n  intro i j h\n  rcases i with i|i <;> rcases j with j|j <;> cases i <;> cases j <;> simp_all [fieldStack]\n/-- Actual comparison roles are physically distinct. -/\ntheorem lessStack_injective : Function.Injective lessStack := by\n  intro i j h\n  rcases i with i|i <;> rcases j with j|j <;> cases i <;> cases j <;> simp_all [lessStack]\n/-- Fixed actual finite-machine word-vector guard. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine Stack.cache Stack.output .start program\n/-- All physical data and real return-tag alphabets are finite before all inputs. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite Stack.cache Stack.output Label.start program\n/-- No decoded word, natural, list or canonicality answer occurs in control. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite Stack.cache Stack.output Label.start program\n/-- Every Boolean register is included in later storage bounds. -/\ntheorem stack_card : Fintype.card Stack=10 := by decide\n\nend RiemannGaussian.SemiprimeD1StackVectorCanonical\n","RiemannGaussian.SemiprimeD1StackVectorCanonicalComponents":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVectorCanonical\n\n/-! # Literal component traces of the complete vector guard\nThese inclusions preserve both retained caches and the unconsumed source. Every\nfield validity bit, copied modulus, numeric answer and cleanup is actual data.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVectorCanonicalComponents\nopen SemiprimeD1StackVectorCanonical SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\n\n/-- The full encoded vector is actually copied once, with its cache retained. -/\ntheorem copy_cache (cache cached : List Bool) :\n    Runs program (5*cache.length+4) .start (store cache cached [] [] [] [] [] [] [])\n      .loop (store cache cached cache [] [] [] [] [] []) := by\n  apply included_call program (copyStack false) (Label.copy false) (copyStack_injective false)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) .start .loop rfl (5*cache.length+3)\n    (SemiprimeD1StackCopy.state 0 none cache [] []) (SemiprimeD1StackCopy.done cache cache)\n    (store cache cached [] [] [] [] [] [] []) (store cache cached cache [] [] [] [] [] [])\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words cache [] none\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk 1 rfl)\n\n/-- Every destructive comparison receives a physically copied binary modulus. -/\ntheorem copy_modulus (cache cached reader word : List Bool) :\n    Runs program (5*cached.length+4) .copyModulus (store cache cached reader word [] [] [] [] [])\n      .compare (store cache cached reader word cached [] [] [] []) := by\n  apply included_call program (copyStack true) (Label.copy true) (copyStack_injective true)\n    SemiprimeD1StackCopy.code 0 (fun _=>rfl) .copyModulus .compare rfl (5*cached.length+3)\n    (SemiprimeD1StackCopy.state 0 none cached [] []) (SemiprimeD1StackCopy.done cached cached)\n    (store cache cached reader word [] [] [] [] []) (store cache cached reader word cached [] [] [] [])\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words cached [] none\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk 1 rfl)\n\n/-- A real field call acquires its exact word and actual validity Boolean. -/\ntheorem field_call (cache cached word tail : List Bool) :\n    Runs program (8*word.length+7) .parse (store cache cached (frame word tail) [] [] [] [] [] [])\n      .parsed (store cache cached tail word [] [true] [] [] []) := by\n  apply included_call program fieldStack Label.field fieldStack_injective F.code\n    (F.active .tagPop (none,false)) (fun _=>rfl) .parse .parsed rfl (8*word.length+6)\n    (F.initial (frame word tail) [])\n    (⟨none,none,Sum.elim (SemiprimeD1TensorTapeFieldMachine.contents tail [] word) (fun _=>[true])⟩:\n      SemiprimeD1StackBytecode.State F.Stack F.Label)\n    (store cache cached (frame word tail) [] [] [] [] [] []) (store cache cached tail word [] [true] [] [] [])\n  · rfl\n  · rfl\n  · exact SemiprimeD1TensorTapeFieldBytecode.framed_run word tail []\n  · constructor\n    · intro k;rcases k with k|k <;> cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rcases k with k|k <;> cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk (.inl .input) rfl) |\n        exact False.elim (hk (.inl .output) rfl) | exact False.elim (hk (.inr ()) rfl)\n\n/-- The physical parser verdict is consumed before any comparison begins. -/\ntheorem field_flag (cache cached reader word : List Bool) :\n    Runs program 1 .parsed (store cache cached reader word [] [true] [] [] [])\n      .copyModulus (store cache cached reader word [] [] [] [] []) := by\n  apply one_base program .parsed .copyModulus (.pop .valid .bad .bad .copyModulus) _ _ rfl\n  · rfl\n  · funext k;cases k <;> rfl\n\n/-- The COMPLETE actual numeric comparison consumes both operands and returns\nonly its computed Boolean, with no canonicality assumption. -/\ntheorem less_call (cache cached reader word : List Bool) :\n    Runs program (SemiprimeD1StackWordLessExecution.totalTime word cached+1) .compare\n      (store cache cached reader word cached [] [] [] []) .compared\n      (store cache cached reader [] [] [] [] [SemiprimeD1StackWordLessExecution.answer word cached] []) := by\n  apply SemiprimeD1StackProcedureCallsTrace.included_call program lessStack Label.less lessStack_injective\n    W.program .start (fun _=>rfl) .compare .compared rfl\n    (SemiprimeD1StackWordLessExecution.totalTime word cached) (W.initial word cached)\n    (SemiprimeD1StackWordLessExecution.done word cached)\n    (store cache cached reader word cached [] [] [] [])\n    (store cache cached reader [] [] [] [] [SemiprimeD1StackWordLessExecution.answer word cached] [])\n  · rfl\n  · rfl\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackWordLessExecution.source_run word cached\n  · constructor\n    · intro k;rcases k with k|k <;> cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;rcases k with k|k <;> cases k <;> rfl\n    · intro k hk\n      cases k <;> first | rfl | exact False.elim (hk (.inl .left) rfl) |\n        exact False.elim (hk (.inl .right) rfl) | exact False.elim (hk (.inr ()) rfl)\n\n/-- Control reads the actual comparison bit, never an external proof verdict. -/\ntheorem less_flag (cache cached reader : List Bool) (bit : Bool) :\n    Runs program 1 .compared (store cache cached reader [] [] [] [] [bit] [])\n      (if bit then .loop else .reject) (store cache cached reader [] [] [] [] [] []) := by\n  apply one_base program .compared (if bit then .loop else .reject)\n    (.pop .lessFlag .bad .reject .loop) _ _ rfl\n  · cases bit <;> rfl\n  · funext k;cases k <;> rfl\n\n/-- Every rejected source-suffix bit is physically popped before returning. -/\ntheorem clear_reader (cache cached reader : List Bool) (bit : Bool) :\n    Runs program (reader.length+1) .clearReader (store cache cached reader [] [] [] [] [] [bit])\n      .done (store cache cached [] [] [] [] [] [] [bit]) := by\n  have h:=SemiprimeD1StackPhysicalLoops.drain program .clearReader .done Stack.reader rfl\n    (store cache cached [] [] [] [] [] [] [bit]) reader\n  have hi : Function.update (store cache cached [] [] [] [] [] [] [bit]) .reader reader=\n      store cache cached reader [] [] [] [] [] [bit] := by\n    funext k;cases k <;> simp [Function.update,store]\n  have ho : Function.update (store cache cached [] [] [] [] [] [] [bit]) .reader []=\n      store cache cached [] [] [] [] [] [] [bit] := Function.update_eq_self _ _\n  rw [hi,ho] at h\n  exact h\n\nend RiemannGaussian.SemiprimeD1StackVectorCanonicalComponents\n","RiemannGaussian.SemiprimeD1StackVertexArityStatic":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexArityCopies\n\n/-! # Actual fixed-copy and literal original arity recipes -/\nset_option autoImplicit false\nset_option maxHeartbeats 1000000\nset_option maxRecDepth 16000\nset_option synthInstance.maxSize 8192\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackVertexArityStatic\nopen SemiprimeD1StackVertexArity SemiprimeD1StackVertexArityView SemiprimeD1StackVertexArityCopies\nopen SemiprimeD1StackProcedureFragments (Runs)\nopen SemiprimeD1StackUnaryDivmod (unary unary_add)\n\n/-- One actual R+1 copy, used by both endpoint constraints. -/\ntheorem radius_one (code index radius first second digits:ℕ) :\n    Runs program (5*radius+4) (.inl .oneRadius)\n      (store (header code index radius first second digits) [] [] [] [] [] []) (.inl .halt)\n      (store (header code index radius first second digits) (unary radius) [] [] [] [] []) := by\n  have h:=copy_radius code index radius first second digits [] [] [] [] [] [] (.inl .oneRadius) (.inl .halt) rfl\n  simpa only [List.append_nil] using h\n/-- Two actual readonly-source copies, for a scale constraint. -/\ntheorem radius_two (code index radius first second digits:ℕ) :\n    Runs program (10*radius+8) (.inl (.twoRadius 0))\n      (store (header code index radius first second digits) [] [] [] [] [] []) (.inl .halt)\n      (store (header code index radius first second digits) (unary (radius+radius)) [] [] [] [] []) := by\n  have h0:=copy_radius code index radius first second digits [] [] [] [] [] [] (.inl (.twoRadius 0)) (.inl (.twoRadius 1)) rfl\n  rw [List.append_nil] at h0\n  have h1:=copy_radius code index radius first second digits (unary radius) [] [] [] [] []\n    (.inl (.twoRadius 1)) (.inl .halt) rfl\n  rw [←unary_add] at h1\n  have h:=h0.trans h1\n  convert h using 1;omega\n/-- Three actual copies, for product and carry constraints. -/\ntheorem radius_three (code index radius first second digits:ℕ) :\n    Runs program (15*radius+12) (.inl (.threeRadius 0))\n      (store (header code index radius first second digits) [] [] [] [] [] []) (.inl .halt)\n      (store (header code index radius first second digits) (unary (radius+(radius+radius))) [] [] [] [] []) := by\n  have h0:=copy_radius code index radius first second digits [] [] [] [] [] [] (.inl (.threeRadius 0)) (.inl (.threeRadius 1)) rfl\n  rw [List.append_nil] at h0\n  have h1:=copy_radius code index radius first second digits (unary radius) [] [] [] [] []\n    (.inl (.threeRadius 1)) (.inl (.threeRadius 2)) rfl\n  rw [←unary_add] at h1\n  have h2:=copy_radius code index radius first second digits (unary (radius+radius)) [] [] [] [] []\n    (.inl (.threeRadius 2)) (.inl .halt) rfl\n  rw [←unary_add] at h2\n  have h:=h0.trans (h1.trans h2)\n  convert h using 1;omega\n/-- One physically pushed marker; no count/word answer is an input. -/\ntheorem literal_one (h:Source→List Bool) (arity:List Bool) :\n    Runs program 1 (.inl (.literal 0)) (store h arity [] [] [] [] []) (.inl .halt)\n      (store h (true::arity) [] [] [] [] []) :=\n  push_arity h arity [] [] [] [] [] (.inl (.literal 0)) (.inl .halt) rfl\n/-- Two literal marker pushes implement every equality-vertex scope. -/\ntheorem literal_two (h:Source→List Bool) (arity:List Bool) :\n    Runs program 2 (.inl (.literal 1)) (store h arity [] [] [] [] []) (.inl .halt)\n      (store h (true::true::arity) [] [] [] [] []) := by\n  have h0:=push_arity h arity [] [] [] [] [] (.inl (.literal 1)) (.inl (.literal 0)) rfl\n  exact h0.trans (literal_one h (true::arity))\n/-- Three literal marker pushes implement every Boolean OR scope. -/\ntheorem literal_three (h:Source→List Bool) (arity:List Bool) :\n    Runs program 3 (.inl (.literal 2)) (store h arity [] [] [] [] []) (.inl .halt)\n      (store h (true::true::true::arity) [] [] [] [] []) := by\n  have h0:=push_arity h arity [] [] [] [] [] (.inl (.literal 2)) (.inl (.literal 1)) rfl\n  exact h0.trans (literal_two h (true::arity))\nend RiemannGaussian.SemiprimeD1StackVertexArityStatic\n","RiemannGaussian.SemiprimeD1StackVertexProductPolynomial":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackVertexProductExecution\n/-! # Original-data polynomial bounds for the actual parsed vertex product -/\nset_option autoImplicit false\nset_option maxRecDepth 16384\nset_option maxHeartbeats 2000000\nnamespace RiemannGaussian.SemiprimeD1StackVertexProductPolynomial\nopen SemiprimeD1StackVertexProductState\nopen SemiprimeD1TensorTapeCodec (vectorBits tape)\nopen SemiprimeD1TensorTables (GoodWords)\n\n/-- Actual framed-vector inventory from the literal coefficient widths. -/\ntheorem vector_length (ws : List (List Bool)) (P : ℕ) (hw : ∀w∈ws,w.length≤P) :\n    (vectorBits ws).length≤2*ws.length*(P+1)+1 := by\n  induction ws with\n  | nil => simp [vectorBits]\n  | cons w ws ih =>\n    have hh:=hw w (by simp)\n    have ht:=ih (fun x hx=>hw x (by simp [hx]))\n    simp only [vectorBits,List.length_cons,SemiprimeSourceHistogramKeyBits.frame_length]\n    nlinarith\n\n/-- Fixed polynomial encoded size for any actual canonical current-context vector. -/\ndef vectorBound (S : ℕ) : ℕ := 2*S*(S+1)+1\n/-- Original shape/width discharge the encoded-vector cap. -/\ntheorem good_vector_length (ctx : SemiprimeD1JetAxes.Context) (ws : List (List Bool))\n    (hg : GoodWords ctx ws) (S : ℕ) (hr : ctx.rank≤S) (hp : ctx.precision≤S) :\n    (vectorBits ws).length≤vectorBound S := by\n  have hh:=vector_length ws ctx.precision (fun w hw=>(hg.2 w hw).2)\n  rw [hg.1] at hh\n  apply hh.trans\n  unfold vectorBound\n  gcongr\n\n/-- Pure polynomial covering every real parser/read/multiply/copy/drain round. -/\ndef roundPolynomial (S : ℕ) : ℕ :=\n  16*S+16+(5*(3*S+8)*(S+1)+8*(4*S+3)+3+1)+\n  (2000000*(10*S+2*vectorBound S+2)^6+1)+\n  (vectorBound S+1)+(vectorBound S+1)+6*vectorBound S+5\n\n/-- All arithmetic and storage caps of one executed round follow from original\nstored-table canonicality and original dimensions/inventory, not result advice. -/\ntheorem roundBudget_le (ctx : SemiprimeD1JetAxes.Context) (v : Values)\n    (vertex : SemiprimeD1LeafCounter.Vertex) (b : List (List Bool)) (S : ℕ)\n    (hv : SemiprimeD1TensorTables.Good ctx vertex.table) (hb : GoodWords ctx b)\n    (hr : ctx.rank≤S) (hp : ctx.precision≤S) (ha : ctx.axes.length≤S)\n    (haxes : (v .axes).length≤S) (hw : (v .width).length≤S) (hrank : (v .rank).length≤S)\n    (hbits : (v .assignment).length≤S)\n    (hports : (SemiprimeD1StackVertexReadExecution.portTape vertex.ports).length≤S)\n    (htable : (tape vertex.table).length≤S) :\n    SemiprimeD1StackVertexProductBody.roundBudget ctx v vertex b≤roundPolynomial S := by\n  let av:=(SemiprimeD1TensorTapeLeaf.evaluateVertex vertex (v .assignment)).words\n  have hav : GoodWords ctx av := by\n    rw [show av=(SemiprimeD1LeafCounter.evaluateVertex vertex (v .assignment)).words from\n      SemiprimeD1TensorTapeLeaf.evaluateVertex_words _ _]\n    exact SemiprimeD1LeafCounterBounds.evaluateVertex_good ctx vertex hv _\n  have hva:=good_vector_length ctx av hav S hr hp\n  have hvb:=good_vector_length ctx b hb S hr hp\n  have hvo:=good_vector_length ctx (SemiprimeD1JetRingBits.mul ctx av b).words\n    (SemiprimeD1LeafCounterBounds.mul_good ctx av b) S hr hp\n  let c : SemiprimeD1StackJetPointExecution.Cache :=\n    ⟨vectorBits av,vectorBits b,v .axes,v .width,v .rank,[]⟩\n  have hc : SemiprimeD1StackJetMulBounds.inputSize ctx c≤10*S+2*vectorBound S+1 := by\n    dsimp only [SemiprimeD1StackJetMulBounds.inputSize,SemiprimeD1StackJetPointBounds.inputSize,\n      SemiprimeD1StackJetMulExecution.indexed,c]\n    omega\n  have hm : 2000000*(SemiprimeD1StackJetMulBounds.inputSize ctx c+1)^6≤\n      2000000*(10*S+2*vectorBound S+2)^6 := by\n    exact Nat.mul_le_mul_left 2000000 (Nat.pow_le_pow_left (by omega) 6)\n  have hread : SemiprimeD1StackVertexReadExecution.budget (v .assignment).length\n      (SemiprimeD1StackVertexReadExecution.portTape vertex.ports).length (tape vertex.table).length≤\n      5*(3*S+8)*(S+1)+8*(4*S+3)+3 := by\n    unfold SemiprimeD1StackVertexReadExecution.budget SemiprimeD1StackGatherBytecode.budget\n      SemiprimeD1StackBitGatherBounds.budget SemiprimeD1StackTreeBytecode.budget\n    have hm:=Nat.mul_le_mul (by omega : 3*(v .assignment).length+8≤3*S+8) (Nat.add_le_add_right hports 1)\n    nlinarith [Nat.mul_le_mul_left 5 hm]\n  dsimp only [SemiprimeD1StackVertexProductBody.roundBudget,roundPolynomial]\n  change _ ≤ _ at hm\n  change (vectorBits av).length≤_ at hva\n  change _≤_ at hvo\n  dsimp only [c,av] at hm hva hvo\n  omega\n\n/-- All reached record rounds have the same original inventory cap; no recursive\ncost oracle is used and accumulator sizes are derived from actual multiplication. -/\ntheorem loopBudget_le (ctx : SemiprimeD1JetAxes.Context)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (v : Values) (b : List (List Bool)) (S : ℕ)\n    (hv : ∀x∈vertices,SemiprimeD1TensorTables.Good ctx x.table ∧\n      (SemiprimeD1StackVertexReadExecution.portTape x.ports).length≤S ∧ (tape x.table).length≤S)\n    (hb : GoodWords ctx b) (hr : ctx.rank≤S) (hp : ctx.precision≤S) (ha : ctx.axes.length≤S)\n    (haxes : (v .axes).length≤S) (hw : (v .width).length≤S) (hrank : (v .rank).length≤S)\n    (hbits : (v .assignment).length≤S) :\n    SemiprimeD1StackVertexProductLoop.loopBudget ctx vertices v b≤vertices.length*(1+roundPolynomial S)+1 := by\n  induction vertices generalizing v b with\n  | nil => simp [SemiprimeD1StackVertexProductLoop.loopBudget]\n  | cons x xs ih =>\n    have hx:=hv x (by simp)\n    let nb:=(SemiprimeD1JetRingBits.mul ctx (SemiprimeD1TensorTapeLeaf.evaluateVertex x (v .assignment)).words b).words\n    let next:=Function.update (Function.update v .reader (SemiprimeD1StackVertexProduct.records xs)) .product (vectorBits nb)\n    have hround:=roundBudget_le ctx v x b S hx.1 hb hr hp ha haxes hw hrank hbits hx.2.1 hx.2.2\n    have ht:=ih next nb (fun y hy=>hv y (by simp [hy]))\n      (SemiprimeD1LeafCounterBounds.mul_good ctx _ _) (by simpa [next] using haxes)\n      (by simpa [next] using hw) (by simpa [next] using hrank) (by simpa [next] using hbits)\n    change 1+SemiprimeD1StackVertexProductBody.roundBudget ctx v x b+\n      SemiprimeD1StackVertexProductLoop.loopBudget ctx xs next nb≤_\n    simp only [List.length_cons]\n    nlinarith\n\n/-- Fixed polynomial including literal unit construction, both physical copies\nand all original record rounds. -/\ndef preparedPolynomial (S : ℕ) : ℕ :=\n  (200*(S+1)*(S+8)+8)+1+(5*vectorBound S+4)+(vectorBound S+1)+(5*S+4)+\n    (S*(1+roundPolynomial S)+1)\n\n/-- Actual prepared product budget is fixed polynomial in the original context\nand literal record inventory. Stored-table canonicality is a data invariant. -/\ntheorem preparedBudget_le (ctx : SemiprimeD1JetAxes.Context)\n    (vertices : List SemiprimeD1LeafCounter.Vertex) (v : Values) (S : ℕ)\n    (hv : ∀x∈vertices,SemiprimeD1TensorTables.Good ctx x.table ∧\n      (SemiprimeD1StackVertexReadExecution.portTape x.ports).length≤S ∧ (tape x.table).length≤S)\n    (hcount : vertices.length≤S) (hrecords : (v .vertices).length≤S)\n    (hr : ctx.rank≤S) (hp : ctx.precision≤S) (ha : ctx.axes.length≤S)\n    (haxes : (v .axes).length≤S) (hw : (v .width).length≤S) (hrank : (v .rank).length≤S)\n    (hbits : (v .assignment).length≤S) :\n    SemiprimeD1StackVertexProductExecution.preparedBudget ctx vertices v≤preparedPolynomial S := by\n  let unit:=vectorBits (SemiprimeD1JetAffineCoefficient.one ctx).words\n  let ready:=Function.update (Function.update (Function.update (Function.update v .result unit)\n    .product unit) .result []) .reader (SemiprimeD1StackVertexProduct.records vertices)\n  have hu:=good_vector_length ctx (SemiprimeD1JetAffineCoefficient.one ctx).words\n    (SemiprimeD1LeafCounterBounds.one_good ctx) S hr hp\n  have ht:=loopBudget_le ctx vertices ready (SemiprimeD1JetAffineCoefficient.one ctx).words S hv\n    (SemiprimeD1LeafCounterBounds.one_good ctx) hr hp ha (by simpa [ready] using haxes)\n    (by simpa [ready] using hw) (by simpa [ready] using hrank) (by simpa [ready] using hbits)\n  have hc:=SemiprimeD1StackJetUnitExecution.totalTime_le (v .width) (v .rank)\n  have hc' : SemiprimeD1StackJetUnitExecution.totalTime (v .width) (v .rank)≤200*(S+1)*(S+8)+8 := by\n    apply hc.trans\n    unfold SemiprimeD1StackJetUnitExecution.timeBound\n    have hm:=Nat.mul_le_mul (Nat.add_le_add_right hrank 1) (Nat.add_le_add_right hw 8)\n    nlinarith [Nat.mul_le_mul_left 200 hm]\n  have htc:=Nat.mul_le_mul_right (1+roundPolynomial S) hcount\n  dsimp only [SemiprimeD1StackVertexProductExecution.preparedBudget,preparedPolynomial]\n  change _≤_ at ht\n  dsimp only [ready,unit] at ht\n  omega\n\nend RiemannGaussian.SemiprimeD1StackVertexProductPolynomial\n","RiemannGaussian.SemiprimeD1StackWeightedModeActivation":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeView\n/-! # Actual five-word recursive activation save and restore\nEvery frame, parse, validity pop and recursive-entry cleanup executes the same\nfixed controller. No activation record or continuation is a runtime structure.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeActivation\nopen SemiprimeD1StackWeightedMode SemiprimeD1StackWeightedModePrimitives SemiprimeD1StackWeightedModeView\nopen SemiprimeD1StackProcedureTrace\nopen SemiprimeSourceHistogramKeyBits (frame)\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Actual traces concatenate without introducing any controller opcode. -/\ntheorem join {m n:Nat} {pc mid next:Label} {before between after:Stack→List Bool}\n    (h:Runs program m pc before mid between) (g:Runs program n mid between next after) :\n    Runs program (m+n) pc before next after:=runs_trans program m n pc mid next before between after h g\n/-- Exact current five-field byte mass; it excludes untouched older frames. -/\ndef mass (v:Words) :Nat:=v.weight.length+v.weights.length+v.budget.length+v.exponent.length+v.path.length\n/-- Actual five-frame prefix followed by the untouched older activation records. -/\ndef savedFrame (v:Words) :List Bool:=frame v.weight\n  (frame v.weights (frame v.budget (frame v.exponent (frame v.path v.frames))))\n/-- Each real preserving-frame call has the exact word-view update. -/\ntheorem frame_view (site:Frame) (pc:Control) (next:Label)\n    (hc:program (ctl pc)=.call (frameLabel site 0) next) (v:Words) (hs:v.frameScratch=[]) :\n    Runs program (6*(store v (frameSource site)).length+5) (ctl pc) (store v) next\n      (store (write v (frameTarget site) (frame (store v (frameSource site)) (store v (frameTarget site))))) :=by\n  simpa only [store_write] using frame_call site pc next hc (store v) _ _ rfl rfl hs\n/-- Five actual preserving calls save the complete activation in the required parse order. -/\ntheorem save_run (v:Words) (hs:v.frameScratch=[]) :\n    Runs program (6*mass v+25) (ctl (.save 4)) (store v) (ctl .pathFrame)\n      (store {v with frames:=savedFrame v}):=by\n  let v1:Words:={v with frames:=frame v.path v.frames}\n  let v2:Words:={v1 with frames:=frame v.exponent v1.frames}\n  let v3:Words:={v2 with frames:=frame v.budget v2.frames}\n  let v4:Words:={v3 with frames:=frame v.weights v3.frames}\n  have h4:=frame_view (.save 4) (.save 4) (ctl (.save 3)) rfl v hs\n  change Runs program (6*v.path.length+5) _ _ _ (store v1) at h4\n  have h3:=frame_view (.save 3) (.save 3) (ctl (.save 2)) rfl v1 hs\n  change Runs program (6*v.exponent.length+5) _ _ _ (store v2) at h3\n  have h2:=frame_view (.save 2) (.save 2) (ctl (.save 1)) rfl v2 hs\n  change Runs program (6*v.budget.length+5) _ _ _ (store v3) at h2\n  have h1:=frame_view (.save 1) (.save 1) (ctl (.save 0)) rfl v3 hs\n  change Runs program (6*v.weights.length+5) _ _ _ (store v4) at h1\n  have h0:=frame_view (.save 0) (.save 0) (ctl .pathFrame) rfl v4 hs\n  change Runs program (6*v.weight.length+5) _ _ _ (store {v with frames:=savedFrame v}) at h0\n  have hh:=join h4 (join h3 (join h2 (join h1 h0)))\n  have he:(6*v.path.length+5)+((6*v.exponent.length+5)+((6*v.budget.length+5)+\n    ((6*v.weights.length+5)+(6*v.weight.length+5))))=6*mass v+25:=by unfold mass;omega\n  rw [he] at hh\n  exact hh\n/-- Exact unparsed physical suffix after zero through five fields. -/\ndef suffix (fields:Fin 5→List Bool) (n:Nat) (tail:List Bool) :List Bool:=\n  if n=0 then frame (fields 0) (frame (fields 1) (frame (fields 2) (frame (fields 3) (frame (fields 4) tail))))\n  else if n=1 then frame (fields 1) (frame (fields 2) (frame (fields 3) (frame (fields 4) tail)))\n  else if n=2 then frame (fields 2) (frame (fields 3) (frame (fields 4) tail))\n  else if n=3 then frame (fields 3) (frame (fields 4) tail)\n  else if n=4 then frame (fields 4) tail else tail\n/-- Exactly the fields already restored by physical parser calls. -/\ndef restored (v:Words) (fields:Fin 5→List Bool) (n:Nat) (tail:List Bool) :Words:=\n  {v with\n    frames := suffix fields n tail\n    weight := if 0 < n then fields 0 else []\n    weights := if 1 < n then fields 1 else []\n    budget := if 2 < n then fields 2 else []\n    exponent := if 3 < n then fields 3 else []\n    path := if 4 < n then fields 4 else []\n    valid := []}\n/-- The current unread word is the next physically framed field. -/\ntheorem restored_input (v:Words) (fields:Fin 5→List Bool) (i:Fin 5) (tail:List Bool) :\n    store (restored v fields i.val tail) (parseInput (.restore i))=\n      frame (fields i) (suffix fields (i.val+1) tail):=by fin_cases i <;> rfl\n/-- Every restore parser writes into an ACTUALLY empty output word. -/\ntheorem restored_output (v:Words) (fields:Fin 5→List Bool) (i:Fin 5) (tail:List Bool) :\n    store (restored v fields i.val tail) (parseOutput (.restore i))=[]:=by fin_cases i <;> rfl\n/-- Actual field/validity writes advance the partial physical activation by exactly one field. -/\ntheorem restored_step (v:Words) (fields:Fin 5→List Bool) (i:Fin 5) (tail:List Bool) :\n    Function.update (Function.update (Function.update\n      (store (restored v fields i.val tail)) .frames (suffix fields (i.val+1) tail))\n      (saved i) (fields i)) .valid []=store (restored v fields (i.val+1) tail):=by\n  rw [store_write,store_write,store_write]\n  fin_cases i <;> rfl\n/-- One actual field parse and true-marker pop restore one activation field. -/\ntheorem restore_one (v:Words) (fields:Fin 5→List Bool) (i:Fin 5) (tail:List Bool)\n    (hs:v.fieldScratch=[]) :\n    Runs program (8*(fields i).length+8) (ctl (.restore i)) (store (restored v fields i.val tail))\n      (restoreNext i) (store (restored v fields (i.val+1) tail)):=by\n  have h0:=field_call (.restore i) (.restore i) (.restoreValid i) rfl\n    (store (restored v fields i.val tail)) (fields i) (suffix fields (i.val+1) tail)\n    (restored_input v fields i tail) (restored_output v fields i tail) hs rfl\n  let s:=Function.update (Function.update (Function.update\n      (store (restored v fields i.val tail)) .frames (suffix fields (i.val+1) tail))\n      (saved i) (fields i)) .valid [true]\n  change Runs program (8*(fields i).length+7) _ _ _ s at h0\n  have h1:=pop_run (.restoreValid i) (ctl .abort) (ctl .abort) (restoreNext i) .valid s [true] rfl\n    (Function.update_self _ _ _)\n  have hh:=join h0 h1\n  change Runs program ((8*(fields i).length+7)+1) _ _ _ (Function.update s .valid []) at hh\n  dsimp only [s] at hh\n  rw [Function.update_idem,restored_step] at hh\n  simpa only [Nat.add_assoc,List.head?_cons,SemiprimeD1StackBytecode.choose] using hh\n/-- Five actual parsers and five true validity pops consume exactly one saved activation. -/\ntheorem restore_run (v:Words) (fields:Fin 5→List Bool) (tail:List Bool) (hs:v.fieldScratch=[]) :\n    Runs program (8*((fields 0).length+(fields 1).length+(fields 2).length+(fields 3).length+(fields 4).length)+40)\n      (ctl (.restore 0)) (store (restored v fields 0 tail)) (ctl .copyWeight)\n      (store (restored v fields 5 tail)):=by\n  have h0:=restore_one v fields 0 tail hs\n  have h1:=restore_one v fields 1 tail hs\n  have h2:=restore_one v fields 2 tail hs\n  have h3:=restore_one v fields 3 tail hs\n  have h4:=restore_one v fields 4 tail hs\n  have hh:=join h0 (join h1 (join h2 (join h3 h4)))\n  have he:(8*(fields 0).length+8)+((8*(fields 1).length+8)+((8*(fields 2).length+8)+\n      ((8*(fields 3).length+8)+(8*(fields 4).length+8))))=\n      8*((fields 0).length+(fields 1).length+(fields 2).length+(fields 3).length+(fields 4).length)+40:=by omega\n  change Runs program _ (ctl (.restore 0)) (store (restored v fields 0 tail)) (ctl .copyWeight)\n    (store (restored v fields 5 tail)) at hh\n  rw [he] at hh\n  exact hh\n/-- Actual saved-loop words match their original five numerical/tape fields. -/\ntheorem loop_saved (cat width:List Bool) (w:Nat) (ws:List Nat) (R e:Nat) (path frames hist out:List Bool) :\n    savedFrame (loop cat width w ws R e path frames hist out)=activation w ws R e path frames:=rfl\n/-- Physical save, path frame/tag and two real drains prepare the exact next recursive child. -/\ntheorem descend (cat width:List Bool) (w:Nat) (ws:List Nat) (R e:Nat) (path frames hist out:List Bool) :\n    ∃t ≤ 20*(mass (loop cat width w ws R e path frames hist out)+1)+50,\n      Runs program t (ctl (.save 4)) (store (loop cat width w ws R e path frames hist out))\n        (ctl .child) (store (node cat width ws R (extend e path) (activation w ws R e path frames) hist out)):=by\n  let v:=loop cat width w ws R e path frames hist out\n  let fs:=activation w ws R e path frames\n  let v1:Words:={v with frames:=fs}\n  let v2:Words:={v1 with path:=frame (unary e) path}\n  let v3:Words:={v2 with path:=extend e path}\n  let v4:Words:={v3 with weight:=[]}\n  have h0:=save_run v rfl\n  change Runs program (6*mass v+25) _ _ _ (store v1) at h0\n  have h1:=frame_view .path .pathFrame (ctl .pathTag) rfl v1 rfl\n  change Runs program (6*(unary e).length+5) _ _ _ (store v2) at h1\n  have h2:=push_run .pathTag (ctl .clearWeight) .path true (store v2) rfl\n  rw [store_write] at h2\n  change Runs program 1 _ _ _ (store v3) at h2\n  have h3:=drain_loop .clearWeight (ctl .clearExponent) .weight rfl (store v3) (unary w) rfl\n  rw [store_write] at h3\n  change Runs program ((unary w).length+1) _ _ _ (store v4) at h3\n  have h4:=drain_loop .clearExponent (ctl .child) .exponent rfl (store v4) (unary e) rfl\n  rw [store_write] at h4\n  change Runs program ((unary e).length+1) _ _ _\n    (store (node cat width ws R (extend e path) fs hist out)) at h4\n  refine ⟨(6*mass v+25)+((6*(unary e).length+5)+(1+(((unary w).length+1)+((unary e).length+1)))),?_,\n    join h0 (join h1 (join h2 (join h3 h4)))⟩\n  dsimp only [mass,v,loop,node,base]\n  omega\nend RiemannGaussian.SemiprimeD1StackWeightedModeActivation\n","RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueFinish":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueOrders\n/-! # Physical catalogue reversal and exact native mode-coordinate binding -/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueFinish\nopen SemiprimeD1StackWeightedModeCatalogue SemiprimeD1StackWeightedModeCatalogueView\nopen SemiprimeD1StackWeightedModeCataloguePrimitives SemiprimeD1StackWeightedModeCatalogueOrders\nopen SemiprimeD1StackWeightedModeView (unary history vector)\nopen SemiprimeD1TensorTapeCodec (vectorBits)\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl :Control→Label)\n/-- Exact actual catalogue weights, in order-major/slot-major sequence. -/\ntheorem weights_original (slots P:Nat):\n    orderWeights slots 0 P=(SemiprimeD1ModeCatalog.weights slots P).map unary:=by\n  rw [SemiprimeD1ModeCatalog.weights_eq]\n  simp only [orderWeights,slotWeights,List.map_flatMap,List.map_replicate,Nat.zero_add]\n/-- Exact actual finite labels, including the physical unary slot and order fields. -/\ntheorem labels_original (slots P:Nat):\n    orderLabels slots 0 P=(SemiprimeD1ModeCatalog.catalog slots P).map (fun m=>modeWord m.slot m.order):=by\n  simp only [orderLabels,slotLabels,SemiprimeD1ModeCatalog.catalog,List.map_flatMap,List.map_map,\n    Function.comp_def,Nat.zero_add]\n/-- The physical reverse source and target are always separate. -/\ntheorem reverse_ne (site:Bool):reverseStack site 0≠reverseStack site 1:=by cases site <;> decide\n/-- Each actual output reversal includes the real call and return. -/\ntheorem reverse_call (site:Bool) (pc next:Control)\n    (hc:program (ctl pc)=.call (reverseLabel site 0) (ctl next))\n    (s:Stack→List Bool) (hist out:List Bool)\n    (hh:s (reverseStack site 0)=hist) (ho:s (reverseStack site 1)=out):\n    Runs program (2*hist.length+3) (ctl pc) s (ctl next)\n      (Function.update (Function.update s (reverseStack site 0) []) (reverseStack site 1) (hist.reverse++out)):=by\n  apply included_call program (reverseStack site) (reverseLabel site) (reverse_injective site)\n    SemiprimeD1StackReverseWord.code 0 (fun _=>rfl) (ctl pc) (ctl next) hc (2*hist.length+2)\n    (SemiprimeD1StackReverseWord.state none hist out) (SemiprimeD1StackReverseWord.done (hist.reverse++out)) s _\n  · rfl\n  · rfl\n  · exact SemiprimeD1StackReverseWord.reverse_run hist out none\n  · constructor\n    · intro k;fin_cases k\n      · exact hh\n      · exact ho\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k\n      · change Function.update (Function.update s (reverseStack site 0) []) (reverseStack site 1)\n          (hist.reverse++out) (reverseStack site 0)=[]\n        rw [Function.update_of_ne (reverse_ne site),Function.update_self]\n      · exact Function.update_self _ _ _\n    · intro k hk\n      rw [Function.update_of_ne (hk 1).symm,Function.update_of_ne (hk 0).symm]\n/-- Proof-side name for the actual generated weight catalogue. -/\ndef weights (p t width:Nat):List Nat:=SemiprimeD1ModeCatalog.weights (p*t) (width-1)\n/-- Proof-side name for the actual generated full mode-label bytes. -/\ndef labels (p t width:Nat):List Bool:=\n  vectorBits ((SemiprimeD1ModeCatalog.catalog (p*t) (width-1)).map (fun m=>modeWord m.slot m.order))\n/-- The physically reached prepared DFS input, retaining all computed metadata. -/\ndef ready (p t width:Nat):Words:=\n  {scanning p t width 0 (width-1) 0 0 [] [] with\n    enumData:=W.input (vector (weights p t width)) (unary width),labels:=labels p t width}\n/-- Both actual logs are reversed to their exact literal native catalogue bytes. -/\ntheorem finish_run (p t width:Nat):\n    Runs program\n      (2*(history (orderWeights (p*t) 0 (width-1)) []).length+\n        2*(history (orderLabels (p*t) 0 (width-1)) []).length+8)\n      (ctl .catalogueSeed)\n      (store (scanning p t width 0 (width-1) 0 0\n        (history (orderWeights (p*t) 0 (width-1)) []) (history (orderLabels (p*t) 0 (width-1)) [])))\n      (ctl .enumerate) (store (ready p t width)):=by\n  let wh:=history (orderWeights (p*t) 0 (width-1)) []\n  let lh:=history (orderLabels (p*t) 0 (width-1)) []\n  let a:=scanning p t width 0 (width-1) 0 0 wh lh\n  let b:=write a (weighted .catalogue) [false]\n  let c:=write (write b (aux .weightHistory) []) (weighted .catalogue) (vectorBits (orderWeights (p*t) 0 (width-1)))\n  let d:Words:={c with labels:=[false]}\n  have h0:=push_run .catalogueSeed .reverseWeights (weighted .catalogue) false (store a) rfl\n  rw [store_write] at h0\n  change Runs program 1 _ _ _ (store b) at h0\n  have h1:=reverse_call true .reverseWeights .labelsSeed rfl (store b) wh [false] rfl rfl\n  rw [store_write,store_write,SemiprimeD1StackWeightedModeExecution.history_vector] at h1\n  change Runs program (2*wh.length+3) _ _ _ (store c) at h1\n  have h2:=push_run .labelsSeed .reverseLabels (aux .labels) false (store c) rfl\n  rw [store_write] at h2\n  change Runs program 1 _ _ _ (store d) at h2\n  have h3:=reverse_call false .reverseLabels .enumerate rfl (store d) lh [false] rfl rfl\n  rw [store_write,store_write,SemiprimeD1StackWeightedModeExecution.history_vector,\n    labels_original] at h3\n  have hdata:write (write d (reverseStack false 0) []) (reverseStack false 1)\n      (vectorBits ((SemiprimeD1ModeCatalog.catalog (p*t) (width-1)).map (fun m=>modeWord m.slot m.order)))=\n      ready p t width:=by\n    change {ready p t width with enumData:=c.enumData}=ready p t width\n    have he:c.enumData=(ready p t width).enumData:=by\n      funext k\n      cases k <;> first\n        | rfl\n        | (change vectorBits (orderWeights (p*t) 0 (width-1))=vector (weights p t width)\n           rw [weights_original]\n           rfl)\n    rw [he]\n  rw [hdata] at h3\n  have h:=join h0 (join h1 (join h2 h3))\n  dsimp only [wh,lh] at h\n  convert h using 1;omega\nend RiemannGaussian.SemiprimeD1StackWeightedModeCatalogueFinish\n","RiemannGaussian.SemiprimeD1StackWeightedModeSubtract":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWeightedModeActivation\n/-! # Literal feasible-branch subtraction and the sole failed end test\nOnly actual unary marker pops decide whether another child is visited. The\nsource has neither a natural division instruction nor an exponent catalogue.\n-/\nset_option autoImplicit false\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWeightedModeSubtract\nopen SemiprimeD1StackWeightedMode SemiprimeD1StackWeightedModePrimitives SemiprimeD1StackWeightedModeView\nopen SemiprimeD1StackWeightedModeActivation (join)\nopen SemiprimeD1StackProcedureTrace\nlocal notation \"ctl\" => (Sum.inl : Control→Label)\n/-- Splitting unary metadata means splitting actual marker cells, not an instruction. -/\ntheorem unary_add (a b:Nat) :unary (a+b)=unary a++unary b:=List.replicate_add a b true\n/-- One successful subtraction pair pops one actual todo and one actual budget marker. -/\ntheorem pair (v:Words) (todo budget:List Bool) (ht:v.subTodo=true::todo) (hb:v.budget=true::budget) :\n    Runs program 2 (ctl .subtract) (store v) (ctl .subtract)\n      (store {v with subTodo:=todo,budget:=budget}):=by\n  let v1:Words:={v with subTodo:=todo}\n  have h0:=pop_run .subtract (ctl .increment) (ctl .budgetPop) (ctl .budgetPop) .subTodo (store v)\n    (true::todo) rfl ht\n  rw [store_write] at h0\n  change Runs program 1 _ _ (ctl .budgetPop) (store v1) at h0\n  have h1:=pop_run .budgetPop (ctl .failure) (ctl .subtract) (ctl .subtract) .budget (store v1)\n    (true::budget) rfl hb\n  rw [store_write] at h1\n  change Runs program 1 _ _ (ctl .subtract) (store {v with subTodo:=todo,budget:=budget}) at h1\n  exact join h0 h1\n/-- Every matched prefix is consumed by exactly two physical pops per marker. -/\ntheorem pairs (n:Nat) (v:Words) (todo budget:List Bool)\n    (ht:v.subTodo=unary n++todo) (hb:v.budget=unary n++budget) :\n    Runs program (2*n) (ctl .subtract) (store v) (ctl .subtract)\n      (store {v with subTodo:=todo,budget:=budget}):=by\n  induction n generalizing v with\n  | zero=>\n    simp only [unary,List.replicate_zero,List.nil_append] at ht hb\n    have he:store {v with subTodo:=todo,budget:=budget}=store v:=by\n      rw [←ht,←hb]\n    rw [he]\n    exact runs_refl program _ _\n  | succ n ih=>\n    rw [unary_succ,List.cons_append] at ht hb\n    let v1:Words:={v with subTodo:=unary n++todo,budget:=unary n++budget}\n    have h0:=pair v (unary n++todo) (unary n++budget) ht hb\n    have h1:=ih v1 rfl rfl\n    have hh:=join h0 h1\n    change Runs program (2+2*n) _ _ _ (store {v with subTodo:=todo,budget:=budget}) at hh\n    convert hh using 1;omega\n/-- A complete feasible subtraction pays its final todo EOF and exponent-marker push. -/\ntheorem success (v:Words) (w R e:Nat) (ht:v.subTodo=unary w) (hb:v.budget=unary (w+R))\n    (he:v.exponent=unary e) :\n    Runs program (2*w+2) (ctl .subtract) (store v) (ctl (.save 4))\n      (store {v with subTodo:=[],budget:=unary R,exponent:=unary (e+1)}):=by\n  let v1:Words:={v with subTodo:=[],budget:=unary R}\n  have h0:=pairs w v [] (unary R) (by simpa only [List.append_nil] using ht) (by rw [←unary_add];exact hb)\n  change Runs program (2*w) _ _ _ (store v1) at h0\n  have h1:=pop_run .subtract (ctl .increment) (ctl .budgetPop) (ctl .budgetPop) .subTodo (store v1) [] rfl rfl\n  rw [store_write] at h1\n  change Runs program 1 _ _ (ctl .increment) (store v1) at h1\n  have h2:=push_run .increment (ctl (.save 4)) .exponent true (store v1) rfl\n  rw [store_write] at h2\n  change Runs program 1 _ _ _ (store {v with subTodo:=[],budget:=unary R,exponent:=true::v.exponent}) at h2\n  rw [he,←unary_succ] at h2\n  have hh:=join h0 (join h1 h2)\n  simpa only [Nat.add_assoc] using hh\n/-- The first failed subtraction reaches cleanup and never calls a spurious child. -/\ntheorem failure (v:Words) (R d:Nat) (ht:v.subTodo=unary (R+d+1)) (hb:v.budget=unary R) :\n    Runs program (2*R+d+3) (ctl .subtract) (store v) (ctl (.cleanup 0))\n      (store {v with subTodo:=[],budget:=[]}):=by\n  let v1:Words:={v with subTodo:=unary (d+1),budget:=[]}\n  let v2:Words:={v1 with subTodo:=unary d}\n  have h0:=pairs R v (unary (d+1)) [] (by\n    rw [←unary_add]\n    simpa only [Nat.add_assoc] using ht) (by simpa only [List.append_nil] using hb)\n  change Runs program (2*R) _ _ _ (store v1) at h0\n  have h1:=pop_run .subtract (ctl .increment) (ctl .budgetPop) (ctl .budgetPop) .subTodo (store v1)\n    (true::unary d) rfl (unary_succ d)\n  rw [store_write] at h1\n  change Runs program 1 _ _ (ctl .budgetPop) (store v2) at h1\n  have h2:=pop_run .budgetPop (ctl .failure) (ctl .subtract) (ctl .subtract) .budget (store v2) [] rfl rfl\n  rw [store_write] at h2\n  change Runs program 1 _ _ (ctl .failure) (store v2) at h2\n  have h3:=drain_loop .failure (ctl (.cleanup 0)) .subTodo rfl (store v2) (unary d) rfl\n  rw [store_write] at h3\n  change Runs program ((unary d).length+1) _ _ _ (store {v with subTodo:=[],budget:=[]}) at h3\n  rw [unary_length] at h3\n  have hh:=join h0 (join h1 (join h2 h3))\n  convert hh using 1;omega\nend RiemannGaussian.SemiprimeD1StackWeightedModeSubtract\n","RiemannGaussian.SemiprimeD1StackWordBlockExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackWordBlock\n\n/-! # Exact physically padded public-word trace\nExactly one physical template width is read or padded. Every remaining source\nassignment bit is retained, with no decoded width or block-answer operand.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 900000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWordBlockExecution\nopen SemiprimeD1StackWordBlock SemiprimeD1StackProcedureTrace\n\n/-- The original public checker fitting bytes. -/\ndef result (word cached : List Bool) : List Bool := (SemiprimeBitDivision.fitBits word cached).bits\n/-- Exact physical output width, for ALL words and templates. -/\ntheorem result_length (word cached : List Bool) : (result word cached).length=cached.length :=\n  (SemiprimeBitDivision.fitBits_counts word cached).1\n/-- Fitting reads one actual word bit or pads false at EOF. -/\ntheorem fit_cons (word count : List Bool) (c : Bool) :\n    result word (c::count)=((word.head?).getD false)::result word.tail count := by\n  cases word <;> rfl\n\n/-- A real preserving copy acquires the disposable physical width word. -/\ntheorem copy_call (word cached : List Bool) :\n    Runs program (5*cached.length+4) .start (store word cached [] [] [])\n      .take (store word cached cached [] []) := by\n  apply included_call program copyStack RiemannGaussian.SemiprimeD1StackWordFit.Label.copy copyStack_injective SemiprimeD1StackCopy.code 0\n    (fun _=>rfl) .start .take rfl (5*cached.length+3)\n    (SemiprimeD1StackCopy.state 0 none cached [] []) (SemiprimeD1StackCopy.done cached cached)\n    (store word cached [] [] []) (store word cached cached [] [])\n  · rfl\n  · rfl\n  · simpa only [List.append_nil] using SemiprimeD1StackCopy.copy_words cached [] none\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k _;rfl\n  · constructor\n    · intro k;fin_cases k <;> rfl\n    · intro k hk\n      fin_cases k <;> first | rfl | exact False.elim (hk 1 rfl)\n\n/-- Exactly three real steps consume one template cell and copy/pad one input bit. -/\ntheorem read_cell (c : Bool) (word cached count acc out : List Bool) :\n    Runs program 3 .take (store word cached (c::count) acc out)\n      .take (store word.tail cached count (((word.head?).getD false)::acc) out) := by\n  have h0 : Runs program 1 .take (store word cached (c::count) acc out)\n      .read (store word cached count acc out) := by\n    apply one_base program .take .read (.pop counter .restore .read .read) _ _ rfl\n    · cases c <;> rfl\n    · funext k;fin_cases k <;> rfl\n  have h1 : Runs program 1 .read (store word cached count acc out)\n      (.save ((word.head?).getD false)) (store word.tail cached count acc out) := by\n    apply one_base program .read (.save ((word.head?).getD false))\n      (.pop operand (.save false) (.save false) (.save true)) _ _ rfl\n    · cases word with\n      | nil => rfl\n      | cons b bs => cases b <;> rfl\n    · funext k;fin_cases k <;> rfl\n  have h2 : Runs program 1 (.save ((word.head?).getD false)) (store word.tail cached count acc out)\n      .take (store word.tail cached count (((word.head?).getD false)::acc) out) := by\n    apply one_base program (.save ((word.head?).getD false)) .take\n      (.push scratch ((word.head?).getD false) .take) _ _ rfl\n    · rfl\n    · funext k;fin_cases k <;> rfl\n  exact runs_trans program 2 1 _ _ _ _ _ _ (runs_trans program 1 1 _ _ _ _ _ _ h0 h1) h2\n\n/-- Exact fitting prefix, preserving ALL template-width padding and exposing\nthe actual unconsumed high input for the subsequent physical drain. -/\ntheorem prefix_run (count word cached acc out : List Bool) :\n    Runs program (3*count.length+1) .take (store word cached count acc out)\n      .restore (store (word.drop count.length) cached [] ((result word count).reverse++acc) out) := by\n  induction count generalizing word acc with\n  | nil =>\n    apply one_base program .take .restore (.pop counter .restore .read .read) _ _ rfl\n    · rfl\n    · funext k;fin_cases k <;> rfl\n  | cons c count ih =>\n    have h0:=read_cell c word cached count acc out\n    have h1:=ih word.tail (((word.head?).getD false)::acc)\n    have hd : word.tail.drop count.length=word.drop (c::count).length := by\n      cases word <;> simp only [List.tail_nil,List.drop_nil,List.length_cons,List.tail_cons,List.drop_succ_cons]\n    rw [hd] at h1\n    have hh:=runs_trans program _ _ _ _ _ _ _ _ h0 h1\n    simpa only [List.length_cons,fit_cons,List.reverse_cons,List.append_assoc,List.singleton_append,\n      show 3+(3*count.length+1)=3*(count.length+1)+1 by omega] using hh\n\n/-- The fitted low cells are physically reversed into their exact original order. -/\ntheorem restore_run (acc word cached out : List Bool) :\n    Runs program (2*acc.length+1) .restore (store word cached [] acc out)\n      .done (store word cached [] [] (acc.reverse++out)) := by\n  induction acc generalizing out with\n  | nil =>\n    apply one_base program .restore .done (.pop scratch .done (.write false) (.write true)) _ _ rfl\n    · rfl\n    · funext k;fin_cases k <;> rfl\n  | cons b acc ih =>\n    have h0 : Runs program 1 .restore (store word cached [] (b::acc) out)\n        (.write b) (store word cached [] acc out) := by\n      apply one_base program .restore (.write b) (.pop scratch .done (.write false) (.write true)) _ _ rfl\n      · cases b <;> rfl\n      · funext k;fin_cases k <;> rfl\n    have h1 : Runs program 1 (.write b) (store word cached [] acc out)\n        .restore (store word cached [] acc (b::out)) := by\n      apply one_base program (.write b) .restore (.push output b .restore) _ _ rfl\n      · rfl\n      · funext k;fin_cases k <;> rfl\n    have hh:=runs_trans program _ _ _ _ _ _ _ _\n      (runs_trans program _ _ _ _ _ _ _ _ h0 h1) (ih (b::out))\n    simpa only [List.length_cons,List.reverse_cons,List.append_assoc,List.singleton_append,\n      show (1+1)+(2*acc.length+1)=2*(acc.length+1)+1 by omega] using hh\n\n/-- Exact own clock; no unread suffix cell is consumed or scanned. -/\ndef totalTime (cached : List Bool) : ℕ :=\n  (5*cached.length+4)+(3*cached.length+1)+(2*cached.length+1)+1\n/-- Exact clean output retains the original source suffix and width cache. -/\ndef done (word cached : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,store (word.drop cached.length) cached [] [] (result word cached),[]⟩\n\n/-- Complete physical block extraction; arbitrary raw words and templates are\nallowed, with zero padding at EOF and the exact remaining source retained. -/\ntheorem source_run (word cached : List Bool) :\n    C.run program (totalTime cached) (initial word cached)=some (done word cached) := by\n  have h0:=copy_call word cached\n  have h1:=prefix_run cached word cached [] []\n  simp only [List.append_nil] at h1\n  have h2:=restore_run (result word cached).reverse (word.drop cached.length) cached []\n  simp only [List.length_reverse,result_length,List.reverse_reverse,List.append_nil] at h2\n  have h:=runs_trans program _ _ _ _ _ _ _ _ (runs_trans program _ _ _ _ _ _ _ _ h0 h1) h2\n  obtain ⟨finish,hr,ho⟩:=h [] (initial word cached) ⟨rfl,rfl,rfl⟩\n  have he:=halt_run program .done rfl\n    (store (word.drop cached.length) cached [] [] (result word cached)) [] finish ho\n  rw [totalTime,SemiprimeD1StackReturnLink.run_add,hr,Option.bind_some,he]\n  rfl\n\n/-- A complete original assignment supplies the exact fixed-width block bytes,\nincluding all high zero padding, with no normalization or reconstruction. -/\ntheorem result_take (word cached : List Bool) (hlen : cached.length ≤ word.length) :\n    result word cached=word.take cached.length := by\n  induction cached generalizing word with\n  | nil => rfl\n  | cons c cached ih =>\n    cases word with\n    | nil => simp only [List.length_cons,List.length_nil] at hlen;omega\n    | cons b word =>\n      have hh : cached.length ≤ word.length := by simpa only [List.length_cons,Nat.add_le_add_iff_right] using hlen\n      simpa only [fit_cons,List.head?_cons,Option.getD_some,List.tail_cons,List.length_cons,List.take_succ_cons] using\n        congrArg (List.cons b) (ih word hh)\n\nend RiemannGaussian.SemiprimeD1StackWordBlockExecution\n","RiemannGaussian.SemiprimeD1StackWordLess":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1StackSubtractorExecution\nimport RiemannGaussian.SemiprimeD1StackProcedureTrace\nimport RiemannGaussian.SemiprimeD1StackPhysicalLoops\n\n/-! # Actual numeric less-than guard for public checker words\nThe literal subtractor produces a real borrow prefix. The caller reads that bit,\nwrites the Boolean answer, and physically drains every remaining difference bit.\nThe original word values and desired comparison never occur in finite control.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 700000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1StackWordLess\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace S\nexport SemiprimeD1StackAdder (Stack store)\nend S\n\n/-- Five fixed Boolean data roles, including the physical comparison output. -/\nabbrev Stack := S.Stack⊕Unit\n/-- Fixed controller plus the literal subtractor's finite labels. -/\ninductive Label where\n  | start | readBorrow | save (b : Bool) | clearDifference | done\n  | subtract (pc : SemiprimeD1StackSubtractor.Label)\n  deriving DecidableEq,Fintype,Repr\n/-- Actual Boolean comparison output stack. -/\ndef output : Stack := .inr ()\n/-- Complete fixed physical comparison/cleanup code. -/\ndef program : Label→C.Instruction Stack Label\n  | .start => .call (.subtract (.start false)) .readBorrow\n  | .readBorrow => .base (.pop (.inl .output) (.save false) (.save false) (.save true))\n  | .save b => .base (.push output b .clearDifference)\n  | .clearDifference => .base (.pop (.inl .output) .done .clearDifference .clearDifference)\n  | .done => .base .halt\n  | .subtract pc => SemiprimeD1StackMultiplierLink.instruction Sum.inl Label.subtract\n      (SemiprimeD1StackSubtractor.code pc)\n/-- Exact physical operand/work/result payload. -/\ndef store (a b scratch diff valid : List Bool) : Stack→List Bool :=\n  Sum.elim (S.store a b scratch diff) (fun _=>valid)\n/-- Only both physical operand words are prepared at entry. -/\ndef initial (a b : List Bool) : C.State Stack Label :=\n  ⟨some .start,none,none,store a b [] [] [],[]⟩\n/-- Fixed actual machine with no comparison or decoded-value operation. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine (.inl .left) output .start program\n/-- Every data/return alphabet is finite, independent of both operands. -/\ntheorem all_alphabets_finite : ∀k,Finite (machine.Γ k) :=\n  SemiprimeD1StackCalls.all_alphabets_finite (.inl .left) output .start program\n/-- Transient control is finite and contains no numeric-word payload. -/\ntheorem control_finite : Finite machine.σ :=\n  SemiprimeD1StackCalls.control_finite (.inl .left) output .start program\n\nend RiemannGaussian.SemiprimeD1StackWordLess\n","RiemannGaussian.SemiprimeD1StackZeroBoundaryTable":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1BooleanTreeStreamOriginal\nimport RiemannGaussian.SemiprimeD1StackPublicZeroOriginal\nimport RiemannGaussian.SemiprimeD1StackProcedureInclusion\n/-! # Actual N-only whole zero-boundary tensor acquisition\nPublic acquisition runs once. ONE literal true bit seeds the actual tree writer;\nEOF supplies all other false entries. The physical modulus word is shared as\ndepth markers and restored EXACTLY by the real recursive writer. No arity,\nentry stream, table, evaluator, predicate, width or clock answer is input.\n-/\nset_option autoImplicit false\nset_option synthInstance.maxSize 8192\nnamespace RiemannGaussian.SemiprimeD1StackZeroBoundaryTable\nnamespace C\nexport SemiprimeD1StackCalls (Instruction State execute step run)\nend C\nnamespace P\nexport SemiprimeD1BinaryPublicAcquisition (Stack Label program input initial mainLabel digitStack fermatStack)\nend P\nnamespace T\nexport SemiprimeD1StackBooleanTree (Stack Label program initial store)\nend T\n/-- Thirty-two fixed Boolean roles, including one unused private depth shadow. -/\nabbrev Stack := P.Stack⊕T.Stack\n/-- Actual original public input role. -/\ndef original : Stack := .inl (P.digitStack (SemiprimeD1BinaryPublicAcquisition.Digits.metaStack .input))\n/-- The ACTUALLY acquired binary modulus word; its length is carry arity R+1. -/\ndef depthKey : P.Stack := P.fermatStack (.inr false)\n/-- Tree depth directly shares that physical word. Every marker bit is restored. -/\ndef treeStack : T.Stack→Stack\n  | .depth=>.inl depthKey\n  | k=>.inr k\n/-- Actual emitted whole tagged tree, not an entry or encoded answer input. -/\ndef output : Stack := treeStack .output\n/-- Literal finite pipeline control plus the actual component labels. -/\ninductive Control where | start | seed | write | done\n  deriving DecidableEq\ninstance : Fintype Control := Fintype.ofList [.start,.seed,.write,.done] (by intro k;cases k <;> simp)\n/-- All labels and the program are fixed before N. -/\nabbrev Label := Control⊕(P.Label⊕T.Label)\n/-- Literal public source inclusion. -/\ndef publicLabel (pc : P.Label) : Label := .inr (.inl pc)\n/-- Literal real recursive tree inclusion. -/\ndef treeLabel (pc : T.Label) : Label := .inr (.inr pc)\n/-- One fixed N-only program; one source call, ONE true push, one tree call. -/\ndef program : Label→C.Instruction Stack Label\n  | .inl .start=>.call (publicLabel (P.mainLabel .start)) (.inl .seed)\n  | .inl .seed=>.base (.push (treeStack .input) true (.inl .write))\n  | .inl .write=>.call (treeLabel .start) (.inl .done)\n  | .inl .done=>.base .halt\n  | .inr (.inl pc)=>SemiprimeD1StackValidationLink.instruction Sum.inl publicLabel (P.program pc)\n  | .inr (.inr pc)=>SemiprimeD1StackValidationLink.instruction treeStack treeLabel (T.program pc)\n/-- Public cache view after the actual source call; proof-side only. -/\ndef context (bits : List Bool) : P.Stack→List Bool := SemiprimeD1BinaryPublicAcquisitionComponents.result bits\n/-- Actual depth bytes, NOT a count/cardinality/template input. -/\ndef cached (bits : List Bool) : List Bool := context bits depthKey\n/-- Complete caller payload; unused private depth and all writer history are empty. -/\ndef store (p : P.Stack→List Bool) (input bytes : List Bool) : Stack→List Bool :=\n  Sum.elim p (T.store input [] [] bytes)\n/-- Original N ONLY, before every source/table operation. -/\ndef initial (bits : List Bool) : C.State Stack Label :=\n  ⟨some (.inl .start),none,none,store (P.input bits) [] [],[]⟩\n/-- The actual public metadata survive, while the acquired tree occupies output. -/\ndef done (bits : List Bool) : C.State Stack Label :=\n  ⟨none,none,none,store (context bits) []\n    (SemiprimeD1BooleanTreeStream.bytes (cached bits).length [true]),[]⟩\n/-- Fixed finite machine, original N as the only initially supplied data. -/\ndef machine : Turing.FinTM2 := SemiprimeD1StackCalls.machine original output (.inl .start) program\n/-- Real source and depth/output roles do not alias each other. -/\ntheorem tree_injective : Function.Injective treeStack := by decide\n/-- Actual stack inventory includes every metadata/private shadow role. -/\ntheorem stack_card : Fintype.card Stack=32 := by decide\n/-- Exact actual public marker word equals the frozen acquired carry width word. -/\ntheorem cached_eq (bits : List Bool) : cached bits=SemiprimeD1StackPublicZeroExecution.cached bits := rfl\nend RiemannGaussian.SemiprimeD1StackZeroBoundaryTable\n","RiemannGaussian.SemiprimeD1TensorNetworkRecursion":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorNetworkLayout\nimport RiemannGaussian.SemiprimeD1PackingReady\n\n/-! # Actual network-data scope contraction for the recursive schedule\nThe original selector's degree premises are derived from literal stored tensor\nports. The child scope is its acquired endpoint count, and the numeric packing\nguard follows uniformly from the public root scale, not an acceptance oracle.\nThe construction and semantics of the child literal tables are separate joins.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2200000\nnamespace RiemannGaussian.SemiprimeD1TensorNetworkRecursion\nopen scoped BigOperators\nopen SemiprimeD1TensorNetwork SemiprimeD1TensorNetworkLayout\n\n/-- A degree cap refers only to the actual cached tensor-port data. -/\ndef DegreeBound (net : Network) (degree : ℕ) : Prop :=\n  ∀ v ∈ vertices net, v.ports.length ≤ degree\n\n/-- Every cached left table belongs to the actual full vertex cache. -/\ntheorem left_mem (net : Network) (v : Fin net.leftCount) : net.left[v.val] ∈ vertices net := by\n  apply List.mem_append_left\n  have hm := List.getElem_mem (l := net.left.toList)\n    (show v.val < net.left.toList.length by simpa only [Vector.length_toList] using v.isLt)\n  simpa only [Vector.getElem_toList] using hm\n\n/-- Every cached right table belongs to the actual full vertex cache. -/\ntheorem right_mem (net : Network) (e : Fin net.rows.length) : net.right[e.val] ∈ vertices net := by\n  apply List.mem_append_right\n  have hm := List.getElem_mem (l := net.right.toList)\n    (show e.val < net.right.toList.length by simpa only [Vector.length_toList] using e.isLt)\n  simpa only [Vector.getElem_toList] using hm\n\n/-- Original sparse owner multiplicity is exactly the actual left table degree. -/\ntheorem owner_multiplicity {n : ℕ} (rows : Rows n) (Q : ℕ) (v : Fin n) :\n    SemiprimeSourceHistogramGrouping.multiplicity (fun i => (owner rows i).val)\n      (SemiprimeD1CollisionOriginal.ports n rows.length Q (arity rows)) v.val =\n        (leftPorts rows v).length := by\n  rw [original_ports]\n  simp only [SemiprimeSourceHistogramGrouping.multiplicity, leftPorts,\n    List.length_map, ← List.countP_eq_length_filter, Fin.ext_iff]\n\n/-- Original sparse factor multiplicity is exactly the actual right table degree. -/\ntheorem factor_multiplicity {n : ℕ} (rows : Rows n) (Q : ℕ) (e : Fin rows.length) :\n    SemiprimeSourceHistogramGrouping.multiplicity (fun i : Incidence rows => n+i.1.val)\n      (SemiprimeD1CollisionOriginal.ports n rows.length Q (arity rows)) (n+e.val) =\n        (rightPorts rows e).length := by\n  rw [original_ports]\n  simp only [SemiprimeSourceHistogramGrouping.multiplicity, rightPorts,\n    List.length_map, ← List.countP_eq_length_filter, Nat.add_left_cancel_iff, Fin.ext_iff]\n\n/-- The original selector's BOTH degree contracts are derived from literal layout\nand cached port lengths, with no supplied colour or fibre-count answers. -/\ntheorem original_degree_contract (net : Network) (hw : WellFormed net) (degree Q : ℕ)\n    (hd : DegreeBound net degree) :\n    (∀ i ∈ SemiprimeD1CollisionOriginal.ports net.leftCount net.rows.length Q (arity net.rows),\n      SemiprimeSourceHistogramGrouping.multiplicity (fun i => (owner net.rows i).val)\n        (SemiprimeD1CollisionOriginal.ports net.leftCount net.rows.length Q (arity net.rows))\n        (owner net.rows i).val ≤ degree) ∧\n    (∀ i ∈ SemiprimeD1CollisionOriginal.ports net.leftCount net.rows.length Q (arity net.rows),\n      SemiprimeSourceHistogramGrouping.multiplicity (fun i : Incidence net.rows => net.leftCount+i.1.val)\n        (SemiprimeD1CollisionOriginal.ports net.leftCount net.rows.length Q (arity net.rows))\n        (net.leftCount+i.1.val) ≤ degree) := by\n  constructor\n  · intro i _\n    rw [owner_multiplicity, ← hw.1 (owner net.rows i)]\n    exact hd _ (left_mem net _)\n  · intro i _\n    rw [factor_multiplicity, ← hw.2 i.1]\n    exact hd _ (right_mem net _)\n\n/-- Literal native child owner rows from the original physical sparse builder. -/\ndef child (net : Network) (a : ℕ) (q : Fin a) (g : Fin 64) : Rows (net.leftCount+net.rows.length) :=\n  childRows (SemiprimeD1ChildGraph.acquire net.leftCount net.rows.length 64 a\n    (arity net.rows) (owner net.rows) q g)\n\n/-- Actual acquired child variables shrink by16, derived from the stored parent\ntables and the literal original packing inequality. -/\ntheorem child_shrink (net : Network) (hw : WellFormed net) (degree a : ℕ)\n    (hd : DegreeBound net degree) (hsmall : 2*(64^(2*a))^2*degree ≤ edgeCount net)\n    (q : Fin a) (g : Fin 64) : 16*scope (child net a q g) ≤ edgeCount net := by\n  have hdegrees := original_degree_contract net hw degree a hd\n  have hnumeric : 2*(64^(2*a))^2*degree ≤\n      (SemiprimeD1CollisionOriginal.ports net.leftCount net.rows.length a (arity net.rows)).length := by\n    rwa [original_ports]\n  have h := SemiprimeD1ChildGraphBounds.child64_shrink net.leftCount net.rows.length a\n    (arity net.rows) (owner net.rows) degree hdegrees.1 hdegrees.2 hnumeric q g\n  rw [SemiprimeD1ChildGraphPartition.arity_sum, original_ports] at h\n  change 16*scope (childRows (SemiprimeD1ChildGraph.acquire net.leftCount net.rows.length 64 a\n    (arity net.rows) (owner net.rows) q g)) ≤ edgeCount net\n  rw [child_scope]\n  exact h\n\n/-- The conservative factor8 used by the exponent ledger holds for the ACTUAL\nacquired child graph, rather than an assumed recursive size sequence. -/\ntheorem child_shrink_eight (net : Network) (hw : WellFormed net) (degree a : ℕ)\n    (hd : DegreeBound net degree) (hsmall : 2*(64^(2*a))^2*degree ≤ edgeCount net)\n    (q : Fin a) (g : Fin 64) : scope (child net a q g)*8 ≤ edgeCount net := by\n  have h := child_shrink net hw degree a hd hsmall q g\n  omega\n\n/-- Uniform original-scale acceptance gives the scope contraction for EVERY\nactual well-formed network at EVERY active recursive depth. No separate packing\nacceptance, child size, or local fibre-count premise remains. -/\ntheorem eventually_actual_children : ∀ᶠ s : ℕ in Filter.atTop,\n    ∀ (depth : ℕ) (net : Network), WellFormed net →\n      DegreeBound net (SemiprimeD1PackingReady.degreeCap s) →\n      SemiprimeD1Schedule.Active s (SemiprimeD1PackingReady.logarithm s) depth (edgeCount net) →\n      ∀ (q : Fin (SemiprimeD1Schedule.exponent (SemiprimeD1PackingReady.logarithm s) depth)) (g : Fin 64),\n        scope (child net (SemiprimeD1Schedule.exponent (SemiprimeD1PackingReady.logarithm s) depth) q g)*8 ≤\n          edgeCount net := by\n  filter_upwards [SemiprimeD1PackingReady.eventually_all_depths] with s hs\n  intro depth net hw hd ha q g\n  have hg := hs depth (edgeCount net) (SemiprimeD1PackingReady.degreeCap s) ha le_rfl\n  exact child_shrink_eight net hw _ _ hd hg.1.le q g\n\nend RiemannGaussian.SemiprimeD1TensorNetworkRecursion\n","RiemannGaussian.SemiprimeD1TensorTables":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1JetRingBits\n\n/-! # Concrete eager local tensor tables\nSubexponential space permits complete local tables. They contain literal\ncoefficient words; there are no entry recipes or requested-value suppliers in\nan acquired table. Building from an actual producer retains every leaf report.\nBit/cell reports below are separate from whole-controller tape simulation.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeD1TensorTables\nopen SemiprimeD1JetAxes (Context)\nopen SemiprimeSourceCompactBits (Compact)\n\n/-- Concrete canonical data for every assignment to an ordered local port list. -/\ninductive Table : ℕ→Type\n  | leaf (words : List (List Bool)) : Table 0\n  | fork {n : ℕ} (low high : Table n) : Table (n+1)\n  deriving Repr\n\n/-- An acquired finite table with its complete retained producer/cell report. -/\nstructure Acquired (n : ℕ) where\n  /-- Entire literal truth table, with no evaluator closure. -/\n  table : Table n\n  /-- Original producer work and every table allocation. -/\n  clock : ℕ\n\n/-- Intrinsic current-context word shape at each actual stored tensor entry. -/\ndef GoodWords (ctx : Context) (words : List (List Bool)) : Prop :=\n  words.length=ctx.rank ∧ ∀w∈words,Compact w ∧ w.length≤ctx.precision\n\n/-- Every stored entry is canonical in the CURRENT context and precision. -/\ndef Good (ctx : Context) : {n : ℕ}→Table n→Prop\n  | _,.leaf words => GoodWords ctx words\n  | _,.fork low high => Good ctx low ∧ Good ctx high\n\n/-- Physical read, following actual assignment bits and copying the final vector. -/\ndef lookup : {n : ℕ}→Table n→List Bool→SemiprimeD1JetRingBits.Run\n  | _,.leaf words,_ =>\n    let out := SemiprimeD1JetAxes.copyVector words\n    ⟨out.1,out.2⟩\n  | _,.fork low high,bits =>\n    let next := if bits.head?.getD false then lookup high bits.tail else lookup low bits.tail\n    ⟨next.words,next.clock+4⟩\n\n/-- Mathematical local tensor value; only the acquired table is inspected. -/\ndef valueAt : {n : ℕ}→Table n→(Fin n→Bool)→List (List Bool)\n  | _,.leaf words,_ => words\n  | _,.fork low high,bits => if bits 0 then valueAt high (fun i => bits i.succ) else valueAt low (fun i => bits i.succ)\n\n/-- Lookup recovers the exact local tensor value, rather than a supplied entry answer. -/\ntheorem lookup_value {n : ℕ} (table : Table n) (bits : List Bool) (hlen : bits.length=n) :\n    (lookup table bits).words=valueAt table (fun i => bits[i.val]'(by omega)) := by\n  induction table generalizing bits with\n  | leaf words => exact SemiprimeD1JetAxes.copyVector_value words\n  | @fork n low high ihlow ihhigh =>\n    cases bits with\n    | nil => simp at hlen\n    | cons bit bits =>\n      have ht : bits.length=n := by simpa only [List.length_cons] using Nat.succ.inj hlen\n      cases bit\n      · simpa only [lookup,valueAt,List.head?_cons,Option.getD_some,Bool.false_eq_true,\n          ite_false,List.tail_cons,Fin.val_zero,Fin.val_succ,List.getElem_cons_zero,List.getElem_cons_succ] using ihlow bits ht\n      · simpa only [lookup,valueAt,List.head?_cons,Option.getD_some,ite_true,List.tail_cons,\n          Fin.val_zero,Fin.val_succ,List.getElem_cons_zero,List.getElem_cons_succ] using ihhigh bits ht\n\n/-- Every reached leaf inherits actual canonical shape, not an output Fits premise. -/\ntheorem lookup_good (ctx : Context) {n : ℕ} (table : Table n) (ht : Good ctx table) (bits : List Bool) :\n    GoodWords ctx (lookup table bits).words := by\n  induction table generalizing bits with\n  | leaf words => simpa only [lookup,SemiprimeD1JetAxes.copyVector_value,Good] using ht\n  | fork low high ihlow ihhigh =>\n    change GoodWords ctx (if bits.head?.getD false then lookup high bits.tail else lookup low bits.tail).words\n    split_ifs\n    · exact ihhigh ht.2 _\n    · exact ihlow ht.1 _\n\n/-- Physical entry reads pay every traversed branch and every copied coefficient bit. -/\ntheorem lookup_clock (ctx : Context) {n : ℕ} (table : Table n) (ht : Good ctx table) (bits : List Bool) :\n    (lookup table bits).clock≤ctx.rank*(3*ctx.precision+4)+1+4*n := by\n  induction table generalizing bits with\n  | leaf words =>\n    have h := SemiprimeD1JetAxes.copyVector_clock_le words ctx.precision (fun w hw => (ht.2 w hw).2)\n    simpa only [lookup,ht.1,Nat.mul_zero,Nat.add_zero] using h\n  | @fork n low high ihlow ihhigh =>\n    have hl := ihlow ht.1 bits.tail\n    have hh := ihhigh ht.2 bits.tail\n    change (if bits.head?.getD false then lookup high bits.tail else lookup low bits.tail).clock+4≤_\n    split_ifs <;> omega\n\n/-- Materialize every actual local assignment, caching both children once. -/\ndef build : (n : ℕ)→(List Bool→SemiprimeD1JetRingBits.Run)→Acquired n\n  | 0,producer =>\n    let entry := producer []\n    ⟨.leaf entry.words,entry.clock+2⟩\n  | n+1,producer =>\n    let low := build n (fun bits => producer (false::bits))\n    let high := build n (fun bits => producer (true::bits))\n    ⟨.fork low.table high.table,low.clock+high.clock+5⟩\n\n/-- Every entry of the materialized table is the actual producer result. -/\ntheorem build_value (n : ℕ) (producer : List Bool→SemiprimeD1JetRingBits.Run)\n    (bits : List Bool) (hlen : bits.length=n) :\n    (lookup (build n producer).table bits).words=(producer bits).words := by\n  induction n generalizing producer bits with\n  | zero =>\n    have hb : bits=[] := List.eq_nil_of_length_eq_zero hlen\n    subst bits\n    exact SemiprimeD1JetAxes.copyVector_value _\n  | succ n ih =>\n    cases bits with\n    | nil => simp at hlen\n    | cons bit bits =>\n      have ht : bits.length=n := by\n        simp only [List.length_cons] at hlen\n        omega\n      cases bit <;> simp only [build,lookup,List.head?_cons,Option.getD_some,\n        Bool.false_eq_true,ite_false,ite_true,List.tail_cons] <;> exact ih _ bits ht\n\n/-- Canonical producer outputs give canonical full tables, from actual assignment shape alone. -/\ntheorem build_good (ctx : Context) (n : ℕ) (producer : List Bool→SemiprimeD1JetRingBits.Run)\n    (hp : ∀bits,bits.length=n→GoodWords ctx (producer bits).words) : Good ctx (build n producer).table := by\n  induction n generalizing producer with\n  | zero => exact hp [] rfl\n  | succ n ih =>\n    exact ⟨ih _ (fun bits hb => hp (false::bits) (by simp only [List.length_cons,hb])),\n      ih _ (fun bits hb => hp (true::bits) (by simp only [List.length_cons,hb]))⟩\n\n/-- ALL actual producer reports and table cells have the exact eager exponential scale. -/\ntheorem build_clock (n B : ℕ) (producer : List Bool→SemiprimeD1JetRingBits.Run)\n    (hp : ∀bits,bits.length=n→(producer bits).clock≤B) :\n    (build n producer).clock+5≤(B+7)*2^n := by\n  induction n generalizing producer with\n  | zero =>\n    have h := hp [] rfl\n    change (producer []).clock+2+5≤_\n    simpa only [pow_zero,Nat.mul_one] using Nat.add_le_add_right h 7\n  | succ n ih =>\n    have hl := ih _ (fun bits hb => hp (false::bits) (by simp only [List.length_cons,hb]))\n    have hh := ih _ (fun bits hb => hp (true::bits) (by simp only [List.length_cons,hb]))\n    change (build n (fun bits => producer (false::bits))).clock+\n      (build n (fun bits => producer (true::bits))).clock+5+5≤_\n    rw [pow_succ,←Nat.mul_assoc]\n    omega\n\n/-- A direct encoding inventory, counting copied bits/cells and each table tag. -/\ndef storage : {n : ℕ}→Table n→ℕ\n  | _,.leaf words => (SemiprimeD1JetAxes.copyVector words).2+1\n  | _,.fork low high => storage low+storage high+1\n\n/-- Complete canonical table memory is bounded uniformly over EVERY assignment. -/\ntheorem storage_bound (ctx : Context) {n : ℕ} (table : Table n) (ht : Good ctx table) :\n    storage table+1≤(ctx.rank*(3*ctx.precision+4)+3)*2^n := by\n  induction table with\n  | leaf words =>\n    have h := SemiprimeD1JetAxes.copyVector_clock_le words ctx.precision (fun w hw => (ht.2 w hw).2)\n    simpa only [storage,ht.1,pow_zero,Nat.mul_one,Nat.add_assoc] using Nat.add_le_add_right h 2\n  | @fork n low high ihlow ihhigh =>\n    have hl := ihlow ht.1\n    have hh := ihhigh ht.2\n    change storage low+storage high+1+1≤_\n    rw [pow_succ,←Nat.mul_assoc]\n    omega\n\nend RiemannGaussian.SemiprimeD1TensorTables\n","RiemannGaussian.SemiprimeD1TensorTapeLeafBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeLeaf\nimport RiemannGaussian.SemiprimeD1OriginalCallBounds\n\n/-! # Original stopped-state bounds for the tape-backed eager leaf\nOnly numerical state/leaf-size facts are reused. The clock belongs to the new\nexecuted tape backend; it is not identified with the older native-lookup clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeD1TensorTapeLeafBudget\nopen SemiprimeD1TensorTapeLeaf SemiprimeD1TensorNetwork SemiprimeD1JetAxes\nopen SemiprimeD1LeafCounterBounds SemiprimeD1NetworkStateResources\nopen SemiprimeD1RecursiveCallTree SemiprimeD1OriginalStateResources\nopen SemiprimeD1Schedule SemiprimeD1RecursiveCounter\n\n/-- One fixed polynomial in actual enumeration, arithmetic and input-storage sizes. -/\ndef polynomial (M axes N p V L I : ℕ) : ℕ :=\n  (9*p+3*N+8)+L*(3*M+4)+V*(8*(I+1)*I+4+\n    SemiprimeD1JetRingBounds.mulBudget axes N p p+7)+\n    (N*(3*p+4)+1)+(N*(6*N+11*p+9*p+17)+10*N+5)+13\n\n/-- All dimension arguments are genuinely polynomial resources, including inventory. -/\ntheorem polynomial_mono {M axes N p V L I M' axes' N' p' V' L' I' : ℕ}\n    (hM : M ≤ M') (ha : axes ≤ axes') (hN : N ≤ N') (hp : p ≤ p')\n    (hV : V ≤ V') (hL : L ≤ L') (hI : I ≤ I') :\n    polynomial M axes N p V L I ≤ polynomial M' axes' N' p' V' L' I' := by\n  unfold polynomial SemiprimeD1JetRingBounds.mulBudget\n    SemiprimeD1JetRingBounds.mulAtBudget SemiprimeD1JetRingBounds.termBudget\n  gcongr\n\n/-- The literal network's full port-list length is covered by its input inventory. -/\ntheorem scope_le_inventory (net : Network) : scopeSize (vertices net) ≤ inventory net := by\n  have h : ∀xs : List SemiprimeD1LeafCounter.Vertex,\n      scopeSize xs ≤ (xs.map (fun v => SemiprimeD1TensorTables.storage v.table+v.ports.length+1)).sum := by\n    intro xs\n    induction xs with\n    | nil => simp [scopeSize]\n    | cons v vs ih => simp only [scopeSize,List.map_cons,List.sum_cons] at *;omega\n  have hs:=h (vertices net)\n  unfold inventory\n  omega\n\n/-- Actual whole leaf report, with no externally supplied table or lookup budget. -/\ntheorem leaf_clock (ctx : Context) (net : Network) (hg : Good ctx net) :\n    (SemiprimeD1TensorTapeLeaf.leaf ctx net).clock ≤\n      polynomial (edgeCount net) ctx.axes.length ctx.rank ctx.precision\n        (vertices net).length (scopeSize (vertices net)) (inventory net)*2^(edgeCount net) :=\n  SemiprimeD1TensorTapeLeaf.leaf_clock ctx net hg\n\n/-- Original resource cofactor fixed before choosing any reachable leaf. -/\ndef originalPolynomial (s : ℕ) : ℕ :=\n  polynomial s (SemiprimeD1PackingReady.logarithm s+1) (rankCap s) (precisionCap s)\n    (5*s) (inventoryCap s) (inventoryCap s)\n\n/-- Actual reachable-state bounds give the entire new cofactor internally. -/\ntheorem bound_polynomial (s : ℕ) (call : Call) (hb : Bound s call) :\n    polynomial (edgeCount call.net) call.ctx.axes.length call.ctx.rank call.ctx.precision\n      (vertices call.net).length (scopeSize (vertices call.net)) (inventory call.net) ≤\n        originalPolynomial s := by\n  have ha : call.ctx.axes.length ≤ SemiprimeD1PackingReady.logarithm s+1 :=\n    hb.axes_length.trans_le hb.depth\n  have hv : (vertices call.net).length ≤ 5*s := by\n    rw [vertices_length]\n    exact hb.vertex_count\n  exact polynomial_mono hb.edge_count ha hb.rank hb.precision hv\n    ((scope_le_inventory call.net).trans hb.inventory) hb.inventory\n\n/-- Every actual failed-guard original leaf executes the new tape backend at\n2^leafSize times a fixed polynomial in inherited original state resources. -/\ntheorem eventually_original_stopped : ∀ᶠ ell : ℕ in Filter.atTop,\n    ∀ (N : ℕ) (hN : 0<N), SemiprimeMacroParameters.bitLength N=ell →\n      ∀ (fixed : List (Fin (SemiprimePublicAcquiredExecution.wireCount N)×Bool)) (call : Call),\n      Reach (SemiprimeD1PublicPackingReady.scale ell) (originalCall N hN fixed) call →\n      activeTest (SemiprimeD1PublicPackingReady.scale ell)\n        (SemiprimeD1PackingReady.logarithm (SemiprimeD1PublicPackingReady.scale ell))\n        call.depth (edgeCount call.net)=false →\n      (SemiprimeD1TensorTapeLeaf.leaf call.ctx call.net).clock ≤\n        originalPolynomial (SemiprimeD1PublicPackingReady.scale ell)*\n          2^leafSize (SemiprimeD1PublicPackingReady.scale ell)\n            (SemiprimeD1PackingReady.logarithm (SemiprimeD1PublicPackingReady.scale ell)) := by\n  filter_upwards [SemiprimeD1OriginalStateResources.eventually_original,\n    SemiprimeD1OriginalCallBounds.eventually_original_stopped_leaf] with ell hstate hsize\n  intro N hN hEll fixed call hr hstop\n  have hb:=hstate N hN hEll fixed call hr\n  have hm:=(hsize N hN hEll fixed call hr hstop).1\n  have hs:=original_shape N hN fixed\n  have hg:=(SemiprimeD1RecursiveCallState.reach_shape _ _ _ hr hs.1 hs.2.1 hs.2.2.1).2.2\n  exact (leaf_clock call.ctx call.net hg).trans\n    (Nat.mul_le_mul (bound_polynomial _ call hb)\n      (Nat.pow_le_pow_right (by decide : 0<(2:ℕ)) hm))\n\n/-- Actual original exhausted-fuel calls use the same executed tape leaf bound. -/\ntheorem eventually_original_zero : ∀ᶠ ell : ℕ in Filter.atTop,\n    ∀ (N : ℕ) (hN : 0<N), SemiprimeMacroParameters.bitLength N=ell →\n      ∀ (fixed : List (Fin (SemiprimePublicAcquiredExecution.wireCount N)×Bool)) (call : Call),\n      Reach (SemiprimeD1PublicPackingReady.scale ell) (originalCall N hN fixed) call →\n      SemiprimeD1PackingReady.logarithm (SemiprimeD1PublicPackingReady.scale ell)+1 ≤ call.depth+0 →\n      (SemiprimeD1TensorTapeLeaf.leaf call.ctx call.net).clock ≤\n        originalPolynomial (SemiprimeD1PublicPackingReady.scale ell)*\n          2^leafSize (SemiprimeD1PublicPackingReady.scale ell)\n            (SemiprimeD1PackingReady.logarithm (SemiprimeD1PublicPackingReady.scale ell)) := by\n  filter_upwards [eventually_original_stopped] with ell hleaf\n  intro N hN hEll fixed call hr hf\n  exact hleaf N hN hEll fixed call hr\n    (SemiprimeD1RecursiveLeafBounds.zero_fuel_inactive _ call.depth hf (edgeCount call.net))\n\nend RiemannGaussian.SemiprimeD1TensorTapeLeafBudget\n","RiemannGaussian.SemiprimeD1TensorTapePublicCounter":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapeRecursiveReport\nimport RiemannGaussian.SemiprimeD1PhysicalPublicCounter\n\n/-! # Actual original-input public prefix caller with tape-backed recursion\nEvery query acquires its root and executes the new closed recursion. Only word\nsemantics transfer; its actual setup and recursive reports remain distinct.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 400000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1TensorTapePublicCounter\nopen SemiprimeBitArithmetic SemiprimePublicAcquiredExecution\nattribute [local irreducible] SemiprimeD1RootTensorTables.acquirePositive\n\n/-- Actual original-N/prefix root acquisition followed by the new tape recursion. -/\ndef prefixRun (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) :\n    SemiprimeD1JetRingBits.Run :=\n  let root:=SemiprimeD1RootNetwork.acquirePositive N hN fixed\n  let s:=SemiprimeD1PublicPackingReady.scale (SemiprimeMacroParameters.bitLength N)\n  let lam:=SemiprimeD1PackingReady.logarithm s\n  let out:=SemiprimeD1TensorTapeRecursiveCounter.run s (lam+1) 0\n    SemiprimeD1RootOwnerTables.rootContext root.network\n  ⟨out.words,root.clock+out.clock+10*(wireCount N+fixed.length+SemiprimeMacroParameters.bitLength N+1)⟩\n\n/-- Public words agree literally, with no old/new query-clock identification. -/\ntheorem prefixRun_words_eq_physical (N : ℕ) (hN : 0<N)\n    (fixed : List (Fin (wireCount N)×Bool)) :\n    (prefixRun N hN fixed).words=(SemiprimeD1PhysicalPublicCounter.prefixRun N hN fixed).words := by\n  unfold prefixRun SemiprimeD1PhysicalPublicCounter.prefixRun\n  dsimp only\n  exact SemiprimeD1TensorTapeRecursiveCounter.run_words_eq_physical _ _ _ _ _\n\n/-- Actual two-bit scalar count returned by the new executed query. -/\ndef prefixCount (N : ℕ) (hN : 0<N) (fixed : List (Fin (wireCount N)×Bool)) : ℕ :=\n  bitValue (((prefixRun N hN fixed).words[0]?).getD [])\n\n/-- Literal scalar equality, not a supplied conditional-count oracle. -/\ntheorem prefixCount_eq_physical (N : ℕ) (hN : 0<N)\n    (fixed : List (Fin (wireCount N)×Bool)) :\n    prefixCount N hN fixed=SemiprimeD1PhysicalPublicCounter.prefixCount N hN fixed := by\n  unfold prefixCount SemiprimeD1PhysicalPublicCounter.prefixCount\n  rw [prefixRun_words_eq_physical]\n\n/-- Closed original count semantics for every semiprime prefix, including squares. -/\ntheorem prefixCount_exact (N p q : ℕ) (hN : 0<N) (hp : p.Prime) (hq : q.Prime)\n    (hsem : N=p*q) (fixed : List (Fin (wireCount N)×Bool)) :\n    prefixCount N hN fixed=SemiprimeCountRecovery.acceptedCount\n      (SemiprimeCountRecovery.restricted SemiprimeCounterSearch.assignmentBit\n        (indexedPredicate N hN) fixed) :=\n  (prefixCount_eq_physical N hN fixed).trans\n    (SemiprimeD1PhysicalPublicCounter.prefixCount_exact N p q hN hp hq hsem fixed)\n\n/-- Mathematical search specification using this same actual prefix value. -/\ndef search (N : ℕ) (hN : 0<N) : SemiprimeCountRecovery.SearchResult (Fin (wireCount N)) :=\n  SemiprimeCountRecovery.search (prefixCount N hN) (List.finRange (wireCount N))\n\n/-- Exact search data and query counter, without transferring report fields. -/\ntheorem search_eq_physical (N : ℕ) (hN : 0<N) :\n    search N hN=SemiprimeD1PhysicalPublicCounter.search N hN := by\n  have he : prefixCount N hN=SemiprimeD1PhysicalPublicCounter.prefixCount N hN :=\n    funext (prefixCount_eq_physical N hN)\n  exact congrArg (fun count => SemiprimeCountRecovery.search count (List.finRange (wireCount N))) he\n\n/-- Original linear query count for the actual new prefix values. -/\ntheorem search_queries (N : ℕ) (hN : 0<N) : (search N hN).queries ≤ wireCount N+1 := by\n  rw [search_eq_physical]\n  exact SemiprimeD1PhysicalPublicCounter.search_queries N hN\n\nend RiemannGaussian.SemiprimeD1TensorTapePublicCounter\n","RiemannGaussian.SemiprimeD1TensorTapePublicSearch":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeD1TensorTapePublicCounter\nimport RiemannGaussian.SemiprimeD1PhysicalPublicSearch\n\n/-! # Actual public search retains every acquired prefix report\nThe closed selector below calls the original-input physical prefix counter on\nthe same zero-first branches as the public search. Its query-work field adds\nevery actual root acquisition and recursive report. Metadata remains an explicit\nseparate report; no whole primitive search/decoder clock is asserted here.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 300000\nset_option Elab.async false\nnamespace RiemannGaussian.SemiprimeD1TensorTapePublicSearch\nopen SemiprimePublicAcquiredExecution SemiprimeBitArithmetic\nopen SemiprimeD1TensorTapePublicCounter\nattribute [local irreducible] prefixRun\n\n/-- Literal selected data, call count and both retained report contributions. -/\nstructure SelectionRun (I : Type) where\n  /-- Selected original wire labels and exact number of executed queries. -/\n  selection : SemiprimeCountRecovery.Selection I\n  /-- Sum of the actual prefix counters' own complete retained reports. -/\n  queryWork : ℕ\n  /-- Finite selection/list/control report, separate from primitive lowering. -/\n  metadataWork : ℕ\n\n/-- Closed actual zero-first selector. No count callback is an input. -/\ndef select (N : ℕ) (hN : 0 < N) :\n    List (Fin (wireCount N)) → List (Fin (wireCount N) × Bool) → SelectionRun (Fin (wireCount N))\n  | [],_ => ⟨⟨[],0⟩,0,1⟩\n  | i::rest,fixed =>\n    let current := prefixRun N hN ((i,false)::fixed)\n    let n := bitValue ((current.words[0]?).getD [])\n    let b := if 0 < n then false else true\n    let tail := select N hN rest ((i,b)::fixed)\n    ⟨⟨(i,b)::tail.selection.values,tail.selection.queries+1⟩,\n      current.clock+tail.queryWork,tail.metadataWork+10*(wireCount N+fixed.length+rest.length+1)+3⟩\n\n/-- Actual selected data and query count coincide with the already proved public\nselector, while the new report records every real prefix execution. -/\ntheorem select_spec (N : ℕ) (hN : 0 < N) (indices : List (Fin (wireCount N)))\n    (fixed : List (Fin (wireCount N) × Bool)) :\n    (select N hN indices fixed).selection =\n      SemiprimeCountRecovery.select (SemiprimeD1TensorTapePublicCounter.prefixCount N hN) indices fixed := by\n  induction indices generalizing fixed with\n  | nil => rfl\n  | cons i rest ih =>\n    simp only [select,SemiprimeCountRecovery.select,SemiprimeD1TensorTapePublicCounter.prefixCount,ih]\n    rfl\n\n/-- Every actual selected prefix has length at most the original wire count.\nThus a uniform bound for original prefix runs suffices; no arbitrary global\npredicate counter or supplied solved branch is introduced. -/\ntheorem select_queryWork (N : ℕ) (hN : 0 < N) (indices : List (Fin (wireCount N)))\n    (fixed : List (Fin (wireCount N) × Bool)) (C : ℕ)\n    (hC : ∀ fixedQuery : List (Fin (wireCount N) × Bool), fixedQuery.length ≤ wireCount N →\n      (prefixRun N hN fixedQuery).clock ≤ C)\n    (hsize : fixed.length+indices.length ≤ wireCount N) :\n    (select N hN indices fixed).queryWork ≤ indices.length*C := by\n  induction indices generalizing fixed with\n  | nil => simp only [select,List.length_nil,Nat.zero_mul,le_refl]\n  | cons i rest ih =>\n    let b := if 0 < SemiprimeD1TensorTapePublicCounter.prefixCount N hN ((i,false)::fixed) then false else true\n    have hc := hC ((i,false)::fixed) (by simp only [List.length_cons] at *;omega)\n    have ht := ih ((i,b)::fixed) (by simp only [List.length_cons] at *;omega)\n    change (prefixRun N hN ((i,false)::fixed)).clock+\n      (select N hN rest ((i,b)::fixed)).queryWork ≤ (rest.length+1)*C\n    nlinarith\n\n/-- The literal selector metadata report has an original wire-count polynomial,\nwith each growing prefix and shrinking remaining list charged. -/\ntheorem select_metadataWork (N : ℕ) (hN : 0 < N) (indices : List (Fin (wireCount N)))\n    (fixed : List (Fin (wireCount N) × Bool))\n    (hsize : fixed.length+indices.length ≤ wireCount N) :\n    (select N hN indices fixed).metadataWork ≤ (indices.length+1)*40*(wireCount N+1) := by\n  induction indices generalizing fixed with\n  | nil => simp only [select,List.length_nil];omega\n  | cons i rest ih =>\n    let b := if 0 < SemiprimeD1TensorTapePublicCounter.prefixCount N hN ((i,false)::fixed) then false else true\n    have ht := ih ((i,b)::fixed) (by simp only [List.length_cons] at *;omega)\n    change (select N hN rest ((i,b)::fixed)).metadataWork+\n      10*(wireCount N+fixed.length+rest.length+1)+3 ≤ (rest.length+1+1)*40*(wireCount N+1)\n    simp only [List.length_cons] at hsize\n    nlinarith\n\n/-- Initial existence result, selected original wires, and all retained reports. -/\nstructure SearchRun (I : Type) where\n  /-- Actual public search data and executed count-query counter. -/\n  result : SemiprimeCountRecovery.SearchResult I\n  /-- Every executed prefix's original acquisition and recursion work. -/\n  queryWork : ℕ\n  /-- Original search/list/control report, with host lowering still separate. -/\n  metadataWork : ℕ\n\n/-- Concrete original-N search executes its own prefix runs on every branch. -/\ndef search (N : ℕ) (hN : 0 < N) : SearchRun (Fin (wireCount N)) :=\n  let initial := prefixRun N hN []\n  if 0 < bitValue ((initial.words[0]?).getD []) then\n    let chosen := select N hN (List.finRange (wireCount N)) []\n    ⟨⟨some chosen.selection.values,chosen.selection.queries+1⟩,\n      initial.clock+chosen.queryWork,chosen.metadataWork+10*(wireCount N+1)+3⟩\n  else ⟨⟨none,1⟩,initial.clock,10*(wireCount N+1)+3⟩\n\n/-- The entire actual new search result is the proved public search result. -/\ntheorem search_spec (N : ℕ) (hN : 0 < N) :\n    (search N hN).result = SemiprimeD1TensorTapePublicCounter.search N hN := by\n  by_cases h : 0 < SemiprimeD1TensorTapePublicCounter.prefixCount N hN []\n  · have hb : 0 < bitValue (((prefixRun N hN []).words[0]?).getD []) := h\n    simp only [search,SemiprimeD1TensorTapePublicCounter.search,SemiprimeCountRecovery.search,\n      ite_eq_left h,ite_eq_left hb,select_spec]\n  · have hb : ¬0 < bitValue (((prefixRun N hN []).words[0]?).getD []) := h\n    simp only [search,SemiprimeD1TensorTapePublicCounter.search,SemiprimeCountRecovery.search,\n      ite_eq_right h,ite_eq_right hb]\n\n/-- Exact original query-count bound applies to the report-producing search. -/\ntheorem search_queries (N : ℕ) (hN : 0 < N) :\n    (search N hN).result.queries ≤ wireCount N+1 := by\n  rw [search_spec]\n  exact SemiprimeD1TensorTapePublicCounter.search_queries N hN\n\n/-- Aggregation pays for one actual original-input run per executed prefix.\nThis is an internal composition lemma; the final rate must discharge hC from\nthe actual root/recursive report bounds, not assume an acquired count budget. -/\ntheorem search_queryWork (N : ℕ) (hN : 0 < N) (C : ℕ)\n    (hC : ∀ fixedQuery : List (Fin (wireCount N) × Bool), fixedQuery.length ≤ wireCount N →\n      (prefixRun N hN fixedQuery).clock ≤ C) :\n    (search N hN).queryWork ≤ (wireCount N+1)*C := by\n  have hi := hC [] (by simp)\n  have hs := select_queryWork N hN (List.finRange (wireCount N)) [] C hC (by simp)\n  simp only [List.length_finRange] at hs\n  dsimp only [search]\n  split\n  · dsimp only\n    nlinarith\n  · dsimp only\n    nlinarith\n\n/-- Explicit original-size search metadata, including initial existence test. -/\ntheorem search_metadataWork (N : ℕ) (hN : 0 < N) :\n    (search N hN).metadataWork ≤ (wireCount N+2)*60*(wireCount N+1) := by\n  have hs := select_metadataWork N hN (List.finRange (wireCount N)) [] (by simp)\n  simp only [List.length_finRange] at hs\n  dsimp only [search]\n  split <;> dsimp only <;> nlinarith\n\n/-- Actual new search data match the former physical search, not its query work. -/\ntheorem search_result_eq_physical (N : ℕ) (hN : 0<N) :\n    (search N hN).result=(SemiprimeD1PhysicalPublicSearch.search N hN).result :=\n  (search_spec N hN).trans ((SemiprimeD1TensorTapePublicCounter.search_eq_physical N hN).trans\n    (SemiprimeD1PhysicalPublicSearch.search_spec N hN).symm)\n\n/-- Only native list/control metadata agrees after proved actual branch equality. -/\ntheorem select_metadata_eq_physical (N : ℕ) (hN : 0<N)\n    (indices : List (Fin (wireCount N))) (fixed : List (Fin (wireCount N)×Bool)) :\n    (select N hN indices fixed).metadataWork=\n      (SemiprimeD1PhysicalPublicSearch.select N hN indices fixed).metadataWork := by\n  induction indices generalizing fixed with\n  | nil => rfl\n  | cons i rest ih =>\n    simp only [select,SemiprimeD1PhysicalPublicSearch.select,\n      SemiprimeD1TensorTapePublicCounter.prefixRun_words_eq_physical,ih]\n\n/-- Search metadata equality does not identify the changed prefix reports. -/\ntheorem search_metadata_eq_physical (N : ℕ) (hN : 0<N) :\n    (search N hN).metadataWork=(SemiprimeD1PhysicalPublicSearch.search N hN).metadataWork := by\n  simp only [search,SemiprimeD1PhysicalPublicSearch.search,\n    SemiprimeD1TensorTapePublicCounter.prefixRun_words_eq_physical]\n  split\n  · exact congrArg (fun k => k+10*(wireCount N+1)+3)\n      (select_metadata_eq_physical N hN (List.finRange (wireCount N)) [])\n  · rfl\n\n/-- Proof-side chronological query list; it is not allocated by executed select. -/\ndef selectPrefixes (N : ℕ) (hN : 0<N) : List (Fin (wireCount N)) →\n    List (Fin (wireCount N)×Bool) → List (List (Fin (wireCount N)×Bool))\n  | [],_ => []\n  | i::rest,fixed =>\n    let b:=if 0<SemiprimeD1TensorTapePublicCounter.prefixCount N hN ((i,false)::fixed) then false else true\n    ((i,false)::fixed)::selectPrefixes N hN rest ((i,b)::fixed)\n\n/-- Exact sum of reports of all actual selector queries, with multiplicity. -/\ntheorem select_queryWork_eq (N : ℕ) (hN : 0<N) (indices : List (Fin (wireCount N)))\n    (fixed : List (Fin (wireCount N)×Bool)) :\n    (select N hN indices fixed).queryWork=\n      ((selectPrefixes N hN indices fixed).map (fun f => (prefixRun N hN f).clock)).sum := by\n  induction indices generalizing fixed with\n  | nil => rfl\n  | cons i rest ih =>\n    simp only [select,selectPrefixes,List.map_cons,List.sum_cons,\n      SemiprimeD1TensorTapePublicCounter.prefixCount,ih]\n    rfl\n\n/-- Proof-side complete executed-prefix trace, including initial existence query. -/\ndef queriedPrefixes (N : ℕ) (hN : 0<N) : List (List (Fin (wireCount N)×Bool)) :=\n  []::(if 0<SemiprimeD1TensorTapePublicCounter.prefixCount N hN [] then\n    selectPrefixes N hN (List.finRange (wireCount N)) [] else [])\n\n/-- Every retained query report is exactly an actual closed original-prefix run. -/\ntheorem search_queryWork_eq (N : ℕ) (hN : 0<N) :\n    (search N hN).queryWork=\n      ((queriedPrefixes N hN).map (fun f => (prefixRun N hN f).clock)).sum := by\n  unfold search queriedPrefixes\n  dsimp only\n  split_ifs <;> simp_all [SemiprimeD1TensorTapePublicCounter.prefixCount,select_queryWork_eq]\n\nend RiemannGaussian.SemiprimeD1TensorTapePublicSearch\n","RiemannGaussian.SemiprimeDenseCarryBoundary":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeDenseRowCarries\nimport Mathlib.Algebra.Polynomial.BigOperators\nimport Mathlib.Data.Finset.Card\nimport Mathlib.NumberTheory.Harmonic.Bounds\n\n/-!\n# Carry boundaries of the actual implicit dense source\n\nAn adjacent-product cancellation retains every floor jump and endpoint;\nchecked unit multipliers preserve the entire public GCD. The public\nnumerator map has fibers of size at most two at prime auxiliary modulus.\nConsequently an explicit boundary-factor construction still has quadratic\ntotal input size, while the initial Euclidean quotient count has a nearly\nlinear bound. Neither result prices a complete recursive detector. The\ninput floor restricts that construction, not all Euclidean circuits,\nimplicit algorithms, or factorization.\n-/\n\nnamespace RiemannGaussian.SemiprimeDenseCarryBoundary\n\nopen SemiprimeQuotientRows SemiprimeDenseRowCoverage SemiprimeDenseRowCarries\nopen scoped BigOperators\nopen Polynomial\n\n/-- A single increment of the retained leading floor carry. -/\ndef carryJump (m u t : ℕ) : ℕ := u*(t+1)/m-u*t/m\n\n/-- The actual implicit curve, including its original orientation. -/\ndef curveValue {G : Type*} [CommGroup G] (A B : G) (m u : ℕ)\n    (negative : Bool) (t : ℕ) : G :=\n  A^t*B^(-((u*t/m+(if negative then 1 else 0) : ℕ) : ℤ))\n\n/-- The public descriptor query is this literal curve. -/\ntheorem progressionValue_curve {G : Type*} [CommGroup G] (m t : ℕ)\n    (negative : Bool) (s : ProgressionSeed G) :\n    progressionValue m t negative s=\n      curveValue s.step s.carryStep m s.slope negative t := rfl\n\n/-- A slope below the modulus has only zero or one carry increments. -/\ntheorem carryJump_le_one {m u t : ℕ} (hu : u<m) : carryJump m u t≤1 := by\n  have h := Nat.add_div_le_div_add_div_add_one (u*t) u m\n  rw [Nat.div_eq_of_lt hu] at h\n  unfold carryJump\n  rw [Nat.mul_succ]\n  omega\n\n/-- The next carry retains its whole increment without truncated subtraction. -/\ntheorem carryJump_add (m u t : ℕ) :\n    u*t/m+carryJump m u t=u*(t+1)/m := by\n  have h : u*t/m≤u*(t+1)/m :=\n    Nat.div_le_div_right (Nat.mul_le_mul_left u (Nat.le_succ t))\n  unfold carryJump\n  omega\n\n/-- The exact query step includes the carry rather than suppressing it. -/\ntheorem curveValue_step {G : Type*} [CommGroup G] (A B : G) (m u t : ℕ)\n    (negative : Bool) :\n    curveValue A B m u negative (t+1)=\n      A*curveValue A B m u negative t*B^(-(carryJump m u t : ℤ)) := by\n  have hk : u*(t+1)/m+(if negative then 1 else 0)=\n      (u*t/m+(if negative then 1 else 0))+carryJump m u t := by\n    have h := carryJump_add m u t\n    omega\n  simp only [curveValue,pow_succ,hk,Nat.cast_add,neg_add,zpow_add]\n  ac_rfl\n\n/-- No-jump edges are the exact factors cancelled by an adjacent shift. -/\ntheorem curveValue_step_no_jump {G : Type*} [CommGroup G] (A B : G)\n    {m u t : ℕ} (negative : Bool) (hjump : carryJump m u t=0) :\n    curveValue A B m u negative (t+1)=A*curveValue A B m u negative t := by\n  rw [curveValue_step,hjump]\n  simp\n\n/-- Total carry variation is the actual endpoint floor. -/\ntheorem carryJump_sum (m u L : ℕ) :\n    ∑ t ∈ Finset.range L, carryJump m u t=u*L/m := by\n  induction L with\n  | zero => simp\n  | succ L ih =>\n    rw [Finset.sum_range_succ,ih]\n    exact carryJump_add m u L\n\n/-- The floor jumps retained by a complete curve's boundary polynomial. -/\ndef jumpSet (m u : ℕ) : Finset ℕ := (Finset.range m).filter (fun t => carryJump m u t=1)\n\n/-- Every slope u<m contributes exactly u boundary factors. -/\ntheorem jumpSet_card {m u : ℕ} (hm : 0<m) (hu : u<m) :\n    (jumpSet m u).card=u := by\n  have hsum : (jumpSet m u).card=∑ t ∈ Finset.range m, carryJump m u t := by\n    simp only [jumpSet,Finset.card_eq_sum_ones,Finset.sum_filter]\n    apply Finset.sum_congr rfl\n    intro t _ht\n    have h := carryJump_le_one (t:=t) hu\n    by_cases he : carryJump m u t=1\n    · simp [he]\n    · have hz : carryJump m u t=0 := by omega\n      simp [hz]\n  rw [hsum,carryJump_sum,Nat.mul_div_cancel _ hm]\n\n/-- The actual seed numerator satisfies its square-residue equation. -/\ntheorem numerator_square {N m j : ℕ} (hm : 0<m) (hj : j.Coprime m) :\n    (representative N m j 1 : ZMod m)*(j : ZMod m)^2=(N : ZMod m) := by\n  have hr := representative_congruence (N:=N) (j:=j) (t:=1) hm\n  have hi := publicInverse_correct hj\n  have hrz := (ZMod.intCast_eq_intCast_iff _ _ m).mpr hr\n  have hiz := (ZMod.intCast_eq_intCast_iff _ _ m).mpr hi\n  push_cast at hrz hiz\n  rw [hrz]\n  calc\n    _=(N : ZMod m)*((j : ZMod m)*(publicInverse m j : ZMod m))^2 := by ring\n    _=_ := by rw [hiz]; ring\n\n/-- A correct public unit prefix ensures the numerator is nonzero modulo m. -/\ntheorem numerator_ne_zero {N m j : ℕ} (hm : 1<m) (hN : m.Coprime N)\n    (hj : j.Coprime m) : (representative N m j 1 : ZMod m)≠0 := by\n  intro hz\n  have hs := numerator_square (N:=N) (by omega) hj\n  rw [hz,zero_mul] at hs\n  have hd := (ZMod.natCast_eq_zero_iff N m).mp hs.symm\n  have he := Nat.dvd_gcd (dvd_refl m) hd\n  rw [hN] at he\n  have hmone := Nat.le_of_dvd (by norm_num : 0<1) he\n  omega\n\n/-- Only nonzero public residues are included in the descriptor cache. -/\ndef residues (m : ℕ) : Finset ℕ := (Finset.range m).erase 0\n\n/-- The descriptor residue range retains its exact positive bounds. -/\ntheorem mem_residues {m j : ℕ} : j∈residues m ↔ 0<j ∧ j<m := by\n  simp only [residues,Finset.mem_erase,Finset.mem_range]\n  omega\n\n/-- Every retained residue is a unit at prime auxiliary modulus. -/\ntheorem residue_coprime {m j : ℕ} (hm : m.Prime) (hj : j∈residues m) :\n    j.Coprime m :=\n  (hm.coprime_iff_not_dvd.mpr\n    (Nat.not_dvd_of_pos_of_lt (mem_residues.mp hj).1 (mem_residues.mp hj).2)).symm\n\n/-- Equal seed numerators have only the two square-root residue aliases. -/\ntheorem numerator_fiber_pair {N m i j : ℕ} (hm : m.Prime) (hN : m.Coprime N)\n    (hi : i∈residues m) (hj : j∈residues m)\n    (he : representative N m i 1=representative N m j 1) : i=j ∨ i+j=m := by\n  let : Fact m.Prime := ⟨hm⟩\n  have his := mem_residues.mp hi\n  have hjs := mem_residues.mp hj\n  have hiq := numerator_square (N:=N) hm.pos (residue_coprime hm hi)\n  have hjq := numerator_square (N:=N) hm.pos (residue_coprime hm hj)\n  rw [he] at hiq\n  have hs : (i : ZMod m)^2=(j : ZMod m)^2 :=\n    mul_left_cancel₀ (numerator_ne_zero hm.one_lt hN (residue_coprime hm hj))\n      (hiq.trans hjq.symm)\n  rcases sq_eq_sq_iff_eq_or_eq_neg.mp hs with hz | hz\n  · have hr := (ZMod.natCast_eq_natCast_iff' i j m).mp hz\n    exact Or.inl (by simpa only [Nat.mod_eq_of_lt his.2,Nat.mod_eq_of_lt hjs.2] using hr)\n  · have hz₀ : ((i+j : ℕ) : ZMod m)=0 := by push_cast; rw [hz]; ring\n    obtain ⟨k,hk⟩ := (ZMod.natCast_eq_zero_iff (i+j) m).mp hz₀\n    have hk₀ : 0<k := by\n      by_contra hn\n      have he₀ : k=0 := by omega\n      rw [he₀,mul_zero] at hk\n      omega\n    have hk₂ : k<2 := by nlinarith [hm.pos]\n    have hk₁ : k=1 := by omega\n    rw [hk₁,mul_one] at hk\n    exact Or.inr hk\n\n/-- Every numerator fiber has size at most two, for the actual public inverse map. -/\ntheorem numerator_fiber_card {N m v : ℕ} (hm : m.Prime) (hN : m.Coprime N) :\n    ((residues m).filter (fun j => representative N m j 1=v)).card≤2 := by\n  classical\n  let S := (residues m).filter (fun j => representative N m j 1=v)\n  change S.card≤2\n  by_cases hS : S.Nonempty\n  · obtain ⟨j,hj⟩ := hS\n    have hs : S⊆({j,m-j} : Finset ℕ) := by\n      intro i hi\n      have hi₀ := Finset.mem_filter.mp hi\n      have hj₀ := Finset.mem_filter.mp hj\n      rcases numerator_fiber_pair hm hN hi₀.1 hj₀.1 (hi₀.2.trans hj₀.2.symm) with he | he\n      · simp [he]\n      · have hei : i=m-j := by omega\n        simp [hei]\n    have hc := (Finset.card_le_card hs).trans (Finset.card_insert_le j {m-j})\n    simpa only [Finset.card_singleton] using hc\n  · rw [Finset.not_nonempty_iff_eq_empty.mp hS]\n    simp\n\n/-- Small numerators occupy at most twice their available value range. -/\ntheorem small_numerator_card {N m K : ℕ} (hm : m.Prime) (hN : m.Coprime N) :\n    ((residues m).filter (fun j => representative N m j 1<K)).card≤2*K := by\n  have he := Finset.sum_card_fiberwise_eq_card_filter (residues m) (Finset.range K)\n    (fun j => representative N m j 1)\n  simp only [Finset.mem_range] at he\n  rw [←he]\n  calc\n    _≤∑ _v ∈ Finset.range K, 2 :=\n      Finset.sum_le_sum (fun _ _ => numerator_fiber_card hm hN)\n    _=2*K := by simp [Nat.mul_comm]\n\n/-- Nonnegative structural costs transfer to the complete slope range\nwith multiplicity at most two. This can also fund amortized upper bounds. -/\ntheorem numerator_weighted_bound {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N)\n    (w : ℕ→ℕ) :\n    (∑ j∈residues m, w (representative N m j 1))≤2*∑ u∈residues m, w u := by\n  have hmap : ∀ j∈residues m, representative N m j 1∈residues m := by\n    intro j hj\n    apply mem_residues.mpr\n    refine ⟨?_,Nat.mod_lt _ hm.pos⟩\n    have hn := numerator_ne_zero hm.one_lt hN (residue_coprime hm hj)\n    by_contra hz\n    have he : representative N m j 1=0 := by omega\n    rw [he,Nat.cast_zero] at hn\n    exact hn rfl\n  rw [←Finset.sum_fiberwise_of_maps_to' hmap w,Finset.mul_sum]\n  apply Finset.sum_le_sum\n  intro u _hu\n  simp only [Finset.sum_const,nsmul_eq_mul]\n  exact Nat.mul_le_mul_right (w u) (numerator_fiber_card hm hN)\n\n/-- Initial Euclidean quotient work is bounded by the complete harmonic\ninteger sum; the quadratic boundary count does not rule out this saving. -/\ntheorem initial_quotient_sum_bound {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N) :\n    (∑ j∈residues m, m/representative N m j 1)≤2*∑ u∈residues m, m/u :=\n  numerator_weighted_bound hm hN (fun u => m/u)\n\n/-- The first Euclidean quotient stage has a nearly linear arithmetic\ncount. Later stages and collision-product evaluation remain separate costs. -/\ntheorem initial_quotient_log_bound {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N) :\n    ((∑ j∈residues m, m/representative N m j 1 : ℕ) : ℝ)≤\n      2*(m : ℝ)*(1+Real.log m) := by\n  have hb : (∑ j∈residues m, ((m/representative N m j 1 : ℕ) : ℝ))≤\n      2*∑ u∈residues m, ((m/u : ℕ) : ℝ) := by\n    exact_mod_cast initial_quotient_sum_bound hm hN\n  have hf : (∑ u∈residues m, ((m/u : ℕ) : ℝ))≤(m : ℝ)*(harmonic m : ℝ) := by\n    calc\n      _≤∑ u∈residues m, (m : ℝ)/(u : ℝ) :=\n        Finset.sum_le_sum (fun _ _ => Nat.cast_div_le)\n      _=(m : ℝ)*∑ u∈residues m, (u : ℝ)⁻¹ := by\n        simp only [div_eq_mul_inv,Finset.mul_sum]\n      _≤(m : ℝ)*∑ u∈Finset.Icc 1 m, (u : ℝ)⁻¹ := by\n        apply mul_le_mul_of_nonneg_left _ (by positivity)\n        apply Finset.sum_le_sum_of_subset_of_nonneg\n        · intro u hu\n          have h := mem_residues.mp hu\n          exact Finset.mem_Icc.mpr ⟨by omega,h.2.le⟩\n        · intro _ _ _\n          positivity\n      _=(m : ℝ)*(harmonic m : ℝ) := by\n        simp only [harmonic_eq_sum_Icc,Rat.cast_sum,Rat.cast_inv,Rat.cast_natCast]\n  have hh := mul_le_mul_of_nonneg_left (harmonic_le_one_add_log m)\n    (by positivity : (0 : ℝ)≤m)\n  push_cast\n  nlinarith only [hb,hf,hh]\n\n/-- The public descriptor range has exactly m-1 residues. -/\ntheorem residues_card {m : ℕ} (hm : 0<m) : (residues m).card=m-1 := by\n  simp only [residues,Finset.card_erase_of_mem (Finset.mem_range.mpr hm),Finset.card_range]\n\n/-- One explicit jump factor per edge of every actual cached curve. -/\ndef boundaryLoad (N m : ℕ) : ℕ :=\n  ∑ j ∈ residues m, (jumpSet m (representative N m j 1)).card\n\n/-- The exact boundary input count is the sum of the actual seed numerators. -/\ntheorem boundaryLoad_eq {N m : ℕ} (hm : 0<m) :\n    boundaryLoad N m=∑ j ∈ residues m, representative N m j 1 := by\n  unfold boundaryLoad\n  apply Finset.sum_congr rfl\n  intro j _hj\n  exact jumpSet_card hm (Nat.mod_lt _ hm)\n\n/-- Explicit boundary construction has a quadratic whole-source input floor.\nThis counts retained factors; it does not lower-bound all implicit algorithms. -/\ntheorem boundaryLoad_quadratic {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N)\n    (hlarge : 8≤m) : m^2≤32*boundaryLoad N m := by\n  let K := m/4\n  let S := (residues m).filter (fun j => K≤representative N m j 1)\n  have hlow := small_numerator_card (K:=K) hm hN\n  have hpart := Finset.card_filter_add_card_filter_not\n    (s:=residues m) (fun j => representative N m j 1<K)\n  simp only [Nat.not_lt] at hpart\n  rw [residues_card hm.pos] at hpart\n  have hcount : m≤4*S.card := by dsimp only [S,K] at *; omega\n  have hK : m≤8*K := by dsimp only [K]; omega\n  have hs : K*S.card≤boundaryLoad N m := by\n    rw [boundaryLoad_eq hm.pos]\n    calc\n      _=∑ _j ∈ S, K := by simp [Nat.mul_comm]\n      _≤∑ j ∈ S, representative N m j 1 :=\n        Finset.sum_le_sum (fun _ hj => (Finset.mem_filter.mp hj).2)\n      _≤∑ j ∈ residues m, representative N m j 1 :=\n        Finset.sum_le_sum_of_subset (Finset.filter_subset _ _)\n  have hmul := Nat.mul_le_mul hK hcount\n  calc\n    m^2=m*m := by ring\n    _≤(8*K)*(4*S.card) := hmul\n    _=32*(K*S.card) := by ring\n    _≤32*boundaryLoad N m := Nat.mul_le_mul_left 32 hs\n\n/-- The initial edge is never a carry boundary for a canonical slope. -/\ntheorem carryJump_zero {m u : ℕ} (hu : u<m) : carryJump m u 0=0 := by\n  simp [carryJump,Nat.div_eq_of_lt hu]\n\n/-- Complete carry boundaries lie among the original positive denominators. -/\ntheorem jumpSet_positive {m u : ℕ} (hu : u<m) :\n    jumpSet m u=(residues m).filter (fun t => carryJump m u t=1) := by\n  ext t\n  by_cases ht : t=0\n  · subst t\n    simp [jumpSet,residues,carryJump_zero hu]\n  · simp [jumpSet,residues,ht]\n\n/-- The original source polynomial retains precisely 1<=t<m. -/\nnoncomputable def sourcePolynomial {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) : R[X] :=\n  ∏ t ∈ residues m, (X-C (curveValue (G:=Rˣ) A B m u negative t : R))\n\n/-- The adjacent shift retains each original root and the public unit A. -/\nnoncomputable def shiftedPolynomial {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) : R[X] :=\n  ∏ t ∈ residues m, (X-C ((A*curveValue A B m u negative t : Rˣ) : R))\n\n/-- Successor roots retain their exact floor carries and endpoint. -/\nnoncomputable def successorPolynomial {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) : R[X] :=\n  ∏ t ∈ residues m, (X-C (curveValue (G:=Rˣ) A B m u negative (t+1) : R))\n\n/-- Before-jump factors required by adjacent-product cancellation. -/\nnoncomputable def beforePolynomial {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) : R[X] :=\n  ∏ t ∈ jumpSet m u, (X-C ((A*curveValue A B m u negative t : Rˣ) : R))\n\n/-- After-jump factors retained on the other side of the same identity. -/\nnoncomputable def afterPolynomial {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) : R[X] :=\n  ∏ t ∈ jumpSet m u, (X-C (curveValue (G:=Rˣ) A B m u negative (t+1) : R))\n\n/-- Boundary products are monic, even over a composite-modulus ring. -/\ntheorem beforePolynomial_monic {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) :\n    (beforePolynomial A B m u negative).Monic :=\n  monic_prod_of_monic _ _ (fun _ _ => monic_X_sub_C _)\n\n/-- The second boundary retains the same monic degree. -/\ntheorem afterPolynomial_monic {R : Type*} [CommRing R]\n    (A B : Rˣ) (m u : ℕ) (negative : Bool) :\n    (afterPolynomial A B m u negative).Monic :=\n  monic_prod_of_monic _ _ (fun _ _ => monic_X_sub_C _)\n\n/-- Explicit before-boundary degree is exactly the public numerator. -/\ntheorem beforePolynomial_natDegree {R : Type*} [CommRing R] [Nontrivial R]\n    (A B : Rˣ) {m u : ℕ} (hm : 0<m) (hu : u<m) (negative : Bool) :\n    (beforePolynomial A B m u negative).natDegree=u := by\n  unfold beforePolynomial\n  rw [natDegree_prod_of_monic _ _ (fun _ _ => monic_X_sub_C _)]\n  simp only [natDegree_X_sub_C,Finset.sum_const,nsmul_eq_mul,Nat.mul_one]\n  exact jumpSet_card hm hu\n\n/-- Explicit after-boundary degree is also exactly the numerator. -/\ntheorem afterPolynomial_natDegree {R : Type*} [CommRing R] [Nontrivial R]\n    (A B : Rˣ) {m u : ℕ} (hm : 0<m) (hu : u<m) (negative : Bool) :\n    (afterPolynomial A B m u negative).natDegree=u := by\n  unfold afterPolynomial\n  rw [natDegree_prod_of_monic _ _ (fun _ _ => monic_X_sub_C _)]\n  simp only [natDegree_X_sub_C,Finset.sum_const,nsmul_eq_mul,Nat.mul_one]\n  exact jumpSet_card hm hu\n\n/-- Products cancel only equal no-jump factors; all boundary factors remain. -/\ntheorem filtered_product_swap {R : Type*} [CommRing R] {ι : Type*}\n    (S : Finset ι) (p : ι→Prop) [DecidablePred p] (f h : ι→R)\n    (he : ∀ t∈S, ¬p t→f t=h t) :\n    (∏ t∈S, f t)*(∏ t∈S.filter p, h t)=\n      (∏ t∈S, h t)*(∏ t∈S.filter p, f t) := by\n  simp only [Finset.prod_filter,←Finset.prod_mul_distrib]\n  apply Finset.prod_congr rfl\n  intro t ht\n  by_cases hp : p t\n  · simp only [ite_eq_left hp,mul_comm]\n  · simp only [ite_eq_right hp,mul_one,he t ht hp]\n\n/-- Exact adjacent shift of the actual floor-filtered product, before\ndiscarding or dividing by any evaluated boundary factor. -/\ntheorem adjacent_boundary_swap {R : Type*} [CommRing R] (A B : Rˣ)\n    {m u : ℕ} (hu : u<m) (negative : Bool) :\n    shiftedPolynomial A B m u negative*afterPolynomial A B m u negative=\n      successorPolynomial A B m u negative*beforePolynomial A B m u negative := by\n  unfold shiftedPolynomial afterPolynomial successorPolynomial beforePolynomial\n  rw [jumpSet_positive hu]\n  apply filtered_product_swap\n  intro t _ht hn\n  have hz : carryJump m u t=0 := by have h := carryJump_le_one (t:=t) hu; omega\n  rw [curveValue_step_no_jump A B negative hz]\n\n/-- Positive source indices reindex to the original descriptor denominator range. -/\ntheorem prod_residues_eq {M : Type*} [CommMonoid M] (f : ℕ→M) {m : ℕ} :\n    (∏ t∈residues m, f t)=∏ r∈Finset.range (m-1), f (r+1) := by\n  have hs : residues m=(Finset.range (m-1)).image (fun r => r+1) := by\n    ext t\n    rw [mem_residues,Finset.mem_image]\n    constructor\n    · intro ht\n      exact ⟨t-1,Finset.mem_range.mpr (by omega),by omega⟩\n    · rintro ⟨r,hr,rfl⟩\n      have hb := Finset.mem_range.mp hr\n      omega\n  rw [hs,Finset.prod_image]\n  intro a _ha b _hb hab\n  change a+1=b+1 at hab\n  omega\n\n/-- A finite adjacent root product telescopes with both endpoints retained. -/\ntheorem consecutive_product_endpoint {R : Type*} [CommRing R]\n    (x : R) (f : ℕ→R) (L : ℕ) :\n    (∏ r∈Finset.range L, (x-f (r+2)))*(x-f 1)=\n      (∏ r∈Finset.range L, (x-f (r+1)))*(x-f (L+1)) := by\n  induction L with\n  | zero => simp\n  | succ L ih =>\n    rw [Finset.prod_range_succ,Finset.prod_range_succ]\n    calc\n      _=((∏ r∈Finset.range L, (x-f (r+2)))*(x-f 1))*(x-f (L+2)) := by ring\n      _=((∏ r∈Finset.range L, (x-f (r+1)))*(x-f (L+1)))*(x-f (L+2)) := by rw [ih]\n      _=_ := by ring\n\n/-- The shifted floor product retains the exact original and final endpoints. -/\ntheorem successor_endpoint {R : Type*} [CommRing R] (A B : Rˣ)\n    {m u : ℕ} (hm : 0<m) (negative : Bool) :\n    successorPolynomial A B m u negative*(X-C (curveValue (G:=Rˣ) A B m u negative 1 : R))=\n      sourcePolynomial A B m u negative*(X-C (curveValue (G:=Rˣ) A B m u negative m : R)) := by\n  unfold successorPolynomial sourcePolynomial\n  rw [prod_residues_eq,prod_residues_eq]\n  have he : m-1+1=m := by omega\n  simpa only [Nat.add_assoc,he] using\n    consecutive_product_endpoint (X : R[X])\n      (fun t => C (curveValue (G:=Rˣ) A B m u negative t : R)) (m-1)\n\n/-- Complete division-free floor-product identity. Evaluated boundary\nand endpoint factors may vanish; the theorem does not cancel those zeros. -/\ntheorem adjacent_polynomial_telescoping {R : Type*} [CommRing R] (A B : Rˣ)\n    {m u : ℕ} (hm : 0<m) (hu : u<m) (negative : Bool) :\n    shiftedPolynomial A B m u negative*afterPolynomial A B m u negative*\n        (X-C (curveValue (G:=Rˣ) A B m u negative 1 : R))=\n      sourcePolynomial A B m u negative*beforePolynomial A B m u negative*\n        (X-C (curveValue (G:=Rˣ) A B m u negative m : R)) := by\n  rw [adjacent_boundary_swap A B hu negative]\n  calc\n    _=(successorPolynomial A B m u negative*\n      (X-C (curveValue (G:=Rˣ) A B m u negative 1 : R)))*beforePolynomial A B m u negative := by ring\n    _=(sourcePolynomial A B m u negative*\n      (X-C (curveValue (G:=Rˣ) A B m u negative m : R)))*beforePolynomial A B m u negative := by\n      rw [successor_endpoint A B hm negative]\n    _=_ := by ring\n\n/-- The shifted polynomial is the original target shift by a public\nunit, with its complete harmless scalar phase made explicit. -/\ntheorem shiftedPolynomial_rephase {R : Type*} [CommRing R] (A B : Rˣ)\n    {m u : ℕ} (hm : 0<m) (negative : Bool) :\n    shiftedPolynomial A B m u negative=\n      C ((A : R)^(m-1))*(sourcePolynomial A B m u negative).comp (C ((A⁻¹ : Rˣ) : R)*X) := by\n  have hi : C (A : R)*C ((A⁻¹ : Rˣ) : R)=(1 : R[X]) := by\n    rw [←C_mul]\n    simp\n  have hf (t : ℕ) : X-C ((A*curveValue A B m u negative t : Rˣ) : R)=\n      C (A : R)*(C ((A⁻¹ : Rˣ) : R)*X-C (curveValue (G:=Rˣ) A B m u negative t : R)) := by\n    simp only [Units.val_mul,C_mul]\n    linear_combination -(X : R[X])*hi\n  simp only [shiftedPolynomial,hf,Finset.prod_mul_distrib,Finset.prod_const,\n    residues_card hm,sourcePolynomial,Polynomial.prod_comp,Polynomial.sub_comp,\n    Polynomial.X_comp,Polynomial.C_comp,map_pow]\n\n/-- Cancelling evaluated boundaries preserves the entire public GCD\nonly after both complete boundary/endpoint multipliers are units.\nThese are explicit checkable premises, not an assumed collision detector. -/\ntheorem checked_boundary_gcd {N m u : ℕ} (A B : (ZMod N)ˣ)\n    (hm : 0<m) (hu : u<m) (negative : Bool) (x : ZMod N)\n    (hleft : IsUnit ((afterPolynomial A B m u negative).eval x*\n      (x-(curveValue (G:=(ZMod N)ˣ) A B m u negative 1 : ZMod N))))\n    (hright : IsUnit ((beforePolynomial A B m u negative).eval x*\n      (x-(curveValue (G:=(ZMod N)ˣ) A B m u negative m : ZMod N)))) :\n    N.gcd ((sourcePolynomial A B m u negative).eval x).val=\n      N.gcd ((sourcePolynomial A B m u negative).eval (((A⁻¹ : (ZMod N)ˣ) : ZMod N)*x)).val := by\n  obtain ⟨v,hv⟩ := hleft\n  obtain ⟨w,hw⟩ := hright\n  have he := congrArg (fun Q : (ZMod N)[X] => Q.eval x)\n    (adjacent_polynomial_telescoping A B hm hu negative)\n  rw [shiftedPolynomial_rephase A B hm negative] at he\n  simp only [eval_mul,eval_comp,eval_sub,eval_X,eval_C] at he\n  have ht : (((A^(m-1)*v : (ZMod N)ˣ) : ZMod N))*\n      (sourcePolynomial A B m u negative).eval (((A⁻¹ : (ZMod N)ˣ) : ZMod N)*x)=\n        (w : ZMod N)*(sourcePolynomial A B m u negative).eval x := by\n    simp only [Units.val_mul,Units.val_pow_eq_pow_val]\n    rw [hv,hw]\n    linear_combination he\n  have hg := congrArg (fun z : ZMod N => N.gcd z.val) ht\n  rw [SemiprimeRHCancellation.unit_mul_gcd_eq,SemiprimeRHCancellation.unit_mul_gcd_eq] at hg\n  exact hg.symm\n\n/-- Actual cached before-boundary degrees have the same quadratic input floor.\nNo minimal circuit or bit-complexity lower bound is claimed. -/\ntheorem public_before_degree_quadratic {R : Type*} [CommRing R] [Nontrivial R]\n    (g : Rˣ) {N m : ℕ} (hm : m.Prime) (hN : m.Coprime N) (hlarge : 8≤m)\n    (negative : Bool) :\n    m^2≤32*∑ j∈residues m,\n      (beforePolynomial (progressionSeed g N m j).step\n        (progressionSeed g N m j).carryStep m\n        (progressionSeed g N m j).slope negative).natDegree := by\n  have he : (∑ j∈residues m,\n      (beforePolynomial (progressionSeed g N m j).step\n        (progressionSeed g N m j).carryStep m\n        (progressionSeed g N m j).slope negative).natDegree)=boundaryLoad N m := by\n    rw [boundaryLoad_eq hm.pos]\n    apply Finset.sum_congr rfl\n    intro j _hj\n    exact beforePolynomial_natDegree _ _ hm.pos (Nat.mod_lt _ hm.pos) negative\n  rw [he]\n  exact boundaryLoad_quadratic hm hN hlarge\n\nend RiemannGaussian.SemiprimeDenseCarryBoundary\n","RiemannGaussian.SemiprimeEncodedRowSelection":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRowSelectionBits\n\n/-! # Original integer rows to the actual physical selector\n\nInteger digit extraction executes explicitly and is reported separately from\nphysical rational-word arithmetic. No encoded matrix or template is an input.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nset_option maxRecDepth 4000\nnamespace RiemannGaussian.SemiprimeEncodedRowSelection\nopen scoped BigOperators\nopen SemiprimeRationalBits SemiprimeBitArithmetic SemiprimeBitIndexClipping\nopen SemiprimeMaterializedSelectionTemporaries\nopen SemiprimeRowSelectionExecution (originalRow selectedIndices)\n\n/-- Paid original integer access. The caller retains responsibility for its\nactual cached-read implementation and representation cost. -/\nstructure IntRun where\n  /-- The actually acquired original integer. -/\n  value : ℤ\n  /-- Retained source-access work. -/\n  work : ℕ\n\n/-- Executed fixed-length scalar digit extraction. -/\nstructure DigitsRun where\n  /-- The actual little-endian output bits. -/\n  bits : List Bool\n  /-- Actual successive division/remainder digit stages. -/\n  stages : ℕ\n  /-- Scalar digit operations and bit-cell/list construction ledger. -/\n  work : ℕ\n\n/-- The data path performs actual remainder/division by two at every digit;\nit does not call a mathematical bit-value inverse or receive the answer. -/\ndef digits : ℕ → ℕ → DigitsRun\n  | 0,_ => ⟨[],0,1⟩\n  | width+1,value =>\n      let next := digits width (value/2)\n      ⟨decide (value%2=1)::next.bits,next.stages+1,next.work+4⟩\n\n/-- Every requested digit cell is allocated, including high zero padding. -/\ntheorem digits_length (width value : ℕ) : (digits width value).bits.length=width := by\n  induction width generalizing value with\n  | zero => rfl\n  | succ width ih => simp [digits,ih]\n\n/-- Exactly width scalar digit stages execute. -/\ntheorem digits_stages (width value : ℕ) : (digits width value).stages=width := by\n  induction width generalizing value with\n  | zero => rfl\n  | succ width ih => simp [digits,ih]\n\n/-- Scalar digit/cell work is acquired from the actual recursive program. -/\ntheorem digits_work (width value : ℕ) : (digits width value).work=4*width+1 := by\n  induction width generalizing value with\n  | zero => rfl\n  | succ width ih => simp only [digits,ih]; omega\n\n/-- The actual remainder Boolean has the exact low-bit natural meaning. -/\ntheorem remainder_bit (value : ℕ) : bitNat (decide (value%2=1))=value%2 := by\n  have h := Nat.mod_lt value (by decide : 0<2)\n  by_cases he : value%2=1\n  · simp [bitNat,he]\n  · have hz : value%2=0 := by omega\n    simp [bitNat,hz]\n\n/-- All ORIGINAL values below the acquired width are represented exactly. -/\ntheorem digits_value (width value : ℕ) (hv : value<2^width) :\n    bitValue (digits width value).bits=value := by\n  induction width generalizing value with\n  | zero =>\n    have hz : value=0 := by simpa using hv\n    subst value\n    rfl\n  | succ width ih =>\n    have hd : value/2<2^width := by\n      apply (Nat.div_lt_iff_lt_mul (by decide : 0<2)).mpr\n      simpa only [pow_succ] using hv\n    simp only [digits,bitValue,remainder_bit,ih _ hd]\n    omega\n\n/-- Physical rational word emitted from one acquired original integer. -/\nstructure IntegerWordRun where\n  /-- Signed magnitude with literal denominator one. -/\n  word : RationalWord\n  /-- Number of scalar digit extraction stages. -/\n  stages : ℕ\n  /-- Scalar digit/sign/cell construction work, NOT a literal integer TM clock. -/\n  work : ℕ\n\n/-- Encode bits+1 digits so the allowed endpoint |z|=2^bits is retained. -/\ndef encode (bits : ℕ) (z : ℤ) : IntegerWordRun :=\n  let magnitude := digits (bits+1) z.natAbs\n  ⟨⟨⟨decide (z<0),magnitude.bits⟩,[true]⟩,magnitude.stages,magnitude.work+3⟩\n\n/-- The acquired scalar encoder reports its actual finite work and stage count. -/\ntheorem encode_work (bits : ℕ) (z : ℤ) :\n    (encode bits z).work=4*(bits+1)+4 ∧ (encode bits z).stages=bits+1 := by\n  constructor\n  · change (digits (bits+1) z.natAbs).work+3=4*(bits+1)+4\n    rw [digits_work]\n  · exact digits_stages _ _\n\n/-- Denominator one makes every emitted word legal, without a fit oracle. -/\ntheorem encode_valid (bits : ℕ) (z : ℤ) : (encode bits z).word.Valid := by\n  change 0<1\n  decide\n\n/-- The emitted signed physical word equals the ORIGINAL integer exactly. -/\ntheorem encode_value (bits : ℕ) (z : ℤ) (hz : |z| ≤ (2^bits : ℕ)) :\n    (encode bits z).word.value=(z : ℚ) := by\n  have hb : z.natAbs<2^(bits+1) := by\n    have h : z.natAbs ≤ 2^bits := by\n      exact_mod_cast (show (z.natAbs : ℤ) ≤ (2^bits : ℕ) by simpa only [Int.natCast_natAbs] using hz)\n    exact h.trans_lt (Nat.pow_lt_pow_right (by decide) (by omega))\n  have he := digits_value (bits+1) z.natAbs hb\n  have hs : (encode bits z).word.numerator.value=z := by\n    change (if decide (z<0)=true then -((bitValue (digits (bits+1) z.natAbs).bits : ℕ) : ℤ)\n      else ((bitValue (digits (bits+1) z.natAbs).bits : ℕ) : ℤ))=z\n    rw [he,Int.natCast_natAbs]\n    by_cases h : z<0\n    · simp [h,abs_of_neg h]\n    · simp [h,abs_of_nonneg (by omega : 0 ≤ z)]\n  change ((encode bits z).word.numerator.value : ℚ)/1=(z : ℚ)\n  rw [hs,div_one]\n\n/-- Initial physical padding fits the selector's DERIVED polynomial width. -/\ntheorem encode_width (n bits : ℕ) (z : ℤ) :\n    Width (encode bits z).word (selectorWidth n bits) := by\n  have h : bits+1 ≤ selectorWidth n bits := by\n    unfold selectorWidth leafBits\n    omega\n  constructor\n  · change (digits (bits+1) z.natAbs).bits.length ≤ selectorWidth n bits\n    rw [digits_length]\n    exact h\n  · change 1 ≤ selectorWidth n bits\n    omega\n\n/-- One retained original-cell access and actual scalar encoding. -/\nstructure CellRun where\n  /-- Actual encoded word payload. -/\n  word : RationalWord\n  /-- The SAME acquired original integer, retained for later selected rows. -/\n  original : ℤ\n  /-- Number of original source accesses. -/\n  calls : ℕ\n  /-- Work returned by the source read. -/\n  sourceWork : ℕ\n  /-- Actual digit/sign/cell work. -/\n  digitWork : ℕ\n\n/-- The source callback is evaluated once before encoding and its report cached. -/\ndef acquireCell (source : IntRun) (bits : ℕ) : CellRun :=\n  let encoded := encode bits source.value\n  ⟨encoded.word,source.value,1,source.work,encoded.work⟩\n\n/-- Complete acquired physical input matrix with separated work categories. -/\nstructure MatrixRun where\n  /-- Cached original word rows. -/\n  words : List (List RationalWord)\n  /-- Original integers from the SAME acquired cell reports. -/\n  integers : List (List ℤ)\n  /-- Exactly one callback per original coefficient. -/\n  sourceCalls : ℕ\n  /-- Retained original read costs. -/\n  sourceWork : ℕ\n  /-- Retained actual scalar digit extraction costs. -/\n  digitWork : ℕ\n  /-- Finite cache allocation/map/fold control allowance. -/\n  cacheWork : ℕ\n\n/-- Materialize every report ONCE, then form all physical rows and work totals. -/\ndef acquire {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) : MatrixRun :=\n  let reports := List.ofFn (fun j : Fin m => List.ofFn (fun v : Fin n => acquireCell (source j v) bits))\n  ⟨reports.map (fun row => row.map CellRun.word),\n    reports.map (fun row => row.map CellRun.original),\n    (reports.map (fun row => (row.map CellRun.calls).sum)).sum,\n    (reports.map (fun row => (row.map CellRun.sourceWork).sum)).sum,\n    (reports.map (fun row => (row.map CellRun.digitWork).sum)).sum,\n    20*m*n+20*m+5⟩\n\n/-- Actual immutable rows have the exact original matrix shape. -/\ntheorem acquire_words {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (acquire source bits).words=List.ofFn (fun j => List.ofFn (fun v => (encode bits (source j v).value).word)) := by\n  simp only [acquire,List.map_ofFn,Function.comp_def,acquireCell]\n\n/-- The original integer cache uses precisely the same once-acquired reports. -/\ntheorem acquire_integers {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (acquire source bits).integers=List.ofFn (fun j => List.ofFn (fun v => (source j v).value)) := by\n  simp only [acquire,List.map_ofFn,Function.comp_def,acquireCell]\n\n/-- Every original coefficient is acquired once, rather than a closure being\nre-evaluated separately for value and work projections. -/\ntheorem acquire_sourceCalls {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (acquire source bits).sourceCalls=m*n := by\n  simp [acquire,List.map_ofFn,Function.comp_def,acquireCell,List.sum_ofFn]\n\n/-- The actual source read costs are retained EXACTLY. -/\ntheorem acquire_sourceWork {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (acquire source bits).sourceWork=∑ j,∑ v,(source j v).work := by\n  simp only [acquire,List.map_ofFn,Function.comp_def,acquireCell,List.sum_ofFn]\n\n/-- All scalar integer-digit extraction has a fixed polynomial exact ledger. -/\ntheorem acquire_digitWork {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (acquire source bits).digitWork=m*n*(4*(bits+1)+4) := by\n  simp only [acquire,List.map_ofFn,Function.comp_def,acquireCell,List.sum_ofFn]\n  simp [encode_work,Nat.mul_assoc]\n\n/-- Actual emitted matrix rows refine ORIGINAL integer rows, with no encoded\nword/template/Fits advice from the caller. -/\ntheorem acquire_refines {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ)\n    (hC : ∀ j v,|(source j v).value| ≤ (2^bits : ℕ)) (j : Fin m) :\n    SemiprimeRowSelectionBits.RowRefines\n      (SemiprimeRowSelectionBitArithmetic.readAt [] (acquire source bits).words j.val).value\n      (originalRow (fun j v => (source j v).value) j) (selectorWidth n bits) := by\n  rw [acquire_words,SemiprimeRowSelectionBitArithmetic.readAt_ofFn]\n  refine ⟨by simp,?_⟩\n  intro v\n  rw [SemiprimeRowSelectionBitArithmetic.readWord,SemiprimeRowSelectionBitArithmetic.readAt_ofFn]\n  exact ⟨encode_valid bits _,encode_width n bits _,encode_value bits _ (hC j v)⟩\n\n/-- Selection output with every acquisition and execution work category kept. -/\nstructure SelectionRun (m : ℕ) where\n  /-- Actual original selected IDs. -/\n  selected : List (Fin m)\n  /-- Original matrix cache, acquired without any second source reads. -/\n  integers : List (List ℤ)\n  /-- Actual source access count. -/\n  sourceCalls : ℕ\n  /-- Source-access work supplied by the actual read program. -/\n  sourceWork : ℕ\n  /-- Scalar integer-digit extraction work. -/\n  digitWork : ℕ\n  /-- Matrix/template/ID allocation and finite traversal work. -/\n  preparationWork : ℕ\n  /-- Physical rational arithmetic and selector list/control work. -/\n  selectorWork : ℕ\n  /-- Sum of all retained work categories. -/\n  work : ℕ\n\n/-- Entire acquired integer-to-selector adapter: actual template, actual row\nIDs, every encoded cell and ONE physical selector call, with no supplied words. -/\ndef select {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) : SelectionRun m :=\n  let acquired := acquire source bits\n  let W := selectorWidth n bits\n  let template := List.replicate W false\n  let ids := List.finRange m\n  let out := SemiprimeRowSelectionBits.run n template acquired.words ids\n  let preparation := acquired.cacheWork+(W+1)+(3*m+1)+3\n  ⟨out.state.selected,acquired.integers,acquired.sourceCalls,acquired.sourceWork,acquired.digitWork,\n    preparation,out.clock,acquired.sourceWork+acquired.digitWork+preparation+out.clock⟩\n\n/-- The acquired adapter selects exactly the actual old original integer rows. -/\ntheorem select_correct {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ)\n    (hC : ∀ j v,|(source j v).value| ≤ (2^bits : ℕ)) :\n    (select source bits).selected=selectedIndices (fun j v => (source j v).value) := by\n  exact SemiprimeRowSelectionBits.run_selected_eq _ (List.finRange m) bits hC\n    (List.replicate (selectorWidth n bits) false) (by simp) (acquire source bits).words\n    (by simpa using acquire_refines source bits hC)\n\n/-- The adapter returns its original integer cache for selected-row assembly,\nso the caller need not re-read an expensive source after choosing IDs. -/\ntheorem select_integers {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (select source bits).integers=List.ofFn (fun j => List.ofFn (fun v => (source j v).value)) :=\n  acquire_integers source bits\n\n/-- Original callback accesses are exposed exactly at the public adapter. -/\ntheorem select_sourceCalls {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (select source bits).sourceCalls=m*n := acquire_sourceCalls source bits\n\n/-- Exact retained source-read work at the public selector adapter. -/\ntheorem select_sourceWork {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (select source bits).sourceWork=∑ j,∑ v,(source j v).work := acquire_sourceWork source bits\n\n/-- Exact digit-extraction ledger, separately exposed from physical arithmetic. -/\ntheorem select_digitWork {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (select source bits).digitWork=m*n*(4*(bits+1)+4) := acquire_digitWork source bits\n\n/-- Matrix cache, actual template and actual row-ID construction are attached. -/\ntheorem select_preparationWork {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits : ℕ) :\n    (select source bits).preparationWork=\n      (20*m*n+20*m+5)+(selectorWidth n bits+1)+(3*m+1)+3 := rfl\n\n/-- Fixed polynomial acquisition/physical-selector ledger after a caller's\noriginal cached-read bound. Its scalar-digit and memory model remains explicit. -/\ndef budget (m n bits readBudget : ℕ) : ℕ :=\n  m*n*readBudget+m*n*(4*(bits+1)+4)+(20*m*n+20*m+5)+\n    (selectorWidth n bits+1)+(3*m+1)+3+\n    SemiprimeRowSelectionBits.runBudget m n (selectorWidth n bits) m\n\n/-- Complete attached work bound: source reads, digit operations, actual cache,\ntemplate/IDs and the ENTIRE physical selector. No output/state/Fits oracle. -/\ntheorem select_work {m n : ℕ} (source : Fin m → Fin n → IntRun) (bits readBudget : ℕ)\n    (hC : ∀ j v,|(source j v).value| ≤ (2^bits : ℕ))\n    (hread : ∀ j v,(source j v).work ≤ readBudget) :\n    (select source bits).work ≤ budget m n bits readBudget := by\n  have hs := Finset.sum_le_sum (fun j (_ : j∈(Finset.univ : Finset (Fin m))) =>\n    Finset.sum_le_sum (fun v (_ : v∈(Finset.univ : Finset (Fin n))) => hread j v))\n  have hshape : (acquire source bits).words.length ≤ m := by rw [acquire_words]; simp\n  have hp := SemiprimeRowSelectionBits.run_clock (fun j v => (source j v).value) (List.finRange m)\n    bits hC (List.replicate (selectorWidth n bits) false) (by simp)\n    (acquire source bits).words hshape (by simpa using acquire_refines source bits hC)\n  rw [List.length_finRange] at hp\n  simp only [List.length_replicate] at hp\n  simp only [Finset.sum_const,Finset.card_univ,Fintype.card_fin,nsmul_eq_mul,Nat.cast_id] at hs\n  have hs' : (∑ j,∑ v,(source j v).work) ≤ m*n*readBudget := by\n    simpa only [Nat.mul_assoc] using hs\n  unfold select budget\n  dsimp only\n  rw [acquire_sourceWork,acquire_digitWork]\n  change (∑ j,∑ v,(source j v).work)+m*n*(4*(bits+1)+4)+\n    ((20*m*n+20*m+5)+(selectorWidth n bits+1)+(3*m+1)+3)+_ ≤ _\n  omega\n\n/-- Plain original integer matrix wrapper: one logical source access per cell.\nA caller needing physical read costs should use select with its actual IntRun. -/\ndef selectMatrix {m n : ℕ} (C : Fin m → Fin n → ℤ) (bits : ℕ) : SelectionRun m :=\n  select (fun j v => ⟨C j v,1⟩) bits\n\n/-- Plain integer input interface requires no pre-encoded data. -/\ntheorem selectMatrix_correct {m n : ℕ} (C : Fin m → Fin n → ℤ) (bits : ℕ)\n    (hC : ∀ j v,|C j v| ≤ (2^bits : ℕ)) :\n    (selectMatrix C bits).selected=selectedIndices C := select_correct _ _ hC\n\n/-- Plain-matrix logical-read wrapper inherits the full acquired ledger; its\none-unit read is explicitly not a physical lookup-cost theorem. -/\ntheorem selectMatrix_work {m n : ℕ} (C : Fin m → Fin n → ℤ) (bits : ℕ)\n    (hC : ∀ j v,|C j v| ≤ (2^bits : ℕ)) :\n    (selectMatrix C bits).work ≤ budget m n bits 1 :=\n  select_work _ bits 1 hC (by intro j v; rfl)\n\nend RiemannGaussian.SemiprimeEncodedRowSelection\n","RiemannGaussian.SemiprimeFastDickson":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeLongPeriodExtraction\nimport Mathlib.FieldTheory.Finite.Basic\nimport Mathlib.FieldTheory.IsAlgClosed.AlgebraicClosure\n\n/-!\n# Cheap high-degree folds and their exact collision limitation\n\nBinary doubling evaluates a Dickson fold without expanding its polynomial.\nA degree coprime to the relevant trace-lift exponent preserves collisions.\nIn particular, degree p*q cannot create collisions in the smaller prime\nfield. These are exact algebraic statements, not a universal factoring\nalgorithm or a proof of its bit complexity. This optional side module is\nchecked in the ordinary library; numerical probes remain optional.\n-/\n\nnamespace RiemannGaussian.SemiprimeFastDickson\n\nopen SemiprimeLongPeriodExtraction\n\n/-- The even binary update, over a commutative ring including Z/NZ. -/\ntheorem dickson_double_eval {R : Type*} [CommRing R] (x : R) (k : ℕ) :\n    (Polynomial.dickson 1 (1 : R) (2*k)).eval x =\n      ((Polynomial.dickson 1 (1 : R) k).eval x)^2-2 := by\n  rw [Polynomial.dickson_one_one_mul, Polynomial.eval_comp]\n  simp\n  ring\n\n/-- The odd update uses the two adjacent values and the original x. -/\ntheorem dickson_double_add_one_eval {R : Type*} [CommRing R] (x : R) (k : ℕ) :\n    (Polynomial.dickson 1 (1 : R) (2*k+1)).eval x =\n      (Polynomial.dickson 1 (1 : R) k).eval x *\n        (Polynomial.dickson 1 (1 : R) (k+1)).eval x-x := by\n  have h := congrArg (fun P : Polynomial R => P.eval x)\n    (Polynomial.Chebyshev.C_mul_C R (k : ℤ) ((k+1 : ℕ) : ℤ))\n  have ha : (k : ℤ)+((k+1 : ℕ) : ℤ) = ((2*k+1 : ℕ) : ℤ) := by omega\n  have hs : (k : ℤ)-((k+1 : ℕ) : ℤ) = -1 := by omega\n  rw [ha, hs, Polynomial.Chebyshev.C_neg_one] at h\n  simp only [Polynomial.eval_mul, Polynomial.eval_add, Polynomial.eval_X,\n    ← Polynomial.dickson_one_one_eq_chebyshev_C] at h\n  linear_combination -h\n\n/-- Little-endian degree bits; no polynomial coefficient list is built. -/\ndef degreeOfBits : List Bool → ℕ\n  | [] => 0\n  | bit :: tail => 2*degreeOfBits tail + if bit then 1 else 0\n\n/-- The exact binary circuit, valid over composite rings as well. -/\ndef dicksonOfBits {R : Type*} [CommRing R] (x : R) : List Bool → R × R\n  | [] => (2, x)\n  | bit :: tail =>\n    let pair := dicksonOfBits x tail\n    if bit then (pair.1*pair.2-x, pair.2^2-2)\n    else (pair.1^2-2, pair.1*pair.2-x)\n\n/-- Both outputs of the small binary circuit are genuine Dickson values. -/\ntheorem dicksonOfBits_correct {R : Type*} [CommRing R] (x : R) (bits : List Bool) :\n    dicksonOfBits x bits =\n      ((Polynomial.dickson 1 (1 : R) (degreeOfBits bits)).eval x,\n       (Polynomial.dickson 1 (1 : R) (degreeOfBits bits+1)).eval x) := by\n  induction bits with\n  | nil => simp [dicksonOfBits, degreeOfBits]; ring\n  | cons bit tail ih =>\n    cases bit <;> simp only [dicksonOfBits, ih, degreeOfBits,\n      Bool.false_eq_true, ite_false, ite_true, add_zero]\n    · apply Prod.ext\n      · exact (dickson_double_eval x _).symm\n      · exact (dickson_double_add_one_eval x _).symm\n    · apply Prod.ext\n      · exact (dickson_double_add_one_eval x _).symm\n      · convert (dickson_double_eval x (degreeOfBits tail+1)).symm using 1\n\nprivate theorem pow_eq_one_of_coprime {F : Type*} [Field F]\n    {x : F} {M d : ℕ} (hM : x^M = 1) (hd : x^d = 1)\n    (hc : M.Coprime d) : x = 1 := by\n  have ho : orderOf x ∣ 1 := by\n    have hh := Nat.dvd_gcd (orderOf_dvd_of_pow_eq_one hM)\n      (orderOf_dvd_of_pow_eq_one hd)\n    simpa [hc.gcd_eq_one] using hh\n  exact orderOf_eq_one_iff.mp (Nat.eq_one_of_dvd_one ho)\n\n/-- Large formal degree alone supplies no folding gain on these lifts. -/\ntheorem dickson_collision_iff_of_coprime {F : Type*} [Field F]\n    {x y : F} {M d : ℕ} (hx : x ≠ 0) (hy : y ≠ 0)\n    (hxM : x^M = 1) (hyM : y^M = 1) (hc : M.Coprime d) :\n    (Polynomial.dickson 1 (1 : F) d).eval (x+x⁻¹) =\n      (Polynomial.dickson 1 (1 : F) d).eval (y+y⁻¹) ↔\n    x+x⁻¹ = y+y⁻¹ := by\n  rw [dickson_collision_lift hx hy, reciprocal_trace_eq_iff hx hy]\n  constructor\n  · rintro (hr | hp)\n    · left\n      have hm : (x/y)^M = 1 := by rw [div_pow, hxM, hyM, div_one]\n      exact (div_eq_one_iff_eq hy).mp (pow_eq_one_of_coprime hm hr hc)\n    · right\n      have hm : (x*y)^M = 1 := by rw [mul_pow, hxM, hyM, mul_one]\n      exact pow_eq_one_of_coprime hm hp hc\n  · rintro (rfl | hp)\n    · left\n      simp [hx]\n    · right\n      simp [hp]\n\nprivate theorem pow_eq_one_gcd_iff {F : Type*} [Field F]\n    {x : F} {M d : ℕ} (hM : x^M = 1) : x^d = 1 ↔ x^(M.gcd d) = 1 := by\n  constructor\n  · intro hd\n    exact orderOf_dvd_iff_pow_eq_one.mp\n      (Nat.dvd_gcd (orderOf_dvd_of_pow_eq_one hM) (orderOf_dvd_of_pow_eq_one hd))\n  · intro hg\n    exact orderOf_dvd_iff_pow_eq_one.mp\n      ((orderOf_dvd_of_pow_eq_one hg).trans (Nat.gcd_dvd_right M d))\n\n/-- Exact fibre compression: only the degree's GCD with the lift period\nmatters, even if the original degree has many more bits. -/\ntheorem dickson_collision_gcd {F : Type*} [Field F]\n    {x y : F} {M : ℕ} (hx : x ≠ 0) (hy : y ≠ 0)\n    (hxM : x^M = 1) (hyM : y^M = 1) (d : ℕ) :\n    (Polynomial.dickson 1 (1 : F) d).eval (x+x⁻¹) =\n      (Polynomial.dickson 1 (1 : F) d).eval (y+y⁻¹) ↔\n    (Polynomial.dickson 1 (1 : F) (M.gcd d)).eval (x+x⁻¹) =\n      (Polynomial.dickson 1 (1 : F) (M.gcd d)).eval (y+y⁻¹) := by\n  rw [dickson_collision_lift hx hy, dickson_collision_lift hx hy]\n  have hdiv : (x/y)^M = 1 := by rw [div_pow, hxM, hyM, div_one]\n  have hmul : (x*y)^M = 1 := by rw [mul_pow, hxM, hyM, mul_one]\n  rw [pow_eq_one_gcd_iff hdiv, pow_eq_one_gcd_iff hmul]\n\nprivate theorem exists_reciprocal_lift {F : Type*} [Field F] [IsAlgClosed F]\n    (x : F) : ∃ a : F, a ≠ 0 ∧ a+a⁻¹ = x := by\n  let P : Polynomial F := Polynomial.X^2-Polynomial.C x*Polynomial.X+1\n  have hdeg : P.degree ≠ 0 := by\n    have hd : P.natDegree = 2 := by dsimp [P]; compute_degree!\n    intro he\n    have hn : P.natDegree = 0 := Polynomial.natDegree_eq_of_degree_eq_some he\n    omega\n  obtain ⟨a, ha⟩ := IsAlgClosed.exists_root P hdeg\n  have he : a^2-x*a+1 = 0 := by simpa [P, Polynomial.IsRoot] using ha\n  have hne : a ≠ 0 := by intro h; simp [h] at he\n  refine ⟨a, hne, ?_⟩\n  apply (mul_left_inj' hne).mp\n  field_simp\n  linear_combination he\n\nprivate theorem reciprocal_lift_period {p : ℕ} [Fact p.Prime]\n    {F : Type*} [Field F] [CharP F p] (f : ZMod p →+* F)\n    {a : F} (ha : a ≠ 0) (x : ZMod p) (ht : a+a⁻¹ = f x) :\n    a^(p^2-1) = 1 := by\n  have hf : (a+a⁻¹)^p = a+a⁻¹ := by\n    rw [ht, ← map_pow, ZMod.pow_card]\n  have htr : a^p+(a^p)⁻¹ = a+a⁻¹ := by\n    simpa only [add_pow_char, inv_pow] using hf\n  have hsplit := (reciprocal_trace_eq_iff (pow_ne_zero p ha) ha).mp htr\n  have hpp : a^(p^2) = a := by\n    rw [pow_two, pow_mul]\n    rcases hsplit with he | he\n    · rw [he, he]\n    · have he' : a^p = a⁻¹ := by\n        exact (mul_eq_one_iff_eq_inv₀ ha).mp he\n      rw [he', inv_pow, he', inv_inv]\n  have hp : 1 ≤ p^2 := by have := (Fact.out : p.Prime).two_le; nlinarith\n  have hh : a^(p^2-1)*a = a := by\n    rw [← pow_succ, Nat.sub_add_cancel hp, hpp]\n  exact (mul_left_inj' ha).mp (by simpa using hh)\n\nprivate theorem map_dickson_eval {F K : Type*} [CommRing F] [CommRing K]\n    (f : F →+* K) (x : F) (d : ℕ) :\n    f ((Polynomial.dickson 1 (1 : F) d).eval x) =\n      (Polynomial.dickson 1 (1 : K) d).eval (f x) := by\n  have hm : (Polynomial.dickson 1 (1 : F) d).map f =\n      Polynomial.dickson 1 (1 : K) d := by\n    simpa using Polynomial.map_dickson (k := 1) (a := (1 : F)) f d\n  rw [← hm, Polynomial.eval_map_apply]\n\n/-- Every prime-field collision partition equals the much smaller\ndegree GCD partition. The hidden GCD is explanatory, not a public oracle. -/\ntheorem dickson_prime_field_collision_gcd {p : ℕ} [Fact p.Prime]\n    (x y : ZMod p) (d : ℕ) :\n    (Polynomial.dickson 1 (1 : ZMod p) d).eval x =\n      (Polynomial.dickson 1 (1 : ZMod p) d).eval y ↔\n    (Polynomial.dickson 1 (1 : ZMod p) ((p^2-1).gcd d)).eval x =\n      (Polynomial.dickson 1 (1 : ZMod p) ((p^2-1).gcd d)).eval y := by\n  let F := AlgebraicClosure (ZMod p)\n  let f : ZMod p →+* F := algebraMap (ZMod p) F\n  obtain ⟨a, ha, hat⟩ := exists_reciprocal_lift (f x)\n  obtain ⟨b, hb, hbt⟩ := exists_reciprocal_lift (f y)\n  have hh := dickson_collision_gcd ha hb\n    (reciprocal_lift_period f ha x hat) (reciprocal_lift_period f hb y hbt) d\n  rw [hat, hbt, ← map_dickson_eval, ← map_dickson_eval,\n    ← map_dickson_eval, ← map_dickson_eval] at hh\n  simpa only [(RingHom.injective f).eq_iff] using hh\n\n/-- Full prime-field injectivity, with its exact group-period condition. -/\ntheorem dickson_injective_prime_field {p d : ℕ} [Fact p.Prime]\n    (hc : (p^2-1).Coprime d) :\n    Function.Injective (fun x : ZMod p =>\n      (Polynomial.dickson 1 (1 : ZMod p) d).eval x) := by\n  let F := AlgebraicClosure (ZMod p)\n  let f : ZMod p →+* F := algebraMap (ZMod p) F\n  intro x y hxy\n  obtain ⟨a, ha, hat⟩ := exists_reciprocal_lift (f x)\n  obtain ⟨b, hb, hbt⟩ := exists_reciprocal_lift (f y)\n  have hfx : (Polynomial.dickson 1 (1 : F) d).eval (f x) =\n      (Polynomial.dickson 1 (1 : F) d).eval (f y) := by\n    have hh := congrArg f hxy\n    have hm : (Polynomial.dickson 1 (1 : ZMod p) d).map f =\n        Polynomial.dickson 1 (1 : F) d := by\n      simpa using Polynomial.map_dickson (k := 1) (a := (1 : ZMod p)) f d\n    rw [← hm, Polynomial.eval_map_apply, Polynomial.eval_map_apply]\n    exact hh\n  rw [← hat, ← hbt] at hfx\n  have ht := (dickson_collision_iff_of_coprime ha hb\n    (reciprocal_lift_period f ha x hat) (reciprocal_lift_period f hb y hbt) hc).mp hfx\n  rw [hat, hbt] at ht\n  exact (RingHom.injective f) ht\n\n/-- For ordered odd primes, N is coprime to the smaller trace exponent. -/\ntheorem semiprime_degree_coprime {p q : ℕ} (hp : p.Prime) (hq : q.Prime)\n    (hpodd : 2 < p) (hpq : p < q) : (p^2-1).Coprime (p*q) := by\n  have hp1 : (p^2-1).Coprime p := by\n    apply Nat.Coprime.symm\n    apply hp.coprime_iff_not_dvd.mpr\n    intro hd\n    have hs : p^2-1+1 = p^2 := Nat.sub_add_cancel (by nlinarith)\n    have hd' : p ∣ p^2-1+1 := by rw [hs]; exact dvd_pow_self p (by decide)\n    have hone : p ∣ 1 := (Nat.dvd_add_iff_right hd).mpr hd'\n    exact hp.not_dvd_one hone\n  have hqp : p+1 < q := by\n    have hpo := hp.mod_two_eq_one_iff_ne_two.mpr (by omega)\n    have hqo := hq.mod_two_eq_one_iff_ne_two.mpr (by omega)\n    omega\n  have he : p^2-1 = (p-1)*(p+1) := by\n    have hs : p^2-1+1 = p^2 := Nat.sub_add_cancel (by nlinarith)\n    have hs' : p-1+1 = p := Nat.sub_add_cancel (by omega)\n    nlinarith\n  have hq1 : (p^2-1).Coprime q := (hq.coprime_iff_not_dvd.mpr (by\n    rw [he]\n    intro hd\n    rcases hq.dvd_mul.mp hd with h | h\n    · exact (Nat.not_dvd_of_pos_of_lt (by omega) (by omega)) h\n    · exact (Nat.not_dvd_of_pos_of_lt (by omega) hqp) h)).symm\n  exact Nat.coprime_mul_iff_right.mpr ⟨hp1, hq1⟩\n\n/-- The proposed cheap degree-N map cannot reveal a new smaller-prime\ncollision for ANY ordered odd semiprime, not merely the tested samples. -/\ntheorem semiprime_degree_no_new_smaller_collision {p q : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpodd : 2 < p) (hpq : p < q)\n    (x y : ZMod p) :\n    (Polynomial.dickson 1 (1 : ZMod p) (p*q)).eval x =\n      (Polynomial.dickson 1 (1 : ZMod p) (p*q)).eval y ↔ x = y := by\n  have : Fact p.Prime := ⟨hp⟩\n  exact (dickson_injective_prime_field (semiprime_degree_coprime hp hq hpodd hpq)).eq_iff\n\n/-- The concrete B-by-B integer cover still misses the smaller prime\nwhen it exceeds B²; evaluating degree N adds no longer-period access. -/\ntheorem semiprime_degree_short_grid_no_collision {p q B i j : ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpodd : 2 < p) (hpq : p < q)\n    (hsize : B^2 < p) (hi : i < B) (hj : 1 ≤ j) (hjB : j ≤ B) :\n    (Polynomial.dickson 1 (1 : ZMod p) (p*q)).eval (i : ZMod p) ≠\n      (Polynomial.dickson 1 (1 : ZMod p) (p*q)).eval ((B*j : ℕ) : ZMod p) := by\n  intro he\n  have hv := congrArg ZMod.val\n    ((semiprime_degree_no_new_smaller_collision hp hq hpodd hpq _ _).mp he)\n  have hB : 0 < B := by omega\n  have hip : i < p := by nlinarith\n  have hjp : B*j < p := by nlinarith\n  simp only [ZMod.val_natCast] at hv\n  rw [Nat.mod_eq_of_lt hip, Nat.mod_eq_of_lt hjp] at hv\n  nlinarith\n\n/-- Finite GCD replay for a nearby-degree recovery missed by the direct\nlinear, degree-six, and degree-twenty-four batches. Polynomial evaluation\nand universal coverage remain distinct from this divisor certificate. -/\ntheorem fresh_nearby_degree_signal :\n    Nat.gcd 171033372116459 95291626633620 = 12108181 ∧\n      (1 : ℕ) < 12108181 ∧ 12108181 < 171033372116459 ∧\n      12108181 ∣ (171033372116459 : ℕ) := by\n  norm_num\n\nend RiemannGaussian.SemiprimeFastDickson\n","RiemannGaussian.SemiprimeGuardedTrace":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeTraceRows\n\n/-!\n# Guarded inverse-orbit compression of retained rows\n\nThe executable representative scan checks one original difference at every\nwhole-trace match. Its accepted rows retain one global inverse orientation,\nand its representatives have distinct whole traces. Raw sign endpoints\nprecede this scan and the one-polynomial derivative stage follows it.\n\nThis module prices GCD queries only. The association-list specification does\nnot supply a fast deterministic table, a bit-machine refinement, paid row\nconstruction, or the missing universal sixth-root collision coverage.\n-/\n\nnamespace RiemannGaussian.SemiprimeGuardedTrace\n\nopen SemiprimeCartesianCompletion SemiprimeRowDerivative SemiprimeTraceRows\n\n/-- A checked trace match either returns a proper factor or retains one\noriginal representative. The richer input list remains available. -/\ndef guardTraces {n : ℕ} : List (ZMod n)ˣ → List (ZMod n)ˣ → ℕ ⊕ List (ZMod n)ˣ\n  | [], reps => .inr reps\n  | x::tail, reps =>\n    match reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none => guardTraces tail (x::reps)\n    | some y =>\n      match SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | some d => .inl d\n      | none => guardTraces tail reps\n\n/-- Every checked whole-trace match uses one GCD; lookup costs are separate. -/\ndef guardGcdCount {n : ℕ} : List (ZMod n)ˣ → List (ZMod n)ˣ → ℕ\n  | [], _ => 0\n  | x::tail, reps =>\n    match reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none => guardGcdCount tail (x::reps)\n    | some y => 1+\n      match SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | some _ => 0\n      | none => guardGcdCount tail reps\n\ntheorem guardTraces_sound {n d : ℕ} (rows reps : List (ZMod n)ˣ)\n    (hd : guardTraces rows reps=.inl d) : SemiprimeGroupSelection.ProperDivisor n d := by\n  induction rows generalizing reps with\n  | nil => simp [guardTraces] at hd\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none => exact ih (x::reps) (by simpa [guardTraces,hf] using hd)\n    | some y =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | none => exact ih reps (by simpa [guardTraces,hf,hc] using hd)\n      | some d' =>\n        have he : d'=d := by simpa [guardTraces,hf,hc] using hd\n        subst d'\n        exact SemiprimeGroupSelection.checkedSignal_sound hc\n\ntheorem guardGcdCount_le {n : ℕ} (rows reps : List (ZMod n)ˣ) :\n    guardGcdCount rows reps≤rows.length := by\n  induction rows generalizing reps with\n  | nil => simp [guardGcdCount]\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none => simpa [guardGcdCount,hf] using (ih (x::reps)).trans (Nat.le_succ _)\n    | some y =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | none => simpa [guardGcdCount,hf,hc,Nat.add_comm] using Nat.succ_le_succ (ih reps)\n      | some d => simp [guardGcdCount,hf,hc]\n\ntheorem guardTraces_length {n : ℕ} (rows reps out : List (ZMod n)ˣ)\n    (ho : guardTraces rows reps=.inr out) : out.length≤rows.length+reps.length := by\n  induction rows generalizing reps with\n  | nil =>\n    have he : reps=out := by simpa [guardTraces] using ho\n    simp [he]\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none =>\n      have hh := ih (x::reps) (by simpa [guardTraces,hf] using ho)\n      simpa [Nat.add_assoc,Nat.add_comm,Nat.add_left_comm] using hh\n    | some y =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | none =>\n        have hh := ih reps (by simpa [guardTraces,hf,hc] using ho)\n        simp only [List.length_cons]\n        omega\n      | some d => simp [guardTraces,hf,hc] at ho\n\n/-- Representatives already retained by the scan are never discarded. -/\ntheorem guardTraces_preserves_old {n : ℕ} (rows reps out : List (ZMod n)ˣ)\n    (ho : guardTraces rows reps=.inr out) : ∀ x∈reps, x∈out := by\n  induction rows generalizing reps with\n  | nil =>\n    have he : reps=out := by simpa [guardTraces] using ho\n    simp [he]\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none =>\n      have hh := ih (x::reps) (by simpa [guardTraces,hf] using ho)\n      exact fun y hy => hh y (List.mem_cons_of_mem x hy)\n    | some y =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | none => exact ih reps (by simpa [guardTraces,hf,hc] using ho)\n      | some d => simp [guardTraces,hf,hc] at ho\n\n/-- Every accepted original row equals a retained unit or its global\ninverse. The guard theorem discharges this orientation information. -/\ntheorem guardTraces_orientation {n : ℕ} [NeZero n]\n    (rows reps out : List (ZMod n)ˣ) (ho : guardTraces rows reps=.inr out) :\n    ∀ x∈rows, ∃ r∈out, x=r ∨ x=r⁻¹ := by\n  induction rows generalizing reps with\n  | nil => simp\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none =>\n      have hh : guardTraces tail (x::reps)=.inr out := by simpa [guardTraces,hf] using ho\n      intro y hy\n      rcases List.mem_cons.mp hy with hxy|hy\n      · subst y\n        exact ⟨x,guardTraces_preserves_old tail (x::reps) out hh x (by simp),Or.inl rfl⟩\n      · exact ih (x::reps) hh y hy\n    | some r =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(r : ZMod n)).val with\n      | none =>\n        have hh : guardTraces tail reps=.inr out := by simpa [guardTraces,hf,hc] using ho\n        have hr := List.mem_of_find?_eq_some hf\n        have ht : traceValue x=traceValue r := of_decide_eq_true\n          (List.find?_some (p:=fun y => decide (traceValue x=traceValue y)) hf)\n        intro y hy\n        rcases List.mem_cons.mp hy with hxy|hy\n        · subst y\n          exact ⟨r,guardTraces_preserves_old tail reps out hh r hr,\n            global_trace_guard_none_orientation x r ht hc⟩\n        · exact ih reps hh y hy\n      | some d => simp [guardTraces,hf,hc] at ho\n\n/-- Every representative comes from the richer original carrier. -/\ntheorem guardTraces_reps_subset {n : ℕ} (rows reps out : List (ZMod n)ˣ)\n    (ho : guardTraces rows reps=.inr out) : ∀ x∈out, x∈rows ∨ x∈reps := by\n  induction rows generalizing reps with\n  | nil =>\n    have he : reps=out := by simpa [guardTraces] using ho\n    simp [he]\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none =>\n      have hh := ih (x::reps) (by simpa [guardTraces,hf] using ho)\n      intro y hy\n      rcases hh y hy with ht|hr\n      · exact Or.inl (List.mem_cons_of_mem x ht)\n      · rcases List.mem_cons.mp hr with rfl|hr\n        · exact Or.inl (by simp)\n        · exact Or.inr hr\n    | some y =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | none =>\n        have hh := ih reps (by simpa [guardTraces,hf,hc] using ho)\n        exact fun z hz => (hh z hz).imp (List.mem_cons_of_mem x) id\n      | some d => simp [guardTraces,hf,hc] at ho\n\n/-- The scalar trace is injective on retained representatives only. -/\ndef TraceSeparated {n : ℕ} (reps : List (ZMod n)ˣ) : Prop :=\n  ∀ x∈reps, ∀ y∈reps, traceValue x=traceValue y → x=y\n\nprivate theorem separated_cons {n : ℕ} {x : (ZMod n)ˣ} {reps : List (ZMod n)ˣ}\n    (hs : TraceSeparated reps) (hx : ∀ y∈reps, traceValue x≠traceValue y) :\n    TraceSeparated (x::reps) := by\n  intro a ha b hb ht\n  rcases List.mem_cons.mp ha with ha|ha\n  · subst a\n    rcases List.mem_cons.mp hb with hb|hb\n    · exact hb.symm\n    · exact (hx b hb ht).elim\n  · rcases List.mem_cons.mp hb with hb|hb\n    · subst b\n      exact (hx a ha ht.symm).elim\n    · exact hs a ha b hb ht\n\n/-- A new representative is inserted only after its whole trace fails to\nmatch every retained one, so successful compression preserves separation. -/\ntheorem guardTraces_separated {n : ℕ} (rows reps out : List (ZMod n)ˣ)\n    (hs : TraceSeparated reps) (ho : guardTraces rows reps=.inr out) :\n    TraceSeparated out := by\n  induction rows generalizing reps with\n  | nil =>\n    have he : reps=out := by simpa [guardTraces] using ho\n    exact he ▸ hs\n  | cons x tail ih =>\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none =>\n      have hx : ∀ y∈reps, traceValue x≠traceValue y := by\n        intro y hy ht\n        have hn := (List.find?_eq_none.mp hf) y hy\n        simp [ht] at hn\n      exact ih (x::reps) (separated_cons hs hx) (by simpa [guardTraces,hf] using ho)\n    | some y =>\n      cases hc : SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val with\n      | none => exact ih reps hs (by simpa [guardTraces,hf,hc] using ho)\n      | some d => simp [guardTraces,hf,hc] at ho\n\n/-- Raw endpoints keep both original sign channels before folding. -/\ndef endpointLeaves {n : ℕ} (rows : List (ZMod n)ˣ) : List ℕ :=\n  rows.flatMap fun (x : (ZMod n)ˣ) => [((x : ZMod n)-1).val,((x : ZMod n)+1).val]\n\ntheorem endpointLeaves_length {n : ℕ} (rows : List (ZMod n)ˣ) :\n    (endpointLeaves rows).length=2*rows.length := by\n  induction rows with\n  | nil => rfl\n  | cons x tail ih =>\n    simp only [endpointLeaves,List.flatMap_cons,List.length_append,List.length_cons,\n      List.length_nil] at *\n    omega\n\ntheorem endpoints_none {n : ℕ} (rows : List (ZMod n)ˣ)\n    (hn : scanProper n (endpointLeaves rows)=none) {x : (ZMod n)ˣ} (hx : x∈rows) :\n    SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-1).val=none ∧\n      SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)+1).val=none := by\n  have hh := (scanProper_none_iff n (endpointLeaves rows)).mp hn\n  exact ⟨hh _ (List.mem_flatMap.mpr ⟨x,hx,by simp⟩),\n    hh _ (List.mem_flatMap.mpr ⟨x,hx,by simp⟩)⟩\n\n/-- The complete guarded extraction procedure. It has no factor field,\nprivate order, collision pair or explicit pair matrix as input. -/\nnoncomputable def guardedTraceRows {n : ℕ} (rows : List (ZMod n)ˣ) : Option ℕ :=\n  match scanProper n (endpointLeaves rows) with\n  | some d => some d\n  | none =>\n    match guardTraces rows [] with\n    | .inl d => some d\n    | .inr reps => recoverTraceRows reps.toFinset\n\ntheorem guardedTraceRows_sound {n d : ℕ} (rows : List (ZMod n)ˣ)\n    (hd : guardedTraceRows rows=some d) : SemiprimeGroupSelection.ProperDivisor n d := by\n  cases he : scanProper n (endpointLeaves rows) with\n  | some d' =>\n    have hh : d'=d := by simpa [guardedTraceRows,he] using hd\n    subst d'\n    exact scanProper_sound he\n  | none =>\n    cases hg : guardTraces rows [] with\n    | inl d' =>\n      have hh : d'=d := by simpa [guardedTraceRows,he,hg] using hd\n      subst d'\n      exact guardTraces_sound rows [] hg\n    | inr reps => exact recoverTraceRows_sound (by simpa [guardedTraceRows,he,hg] using hd)\n\n/-- Only derivative-stage GCD queries are counted by this component. -/\nnoncomputable def traceGcdCount {n : ℕ} (reps : List (ZMod n)ˣ) : ℕ :=\n  recoveryGcdCount n (fun i => residueLeaves (traceRoots reps.toFinset) (i : ZMod n))\n    (evaluatedColumns (traceRoots reps.toFinset) (traceRoots reps.toFinset).toList)\n\ntheorem traceGcdCount_le {n : ℕ} (reps : List (ZMod n)ˣ) :\n    traceGcdCount reps≤2*reps.length :=\n  (recoverTraceRows_gcd_bound reps.toFinset).trans\n    (Nat.mul_le_mul_left 2 reps.toFinset_card_le)\n\n/-- The complete guard/derivative query counter. This does not count\ntable searches, inverses, polynomial work or machine bit operations. -/\nnoncomputable def guardedTraceGcdCount {n : ℕ} (rows : List (ZMod n)ˣ) : ℕ :=\n  scanGcdCount n (endpointLeaves rows)+\n    match scanProper n (endpointLeaves rows) with\n    | some _ => 0\n    | none => guardGcdCount rows []+\n      match guardTraces rows [] with\n      | .inl _ => 0\n      | .inr reps => traceGcdCount reps\n\n/-- Both endpoints, at most one whole-trace guard per row, and one folded\nderivative recovery use at most five GCD queries per original unit. -/\ntheorem guardedTraceGcdCount_le {n : ℕ} (rows : List (ZMod n)ˣ) :\n    guardedTraceGcdCount rows≤5*rows.length := by\n  have he : scanGcdCount n (endpointLeaves rows)≤2*rows.length := by\n    simpa [endpointLeaves_length] using scanGcdCount_le n (endpointLeaves rows)\n  have hg := guardGcdCount_le rows []\n  cases hs : scanProper n (endpointLeaves rows) with\n  | some d => simp only [guardedTraceGcdCount,hs,Nat.add_zero]; omega\n  | none =>\n    cases ho : guardTraces rows [] with\n    | inl d => simp only [guardedTraceGcdCount,hs,ho,Nat.add_zero]; omega\n    | inr reps =>\n      have hl : reps.length≤rows.length := by simpa using guardTraces_length rows [] reps ho\n      have hr := traceGcdCount_le reps\n      simp only [guardedTraceGcdCount,hs,ho]\n      calc\n        _ ≤ 2*rows.length+(rows.length+2*rows.length) :=\n          Nat.add_le_add he (Nat.add_le_add hg (hr.trans (Nat.mul_le_mul_left 2 hl)))\n        _ = 5*rows.length := by omega\n\nprivate theorem trace_eq_of_orientation {R : Type*} [CommRing R] {x r : Rˣ}\n    (h : x=r ∨ x=r⁻¹) : traceValue x=traceValue r := by\n  rcases h with h|h\n  · rw [h]\n  · rw [h,traceValue_inv]\n\n/-- Every original trace remains present in the accepted folded carrier. -/\ntheorem guardTraces_trace_mem {n : ℕ} [NeZero n]\n    (rows out : List (ZMod n)ˣ) (ho : guardTraces rows []=.inr out)\n    {x : (ZMod n)ˣ} (hx : x∈rows) : traceValue x∈traceRoots out.toFinset := by\n  obtain ⟨r,hr,hxr⟩ := guardTraces_orientation rows [] out ho x hx\n  exact Finset.mem_image.mpr ⟨r,List.mem_toFinset.mpr hr,(trace_eq_of_orientation hxr).symm⟩\n\n/-- Once every whole-trace check has passed, equal original traces have\none consistent global orientation; no mixed component match was dropped. -/\ntheorem guardTraces_same_trace_orientation {n : ℕ} [NeZero n]\n    (rows out : List (ZMod n)ˣ) (ho : guardTraces rows []=.inr out)\n    {x y : (ZMod n)ˣ} (hx : x∈rows) (hy : y∈rows)\n    (ht : traceValue x=traceValue y) : x=y ∨ y=x⁻¹ := by\n  obtain ⟨r,hr,hxr⟩ := guardTraces_orientation rows [] out ho x hx\n  obtain ⟨s,hs,hys⟩ := guardTraces_orientation rows [] out ho y hy\n  have hsep := guardTraces_separated rows [] out (by simp [TraceSeparated]) ho\n  have he : traceValue r=traceValue s :=\n    (trace_eq_of_orientation hxr).symm.trans (ht.trans (trace_eq_of_orientation hys))\n  have hrs : r=s := hsep r hr s hs he\n  subst s\n  rcases hxr with hxr|hxr <;> rcases hys with hys|hys\n  · exact Or.inl (hxr.trans hys.symm)\n  · exact Or.inr (by rw [hxr]; exact hys)\n  · exact Or.inr (by rw [hxr,inv_inv]; exact hys)\n  · exact Or.inl (hxr.trans hys.symm)\n\n/-- Failed raw endpoint checks also make the self-product a global zero\nor a unit. This retains local self-inversion without squaring a signal. -/\ntheorem self_product_none_of_endpoints {n : ℕ} [NeZero n] (x : ZMod n)\n    (hm : SemiprimeGroupSelection.checkedSignal n (x-1).val=none)\n    (hp : SemiprimeGroupSelection.checkedSignal n (x+1).val=none) :\n    SemiprimeGroupSelection.checkedSignal n (x*x-1).val=none := by\n  rw [checkedSignal_none_iff]\n  have he : (x-1)*(x+1)=x*x-1 := by ring\n  rcases (checkedSignal_none_iff _).mp hm with hz|hu\n  · left; rw [←he,hz,zero_mul]\n  · rcases (checkedSignal_none_iff _).mp hp with hz|hv\n    · left; rw [←he,hz,mul_zero]\n    · right; rw [←he]; exact hu.mul hv\n\nprivate theorem inverse_difference_checkedSignal {n : ℕ} (x : (ZMod n)ˣ) :\n    SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-((x⁻¹ : (ZMod n)ˣ) : ZMod n)).val=\n      SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)*(x : ZMod n)-1).val := by\n  simp only [SemiprimeGroupSelection.checkedSignal,SemiprimeReciprocalRows.inverse_residual_gcd]\n\n/-- Exhaustion exposes all the actual failed stages, rather than assuming\nthe needed mathematical collision coverage in a hidden premise. -/\ntheorem guardedTraceRows_none_stages {n : ℕ} (rows : List (ZMod n)ˣ)\n    (hn : guardedTraceRows rows=none) :\n    scanProper n (endpointLeaves rows)=none ∧\n      ∃ out, guardTraces rows []=.inr out ∧ recoverTraceRows out.toFinset=none := by\n  cases he : scanProper n (endpointLeaves rows) with\n  | some d => simp [guardedTraceRows,he] at hn\n  | none =>\n    refine ⟨rfl,?_⟩\n    cases hg : guardTraces rows [] with\n    | inl d => simp [guardedTraceRows,he,hg] at hn\n    | inr out => exact ⟨out,rfl,by simpa [guardedTraceRows,he,hg] using hn⟩\n\n/-- Every proper ordinary or product-one pair hit survives all guards and\nthe single trace polynomial. This is a supplied-hit preservation theorem,\nnot an assumption or proof of universal sixth-root row coverage. -/\ntheorem guardedTraceRows_none_pair_checks {n : ℕ} [NeZero n]\n    (rows : List (ZMod n)ˣ) (hn : guardedTraceRows rows=none)\n    {x y : (ZMod n)ˣ} (hx : x∈rows) (hy : y∈rows) :\n    SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val=none ∧\n      SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)*(y : ZMod n)-1).val=none := by\n  obtain ⟨hend,out,hguard,hfold⟩ := guardedTraceRows_none_stages rows hn\n  have hsign := endpoints_none rows hend hx\n  have hself := self_product_none_of_endpoints (x : ZMod n) hsign.1 hsign.2\n  by_cases ht : traceValue x=traceValue y\n  · rcases guardTraces_same_trace_orientation rows out hguard hx hy ht with he|he\n    · subst y\n      exact ⟨by simp [SemiprimeGroupSelection.checkedSignal],hself⟩\n    · subst y\n      have hp : (x : ZMod n)*((x⁻¹ : (ZMod n)ˣ) : ZMod n)=1 := by simp\n      exact ⟨by rw [inverse_difference_checkedSignal]; exact hself,\n        by simp [hp,SemiprimeGroupSelection.checkedSignal]⟩\n  · have hh : n.gcd (traceValue x-traceValue y).val=1 :=\n      (recoverRows_none_iff (traceRoots out.toFinset)).mp hfold\n        (traceValue x) (guardTraces_trace_mem rows out hguard hx)\n        (traceValue y) (guardTraces_trace_mem rows out hguard hy) (Ne.symm ht)\n    have hu := (trace_difference_isUnit_iff x y).mp\n      ((SemiprimeBulkNorm.gcd_one_iff_unit _).mp hh)\n    exact ⟨(checkedSignal_none_iff _).mpr (Or.inr hu.1),\n      (checkedSignal_none_iff _).mpr (Or.inr hu.2)⟩\n\n/-- The complete guarded procedure detects every proper original pair\nin either channel, including diagonal reciprocal hits and saturation. -/\ntheorem guardedTraceRows_succeeds_of_pair {n : ℕ} [NeZero n]\n    (rows : List (ZMod n)ˣ) {x y : (ZMod n)ˣ} (hx : x∈rows) (hy : y∈rows)\n    (hp : SemiprimeGroupSelection.ProperDivisor n (n.gcd ((x : ZMod n)-(y : ZMod n)).val) ∨\n      SemiprimeGroupSelection.ProperDivisor n (n.gcd ((x : ZMod n)*(y : ZMod n)-1).val)) :\n    ∃ d, guardedTraceRows rows=some d := by\n  cases hn : guardedTraceRows rows with\n  | some d => exact ⟨d,rfl⟩\n  | none =>\n    have hh := guardedTraceRows_none_pair_checks rows hn hx hy\n    rcases hp with hp|hp\n    · have hc : SemiprimeGroupSelection.checkedSignal n\n          ((x : ZMod n)-(y : ZMod n)).val=some (n.gcd ((x : ZMod n)-(y : ZMod n)).val) := by\n        simp [SemiprimeGroupSelection.checkedSignal,hp.1,hp.2.1]\n      rw [hh.1] at hc\n      contradiction\n    · have hc : SemiprimeGroupSelection.checkedSignal n\n          ((x : ZMod n)*(y : ZMod n)-1).val=some (n.gcd ((x : ZMod n)*(y : ZMod n)-1).val) := by\n        simp [SemiprimeGroupSelection.checkedSignal,hp.1,hp.2.1]\n      rw [hh.2] at hc\n      contradiction\n\n/-- A proper raw endpoint hit is also recovered by the complete procedure. -/\ntheorem guardedTraceRows_succeeds_of_endpoint {n : ℕ} (rows : List (ZMod n)ˣ)\n    {v : ℕ} (hv : v∈endpointLeaves rows)\n    (hp : SemiprimeGroupSelection.ProperDivisor n (n.gcd v)) :\n    ∃ d, guardedTraceRows rows=some d := by\n  cases hn : guardedTraceRows rows with\n  | some d => exact ⟨d,rfl⟩\n  | none =>\n    have he := (guardedTraceRows_none_stages rows hn).1\n    have hh := (scanProper_none_iff n (endpointLeaves rows)).mp he v hv\n    have hc : SemiprimeGroupSelection.checkedSignal n v=some (n.gcd v) := by\n      simp [SemiprimeGroupSelection.checkedSignal,hp.1,hp.2.1]\n    rw [hh] at hc\n    contradiction\n\n/-- Failed original ordinary checks let the actual representative scan\nfinish; the scope contains every input and every retained representative. -/\ntheorem guardTraces_exists_of_pair_checks {n : ℕ}\n    (rows reps scope : List (ZMod n)ˣ)\n    (hrows : ∀ x∈rows, x∈scope) (hreps : ∀ x∈reps, x∈scope)\n    (hall : ∀ x∈scope, ∀ y∈scope,\n      SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val=none) :\n    ∃ out, guardTraces rows reps=.inr out := by\n  induction rows generalizing reps with\n  | nil => exact ⟨reps,rfl⟩\n  | cons x tail ih =>\n    have htail : ∀ y∈tail, y∈scope := fun y hy => hrows y (List.mem_cons_of_mem x hy)\n    cases hf : reps.find? (fun y => decide (traceValue x=traceValue y)) with\n    | none =>\n      have hnew : ∀ y∈x::reps, y∈scope := by\n        intro y hy\n        rcases List.mem_cons.mp hy with hxy|hy\n        · exact hxy ▸ hrows x (by simp)\n        · exact hreps y hy\n      obtain ⟨out,ho⟩ := ih (x::reps) htail hnew\n      exact ⟨out,by simpa [guardTraces,hf] using ho⟩\n    | some y =>\n      have hc := hall x (hrows x (by simp)) y (hreps y (List.mem_of_find?_eq_some hf))\n      obtain ⟨out,ho⟩ := ih reps htail hreps\n      exact ⟨out,by simpa [guardTraces,hf,hc] using ho⟩\n\n/-- Distinct global traces have unit differences when every original\nordinary and reciprocal pair check fails. This proves that the folded\npolynomial adds no new proper-factor channel to that original carrier. -/\ntheorem recoverTraceRows_none_of_pair_checks {n : ℕ} [NeZero n]\n    (S : Finset (ZMod n)ˣ)\n    (hall : ∀ x∈S, ∀ y∈S,\n      SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val=none ∧\n        SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)*(y : ZMod n)-1).val=none) :\n    recoverTraceRows S=none := by\n  apply (recoverRows_none_iff (traceRoots S)).mpr\n  intro t ht u hu hne\n  obtain ⟨x,hx,htx⟩ := Finset.mem_image.mp ht\n  obtain ⟨y,hy,hty⟩ := Finset.mem_image.mp hu\n  have hnt : traceValue x≠traceValue y := by\n    intro he\n    exact hne (hty.symm.trans (he.symm.trans htx))\n  have hd : (x : ZMod n)-(y : ZMod n)≠0 := by\n    intro he\n    exact hnt (congrArg traceValue (Units.ext (sub_eq_zero.mp he)))\n  have hp : (x : ZMod n)*(y : ZMod n)-1≠0 := by\n    intro he\n    have hh : traceValue x-traceValue y=0 := by rw [trace_difference,he,mul_zero]\n    exact hnt (sub_eq_zero.mp hh)\n  have hc := hall x hx y hy\n  have hdu := ((checkedSignal_none_iff _).mp hc.1).resolve_left hd\n  have hpu := ((checkedSignal_none_iff _).mp hc.2).resolve_left hp\n  apply (SemiprimeBulkNorm.gcd_one_iff_unit _).mpr\n  rw [←htx,←hty]\n  exact (trace_difference_isUnit_iff x y).mpr ⟨hdu,hpu⟩\n\n/-- Exact exhaustion criterion for the complete guarded procedure. It\npreserves precisely the original pair-hit union and raw endpoint channel;\nit does not create universal coverage by compressing those observables. -/\ntheorem guardedTraceRows_none_iff {n : ℕ} [NeZero n] (rows : List (ZMod n)ˣ) :\n    guardedTraceRows rows=none ↔ scanProper n (endpointLeaves rows)=none ∧\n      ∀ x∈rows, ∀ y∈rows,\n        SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)-(y : ZMod n)).val=none ∧\n          SemiprimeGroupSelection.checkedSignal n ((x : ZMod n)*(y : ZMod n)-1).val=none := by\n  constructor\n  · intro hn\n    exact ⟨(guardedTraceRows_none_stages rows hn).1,\n      fun _ hx _ hy => guardedTraceRows_none_pair_checks rows hn hx hy⟩\n  · rintro ⟨he,hall⟩\n    obtain ⟨out,ho⟩ := guardTraces_exists_of_pair_checks rows [] rows\n      (fun _ hx => hx) (by simp) (fun x hx y hy => (hall x hx y hy).1)\n    have hsub : ∀ x∈out, x∈rows := by\n      intro x hx\n      simpa using guardTraces_reps_subset rows [] out ho x hx\n    have hf : recoverTraceRows out.toFinset=none := by\n      apply recoverTraceRows_none_of_pair_checks\n      intro x hx y hy\n      exact hall x (hsub x (List.mem_toFinset.mp hx)) y (hsub y (List.mem_toFinset.mp hy))\n    simp [guardedTraceRows,he,ho,hf]\n\n/-- Actual packet powers remain in their original list before any trace\nprojection. The constructor takes no hidden factor or component order. -/\ndef publicUnitRows {n : ℕ} (m : ℕ) (g : (ZMod n)ˣ) : List (ZMod n)ˣ :=\n  (SemiprimeEuclidRowFamily.publicPackets n m).map\n    fun w => g^SemiprimeEuclidRowFamily.packetExponent m w\n\ntheorem publicUnitRows_mem_of_exponent {n m : ℕ} (g : (ZMod n)ˣ) {e : ℤ}\n    (he : e∈SemiprimeEuclidRowFamily.publicExponents n m) : g^e∈publicUnitRows m g := by\n  obtain ⟨w,hw,hwe⟩ := List.mem_map.mp he\n  exact List.mem_map.mpr ⟨w,hw,by rw [hwe]⟩\n\n/-- Complete guarded extraction on the public retained quadratic family. -/\nnoncomputable def publicGuardedTraceRows {n : ℕ} (m : ℕ) (g : (ZMod n)ˣ) : Option ℕ :=\n  guardedTraceRows (publicUnitRows m g)\n\ntheorem publicGuardedTraceRows_sound {n m d : ℕ} {g : (ZMod n)ˣ}\n    (hd : publicGuardedTraceRows m g=some d) : SemiprimeGroupSelection.ProperDivisor n d :=\n  guardedTraceRows_sound _ hd\n\ntheorem publicGuardedTraceRows_gcd_bound {n m : ℕ} (g : (ZMod n)ˣ) :\n    guardedTraceGcdCount (publicUnitRows m g)≤\n      5*(SemiprimeEuclidRowFamily.publicPackets n m).length := by\n  simpa [publicUnitRows] using guardedTraceGcdCount_le (publicUnitRows m g)\n\n/-- A proper pair in either original public channel is enough for the\ncomplete guarded detector. The proving pair is not an algorithm input. -/\ntheorem publicGuardedTraceRows_succeeds_of_pair {n m : ℕ} [NeZero n]\n    (g : (ZMod n)ˣ) {e f : ℤ}\n    (he : e∈SemiprimeEuclidRowFamily.publicExponents n m)\n    (hf : f∈SemiprimeEuclidRowFamily.publicExponents n m)\n    (hp : SemiprimeGroupSelection.ProperDivisor n\n        (n.gcd (((g^e : (ZMod n)ˣ) : ZMod n)-((g^f : (ZMod n)ˣ) : ZMod n)).val) ∨\n      SemiprimeGroupSelection.ProperDivisor n\n        (n.gcd (((g^e : (ZMod n)ˣ) : ZMod n)*((g^f : (ZMod n)ˣ) : ZMod n)-1).val)) :\n    ∃ d, publicGuardedTraceRows m g=some d :=\n  guardedTraceRows_succeeds_of_pair _\n    (publicUnitRows_mem_of_exponent g he) (publicUnitRows_mem_of_exponent g hf) hp\n\n/-- The complete public guarded procedure recovers on the larger\nordinary-row stress input. It retains both raw endpoint orientations and\nuses neither the proving pair nor component factors as source inputs. -/\ntheorem control_public_guarded_recovers :\n    ∃ d, publicGuardedTraceRows 3691 SemiprimeReciprocalRows.controlBase=some d ∧\n      SemiprimeGroupSelection.ProperDivisor 2518766418595894637609 d := by\n  have hp : SemiprimeGroupSelection.ProperDivisor 2518766418595894637609\n      ((2518766418595894637609 : ℕ).gcd\n        (((SemiprimeReciprocalRows.controlBase^(3596798445668641429783915 : ℤ) :\n          (ZMod 2518766418595894637609)ˣ) : ZMod 2518766418595894637609)*\n          ((SemiprimeReciprocalRows.controlBase^(3037632300775047433790237 : ℤ) :\n          (ZMod 2518766418595894637609)ˣ) : ZMod 2518766418595894637609)-1).val) := by\n    rw [SemiprimeReciprocalRows.control_values.1,SemiprimeReciprocalRows.control_values.2]\n    exact SemiprimeReciprocalRows.control_product_pair\n  obtain ⟨d,hd⟩ := publicGuardedTraceRows_succeeds_of_pair SemiprimeReciprocalRows.controlBase\n    SemiprimeReciprocalRows.control_exponents.1 SemiprimeReciprocalRows.control_exponents.2 (Or.inr hp)\n  exact ⟨d,hd,publicGuardedTraceRows_sound hd⟩\n\nend RiemannGaussian.SemiprimeGuardedTrace\n","RiemannGaussian.SemiprimeHermiteWordWidth":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeAffineJetBits\nimport RiemannGaussian.SemiprimeNormalizedInverseBits\nimport RiemannGaussian.SemiprimeHermiteEvaluationBitsBounds\n\n/-! # Original-input width for the whole physical Hermite node\n\nAll exponents are explicit fixed polynomials with natural logarithmic factors.\nNo cardinal input, inverse coefficient or intermediate Fits is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeHermiteWordWidth\nopen SemiprimeHermiteArrayHeight SemiprimeJetArrayHeight SemiprimeCardinalHeight\n\n/-- Original factorial, node and precision input exponent. -/\ndef inputExponent (Q J : ℕ) : ℕ := Nat.clog 2 Q*Q+Q+J+1\n/-- Intrinsic cardinal coefficient exponent, common to every node. -/\ndef cardinalExponent (Q J : ℕ) : ℕ := cardinalBits Q J+Q*J\n/-- Common quotient denominator and coefficient numerator exponent. -/\ndef quotientExponent (b Q J : ℕ) : ℕ :=\n  b+J+(cardinalBits Q J+inverseBits Q J)*J+1\n/-- One literal public template for all actual Hermite stages and final sums. -/\ndef width (b Q J : ℕ) : ℕ :=\n  b+Q+J+SemiprimeAffineJetBits.width (inputExponent Q J) (Q*J)+\n  SemiprimeNormalizedInverseBits.inverseWidth (cardinalExponent Q J) J+\n  SemiprimeHermiteEvaluationBitsBounds.evaluationWidth (inputExponent Q J) (Q*J)+\n  SemiprimeHermiteEvaluationBitsBounds.evaluationWidth (quotientExponent b Q J+Q+1) J+\n  quotientExponent b Q J+hermiteDenominatorBits Q J b+\n  hermiteNumeratorBits Q J b+Q+10\n\n/-- Factorial and integer node/precision bounds follow from the public exponent. -/\ntheorem input_guards (Q J : ℕ) :\n    Q.factorial≤2^inputExponent Q J ∧ Q≤2^inputExponent Q J ∧ J≤2^inputExponent Q J := by\n  have hf := factorial_dyadic Q\n  have hq := (Nat.lt_two_pow_self (n:=Q)).le\n  have hj := (Nat.lt_two_pow_self (n:=J)).le\n  unfold inputExponent\n  exact ⟨hf.trans (Nat.pow_le_pow_right (by decide) (by omega)),\n    hq.trans (Nat.pow_le_pow_right (by decide) (by omega)),\n    hj.trans (Nat.pow_le_pow_right (by decide) (by omega))⟩\n\n/-- Intrinsic cardinal denominator and numerator share a computable exponent. -/\ntheorem cardinal_guards (Q J : ℕ) :\n    cardinalDenominator Q J≤2^cardinalExponent Q J ∧\n    cardinalDenominator Q J*2^(Q*J)≤2^cardinalExponent Q J := by\n  have hc := cardinalDenominator_dyadic Q J\n  refine ⟨hc.trans (Nat.pow_le_pow_right (by decide) (by unfold cardinalExponent;omega)),?_⟩\n  calc\n    _ ≤ 2^cardinalBits Q J*2^(Q*J) := Nat.mul_le_mul_right _ hc\n    _ = _ := by rw [← pow_add];rfl\n\n/-- Original packet bounds imply actual cached quotient coefficient bounds. -/\ntheorem quotient_guards (b Q J DH BH : ℕ) (hDH : DH≤2^b) (hBH : BH≤2^b) :\n    DH*cardinalDenominator Q J^J≤2^quotientExponent b Q J ∧\n    J*BH*inverseBase J (cardinalDenominator Q J)\n      (cardinalDenominator Q J*2^(Q*J))^J≤2^quotientExponent b Q J := by\n  have hc := cardinalDenominator_dyadic Q J\n  have hi := inverseBase_dyadic Q J\n  have hj := (Nat.lt_two_pow_self (n:=J)).le\n  constructor\n  · calc\n      _ ≤ 2^b*(2^cardinalBits Q J)^J := Nat.mul_le_mul hDH (Nat.pow_le_pow_left hc _)\n      _ = 2^(b+cardinalBits Q J*J) := by rw [← pow_mul,← pow_add]\n      _ ≤ _ := Nat.pow_le_pow_right (by decide) (by unfold quotientExponent;nlinarith)\n  · calc\n      _ ≤ 2^J*2^b*(2^inverseBits Q J)^J :=\n        Nat.mul_le_mul (Nat.mul_le_mul hj hBH) (Nat.pow_le_pow_left hi _)\n      _ = 2^(J+b+inverseBits Q J*J) := by rw [← pow_mul,← pow_add,← pow_add]\n      _ ≤ _ := Nat.pow_le_pow_right (by decide) (by unfold quotientExponent;nlinarith)\n\n/-- The actual physical template is nonempty. -/\ntheorem width_positive (b Q J : ℕ) : 0<width b Q J := by unfold width;omega\n/-- Original packet exponent fits in the selected word width. -/\ntheorem input_width_le (b Q J : ℕ) : b≤width b Q J := by unfold width;omega\n/-- Intrinsic affine array construction has its acquired width. -/\ntheorem affine_width_le (b Q J : ℕ) :\n    SemiprimeAffineJetBits.width (inputExponent Q J) (Q*J)≤width b Q J := by unfold width;omega\n/-- Cached normalized inversion has its acquired width. -/\ntheorem inverse_width_le (b Q J : ℕ) :\n    SemiprimeNormalizedInverseBits.inverseWidth (cardinalExponent Q J) J≤width b Q J := by unfold width;omega\n/-- Scalar affine-at-zero construction has its acquired width. -/\ntheorem affineValue_width_le (b Q J : ℕ) :\n    SemiprimeHermiteEvaluationBitsBounds.evaluationWidth (inputExponent Q J) (Q*J)≤width b Q J := by unfold width;omega\n/-- Quotient scalar evaluation has its acquired width. -/\ntheorem eval_width_le (b Q J : ℕ) :\n    SemiprimeHermiteEvaluationBitsBounds.evaluationWidth (quotientExponent b Q J+Q+1) J≤width b Q J := by unfold width;omega\n/-- The original factorial/node exponent fits in the selected width. -/\ntheorem inputExponent_le (b Q J : ℕ) : inputExponent Q J≤width b Q J := by\n  have h := affine_width_le b Q J\n  unfold SemiprimeAffineJetBits.width at h\n  have hp : 2*inputExponent Q J+1≤(2*inputExponent Q J+1)*(Q*J+1) := by\n    simpa only [Nat.mul_one] using Nat.mul_le_mul_left (2*inputExponent Q J+1) (show 1≤Q*J+1 by omega)\n  omega\n/-- The intrinsic cardinal common exponent fits in the selected width. -/\ntheorem cardinalExponent_le (b Q J : ℕ) : cardinalExponent Q J≤width b Q J := by\n  have h := inverse_width_le b Q J\n  unfold SemiprimeNormalizedInverseBits.inverseWidth at h\n  omega\n/-- Literal original slope and integer-node encodings fit in the template. -/\ntheorem node_input_width_le (b Q J : ℕ) : Q+2≤width b Q J := by unfold width;omega\n/-- Cached quotient height is strictly below the physical width. -/\ntheorem quotientExponent_lt (b Q J : ℕ) : quotientExponent b Q J<width b Q J := by unfold width;omega\n/-- Cached quotient height is below the physical width. -/\ntheorem quotientExponent_le (b Q J : ℕ) : quotientExponent b Q J≤width b Q J := by unfold width;omega\n/-- Final common denominator fits strictly, including all node-sum prefixes. -/\ntheorem denominatorBits_lt (b Q J : ℕ) : hermiteDenominatorBits Q J b<width b Q J := by unfold width;omega\n/-- Final common numerator fits strictly, including all node-sum prefixes. -/\ntheorem numeratorBits_lt (b Q J : ℕ) : hermiteNumeratorBits Q J b<width b Q J := by unfold width;omega\n\n/-- Actual quotient multiplication receives strict derived denominator/numerator caps. -/\ntheorem quotient_caps (b Q J DH BH : ℕ) (hDH : DH≤2^b) (hBH : BH≤2^b) :\n    DH*cardinalDenominator Q J^J<2^width b Q J ∧\n    J*BH*inverseBase J (cardinalDenominator Q J)\n      (cardinalDenominator Q J*2^(Q*J))^J<2^width b Q J := by\n  have h := quotient_guards b Q J DH BH hDH hBH\n  have hp := Nat.pow_lt_pow_right (by decide : 1<2) (quotientExponent_lt b Q J)\n  exact ⟨h.1.trans_lt hp,h.2.trans_lt hp⟩\n\n/-- The original packet common bounds imply strict final scalar-sum caps. -/\ntheorem final_caps (b Q J DH BH : ℕ) (hDH : DH≤2^b) (hBH : BH≤2^b) :\n    hermiteDenominator Q J DH<2^width b Q J ∧\n    Q*hermiteNodeBound Q J BH<2^width b Q J := by\n  exact ⟨(hermiteDenominator_dyadic Q J DH b hDH).trans_lt\n      (Nat.pow_lt_pow_right (by decide) (denominatorBits_lt b Q J)),\n    (hermiteNodeBound_dyadic Q J BH b hBH).trans_lt\n      (Nat.pow_lt_pow_right (by decide) (numeratorBits_lt b Q J))⟩\n\n/-- For an existing node, the same original sum cap also covers that one node. -/\ntheorem final_node_cap (b Q J BH : ℕ) (hQ : 0<Q) (hBH : BH≤2^b) :\n    hermiteNodeBound Q J BH<2^width b Q J := by\n  have h := (hermiteNodeBound_dyadic Q J BH b hBH).trans_lt\n    (Nat.pow_lt_pow_right (by decide) (numeratorBits_lt b Q J))\n  exact (show hermiteNodeBound Q J BH≤Q*hermiteNodeBound Q J BH by\n    simpa only [Nat.one_mul] using Nat.mul_le_mul_right (hermiteNodeBound Q J BH) hQ).trans_lt h\n\nend RiemannGaussian.SemiprimeHermiteWordWidth\n","RiemannGaussian.SemiprimePaddedBlockExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeFiniteEnumerations\n\n/-!\n# Executed padded integer block constraints\n\nThe full universal alphabet and all original incidences form a concrete padded\nrow index. Invalid universal rows and covered leftover rows are zero. Explicit\nenumerations implement the integer pullbacks, avoiding mathematical finite\nequivalences in the runtime.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1400000\nnamespace RiemannGaussian.SemiprimePaddedBlockExecution\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen Subexp.ConstructivePacking SqrtLog\n\nvariable {I U V : Type} [DecidableEq I] [DecidableEq U] [DecidableEq V]\n\n/-- Sum one integer row along an owner map using its explicit finite list. -/\ndef integerPullback (en : FiniteEnumeration I) (owner : I → V) (a : I → ℤ) (v : V) : ℤ :=\n  (List.ofFn (fun k : Fin en.values.length =>\n    if owner (en.equivFin k)=v then a (en.equivFin k) else 0)).sum\n\n/-- Explicit list summation equals the mathematical owner-fibre pullback. -/\ntheorem integerPullback_eq [Fintype I] (en : FiniteEnumeration I)\n    (owner : I → V) (a : I → ℤ) (v : V) :\n    integerPullback en owner a v=LayoutPullback.row owner a v := by\n  rw [integerPullback,List.sum_ofFn]\n  simpa only [LayoutPullback.row] using en.equivFin.sum_comp\n    (fun i => if owner i=v then a i else (0 : ℤ))\n\n/-- Every potential block row and every incidence has a concrete runtime index. -/\ndef indices (P : PackingData I U) : FiniteEnumeration ((Fin P.blockCount × U) ⊕ I) :=\n  SemiprimeFiniteEnumerations.sum\n    (SemiprimeFiniteEnumerations.prod (SemiprimeFiniteEnumerations.fin P.blockCount) P.types)\n    P.vertices\n\n/-- Actual padded copy constraints, before the original-variable pullback. -/\ndef copyRow {r : ℕ} (P : PackingData I U) (head : U → Fin r) (g : Fin r)\n    (C : U → U → ℤ) : ((Fin P.blockCount × U) ⊕ I) → I → ℤ\n  | .inl z => integerPullback P.types (P.vertexAt z.1) (C z.2)\n  | .inr i => fun v => if P.lookup i=none ∧ head (P.label i)=g ∧ v=i then 1 else 0\n\n/-- The computed original-coordinate padded matrix. -/\ndef sourceRow {r : ℕ} (P : PackingData I U) (owner : I → V)\n    (head : U → Fin r) (g : Fin r) (C : U → U → ℤ)\n    (j : (Fin P.blockCount × U) ⊕ I) : V → ℤ :=\n  integerPullback P.vertices owner (copyRow P head g C j)\n\n/-- Concrete finite row numbering with no choice of a finite-type equivalence. -/\ndef matrix {r : ℕ} (P : PackingData I U) (owner : I → V)\n    (head : U → Fin r) (g : Fin r) (C : U → U → ℤ) :\n    Fin (indices P).values.length → V → ℤ :=\n  fun j => sourceRow P owner head g C ((indices P).equivFin j)\n\n/-- Zero padded universal rows remain zero through block embedding. -/\ntheorem copyRow_zero {r : ℕ} (P : PackingData I U) (head : U → Fin r) (g : Fin r)\n    (C : U → U → ℤ) (j : Fin P.blockCount) (a : U) (h : ∀ y, C a y=0) :\n    copyRow P head g C (.inl (j,a))=0 := by\n  funext v\n  simp [copyRow,integerPullback,h]\n\n/-- Covered incidences or wrong-head leftovers contribute only zero rows. -/\ntheorem copyRow_leftover_zero {r : ℕ} (P : PackingData I U) (head : U → Fin r)\n    (g : Fin r) (C : U → U → ℤ) (i : I)\n    (h : ¬(P.lookup i=none ∧ head (P.label i)=g)) :\n    copyRow P head g C (.inr i)=0 := by\n  funext v\n  simp only [copyRow,Pi.zero_apply]\n  split_ifs with hv\n  · exact False.elim (h ⟨hv.1,hv.2.1⟩)\n  · rfl\n\nomit [DecidableEq I] in\n/-- The concrete index count is block-count times alphabet size plus incidences. -/\ntheorem indices_length (P : PackingData I U) :\n    (indices P).values.length=P.blockCount*P.types.values.length+P.vertices.values.length := by\n  simp [indices,SemiprimeFiniteEnumerations.fin]\n\nsection Specification\nvariable [Fintype I] [Fintype U] {r Q R : ℕ}\n\nomit [Fintype I] in\n/-- A block row whose universal head restriction matches the source has exactly\nthe source's assembled head restriction. The source layout is proof-only. -/\ntheorem copyRow_block_spec\n    (L : Layout.Data (O := ℚ) (G := Fin r) (id : U → U) (id : U → U) Q R)\n    (P : PackingData I U) (t : Fin Q) (g : Fin r) (C : U → U → ℤ)\n    (a : U) (k : Fin (L.rowCount t g))\n    (h : ∀ y : {y : U // L.head t y=g}, C a y.val=L.constraints t g k y)\n    (j : Fin P.blockCount)\n    (v : {i : I // LayoutBlocks.copyHead L P.label t i=g}) :\n    copyRow P (L.head t) g C (.inl (j,a)) v.val =\n      LayoutBlocks.constraints L P.completeBlocks t g (.inl (j,k)) v := by\n  rw [copyRow,integerPullback_eq]\n  have hh : ∀ y : U, L.head t y=LayoutBlocks.copyHead L P.label t (P.vertexAt j y) := by\n    intro y\n    change L.head t y=L.head t (P.label (P.completeBlocks.embed (j,y)))\n    rw [P.completeBlocks.type_eq]\n  rw [LayoutHeadPullback.row_restrict (P.vertexAt j) (L.head t)\n    (LayoutBlocks.copyHead L P.label t) hh g]\n  change LayoutPullback.row (LayoutBlocks.embedHead L P.completeBlocks t g j)\n    (fun y => C a y.val) v =\n    LayoutPullback.row (LayoutBlocks.embedHead L P.completeBlocks t g j) (L.constraints t g k) v\n  congr 2\n  exact funext h\n\nomit [Fintype I] in\n/-- A real leftover is the original singleton constraint. -/\ntheorem copyRow_leftover_spec\n    (L : Layout.Data (O := ℚ) (G := Fin r) (id : U → U) (id : U → U) Q R)\n    (P : PackingData I U) (t : Fin Q) (g : Fin r) (C : U → U → ℤ)\n    (i : {v : {i : I // LayoutBlocks.copyHead L P.label t i=g} //\n      v.val ∉ Set.range P.completeBlocks.embed})\n    (v : {i : I // LayoutBlocks.copyHead L P.label t i=g}) :\n    copyRow P (L.head t) g C (.inr i.val.val) v.val =\n      LayoutBlocks.constraints L P.completeBlocks t g (.inr i) v := by\n  have hi := (P.lookup_none_iff i.val.val).mpr i.property\n  have hh : L.head t (P.label i.val.val)=g := i.val.property\n  simp only [copyRow,hi,hh,true_and,LayoutBlocks.constraints,Pi.single_apply]\n  have he : v.val=i.val.val ↔ i.val=v := by\n    constructor\n    · intro h\n      exact (Subtype.ext h).symm\n    · intro h\n      exact congrArg Subtype.val h.symm\n  simp only [he,eq_comm]\n\nomit [Fintype U] in\n/-- Restricting the computed owner pullback gives the exact restricted source\npullback for any matching incidence head row. -/\ntheorem sourceRow_spec {r : ℕ} (P : PackingData I U) (owner : I → V)\n    (head : U → Fin r) (originalHead : V → Fin r)\n    (hhead : ∀ i, head (P.label i)=originalHead (owner i))\n    (g : Fin r) (C : U → U → ℤ) (j : (Fin P.blockCount × U) ⊕ I)\n    (a : {i : I // head (P.label i)=g} → ℤ)\n    (ha : ∀ i : {i : I // head (P.label i)=g}, copyRow P head g C j i.val=a i)\n    (v : {v : V // originalHead v=g}) :\n    sourceRow P owner head g C j v.val=\n      LayoutPullback.row (LayoutHeadPullback.headOwner owner\n        (fun i => head (P.label i)) originalHead hhead g) a v := by\n  rw [sourceRow,integerPullback_eq,LayoutHeadPullback.row_restrict owner\n    (fun i => head (P.label i)) originalHead hhead g]\n  congr 2\n  exact funext ha\n\nend Specification\nend RiemannGaussian.SemiprimePaddedBlockExecution\n","RiemannGaussian.SemiprimeRuntimeDesignCache":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeRuntimeDesignAcquisition\n\n/-!\n# Materializing runtime design accessors\nBoth grouping directions, bounds, assignments and integer entries are cached.\nShape functions retain their original types; their finite metadata evaluation\nis a separate bounded scalar-read stage, not a free arbitrary callback claim.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeRuntimeDesignCache\nopen SemiprimeNodeArrayExecution\n\n/-- Acquire an entire finite function once; later calls read its actual array. -/\ndef function {n : ℕ} {A : Type*} (f : Fin n → A) : Fin n → A :=\n  let entries := Array.ofFn f\n  fun i => entries[i.val]'(by simp [entries])\n\n/-- A cached finite function retains its exact values. -/\ntheorem function_eq {n : ℕ} {A : Type*} (f : Fin n → A) : function f=f := by\n  funext i\n  simp only [function,Array.getElem_ofFn]\n\n/-- Cache both directions of an explicitly supplied finite grouping equivalence. -/\ndef grouping {n r : ℕ} {h : Fin r → ℕ} (e : Fin n ≃ ((g : Fin r) × Fin (h g))) :\n    Fin n ≃ ((g : Fin r) × Fin (h g)) := by\n  let forwards := Array.ofFn e\n  let backwards := Array.ofFn (fun g : Fin r => Array.ofFn (fun i : Fin (h g) => e.symm ⟨g,i⟩))\n  let f := fun i : Fin n => forwards[i.val]'(by simp [forwards])\n  let b := fun p : (g : Fin r) × Fin (h g) =>\n    (backwards[p.1.val]'(by simp [backwards]))[p.2.val]'(by simp [backwards])\n  have hf : f=e := by funext i; simp only [f,forwards,Array.getElem_ofFn]\n  have hb : b=e.symm := by\n    funext p\n    rcases p with ⟨g,i⟩\n    simp only [b,backwards,Array.getElem_ofFn]\n  exact { toFun := f, invFun := b\n          left_inv := by intro i; rw [hf,hb]; exact e.symm_apply_apply i\n          right_inv := by intro p; rw [hf,hb]; exact e.apply_symm_apply p }\n\n/-- Grouping acquisition changes neither direction's values. -/\ntheorem grouping_eq {n r : ℕ} {h : Fin r → ℕ} (e : Fin n ≃ ((g : Fin r) × Fin (h g))) : grouping e=e := by\n  apply Equiv.ext\n  intro i\n  simp only [grouping,Array.getElem_ofFn]\n  rfl\n\n/-- Cache finite value accessors and both grouping directions. Shape fields are\nunchanged; they carry no row selection and are charged as metadata separately. -/\ndef acquire {n F : ℕ} (d : RuntimeDesign n F) : RuntimeDesign n F :=\n  let ws := function d.W\n  let assigned := function d.assigned\n  let grp := grouping d.grouping\n  let values := Array.ofFn (fun g : Fin d.r => Array.ofFn (fun j : Fin (d.m g) =>\n    Array.ofFn (fun v : Fin (d.h g) => d.C g j v)))\n  { d with W := ws, grouping := grp, assigned := assigned\n           C := fun g j v => ((values[g.val]!)[j.val]!)[v.val]! }\n\n/-- Cached accessors give EXACT original design values. -/\ntheorem acquire_eq {n F : ℕ} (d : RuntimeDesign n F) : acquire d=d := by\n  simp [acquire,function_eq,grouping_eq]\n\nend RiemannGaussian.SemiprimeRuntimeDesignCache\n","RiemannGaussian.SemiprimeSetupPolynomialEnvelope":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeFullSetupBudget\n\n/-! # Fixed polynomial closure of the actual setup envelope\nOnly the bit-width bound enters the selector dimensions. The large integer\nmeasurement magnitude is not an independent dimension here. This comparison\nbounds the existing mixed execution ledger, not a literal machine clock.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 5000000\nnamespace RiemannGaussian.SemiprimeSetupPolynomialEnvelope\n\n/-- Diagonal fixed-polynomial setup envelope. Its dependencies contain only\naddition, multiplication and fixed natural powers, after the paid universal\nalphabet has replaced the variable-size subset expansion. -/\ndef polynomialEnvelope (S : ℕ) : ℕ :=\n  SemiprimeFullSetupBudget.setupBudget S S S S S S S S S\n\n/-- Every actual setup dimension may be replaced by a common upper bound.\nThe selector width is recomputed from B,Q,R; no measurement-magnitude advice,\nintermediate Fits or precomputed setup result is assumed. -/\ntheorem setupBudget_le_envelope (n F M r Q R B D A S : ℕ)\n    (hn : n≤S) (hF : F≤S) (hM : M≤S) (hr : r≤S) (hQ : Q≤S)\n    (hR : R≤S) (hB : B≤S) (hD : D≤S) (hA : A≤S) :\n    SemiprimeFullSetupBudget.setupBudget n F M r Q R B D A ≤ polynomialEnvelope S := by\n  unfold polynomialEnvelope\n  simp only [SemiprimeFullSetupBudget.setupBudget,SemiprimeFullSetupBudget.sourceBudget,\n    SemiprimeFullSetupBudget.rawBudget,SemiprimeFullSetupBudget.designBudget,\n    SemiprimePaidFiniteEnumerations.polynomial,SemiprimePaidFiniteEnumerations.incidenceBudget,\n    SemiprimePaidFiniteEnumerations.wordPolynomial,SemiprimePaidFiniteEnumerations.universalPolynomial,\n    SemiprimePaidFiniteEnumerations.scoreBudget,SemiprimePaidSourceMetadata.budget,\n    SemiprimePaidOriginalConstraints.polynomial,SemiprimePaidConstraintAcquisition.polynomial,\n    SemiprimePaidConstraintAcquisition.universalPolynomial,SemiprimePaidConstraintAcquisition.tableBudget,\n    SemiprimeMaterializedSourceWords.producerBudget,SemiprimeMaterializedScoreSearch.evaluatorBudget,\n    SemiprimeMaterializedScoreEnvironment.terminalBudget,\n    SemiprimeMaterializedSourceAcquisition.packingBudget,\n    SemiprimeMaterializedSourceRows.rowPolynomial,SemiprimeMaterializedSourceRows.rowAuxiliary,\n    SemiprimeMaterializedSourceUniversal.entryPolynomial,\n    SemiprimePaidMeasurementBound.bits,SemiprimePaidRuntimeDesign.groupBudget,\n    SemiprimeEncodedRowSelection.budget,SemiprimeRowSelectionBits.runBudget,\n    SemiprimeRowSelectionBits.insertBudget,SemiprimeRowSelectionBits.residualRowBudget,\n    SemiprimeRowSelectionBits.normalizeRowBudget,SemiprimeRowSelectionBits.updateRowBudget,\n    SemiprimeRowSelectionBitArithmetic.residualBudget,\n    SemiprimeMaterializedSelectionTemporaries.selectorWidth,\n    SemiprimeMaterializedSelectionTemporaries.leafBits,\n    SemiprimeMaterializedSelectionTemporaries.residualBits,\n    SemiprimeMaterializedSelectionTemporaries.normalizeBits,\n    SemiprimeMaterializedSelectionTemporaries.updateBits]\n  gcongr\n\n/-- A larger common resource bound increases the same fixed setup polynomial. -/\ntheorem polynomialEnvelope_mono : Monotone polynomialEnvelope := by\n  intro S T h\n  exact setupBudget_le_envelope S S S S S S S S S T h h h h h h h h h\n\nend RiemannGaussian.SemiprimeSetupPolynomialEnvelope\n","RiemannGaussian.SemiprimeSourceArrayBackendBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceProgramStorage\n\n/-! # Numeric envelope for the executed source-array backend\nThis isolates monotonic resource substitution from all source syntax and interpreter\nterms. The two summands are exactly the acquisition and bit-work bounds.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceArrayBackendBudget\nopen SemiprimeReportPolynomialGrowth\n\n/-- Sum of the actual coefficient backend's two displayed work bounds. -/\ndef envelope (M T V b : ℕ) : ℕ :=\n  M*(8*(b+1)+16)+1+T*(8*(V+1)+17)+1+2*(b+1)+5+4*(V+1)+10+\n    (T*(SemiprimeSourceProgramBits.stepBudget V (b+1) (V+1)+3)+1+\n      (V+1)*(8*(b+1)+15*(V+1)+30)+2)\n\n/-- Monotonicity uses only four independent natural-number resources. -/\ntheorem envelope_mono {M T V b M' T' V' b' : ℕ}\n    (hM : M ≤ M') (hT : T ≤ T') (hV : V ≤ V') (hb : b ≤ b') :\n    envelope M T V b ≤ envelope M' T' V' b' := by\n  unfold envelope SemiprimeSourceProgramBits.stepBudget\n  gcongr\n\n/-- The diagonal has fixed monomial growth, with input-independent constants. -/\ntheorem diagonal_monomial : ∃ C k : ℕ, ∀ S, envelope S S S S ≤ C*(S+1)^k := by\n  change Bound (fun S => envelope S S S S)\n  simp only [envelope, SemiprimeSourceProgramBits.stepBudget]\n  boundArithmetic\n\nend RiemannGaussian.SemiprimeSourceArrayBackendBudget\n","RiemannGaussian.SemiprimeSourceArrayProgramGeneration":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceArrayProgramCompiler\nimport RiemannGaussian.SemiprimeMaterializedPacking\n\n/-! # Executed finite generation of cached source instruction blocks\nCached size metadata and fixed-shape output-ID arithmetic avoid a functional\nregister oracle. Literal scans and every code append copy retain their work.\nThe ledger is scalar/list metadata work, not a complete primitive-bit compiler.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 3000000\nnamespace RiemannGaussian.SemiprimeSourceArrayProgramGeneration\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT.SubexpRowInterpolation\nopen SemiprimeMaterializedSourceUniversal\nopen SemiprimeSourceArrayProgramIR SemiprimeSourceArrayProgramBlocks\nopen SemiprimeSourceArrayProgramCompiler\n\n/-- Actual recursive append, with each copied cons cell paid. -/\ndef append {α : Type*} : List α → List α → Run (List α)\n  | [],ys => ⟨ys,1⟩\n  | x::xs,ys => let tail := append xs ys; ⟨x::tail.value,tail.work+2⟩\n\n/-- Exact copied list and code generation stages. -/\ntheorem append_value_work {α : Type*} (xs ys : List α) :\n    (append xs ys).value=xs++ys ∧ (append xs ys).work=2*xs.length+1 := by\n  induction xs with\n  | nil => simp [append]\n  | cons x xs ih =>\n    simp only [append,ih.1,ih.2,List.cons_append,List.length_cons]\n    constructor\n    · trivial\n    · omega\n\n/-- Cached output-ID formula of one actual compiler node. -/\ninductive Shape where\n  | constant (value zeroId : ℕ)\n  | variable (oneId zeroId : ℕ)\n  | addition (start : ℕ)\n  | multiplication (start : ℕ)\n\n/-- The original simple arithmetic formula behind the output lookup. -/\ndef Shape.value : Shape → ℕ → ℕ\n  | .constant value zeroId,k => if k=0 then value else zeroId\n  | .variable oneId zeroId,k => if k=1 then oneId else zeroId\n  | .addition start,k => start+k\n  | .multiplication start,k => mulResult start k\n\n/-- Actual scalar metadata lookup, with every bounded arithmetic/branch stage retained. -/\ndef Shape.read (s : Shape) (k : ℕ) : Run ℕ :=\n  match s with\n  | .constant value zeroId => ⟨if k=0 then value else zeroId,2⟩\n  | .variable oneId zeroId => ⟨if k=1 then oneId else zeroId,2⟩\n  | .addition start => ⟨start+k,2⟩\n  | .multiplication start => ⟨start+(k+1)*(k+2)-1,6⟩\n\n/-- Every produced register map is computed, never queried as an arbitrary function. -/\ntheorem Shape.read_value (s : Shape) (k : ℕ) : (s.read k).value=s.value k := by cases s <;> rfl\n\n/-- Uniform original scalar-ID lookup cost. -/\ntheorem Shape.read_work (s : Shape) (k : ℕ) : (s.read k).work ≤ 6 := by cases s <;> simp [Shape.read]\n\n/-- Actual generated code, cached length, and retained generation work. -/\nstructure CodeRun where\n  /-- Constructed instruction list. -/\n  code : List Instruction\n  /-- Acquired length metadata. -/\n  size : ℕ\n  /-- Scalar/read/cons/copy generation stages. -/\n  work : ℕ\n  /-- Cached length is always the actual output length. -/\n  size_eq : size=code.length\n\n/-- Empty code still retains original leaf-lookup/control work. -/\ndef emptyCode (work : ℕ) : CodeRun := ⟨[],0,work,rfl⟩\n\n/-- Copy the actual first code list and retain both already acquired child reports. -/\ndef join (a b : CodeRun) : CodeRun :=\n  let out := append a.code b.code\n  ⟨out.value,a.size+b.size,a.work+b.work+out.work+3,by rw [(append_value_work _ _).1,List.length_append,← a.size_eq,← b.size_eq]⟩\n\n/-- Exact code and cached metadata from executed joining. -/\ntheorem join_code_size_work (a b : CodeRun) :\n    (join a b).code=a.code++b.code ∧ (join a b).size=a.size+b.size ∧\n      (join a b).work=a.work+b.work+2*a.size+4 := by\n  refine ⟨(append_value_work a.code b.code).1,rfl,?_⟩\n  simp only [join,(append_value_work _ _).2]\n  rw [← a.size_eq]\n  omega\n\n/-- Execute all coefficient-addition code generation, including both output-ID reads. -/\ndef addRun (a b : Shape) : ℕ → CodeRun\n  | 0 => emptyCode 1\n  | J+1 =>\n      let previous := addRun a b J\n      let left := a.read J\n      let right := b.read J\n      let one : CodeRun := ⟨[⟨.add,left.value,right.value⟩],1,left.work+right.work+10,rfl⟩\n      join previous one\n\n/-- The actual add generator emits precisely the compiler's coefficient block. -/\ntheorem addRun_code (a b : Shape) (J : ℕ) : (addRun a b J).code=addCode J a.value b.value := by\n  induction J with\n  | zero => rfl\n  | succ J ih =>\n    simp only [addRun,(join_code_size_work _ _).1,ih,Shape.read_value,addCode,List.range_succ,List.map_append,List.map_singleton]\n\n/-- Add generator length metadata is exact. -/\ntheorem addRun_size (a b : Shape) (J : ℕ) : (addRun a b J).size=J := by\n  rw [(addRun a b J).size_eq,addRun_code,addCode_length]\n\n/-- Actual addition-code generation has quadratic scalar/list work. -/\ntheorem addRun_work (a b : Shape) (J : ℕ) : (addRun a b J).work ≤ 60*(J+1)^2 := by\n  induction J with\n  | zero => norm_num [addRun,emptyCode]\n  | succ J ih =>\n    have hl := a.read_work J\n    have hr := b.read_work J\n    simp only [addRun,(join_code_size_work _ _).2.2,addRun_size]\n    nlinarith\n\n/-- Generate both operations per actual dot prefix, with paid cached-ID arithmetic. -/\ndef dotRun (zeroId start k : ℕ) (a b : Shape) : ℕ → CodeRun\n  | 0 => emptyCode 1\n  | len+1 =>\n      let previous := dotRun zeroId start k a b len\n      let left := a.read len\n      let right := b.read (k-len)\n      let pair : CodeRun :=\n        ⟨[⟨.mul,left.value,right.value⟩,⟨.add,start+2*len,accumulator zeroId start len⟩],\n          2,left.work+right.work+20,rfl⟩\n      join previous pair\n\n/-- The generated scalar dot code is exactly the original stable-ID block. -/\ntheorem dotRun_code (zeroId start k : ℕ) (a b : Shape) (len : ℕ) :\n    (dotRun zeroId start k a b len).code=dotCode zeroId start k a.value b.value len := by\n  induction len with\n  | zero => rfl\n  | succ len ih => simp only [dotRun,(join_code_size_work _ _).1,ih,Shape.read_value,dotCode]\n\n/-- Dot generation caches its exact size. -/\ntheorem dotRun_size (zeroId start k : ℕ) (a b : Shape) (len : ℕ) :\n    (dotRun zeroId start k a b len).size=2*len := by\n  rw [(dotRun zeroId start k a b len).size_eq,dotRun_code,dotCode_length]\n\n/-- Paid dot-code generation has quadratic work, including append traversal. -/\ntheorem dotRun_work (zeroId start k : ℕ) (a b : Shape) (len : ℕ) :\n    (dotRun zeroId start k a b len).work ≤ 80*(len+1)^2 := by\n  induction len with\n  | zero => norm_num [dotRun,emptyCode]\n  | succ len ih =>\n    have hl := a.read_work len\n    have hr := b.read_work (k-len)\n    simp only [dotRun,(join_code_size_work _ _).2.2,dotRun_size]\n    nlinarith\n\n/-- Generate cached full-array convolution once, not a per-coefficient source-AST expansion. -/\ndef mulRun (zeroId start : ℕ) (a b : Shape) : ℕ → CodeRun\n  | 0 => emptyCode 1\n  | J+1 =>\n      let previous := mulRun zeroId start a b J\n      let dot := dotRun zeroId (start+previous.size) J a b (J+1)\n      join previous dot\n\n/-- Actual convolution generator matches its scalar instruction semantics. -/\ntheorem mulRun_code (zeroId start : ℕ) (a b : Shape) (J : ℕ) :\n    (mulRun zeroId start a b J).code=mulCode zeroId start a.value b.value J := by\n  induction J with\n  | zero => rfl\n  | succ J ih =>\n    simp only [mulRun,(join_code_size_work _ _).1,dotRun_code,ih,mulCode]\n    rw [(mulRun zeroId start a b J).size_eq,ih]\n\n/-- Exact metadata length of actual convolution code. -/\ntheorem mulRun_size (zeroId start : ℕ) (a b : Shape) (J : ℕ) :\n    (mulRun zeroId start a b J).size=J*(J+1) := by\n  rw [(mulRun zeroId start a b J).size_eq,mulRun_code,mulCode_length]\n\n/-- Full convolution-code generation has a fixed cubic list/scalar bound. -/\ntheorem mulRun_work (zeroId start : ℕ) (a b : Shape) (J : ℕ) :\n    (mulRun zeroId start a b J).work ≤ 200*(J+1)^3 := by\n  induction J with\n  | zero => norm_num [mulRun,emptyCode]\n  | succ J ih =>\n    have hd := dotRun_work zeroId (start+(mulRun zeroId start a b J).size) J a b (J+1)\n    rw [mulRun_size] at hd\n    simp only [mulRun,(join_code_size_work _ _).2.2,mulRun_size]\n    nlinarith\n\n/-- Acquired cached code and a concrete finite output-ID descriptor. -/\nstructure Acquired where\n  /-- Actual constructed code and retained stages. -/\n  compiled : CodeRun\n  /-- Output IDs have one of four original compiler-node formulas. -/\n  shape : Shape\n\n/-- Mathematical block view consumed by the verified compiler/refinement. -/\ndef Acquired.block (a : Acquired) : Block := ⟨a.compiled.code,a.shape.value⟩\n\n/-- Cached metadata is exactly the actual block length. -/\ntheorem Acquired.size_eq_block (a : Acquired) : a.compiled.size=a.block.code.length := a.compiled.size_eq\n\n/-- Additional finite control/metadata stages, with the same acquired code. -/\ndef bump (n : ℕ) (a : CodeRun) : CodeRun := ⟨a.code,a.size,a.work+n,a.size_eq⟩\n\n/-- Assemble one actual addition node after both children have been acquired. -/\ndef assembleAdd (J next : ℕ) (a b : Acquired) : Acquired :=\n  let children := join a.compiled b.compiled\n  let start := next+children.size\n  let out := addRun a.shape b.shape J\n  ⟨bump 10 (join children out),.addition start⟩\n\n/-- Assemble one actual convolution node after both children have been acquired. -/\ndef assembleMul (J zeroId next : ℕ) (a b : Acquired) : Acquired :=\n  let children := join a.compiled b.compiled\n  let start := next+children.size\n  let out := mulRun zeroId start a.shape b.shape J\n  ⟨bump 10 (join children out),.multiplication start⟩\n\n/-- Exact projection of actual cached addition assembly. -/\ntheorem assembleAdd_block (J next : ℕ) (a b : Acquired) :\n    (assembleAdd J next a b).block=\n      (let combined := a.block.code++b.block.code\n       let start := next+combined.length\n       (⟨combined++addCode J a.block.output b.block.output,fun k => start+k⟩ : Block)) := by\n  simp only [assembleAdd,Acquired.block,bump,(join_code_size_work _ _).1,\n    (join_code_size_work _ _).2.1,addRun_code]\n  rw [a.compiled.size_eq,b.compiled.size_eq,List.length_append]\n  rfl\n\n/-- Exact projection of actual cached convolution assembly. -/\ntheorem assembleMul_block (J zeroId next : ℕ) (a b : Acquired) :\n    (assembleMul J zeroId next a b).block=\n      (let combined := a.block.code++b.block.code\n       let start := next+combined.length\n       (⟨combined++mulCode zeroId start a.block.output b.block.output J,fun k => mulResult start k⟩ : Block)) := by\n  simp only [assembleMul,Acquired.block,bump,(join_code_size_work _ _).1,\n    (join_code_size_work _ _).2.1,mulRun_code]\n  rw [a.compiled.size_eq,b.compiled.size_eq,List.length_append]\n  rfl\n\n/-- Actual AST traversal, using a cached original literal menu and paid finite scans. -/\ndef acquire (J zeroId oneId next : ℕ) (cache : List ℚ) : PolynomialCode ℚ → Acquired\n  | .constant c =>\n      let found := SemiprimeMaterializedPacking.position c cache\n      ⟨emptyCode (found.work+5),.constant (found.value+2) zeroId⟩\n  | .indeterminate => ⟨emptyCode 3,.variable oneId zeroId⟩\n  | .add p q =>\n      let left := acquire J zeroId oneId next cache p\n      let right := acquire J zeroId oneId (next+left.compiled.size) cache q\n      assembleAdd J next left right\n  | .mul p q =>\n      let left := acquire J zeroId oneId next cache p\n      let right := acquire J zeroId oneId (next+left.compiled.size) cache q\n      assembleMul J zeroId next left right\n\n/-- The actual generator computes the SAME code and registers, never a supplied program. -/\ntheorem acquire_block (J zeroId oneId next : ℕ) (cache : List ℚ) (p : PolynomialCode ℚ) :\n    (acquire J zeroId oneId next cache p).block=\n      compile J zeroId oneId next (fun c => 2+cache.idxOf c) p := by\n  induction p generalizing next with\n  | constant c =>\n    simp only [acquire,Acquired.block,emptyCode,\n      SemiprimeMaterializedPacking.position_value,compile]\n    congr 1\n    funext k\n    change (if k=0 then cache.idxOf c+2 else zeroId)=(if k=0 then 2+cache.idxOf c else zeroId)\n    split_ifs <;> omega\n  | indeterminate => rfl\n  | add p q hp hq =>\n    rw [acquire,assembleAdd_block,Acquired.size_eq_block,hp,hq]\n    rfl\n  | mul p q hp hq =>\n    rw [acquire,assembleMul_block,Acquired.size_eq_block,hp,hq]\n    rfl\n\n/-- Actual syntax-leaf collection, paying every append traversal and cons. -/\ndef constantsRun : PolynomialCode ℚ → Run (List ℚ)\n  | .constant c => ⟨[c],2⟩\n  | .indeterminate => ⟨[],1⟩\n  | .add p q =>\n      let a := constantsRun p\n      let b := constantsRun q\n      let out := append a.value b.value\n      ⟨out.value,a.work+b.work+out.work+2⟩\n  | .mul p q =>\n      let a := constantsRun p\n      let b := constantsRun q\n      let out := append a.value b.value\n      ⟨out.value,a.work+b.work+out.work+2⟩\n\n/-- The acquired literal cache is exactly the original traversal order. -/\ntheorem constantsRun_value (p : PolynomialCode ℚ) : (constantsRun p).value=constants p := by\n  induction p with\n  | constant c => rfl\n  | indeterminate => rfl\n  | add p q hp hq => simp only [constantsRun,(append_value_work _ _).1,hp,hq,constants]\n  | mul p q hp hq => simp only [constantsRun,(append_value_work _ _).1,hp,hq,constants]\n\n/-- Returned generator record, with original constants and every construction report retained. -/\nstructure Generated where\n  /-- Actual acquired original bank. -/\n  bank : List ℚ\n  /-- Actual acquired generated code and cached output-ID descriptor. -/\n  result : Acquired\n  /-- Complete bank/code generation ledger. -/\n  work : ℕ\n\n/-- Actual generated block view. -/\ndef Generated.block (g : Generated) : Block := g.result.block\n\n/-- Acquire the original literal cache ONCE, then generate the cached AST code. -/\ndef generate (J : ℕ) (p : PolynomialCode ℚ) : Generated :=\n  let literals := constantsRun p\n  let inputs := 0::1::literals.value\n  let result := acquire J 0 1 (literals.value.length+2) literals.value p\n  ⟨inputs,result,literals.work+result.compiled.work+literals.value.length+7⟩\n\n/-- The actual generator exposes the original input bank, not external constant advice. -/\ntheorem generate_bank (J : ℕ) (p : PolynomialCode ℚ) : (generate J p).bank=bank p := by\n  simp only [generate,constantsRun_value,bank]\n\n/-- The actual generated code/registers equal the fully initialized original compiler. -/\ntheorem generate_block (J : ℕ) (p : PolynomialCode ℚ) : (generate J p).block=program J p := by\n  simp only [generate,Generated.block,acquire_block,constantsRun_value,program]\n  rw [bank_length]\n  congr 1\n  omega\n\n/-- Exact scalar/list stage split of actual addition assembly. -/\ntheorem assembleAdd_work (J next : ℕ) (a b : Acquired) :\n    (assembleAdd J next a b).compiled.work=\n      a.compiled.work+b.compiled.work+(addRun a.shape b.shape J).work+\n        4*a.compiled.size+2*b.compiled.size+18 := by\n  simp only [assembleAdd,bump,(join_code_size_work _ _).2.2,(join_code_size_work _ _).2.1]\n  ring\n\n/-- Exact scalar/list stage split of actual convolution assembly. -/\ntheorem assembleMul_work (J zeroId next : ℕ) (a b : Acquired) :\n    (assembleMul J zeroId next a b).compiled.work=\n      a.compiled.work+b.compiled.work+\n        (mulRun zeroId (next+(a.compiled.size+b.compiled.size)) a.shape b.shape J).work+\n        4*a.compiled.size+2*b.compiled.size+18 := by\n  simp only [assembleMul,bump,(join_code_size_work _ _).2.2,(join_code_size_work _ _).2.1]\n  ring\n\n/-- Actual generated lengths are bounded by original syntax, independent of register values. -/\ntheorem acquire_size_bound (J zeroId oneId next : ℕ) (cache : List ℚ) (p : PolynomialCode ℚ) :\n    (acquire J zeroId oneId next cache p).compiled.size ≤\n      SemiprimeSourceCodeArrays.nodes p*(J*(J+1)+J) := by\n  rw [Acquired.size_eq_block,acquire_block]\n  exact compile_code_length _ _ _ _ _ _\n\n/-- Collecting the original constant cache has a quadratic actual traversal/copy budget. -/\ntheorem constantsRun_work (p : PolynomialCode ℚ) :\n    (constantsRun p).work ≤ 5*(SemiprimeSourceCodeArrays.nodes p)^2 := by\n  induction p with\n  | constant c => norm_num [constantsRun,SemiprimeSourceCodeArrays.nodes]\n  | indeterminate => norm_num [constantsRun,SemiprimeSourceCodeArrays.nodes]\n  | add p q hp hq =>\n    have hl := constants_length_le p\n    simp only [constantsRun,(append_value_work _ _).2,constantsRun_value,SemiprimeSourceCodeArrays.nodes]\n    nlinarith [Nat.zero_le (SemiprimeSourceCodeArrays.nodes p*SemiprimeSourceCodeArrays.nodes q)]\n  | mul p q hp hq =>\n    have hl := constants_length_le p\n    simp only [constantsRun,(append_value_work _ _).2,constantsRun_value,SemiprimeSourceCodeArrays.nodes]\n    nlinarith [Nat.zero_le (SemiprimeSourceCodeArrays.nodes p*SemiprimeSourceCodeArrays.nodes q)]\n\n/-- One original-size allowance for all node-local scans, copies and scalar code construction. -/\ndef unitWork (J L N : ℕ) : ℕ :=\n  3*L+6+6*N*(J*(J+1)+J)+300*(J+1)^3+50\n\n/-- Actual compiler construction has a fixed polynomial bound with no instruction-answer advice. -/\ntheorem acquire_work (J zeroId oneId next : ℕ) (cache : List ℚ) (p : PolynomialCode ℚ)\n    (N : ℕ) (hN : SemiprimeSourceCodeArrays.nodes p ≤ N) :\n    (acquire J zeroId oneId next cache p).compiled.work ≤\n      SemiprimeSourceCodeArrays.nodes p*unitWork J cache.length N := by\n  induction p generalizing next with\n  | constant c =>\n    have h := SemiprimeMaterializedPacking.position_work c cache\n    simp only [acquire,emptyCode,SemiprimeSourceCodeArrays.nodes]\n    unfold unitWork\n    omega\n  | indeterminate =>\n    simp only [acquire,emptyCode,SemiprimeSourceCodeArrays.nodes]\n    unfold unitWork\n    omega\n  | add p q hp hq =>\n    have hnP : SemiprimeSourceCodeArrays.nodes p ≤ N := by simp only [SemiprimeSourceCodeArrays.nodes] at hN;omega\n    have hnQ : SemiprimeSourceCodeArrays.nodes q ≤ N := by simp only [SemiprimeSourceCodeArrays.nodes] at hN;omega\n    let a := acquire J zeroId oneId next cache p\n    let b := acquire J zeroId oneId (next+a.compiled.size) cache q\n    have hl := hp next hnP\n    have hr := hq (next+a.compiled.size) hnQ\n    have hls : a.compiled.size ≤ N*(J*(J+1)+J) :=\n      (acquire_size_bound J zeroId oneId next cache p).trans (Nat.mul_le_mul_right _ hnP)\n    have hrs : b.compiled.size ≤ N*(J*(J+1)+J) :=\n      (acquire_size_bound J zeroId oneId (next+a.compiled.size) cache q).trans (Nat.mul_le_mul_right _ hnQ)\n    have ho := addRun_work a.shape b.shape J\n    have hpow : (J+1)^2 ≤ (J+1)^3 := Nat.pow_le_pow_right (by omega) (by decide)\n    have hunit : (addRun a.shape b.shape J).work+4*a.compiled.size+2*b.compiled.size+18 ≤ unitWork J cache.length N := by\n      unfold unitWork\n      nlinarith\n    change (assembleAdd J next a b).compiled.work ≤ _\n    rw [assembleAdd_work]\n    simp only [SemiprimeSourceCodeArrays.nodes]\n    change a.compiled.work ≤ _ at hl\n    change b.compiled.work ≤ _ at hr\n    nlinarith\n  | mul p q hp hq =>\n    have hnP : SemiprimeSourceCodeArrays.nodes p ≤ N := by simp only [SemiprimeSourceCodeArrays.nodes] at hN;omega\n    have hnQ : SemiprimeSourceCodeArrays.nodes q ≤ N := by simp only [SemiprimeSourceCodeArrays.nodes] at hN;omega\n    let a := acquire J zeroId oneId next cache p\n    let b := acquire J zeroId oneId (next+a.compiled.size) cache q\n    have hl := hp next hnP\n    have hr := hq (next+a.compiled.size) hnQ\n    have hls : a.compiled.size ≤ N*(J*(J+1)+J) :=\n      (acquire_size_bound J zeroId oneId next cache p).trans (Nat.mul_le_mul_right _ hnP)\n    have hrs : b.compiled.size ≤ N*(J*(J+1)+J) :=\n      (acquire_size_bound J zeroId oneId (next+a.compiled.size) cache q).trans (Nat.mul_le_mul_right _ hnQ)\n    have ho := mulRun_work zeroId (next+(a.compiled.size+b.compiled.size)) a.shape b.shape J\n    have hunit : (mulRun zeroId (next+(a.compiled.size+b.compiled.size)) a.shape b.shape J).work+\n        4*a.compiled.size+2*b.compiled.size+18 ≤ unitWork J cache.length N := by\n      unfold unitWork\n      nlinarith\n    change (assembleMul J zeroId next a b).compiled.work ≤ _\n    rw [assembleMul_work]\n    simp only [SemiprimeSourceCodeArrays.nodes]\n    change a.compiled.work ≤ _ at hl\n    change b.compiled.work ≤ _ at hr\n    nlinarith\n\n/-- A literal fixed polynomial for complete original syntax/bank/code acquisition. -/\ndef generationBudget (J N : ℕ) : ℕ := 5*N^2+N*unitWork J N N+N+7\n\n/-- The actual original-only generator includes all constant scans and cached-code construction. -/\ntheorem generate_work (J : ℕ) (p : PolynomialCode ℚ) :\n    (generate J p).work ≤ generationBudget J (SemiprimeSourceCodeArrays.nodes p) := by\n  have hc := constantsRun_work p\n  have hl := constants_length_le p\n  have ha := acquire_work J 0 1 ((constants p).length+2) (constants p) p\n    (SemiprimeSourceCodeArrays.nodes p) le_rfl\n  have hu : unitWork J (constants p).length (SemiprimeSourceCodeArrays.nodes p) ≤\n      unitWork J (SemiprimeSourceCodeArrays.nodes p) (SemiprimeSourceCodeArrays.nodes p) := by\n    unfold unitWork\n    omega\n  have ha' := ha.trans (Nat.mul_le_mul_left _ hu)\n  simp only [generate,constantsRun_value]\n  unfold generationBudget\n  omega\n\nend RiemannGaussian.SemiprimeSourceArrayProgramGeneration\n","RiemannGaussian.SemiprimeSourceClassifiedCaller":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceClassifiedSearch\nimport RiemannGaussian.SemiprimeSourceWordIdMetadata\nimport RiemannGaussian.SemiprimeSourceScorePhysicalCaller\n\n/-! # Original indexed inputs to source labels without local completion enumeration\nMetadata is constructed from original dimensions/arities, descriptors are\nactually compiled, and the acquired bank/ID controller supplies the labels.\nNo native source word, decoded prefix, advised menu or score is a runtime input.\nNative original arity/owner/index/descriptor operations retain their own ledger.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1800000\nnamespace RiemannGaussian.SemiprimeSourceClassifiedCaller\nopen SemiprimeMaterializedWords SemiprimeSourceWordBankSemantics\n\n/-- Construct original metadata and score descriptors before the actual acquired-ID search. -/\ndef indexed (n F r Q lam : ℕ) (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) : Run (List (List Bool)) :=\n  let metadata := SemiprimeSourceWordIdMetadata.acquire n F Q arity\n  let compiled := SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst metadata.indices metadata.terms\n  let result := SemiprimeSourceClassifiedSearch.run metadata.incidences.length n r Q lam compiled.value metadata.indices.length\n  ⟨result.value,metadata.clock+compiled.work+result.work+3⟩\n\n/-- All actual stored labels remain acquired candidate IDs, without a decoder on runtime. -/\ntheorem indexed_valid (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) :\n    SemiprimeSourceWordIdControl.InMenu (SemiprimeSourceWordBank.acquire r Q).ids\n      (indexed n F r Q lam arity owner).value := by\n  exact SemiprimeSourceClassifiedSearch.run_valid _ n r Q lam _ _\n\n/-- Physically selected IDs decode to the EXACT previously proved original source\ncaller result; both candidate order and every left-on-tie decision are retained. -/\ntheorem indexed_refines (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) (hlam : 0 < lam) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    (indexed n F r Q lam arity owner).value.map (decode r Q)=\n      (SemiprimeSourceScorePhysicalCaller.computed owner Sigma.fst en lam).value := by\n  let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n  have fields := SemiprimeSourceWordIdMetadata.indexed_fields n F r Q arity\n  change (SemiprimeSourceClassifiedSearch.run\n      (SemiprimeSourceWordIdMetadata.acquire n F Q arity).incidences.length n r Q lam\n      (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst\n        (SemiprimeSourceWordIdMetadata.acquire n F Q arity).indices\n        (SemiprimeSourceWordIdMetadata.acquire n F Q arity).terms).value\n      (SemiprimeSourceWordIdMetadata.acquire n F Q arity).indices.length).value.map (decode r Q)=_\n  rw [fields.1,fields.2.1,fields.2.2]\n  let programs := (SemiprimeMaterializedSourceWords.compileAll owner Sigma.fst en.indices.values en.terms.values).value\n  have hsep := SemiprimeSourceIncidenceNamespaces.compileAll_separated owner Sigma.fst\n    en.indices.values en.indices.complete en.terms.values\n  have hnew := SemiprimeSourceClassifiedSearch.run_refines en.incidences.values.length n F r Q lam arity\n    programs en.indices.values.length 0 hsep hlam\n  have hcard := SemiprimeSourceScoreCountOrder.caller_cardinality en\n  rw [SemiprimeSourceOffsetHeight.caller_universal_length] at hcard\n  have hold := SemiprimeSourceScorePhysicalSearch.run_refines en.incidences.values.length n lam\n    en.wordFirst en.wordTail programs en.indices.values.length 0 (NeZero.pos r) hlam hcard\n  exact hnew.trans hold.symm\n\n/-- Direct original scalar-source comparison, with any shared offset appearing only in proof. -/\ntheorem indexed_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) (hlam : 0 < lam) (offset : ℚ) :\n    let en := (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value\n    (indexed n F r Q lam arity owner).value.map (decode r Q)=\n      (SemiprimeMaterializedSourceWords.computedList owner Sigma.fst en.wordFirst en.wordTail\n        en.terms.values en.indices.values (SemiprimeSourceScorePhysicalCaller.originalX en lam)\n        ((n:ℚ)/(2*(r:ℚ))) offset).value :=\n  (indexed_refines n F r Q lam arity owner hlam).trans\n    (SemiprimeSourceScorePhysicalCaller.computed_refines owner Sigma.fst\n      (SemiprimePaidFiniteEnumerations.indexed n F r Q arity).value lam hlam offset)\n\nend RiemannGaussian.SemiprimeSourceClassifiedCaller\n","RiemannGaussian.SemiprimeSourceClassifiedResources":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceClassifiedSearchBudget\n\n/-! # Uniform original-resource bound for the actual acquired-ID source caller\nOnly original dimension caps occur in the final executed-report theorem. No unary universal-alphabet initialization is used. All\nconstants in the diagonal monomial precede the entire family of original inputs.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nset_option maxRecDepth 8192\nnamespace RiemannGaussian.SemiprimeSourceClassifiedResources\nopen scoped BigOperators\nopen SemiprimeReportPolynomialGrowth\n\n/-- Actual complete original-caller budget is monotone in its nine independent resources. -/\ntheorem indexedBudget_mono {n F r Q lam M L T N n' F' r' Q' lam' M' L' T' N' : ℕ}\n    (hn : n≤n') (hF : F≤F') (hr : r≤r') (hQ : Q≤Q') (hlam : lam≤lam')\n    (hM : M≤M') (hL : L≤L') (hT : T≤T') (hN : N≤N') :\n    SemiprimeSourceClassifiedSearchBudget.indexedBudget n F r Q lam M L T N ≤\n      SemiprimeSourceClassifiedSearchBudget.indexedBudget n' F' r' Q' lam' M' L' T' N' := by\n  simp only [SemiprimeSourceClassifiedSearchBudget.indexedBudget,\n    SemiprimeSourceClassifiedSearchBudget.runBudget,SemiprimeSourceClassifiedSearchBudget.controlBudget,\n    SemiprimeSourceClassifiedSearchBudget.wordCap,SemiprimeSourceClassifiedSearchBudget.weightCap,\n    SemiprimeSourceWordIdMetadata.budget,SemiprimePaidFiniteEnumerations.incidenceBudget,\n    SemiprimePaidFiniteEnumerations.scoreBudget,SemiprimeSourceWordBankAcquisitionBudget.budget,\n    SemiprimeSourceWordBankAcquisitionBudget.colourBudget,SemiprimeSourceWordBankAcquisitionBudget.rowStage,\n    SemiprimeSourceCountPowers.budget,SemiprimeSourceCountPowers.stepBudget,SemiprimeSourceCountPowers.width,\n    SemiprimeSourceClassifiedWeights.budget,SemiprimeSourceClassifiedWeights.inputWidth,\n    SemiprimeSourceScoreWeightBits.weightWidth,SemiprimeSourceScoreWeightBits.weightBudget,\n    SemiprimeSourceScoreWeightBits.combineBudget,SemiprimeSourceClassifiedCountsClock.operandWidth,\n    SemiprimeSourceClassifiedCountsClock.laneWidth,SemiprimeSourceClassifiedCountsClock.scoreBudget,\n    SemiprimeSourceClassifiedCountsClock.sequentialBudget,SemiprimeSourceClassifiedCountsClock.evaluateBudget,\n    SemiprimeSourceClassifiedCountsClock.localBudget,SemiprimeSourceHeadCountBitsBounds.budget,\n    SemiprimeSourceIncidenceCountBitsBounds.countBudget,SemiprimeSourceIncidenceCountBitsBounds.edgeBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n  gcongr\n\n/-- Diagonal bound of the ACTUAL displayed original-input caller budget. -/\ndef envelope (S : ℕ) : ℕ :=\n  SemiprimeSourceClassifiedSearchBudget.indexedBudget S S S S S S S S S\n\n/-- Controller majorant replaces only the sole truncated tail length by its full length. -/\ndef controllerMajorant (S : ℕ) : ℕ :=\n  2*S+3+S*(S*(2*SemiprimeSourceClassifiedCountsClock.scoreBudget S S S S S\n    (SemiprimeSourceClassifiedSearchBudget.weightCap S S S S S)+\n    200*(SemiprimeSourceClassifiedSearchBudget.wordCap S S S S S S+1)^2+4*(2*S)+5)+\n    4*(2*S)+2+S*(4*(2*S)+4)+4)+S*(4*(2*S)+4)+1\n\n/-- Subtraction-free diagonal with exactly the same acquired bank/weight/callback costs. -/\ndef diagonalMajorant (S : ℕ) : ℕ :=\n  SemiprimeSourceWordIdMetadata.budget S S S S+S*(8*S+15)+1+\n    (SemiprimeSourceWordBankAcquisitionBudget.budget S S S+\n      SemiprimeSourceCountPowers.budget S S+\n      SemiprimeSourceClassifiedWeights.budget S S S S S+\n      controllerMajorant S+S+7)+3\n\n/-- Replacing S-1 by S never discards any actual work. -/\ntheorem envelope_le_majorant (S : ℕ) : envelope S≤diagonalMajorant S := by\n  unfold envelope diagonalMajorant controllerMajorant\n    SemiprimeSourceClassifiedSearchBudget.indexedBudget SemiprimeSourceClassifiedSearchBudget.runBudget\n    SemiprimeSourceClassifiedSearchBudget.controlBudget\n  gcongr\n  omega\n\n/-- A fixed monomial bounds the full actual-family resource envelope. -/\ntheorem envelope_monomial : ∃ C k : ℕ,∀ S,envelope S≤C*(S+1)^k := by\n  have hp : Bound diagonalMajorant := by\n    change Bound (fun S => diagonalMajorant S)\n    simp only [diagonalMajorant,controllerMajorant,SemiprimeSourceClassifiedSearchBudget.wordCap,SemiprimeSourceClassifiedSearchBudget.weightCap,\n    SemiprimeSourceWordIdMetadata.budget,SemiprimePaidFiniteEnumerations.incidenceBudget,\n    SemiprimePaidFiniteEnumerations.scoreBudget,SemiprimeSourceWordBankAcquisitionBudget.budget,\n    SemiprimeSourceWordBankAcquisitionBudget.colourBudget,SemiprimeSourceWordBankAcquisitionBudget.rowStage,\n    SemiprimeSourceCountPowers.budget,SemiprimeSourceCountPowers.stepBudget,SemiprimeSourceCountPowers.width,\n    SemiprimeSourceClassifiedWeights.budget,SemiprimeSourceClassifiedWeights.inputWidth,\n    SemiprimeSourceScoreWeightBits.weightWidth,SemiprimeSourceScoreWeightBits.weightBudget,\n    SemiprimeSourceScoreWeightBits.combineBudget,SemiprimeSourceClassifiedCountsClock.operandWidth,\n    SemiprimeSourceClassifiedCountsClock.laneWidth,SemiprimeSourceClassifiedCountsClock.scoreBudget,\n    SemiprimeSourceClassifiedCountsClock.sequentialBudget,SemiprimeSourceClassifiedCountsClock.evaluateBudget,\n    SemiprimeSourceClassifiedCountsClock.localBudget,SemiprimeSourceHeadCountBitsBounds.budget,\n    SemiprimeSourceIncidenceCountBitsBounds.countBudget,SemiprimeSourceIncidenceCountBitsBounds.edgeBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalBudget,SemiprimeSourceWordIdPredicateBounds.programBudget,\n    SemiprimeSourceWordIdPredicateBounds.terminalStepBudget,SemiprimeSourceWordIdPredicateBounds.bankReadBudget,\n    SemiprimeSourceWordIdPredicateBounds.colourReadBudget,SemiprimeSourceWordIdEnvironmentBounds.readBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.keyBudget,SemiprimeSourceWordIdEnvironmentBounds.idCopyBudget,\n    SemiprimeSourceWordIdEnvironmentBounds.scanStep,SemiprimeSourceWordIdEnvironmentBounds.eqBudget,\n    SemiprimeSourceScorePredicateBitsBounds.copyBudget,SemiprimeSourceScorePredicateBitsBounds.equalityBudget]\n    boundArithmetic\n  obtain ⟨C,k,h⟩ := hp\n  exact ⟨C,k,fun S => (envelope_le_majorant S).trans (h S)⟩\n\n/-- The actual original indexed caller is uniformly bounded using only original\nnetwork/alphabet/descriptor dimensions, without a report/word/output oracle. -/\ntheorem indexed_report_actual (n F r Q lam : ℕ) [NeZero r] (arity : Fin F → ℕ)\n    (owner : ((e : Fin F) × Fin (arity e)) → Fin n) (S : ℕ)\n    (hn : n≤S) (hF : F≤S) (hr : r≤S) (hQ : Q≤S) (hlam : lam≤S)\n    (hM : (∑ e,arity e)≤S) (hL : r^Q≤S)\n    (hT : (∑ e,arity e)^2+Q*n^2≤S) (hN : n+F≤S) :\n    (SemiprimeSourceClassifiedCaller.indexed n F r Q lam arity owner).work≤envelope S := by\n  exact (SemiprimeSourceClassifiedSearchBudget.indexed_work n F r Q lam arity owner).trans\n    (indexedBudget_mono hn hF hr hQ hlam hM hL hT hN)\n\nend RiemannGaussian.SemiprimeSourceClassifiedResources\n","RiemannGaussian.SemiprimeSourceHistogramQueryBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramQuery\nimport RiemannGaussian.SemiprimeSourceHistogramSetupBounds\nimport RiemannGaussian.SemiprimeSourceHistogramArithmeticBounds\nimport RiemannGaussian.SemiprimeSourceHistogramFeatureBitsBounds\nimport RiemannGaussian.SemiprimeSourceHistogramHeadBounds\n\n/-! # Actual original histogram-query width and clock\nAll sixteen feature passes, the all-coordinate head pass, signed arithmetic,\nand one actual prefix dictionary are paid. Setup is separately retained; no\nhistogram, Fits, output-width, callback-clock or native count advice is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 2400000\nnamespace RiemannGaussian.SemiprimeSourceHistogramQueryBounds\nopen scoped BigOperators\nopen SemiprimeBitArithmetic SemiprimeRationalBits\nopen SemiprimeSourceHistogramQuery\nopen SemiprimeSourceHistogramArithmeticBounds\nopen SemiprimeSourceIncidenceHistogram (Feature)\n\n/-- Original logarithmic acquired-input widths, before fixed-depth score arithmetic. -/\ndef baseWidth (n M r Q lam : ℕ) : ℕ := 1+\n  Nat.clog 2 (r^Q+1)+Nat.clog 2 ((r^Q)^2+1)+Nat.clog 2 ((r^Q)^4+1)+\n  Nat.clog 2 (r^(4*Q-1)+1)+Nat.clog 2 (n^2*lam^2*(r^Q)^4+1)+\n  Nat.clog 2 (4*M^2+1)+Nat.clog 2 (M^2+1)+Nat.clog 2 ((Q*n)^2+1)+\n  Nat.clog 2 (Q+1)+Nat.clog 2 (n+2)\n\n/-- Actual incidence/head output shape fits this fixed-depth acquired-width envelope. -/\ndef laneWidth (n M r Q lam : ℕ) : ℕ := grow (baseWidth n M r Q lam) 20\n\n/-- Actual final signed score shape, independent of histogram values. -/\ndef outputWidth (n M r Q lam : ℕ) : ℕ := grow (laneWidth n M r Q lam) 2\n\nprivate theorem base_caps (n M r Q lam : ℕ) :\n    1 ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (r^Q+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 ((r^Q)^2+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 ((r^Q)^4+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (r^(4*Q-1)+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (n^2*lam^2*(r^Q)^4+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (4*M^2+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (M^2+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 ((Q*n)^2+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (Q+1) ≤ baseWidth n M r Q lam ∧\n    Nat.clog 2 (n+2) ≤ baseWidth n M r Q lam := by\n  unfold baseWidth\n  omega\n\n/-- Complete prefix construction from actual selected IDs, without native ID encoding. -/\ndef prefixBudget (L k : ℕ) : ℕ :=\n  k*(100*(Nat.clog 2 (L+1)+SemiprimeSourceHistogramTrieBounds.clockWidth k+2))+1\n\n/-- Complete per-query report, separate from the once-acquired setup producer.\nThe only incidence count is M; there is no M²+Q*n² descriptor construction. -/\ndef scoreBudget (n F M r Q lam k : ℕ) : ℕ :=\n  prefixBudget (r^Q) k+\n  16*SemiprimeSourceHistogramFeatureBitsBounds.budget (n+F) (r^Q) M+\n  SemiprimeSourceHistogramHeadBounds.budget r Q (SemiprimeSourceHistogramPortKeys.keyWidth n) n+\n  90*unitBudget (baseWidth n M r Q lam)+3*unitBudget (laneWidth n M r Q lam)+k+10\n\n/-- Actual sparse original port-list size discharges the query's M parameter. -/\ntheorem records_length (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).data.records.length=∑ e,arity e := by\n  rw [SemiprimeSourceHistogramSetup.records_actual,\n    SemiprimeSourceHistogramPortKeys.acquirePorts_value,List.length_map]\n  exact (SemiprimeSourceHistogramMetadata.sizes n F Q arity).2.2.1\n\n/-- Original head cache is the actual complete original vertex list, not an advised scan. -/\ntheorem vertices_actual (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).vertices=\n      (SemiprimeSourceHistogramHeadBits.verticesWith (List.finRange n)).value := by\n  change (SemiprimeSourceHistogramHeadBits.verticesWith\n    (SemiprimeSourceHistogramPortKeys.acquireOriginal n F Q arity owner).metadata.vertices).value=_\n  rw [SemiprimeSourceHistogramPortKeys.acquireOriginal_metadata]\n  simp only [SemiprimeSourceHistogramMetadata.acquire,SemiprimeSourceHistogramMetadata.finFast_value]\n\n/-- Original list counting gives the actual compact coordinate operand width. -/\ntheorem coordinate_length (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).coordinateCount.length ≤\n      Nat.clog 2 (Q+1) := by\n  have h := SemiprimeSourceHistogramCountInput.count_length\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).data.metadata.coordinates\n  rw [SemiprimeSourceHistogramSetup.metadata_actual,\n    (SemiprimeSourceHistogramMetadata.sizes n F Q arity).2.2.2.1] at h\n  exact h\n\n/-- Every acquired scale and weight output fits the same original logarithmic cap. -/\ntheorem scales_widths (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) :\n    let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n    let W := baseWidth n (∑ e,arity e) r Q lam\n    cache.scales.alphabet.length ≤ W ∧ cache.scales.square.length ≤ W ∧\n    cache.scales.fourth.length ≤ W ∧ cache.scales.head.length ≤ W ∧\n    cache.scales.weights.incidence.length ≤ W ∧ cache.scales.weights.head.length ≤ W := by\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  have h := SemiprimeSourceHistogramScales.acquire_lengths r Q lam cache.data.records cache.data.metadata.vertices\n  have hm := records_length n F r Q lam arity owner\n  have hn : cache.data.metadata.vertices.length=n := by\n    rw [SemiprimeSourceHistogramSetup.metadata_actual]\n    exact (SemiprimeSourceHistogramMetadata.sizes n F Q arity).1\n  rw [hm,hn] at h\n  obtain ⟨_,hL,hS,hA,hG,hwa,hwb,_,_,_,_⟩ := base_caps n (∑ e,arity e) r Q lam\n  exact ⟨h.1.trans hL,h.2.1.trans hS,h.2.2.1.trans hA,h.2.2.2.1.trans hG,\n    h.2.2.2.2.1.trans hwa,h.2.2.2.2.2.trans hwb⟩\n\n/-- Actual feature histograms derive width from their original ordered port count. -/\ntheorem feature_width (n F r Q lam : ℕ) (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n)\n    (dict : SemiprimeSourceHistogramTrie.Trie) (k s : ℕ) (f g : Feature) :\n    (SemiprimeSourceHistogramFeatureBits.acquire dict k s f g\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).data.records).bits.length ≤\n        baseWidth n (∑ e,arity e) r Q lam := by\n  have h := SemiprimeSourceHistogramFeatureBitsBounds.acquire_length dict k s f g\n    (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).data.records\n  rw [records_length] at h\n  obtain ⟨_,_,_,_,_,_,_,hI,_,_,_⟩ := base_caps n (∑ e,arity e) r Q lam\n  exact h.trans hI\n\n/-- All actual sixteen producer clocks follow original acquired prefix/port data. -/\ntheorem feature_clock (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids)\n    (k s : ℕ) (f g : Feature) :\n    (SemiprimeSourceHistogramFeatureBits.acquire (SemiprimeSourceHistogramPrefix.acquire fixed).trie k s f g\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).data.records).clock ≤\n        SemiprimeSourceHistogramFeatureBitsBounds.budget (n+F) (r^Q) (∑ e,arity e) := by\n  rw [SemiprimeSourceHistogramSetup.records_actual]\n  have h := SemiprimeSourceHistogramFeatureBitsBounds.acquirePorts_clock owner\n    (SemiprimeSourceHistogramMetadata.acquire n F Q arity).incidences\n    (SemiprimeSourceHistogramPrefix.acquire fixed).trie k s f g (r^Q)\n    (SemiprimeSourceHistogramPrefix.stored_compact fixed)\n    (SemiprimeSourceHistogramDictRefinement.count_cap r Q fixed hf)\n  rwa [(SemiprimeSourceHistogramMetadata.sizes n F Q arity).2.2.1] at h\n\n/-- Actual incidence producers and fixed-depth combination both retain their costs. -/\ntheorem incidence_bound_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) (k s : ℕ) :\n    let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n    let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n    Width (incidenceWith cache dict k s).word (laneWidth n (∑ e,arity e) r Q lam) ∧\n    (incidenceWith cache dict k s).clock ≤\n      16*SemiprimeSourceHistogramFeatureBitsBounds.budget (n+F) (r^Q) (∑ e,arity e)+\n        60*unitBudget (baseWidth n (∑ e,arity e) r Q lam) := by\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n  let hist := fun f g => SemiprimeSourceHistogramFeatureBits.acquire dict k s f g cache.data.records\n  obtain ⟨hW,_,_,_,_,_,_,_,_,_,_⟩ := base_caps n (∑ e,arity e) r Q lam\n  have hs := scales_widths n F r Q lam arity owner\n  have h := SemiprimeSourceHistogramArithmeticBounds.incidence_bound cache.scales hist\n    (baseWidth n (∑ e,arity e) r Q lam) hW hs.1 hs.2.1\n    (fun f g => feature_width n F r Q lam arity owner dict k s f g)\n  have hsum := SemiprimeSourceHistogramSquaresBounds.list_sum_cap\n    SemiprimeSourceHistogramArithmetic.featurePairs\n    (fun fg => (hist fg.1 fg.2).clock)\n    (SemiprimeSourceHistogramFeatureBitsBounds.budget (n+F) (r^Q) (∑ e,arity e))\n    (fun fg _ => feature_clock n F r Q lam arity owner fixed hf k s fg.1 fg.2)\n  rw [SemiprimeSourceHistogramArithmeticBounds.featurePairs_length] at hsum\n  exact ⟨h.1,h.2.trans (Nat.add_le_add_right hsum _)⟩\n\n/-- Actual physical head counters and collision word derive all head-arithmetic guards. -/\ntheorem head_bound_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) (k s : ℕ) :\n    let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n    let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n    Width (headWith cache dict k s).word (grow (baseWidth n (∑ e,arity e) r Q lam) 8) ∧\n    (headWith cache dict k s).clock ≤\n      SemiprimeSourceHistogramHeadBounds.budget r Q (SemiprimeSourceHistogramPortKeys.keyWidth n) n+\n        30*unitBudget (baseWidth n (∑ e,arity e) r Q lam)+3 := by\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n  let data := SemiprimeSourceHistogramHeadBits.acquire cache.rows dict k s cache.vertices\n  let C : RationalReport := ⟨(SemiprimeSourceHistogramArithmetic.fromState data.histogram).word,data.clock+3⟩\n  obtain ⟨hW,_,_,_,_,_,_,_,hH,hq,hcount⟩ := base_caps n (∑ e,arity e) r Q lam\n  have hs := scales_widths n F r Q lam arity owner\n  have hvlen : cache.vertices.length=n := by\n    rw [vertices_actual,SemiprimeSourceHistogramHeadBounds.verticesWith_length,List.length_finRange]\n  have hc := SemiprimeSourceHistogramHeadBounds.counter_lengths cache.rows dict k s cache.vertices n hvlen.le\n  have hp : data.head.fixed.length ≤ baseWidth n (∑ e,arity e) r Q lam := hc.1.trans hcount\n  have hf' : data.head.free.length ≤ baseWidth n (∑ e,arity e) r Q lam := hc.2.trans hcount\n  have hq' := (coordinate_length n F r Q lam arity owner).trans hq\n  have hrows : cache.rows=SemiprimeSourceHistogramRowKeys.acquireCaches r Q := rfl\n  have hdict : dict=(SemiprimeSourceHistogramPrefix.acquire fixed).trie := rfl\n  have hlen : data.head.keys.length ≤ Q*n := by\n    change (SemiprimeSourceHistogramHeadBits.produce cache.rows dict k s cache.vertices).keys.length ≤ _\n    rw [vertices_actual,hrows,hdict]\n    have h := SemiprimeSourceHistogramHeadBounds.produce_length r Q fixed hf k s\n      (SemiprimeSourceHistogramHeadBits.verticesWith (List.finRange n)).value\n    simpa only [SemiprimeSourceHistogramHeadBounds.verticesWith_length,List.length_finRange] using h\n  have hbits : data.histogram.bits.length ≤ baseWidth n (∑ e,arity e) r Q lam := by\n    have h := SemiprimeSourceHistogramSquaresBounds.square_width data.head.keys\n    have hm := Nat.clog_mono_right 2 (Nat.add_le_add_right (Nat.pow_le_pow_left hlen 2) 1)\n    exact h.trans (hm.trans hH)\n  have hC : Width C.word (baseWidth n (∑ e,arity e) r Q lam) := unsigned_width _ _ hW hbits\n  have h := SemiprimeSourceHistogramArithmeticBounds.head_bound cache.scales\n    (⟨cache.coordinateCount,0⟩:SemiprimeSourceCompactBits.Report)\n    (⟨data.head.fixed,0⟩:SemiprimeSourceCompactBits.Report)\n    (⟨data.head.free,0⟩:SemiprimeSourceCompactBits.Report) C\n    (baseWidth n (∑ e,arity e) r Q lam) hW hs.2.2.1 hs.2.2.2.1 hq' hp hf' hC\n  have hdclock : data.clock ≤ SemiprimeSourceHistogramHeadBounds.budget r Q\n      (SemiprimeSourceHistogramPortKeys.keyWidth n) n := by\n    change (SemiprimeSourceHistogramHeadBits.acquire cache.rows dict k s cache.vertices).clock ≤ _\n    rw [vertices_actual,hrows,hdict]\n    simpa only [List.length_finRange] using\n      SemiprimeSourceHistogramHeadBounds.acquire_static_clock r Q fixed hf k s (List.finRange n)\n  refine ⟨h.1,?_⟩\n  exact h.2.trans (by\n    change 0+0+0+(data.clock+3)+30*unitBudget (baseWidth n (∑ e,arity e) r Q lam) ≤ _\n    omega)\n\n/-- All actual lane inputs fit the derived weighted-arithmetic envelope. -/\ntheorem scoreWith_bound_original (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) (k s : ℕ) :\n    let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n    let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n    Width (scoreWith cache dict k s).word (outputWidth n (∑ e,arity e) r Q lam) ∧\n    (scoreWith cache dict k s).clock ≤\n      16*SemiprimeSourceHistogramFeatureBitsBounds.budget (n+F) (r^Q) (∑ e,arity e)+\n      SemiprimeSourceHistogramHeadBounds.budget r Q (SemiprimeSourceHistogramPortKeys.keyWidth n) n+\n      90*unitBudget (baseWidth n (∑ e,arity e) r Q lam)+\n      3*unitBudget (laneWidth n (∑ e,arity e) r Q lam)+3 := by\n  let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n  let dict := (SemiprimeSourceHistogramPrefix.acquire fixed).trie\n  have hI := incidence_bound_original n F r Q lam arity owner fixed hf k s\n  have hH := head_bound_original n F r Q lam arity owner fixed hf k s\n  have hs := scales_widths n F r Q lam arity owner\n  have hbase : baseWidth n (∑ e,arity e) r Q lam ≤ laneWidth n (∑ e,arity e) r Q lam :=\n    (show baseWidth n (∑ e,arity e) r Q lam ≤ grow (baseWidth n (∑ e,arity e) r Q lam) 0 by simp [grow]).trans\n      (grow_mono _ (by decide : 0 ≤ 20))\n  have hh := widen hH.1 (grow_mono (baseWidth n (∑ e,arity e) r Q lam) (by decide : 8 ≤ 20))\n  have h := SemiprimeSourceHistogramArithmeticBounds.weighted_bound cache.scales\n    (incidenceWith cache dict k s) (headWith cache dict k s)\n    (laneWidth n (∑ e,arity e) r Q lam) (grow_pos _ 20)\n    (hs.2.2.2.2.1.trans hbase) (hs.2.2.2.2.2.trans hbase) hI.1 hh\n  refine ⟨h.1,?_⟩\n  exact h.2.trans (by\n    have hi := hI.2\n    have hh' := hH.2\n    change (incidenceWith cache dict k s).clock ≤ _ at hi\n    change (headWith cache dict k s).clock ≤ _ at hh'\n    omega)\n\n/-- Actual selected-ID membership closes prefix acquisition without encoded-ID advice. -/\ntheorem prefix_clock (r Q : ℕ) (fixed : List (List Bool))\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (SemiprimeSourceHistogramPrefix.acquire fixed).clock ≤ prefixBudget (r^Q) fixed.length :=\n  SemiprimeSourceHistogramPrefix.acquire_clock fixed _ fixed.length le_rfl\n    (fun id hi => SemiprimeSourceCompactWordBank.ids_bounded r Q id (hf id hi))\n\n/-- Complete actual query shape and report from original setup and selected prefix.\nOnly reached-menu membership is required; no output/Fits/clock advice occurs. -/\ntheorem score_bound (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    let cache := SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner\n    Width (score cache fixed s).word (outputWidth n (∑ e,arity e) r Q lam) ∧\n    (score cache fixed s).clock ≤ scoreBudget n F (∑ e,arity e) r Q lam fixed.length := by\n  have h := scoreWith_bound_original n F r Q lam arity owner fixed hf fixed.length s\n  have hp := prefix_clock r Q fixed hf\n  refine ⟨h.1,?_⟩\n  unfold score scoreBudget\n  dsimp only\n  omega\n\n/-- Final original-query report, including one actually acquired prefix trie. -/\ntheorem score_clock (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (score (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner) fixed s).clock ≤\n      scoreBudget n F (∑ e,arity e) r Q lam fixed.length :=\n  (score_bound n F r Q lam arity owner fixed s hf).2\n\n/-- Final signed physical output width is derived from acquired original dimensions. -/\ntheorem score_width (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    Width (score (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner) fixed s).word\n      (outputWidth n (∑ e,arity e) r Q lam) :=\n  (score_bound n F r Q lam arity owner fixed s hf).1\n\n/-- Standalone input acquisition remains an explicit separately paid producer.\nThis does not assert a new setup-clock or full-machine execution theorem. -/\ntheorem indexed_clock (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (indexed n F r Q lam arity owner fixed s).clock ≤\n      (SemiprimeSourceHistogramSetup.acquire n F r Q lam arity owner).clock+\n        scoreBudget n F (∑ e,arity e) r Q lam fixed.length+3 := by\n  exact Nat.add_le_add_right (Nat.add_le_add_left\n    (score_clock n F r Q lam arity owner fixed s hf) _) 3\n\n/-- Reachable-prefix length caps enlarge only the actual prefix acquisition term. -/\ntheorem scoreBudget_prefix_mono (n F M r Q lam : ℕ) {k K : ℕ} (hk : k ≤ K) :\n    scoreBudget n F M r Q lam k ≤ scoreBudget n F M r Q lam K := by\n  have hc := Nat.clog_mono_right 2 (Nat.add_le_add_right hk 2)\n  unfold scoreBudget prefixBudget SemiprimeSourceHistogramTrieBounds.clockWidth\n  gcongr\n\n/-- Closed standalone original setup plus actual query report. Cached callers pay\nthis setup once, then use score_clock for each subsequent query. -/\ntheorem indexed_clock_closed (n F r Q lam : ℕ) [NeZero r] (arity : Fin F→ℕ)\n    (owner : ((e : Fin F)×Fin (arity e))→Fin n) (fixed : List (List Bool)) (s : ℕ)\n    (hf : ∀ id∈fixed,id∈(SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (indexed n F r Q lam arity owner fixed s).clock ≤\n      SemiprimeSourceHistogramSetupBounds.budget n F r Q lam (∑ e,arity e) (r^Q)+\n        scoreBudget n F (∑ e,arity e) r Q lam fixed.length+3 := by\n  have hs := SemiprimeSourceHistogramSetupBounds.acquire_clock n F r Q lam arity owner (NeZero.pos r)\n  exact (indexed_clock n F r Q lam arity owner fixed s hf).trans\n    (Nat.add_le_add_right (Nat.add_le_add_right hs _) 3)\n\nend RiemannGaussian.SemiprimeSourceHistogramQueryBounds\n","RiemannGaussian.SemiprimeSourceHistogramRows":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramTrieStore\nimport RiemannGaussian.SemiprimeSourceHistogramKeyBits\nimport RiemannGaussian.SemiprimeSourceCompactWordBank\n\n/-! # Acquired physical candidate-row dictionary\nEvery colour magnitude is physically trimmed and framed once. The dictionary\ncopies the actual encoded row at its acquired compact candidate ID. Native\npersistent references and host list/control stages remain explicit boundaries.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramRows\nopen SemiprimeRationalBits SemiprimeBitArithmetic SemiprimeSourceHistogramTrie\nopen SemiprimeSourceCompactBits (Report)\n/-- Actual acquired physical coordinate row. -/\nabbrev Row := List RationalWord\n\n/-- Proof-side byte layout of a physical row, without rational interpretation. -/\ndef layout : Row → List Bool\n  | [] => []\n  | x::xs => SemiprimeSourceHistogramKeyBits.frame\n      (SemiprimeSourceCompactBits.trim x.numerator.magnitude).bits (layout xs)\n\n/-- Acquire compact colour fields solely from actual numerator magnitudes. -/\ndef encodeRow : Row → Report\n  | [] => ⟨[],1⟩\n  | x::xs =>\n    let tail := encodeRow xs\n    let colour := SemiprimeSourceCompactBits.trim x.numerator.magnitude\n    let joined := SemiprimeSourceHistogramKeyBits.pair colour.bits tail.bits\n    ⟨joined.bits,tail.clock+colour.clock+joined.clock+6⟩\n\n/-- Executed bytes equal the complete framed physical-row layout. -/\ntheorem encodeRow_bits (row : Row) : (encodeRow row).bits=layout row := by\n  induction row with\n  | nil => rfl\n  | cons x xs ih => simp only [encodeRow,layout,SemiprimeSourceHistogramKeyBits.pair_bits,ih]\n\n/-- Every original bounded magnitude gives a linear encoded-row payload bound. -/\ntheorem layout_length (row : Row) (B : ℕ)\n    (hb : ∀ x ∈ row, x.numerator.magnitude.length ≤ B) :\n    (layout row).length ≤ row.length*(2*B+1) := by\n  induction row with\n  | nil => simp [layout]\n  | cons x xs ih =>\n    have hx := hb x (by simp)\n    have ht := ih (fun y hy => hb y (List.mem_cons_of_mem x hy))\n    have hc := SemiprimeSourceCompactBits.trim_length x.numerator.magnitude\n    simp only [layout,SemiprimeSourceHistogramKeyBits.frame_length,List.length_cons]\n    nlinarith\n\n/-- Actual trim, frame, list and cell work is linear in original row payload. -/\ntheorem encodeRow_clock (row : Row) (B : ℕ)\n    (hb : ∀ x ∈ row, x.numerator.magnitude.length ≤ B) :\n    (encodeRow row).clock ≤ row.length*(12*B+10)+1 := by\n  induction row with\n  | nil => simp [encodeRow]\n  | cons x xs ih =>\n    have hx := hb x (by simp)\n    have ht := ih (fun y hy => hb y (List.mem_cons_of_mem x hy))\n    have hc := SemiprimeSourceCompactBits.trim_length x.numerator.magnitude\n    simp only [encodeRow,SemiprimeSourceCompactBits.trim_clock,\n      SemiprimeSourceHistogramKeyBits.pair_clock,List.length_cons]\n    nlinarith\n\n/-- Actual cached paired-list acquisition, including every emitted pair cell. -/\ndef zipRows : List (List Bool) → List Row → SemiprimeMaterializedWords.Run\n    (List (List Bool × Row))\n  | id::ids,row::rows =>\n    let tail := zipRows ids rows\n    ⟨(id,row)::tail.value,tail.work+4⟩\n  | _,_ => ⟨[],1⟩\n\n/-- No list-order or reindexing assumption hides in paired-list acquisition. -/\ntheorem zipRows_value (ids : List (List Bool)) (rows : List Row) :\n    (zipRows ids rows).value=ids.zip rows := by\n  induction ids generalizing rows with\n  | nil => cases rows <;> rfl\n  | cons id ids ih => cases rows with\n    | nil => rfl\n    | cons row rows => simp only [zipRows,List.zip_cons_cons,ih]\n\n/-- The actual zip traversal pays once per emitted cell. -/\ntheorem zipRows_clock (ids : List (List Bool)) (rows : List Row) :\n    (zipRows ids rows).work=4*(ids.zip rows).length+1 := by\n  induction ids generalizing rows with\n  | nil => cases rows <;> rfl\n  | cons id ids ih => cases rows with\n    | nil => rfl\n    | cons row rows => simp only [zipRows,List.zip_cons_cons,List.length_cons,ih];omega\n\n/-- Physical acquired row dictionary and retained construction report. -/\nstructure Dictionary where\n  /-- Actual persistent Boolean-key dictionary. -/\n  trie : Trie\n  /-- All row encoding, insertion and original acquisition stages. -/\n  clock : ℕ\n\n/-- Every supplied pair is encoded once and inserted once, in literal order. -/\ndef build : List (List Bool × Row) → Dictionary\n  | [] => ⟨.empty,1⟩\n  | (id,row)::rest =>\n    let tail := build rest\n    let encoded := encodeRow row\n    let out := SemiprimeSourceHistogramTrieStore.put tail.trie id encoded.bits\n    ⟨out.trie,tail.clock+encoded.clock+out.clock+6⟩\n\n/-- Actual bank dictionary construction retains its bank acquisition report. -/\ndef acquire (r Q : ℕ) : Dictionary :=\n  let bank := SemiprimeSourceCompactWordBank.acquire r Q\n  let paired := zipRows bank.ids bank.rows\n  let out := build paired.value\n  ⟨out.trie,bank.clock+paired.work+out.clock+4⟩\n\n/-- Original bank and its actual row dictionary acquired in one shared scope. -/\nstructure Cached where\n  /-- The same acquired original physical rows and candidate IDs. -/\n  bank : SemiprimeSourceWordBank.Bank\n  /-- Dictionary with original bank acquisition already included in its report. -/\n  dictionary : Dictionary\n\n/-- Acquire the bank once and retain it for candidate/prefix selection. -/\ndef acquireWithBank (r Q : ℕ) : Cached :=\n  let bank := SemiprimeSourceCompactWordBank.acquire r Q\n  let paired := zipRows bank.ids bank.rows\n  let out := build paired.value\n  ⟨bank,⟨out.trie,bank.clock+paired.work+out.clock+4⟩⟩\n\n/-- Retaining the actual bank does not change dictionary data or its paid report. -/\ntheorem acquireWithBank_dictionary (r Q : ℕ) :\n    (acquireWithBank r Q).dictionary=acquire r Q := rfl\n\n/-- The retained candidate menu is the actual single acquired compact bank. -/\ntheorem acquireWithBank_bank (r Q : ℕ) :\n    (acquireWithBank r Q).bank=SemiprimeSourceCompactWordBank.acquire r Q := rfl\n\n/-- Read the physical selected payload by the actual trie path and copy. -/\ndef readRow (dict : Dictionary) (id : List Bool) : Report := lookup dict.trie id\n\n/-- Literal first-match specification, used only to prove the constructed map. -/\ndef expected : List (List Bool × Row) → List Bool → List Bool\n  | [],_ => []\n  | (id,row)::rest,key => if key=id then layout row else expected rest key\n\n/-- The actual insertion sequence gives exact literal first-match byte semantics. -/\ntheorem build_stored (pairs : List (List Bool × Row)) (key : List Bool) :\n    stored (build pairs).trie key=expected pairs key := by\n  induction pairs with\n  | nil => simp [build,stored_empty,expected]\n  | cons p ps ih =>\n    rcases p with ⟨id,row⟩\n    simp only [build,SemiprimeSourceHistogramTrieStore.put_stored,expected,encodeRow_bits,ih]\n\n/-- No duplicated acquired ID can shadow another original row. -/\ntheorem expected_mem (pairs : List (List Bool × Row)) (id : List Bool) (row : Row)\n    (hn : (pairs.map Prod.fst).Nodup) (hm : (id,row) ∈ pairs) :\n    expected pairs id=layout row := by\n  induction pairs with\n  | nil => simp at hm\n  | cons p ps ih =>\n    rcases p with ⟨key,value⟩\n    simp only [List.map_cons,List.nodup_cons] at hn\n    rcases List.mem_cons.mp hm with h|h\n    · cases h; simp only [expected,ite_true]\n    · have hk : id≠key := by\n        intro he\n        apply hn.1\n        exact List.mem_map.mpr ⟨(id,row),h,he⟩\n      simp only [expected,hk,ite_false]\n      exact ih hn.2 h\n\n/-- Physical dictionary lookup for any actual original paired row. -/\ntheorem build_lookup (pairs : List (List Bool × Row)) (id : List Bool) (row : Row)\n    (hn : (pairs.map Prod.fst).Nodup) (hm : (id,row) ∈ pairs) :\n    (readRow (build pairs) id).bits=(encodeRow row).bits := by\n  rw [readRow,lookup_bits,build_stored,expected_mem pairs id row hn hm,encodeRow_bits]\n\n/-- Original acquired paired rows have distinct dictionary keys. -/\ntheorem original_nodup (r Q : ℕ) :\n    (((SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n      (SemiprimeSourceCompactWordBank.acquire r Q).rows).map Prod.fst).Nodup := by\n  rw [List.map_fst_zip (SemiprimeSourceCompactWordBank.ids_length r Q).le]\n  exact SemiprimeSourceCompactWordBank.ids_nodup r Q\n\n/-- Each actual acquired ID is paired with its physically indexed original row. -/\ntheorem original_pair (r Q : ℕ) (id : List Bool)\n    (hi : id ∈ (SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (id,(SemiprimeSourceWordBank.readRow\n      (SemiprimeSourceCompactWordBank.acquire r Q) id).value) ∈\n      (SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n        (SemiprimeSourceCompactWordBank.acquire r Q).rows := by\n  obtain ⟨i,hil,he⟩ := List.mem_iff_getElem.mp hi\n  have hv := congrArg (fun xs : List ℕ => xs[i]?)\n    (SemiprimeSourceCompactWordBank.ids_values r Q)\n  rw [List.getElem?_map,List.getElem?_eq_getElem hil,Option.map_some,he] at hv\n  have hrange : i < (List.range (r^Q)).length := by\n    simpa only [List.length_range,SemiprimeSourceCompactWordBank.ids_length,\n      SemiprimeSourceCompactWordBank.acquire_length] using hil\n  rw [List.getElem?_eq_getElem hrange,List.getElem_range,Option.some.injEq] at hv\n  have hir : i < (SemiprimeSourceCompactWordBank.acquire r Q).rows.length := by\n    rwa [← SemiprimeSourceCompactWordBank.ids_length r Q]\n  have hiz : i < ((SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n      (SemiprimeSourceCompactWordBank.acquire r Q).rows).length := by\n    rw [List.length_zip]; exact lt_min hil hir\n  have hm := List.getElem_mem hiz\n  rw [List.getElem_zip,he] at hm\n  simpa only [SemiprimeSourceWordBank.readRow_value,hv,\n    List.getElem?_eq_getElem hir,Option.getD_some] using hm\n\n/-- Actual original-input lookup equals the encoded actual physical bank row.\nThe old linear bank read appears ONLY in this semantic theorem. -/\ntheorem lookup_original (r Q : ℕ) (id : List Bool)\n    (hi : id ∈ (SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (readRow (acquire r Q) id).bits =\n      (encodeRow (SemiprimeSourceWordBank.readRow\n        (SemiprimeSourceCompactWordBank.acquire r Q) id).value).bits := by\n  change (readRow (build (zipRows _ _).value) id).bits = _\n  rw [zipRows_value]\n  exact build_lookup _ _ _ (original_nodup r Q) (original_pair r Q id hi)\n\nend RiemannGaussian.SemiprimeSourceHistogramRows\n","RiemannGaussian.SemiprimeSourceHistogramRowsBounds":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramRows\n\n/-! # Original-dimension row-dictionary acquisition and query bounds\nThe bank is acquired once and every row is encoded and inserted once. Bounds\ninclude actual zip traversal, frame/counter work, copies and dictionary visits.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramRowsBounds\nopen SemiprimeSourceHistogramRows SemiprimeSourceHistogramTrie SemiprimeRationalBits\n\n/-- Original bounds on literal paired IDs and physical coordinate rows. -/\ndef Good (pairs : List (List Bool × Row)) (B Q R : ℕ) : Prop :=\n  ∀ p ∈ pairs, p.1.length ≤ B ∧ p.2.length ≤ Q ∧\n    ∀ x ∈ p.2, x.numerator.magnitude.length ≤ R\n\n/-- Every stored raw encoded row has the same original payload-width cap. -/\ntheorem build_width (pairs : List (List Bool × Row)) (B Q R : ℕ)\n    (hg : Good pairs B Q R) (key : List Bool) :\n    (stored (build pairs).trie key).length ≤ Q*(2*R+1) := by\n  induction pairs generalizing key with\n  | nil => simp [build,stored_empty]\n  | cons p ps ih =>\n    have hp := hg p (by simp)\n    apply SemiprimeSourceHistogramTrieStore.put_width\n    · exact fun query => ih (fun x hx => hg x (List.mem_cons_of_mem p hx)) query\n    · rw [encodeRow_bits]\n      exact (layout_length p.2 R hp.2.2).trans (Nat.mul_le_mul_right _ hp.2.1)\n\n/-- Each actual encoded original row has a linear one-time construction ledger. -/\ndef rowStage (B Q R : ℕ) : ℕ := Q*(18*R+13)+20*B+28\n\n/-- No acquisition step repeats an earlier bank lookup or row encoding. -/\ntheorem build_clock (pairs : List (List Bool × Row)) (B Q R : ℕ)\n    (hg : Good pairs B Q R) :\n    (build pairs).clock ≤ pairs.length*rowStage B Q R+1 := by\n  induction pairs with\n  | nil => simp [build]\n  | cons p ps ih =>\n    have hp := hg p (by simp)\n    have ht := ih (fun x hx => hg x (List.mem_cons_of_mem p hx))\n    have he := encodeRow_clock p.2 R hp.2.2\n    have hl := layout_length p.2 R hp.2.2\n    have hu := SemiprimeSourceHistogramTrieStore.put_clock (build ps).trie p.1\n      (encodeRow p.2).bits\n    rw [encodeRow_bits] at hu\n    change (build ps).clock+_+_+6 ≤ _\n    rw [encodeRow_bits]\n    simp only [List.length_cons]\n    unfold rowStage at ht ⊢\n    nlinarith\n\n/-- Dictionary inventory grows only by the inserted original ID path. -/\ntheorem build_nodes (pairs : List (List Bool × Row)) (B Q R : ℕ)\n    (hg : Good pairs B Q R) : nodes (build pairs).trie ≤ pairs.length*(B+1) := by\n  induction pairs with\n  | nil => simp [build,nodes]\n  | cons p ps ih =>\n    have hp := hg p (by simp)\n    have ht := ih (fun x hx => hg x (List.mem_cons_of_mem p hx))\n    have hu := SemiprimeSourceHistogramTrieStore.put_nodes (build ps).trie p.1\n      (encodeRow p.2).bits\n    change nodes (SemiprimeSourceHistogramTrieStore.put _ _ _).trie ≤ _\n    simp only [List.length_cons]\n    nlinarith\n\n/-- Actual acquired bank bounds discharge all original row-dictionary input caps. -/\ntheorem original_good (r Q : ℕ) : Good\n    ((SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n      (SemiprimeSourceCompactWordBank.acquire r Q).rows)\n    (Nat.clog 2 (r^Q+1)) Q (r+1) := by\n  intro p hp\n  have ha : p.1 ∈ (SemiprimeSourceCompactWordBank.acquire r Q).ids := by\n    have h : p.1 ∈ (((SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n      (SemiprimeSourceCompactWordBank.acquire r Q).rows).map Prod.fst) :=\n      List.mem_map.mpr ⟨p,hp,rfl⟩\n    rwa [List.map_fst_zip (SemiprimeSourceCompactWordBank.ids_length r Q).le] at h\n  have hb : p.2 ∈ (SemiprimeSourceCompactWordBank.acquire r Q).rows := by\n    have h : p.2 ∈ (((SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n      (SemiprimeSourceCompactWordBank.acquire r Q).rows).map Prod.snd) :=\n      List.mem_map.mpr ⟨p,hp,rfl⟩\n    rw [List.map_snd_zip (SemiprimeSourceCompactWordBank.ids_length r Q).symm.le] at h\n    exact h\n  refine ⟨SemiprimeSourceCompactWordBank.ids_bounded r Q p.1 ha,?_,?_⟩\n  · exact (SemiprimeSourceWordBankBounds.acquire_row_length r Q p.2 hb).le\n  · intro x hx\n    exact (SemiprimeSourceWordBankBounds.acquire_good r Q p.2 hb x hx).2.1\n\n/-- Original candidate IDs and rows are zipped with exactly original cardinality. -/\ntheorem original_pair_length (r Q : ℕ) :\n    ((SemiprimeSourceCompactWordBank.acquire r Q).ids.zip\n      (SemiprimeSourceCompactWordBank.acquire r Q).rows).length=r^Q := by\n  rw [List.length_zip,SemiprimeSourceCompactWordBank.ids_length,Nat.min_self,\n    SemiprimeSourceCompactWordBank.acquire_length]\n\n/-- Complete original input construction, including the original bank producer. -/\ndef budget (r Q L : ℕ) : ℕ := SemiprimeSourceCompactWordBank.budget r Q L+\n  4*L+1+L*rowStage (Nat.clog 2 (L+1)) Q (r+1)+1+4\n\n/-- No external bank, row, ID-width or producer-clock advice remains. -/\ntheorem acquire_clock (r Q : ℕ) (hr : 0 < r) :\n    (acquire r Q).clock ≤ budget r Q (r^Q) := by\n  have hb := SemiprimeSourceCompactWordBank.acquire_clock r Q hr\n  have hz := zipRows_clock (SemiprimeSourceCompactWordBank.acquire r Q).ids\n    (SemiprimeSourceCompactWordBank.acquire r Q).rows\n  have ht := build_clock _ _ _ _ (original_good r Q)\n  simp only [original_pair_length] at hz ht\n  unfold acquire budget\n  dsimp only\n  rw [zipRows_value]\n  omega\n\n/-- Every stored actual original row fits its original coordinate payload size. -/\ntheorem acquire_width (r Q : ℕ) (key : List Bool) :\n    (stored (acquire r Q).trie key).length ≤ Q*(2*(r+1)+1) := by\n  change (stored (build (zipRows _ _).value).trie key).length ≤ _\n  rw [zipRows_value]\n  exact build_width _ _ _ _ (original_good r Q) key\n\n/-- Actual original dictionary inventory is linear-count times compact-ID width. -/\ntheorem acquire_nodes (r Q : ℕ) : nodes (acquire r Q).trie ≤\n    r^Q*(Nat.clog 2 (r^Q+1)+1) := by\n  change nodes (build (zipRows _ _).value).trie ≤ _\n  rw [zipRows_value]\n  have h := build_nodes _ _ _ _ (original_good r Q)\n  rwa [original_pair_length] at h\n\n/-- Each subsequent row query pays only its compact key and selected row payload. -/\ntheorem readRow_clock (r Q : ℕ) (id : List Bool)\n    (hi : id ∈ (SemiprimeSourceCompactWordBank.acquire r Q).ids) :\n    (readRow (acquire r Q) id).clock ≤\n      8*Nat.clog 2 (r^Q+1)+3*(Q*(2*(r+1)+1))+12 := by\n  have h := SemiprimeSourceHistogramTrieBounds.lookup_clock\n    (acquire r Q).trie id _ (acquire_width r Q id)\n  have hl := SemiprimeSourceCompactWordBank.ids_bounded r Q id hi\n  exact h.trans (by omega)\n\nend RiemannGaussian.SemiprimeSourceHistogramRowsBounds\n","RiemannGaussian.SemiprimeSourceHistogramSquares":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceHistogramTrie\nimport RiemannGaussian.SemiprimeSourceHistogramGrouping\n\n/-! # Actual streaming physical collision-square histogram\nEach key visits one trie path. The returned old frequency k drives the physical\nincrement 2k+1 and compact accumulated sum. No final-bin catalogue is executed.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceHistogramSquares\nopen SemiprimeBitArithmetic\nopen SemiprimeSourceHistogramGrouping\nopen SemiprimeSourceHistogramTrie (Trie CompactCounters)\nopen SemiprimeSourceCompactBits (Compact)\n\n/-- Actual dictionary, compact accumulated square-count and all retained reports. -/\nstructure State where\n  /-- Acquired persistent frequency trie. -/\n  trie : Trie\n  /-- Physical compact collision-square total. -/\n  bits : List Bool\n  /-- Every trie/arithmetic/cell/control stage already executed. -/\n  clock : ℕ\n\n/-- Empty physical state contains no frequency answer or allocated bins. -/\ndef initial : State := ⟨.empty,[],1⟩\n\n/-- One physical streaming step, with the old counter acquired once by bump.\nLittle-endian false-processed is the actual doubled counter, not an encoded Nat. -/\ndef step (state : State) (key : List Bool) : State :=\n  let changed := SemiprimeSourceHistogramTrie.bump state.trie key\n  let term := SemiprimeSourceCompactBits.increment (false::changed.old)\n  let total := SemiprimeSourceCompactBits.add state.bits term.bits\n  ⟨changed.trie,total.bits,state.clock+changed.clock+term.clock+total.clock+\n    key.length+changed.old.length+10⟩\n\n/-- Original key order is traversed literally, retaining the same acquired state. -/\ndef fold : List (List Bool) → State → State\n  | [],state => ⟨state.trie,state.bits,state.clock+1⟩\n  | key::keys,state =>\n    let next := step state key\n    let rest := fold keys next\n    ⟨rest.trie,rest.bits,rest.clock+3⟩\n\n/-- Complete generic key-list acquisition with no supplied frequencies. -/\ndef acquire (keys : List (List Bool)) : State := fold keys initial\n\n/-- Proof-only ordered collision count; runtime never executes this pair scan. -/\ndef collisions (keys : List (List Bool)) : ℕ :=\n  pairs keys (fun a b => if a=b then (1:ℕ) else 0)\n\n/-- One equality row is exactly the literal occurrence count. -/\ntheorem row_count (keys : List (List Bool)) (key : List Bool) :\n    (keys.map (fun a => if a=key then (1:ℕ) else 0)).sum=keys.count key := by\n  induction keys with\n  | nil => simp\n  | cons a keys ih => by_cases h : a=key <;> simp [h,ih,Nat.add_comm]\n\n/-- Appending one original occurrence creates precisely 2k+1 ordered collisions. -/\ntheorem collisions_append (keys : List (List Bool)) (key : List Bool) :\n    collisions (keys++[key])=collisions keys+2*keys.count key+1 := by\n  have hl := row_count keys key\n  have hr : (keys.map (fun a => if key=a then (1:ℕ) else 0)).sum=keys.count key := by\n    simpa only [eq_comm] using hl\n  unfold collisions pairs\n  simp only [List.map_append,List.sum_append,List.map_cons,List.map_nil,List.sum_cons,List.sum_nil,\n    List.sum_map_add,ite_true,Nat.add_zero]\n  rw [hl,hr]\n  omega\n\n/-- Pointwise executed total update from the SAME physically returned old counter. -/\ntheorem step_value (state : State) (key : List Bool) :\n    bitValue (step state key).bits=bitValue state.bits+\n      2*SemiprimeSourceHistogramTrie.value state.trie key+1 := by\n  simp only [step,SemiprimeSourceCompactBits.add_value,\n    SemiprimeSourceCompactBits.increment_value,SemiprimeSourceHistogramTrie.bump_old,\n    bitValue,SemiprimeSourceHistogramTrie.value,bitNat,Bool.false_eq_true,ite_false]\n  omega\n\n/-- Every executed total remains canonical compact bits. -/\ntheorem step_compact (state : State) (key : List Bool) : Compact (step state key).bits :=\n  SemiprimeSourceCompactBits.add_compact _ _\n\n/-- The proof-view names actual processed frequencies and their square total. -/\ndef Good (processed : List (List Bool)) (state : State) : Prop :=\n  (∀ key,SemiprimeSourceHistogramTrie.value state.trie key=processed.count key) ∧\n    bitValue state.bits=collisions processed ∧ CompactCounters state.trie ∧ Compact state.bits\n\n/-- Actual empty acquisition has zero frequencies and zero collision total. -/\ntheorem initial_good : Good [] initial := by\n  refine ⟨?_,rfl,SemiprimeSourceHistogramTrie.empty_compact,trivial⟩\n  intro key\n  simp [initial,SemiprimeSourceHistogramTrie.value,SemiprimeSourceHistogramTrie.stored_empty,bitValue]\n\n/-- Every actual streamed processed has the literal original occurrence counts. -/\ntheorem step_good (processed : List (List Bool)) (state : State) (key : List Bool)\n    (hs : Good processed state) : Good (processed++[key]) (step state key) := by\n  refine ⟨?_,?_,SemiprimeSourceHistogramTrie.bump_compact _ _ hs.2.2.1,step_compact state key⟩\n  · intro query\n    change SemiprimeSourceHistogramTrie.value\n      (SemiprimeSourceHistogramTrie.bump state.trie key).trie query=_\n    rw [SemiprimeSourceHistogramTrie.bump_value,hs.1 query]\n    by_cases h : query=key <;> simp [List.count_append,h,Ne.symm]\n  · rw [step_value,hs.1 key,hs.2.1,collisions_append]\n\n/-- Loop invariant is established from actual steps, not supplied final state. -/\ntheorem fold_good (keys processed : List (List Bool)) (state : State) (hs : Good processed state) :\n    Good (processed++keys) (fold keys state) := by\n  induction keys generalizing processed state with\n  | nil => simpa only [Good,fold,List.append_nil] using hs\n  | cons key keys ih =>\n    have h := ih (processed++[key]) (step state key) (step_good processed state key hs)\n    simpa only [Good,fold,List.append_assoc,List.singleton_append] using h\n\n/-- All original keys, duplicates, empty keys and processed-related keys are exact. -/\ntheorem acquire_good (keys : List (List Bool)) : Good keys (acquire keys) := by\n  simpa only [acquire,List.nil_append] using fold_good keys [] initial initial_good\n\n/-- Exact physical final lookup against literal List.count, including absent keys. -/\ntheorem lookup_final (keys : List (List Bool)) (key : List Bool) :\n    bitValue (SemiprimeSourceHistogramTrie.lookup (acquire keys).trie key).bits=keys.count key := by\n  rw [SemiprimeSourceHistogramTrie.lookup_value]\n  exact (acquire_good keys).1 key\n\n/-- The actual accumulator equals the original collision-pair count. -/\ntheorem acquire_value (keys : List (List Bool)) :\n    bitValue (acquire keys).bits=collisions keys := (acquire_good keys).2.1\n\n/-- Final sparse-bin squares are a theorem, never an extra executed scan. -/\ntheorem acquire_squares (keys : List (List Bool)) :\n    bitValue (acquire keys).bits=∑ key∈keys.toFinset,(keys.count key)^2 := by\n  rw [acquire_value]\n  have h := pair_grouping (fun a : List Bool => a) keys\n  change collisions keys=∑ key∈(keys.map id).toFinset,\n    (multiplicity (id : List Bool → List Bool) keys key)^2 at h\n  have hm (key : List Bool) : multiplicity (id : List Bool → List Bool) keys key=keys.count key := by\n    exact (indicator_sum (id : List Bool → List Bool) keys key).symm.trans (row_count keys key)\n  simp only [hm,List.map_id] at h\n  exact h\n\nend RiemannGaussian.SemiprimeSourceHistogramSquares\n","RiemannGaussian.SemiprimeSourceIncidenceCountFormula":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceIncidencePairAverage\nimport RiemannGaussian.SemiprimeSourceIncidenceNamespaces\n\n/-! # Exact original incidence counts from two constant-size edge classifiers -/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceIncidenceCountFormula\nopen OAI.Algorithms.SubexponentialSAT\nopen LocalExpectation MulticolorTypes\nopen SemiprimeSourceHeadCountFormula SemiprimeSourceIncidencePairAverage\nopen SemiprimeMaterializedScoreEnvironment SemiprimeSourceScoreCountsPadding\n\n/-- A nonloop equality with at least one still-free endpoint costs one word. -/\ndef pairActive (remaining : List ℕ) (a c : ℕ) : Prop :=\n  a≠c ∧ (a∈remaining ∨ c∈remaining)\n\n/-- Anchors are compared only if neither endpoint is free; defaults and\nprevious overrides never constrain a genuinely still-free endpoint. -/\ndef pairOK {W : Type*} (remaining : List ℕ) (ω : ℕ → W) (a c : ℕ) : Prop :=\n  a=c ∨ a∈remaining ∨ c∈remaining ∨ ω a=ω c\n\ninstance pairActiveDecidable (remaining : List ℕ) (a c : ℕ) :\n    Decidable (pairActive remaining a c) := by unfold pairActive;infer_instance\n\ninstance pairOKDecidable {W : Type*} [DecidableEq W]\n    (remaining : List ℕ) (ω : ℕ → W) (a c : ℕ) :\n    Decidable (pairOK remaining ω a c) := by unfold pairOK;infer_instance\n\n/-- Four cached integer lanes suffice for every separated original incidence. -/\ndef classifiedCount {W : Type*} [DecidableEq W] (L : ℕ) (remaining : List ℕ)\n    (ω : ℕ → W) (a b c d : ℕ) : ℕ :=\n  if pairOK remaining ω a c ∧ pairOK remaining ω b d then\n    if pairActive remaining a c ∧ pairActive remaining b d then L^2\n    else if pairActive remaining a c ∨ pairActive remaining b d then L^3 else L^4\n  else 0\n\n/-- The edge classifier is the exact conditional equality probability. -/\ntheorem pairPotential_classified {W : Type*} [DecidableEq W] (L : ℕ)\n    (remaining : List ℕ) (ω : ℕ → W) (a c : ℕ) :\n    pairPotential L remaining ω a c=\n      if pairOK remaining ω a c then\n        if pairActive remaining a c then 1/(L:ℚ) else 1 else 0 := by\n  classical\n  by_cases h : a=c\n  · subst c;simp [pairPotential,pairOK,pairActive]\n  by_cases hf : a∈remaining ∨ c∈remaining\n  · have hok : pairOK remaining ω a c := by\n      unfold pairOK\n      rcases hf with ha|hc\n      · exact Or.inr (Or.inl ha)\n      · exact Or.inr (Or.inr (Or.inl hc))\n    simp [pairPotential,pairActive,h,hf,hok]\n  · have ha : a∉remaining := fun ha => hf (Or.inl ha)\n    have hc : c∉remaining := fun hc => hf (Or.inr hc)\n    simp [pairPotential,pairOK,pairActive,h,ha,hc]\n\n/-- Clearing only the known positive integer L proves the literal lane value. -/\ntheorem classified_probability {W : Type*} [DecidableEq W] (L : ℕ) (hL : 0<L)\n    (remaining : List ℕ) (ω : ℕ → W) (a b c d : ℕ) :\n    pairPotential L remaining ω a c*pairPotential L remaining ω b d=\n      (classifiedCount L remaining ω a b c d:ℚ)/(L:ℚ)^4 := by\n  classical\n  have hln : (L:ℚ)≠0 := by exact_mod_cast Nat.ne_of_gt hL\n  rw [pairPotential_classified,pairPotential_classified]\n  by_cases ha : pairOK remaining ω a c <;>\n    by_cases hb : pairOK remaining ω b d <;>\n    by_cases hc : pairActive remaining a c <;>\n    by_cases hd : pairActive remaining b d <;>\n    simp [classifiedCount,ha,hb,hc,hd] <;> field_simp\n\n/-- Literal lane result belongs to the four cached possibilities, including L=1. -/\ntheorem classified_cases {W : Type*} [DecidableEq W] (L : ℕ)\n    (remaining : List ℕ) (ω : ℕ → W) (a b c d : ℕ) :\n    classifiedCount L remaining ω a b c d=0 ∨\n    classifiedCount L remaining ω a b c d=L^2 ∨\n    classifiedCount L remaining ω a b c d=L^3 ∨\n    classifiedCount L remaining ω a b c d=L^4 := by\n  classical\n  by_cases h : pairOK remaining ω a c ∧ pairOK remaining ω b d\n  · by_cases h2 : pairActive remaining a c ∧ pairActive remaining b d\n    · simp [classifiedCount,h,h2]\n    · by_cases h3 : pairActive remaining a c ∨ pairActive remaining b d\n      · simp [classifiedCount,h,h2,h3]\n      · simp [classifiedCount,h,h2,h3]\n  · simp [classifiedCount,h]\n\n/-- Exact ORIGINAL local count, for every prefix and every cached environment.\nThe only structural condition is discharged for every compiled source descriptor\nby SourceIncidenceNamespaces; it is not an added promise on the source. -/\ntheorem paddedLocal_formula (r Q : ℕ) (hr : 0<r) (a b c d : ℕ)\n    (remaining : List ℕ) (env : Environment r Q) (hn : remaining.Nodup)\n    (hab : a≠b) (had : a≠d) (hcb : c≠b) (hcd : c≠d) :\n    (paddedLocal (alphabet r Q) (.incidence a b c d) remaining env).value=\n      classifiedCount (r^Q) remaining (denote env) a b c d := by\n  classical\n  have hL : 0<(alphabet r Q).length := by rw [alphabet_length];exact pow_pos hr Q\n  have hp := localTerm_count (alphabet r Q) 1 1 (.incidence a b c d) remaining env hL hn\n  have hs : DependsOn (support (.incidence a b c d : ScoreProgram Q)).toFinset\n      (programValue (r:=r) (Q:=Q) 1 1 (.incidence a b c d)) := by\n    intro v w h\n    have ha := h a (by simp [support])\n    have hb := h b (by simp [support])\n    have hc := h c (by simp [support])\n    have hd := h d (by simp [support])\n    simp only [programValue,ha,hb,hc,hd]\n  have hv := SemiprimeMaterializedScoreSearch.localTerm_value (alphabet r Q) 1 1\n    (.incidence a b c d) remaining env\n  rw [← wordExpectation_filter (alphabet r Q) (List.ne_nil_of_length_pos hL)\n    _ _ hs remaining (denote env)] at hv\n  have hf : programValue (r:=r) (Q:=Q) 1 1 (.incidence a b c d)=\n      (fun v => (if v a=v c then 1 else 0)*(if v b=v d then 1 else 0)) := by\n    funext v\n    by_cases h1 : v a=v c <;> by_cases h2 : v b=v d <;> simp [programValue,h1,h2]\n  rw [hf,separated_average r Q hr remaining hn (denote env) a b c d hab had hcb hcd,\n    classified_probability (r^Q) (pow_pos hr Q)] at hv\n  simp only [SemiprimeSourceScoreCounts.weight,one_mul,mul_one,alphabet_length] at hp\n  have hden : ((r^Q:ℕ):ℚ)^4≠0 := pow_ne_zero _ (by exact_mod_cast Nat.ne_of_gt (pow_pos hr Q))\n  have he : ((paddedLocal (alphabet r Q) (.incidence a b c d) remaining env).value:ℚ)=\n      (classifiedCount (r^Q) remaining (denote env) a b c d:ℚ) := by\n    exact (div_left_inj' hden).mp (hp.symm.trans hv)\n  exact_mod_cast he\n\nend RiemannGaussian.SemiprimeSourceIncidenceCountFormula\n","RiemannGaussian.SemiprimeSourceInterpolationExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeUniversalNumeratorExecution\nimport RiemannGaussian.SemiprimeSourceCodeArrays\n\n/-! # Executed finite mismatch interpolation for actual universal source rows\nThe runtime receives finite universal register words and integer parity data.\nNo polynomial or requested coefficient is a runtime argument.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceInterpolationExecution\nopen scoped BigOperators\nopen Polynomial SemiprimeJetArray SemiprimeSourceCodeArrays\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes SubexpRowInterpolation SubexpAnnihilation\nopen SqrtLog LayoutScaledMatrices\nopen SemiprimeUniversalNumeratorExecution\nvariable {r Q Δ R : ℕ}\n\n/-- Literal positive rational interpolation nodes. -/\ndef node (Q : ℕ) (t : Fin Q) : ℚ := (t.val : ℚ)+1\n\n/-- Node and difference units computed by rational inversion, with proof-only guards. -/\ndef units (Q : ℕ) : NodeUnits (node Q) :=\n  NodeUnits.ofField (node Q) (by\n    intro a b h\n    apply Fin.ext\n    exact_mod_cast (add_right_cancel h : (a.val : ℚ)=(b.val : ℚ)))\n    (by intro t; unfold node; positivity)\n\n/-- Literal power-of-two clearing denominator. -/\ndef denominator (R : ℕ) : ℚˣ := Units.mk0 ((2 : ℚ)^(R-1)) (by positivity)\n\n/-- Actual source prescription from the computed zero-extended integer numerator. -/\ndef prescription (c : Fin R → ℤ) (a : UniversalType r Q Δ) (i : Fin Δ)\n    (y : UniversalType r Q Δ) (t : Fin Q) : ℚ :=\n  -(↑((denominator R)⁻¹) : ℚ) * (extended c i t (y.head t) a y : ℚ)\n\n/-- The finite executable expression for this source row column. -/\ndef code (c : Fin R → ℤ) (a : UniversalType r Q Δ) (i : Fin Δ)\n    (y : UniversalType r Q Δ) : PolynomialCode ℚ :=\n  mismatchRowCode a (fun v => v.head) (a.slot i) R (units Q) (prescription c a i) y\n\n/-- Actual source coefficient array, including the constant and degree-R coefficient. -/\ndef row (c : Fin R → ℤ) (a : UniversalType r Q Δ) (i : Fin Δ)\n    (y : UniversalType r Q Δ) : InverseReport := compile (R+1) (code c a i y)\n\n/-- Explicit normalized interpolation units agree with the source's units. -/\ntheorem units_eq (Q : ℕ) : units Q = SemiprimeSourceLayout.sampleUnits Q := rfl\n\n/-- Explicit power-of-two units agree with the source denominator. -/\ntheorem denominator_eq (R : ℕ) : denominator R = SemiprimeSourceLayout.denominatorUnit R := by\n  apply Units.ext\n  simp [denominator, SemiprimeSourceLayout.denominatorUnit, LayoutNumerator.denominator]\n\n/-- Scaling and zero extension commute, including both missing-index branches. -/\ntheorem zeroExtend_scaled (denom : ℚˣ) (i : Fin Δ) (t : Fin Q) (g : Fin r)\n    (N : Matrix (Joint t g i) (Joint t g i) ℤ) (a y : UniversalType r Q Δ) :\n    zeroExtendMatrix (joint t g i) (unitScaled denom N) a y =\n      (↑(denom⁻¹) : ℚ) * ((zeroExtendMatrix (F := ℤ) (joint t g i) N a y : ℤ) : ℚ) := by\n  unfold zeroExtendMatrix\n  split_ifs <;> simp [unitScaled]\n\n/-- The supplied finite parity solution yields exactly the source prescription. -/\ntheorem prescription_eq (A : ℕ) (c : Fin R → ℤ)\n    (hc : c=BinomialInterpolation.parityCoefficients (K := ℤ) A R)\n    (a : UniversalType r Q Δ) (i : Fin Δ) (y : UniversalType r Q Δ) :\n    prescription c a i y = matrixPrescription (RingHom.id ℚ)\n      (fun t g j => unitScaled (denominator R) (LayoutNumerator.family r Q Δ A R t g j)) a i y := by\n  funext t\n  unfold prescription matrixPrescription\n  rw [extended_eq A c hc, zeroExtend_scaled]\n  simp only [LayoutNumerator.family, RingHom.id_apply, neg_mul]\n\n/-- The finite expression denotes the literal universal source polynomial. -/\ntheorem code_denote (A : ℕ) (c : Fin R → ℤ)\n    (hc : c=BinomialInterpolation.parityCoefficients (K := ℤ) A R)\n    (a : UniversalType r Q Δ) (i : Fin Δ) (y : UniversalType r Q Δ) :\n    (code c a i y).denote = sourceRow (LayoutNumerator.family r Q Δ A R)\n      (denominator R) a i R (units Q) y := by\n  rw [code, mismatchRowCode_denote]\n  unfold sourceRow rowForMatrices\n  have hd : prescription c a i = matrixPrescription (RingHom.id ℚ)\n      (fun t g j => unitScaled (denominator R) (LayoutNumerator.family r Q Δ A R t g j)) a i :=\n    funext (fun y => prescription_eq A c hc a i y)\n  rw [hd]\n\n/-- Every retained array coefficient is actually acquired from the universal source formula. -/\ntheorem row_coefficient (A : ℕ) (c : Fin R → ℤ)\n    (hc : c=BinomialInterpolation.parityCoefficients (K := ℤ) A R)\n    (a : UniversalType r Q Δ) (i : Fin Δ) (y : UniversalType r Q Δ)\n    (k : ℕ) (hk : k<R+1) :\n    coefficient (row c a i y).coefficients k =\n      (sourceRow (LayoutNumerator.family r Q Δ A R)\n        (SemiprimeSourceLayout.denominatorUnit R) a i R\n        (SemiprimeSourceLayout.sampleUnits Q) y).coeff k := by\n  rw [row, compile_coefficient _ _ _ hk, code_denote A c hc, units_eq, denominator_eq]\n  rfl\n\n/-- The universal layout row has exactly these acquired coefficients (single incidence slot). -/\ntheorem universal_coefficient (A : ℕ) (c : Fin R → ℤ)\n    (hc : c=BinomialInterpolation.parityCoefficients (K := ℤ) A R)\n    (a y : UniversalType r Q 1) (k : ℕ) (hk : k<R+1) :\n    coefficient (row c a 0 y).coefficients k =\n      ((LayoutUniversal.data A R (SemiprimeSourceLayout.denominatorUnit R) rfl\n        (SemiprimeSourceLayout.sampleUnits Q)).row a y).coeff k :=\n  row_coefficient A c hc a 0 y k hk\n\n#print axioms row_coefficient\nend RiemannGaussian.SemiprimeSourceInterpolationExecution\n","RiemannGaussian.SemiprimeSourcePullbackHeight":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeMaterializedSourceAcquisition\nimport RiemannGaussian.SemiprimeLocalExecutionHeight\n\n/-! # Heights and array cells of the actual source cache and pullback\nThese invariants follow the finite cache lookups and right-recursive array sums.\nThe audit lists below describe returned arrays at executed recursion frames; they\nare proof views, not new runtime suppliers or a complete machine-space theorem.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1600000\nnamespace RiemannGaussian.SemiprimeSourcePullbackHeight\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes\nopen SemiprimeJetArray SemiprimeJetArrayHeight SemiprimeHermiteArrayHeight\nopen SemiprimeLocalExecutionHeight SemiprimeArrayOps\nopen SemiprimeMaterializedSourceUniversal SemiprimeMaterializedSourcePullback\nvariable {I : Type} {r Q : ℕ}\n\n/-- Uniform shape and coefficient bound of a materialized two-dimensional cache. -/\ndef CacheBound (cache : List (List (Array ℚ))) (J d B : ℕ) : Prop :=\n  ∀ row ∈ cache, ∀ a ∈ row, a.size=J ∧ ArrayBound a J d B\n\n/-- A successful actual lookup returns a member of the supplied finite values. -/\ntheorem lookup_some_mem {α : Type*} (target : UniversalType r Q 1)\n    (keys : List (UniversalType r Q 1)) (values : List α) (a : α)\n    (h : (SemiprimeMaterializedSourceCache.lookup target keys values).value=some a) :\n    a∈values := by\n  induction keys generalizing values with\n  | nil => simp [SemiprimeMaterializedSourceCache.lookup] at h\n  | cons key keys ih =>\n    cases values with\n    | nil => simp [SemiprimeMaterializedSourceCache.lookup] at h\n    | cons v vs =>\n      simp only [SemiprimeMaterializedSourceCache.lookup] at h\n      split_ifs at h with he\n      · simp only [Option.some.injEq] at h\n        subst a\n        exact List.mem_cons_self\n      · exact List.mem_cons_of_mem v (ih vs h)\n\n/-- Both Boolean literal branches have their literal size and common denominator. -/\ntheorem literal_bound (J d B : ℕ) (one : Bool) (hd : 0<d) (hB : d≤B) :\n    (literal J one).value.size=J ∧ ArrayBound (literal J one).value J d B := by\n  refine ⟨by simp [literal], ?_⟩\n  intro k hk\n  rw [literal_coefficient J one k hk]\n  split_ifs\n  · exact representation_mono (representation_one d hd) hB\n  · exact representation_mono (representation_zero d) (Nat.zero_le _)\n\n/-- Neither missing-key branch nor a successful scan enlarges the cached bound. -/\ntheorem cache_read_bound (R d B : ℕ) (keys : List (UniversalType r Q 1))\n    (cache : List (List (Array ℚ))) (u y : UniversalType r Q 1)\n    (hc : CacheBound cache (R+1) d B) :\n    (SemiprimeMaterializedSourceCache.read R keys cache u y).value.size=R+1 ∧\n      ArrayBound (SemiprimeMaterializedSourceCache.read R keys cache u y).value (R+1) d B := by\n  have hz : (Array.replicate (R+1) (0:ℚ)).size=R+1 ∧\n      ArrayBound (Array.replicate (R+1) (0:ℚ)) (R+1) d B :=\n    ⟨by simp, zero_bound (R+1) d B⟩\n  unfold SemiprimeMaterializedSourceCache.read\n  dsimp only\n  cases ho : (SemiprimeMaterializedSourceCache.lookup u keys cache).value with\n  | none => exact hz\n  | some row =>\n    have hr := lookup_some_mem u keys cache row ho\n    dsimp only\n    cases hi : (SemiprimeMaterializedSourceCache.lookup y keys row).value with\n    | none => exact hz\n    | some a => exact hc row hr a (lookup_some_mem y keys row a hi)\n\n/-- All address branches of one original-coordinate contribution retain the bound. -/\ntheorem assembled_bound [DecidableEq I] (R d B : ℕ) (as : Addresses I r Q)\n    (keys : List (UniversalType r Q 1)) (cache : List (List (Array ℚ))) (i j : I)\n    (hd : 0<d) (hB : d≤B) (hc : CacheBound cache (R+1) d B) :\n    (assembled R as keys cache i j).value.size=R+1 ∧\n      ArrayBound (assembled R as keys cache i j).value (R+1) d B := by\n  unfold assembled\n  dsimp only\n  split\n  · exact literal_bound _ _ _ _ hd hB\n  · split\n    · exact literal_bound _ _ _ _ hd hB\n    · split_ifs\n      · exact cache_read_bound _ _ _ _ _ _ _ hc\n      · exact literal_bound _ _ _ _ hd hB\n\n/-- Every completed right-recursive sum has exactly the requested array width. -/\ntheorem sumArrays_size (J : ℕ) (f : I → Run (Array ℚ)) (is : List I) :\n    (sumArrays J f is).value.size=J := by\n  cases is <;> simp [sumArrays,literal,add,addJet]\n\n/-- Bounds every recursive suffix by its actual number of contribution terms. -/\ntheorem sumArrays_bound (J d B : ℕ) (f : I → Run (Array ℚ)) (is : List I)\n    (hf : ∀ i∈is, ArrayBound (f i).value J d B) :\n    ArrayBound (sumArrays J f is).value J d (is.length*B) := by\n  induction is with\n  | nil =>\n    intro k hk\n    rw [sumArrays,literal_coefficient J false k hk]\n    simpa only [Bool.false_and,Bool.false_eq_true,ite_false,List.length_nil,Nat.zero_mul] using representation_zero d\n  | cons i is ih =>\n    have ht := ih (fun j hj => hf j (List.mem_cons_of_mem i hj))\n    intro k hk\n    change Representation (coefficient (addJet (f i).value (sumArrays J f is).value J).coefficients k) _ _\n    have h := addJet_representation _ _ J d B (is.length*B)\n      (hf i List.mem_cons_self) ht k hk\n    convert h using 1\n    simp only [List.length_cons]\n    ring\n\n/-- Covers the actual stored suffix accumulator at every recursion depth. -/\ntheorem sumArrays_suffix_bound (J d B : ℕ) (f : I → Run (Array ℚ))\n    (is : List I) (k : ℕ) (hf : ∀ i∈is, ArrayBound (f i).value J d B) :\n    ArrayBound (sumArrays J f (is.drop k)).value J d (is.length*B) := by\n  apply arrayBound_mono (sumArrays_bound J d B f (is.drop k)\n    (fun i hi => hf i (List.mem_of_mem_drop hi)))\n  exact Nat.mul_le_mul_right B (by simp only [List.length_drop]; omega)\n\n/-- Proof view of every sum return array and callback return array in the actual recursion. -/\ndef sumFrameArrays (J : ℕ) (f : I → Run (Array ℚ)) : List I → List (Array ℚ)\n  | [] => [(literal J false).value]\n  | i::is => (f i).value :: (sumArrays J f (i::is)).value :: sumFrameArrays J f is\n\n/-- Summed scalar slots, counting arrays separately even if an implementation shares them. -/\ndef arrayCells (xs : List (Array ℚ)) : ℕ := (xs.map Array.size).sum\n\n/-- Exact array-slot count over all returned recursion-frame and callback arrays. -/\ntheorem sumFrameArrays_cells (J : ℕ) (f : I → Run (Array ℚ)) (is : List I)\n    (hf : ∀ i∈is, (f i).value.size=J) :\n    arrayCells (sumFrameArrays J f is)=(2*is.length+1)*J := by\n  induction is with\n  | nil => simp [sumFrameArrays,arrayCells,literal]\n  | cons i is ih =>\n    have ht := ih (fun j hj => hf j (List.mem_cons_of_mem i hj))\n    simp only [sumFrameArrays,arrayCells,List.map_cons,List.sum_cons,\n      hf i List.mem_cons_self,sumArrays_size] at ⊢\n    change J+ (J+arrayCells (sumFrameArrays J f is))=_\n    rw [ht,List.length_cons]\n    ring\n\n/-- All arrays in the recursion view obey one original-contribution bound. -/\ntheorem sumFrameArrays_bound (J d B : ℕ) (f : I → Run (Array ℚ)) (is : List I)\n    (hf : ∀ i∈is, ArrayBound (f i).value J d B) :\n    ∀ a∈sumFrameArrays J f is, ArrayBound a J d ((is.length+1)*B) := by\n  induction is with\n  | nil =>\n    intro a ha\n    simp only [sumFrameArrays,List.mem_singleton] at ha\n    subst a\n    intro k hk\n    rw [literal_coefficient J false k hk]\n    exact representation_mono (representation_zero d) (Nat.zero_le _)\n  | cons i is ih =>\n    intro a ha\n    simp only [sumFrameArrays,List.mem_cons] at ha\n    rcases ha with rfl | rfl | ha\n    · exact arrayBound_mono (hf i List.mem_cons_self) (by simp only [List.length_cons]; nlinarith)\n    · exact arrayBound_mono (sumArrays_bound J d B f (i::is) hf)\n        (Nat.mul_le_mul_right B (Nat.le_succ _))\n    · exact arrayBound_mono (ih (fun j hj => hf j (List.mem_cons_of_mem i hj)) a ha)\n        (by simp only [List.length_cons]; nlinarith)\n\n/-- Original variable filtering produces only bounded assembled arrays or zero arrays. -/\ntheorem sourceRow_bound [DecidableEq I] {n : ℕ} (R d B : ℕ) (is : List I)\n    (owner : I → Fin n) (as : Addresses I r Q) (keys : List (UniversalType r Q 1))\n    (cache : List (List (Array ℚ))) (i : I) (v : Fin n)\n    (hd : 0<d) (hB : d≤B) (hc : CacheBound cache (R+1) d B) :\n    (sourceRow R is owner as keys cache i v).value.size=R+1 ∧\n      ArrayBound (sourceRow R is owner as keys cache i v).value (R+1) d (is.length*B) := by\n  refine ⟨sumArrays_size _ _ _, ?_⟩\n  apply sumArrays_bound\n  intro j _\n  split_ifs <;> dsimp only\n  · exact (assembled_bound R d B as keys cache i j hd hB hc).2\n  · exact (literal_bound (R+1) d B false hd hB).2\n\n/-- Actual filtered source-row recursion at every stored suffix. -/\ntheorem sourceRow_suffix_bound [DecidableEq I] {n : ℕ} (R d B : ℕ) (is : List I)\n    (owner : I → Fin n) (as : Addresses I r Q) (keys : List (UniversalType r Q 1))\n    (cache : List (List (Array ℚ))) (i : I) (v : Fin n) (k : ℕ)\n    (hd : 0<d) (hB : d≤B) (hc : CacheBound cache (R+1) d B) :\n    ArrayBound (sourceRow R (is.drop k) owner as keys cache i v).value\n      (R+1) d (is.length*B) := by\n  apply arrayBound_mono (sourceRow_bound R d B (is.drop k) owner as keys cache i v hd hB hc).2\n  exact Nat.mul_le_mul_right B (by simp only [List.length_drop]; omega)\n\n/-- Count all scalar array slots of an acquired two-dimensional cache. -/\ndef cacheCells (cache : List (List (Array ℚ))) : ℕ := (cache.map arrayCells).sum\n\n/-- Uniform rectangular caches have their exact materialized array-slot count. -/\ntheorem cacheCells_map {A C : Type*} (xs : List A) (ys : List C)\n    (f : A → C → Array ℚ) (J : ℕ) (hf : ∀ x∈xs, ∀ y∈ys, (f x y).size=J) :\n    cacheCells (xs.map (fun x => ys.map (f x)))=xs.length*ys.length*J := by\n  have hi (x : A) (hx : x∈xs) : arrayCells (ys.map (f x))=ys.length*J := by\n    unfold arrayCells\n    rw [List.map_map]\n    have he : ys.map (Array.size ∘ f x)=ys.map (fun _ => J) :=\n      List.map_congr_left (fun y hy => hf x hx y hy)\n    rw [he]\n    simp\n  unfold cacheCells\n  rw [List.map_map]\n  have he : xs.map (arrayCells ∘ fun x => ys.map (f x))=xs.map (fun _ => ys.length*J) :=\n    List.map_congr_left (fun x hx => hi x hx)\n  rw [he]\n  simp only [List.map_const',List.sum_replicate,smul_eq_mul]\n  ring\n\n/-- This is the actual source-cache materialization, including every universal pair. -/\ntheorem universal_cache_cells (A R : ℕ) (keys : List (UniversalType r Q 1)) :\n    cacheCells (SemiprimeMaterializedSourceRows.acquire A R keys).value=\n      keys.length*keys.length*(R+1) := by\n  rw [SemiprimeMaterializedSourceRows.acquire_value]\n  apply cacheCells_map\n  intro u _ y _\n  exact SemiprimeSourceCodeArrays.compile_size (R+1) _\n\n/-- Actual original-row acquisition retains incidence-by-variable-by-width cells. -/\ntheorem acquire_cells [DecidableEq I] {n : ℕ} (R : ℕ) (is : List I)\n    (owner : I → Fin n) (as : Addresses I r Q) (keys : List (UniversalType r Q 1)) :\n    cacheCells (acquire R is owner as keys).value=is.length*n*(R+1) := by\n  rw [acquire_value]\n  have h := cacheCells_map is (List.finRange n) (fun i v =>\n    (sourceRow R is owner as keys\n      (SemiprimeMaterializedSourceRows.acquire (centered r Q R) R keys).value i v).value)\n    (R+1) (fun _ _ _ _ => sumArrays_size _ _ _)\n  simpa only [List.length_finRange] using h\n\n/-- All original cached rows derive from the actual acquired universal cache. -/\ntheorem acquire_bound [DecidableEq I] {n : ℕ} (R d B : ℕ) (is : List I)\n    (owner : I → Fin n) (as : Addresses I r Q) (keys : List (UniversalType r Q 1))\n    (hd : 0<d) (hB : d≤B)\n    (hc : CacheBound (SemiprimeMaterializedSourceRows.acquire (centered r Q R) R keys).value\n      (R+1) d B) :\n    CacheBound (acquire R is owner as keys).value (R+1) d (is.length*B) := by\n  rw [acquire_value]\n  intro row hr a ha\n  obtain ⟨i,_,rfl⟩ := List.mem_map.mp hr\n  obtain ⟨v,_,rfl⟩ := List.mem_map.mp ha\n  exact sourceRow_bound R d B is owner as keys _ i v hd hB hc\n\n/-- The physical immutable array grid has the same coefficient invariant as its source lists. -/\ndef FrozenBound (a : Array (Array (Array ℚ))) (J d B : ℕ) : Prop :=\n  CacheBound (a.toList.map Array.toList) J d B\n\n/-- Freezing traverses metadata but cannot create new scalar values. -/\ntheorem freeze_bound (rows : List (List (Array ℚ))) (J d B : ℕ)\n    (h : CacheBound rows J d B) :\n    FrozenBound (SemiprimeMaterializedSourceAcquisition.freeze rows) J d B := by\n  simpa [FrozenBound,SemiprimeMaterializedSourceAcquisition.freeze,List.map_map,\n    Function.comp_def] using h\n\n/-- Exact number of scalar slots after the actual immutable copy. -/\ntheorem freeze_cells (rows : List (List (Array ℚ))) :\n    cacheCells ((SemiprimeMaterializedSourceAcquisition.freeze rows).toList.map Array.toList)=\n      cacheCells rows := by\n  simp [SemiprimeMaterializedSourceAcquisition.freeze,List.map_map,Function.comp_def]\n\n/-- Packing labels are generated by the original callback; their values do not affect array shape. -/\ntheorem source_acquisition_cells [DecidableEq I] {n : ℕ} (R : ℕ) (is : List I)\n    (owner : I → Fin n) (keys : List (UniversalType r Q 1))\n    (producer : I → Run (UniversalType r Q 1)) :\n    cacheCells ((SemiprimeMaterializedSourceAcquisition.acquire R is owner keys producer).value.toList.map\n      Array.toList)=is.length*n*(R+1) := by\n  change cacheCells ((SemiprimeMaterializedSourceAcquisition.freeze _).toList.map Array.toList)=_\n  rw [freeze_cells]\n  exact acquire_cells R is owner _ keys\n\n/-- The original paid source acquisition preserves the universal-bound derivation. -/\ntheorem source_acquisition_bound [DecidableEq I] {n : ℕ} (R d B : ℕ) (is : List I)\n    (owner : I → Fin n) (keys : List (UniversalType r Q 1))\n    (producer : I → Run (UniversalType r Q 1)) (hd : 0<d) (hB : d≤B)\n    (hc : CacheBound (SemiprimeMaterializedSourceRows.acquire (centered r Q R) R keys).value\n      (R+1) d B) :\n    FrozenBound (SemiprimeMaterializedSourceAcquisition.acquire R is owner keys producer).value\n      (R+1) d (is.length*B) :=\n  freeze_bound _ _ _ _ (acquire_bound R d B is owner _ keys hd hB hc)\n\nend RiemannGaussian.SemiprimeSourcePullbackHeight\n","RiemannGaussian.SemiprimeSourceWordIdCountsBudget":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceWordIdCountsCore\n\n/-! # Physical-ID count circuit resources\nReachable-state caps are internal proof interfaces; the original-bank endpoint\nuses the concrete copied-key push and concrete bank predicate.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeSourceWordIdCountsBudget\nopen SemiprimeMaterializedWords (Run activeRun)\nopen SemiprimeSourceOffsetInputsCore SemiprimeBitArithmetic\nopen SemiprimeSourceScoreCountBitsCore (sumBits_clock)\nopen SemiprimeSourceWordIdCountsCore\nopen SemiprimeMaterializedScoreEnvironment\n\n/-- Exact reachable-state obligations for both paid physical pushes and leaves. -/\ndef Cap {σ : Type*} (ids : List (List Bool))\n    (push : σ→ List Bool→ List Bool→ Run σ) (terminal : σ→ Run Bool) (P T : ℕ) :\n    List (List Bool)→σ→ Prop\n  | [],env => (terminal env).work≤ T\n  | key::keys,env => ∀ id∈ids,(push env key id).work≤ P ∧\n      Cap ids push terminal P T keys (push env key id).value\n\n/-- Original-depth branch adder and copied-push report envelope. -/\ndef budget (L P T : ℕ) : ℕ→ℕ\n  | 0 => T+2\n  | m+1 => L*(P+budget L P T m+3+11*(1+m*L+L)+7)+1+L+3\n\n/-- Every actual push, child and adder stays in the retained count report. -/\ntheorem count_clock {σ : Type*} (ids : List (List Bool))\n    (push : σ→ List Bool→ List Bool→ Run σ) (terminal : σ→ Run Bool)\n    (P T : ℕ) (keys : List (List Bool)) (env : σ)\n    (h : Cap ids push terminal P T keys env) :\n    (count ids push terminal keys env).clock≤ budget ids.length P T keys.length := by\n  induction keys generalizing env with\n  | nil => exact Nat.add_le_add_right h 2\n  | cons key keys ih =>\n    have hh:=sumBits_clock (fun id =>\n      let next:=push env key id\n      let child:=count ids push terminal keys next.value\n      (⟨child.bits,next.work+child.clock+3⟩:NatRun)) ids\n      (1+keys.length*ids.length) (P+budget ids.length P T keys.length+3)\n      (fun id _ => count_length ids push terminal keys (push env key id).value)\n      (fun id hi => Nat.add_le_add_right (Nat.add_le_add (h id hi).1 (ih _ (h id hi).2)) 3)\n    simpa only [count,budget,List.length_cons,Nat.add_assoc] using\n      Nat.add_le_add_right (Nat.add_le_add_right hh ids.length) 3\n\n/-- At most four original active keys give at most four completion levels. -/\ntheorem budget_mono_depth (L P T m : ℕ) (hL : 0< L) :\n    budget L P T m≤ budget L P T (m+1) := by\n  have h : budget L P T m≤ L*budget L P T m := by\n    simpa only [Nat.one_mul] using Nat.mul_le_mul_right (budget L P T m) hL\n  have h' := Nat.mul_le_mul_left L\n    (show budget L P T m≤ P+budget L P T m+3+11*(1+m*L+L)+7 from by omega)\n  change budget L P T m≤ L*(P+budget L P T m+3+11*(1+m*L+L)+7)+1+L+3\n  omega\n\n/-- The original support-four bound specializes the actual recursive cap. -/\ntheorem budget_le_four (L P T m : ℕ) (hL : 0< L) (hm : m≤4) :\n    budget L P T m≤ budget L P T 4 :=\n  monotone_nat_of_le_succ (fun k => budget_mono_depth L P T k hL) hm\n\n/-- Direct structural padding width, without a numerical count-answer premise. -/\ntheorem padded_length {σ : Type*} {Q : ℕ} (ids : List (List Bool))\n    (push : σ→ List Bool→ List Bool→ Run σ) (terminal : σ→ Run Bool)\n    (p : ScoreProgram Q) (remaining : List ℕ) (env : σ)\n    (hL : 0< ids.length) (hr : remaining.Nodup) :\n    (padded ids push terminal p remaining env).bits.length≤3+8*ids.length+ids.length^4 := by\n  have ha:=SemiprimeSourceScoreCountsPadding.active_length p remaining hr\n  have hc:=count_length ids push terminal (acquireKeys (activeRun (support p) remaining).value).value env\n  rw [acquireKeys_length] at hc\n  have he:=natBits_length (unaryPower ids.length (4-(activeRun (support p) remaining).value.length)).cells.length\n  have hm:=mulBits_length\n    (count ids push terminal (acquireKeys (activeRun (support p) remaining).value).value env).bits\n    (natBits (unaryPower ids.length (4-(activeRun (support p) remaining).value.length)).cells.length).bits\n  simp only [unaryPower_length] at he hm\n  have hp:ids.length^(4-(activeRun (support p) remaining).value.length)≤ ids.length^4 :=\n    Nat.pow_le_pow_right hL (by omega)\n  have hca: (count ids push terminal (acquireKeys (activeRun (support p) remaining).value).value env).bits.length≤\n      1+4*ids.length := hc.trans (by gcongr)\n  simp only [padded,unaryPower_length]\n  omega\n\n/-- Every actual lane suffix has a structural physical-word bound. -/\ntheorem evaluate_length {σ : Type*} {Q : ℕ} (ids : List (List Bool))\n    (push : σ→ List Bool→ List Bool→ Run σ) (terminal : ScoreProgram Q→σ→ Run Bool)\n    (programs : List (ScoreProgram Q)) (remaining : List ℕ) (env : σ)\n    (hL : 0< ids.length) (hr : remaining.Nodup) :\n    (evaluate ids push terminal programs remaining env).incidence.length≤\n      3+8*ids.length+ids.length^4+programs.length ∧\n    (evaluate ids push terminal programs remaining env).head.length≤\n      3+8*ids.length+ids.length^4+programs.length := by\n  induction programs with\n  | nil => simp [evaluate]\n  | cons p programs ih =>\n    have ht:=padded_length ids push (terminal p) p remaining env hL hr\n    have hi:=(addBits_counts (padded ids push (terminal p) p remaining env).bits\n      (evaluate ids push terminal programs remaining env).incidence false).2.2.2.2\n    have hh:=(addBits_counts (padded ids push (terminal p) p remaining env).bits\n      (evaluate ids push terminal programs remaining env).head false).2.2.2.2\n    cases p <;> simp only [evaluate,List.length_cons] <;> constructor <;> omega\n\nend RiemannGaussian.SemiprimeSourceWordIdCountsBudget\n","RiemannGaussian.SemiprimeSparseBlockPeriodObstruction":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSeedMomentPeriodGapObstruction\n\n/-!\n# Period gaps for arbitrarily placed original seed blocks\n\nThe sample may use any finite set of block positions. Its gap condition\nkeeps the signed differences of those positions, rather than enlarging\nthem to a consecutive interval. Under gaps in both actual local orders,\nno pair of sampled points yields a proper factor. A gap in one component\nretains half the sample mass and forces the corresponding degree floor\nfor the whole original positive moment carrier.\n\nThe separate classical argument in the investigation journal supplies\ninfinitely many actual long inputs for each predetermined sparse layout.\nIts analytic density and selector counting are not formalized here. The\nstronger consequence of the OpenAI prime-predecessor manuscript is kept\nseparate from the published Baker--Harman input and its verification.\n-/\n\nnamespace RiemannGaussian.SemiprimeSparseBlockPeriodObstruction\n\nopen scoped BigOperators\nopen Polynomial SemiprimeSeedMomentPoleRetention SemiprimeSeedMomentPrefixRigidity\nopen SemiprimeSeedPointRigidity SemiprimeSeedMomentCancellationObstruction\nopen SemiprimeSeedSumAcquisition SemiprimeLocalOrderRouting SemiprimeCentreFreeCover\nopen SemiprimeGlobalPhaseCancellation SemiprimeSeedFiniteTransfer\nopen SemiprimeSharedIntervalJet SemiprimeIntervalJet\n\n/-- The actual period avoids the windows at every signed layout distance.\nThe condition does not fill in unsampled block positions. -/\nabbrev BlockSetPeriodGap (m : ℕ) (blocks : Finset ℕ) (R : ℕ) : Prop :=\n  ∀ k∈blocks,∀ k₀∈blocks,k≠k₀ → ∀ a : ℤ,\n    4*(m : ℤ)^2 < |4*(m : ℤ)^3*((k : ℤ)-k₀)-a*R|\n\n/-- A local equality in this layout has the same block and exact offset. -/\ntheorem point_reduction_eq_blocks_offsets {N m j j₀ k k₀ : ℕ}\n    {blocks : Finset ℕ} {R : Type*} [CommRing R]\n    (f : ZMod N→+*R) (g : (ZMod N)ˣ)\n    (hm : 4≤m) (hmprime : m.Prime)\n    (hj : 1≤j) (hjm : j<m) (hj₀ : 1≤j₀) (hj₀m : j₀<m)\n    (hk : k∈blocks) (hk₀ : k₀∈blocks)\n    (horder : 4*m^2<orderOf (Units.map f.toMonoidHom g))\n    (hgap : BlockSetPeriodGap m blocks (orderOf (Units.map f.toMonoidHom g)))\n    (he : f (seedPoint g m (4*m) j k)=f (seedPoint g m (4*m) j₀ k₀)) :\n    k=k₀ ∧ seedOffset N m j=seedOffset N m j₀ := by\n  have hjcop : j.Coprime m :=\n    (hmprime.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hjm)).symm\n  have hj₀cop : j₀.Coprime m :=\n    (hmprime.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hj₀m)).symm\n  have hu : Units.map f.toMonoidHom (g^pointExponent N m (4*m) j k)=\n      Units.map f.toMonoidHom (g^pointExponent N m (4*m) j₀ k₀) := by\n    apply Units.ext\n    change f ((g^pointExponent N m (4*m) j k : (ZMod N)ˣ) : ZMod N)=\n      f ((g^pointExponent N m (4*m) j₀ k₀ : (ZMod N)ˣ) : ZMod N)\n    simpa only [seedPoint_eq_zpow g hmprime.pos hjcop,\n      seedPoint_eq_zpow g hmprime.pos hj₀cop] using he\n  rw [map_zpow,map_zpow] at hu\n  obtain ⟨a,ha⟩ := orderOf_dvd_sub_iff_zpow_eq_zpow.mpr hu\n  have hb := seed_offset_difference_bound (N:=N) (by omega) hj hjm hj₀ hj₀m\n  have hsame : k=k₀ := by\n    by_contra hn\n    have hh := hgap k hk k₀ hk₀ hn (-a)\n    have heq : 4*(m : ℤ)^3*((k : ℤ)-k₀)-(-a)*orderOf (Units.map f.toMonoidHom g)=\n        seedOffset N m j-seedOffset N m j₀ := by\n      simp only [pointExponent,Nat.cast_mul] at ha\n      norm_num only [Nat.cast_ofNat] at ha\n      linear_combination -ha\n    rw [heq] at hh\n    exact (not_lt_of_ge hb) hh\n  have hdδ : (orderOf (Units.map f.toMonoidHom g) : ℤ)∣\n      seedOffset N m j-seedOffset N m j₀ := by\n    rw [hsame] at ha\n    refine ⟨a,?_⟩\n    simp only [pointExponent] at ha\n    linear_combination ha\n  have ho : 4*(m : ℤ)^2<(orderOf (Units.map f.toMonoidHom g) : ℤ) := by\n    exact_mod_cast horder\n  have hsmall : (seedOffset N m j-seedOffset N m j₀).natAbs<\n      (orderOf (Units.map f.toMonoidHom g) : ℤ).natAbs := by\n    rw [←Int.natCast_natAbs] at hb\n    simpa only [Int.natAbs_natCast] using\n      (show (seedOffset N m j-seedOffset N m j₀).natAbs<\n        orderOf (Units.map f.toMonoidHom g) by exact_mod_cast hb.trans_lt ho)\n  exact ⟨hsame,sub_eq_zero.mp (Int.eq_zero_of_dvd_of_natAbs_lt_natAbs hdδ hsmall)⟩\n\n/-- These gaps prevent local-only collisions at every selected position. -/\ntheorem point_eq_of_period_gap_reduction {N m j j₀ k k₀ : ℕ}\n    {blocks : Finset ℕ} {R : Type*} [CommRing R]\n    (f : ZMod N→+*R) (g : (ZMod N)ˣ)\n    (hm : 4≤m) (hmprime : m.Prime)\n    (hj : 1≤j) (hjm : j<m) (hj₀ : 1≤j₀) (hj₀m : j₀<m)\n    (hk : k∈blocks) (hk₀ : k₀∈blocks)\n    (horder : 4*m^2<orderOf (Units.map f.toMonoidHom g))\n    (hgap : BlockSetPeriodGap m blocks (orderOf (Units.map f.toMonoidHom g)))\n    (he : f (seedPoint g m (4*m) j k)=f (seedPoint g m (4*m) j₀ k₀)) :\n    seedPoint g m (4*m) j k=seedPoint g m (4*m) j₀ k₀ := by\n  obtain ⟨hblock,hδ⟩ := point_reduction_eq_blocks_offsets f g hm hmprime\n    hj hjm hj₀ hj₀m hk hk₀ horder hgap he\n  have hjcop : j.Coprime m :=\n    (hmprime.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hjm)).symm\n  have hj₀cop : j₀.Coprime m :=\n    (hmprime.coprime_iff_not_dvd.mpr (Nat.not_dvd_of_pos_of_lt (by omega) hj₀m)).symm\n  rw [seedPoint_eq_zpow g hmprime.pos hjcop,seedPoint_eq_zpow g hmprime.pos hj₀cop]\n  simp only [pointExponent,hblock,hδ]\n\n/-- Both actual local gaps make every distinct sampled point difference a unit. -/\ntheorem original_sample_unit_separated {p q m : ℕ} {blocks : Finset ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hm : 4≤m) (hmprime : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hgapP : BlockSetPeriodGap m blocks (orderOf (Units.map\n      (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom (projectedUnit g m))))\n    (hgapQ : BlockSetPeriodGap m blocks (orderOf (Units.map\n      (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom (projectedUnit g m)))) :\n    let sample := (Finset.range (m-1)) ×ˢ blocks\n    let point := fun jk : ℕ×ℕ => seedPoint (projectedUnit g m) m (4*m) (jk.1+1) jk.2\n    ∀ u∈sample,∀ v∈sample,point u≠point v → IsUnit (point u-point v) := by\n  dsimp only\n  intro u hu v hv hne\n  have huj : u.1+1<m := by have hh := Finset.mem_range.mp (Finset.mem_product.mp hu).1; omega\n  have hvj : v.1+1<m := by have hh := Finset.mem_range.mp (Finset.mem_product.mp hv).1; omega\n  have huk := (Finset.mem_product.mp hu).2\n  have hvk := (Finset.mem_product.mp hv).2\n  apply isUnit_of_prime_reductions hp hq\n  · rw [map_sub]\n    intro he\n    exact hne (point_eq_of_period_gap_reduction _ (projectedUnit g m) hm hmprime\n      (by omega) huj (by omega) hvj huk hvk\n      (by have hh := hlong.2.2.2.1.1\n          change (2*m)^2<orderOf (Units.map\n            (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom (projectedUnit g m)) at hh\n          nlinarith only [hh]) hgapP (sub_eq_zero.mp he))\n  · rw [map_sub]\n    intro he\n    exact hne (point_eq_of_period_gap_reduction _ (projectedUnit g m) hm hmprime\n      (by omega) huj (by omega) hvj huk hvk\n      (by have hh := hlong.2.2.2.1.2\n          change (2*m)^2<orderOf (Units.map\n            (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom (projectedUnit g m)) at hh\n          nlinarith only [hh]) hgapQ (sub_eq_zero.mp he))\n\n/-- Proper-factor credit is impossible for every pair, including global duplicates. -/\ntheorem original_sample_no_proper_difference {p q m : ℕ} {blocks : Finset ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hm : 4≤m) (hmprime : m.Prime)\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hgapP : BlockSetPeriodGap m blocks (orderOf (Units.map\n      (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom (projectedUnit g m))))\n    (hgapQ : BlockSetPeriodGap m blocks (orderOf (Units.map\n      (ZMod.castHom (dvd_mul_left q p) (ZMod q)).toMonoidHom (projectedUnit g m)))) :\n    let sample := (Finset.range (m-1)) ×ˢ blocks\n    let point := fun jk : ℕ×ℕ => seedPoint (projectedUnit g m) m (4*m) (jk.1+1) jk.2\n    ∀ u∈sample,∀ v∈sample,\n      ¬SemiprimeGroupSelection.ProperDivisor (p*q) ((p*q).gcd (point u-point v).val) := by\n  let : NeZero (p*q) := ⟨(Nat.mul_pos hp.pos hq.pos).ne'⟩\n  dsimp only\n  intro u hu v hv hproper\n  by_cases he : seedPoint (projectedUnit g m) m (4*m) (u.1+1) u.2=\n      seedPoint (projectedUnit g m) m (4*m) (v.1+1) v.2\n  · rw [he,sub_self,ZMod.val_zero,Nat.gcd_zero_right] at hproper\n    exact (Nat.lt_irrefl (p*q)) hproper.2.1\n  · have hunit := original_sample_unit_separated hp hq hm hmprime g hlong hgapP hgapQ u hu v hv he\n    have hg := (SemiprimeBulkNorm.gcd_one_iff_unit _).mpr hunit\n    rw [hg] at hproper\n    exact (Nat.lt_irrefl 1) hproper.1\n\n/-- One local gap retains half the raw sample mass throughout the original domain. -/\ntheorem original_sample_local_card_lower {p q m : ℕ} {blocks : Finset ℕ}\n    {R : Type*} [CommRing R] [DecidableEq R]\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : 4≤m) (hmprime : m.Prime)\n    (hblocks : blocks⊆Finset.range (blockCount m (4*m)))\n    (f : ZMod (p*q)→+*R) (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (horder : 4*m^2<orderOf (Units.map f.toMonoidHom (projectedUnit g m)))\n    (hgap : BlockSetPeriodGap m blocks (orderOf (Units.map f.toMonoidHom (projectedUnit g m)))) :\n    let sample := (Finset.range (m-1)) ×ˢ blocks\n    let point := fun jk : ℕ×ℕ => seedPoint (projectedUnit g m) m (4*m) (jk.1+1) jk.2\n    (m-1)*blocks.card≤2*(sample.image (fun jk => f (point jk))).card := by\n  classical\n  let sample := (Finset.range (m-1)) ×ˢ blocks\n  let point := fun jk : ℕ×ℕ => seedPoint (projectedUnit g m) m (4*m) (jk.1+1) jk.2\n  let S := sample.image point\n  have hdomain : sample⊆pointDomain m (4*m) := by\n    intro jk hjk\n    have hh := Finset.mem_product.mp hjk\n    exact Finset.mem_product.mpr ⟨hh.1,hblocks hh.2⟩\n  have hfiber : ∀ x∈S,(sample.filter fun jk => point jk=x).card≤2 := by\n    intro x _\n    have hsub : (sample.filter fun jk => point jk=x)⊆pointFiber (projectedUnit g m) m (4*m) x := by\n      intro jk hjk\n      exact Finset.mem_filter.mpr ⟨hdomain (Finset.mem_filter.mp hjk).1,(Finset.mem_filter.mp hjk).2⟩\n    exact (Finset.card_le_card hsub).trans (pointFiber_card_le_two hp hq hpq hm hmprime\n      (original_modulus_coprime hp hq hm g hlong) (by omega) (by nlinarith only [hm]) g hlong x)\n  have hraw : (m-1)*blocks.card≤2*S.card := by\n    calc\n      (m-1)*blocks.card=sample.card := by simp only [sample,Finset.card_product,Finset.card_range]\n      _=∑ x∈S,(sample.filter fun jk => point jk=x).card := Finset.card_eq_sum_card_image point sample\n      _≤∑ _x∈S,2 := Finset.sum_le_sum hfiber\n      _=2*S.card := by simp only [Finset.sum_const,smul_eq_mul,mul_comm]\n  have hinj : Set.InjOn (fun x => f x) S := by\n    intro x hx y hy he\n    obtain ⟨u,hu,rfl⟩ := Finset.mem_image.mp hx\n    obtain ⟨v,hv,rfl⟩ := Finset.mem_image.mp hy\n    have huj : u.1+1<m := by have hh := Finset.mem_range.mp (Finset.mem_product.mp hu).1; omega\n    have hvj : v.1+1<m := by have hh := Finset.mem_range.mp (Finset.mem_product.mp hv).1; omega\n    exact point_eq_of_period_gap_reduction f (projectedUnit g m) hm hmprime\n      (by omega) huj (by omega) hvj (Finset.mem_product.mp hu).2\n      (Finset.mem_product.mp hv).2 horder hgap he\n  have hcard : (S.image (fun x => f x)).card=S.card := Finset.card_image_of_injOn hinj\n  change (m-1)*blocks.card≤2*(sample.image (fun jk => f (point jk))).card\n  rw [←hcard] at hraw\n  simpa only [S,Finset.image_image,Function.comp_def] using hraw\n\n/-- The full original positive moment carrier must retain this sparse local support. -/\ntheorem original_period_gap_denominator_degree {p q m : ℕ} {blocks : Finset ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : 4≤m) (hmprime : m.Prime)\n    (hblocks : blocks⊆Finset.range (blockCount m (4*m)) ∧\n      blocks⊆Finset.range (seedLength m/(4*m)+1))\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hgap : BlockSetPeriodGap m blocks (orderOf (Units.map\n      (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom (projectedUnit g m))))\n    (U V : (ZMod (p*q))[X]) (hU : U.coeff 0=1)\n    (hUV : (U : PowerSeries (ZMod (p*q)))*centredGridSeries (projectedUnit g m) m (4*m)\n      (seedLength m/(4*m)+1)=(V : PowerSeries (ZMod (p*q)))) :\n    (m-1)*blocks.card≤2*U.natDegree := by\n  classical\n  let sample := (Finset.range (m-1)) ×ˢ blocks\n  let I := (Finset.range (m-1)) ×ˢ (Finset.range (seedLength m/(4*m)+1))\n  let point := fun jk : ℕ×ℕ => seedPoint (projectedUnit g m) m (4*m) (jk.1+1) jk.2\n  let f := ZMod.castHom (dvd_mul_right p q) (ZMod p)\n  have hsample : sample⊆I := by\n    intro jk hjk\n    have hh := Finset.mem_product.mp hjk\n    exact Finset.mem_product.mpr ⟨hh.1,hblocks.2 hh.2⟩\n  have hlower := original_sample_local_card_lower hp hq hpq hm hmprime hblocks.1 f g hlong\n    (by have hh := hlong.2.2.2.1.1\n        change (2*m)^2<orderOf (Units.map f.toMonoidHom (projectedUnit g m)) at hh\n        nlinarith only [hh]) hgap\n  have hupper := (original_denominator_local_degrees hp hq hm g hlong U V hU hUV).1\n  have hsub : sample.image (fun jk => f (point jk))⊆I.image (fun jk => f (point jk)) :=\n    Finset.image_subset_image hsample\n  exact hlower.trans (Nat.mul_le_mul_left 2 ((Finset.card_le_card hsub).trans hupper))\n\n/-- Matching a genuine finite prefix cannot bypass the same whole-family degree floor. -/\ntheorem original_period_gap_prefix_degree {p q m d : ℕ} {blocks : Finset ℕ}\n    (hp : p.Prime) (hq : q.Prime) (hpq : p≠q) (hm : 4≤m) (hmprime : m.Prime)\n    (hd : d≤m^2) (hblocks : blocks⊆Finset.range (blockCount m (4*m)) ∧\n      blocks⊆Finset.range (seedLength m/(4*m)+1))\n    (g : (ZMod (p*q))ˣ) (hlong : LongData g m)\n    (hgap : BlockSetPeriodGap m blocks (orderOf (Units.map\n      (ZMod.castHom (dvd_mul_right p q) (ZMod p)).toMonoidHom (projectedUnit g m))))\n    (U V : (ZMod (p*q))[X]) (hU : U.coeff 0=1)\n    (hUd : U.natDegree≤d) (hVd : V.natDegree≤d)\n    (hprefix : ∀ r≤2*(d+(m-1)), PowerSeries.coeff r\n      ((U : PowerSeries (ZMod (p*q)))*centredGridSeries (projectedUnit g m) m (4*m)\n        (seedLength m/(4*m)+1))=V.coeff r) : (m-1)*blocks.card≤2*d := by\n  have hUV := original_polynomial_prefix_certificate hp hq hm hd g hlong U V hU hUd hVd hprefix\n  exact (original_period_gap_denominator_degree hp hq hpq hm hmprime hblocks\n    g hlong hgap U V hU hUV).trans (Nat.mul_le_mul_left 2 hUd)\n\nend RiemannGaussian.SemiprimeSparseBlockPeriodObstruction\n","RiemannGaussian.SemiprimeSparseResidueGaussRadius":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSparseResidueGauss\nimport Mathlib.Analysis.SpecialFunctions.Sqrt\nimport Mathlib.Algebra.Order.Floor.Div\n\n/-! Exact producer-certificate closure for the quadratic quotient radius.\nNo reduced basis, residue acquisition, or bit-complexity theorem is asserted. -/\n\nnamespace RiemannGaussian.SemiprimeSparseResidueGaussRadius\n\n/-- Real form of the exact reduced-Gram certificate. -/\ntheorem gram_bound {F F₂ dot N W : ℝ} (hF : 0 ≤ F) (ho : F ≤ F₂)\n    (hr : |2 * dot| ≤ F) (hg : F * F₂ - dot ^ 2 = N ^ 2 * W) :\n    3 * F ^ 2 ≤ 4 * N ^ 2 * W := by\n  have hl := neg_abs_le (2 * dot)\n  have hu := le_abs_self (2 * dot)\n  have hp : 0 ≤ (F - 2 * dot) * (F + 2 * dot) :=\n    mul_nonneg (by linarith) (by linarith)\n  have hm := mul_nonneg hF (sub_nonneg.mpr ho)\n  nlinarith\n\n/-- The lifted norm bound follows from the Gram and nearest-line certificates. -/\ntheorem lifted_norm_bound {N H s X F T : ℝ} (hN : 0 < N) (hH : 0 < H)\n    (hX : 1 ≤ X) (hs : 0 ≤ s) (hsH : s < H) (hscale : H ^ 3 ≤ N)\n    (hgram : 3 * F ^ 2 ≤ 4 * N ^ 2 * (X ^ 2 * (s ^ 2 + H ^ 2 * X ^ 2)))\n    (hlift : 4 * (s ^ 2 + H ^ 2 * X ^ 2) * T ≤\n      4 * X ^ 2 * F + (s ^ 2 + H ^ 2 * X ^ 2) ^ 2) :\n    2 * H * T ≤ 5 * N * X ^ 2 := by\n  let D := s ^ 2 + H ^ 2 * X ^ 2\n  have hXp : 0 < X := by linarith\n  have hDp : 0 < D := by dsimp [D]; positivity\n  have hs2 : s ^ 2 ≤ H ^ 2 := by nlinarith\n  have hX2 : 1 ≤ X ^ 2 := by nlinarith\n  have hDlo : H ^ 2 * X ^ 2 ≤ D := by dsimp [D]; nlinarith [sq_nonneg s]\n  have hDhi : D ≤ 2 * H ^ 2 * X ^ 2 := by\n    dsimp [D]\n    nlinarith [mul_nonneg (sq_nonneg H) (sub_nonneg.mpr hX2)]\n  have hHF : H * F ≤ 2 * N * D := by\n    have hm := mul_nonneg (sq_nonneg H) (sub_nonneg.mpr hgram)\n    have hn := mul_nonneg (by positivity : 0 ≤ 4 * N ^ 2 * D) (sub_nonneg.mpr hDlo)\n    have hpos : 0 ≤ 2 * N * D := by positivity\n    change 3 * F ^ 2 ≤ 4 * N ^ 2 * (X ^ 2 * D) at hgram\n    nlinarith [sq_nonneg (H * F + 2 * N * D)]\n  have hHD : H * D ≤ 2 * N * X ^ 2 := by\n    have h1 := mul_le_mul_of_nonneg_left hDhi hH.le\n    have h2 := mul_le_mul_of_nonneg_right hscale (by positivity : 0 ≤ 2 * X ^ 2)\n    nlinarith\n  change 4 * D * T ≤ 4 * X ^ 2 * F + D ^ 2 at hlift\n  have h1 := mul_le_mul_of_nonneg_left hlift hH.le\n  have h2 := mul_le_mul_of_nonneg_left hHF (by positivity : 0 ≤ 4 * X ^ 2)\n  have h3 := mul_le_mul_of_nonneg_right hHD hDp.le\n  nlinarith\n\n/-- Three-term evaluation is controlled by the weighted coefficient norm. -/\ntheorem evaluation_bound {a b c x X : ℝ} (hx : 0 ≤ x) (hxX : x ≤ X) :\n    (c + b * x + a * x ^ 2) ^ 2 ≤\n      3 * (c ^ 2 + X ^ 2 * b ^ 2 + X ^ 4 * a ^ 2) := by\n  have hX : 0 ≤ X := le_trans hx hxX\n  have hx2 : x ^ 2 ≤ X ^ 2 := by nlinarith\n  have hx4 : x ^ 4 ≤ X ^ 4 := by nlinarith [sq_nonneg (X ^ 2 - x ^ 2)]\n  have hb := mul_le_mul_of_nonneg_right hx2 (sq_nonneg b)\n  have ha := mul_le_mul_of_nonneg_right hx4 (sq_nonneg a)\n  nlinarith [sq_nonneg (c - b * x), sq_nonneg (c - a * x ^ 2),\n    sq_nonneg (b * x - a * x ^ 2)]\n\n/-- Squared quotient radius, with every target norm discharged by certificates. -/\ntheorem quotient_radius_squared {N H s X F F₂ dot a b c x P σ : ℝ}\n    (hN : 0 < N) (hH : 0 < H) (hX : 1 ≤ X) (hs : 0 ≤ s) (hsH : s < H)\n    (hscale : H ^ 3 ≤ N) (hF : 0 ≤ F) (ho : F ≤ F₂)\n    (hr : |2 * dot| ≤ F)\n    (hg : F * F₂ - dot ^ 2 = N ^ 2 * (X ^ 2 * (s ^ 2 + H ^ 2 * X ^ 2)))\n    (hlift : 4 * (s ^ 2 + H ^ 2 * X ^ 2) *\n      (c ^ 2 + X ^ 2 * b ^ 2 + X ^ 4 * a ^ 2) ≤\n      4 * X ^ 2 * F + (s ^ 2 + H ^ 2 * X ^ 2) ^ 2)\n    (hx : 0 ≤ x) (hxX : x ≤ X) (hP : H * X ≤ 2 * P)\n    (heval : c + b * x + a * x ^ 2 = σ * P) :\n    H ^ 3 * σ ^ 2 ≤ 30 * N := by\n  have hn := lifted_norm_bound hN hH hX hs hsH hscale (gram_bound hF ho hr hg) hlift\n  have he := evaluation_bound (a := a) (b := b) (c := c) hx hxX\n  rw [heval] at he\n  have hXp : 0 < X := by linarith\n  have hPp : 0 < P := by nlinarith\n  have hP2 : H ^ 2 * X ^ 2 ≤ 4 * P ^ 2 := by\n    have hp := mul_nonneg (sub_nonneg.mpr hP) (by positivity : 0 ≤ 2 * P + H * X)\n    nlinarith\n  have h1 := mul_le_mul_of_nonneg_left he (by positivity : 0 ≤ 2 * H)\n  have h2 := mul_le_mul_of_nonneg_left hP2 (by positivity : 0 ≤ H * σ ^ 2)\n  have hc : X ^ 2 * (H ^ 3 * σ ^ 2) ≤ X ^ 2 * (30 * N) := by nlinarith\n  exact (mul_le_mul_iff_right₀ (sq_pos_of_pos hXp)).mp hc\n\n/-- The squared bound gives the strict advertised real radius. -/\ntheorem radius_of_squared {N H σ : ℝ} (hN : 0 < N) (hH : 0 < H)\n    (hbound : H ^ 3 * σ ^ 2 ≤ 30 * N) :\n    |σ| < 6 * Real.sqrt (N / H ^ 3) := by\n  have hp : 0 < N / H ^ 3 := div_pos hN (pow_pos hH 3)\n  have hs := Real.sq_sqrt hp.le\n  have hb : σ ^ 2 ≤ 30 * N / H ^ 3 := by\n    apply (le_div_iff₀ (pow_pos hH 3)).mpr\n    nlinarith\n  have he : 30 * N / H ^ 3 = 30 * (N / H ^ 3) := by ring\n  rw [he] at hb\n  apply (sq_lt_sq₀ (abs_nonneg σ) (by positivity : 0 ≤ 6 * Real.sqrt (N / H ^ 3))).mp\n  nlinarith [sq_abs σ]\n\n/-- Full strict radius closure directly from the exact producer certificates. -/\ntheorem quotient_radius {N H s X F F₂ dot a b c x P σ : ℝ}\n    (hN : 0 < N) (hH : 0 < H) (hX : 1 ≤ X) (hs : 0 ≤ s) (hsH : s < H)\n    (hscale : H ^ 3 ≤ N) (hF : 0 ≤ F) (ho : F ≤ F₂)\n    (hr : |2 * dot| ≤ F)\n    (hg : F * F₂ - dot ^ 2 = N ^ 2 * (X ^ 2 * (s ^ 2 + H ^ 2 * X ^ 2)))\n    (hlift : 4 * (s ^ 2 + H ^ 2 * X ^ 2) *\n      (c ^ 2 + X ^ 2 * b ^ 2 + X ^ 4 * a ^ 2) ≤\n      4 * X ^ 2 * F + (s ^ 2 + H ^ 2 * X ^ 2) ^ 2)\n    (hx : 0 ≤ x) (hxX : x ≤ X) (hP : H * X ≤ 2 * P)\n    (heval : c + b * x + a * x ^ 2 = σ * P) :\n    |σ| < 6 * Real.sqrt (N / H ^ 3) := by\n  exact radius_of_squared hN hH\n    (quotient_radius_squared hN hH hX hs hsH hscale hF ho hr hg hlift hx hxX hP heval)\n\n/-- The implemented integer interval follows from a certified ceiling radius.\nThe caller still constructs `R` and proves `N ≤ H^3*R^2` (for example by\n`R = ceil_sqrt (ceil (N/H^3))`); no ceiling algorithm is assumed here. -/\ntheorem integer_cap {N H R σ : ℤ} (hH : 0 < H) (hR : 1 ≤ R)\n    (hsigma : H ^ 3 * σ ^ 2 ≤ 30 * N) (hceil : N ≤ H ^ 3 * R ^ 2) :\n    |σ| ≤ 8 * R := by\n  have hc : H ^ 3 * σ ^ 2 ≤ H ^ 3 * (30 * R ^ 2) := by nlinarith\n  have hs : σ ^ 2 ≤ 30 * R ^ 2 :=\n    (mul_le_mul_iff_right₀ (pow_pos hH 3)).mp hc\n  have hstrict : |σ| < 8 * R := by\n    apply (sq_lt_sq₀ (abs_nonneg σ) (by omega : 0 ≤ 8 * R)).mp\n    nlinarith [sq_abs σ]\n  exact hstrict.le\n\n/-- The explicit integer radius used by the executable cap. -/\ndef publicRadius (N H : ℕ) : ℕ := Nat.sqrt (((N + H ^ 3 - 1) / H ^ 3) - 1) + 1\n\n/-- The public radius is positive without any input promise. -/\ntheorem publicRadius_pos (N H : ℕ) : 1 ≤ publicRadius N H := by\n  unfold publicRadius\n  omega\n\n/-- The explicit ceiling-square-root formula certifies the required interval. -/\ntheorem publicRadius_covers {N H : ℕ} (hN : 0 < N) (hH : 0 < H) :\n    N ≤ H ^ 3 * publicRadius N H ^ 2 := by\n  let t := (N + H ^ 3 - 1) / H ^ 3\n  have hn : N ≤ H ^ 3 * t := by\n    exact (ceilDiv_le_iff_le_mul (pow_pos hH 3)).mp (le_refl (N ⌈/⌉ H ^ 3))\n  have ht : 1 ≤ t := by\n    by_contra h\n    have hz : t = 0 := Nat.eq_zero_of_not_pos h\n    rw [hz, mul_zero] at hn\n    omega\n  have hs := Nat.lt_succ_sqrt' (t - 1)\n  have hs' : t ≤ (Nat.sqrt (t - 1) + 1) ^ 2 := by\n    change t - 1 < (Nat.sqrt (t - 1) + 1) ^ 2 at hs\n    omega\n  exact hn.trans (Nat.mul_le_mul_left (H ^ 3) hs')\n\n/-- The squared Gauss radius reaches the implemented, input-derived cap. -/\ntheorem public_integer_cap {N H : ℕ} {σ : ℤ} (hN : 0 < N) (hH : 0 < H)\n    (hsigma : (H : ℤ) ^ 3 * σ ^ 2 ≤ 30 * (N : ℤ)) :\n    |σ| ≤ 8 * (publicRadius N H : ℤ) := by\n  apply integer_cap (by exact_mod_cast hH) (by exact_mod_cast publicRadius_pos N H) hsigma\n  exact_mod_cast publicRadius_covers hN hH\n\nend RiemannGaussian.SemiprimeSparseResidueGaussRadius\n","RiemannGaussian.SemiprimeUniversalNumeratorExecution":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeSourceLayout\n\n/-! # Executed finite universal integer numerator entries\nThe ordered differences use the computable sorted Fin list, rather than the\nnoncomputable multiset representative `Finset.toList` in the semantic formula.\n-/\nset_option autoImplicit false\nnamespace RiemannGaussian.SemiprimeUniversalNumeratorExecution\nopen scoped BigOperators\nopen OAI.Algorithms.SubexponentialSAT\nopen MulticolorTypes Subexp.MatrixSupport BinomialInterpolation\nopen SqrtLog\nvariable {r Q Δ R : ℕ}\n\n/-- Commuting register swaps make the difference independent of list ordering. -/\ntheorem integerDifference_perm (i : Fin Δ) {a b : List (Fin Q)} (h : a.Perm b)\n    (f : UniversalType r Q Δ → ℤ) (u : UniversalType r Q Δ) :\n    LayoutNumerator.integerDifference i a f u = LayoutNumerator.integerDifference i b f u := by\n  induction h generalizing u with\n  | nil => rfl\n  | cons a h ih => simp only [LayoutNumerator.integerDifference, ih]\n  | swap a b l =>\n    simp only [LayoutNumerator.integerDifference]\n    rw [swapPositions_commute i {a} {b}]\n    ring\n  | trans h₁ h₂ ih₁ ih₂ => exact (ih₁ u).trans (ih₂ u)\n\n/-- Literal integer entry from the supplied finite parity vector and all active subsets. -/\ndef entry (c : Fin R → ℤ) (i : Fin Δ) (t : Fin Q)\n    (u y : UniversalType r Q Δ) : ℤ :=\n  ∑ j ∈ Finset.range R, extendCoefficients c j * 2^(R-1-j) *\n    ∑ S ∈ (activePositions t).powersetCard j,\n      LayoutNumerator.integerDifference i (S.sort (· ≤ ·)) (LayoutNumerator.integerDelta y)\n        (swapPositions i (activePositions t) u)\n\n/-- The compiled sorted-difference formula is the source's actual integer numerator. -/\ntheorem entry_eq (A : ℕ) (c : Fin R → ℤ)\n    (hc : c = parityCoefficients (K := ℤ) A R)\n    (i : Fin Δ) (t : Fin Q) (u y : UniversalType r Q Δ) :\n    entry c i t u y = LayoutNumerator.entry i t A R u y := by\n  subst c\n  unfold entry LayoutNumerator.entry\n  apply Finset.sum_congr rfl\n  intro j _\n  congr 1\n  apply Finset.sum_congr rfl\n  intro S _\n  exact integerDifference_perm i (Finset.sort_perm_toList _ _) _ _\n\n/-- Zero extension to the head/slot joint fibre, with all membership decisions explicit. -/\ndef extended (c : Fin R → ℤ) (i : Fin Δ) (t : Fin Q) (g : Fin r)\n    (u y : UniversalType r Q Δ) : ℤ :=\n  if u.head t = g ∧ u.slot i t ≠ g then\n    if y.head t = g ∧ y.slot i t ≠ g then entry c i t u y else 0\n  else 0\n\n/-- The zero extension is the very same source joint numerator, not an arbitrary matrix. -/\ntheorem extended_eq (A : ℕ) (c : Fin R → ℤ)\n    (hc : c = parityCoefficients (K := ℤ) A R)\n    (i : Fin Δ) (t : Fin Q) (g : Fin r) (u y : UniversalType r Q Δ) :\n    extended c i t g u y = SubexpAnnihilation.zeroExtendMatrix (joint t g i)\n      (LayoutNumerator.joint i t g A R) u y := by\n  unfold extended SubexpAnnihilation.zeroExtendMatrix\n  change (if u.head t = g ∧ u.slot i t ≠ g then\n      if y.head t = g ∧ y.slot i t ≠ g then entry c i t u y else 0 else 0) =\n    (if u.head t = g ∧ u.slot i t ≠ g then\n      if y.head t = g ∧ y.slot i t ≠ g then LayoutNumerator.entry i t A R u y else 0 else 0)\n  rw [entry_eq A c hc]\n\n#print axioms entry_eq\nend RiemannGaussian.SemiprimeUniversalNumeratorExecution\n","RiemannGaussian.SemiprimeWordPacketHermiteInput":"/-\nCopyright (c) 2026 David Sanftenberg. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: David Sanftenberg\n-/\nimport RiemannGaussian.SemiprimeWordPacketCounter\nimport RiemannGaussian.SemiprimeMaterializedWordFibreBounds\n\n/-! # A common Hermite input height for actual acquired word packets\nThe denominator below is proof-only. Runtime computes only the sum of actual\nnode widths; no large common denominator or encoded packet answer is supplied.\n-/\nset_option autoImplicit false\nset_option maxHeartbeats 1200000\nnamespace RiemannGaussian.SemiprimeWordPacketHermiteInput\nopen scoped BigOperators\nopen SemiprimeJetArrayHeight SemiprimeLocalExecutionHeight SemiprimeJetArray\nopen SemiprimeRationalBits SemiprimeJetBits SemiprimeLocalBits\nopen SemiprimeNodeArrayExecution (RuntimeDesign)\nopen SemiprimeNativeBitsCounter (nodeWord nodeInt nodeWord_value nodeWord_valid)\n\n/-- Runtime height parameter from actual packet metadata alone. -/\ndef packetBits {n F Q : ℕ} (b R J : ℕ) (arity : Fin F → ℕ)\n    (design : Fin Q → RuntimeDesign n F) : ℕ :=\n  2*(∑ a,SemiprimeWordPacketCounter.nodeWidth b R J arity (design a))+1\n\n/-- Proof-only common denominator, permitting different group counts at each node. -/\ndef commonDenominator {n F Q : ℕ} (den : ℕ) (arity : Fin F → ℕ)\n    (design : Fin Q → RuntimeDesign n F) : ℕ :=\n  ∏ a,(SemiprimeNativeGroupBitsHeight.denominator den (∑ e,arity e) F)^(design a).r\n\n/-- Homogenize a finite family without denominator multiplication at sum steps. -/\ntheorem homogenize {Q : ℕ} (d B W : Fin Q → ℕ) (q : Fin Q → ℚ)\n    (hd : ∀ a,0<d a) (hdW : ∀ a,d a ≤ 2^(W a))\n    (hBW : ∀ a,B a ≤ 2^(W a)) (hq : ∀ a,Representation (q a) (d a) (B a)) :\n    let D := ∏ a,d a\n    0<D ∧ D ≤ 2^(∑ a,W a) ∧\n      ∀ a,Representation (q a) D (2^(2*(∑ a,W a)+1)) := by\n  have hp : 0<∏ a,d a := Finset.prod_pos (fun a _ => hd a)\n  have hb : (∏ a,d a) ≤ 2^(∑ a,W a) := by\n    calc\n      _ ≤ ∏ a,2^(W a) := Finset.prod_le_prod (fun a _ => hdW a)\n      _ = _ := by rw [Finset.prod_pow_eq_pow_sum]\n  refine ⟨hp,hb,?_⟩\n  intro a\n  let c := ∏ x ∈ (Finset.univ.erase a),d x\n  have hc : 0<c := Finset.prod_pos (fun x _ => hd x)\n  have he : d a*c = ∏ x,d x := by\n    simpa only [c] using Finset.mul_prod_erase Finset.univ d (Finset.mem_univ a)\n  have hcD : c ≤ ∏ x,d x := by\n    rw [← he]\n    exact Nat.le_mul_of_pos_left c (hd a)\n  have hBa : B a ≤ 2^(∑ x,W x) := (hBW a).trans\n    (Nat.pow_le_pow_right (by decide) (Finset.single_le_sum (fun x _ => Nat.zero_le (W x)) (Finset.mem_univ a)))\n  have hOne : Representation (1:ℚ) c c := by\n    refine ⟨(c:ℤ),?_,by simp⟩\n    simp only [Int.cast_natCast]\n    exact (div_self (by exact_mod_cast (Nat.ne_of_gt hc))).symm\n  have hh := representation_mul (hq a) hOne\n  rw [mul_one,he] at hh\n  apply representation_mono hh\n  calc\n    B a*c ≤ 2^(∑ x,W x)*2^(∑ x,W x) := Nat.mul_le_mul hBa (hcD.trans hb)\n    _ = 2^(2*(∑ x,W x)) := by rw [← pow_add]; congr 1; omega\n    _ ≤ _ := Nat.pow_le_pow_right (by decide) (by omega)\n\n/-- Every actual original node packet has a single common Hermite denominator.\nOnly original source and Boolean-entry bounds are premises. -/\ntheorem actual_nodes_bound {n F Q : ℕ} (b J R den B : ℕ)\n    (arity : Fin F → ℕ) (design : Fin Q → RuntimeDesign n F)\n    (source : (e : Fin F) → Fin (arity e) → Fin n → Array RationalWord)\n    (entries : (e : Fin F) → (Fin (arity e) → Bool) → EntryWord)\n    (hvalid : ∀ e i v,Valid (source e i v)) (hd : 0<den)\n    (hdb : den ≤ 2^b) (hBb : B ≤ 2^b) (hQb : Q ≤ 2^b)\n    (hJb : J ≤ 2^b) (hnb : n ≤ 2^b)\n    (hsource : ∀ e i v k,k ≤ R → Representation (coefficient (decode (source e i v)) k) den B)\n    (hentries : ∀ e eta,(entries e eta).bits.value.natAbs ≤ 1) :\n    let D := commonDenominator den arity design\n    0<D ∧ D ≤ 2^(packetBits b R J arity design) ∧\n    ∀ a,let out := SemiprimeWordPacketCounter.node b J R (design a) (nodeWord b a).word source entries;\n      Valid out.words ∧ out.words.size=J ∧\n        ArrayBound (decode out.words) J D (2^(packetBits b R J arity design)) := by\n  let s := ∑ e,arity e\n  let DG := SemiprimeNativeGroupBitsHeight.denominator den s F\n  let BG := SemiprimeNativeGroupBitsHeight.numerator n J R den B Q s F\n  let ds := fun a : Fin Q => DG^(design a).r\n  let Bs := fun a : Fin Q => SemiprimeCounterEnumeration.weightedCount n (J-1)*\n    (SemiprimePacketArrayExecution.summaryCount (design a).r (design a).h (design a).m (design a).W*\n      (SemiprimeWordPacketWidth.productBase J DG BG (SemiprimeWordPacketCounter.headCap (design a)))^(2*(design a).r))\n  let Ws := fun a : Fin Q => SemiprimeWordPacketCounter.nodeWidth b R J arity (design a)\n  let out := fun a : Fin Q => SemiprimeWordPacketCounter.node b J R (design a)\n    (nodeWord b a).word source entries\n  have hDG := SemiprimeNativeGroupBitsHeight.denominator_dyadic b R den s F hdb\n  have hBG := SemiprimeNativeGroupBitsHeight.numerator_dyadic b R J den B Q n s F hdb hBb hQb hJb hnb\n  have hpos : ∀ a,0<ds a := fun a => pow_pos\n    (SemiprimeNativeGroupBitsHeight.denominator_pos den s F hd) _\n  have hdW : ∀ a,ds a ≤ 2^(Ws a) := by\n    intro a\n    exact (SemiprimeWordPacketWidth.fibre_denominator_lt b R n F s J (design a).r\n      (SemiprimeWordPacketCounter.headCap (design a))\n      (SemiprimePacketArrayExecution.summaryCount (design a).r (design a).h (design a).m (design a).W)\n      (SemiprimeCounterEnumeration.weightedCount n (J-1)) DG hDG).le\n  have hBW : ∀ a,Bs a ≤ 2^(Ws a) := by\n    intro a\n    have h := SemiprimeWordPacketWidth.support_numerator_lt b R n F s J (design a).r\n      (SemiprimeWordPacketCounter.headCap (design a))\n      (SemiprimePacketArrayExecution.summaryCount (design a).r (design a).h (design a).m (design a).W)\n      (SemiprimeCounterEnumeration.weightedCount n (J-1)) DG BG hDG hBG\n    simpa only [Bs,Ws,SemiprimeWordPacketCounter.nodeWidth,s,Nat.mul_assoc] using h.le\n  have hs (a : Fin Q) := SemiprimeWordPacketCounter.node_spec b J R den B Q (design a) source\n    (nodeWord b a).word (nodeInt a) entries hvalid (nodeWord_valid b Q a)\n    (nodeWord_value b Q a hQb) hd (by change a.val+1 ≤ Q; omega)\n    hdb hBb hQb hJb hnb hsource hentries\n  have hp : 0<∏ a,ds a := Finset.prod_pos (fun a _ => hpos a)\n  have hD : (∏ a,ds a) ≤ 2^(∑ a,Ws a) := by\n    calc\n      _ ≤ ∏ a,2^(Ws a) := Finset.prod_le_prod (fun a _ => hdW a)\n      _ = _ := by rw [Finset.prod_pow_eq_pow_sum]\n  refine ⟨hp,?_,?_⟩\n  · exact hD.trans (Nat.pow_le_pow_right (by decide) (by dsimp only [packetBits,Ws]; omega))\n  · intro a\n    refine ⟨(hs a).2.1,?_,?_⟩\n    · exact SemiprimeMaterializedWordFibreBounds.node_size _ J (design a) _\n    · intro k hk\n      have hh := homogenize ds Bs Ws (fun x => coefficient (decode (out x).words) k)\n        hpos hdW hBW (fun x => (hs x).2.2 k hk)\n      exact hh.2.2 a\n\nend RiemannGaussian.SemiprimeWordPacketHermiteInput\n"};
